/*
 * Soil Moisture Sensor Reader for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - DFRobot Soil Moisture Sensor v2.0 (analog resistive)
 *   - MCP3008 10-bit ADC on SPI0
 *
 * Wiring (BCM numbering):
 *   MCP3008 CS  -> GPIO8  (SPI0 CE0)
 *   MCP3008 DIN -> GPIO10 (SPI0 MOSI)
 *   MCP3008 DOUT-> GPIO9  (SPI0 MISO)
 *   MCP3008 CLK -> GPIO11 (SPI0 SCLK)
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   Sensor AOUT -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -o soil_moisture soil_moisture.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM 8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define SAMPLE_PERIOD  1.0        /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read (single-ended, 10-bit)                                 */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   TX: [0x01] [SGL/DIFF | D2 | D1 | D0 | 0 | 0 | 0 | 0] [0x00]
 *   RX: [xx]   [xx]   [xx | b9 b8 | b7 b6 | b5 b4 | b3 b2 | b1 b0]
 *
 *   SGL/DIFF = 0x00 (single-ended)
 *   D2 D1 D0 = channel number (0-7)
 *   Result: ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01;
    tx[1] = (char)((0x08 | channel) << 4);
    tx[2] = 0x00;

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Sensor Reader started. Press Ctrl+C to exit.\n");
    printf("Sampling MCP3008 CH0 every %.1f s.\n\n", SAMPLE_PERIOD);

    /* --- Main loop --- */
    while (g_running) {
        int moisture = read_mcp3008(ADC_CHANNEL);

        if (moisture < 0) {
            fprintf(stderr, "Error: failed to read moisture level\n");
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("[%s] Moisture Level: %d\n", timestamp, moisture);
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            time_sleep(0.1);
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

