/*
 * Raspberry Pi 4 Model B — MLX91219 Hall-Effect Current Sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX91219 VCC -> 3.3 V (Pin 1)
 *   MLX91219 GND -> GND  (Pin 9)
 *   MLX91219 VOUT -> ADS1115 AIN0 (Pin 4)
 *   ADS1115 VDD -> 3.3 V (Pin 1)
 *   ADS1115 GND -> GND  (Pin 6)
 *   ADS1115 SDA -> GPIO2 (Pin 3, I2C bus 1)
 *   ADS1115 SCL -> GPIO3 (Pin 5, I2C bus 1)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *
 * Build: gcc -O2 -Wall -o mlx91219_adc mlx91219_adc.c -lpigpio -lrt
 * Run:   sudo ./mlx91219_adc
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants ---- */
#define I2C_BUS        1
#define ADS1115_ADDR   0x48

/*
 * ADS1115 register addresses (16-bit big-endian on the bus).
 * The library's ADS1115_READ_REG and ADS1115_WRITE_REG macros expect
 * the 16-bit register value assembled in the order [reg_hi, reg_lo].
 */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (±4.096 V)
 *   Bit  8    MODE     = 1  (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit  4    COMP_MODE= 0
 *   Bit  3    COMP_POL = 0
 *   Bit  2    COMP_LAT = 0
 *   Bit  1    COMP_QUE = 11 (disable comparator)
 *   Bit  0    COMP_MASK= 0
 * => 0x8483
 */
#define ADS1115_CONFIG_WORD 0x8483

/* ---- Application constants ---- */
#define SAMPLE_PERIOD_US  500000   /* 500 ms */
#define ADC_MAX_VALUE     32767.0f /* 16-bit signed, single-ended */
#define ADC_VREF          4.096f    /* PGA ±4.096 V */
#define SENSITIVITY_V_A   0.001f    /* MLX91219: 1 V = 1 A */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice to register 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice from register 0x%02X failed\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and read the raw ADC count. */
static int read_adc_raw(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_WORD;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at ADS1115 address 0x48 ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current sensor via ADS1115 (I2C 0x48, AIN0).\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw;

        if (read_adc_raw(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "Warning: ADC read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw ADC count to current (A). */
        float voltage = (float)raw * ADC_VREF / ADC_MAX_VALUE;
        float current = voltage / SENSITIVITY_V_A;

        printf("Current: %+.4f A (raw=%d, V=%.4f)\n", current, raw, voltage);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

