/*
 * Raspberry Pi 3 Model B+ — KY-026 Flame Sensor + MCP3008 ADC
 *
 * Wiring:
 *   KY-026 D0  -> GPIO4  (BCM 4, SPI0 SCLK)
 *   KY-026 A0  -> MCP3008 CH0
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *
 * Build:  gcc -O2 -Wall -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4          /* BCM 4 — KY-026 D0 (digital) */
#define MCP3008_CS_PIN   8          /* BCM 8 — MCP3008 chip-select (CE0) */
#define SPI_CHANNEL     0           /* pigpio SPI channel 0 maps to CE0 */
#define SPI_SPEED       1000000     /* 1 MHz */
#define SPI_FLAGS       0           /* Mode 0, active-low CS handled by pigpio */
#define MCP3008_CHANNEL 0           /* Single-ended CH0 */
#define SAMPLE_PERIOD_US 1000000    /* 1 second */
#define LOG_FILE        "flame_data.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
