#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define FLAME_THRESHOLD 1
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_DELAY_MS 50
#define POLL_DELAY_MS 100
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_ads1115(void) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS) >> 8;
    config[2] = (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS) & 0xFF;
    if (i2cWriteDevice(i2c_handle, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int raw = gpioRead(FLAME_SENSOR_GPIO);
    if (raw < 0) {
        fprintf(stderr, "Error: Failed to read flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return raw;
}

static int read_temperature(float *temp_out) {
    char reg[1] = {ADS1115_REG_CONVERSION};
    char buf[2];
    int16_t raw;

    if (i2cWriteDevice(i2c_handle, reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }
    raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_out = (float)raw * 4.096 / 1000.0;
    return 0;
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(BUZZER_DURATION_MS * 1000);
    gpioWrite(BUZZER_GPIO, 0);
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_raw = read_flame_sensor();
        if (flame_raw < 0) {
            gpioDelay(POLL_DELAY_MS * 1000);
            continue;
        }

        int flame_state = (flame_raw >= FLAME_THRESHOLD) ? 1 : 0;

        if (flame_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            flame_raw = read_flame_sensor();
            if (flame_raw < 0) {
                gpioDelay(POLL_DELAY_MS * 1000);
                continue;
            }
            if (flame_raw < FLAME_THRESHOLD) {
                flame_state = 0;
            }
        }

        float temperature;
        int temp_ok = (read_temperature(&temperature) == 0);

        if (flame_state && temp_ok) {
            log_event("Fire detected!");
            activate_buzzer();
        } else if (flame_state) {
            log_event("Flame detected!");
        } else if (temp_ok && temperature > TEMP_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
            log_event(msg);
        }

        gpioDelay(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

