    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_raw = read_flame_sensor();
        if (flame_raw < 0) {
            gpioDelay(POLL_DELAY_MS * 1000);
            continue;
        }

        int flame_state = (flame_raw >= FLAME_THRESHOLD) ? 1 : 0;

        if (flame_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            flame_raw = read_flame_sensor();
            if (flame_raw < 0) {
                gpioDelay(POLL_DELAY_MS * 1000);
                continue;
            }
            if (flame_raw < FLAME_THRESHOLD) {
                flame_state = 0;
            }
        }

        float temperature;
        int temp_ok = (read_temperature(&temperature) == 0);

        if (flame_state && temp_ok) {
            log_event("Fire detected!");
            activate_buzzer();
        } else if (flame_state) {
            log_event("Flame detected!");
        } else if (temp_ok && temperature > TEMP_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
            log_event(msg);
        }

        gpioDelay(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

