#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define SPI_DELAY_US    0

#define FAN_GPIO_LINE   18
#define GPIO_CHIP_NAME  "gpiochip4"   /* Pi 5 default; fall back to gpiochip0 */
#define GPIO_CHIP_ALT   "gpiochip0"

#define CURRENT_THRESHOLD 5.0
#define LOG_FILE          "current_log.txt"
#define SAMPLE_INTERVAL   1

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_fan   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        g_chip = gpiod_chip_open_by_name(GPIO_CHIP_ALT);
        if (!g_chip) {
            fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                    GPIO_CHIP_ALT, strerror(errno));
            return -1;
        }
    }

    g_fan = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FAN_GPIO_LINE, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(g_fan, "mlx91219-fan", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_adc(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit + SGL/DIFF=1 + D2 D1 D0 */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    /* Sensor-absent / bus-error heuristics */
    if (adc_value == 0 || adc_value == 0xFF) {
        fprintf(stderr, "ADC value out of range (0x%02X) - sensor absent or bus error\n",
                adc_value);
        return -1;
    }
    return adc_value;
}

/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value)
{
    /* Placeholder linear conversion; replace with MLX91219 datasheet curve. */
    return (float)adc_value * 0.1f;
}

/* ------------------------------------------------------------------ */
static void log_data(float current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, current);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void control_fan(float current)
{
    int val = (current > CURRENT_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(g_fan, val) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d): %s\n", val, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fan) {
        gpiod_line_set_value(g_fan, 0);
        gpiod_line_release(g_fan);
        g_fan = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91219 current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_data(current);
        control_fan(current);

        printf("ADC: %4d  Current: %.2f  Fan: %s\n",
               adc_value, current,
               (current > CURRENT_THRESHOLD) ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

