/*
 * Raspberry Pi 4 Model B - Honeywell/SGX MICS-4514 CO Sensor Logger
 *
 * Reads a simulated 16-bit raw ADC value from the MICS-4514 via I2C bus 1.
 * Converts the raw value to a CO concentration in ppm using a calibrated
 * logarithmic curve. Logs each timestamped ppm value to co_log.txt every 5 seconds.
 *
 * Wiring:
 *   MICS-4514 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MICS-4514 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MICS-4514 VDD -> 3.3V
 *   MICS-4514 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o co_logger co_logger.c -lpigpio -lrt
 * Run:   sudo ./co_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48  /* MICS-4514 I2C address (7-bit) */
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/*
 * Calibration parameters (example values - must be calibrated for your specific sensor).
 * The MICS-4514 outputs a voltage proportional to CO concentration.
 * A 16-bit ADC converts this voltage to a raw digital value.
 * The relationship between raw ADC value and CO concentration is typically logarithmic.
 */
#define ADC_MAX_VALUE 65535.0f  /* 16-bit ADC full-scale */
#define CO_MIN_PPM 0.0f
#define CO_MAX_PPM 100.0f
#define RAW_MIN 1000.0f
#define RAW_MAX 5000.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit raw ADC value from the MICS-4514 sensor.              */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_raw_co_value(uint16_t *raw_value)
{
    char buf[2];
    int bytes_read;

    /*
     * The MICS-4514 typically outputs a 16-bit value.
     * pigpio's i2cReadDevice returns the number of bytes read.
     */
    bytes_read = i2cReadDevice(g_i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (expected 2 bytes, got %d).\n", bytes_read);
        return -1;
    }

    *raw_value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint16_t)(uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC value to CO concentration in ppm.                   */
/* ------------------------------------------------------------------ */
static float raw_to_ppm(uint16_t raw_value)
{
    /*
     * Example calibration curve: logarithmic relationship.
     * Adjust the constants below to match your sensor's datasheet.
     */
    float ratio = (float)raw_value / ADC_MAX_VALUE;
    float ppm = CO_MIN_PPM + (CO_MAX_PPM - CO_MIN_PPM) *
                (1.0f - (float)raw_value / RAW_MAX);

    /* Clamp to valid range */
    if (ppm < CO_MIN_PPM) ppm = CO_MIN_PPM;
    if (ppm > CO_MAX_PPM) ppm = CO_MAX_PPM;

    return ppm;
}

/* ------------------------------------------------------------------ */
/* Log CO concentration with timestamp to file.                         */
/* ------------------------------------------------------------------ */
static void log_co_concentration(float ppm)
{
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[64];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t raw_value;
    float ppm;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at bus %d, addr 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MICS-4514 CO Sensor Logger started. Logging to '%s' every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_raw_co_value(&raw_value) == 0) {
            ppm = raw_to_ppm(raw_value);
            log_co_concentration(ppm);
            printf("Raw: %5u, CO: %6.2f ppm\n", raw_value, ppm);
        } else {
            fprintf(stderr, "Warning: Failed to read CO sensor data. Check wiring and sensor presence.\n");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

