static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error: I2C read failed (expected 4 bytes, got %d)\n", bytes_read);
        return -1;
    }
    *ox = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *red = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float convert_ox_to_co(uint16_t ox_value) {
    return (float)ox_value / 100.0;
}

static int log_co_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening CO log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening alert log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold (%.2f ppm > %.1f ppm)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm, ALERT_THRESHOLD);
    fclose(fp);
    return 0;
}

