    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MICS-4514 monitoring started. Logging to %s and %s every %d seconds.\n",
           CO_LOG_FILE, ALERT_LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        uint16_t ox_value = 0, red_value = 0;

        if (read_sensor_data(i2c_handle, &ox_value, &red_value) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float co_ppm = convert_ox_to_co(ox_value);

        if (log_co_data(co_ppm) != 0) {
            fprintf(stderr, "Error logging CO data.\n");
        }

        if (co_ppm >= ALERT_THRESHOLD) {
            if (log_alert(co_ppm) != 0) {
                fprintf(stderr, "Error logging alert.\n");
            }
        }

        printf("CO: %.2f ppm (OX: %u, RED: %u)\n", co_ppm, ox_value, red_value);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
