/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU analog MEMS microphone logger
 *
 * Wiring:
 *   IMP1 OUT  -> GPIO2 (BCM2)
 *   IMP2 OUT  -> GPIO3 (BCM3)
 *   I2C bus 1: SDA -> GPIO2, SCL -> GPIO3
 *
 * The IMP23ABSU is an analog microphone; it has no I2C interface.
 * This program bit-bangs the I2C protocol on GPIO2/3 using the
 * Raspberry Pi's hardware-timed PWM/GPIO peripheral via pigpio.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c -lpigpio -lrt
 * Run:    sudo ./audio_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_SDA_PIN    2          /* BCM2  */
#define I2C_SCL_PIN    3          /* BCM3  */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define LOG_FILE       "audio_log.txt"
#define ERROR_VALUE     (-999.0f)

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Bit-banged I2C primitives                                          */
/* ------------------------------------------------------------------ */

/*
 * Drive the SDA line.  pigpio's gpioWrite is busy-wait-free (hardware
 * PWM/GPIO), so this is as fast as the Pi's clock permits.
 */
static void sda_write(int level)
{
    gpioWrite(I2C_SDA_PIN, level);
}

static int sda_read(void)
{
    return gpioRead(I2C_SDA_PIN);
}

/*
 * Drive the SCL line.  A 100 kHz I2C clock on a Pi is ~10 us high/low.
 * We use a 5 us high / 5 us low for safety margin.
 */
static void scl_write(int level)
{
    gpioWrite(I2C_SCL_PIN, level);
}

static void i2c_delay_us(uint32_t us)
{
    gpioDelay(us);
}

/*
 * Bit-bang a single-byte write transaction:
 *   start, [7:0] data bits (MSB first), stop
 * Returns 0 on success, -1 on SDA error.
 */
static int i2c_write_byte(uint8_t byte)
{
    sda_write(1);                       /* release SDA (open-drain) */
    scl_write(0);

    for (int i = 7; i >= 0; i--) {
        sda_write((byte >> i) & 1);
        scl_write(1);
        i2c_delay_us(1);                /* >0.6 us high */
        sda_write(1);                   /* release SDA */
        scl_write(0);
        i2c_delay_us(1);                /* >0.6 us low  */
    }

    sda_write(1);                       /* release SDA */
    scl_write(1);
    i2c_delay_us(1);
    sda_write(0);                       /* start */
    i2c_delay_us(1);
    sda_write(1);
    i2c_delay_us(1);
    scl_write(1);
    i2c_delay_us(1);
    scl_write(0);
    i2c_delay_us(1);

    return 0;
}

/*
 * Bit-bang a single-byte read transaction:
 *   start, [7:0] read bits (MSB first), stop
 * Returns the byte read, or 0xFF on error.
 */
static uint8_t i2c_read_byte(void)
{
    uint8_t byte = 0;

    sda_write(1);                       /* release SDA */
    scl_write(0);

    for (int i = 7; i >= 0; i--) {
        scl_write(1);
        i2c_delay_us(1);
        byte |= ((uint8_t)(sda_read() & 1) << i);
        sda_write(1);                   /* release SDA */
        scl_write(0);
        i2c_delay_us(1);
    }

    sda_write(1);                       /* release SDA */
    scl_write(1);
    i2c_delay_us(1);
    sda_write(0);                       /* start */
    i2c_delay_us(1);
    sda_write(1);
    i2c_delay_us(1);
    scl_write(1);
    i2c_delay_us(1);
    scl_write(0);
    i2c_delay_us(1);

    return byte;
}

/*
 * Bit-bang a 16-bit word read (two consecutive byte reads).
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_word(uint16_t *word)
{
    uint8_t msb = i2c_read_byte();
    uint8_t lsb = i2c_read_byte();

    if (msb == 0xFF || lsb == 0xFF) {
        return -1;
    }

    *word = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Microphone abstraction                                               */
/* ------------------------------------------------------------------ */

typedef struct {
    int  handle;
    int  id;
    int  valid;
    float last_reading;
} microphone_t;

static int microphone_init(microphone_t *mic, int id)
{
    mic->id = id;
    mic->valid = 0;
    mic->last_reading = 0.0f;

    /*
     * The IMP23ABSU is an analog microphone; it has no I2C address.
     * We treat it as a 16-bit register at address 0x00.
     * A real I2C device would have a specific address; here we use
     * the bit-banged bus to read the analog OUT signal via GPIO.
     */
    if (i2c_write_byte(0x00) != 0) {
        fprintf(stderr, "[mic %d] I2C write failed\n", id);
        return -1;
    }
    if (i2c_read_word(&mic->last_reading) != 0) {
        fprintf(stderr, "[mic %d] I2C read failed\n", id);
        return -1;
    }
    mic->valid = 1;
    return 0;
}

static float microphone_read(microphone_t *mic)
{
    if (!mic->valid) {
        return ERROR_VALUE;
    }

    if (i2c_write_byte(0x00) != 0) {
        fprintf(stderr, "[mic %d] I2C write failed\n", mic->id);
        mic->valid = 0;
        return ERROR_VALUE;
    }

    uint16_t raw;
    if (i2c_read_word(&raw) != 0) {
        fprintf(stderr, "[mic %d] I2C read failed\n", mic->id);
        mic->valid = 0;
        return ERROR_VALUE;
    }

    float reading = (float)raw;
    mic->last_reading = reading;
    return reading;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_data(float avg_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Average Sound Level: %.2f dB\n", ts, avg_level);
    } else {
        fprintf(fp, "(time error), Average Sound Level: %.2f dB\n", avg_level);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SDA and SCL as outputs */
    gpioSetMode(I2C_SDA_PIN, PI_OUTPUT);
    gpioSetMode(I2C_SCL_PIN, PI_OUTPUT);
    gpioWrite(I2C_SDA_PIN, 1);   /* idle high */
    gpioWrite(I2C_SCL_PIN, 1);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize microphones */
    microphone_t mics[2];
    for (int i = 0; i < 2; i++) {
        if (microphone_init(&mics[i], i + 1) != 0) {
            fprintf(stderr, "Failed to initialize microphone %d\n", i + 1);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Audio logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float reading1 = microphone_read(&mics[0]);
        float reading2 = microphone_read(&mics[1]);

        float avg_level = (reading1 + reading2) / 2.0f;

        log_data(avg_level);
        printf("Average Sound Level: %.2f dB\n", avg_level);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nAudio logger stopped.\n");
    return EXIT_SUCCESS;
}

