/*
 * Raspberry Pi 4 Model B — Dual ADMP401 MEMS Microphone RMS Sampler
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 = GPIO8, CE1 = GPIO9, MISO = GPIO9,
 *     MOSI = GPIO10, SCLK = GPIO11)
 *   - ADMP401 mic1 -> MCP3008 CH0
 *   - ADMP401 mic2 -> MCP3008 CH1
 *   - LED on GPIO27 (BCM)
 *
 * Build:  gcc -O2 -Wall -o audio_sampler audio_sampler.c -lpigpio -lrt
 * Run:    sudo ./audio_sampler
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define LED_PIN          27         /* BCM 27 */

#define MIC1_CH          0          /* MCP3008 channel 0 */
#define MIC2_CH          1          /* MCP3008 channel 1 */

#define WINDOW_MS        100        /* 100 ms sampling window */
#define SAMPLE_MS        1          /* 1 ms per sample */
#define NUM_SAMPLES      (WINDOW_MS / SAMPLE_MS)  /* 100 */

#define RMS_THRESHOLD    0.1        /* RMS threshold (normalized 0..1) */
#define LED_ON_MS        500        /* LED on duration after trigger */

#define LOG_FILE         "audio_events.csv"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  init_spi(void);
static int  read_mcp3008(int channel);
static double calculate_rms(const int *samples, int num_samples);
static void log_event(double mic1_rms, double mic2_rms);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI Init -------------------------------- */
static int init_spi(void)
{
    /*
     * pigpio spiOpen flags bits (32-bit):
     *   bits 0-1 : SPI mode (0)
     *   bit    2 : active-low CE (0 = active-low, 1 = active-high)
     *   bits  3-16: baud rate (1000000 = 1 MHz)
     *   bits 17-23: reserved
     *   bit    24 : auxiliary SPI (0)
     *   bits 25-31: reserved
     */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n",
                g_spi_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- MCP3008 Read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "Error: spiXfer failed (pigpio error %d).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------ RMS Calculation --------------------------- */
static double calculate_rms(const int *samples, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / (double)num_samples);
}

/* ------------------------------- Log Event -------------------------------- */
static void log_event(double mic1_rms, double mic2_rms)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
    } else {
        fflush(g_log_fp);
    }
}

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(LED) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,mic1_rms,mic2_rms\n");
        fflush(g_log_fp);
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
