/*
 * Raspberry Pi 4 Model B — Dual ADMP401 MEMS Microphone RMS Sampler
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 = GPIO8, CE1 = GPIO9, MISO = GPIO9,
 *     MOSI = GPIO10, SCLK = GPIO11)
 *   - ADMP401 mic1 -> MCP3008 CH0
 *   - ADMP401 mic2 -> MCP3008 CH1
 *   - LED on GPIO27 (BCM)
 *
 * Build:  gcc -O2 -Wall -o audio_sampler audio_sampler.c -lpigpio -lrt
 * Run:    sudo ./audio_sampler
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define LED_PIN          27         /* BCM 27 */

#define MIC1_CH          0          /* MCP3008 channel 0 */
#define MIC2_CH          1          /* MCP3008 channel 1 */

#define WINDOW_MS        100        /* 100 ms sampling window */
#define SAMPLE_MS        1          /* 1 ms per sample */
#define NUM_SAMPLES      (WINDOW_MS / SAMPLE_MS)  /* 100 */

#define RMS_THRESHOLD    0.1        /* RMS threshold (normalized 0..1) */
#define LED_ON_MS        500        /* LED on duration after trigger */

#define LOG_FILE         "audio_events.csv"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  init_spi(void);
static int  read_mcp3008(int channel);
static double calculate_rms(const int *samples, int num_samples);
static void log_event(double mic1_rms, double mic2_rms);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI Init -------------------------------- */
static int init_spi(void)
{
    /*
     * pigpio spiOpen flags bits (32-bit):
     *   bits 0-1 : SPI mode (0)
     *   bit    2 : active-low CE (0 = active-low, 1 = active-high)
     *   bits  3-16: baud rate (1000000 = 1 MHz)
     *   bits 17-23: reserved
     *   bit    24 : auxiliary SPI (0)
     *   bits 25-31: reserved
     */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n",
                g_spi_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- MCP3008 Read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "Error: spiXfer failed (pigpio error %d).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------ RMS Calculation --------------------------- */
static double calculate_rms(const int *samples, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / (double)num_samples);
}

/* ------------------------------- Log Event -------------------------------- */
static void log_event(double mic1_rms, double mic2_rms)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
    } else {
        fflush(g_log_fp);
    }
}

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(LED) failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,mic1_rms,mic2_rms\n");
        fflush(g_log_fp);
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];

    while (g_running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_mcp3008(MIC1_CH);
            mic2_samples[i] = read_mcp3008(MIC2_CH);
            if (mic1_samples[i] < 0 || mic2_samples[i] < 0) {
                fprintf(stderr, "Error: ADC read failed at sample %d.\n", i);
                cleanup();
                return EXIT_FAILURE;
            }
            gpioDelay(SAMPLE_MS * 1000); /* microseconds */
        }

        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        log_event(mic1_rms, mic2_rms);

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_MS * 1000);
            gpioWrite(LED_PIN, 0);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi 4 Model B – MLX91204 Hall sensor current monitor
 *
 * Hardware:
 *   - ADS1115 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *     Address 0x48 (ADDR pin tied to GND)
 *   - Melexis MLX91204 analog output wired to ADS1115 AIN0
 *   - Warning LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -li2c -lm
 *
 * Run:
 *   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS_NAME      "/dev/i2c-1"
#define ADS1115_ADDR      0x48

#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CFG   0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (±4.096 V)
 *   Bit  8    MODE     = 1  (continuous conversion)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit  4    COMP_MODE= 0
 *   Bit  3    COMP_POL = 0
 *   Bit  2    COMP_LAT = 0
 *   Bit  1    COMP_QUE = 11 (disable comparator)
 *   Bit  0    COMP_MASK= 0
 *
 *   1100 0001 1000 0011  ->  0xC183
 */
#define ADS1115_CFG_BASE  0xC183

#define LED_GPIO          17
#define CURRENT_THRESHOLD 50.0f   /* Amperes */
#define BUFFER_SIZE       100
#define SAMPLE_PERIOD_US  100000 /* 10 Hz */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ----------------------------- Circular buffer --------------------------- */

typedef struct {
    float  data[BUFFER_SIZE];
    int    head;
    int    count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb->data, 0, sizeof(cb->data));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float value)
{
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->data[i];
    return sum / (float)cb->count;
}

/* ----------------------------- Signal handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(reg=0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- ADS1115 ----------------------------------- */

static int ads1115_init(int fd)
{
    if (i2c_write_reg16(fd, ADS1115_REG_CFG, ADS1115_CFG_BASE) != 0)
        return -1;

    /* Allow the first conversion to complete */
    usleep(10000);
    return 0;
}

/*
 * Read a single-ended sample from AIN0.
 * Returns 0 on success and stores the signed 16-bit raw value in *raw.
 * Returns -1 on I2C error.
 */
static int ads1115_read_ain0(int fd, int16_t *raw)
{
    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &val) != 0)
        return -1;
    *raw = (int16_t)val;
    return 0;
}

/* ----------------------------- Current conversion ------------------------- */

/*
 * Convert the raw ADS1115 code to current (A).
 * PGA = ±4.096 V  ->  1 bit = 125 µV
 * MLX91204 VOUT / R = I
 * Assume R = 1 Ω (adjust for your sensor's gain/R combination).
 */
static float raw_to_current(int16_t raw)
{
    const float pga_vref = 4.096f;
    const float pga_lsb  = pga_vref / 32768.0f;  /* 125 µV */
    return (float)raw * pga_lsb;
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    CircularBuffer current_buffer;
    cb_init(&current_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpio_export(LED_GPIO, 1) < 0) {
        fprintf(stderr, "gpio_export(%d): %s\n", LED_GPIO, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpio_set_mode(%d, PI_OUTPUT): %s\n",
                LED_GPIO, strerror(errno));
        gpio_unexport(LED_GPIO);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpio_write(LED_GPIO, 0) < 0) {
        fprintf(stderr, "gpio_write(%d, 0): %s\n", LED_GPIO, strerror(errno));
        gpio_unexport(LED_GPIO);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Monitoring current (ADS1115 AIN0, 10 Hz, threshold %.1f A)...\n",
           CURRENT_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_fd, &raw) != 0) {
            fprintf(stderr, "I2C read error – continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float current = raw_to_current(raw);
        cb_push(&current_buffer, current);

        float avg = cb_average(&current_buffer);
        bool over = (avg > CURRENT_THRESHOLD);

        if (gpio_write(LED_GPIO, over ? 1 : 0) < 0)
            fprintf(stderr, "gpio_write(%d): %s\n", LED_GPIO, strerror(errno));

        printf("Raw: %6d  Current: %7.2f A  Avg: %7.2f A  LED: %s\n",
               raw, current, avg, over ? "ON" : "OFF");

        usleep(SAMPLE_PERIOD_US);
    }

    /* ----------------------------- Cleanup -------------------------------- */

    printf("\nShutting down...\n");
    gpio_write(LED_GPIO, 0);
    gpio_unexport(LED_GPIO);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    printf("Done.\n");
    return EXIT_SUCCESS;
}

