#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ATIME_DEFAULT 0xFF
#define TCS34725_ENABLE_DEFAULT 0x03
#define TCS34725_ID_VALUE 0x44
#define MAX_I2C_FAILURES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)(TCS34725_COMMAND_BIT | reg), (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char cmd = (char)(TCS34725_COMMAND_BIT | reg);
    if (i2cWriteDevice(handle, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

static int tcs34725_init(int handle) {
    uint8_t id;
    if (i2c_read_reg(handle, TCS34725_ID, &id) != 0) return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }
    if (i2c_write_reg(handle, TCS34725_ATIME, TCS34725_ATIME_DEFAULT) != 0) return -1;
    if (i2c_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_DEFAULT) != 0) return -1;
    return 0;
}

static int tcs34725_read_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t c, r, g, b;
    if (i2c_read_reg(handle, TCS34725_CDATA, &c) != 0) return -1;
    if (i2c_read_reg(handle, TCS34725_RDATA, &r) != 0) return -1;
    if (i2c_read_reg(handle, TCS34725_GDATA, &g) != 0) return -1;
    if (i2c_read_reg(handle, TCS34725_BDATA, &b) != 0) return -1;
    *clear = (uint16_t)((c << 8) | r);
    *red   = (uint16_t)((r << 8) | g);
    *green = (uint16_t)((g << 8) | b);
    *blue  = (uint16_t)((b << 8) | c);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
