        fprintf(stderr, "Failed to open %s: %s\n", dev_path, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        close(fd);
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }

    int failure_count = 0;
    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            failure_count = 0;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
            fflush(log_file);
        } else {
            failure_count++;
            fprintf(stderr, "Sensor read failed (count: %d)\n", failure_count);
            if (failure_count >= MAX_I2C_FAILURES) {
                fprintf(stderr, "Too many I2C failures, exiting.\n");
                break;
            }
        }
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    cleanup();
    return 0;
}

