/*
 * MLX90817 absolute pressure sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX90817 SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   MLX90817 SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   MLX90817 VDD -> 3.3 V
 *   MLX90817 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_log mlx90817_log.c -lpigpio -lrt
 * Run:    sudo ./mlx90817_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MLX90817 constants (datasheet) ---- */
#define MLX90817_I2C_BUS        1
#define MLX90817_I2C_ADDR       0x22    /* SA0 tied to GND */

#define MLX90817_REG_PRESSURE   0x00    /* 24-bit two's-complement, 0.01 hPa */
#define MLX90817_REG_TEMP       0x01    /* 24-bit two's-complement, 0.01 °C */
#define MLX90817_REG_CONFIG     0x02    /* 16-bit config register */

#define MLX90817_CFG_RESET      0x8000  /* write 1 to bit 15 to reset */
#define MLX90817_CFG_POWER_ON   0x0001  /* bit 0: 1 = power on */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (pigpio i2cWriteWordData).  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int mlx_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (pigpio i2cReadWordData).                    */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int mlx_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 24-bit two's-complement register (3 bytes, big-endian).       */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int mlx_read_reg24(int handle, uint8_t reg, int32_t *out)
{
    char buf[3];
    int  bytes = i2cReadI2CBlockData(handle, reg, buf, 3);
    if (bytes != 3) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X) returned %d (expected 3)\n",
                reg, bytes);
        return -1;
    }

    /* MLX90817 returns MSB first, then LSB, then XLSB (datasheet). */
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 16) |
                   ((uint32_t)(uint8_t)buf[1] << 8)  |
                   ((uint32_t)(uint8_t)buf[2]);

    /* Sign-extend 24-bit two's complement to 32-bit. */
    if (raw & 0x00800000)
        raw |= 0xFF000000;

    *out = (int32_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MLX90817: reset, power on, wait for conversion.       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int mlx_init(int handle)
{
    /* Reset the device. */
    if (mlx_write_reg16(handle, MLX90817_REG_CONFIG, MLX90817_CFG_RESET) != 0)
        return -1;
    gpioDelay(2000);  /* 2 ms reset settling time */

    /* Power on. */
    if (mlx_write_reg16(handle, MLX90817_REG_CONFIG, MLX90817_CFG_POWER_ON) != 0)
        return -1;
    gpioDelay(2000);  /* 2 ms power-on settling time */

    /* Allow the first conversion to complete. */
    gpioDelay(5000);  /* 5 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure in kPa.                                              */
/* Returns 0 on success and stores the value in *pressure_kPa; -1 on    */
/* error.                                                               */
/* ------------------------------------------------------------------ */
static int mlx_read_pressure(int handle, float *pressure_kPa)
{
    int32_t raw_hPa;
    if (mlx_read_reg24(handle, MLX90817_REG_PRESSURE, &raw_hPa) != 0)
        return -1;

    /* raw_hPa is in hPa (0.01 hPa resolution). */
    *pressure_kPa = (float)raw_hPa / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line: timestamp, pressure (kPa).                     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_pressure(FILE *fp, float pressure_kPa)
{
    time_t     rawtime;
    struct tm  utc;
    char       ts[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &utc) == NULL) {
        fprintf(stderr, "[ERROR] gmtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &utc) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(MLX90817_I2C_BUS, MLX90817_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                MLX90817_I2C_BUS, MLX90817_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (mlx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] MLX90817 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file once ---- */
    g_log_file = fopen("pressure_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open pressure_log.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty. */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0 || fflush(g_log_file) != 0) {
            fprintf(stderr, "[FATAL] Cannot write CSV header\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

