/*
 * Raspberry Pi 4 Model B – MLX90834 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2 (I2C1 SDA)
 *   ADS1115 SCL -> GPIO3 (I2C1 SCL)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 AIN0 <- MLX90834 SENT out
 *   ADS1115 AIN1 <- NTC thermistor divider
 *   LED anode -> GPIO17 (via 330 Ω resistor) -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90834_ads1115 mlx90834_ads1115.c -lpigpio -lrt
 * Run:    sudo ./mlx90834_ads1115
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_CONV_REG     0x00
#define ADS1115_CONFIG_REG   0x01

/* Config word: single-shot, AIN0/AIN1 single-ended, ±4.096 V, 128 SPS */
#define ADS1115_CONFIG_BASE  0x8483
#define ADS1115_CONFIG_MUX_AIN0 (0x4000)   /* AIN0 single-ended */
#define ADS1115_CONFIG_MUX_AIN1 (0x5000)   /* AIN1 single-ended */
#define ADS1115_CONFIG_OS_BEGIN (0x8000)   /* Assert OS bit to start conv */

#define LED_GPIO             17
#define PRESSURE_THRESHOLD   105.0f          /* kPa */
#define SAMPLE_PERIOD_US     1000000         /* 1 s */
#define MAX_RETRIES          3
#define ADC_RESOLUTION       32767.0f        /* 16-bit signed full-scale */
#define ADC_VREF             4.096f          /* ADS1115 default VREF */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  ads1115_write_config(uint16_t mux);
static int  ads1115_read_conversion(int16_t *raw);
static int  read_pressure(float *pressure_kPa);
static int  read_temperature(float *temp_c);
static void control_led(float pressure_kPa);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers ---------------------------- */
static int ads1115_write_config(uint16_t mux)
{
    uint16_t config = ADS1115_CONFIG_BASE | mux | ADS1115_CONFIG_OS_BEGIN;
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(g_i2c_handle, buf, 3);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write config failed (attempt %d/%d): rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);  /* 10 ms back-off */
    }
    return -1;
}

static int ads1115_read_conversion(int16_t *raw)
{
    char reg = ADS1115_CONV_REG;
    char buf[2];

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 0) {
            fprintf(stderr, "I2C set conv reg failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
            continue;
        }
        if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read conv failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
            continue;
        }
        *raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
        return 0;
    }
    return -1;
}

/* ----------------------------- Sensor reads ------------------------------ */
static int read_pressure(float *pressure_kPa)
{
    int16_t raw;
    if (ads1115_write_config(ADS1115_CONFIG_MUX_AIN0) != 0)
        return -1;

    /* Wait for conversion: 128 SPS -> ~8 ms; use 10 ms for safety */
    gpioDelay(10000);

    if (ads1115_read_conversion(&raw) != 0)
        return -1;

    float voltage = ((float)raw / ADC_RESOLUTION) * ADC_VREF;
    /*
     * MLX90834 SENT output is proportional to pressure.
     * Assuming a linear transfer function: P = m * V + b.
     * Replace m and b with the sensor's calibration constants.
     * For a generic example: m = 100.0 kPa/V, b = 0.0 kPa.
     */
    const float m = 100.0f;
    const float b = 0.0f;
    *pressure_kPa = m * voltage + b;
    return 0;
}

static int read_temperature(float *temp_c)
{
    int16_t raw;
    if (ads1115_write_config(ADS1115_CONFIG_MUX_AIN1) != 0)
        return -1;

    gpioDelay(10000);

    if (ads1115_read_conversion(&raw) != 0)
        return -1;

    float voltage = ((float)raw / ADC_RESOLUTION) * ADC_VREF;
    /*
     * NTC thermistor divider: V_out = V_ref * R_ntc / (R_ntc + R_series).
     * Assuming R_series = 10 kΩ, R_ntc at 25 °C = 10 kΩ, β = 3950.
     * A simplified lookup table or polynomial approximation is needed.
     * For a generic example: T = 100.0 * V.
     */
    *temp_c = 100.0f * voltage;
    return 0;
}

/* ----------------------------- LED control ------------------------------- */
static void control_led(float pressure_kPa)
{
    gpioWrite(LED_GPIO, (pressure_kPa > PRESSURE_THRESHOLD) ? 1 : 0);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("MLX90834 pressure monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure_kPa, temp_c;

        if (read_pressure(&pressure_kPa) != 0) {
            fprintf(stderr, "Pressure read failed after %d retries\n", MAX_RETRIES);
        } else if (read_temperature(&temp_c) != 0) {
            fprintf(stderr, "Temperature read failed after %d retries\n", MAX_RETRIES);
        } else {
            printf("Pressure: %.2f kPa | Temperature: %.2f °C\n",
                   pressure_kPa, temp_c);
            control_led(pressure_kPa);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

