/*
 * Raspberry Pi 4 Model B – MLX90830 Pressure Sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA  -> GPIO2  (BCM 2, I2C bus 1 SDA)
 *   ADS1115 SCL  -> GPIO3  (BCM 3, I2C bus 1 SCL)
 *   ADS1115 ADDR -> GND    (I2C address 0x48)
 *   ADS1115 AIN0 <- MLX90830 analog output
 *   ADS1115 VDD  -> 3.3 V
 *   ADS1115 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o pressure_monitor pressure_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define ADS1115_ADDR    0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit masks */
#define ADS1115_CFG_OS_BEGIN  (1 << 15)
#define ADS1115_CFG_MUX_AIN0 (0x04 << 12)   /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V (0x01 << 9)  /* ±4.096 V */
#define ADS1115_CFG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CFG_DR_128SPS (0x00 << 5)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x03 << 0)   /* Disable comparator */

#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                             */
/* ------------------------------------------------------------------ */
static int ads1115_init(int fd)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096V
                    | ADS1115_CFG_MODE_SINGLE
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Allow the first conversion to complete */
    usleep(10000);
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t cfg = ADS1115_CFG_OS_BEGIN
                  | ADS1115_CFG_MUX_AIN0
                  | ADS1115_CFG_PGA_4_096V
                  | ADS1115_CFG_MODE_SINGLE
                  | ADS1115_CFG_DR_128SPS
                  | ADS1115_CFG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (128 SPS -> ~8 ms; use 10 ms) */
    usleep(10000);

    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Pressure conversion                                                 */
/* ------------------------------------------------------------------ */
/*
 * MLX90830 transfer function (simplified linear approximation):
 *   V_out = V_supply * (P / P_max)
 *   P = (V_out / V_supply) * P_max
 *
 * PGA = ±4.096 V  -> 1 bit = 125 µV
 * P_max = 100 kPa
 * V_supply = 3.3 V
 */
static float raw_to_pressure_kPa(int16_t raw)
{
    const float v_supply = 3.3f;
    const float p_max = 100.0f;
    const float pga_range = 4.096f;
    const float q = 1.0f / 32768.0f;  /* 16-bit signed */

    float v_out = (float)raw * q * pga_range;
    if (v_out < 0.0f) v_out = 0.0f;
    if (v_out > v_supply) v_out = v_supply;

    return (v_out / v_supply) * p_max;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_pressure(float pressure_kPa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f kPa\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor may be absent)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pressure monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) < 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (consecutive: %d)\n",
                    consecutive_errors);

            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive ADC errors. Aborting.\n");
                break;
            }
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        float pressure = raw_to_pressure_kPa(raw);

        if (pressure < 0.0f || pressure > 100.0f) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
        } else {
            if (log_pressure(pressure) < 0) {
                fprintf(stderr, "Logging failed.\n");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

