#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define GPIO_CHIP       "gpiochip4"
#define CE0_OFFSET      8
#define SCLK_OFFSET     11
#define MOSI_OFFSET     10
#define MISO_OFFSET     9

#define ADC_CHANNEL     0
#define ADC_RESOLUTION  12
#define ADC_VREF        3.3f
#define ADC_MAX         4095.0f

#define SAMPLE_PERIOD_US 1000000
#define LOG_FILE        "temperature_log.csv"

#define MIN_TEMP_C      (-40.0f)
#define MAX_TEMP_C      125.0f

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_ce0 = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_ce0 = gpiod_chip_get_line(g_chip, CE0_OFFSET);
    if (!g_ce0) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CE0_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_ce0, "mcp3208-ce0", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
