/*
 * ADXL335 impact logger via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> ADXL335 X
 *   MCP3008 CH1  -> ADXL335 Y
 *   MCP3008 CH2  -> ADXL335 Z
 *
 * Build:  gcc -O2 -Wall -o impact_logger impact_logger.c -lpigpio -lrt
 * Run:    sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)  */
#define SPI_SPEED      1000000    /* 1 MHz             */
#define SPI_FLAGS      0          /* Mode 0, active-low CS */

#define ADC_CHANNEL_X  0
#define ADC_CHANNEL_Y  1
#define ADC_CHANNEL_Z  2

#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define IMPACT_THRESHOLD 1000   /* raw ADC threshold (adjust per calibration) */
#define LOG_FILE_NAME    "impact_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static int  log_data(int x, int y, int z, int impact_detected);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI init -------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- MCP3008 read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", bytes);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];

    /* Sanity-check: 10-bit ADC → 0–1023 */
    if (value < 0 || value > 1023) {
        fprintf(stderr, "Error: ADC value %d out of range on channel %d.\n",
                value, channel);
        return -1;
    }

    *out_value = value;
    return 0;
}

/* ------------------------------ Data logging ----------------------------- */
static int log_data(int x, int y, int z, int impact_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%d,%d,%s\n",
                timestamp, x, y, z,
                impact_detected ? "IMPACT DETECTED" : "NO IMPACT") < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }

    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z,impact\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed.\n");
    }

    printf("ADXL335 impact logger started. Logging to '%s' at %d Hz.\n",
           LOG_FILE_NAME, SAMPLE_RATE_HZ);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int x_val = 0, y_val = 0, z_val = 0;
        int impact_detected = 0;
        int read_error = 0;

        if (read_mcp3008(ADC_CHANNEL_X, &x_val) != 0) {
            fprintf(stderr, "Error: failed to read X axis.\n");
            read_error = 1;
        }
        if (!read_error && read_mcp3008(ADC_CHANNEL_Y, &y_val) != 0) {
            fprintf(stderr, "Error: failed to read Y axis.\n");
            read_error = 1;
        }
        if (!read_error && read_mcp3008(ADC_CHANNEL_Z, &z_val) != 0) {
            fprintf(stderr, "Error: failed to read Z axis.\n");
            read_error = 1;
        }

        if (!read_error) {
            /* Impact detection: any axis exceeding threshold */
            if (x_val > IMPACT_THRESHOLD ||
                y_val > IMPACT_THRESHOLD ||
                z_val > IMPACT_THRESHOLD) {
                impact_detected = 1;
            }
        }

        if (log_data(x_val, y_val, z_val, impact_detected) != 0) {
            fprintf(stderr, "Error: failed to log data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

