        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%d,%d,%s\n",
                timestamp, x, y, z,
                impact_detected ? "IMPACT DETECTED" : "NO IMPACT") < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }

    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z,impact\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed.\n");
    }

    printf("ADXL335 impact logger started. Logging to '%s' at %d Hz.\n",
           LOG_FILE_NAME, SAMPLE_RATE_HZ);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int x_val = 0, y_val = 0, z_val = 0;
        int impact_detected = 0;
        int read_error = 0;

        if (read_mcp3008(ADC_CHANNEL_X, &x_val) != 0) {
            fprintf(stderr, "Error: failed to read X axis.\n");
            read_error = 1;
        }
        if (!read_error && read_mcp3008(ADC_CHANNEL_Y, &y_val) != 0) {
            fprintf(stderr, "Error: failed to read Y axis.\n");
            read_error = 1;
        }
        if (!read_error && read_mcp3008(ADC_CHANNEL_Z, &z_val) != 0) {
            fprintf(stderr, "Error: failed to read Z axis.\n");
            read_error = 1;
        }

        if (!read_error) {
            /* Impact detection: any axis exceeding threshold */
            if (x_val > IMPACT_THRESHOLD ||
                y_val > IMPACT_THRESHOLD ||
                z_val > IMPACT_THRESHOLD) {
                impact_detected = 1;
            }
        }

        if (log_data(x_val, y_val, z_val, impact_detected) != 0) {
            fprintf(stderr, "Error: failed to log data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

