/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1172 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1172 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1172 VDD  -> 3.3 V
 *   Si1172 GND  -> GND
 *
 * The Si1172 requires a proprietary driver library (typically from Silicon
 * Labs) to read its raw PPG data and compute HR/SpO2.  This program uses
 * the open-source pigpio I2C API to communicate with the sensor and logs
 * the raw 16-bit IR and RED ADC values as proxies for HR and SpO2.
 *
 * NOTE: The Si1172 does NOT expose a public SDK; the proprietary driver
 * library performs the necessary timing, LED drive, and ADC conversion.
 * This program reads the raw ADC registers and logs them as HR/SpO2
 * placeholders.  A true HR/SpO2 implementation requires the Si1172
 * driver library and the proprietary conversion algorithm.
 *
 * Build:  gcc -O2 -Wall -o si1172_log si1172_log.c -lpigpio -lrt
 * Run:    sudo ./si1172_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172 I2C address (7-bit) ---- */
#define SI1172_ADDR 0x60

/* ---- Si1172 register addresses (from datasheet) ---- */
#define SI1172_REG_HW_KEY      0x07
#define SI1172_REG_MEAS_RATE   0x08
#define SI1172_REG_IRQ_ENABLE  0x09
#define SI1172_REG_IRQ_STATUS  0x0A
#define SI1172_REG_IRQ_MASK    0x0B
#define SI1172_REG_ALS_IR_DATA0 0x22
#define SI1172_REG_ALS_IR_DATA1 0x23
#define SI1172_REG_ALS_RED_DATA0 0x24
#define SI1172_REG_ALS_RED_DATA1 0x25

/* ---- Error codes ---- */
#define ERR_OK           0
#define ERR_READ_FAIL    1
#define ERR_SENSOR_ABSENT 2

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a Si1172 register (pigpio handles the byte-swap
 * required for the Si1172's big-endian register interface). */
static int si1172_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a Si1172 register. */
static int si1172_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172: write the HW_KEY and configure measurement rate. */
static int si1172_init(int handle)
{
    /* Write HW_KEY to enable the device (required by the Si1172 driver). */
    if (si1172_write_reg(handle, SI1172_REG_HW_KEY, 0x0001) != 0)
        return -1;

    /* Set measurement rate to 1 Hz (1000 ms = 0x03E8). */
    if (si1172_write_reg(handle, SI1172_REG_MEAS_RATE, 0x03E8) != 0)
        return -1;

    /* Clear any pending IRQ and disable IRQ generation. */
    if (si1172_write_reg(handle, SI1172_REG_IRQ_ENABLE, 0x0000) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample: raw IR and RED ADC values. */
static int si1172_read_sample(int handle, uint16_t *ir, uint16_t *red)
{
    if (si1172_read_reg(handle, SI1172_REG_ALS_IR_DATA0, ir) != 0)
        return -1;

    if (si1172_read_reg(handle, SI1172_REG_ALS_RED_DATA0, red) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, uint16_t ir, uint16_t red, int err)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%d\n", (long)now, ir, red, err);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the Si1172 address ---- */
    g_i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize the Si1172 ---- */
    if (si1172_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed (sensor absent or unresponsive)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,HR_raw,SpO2_raw,error\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; Ctrl+C will not clean up\n");
    }

    printf("Si1172 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int err = ERR_OK;

        if (si1172_read_sample(g_i2c_handle, &ir, &red) != 0) {
            fprintf(stderr, "[WARN] Read failed; logging error row\n");
            err = ERR_READ_FAIL;
        }

        log_sample(g_log_file, ir, red, err);

        /* Sleep 1 second (pigpio gpioDelay is microseconds) */
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

