code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define ADC_CHANNEL 0
#define LOG_FILE    "flow_log.csv"
#define SAMPLE_US   1000000
#define MIN_FLOW    0.0f
#define MAX_FLOW    5.0f

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_adc(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float convert_adc_to_flow(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return (float)adc_value / 1023.0f * MAX_FLOW;
}

static int log_flow_rate(FILE *fp, float flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int adc_value = read_adc(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or out of range (ADC=%d)\n", adc_value);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float flow_rate = convert_adc_to_flow(adc_value);
        if (flow_rate < 0.0f) {
            fprintf(stderr, "Flow conversion error; skipping sample\n");
