/*
 * Raspberry Pi Zero W – TDK ICP-10125 I2C environmental sensor reader
 *
 * Wiring:
 *   ICP-10125 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10125 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10125 VDD -> 3.3 V
 *   ICP-10125 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o icp10125 icp10125.c
 * Run:    sudo ./icp10125
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR   0x60          /* 7-bit I2C address */
#define CSV_FILE        "environmental_data.csv"
#define SAMPLE_PERIOD_S 5

/*
 * High-precision measurement command (1-shot, clock stretching disabled).
 * Bits [7:0] = 0x36 -> bit7=0 (high-precision), bit6=0 (no clock stretching),
 *              bits [5:4] = 00 (one-shot mode), bits [3:0] = 0010 (high-precision).
 */
#define CMD_HIGH_PREC   0x36

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* CRC-8 polynomial 0x31, init 0x00, as used by TDK/Sensirion sensors.  */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/*
 * Read one high-precision sample from the ICP-10125.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_icp10125(int fd, float *temperature, float *pressure)
{
    uint8_t cmd = CMD_HIGH_PREC;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "[ERROR] I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* High-precision mode conversion takes ~15 ms; wait 20 ms to be safe. */
    usleep(20000);

    uint8_t buf[6];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    /* Verify CRC over the first 5 data bytes. */
    if (crc8(buf, 5) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on sensor data\n");
        return -2;
    }

    /*
     * Raw 20-bit pressure (buf[0:1] = 16-bit, buf[2] = 4 MSB bits).
     * Raw 20-bit temperature (buf[3:4] = 16-bit, buf[5] = 4 MSB bits).
     */
    uint32_t raw_p = ((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | (buf[2] >> 4);
    uint32_t raw_t = ((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | (buf[5] >> 4);

    /*
     * Per TDK ICP-10125 datasheet (high-precision mode):
     *   P = (raw_p / 1048576.0) * 100000.0  [Pa]
     *   T = (raw_t / 1048576.0) * 200.0    [°C]
     */
    *pressure    = (float)raw_p / 1048576.0f * 100000.0f;
    *temperature = (float)raw_t / 1048576.0f * 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temp, float press)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, press);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ICP10125_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV log ---- */
    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty. */
    if (ftell(g_csv) == 0)
        fprintf(g_csv, "timestamp,temperature_c,pressure_pa\n");

    printf("ICP-10125 reader started. Logging to %s every %d s. Ctrl+C to stop.\n",
           CSV_FILE, SAMPLE_PERIOD_S);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temp = 0.0f, press = 0.0f;
        int rc = read_icp10125(g_i2c_fd, &temp, &press);

        if (rc == 0) {
            log_data(g_csv, temp, press);
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temp, press);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed (rc=%d), retrying in %d s...\n",
                    rc, SAMPLE_PERIOD_S);
            log_data(g_csv, -999.0f, -999.0f);  /* sentinel for error rows */
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

