#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_RATE 1000
#define NUM_SAMPLES 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    if (gain1 < 0 || gain1 > 100 || gain2 < 0 || gain2 > 100) {
        fprintf(stderr, "Error: Gain values must be between 0 and 100.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Audio Sampling and Noise Cancellation\n");
    printf("Gain1: %d, Gain2: %d\n", gain1, gain2);
    printf("Sample Rate: %d Hz, Samples: %d\n", SAMPLE_RATE, NUM_SAMPLES);
    printf("CSV Output: Channel1, Channel2, Cancelled\n");

    for (int i = 0; i < NUM_SAMPLES && running; i++) {
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(1);

        if (sample1 < 0 || sample2 < 0) {
            fprintf(stderr, "Error: Failed to read ADC samples\n");
            break;
        }

        int cancelled = (sample1 * gain1 - sample2 * gain2) / 100;

        printf("%d,%d,%d\n", sample1, sample2, cancelled);
        fflush(stdout);

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nAudio sampling stopped.\n");
    return 0;
}

