/*
 * VH400 soil moisture logger via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> VH400 analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o moisture_logger moisture_logger.c -lpigpio -lrt
 * Run:    sudo ./moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "moisture_log.txt"
#define SAMPLE_PERIOD  60         /* seconds between readings */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read (3-byte transfer)                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (don't-care, clocks out low bits)
     *
     * Response:
     *   rx[0] = don't-care
     *   rx[1] = [null bit][b9 b8] in the low nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* ISO-8601 UTC timestamp helper                                      */
/* ------------------------------------------------------------------ */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

/* ------------------------------------------------------------------ */
/* Append one CSV line to the log file                                  */
/* ------------------------------------------------------------------ */
static int log_data(const char *timestamp, int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, adc_value) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; will retry next cycle.\n");
        } else if (adc_value > ADC_MAX) {
            fprintf(stderr, "ADC value %d out of range; skipping.\n", adc_value);
        } else {
            char timestamp[32];
            get_iso8601_timestamp(timestamp, sizeof(timestamp));
            if (log_data(timestamp, adc_value) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("%s  ADC=%d\n", timestamp, adc_value);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

