    }
    fclose(fp);
    return temp;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage,
                     float ambient_temp, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_fp, "%s,%d,%.3f,%.3f,%.2f,%d\n",
            timestamp, raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);
    fflush(log_fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", BUZZER_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            raw_adc = read_mcp3008(FLAME_SENSOR_CHANNEL);
            if (raw_adc >= 0 && raw_adc <= 1023) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "ADC read out of range (%d). Retrying...\n", raw_adc);
                usleep(100000);
            }
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "ADC read failed after %d retries. Buzzer OFF for safety.\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (raw_adc / 1023.0f) * 3.3f;
        float ambient_temp = read_ambient_temperature();
        float compensated_voltage = voltage * (1.0f + 0.005f * (ambient_temp - 25.0f));
        int flame_detected = (compensated_voltage > 0.5f) ? 1 : 0;

        gpioWrite(BUZZER_GPIO, flame_detected);
        log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
    cleanup();
    return 0;
}

