#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE "water_levels.json"
#define READ_INTERVAL_MS 5000
#define SLEEP_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_water_level(int adc_value) {
    return (double)adc_value / 1023.0 * 100.0;
}

static void control_led(double water_level) {
    static int led_state = 0;

    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_PIN, 1);
        led_state = 1;
        printf("Water level high (%.1f%%). LED ON.\n", water_level);
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_PIN, 0);
        led_state = 0;
        printf("Water level low (%.1f%%). LED OFF.\n", water_level);
    }
}

static void log_water_level(double water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level) < 0) {
        fprintf(stderr, "Error: Failed to write to JSON file\n");
        return;
    }
    fflush(json_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (json_file != NULL) {
        fclose(json_file);
        json_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    json_file = fopen(JSON_FILE, "w");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open JSON file '%s'\n", JSON_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(json_file, "[\n") < 0) {
        fprintf(stderr, "Error: Failed to write JSON array header\n");
        fclose(json_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            double water_level = calculate_water_level(adc_value);
            printf("Water level: %.2f%%\n", water_level);
            control_led(water_level);
            log_water_level(water_level);
        }

        for (int i = 0; i < READ_INTERVAL_MS / SLEEP_INTERVAL_MS && running; i++) {
            gpioDelay(SLEEP_INTERVAL_MS * 1000);
        }
    }

    if (fprintf(json_file, "]\n") < 0) {
        fprintf(stderr, "Error: Failed to write JSON array footer\n");
    }
    fclose(json_file);
    cleanup();

    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

