            if (lpm < 0.0f) {
                fprintf(stderr, "Error: Failed to convert ADC value to LPM\n");
            } else {
                if (log_data(lpm) != 0) {
                    fprintf(stderr, "Error: Failed to log data\n");
                }
            }
        }

