#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_VALUE 500
#define DEFAULT_MAX_VALUE 1000
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtp.cf"
#define DEFAULT_LOG_FILE "plant_data.txt"
#define SPI_SPEED_HZ 500000
#define SPI_BITS_PER_WORD 8
#define ADC_MAX_VALUE 1023

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static char *msmtp_config_path = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(int channel) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", channel);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    int speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx_buf[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

static float calculate_moisture_percentage(int adc_value, int min_value, int max_value) {
    if (max_value == min_value) {
        fprintf(stderr, "Error: min_value and max_value are equal.\n");
        return -1.0f;
    }
    float percentage = 100.0f - ((float)(adc_value - min_value) / (float)(max_value - min_value) * 100.0f);
    if (percentage < 0.0f) percentage = 0.0f;
    if (percentage > 100.0f) percentage = 100.0f;
    return percentage;
}

static void log_data(float moisture_percentage, const char *log_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

static void send_email_alert(float moisture_percentage, float moisture_threshold, const char *recipient_email, const char *msmtp_config_path) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nPlant moisture is below threshold. Current moisture: %.2f%%, Threshold: %.2f%%\" | msmtp -a %s -C %s %s",
             moisture_percentage, moisture_threshold, recipient_email, msmtp_config_path, recipient_email);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        perror("Error executing msmtp");
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "msmtp command failed with status %d\n", status);
    }
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_value = DEFAULT_MIN_VALUE;
    int max_value = DEFAULT_MAX_VALUE;
    float moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_interval = DEFAULT_LOGGING_INTERVAL;
    char *recipient_email = strdup(DEFAULT_RECIPIENT_EMAIL);
    char *msmtp_config_path_local = strdup(DEFAULT_MSMTP_CONFIG);
    char *log_file = strdup(DEFAULT_LOG_FILE);

    if (argc > 1) spi_channel = atoi(argv[1]);
    if (argc > 2) adc_channel = atoi(argv[2]);
    if (argc > 3) min_value = atoi(argv[3]);
    if (argc > 4) max_value = atoi(argv[4]);
    if (argc > 5) moisture_threshold = atof(argv[5]);
    if (argc > 6) logging_interval = atoi(argv[6]);
    if (argc > 7) recipient_email = strdup(argv[7]);
    if (argc > 8) msmtp_config_path_local = strdup(argv[8]);
    if (argc > 9) log_file = strdup(argv[9]);

    if (min_value > max_value) {
        fprintf(stderr, "Error: min_value (%d) must be less than or equal to max_value (%d).\n", min_value, max_value);
        free(recipient_email);
        free(msmtp_config_path_local);
        free(log_file);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting SIGINT handler");
        free(recipient_email);
        free(msmtp_config_path_local);
        free(log_file);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting SIGTERM handler");
        free(recipient_email);
        free(msmtp_config_path_local);
        free(log_file);
        return 1;
    }

    spi_fd = spi_init(spi_channel);
    if (spi_fd < 0) {
        free(recipient_email);
        free(msmtp_config_path_local);
        free(log_file);
        return 1;
    }

    printf("Plant monitoring started. Logging to %s every %d seconds.\n", log_file, logging_interval);

    while (running) {
        int adc_value = read_adc(spi_fd, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value, min_value, max_value);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error calculating moisture percentage. Retrying in %d seconds.\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        log_data(moisture_percentage, log_file);

        if (moisture_percentage < moisture_threshold) {
            send_email_alert(moisture_percentage, moisture_threshold, recipient_email, msmtp_config_path_local);
        }

        sleep(logging_interval);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    free(recipient_email);
    free(msmtp_config_path_local);
    free(log_file);

    printf("Plant monitoring stopped.\n");
    return 0;
}

