 *   MLX90823 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90823_monitor mlx90823_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 spec */
#define SPI_BITS         8
#define SPI_MODE         0

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC */
#define ADC_VREF         3.3f       /* Reference voltage */

#define SAMPLE_INTERVAL  1          /* Seconds between readings */
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* SPI setup                                                            */
/* ------------------------------------------------------------------ */
static int spi_setup(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                          */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int channel, uint16_t *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor voltage and pressure conversion                              */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(uint16_t adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
}

/*
 * Placeholder linear conversion.
 * The MLX90823 outputs a voltage proportional to pressure; the exact
 * scale factor depends on the sensor's supply voltage and internal
 * gain.  This placeholder assumes 0 V -> 0 Pa and 3.3 V -> 100 kPa.
 * Replace with the calibration curve from your specific module.
 */
static float voltage_to_pressure(float voltage)
{
    return (voltage / ADC_VREF) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Timestamped logging                                                  */
/* ------------------------------------------------------------------ */
static void log_reading(float pressure, float voltage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    printf("%s  Pressure: %.2f kPa  (V=%.3f)  %s\n",
           timestamp, pressure, voltage,
           (pressure < 0.0f || pressure > 100.0f) ? "*** OUT OF RANGE ***" : "");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Sensor-absent / fault detection                                      */
/* ------------------------------------------------------------------ */
static bool detect_sensor_fault(uint16_t adc_value)
{
    /*
     * Stuck at 0 V or 3.3 V may indicate a disconnected sensor,
     * short to VCC, or open circuit.
     */
    return (adc_value == 0 || adc_value == ADC_MAX_VALUE);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (spi_setup() != 0) {
        return EXIT_FAILURE;
    }

    printf("MLX90823 Pressure Monitor – MCP3008 on %s\n", SPI_DEVICE);
    printf("Sampling every %d s. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL);

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(ADC_CHANNEL, &adc_value) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: SPI read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Fatal: %d consecutive SPI errors – aborting.\n",
                        consecutive_errors);
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        consecutive_errors = 0;

        if (detect_sensor_fault(adc_value)) {
            fprintf(stderr, "Warning: sensor fault – ADC stuck at %u (%.3f V)\n",
                    adc_value, adc_to_voltage(adc_value));
        } else {
            float voltage = adc_to_voltage(adc_value);
            float pressure = voltage_to_pressure(voltage);
            log_reading(pressure, voltage);
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

