#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x05
#define REG_FIFO_CONFIG 0x06
#define REG_MODE_CONFIG 0x07
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define SPO2_THRESHOLD 95
#define HEART_RATE_THRESHOLD 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        return -1;
    }
    return 0;
}

static int read_spo2(int handle, uint16_t *spo2) {
    uint8_t buffer[2];
    int result = i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)buffer, 2);
    if (result != 2) {
        return -1;
    }
    *spo2 = ((uint16_t)buffer[0] << 8) | buffer[1];
    return 0;
}

static int read_heart_rate(int handle, uint16_t *heart_rate) {
    uint8_t buffer[2];
    int result = i2cReadI2CBlockData(handle, REG_FIFO_DATA + 2, (char *)buffer, 2);
    if (result != 2) {
        return -1;
    }
    *heart_rate = ((uint16_t)buffer[0] << 8) | buffer[1];
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_max30102(int handle) {
    uint8_t part_id;
    if (read_register(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID. Sensor may be absent.\n");
        log_event("Error: Failed to read Part ID. Sensor may be absent.");
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x15).\n", part_id);
        log_event("Error: Unexpected Part ID.");
        return -1;
    }

    if (write_register(handle, REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (write_register(handle, REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (write_register(handle, REG_FIFO_CONFIG, 0x00) != 0) return -1;
    if (write_register(handle, REG_MODE_CONFIG, 0x01) != 0) return -1;
    if (write_register(handle, REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (write_register(handle, REG_LED1_PA, 0x24) != 0) return -1;
    if (write_register(handle, REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        log_event("Error: Failed to open I2C device.");
        gpioTerminate();
        return 1;
    }

    if (initialize_max30102(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing MAX30102 sensor.\n");
        log_event("Error: Failed to initialize MAX30102 sensor.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX30102 sensor initialized. Monitoring SpO2 and heart rate...\n");

    while (running) {
        uint16_t spo2, heart_rate;

        if (read_spo2(i2c_handle, &spo2) != 0) {
            fprintf(stderr, "Error reading SpO2 value.\n");
            log_event("Error: Failed to read SpO2 value.");
        } else if (spo2 < SPO2_THRESHOLD) {
            char message[64];
            snprintf(message, sizeof(message), "SpO2 below threshold: %u%%", spo2);
            printf("%s\n", message);
            log_event(message);
        }

        if (read_heart_rate(i2c_handle, &heart_rate) != 0) {
            fprintf(stderr, "Error reading heart rate value.\n");
            log_event("Error: Failed to read heart rate value.");
        } else if (heart_rate > HEART_RATE_THRESHOLD) {
            char message[64];
            snprintf(message, sizeof(message), "Heart rate above threshold: %u BPM", heart_rate);
            printf("%s\n", message);
            log_event(message);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

