#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define BUZZER_PIN     24         /* BCM GPIO24 */
#define THRESHOLD      500        /* ADC counts */
#define SAMPLE_US      500000     /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, or -1 on error.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: SGL/DIFF=1 (single) | D2 D1 D0 (channel) << 4
     *   Byte 2: 0x00  (don't care, clocks out low bits)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 1..0 undefined, bits 7..2 = 2 MSBs of result
     *   Byte 2: bits 7..0 = 8 LSBs of result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static int set_buzzer(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Buzzer pin as output, off --- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_buzzer(BUZZER_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        printf("ADC value: %d\n", adc_value);

        if (adc_value >= THRESHOLD) {
            if (set_buzzer(BUZZER_PIN, 1) != 0) {
                fprintf(stderr, "Buzzer ON failed\n");
            }
        } else {
            if (set_buzzer(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Buzzer OFF failed\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

