#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define RELAY_GPIO     17
#define DOOR_SENSOR_GPIO 27
#define LOG_FILE       "/var/log/door_events.log"

#define RELAY_PULSE_MS  3000
#define SAMPLE_MS       200
#define CALIB_SAMPLES   10
#define CALIB_MS        50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    /* Config: AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS, no comparator */
    uint16_t cfg = 0xC183; /* 1100 0001 1000 0011 */
    return i2c_write_reg(fd, ADS1115_REG_CONFIG, cfg);
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t val;
    if (i2c_read_reg(fd, ADS1115_REG_CONV, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

static int calibrate_sensor(int fd, int *threshold) {
    double sum = 0.0;
    int samples = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read(fd, &raw) < 0) {
            fprintf(stderr, "Calibration: I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        sum += (double)raw;
        usleep(CALIB_MS * 1000);
    }
    *threshold = (int)(sum / CALIB_SAMPLES);
    printf("Calibration complete. Threshold: %d\n", *threshold);
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADS1115: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(DOOR_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP);

    int threshold = 0;
    if (calibrate_sensor(i2c_fd, &threshold) < 0) {
        cleanup();
        return 1;
    }

    printf("Monitoring distance. Threshold: %d\n", threshold);

    while (running) {
        int16_t raw;
        if (ads1115_read(i2c_fd, &raw) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }
        int distance = (int)raw;
        printf("Distance: %d\n", distance);

        if (distance < threshold) {
            printf("Distance below threshold. Energizing relay.\n");
            gpioWrite(RELAY_GPIO, 1);
            usleep(RELAY_PULSE_MS * 1000);
            gpioWrite(RELAY_GPIO, 0);

            int reed = gpioRead(DOOR_SENSOR_GPIO);
            if (reed == 0) {
                log_event("door opened");
                printf("Door opened.\n");
            } else {
                log_event("door not opened");
                printf("Door not opened.\n");
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

