#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define CS0_LINE        8   /* BCM 8  */
#define CS1_LINE        7   /* BCM 7  */
#define CS2_LINE        25  /* BCM 25 */

#define NUM_SENSORS     3
#define LOG_FILE        "soil_moisture_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer, Mode 0,0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, int channel)
{
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
