        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int value = read_mcp3008(ADC_CHANNEL);
        if (value < 0) {
            fprintf(stderr, "ADC read error, retrying in 100 ms...\n");
            gpioDelay(100000);
            continue;
        }

        if (value > PEAK_THRESHOLD) {
            if (log_peak(value) != 0) {
                fprintf(stderr, "Failed to log peak event\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Sound level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

