#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 device */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    printf("Monitoring PCF8591 AIN0 on %s (addr 0x%02X) every %d ms. Press Ctrl+C to exit.\n",
           I2C_BUS, PCF8591_ADDR, SAMPLE_MS);

    /*
     * The PCF8591 returns the result of the previous conversion on the
     * first read after a write.  Issue a dummy write to select AIN0
     * and then discard the stale byte so the next read is the current
     * conversion.
     */
    uint8_t dummy = 0x00;  /* control byte: AIN0 single-ended, auto-increment off */
    if (write(fd, &dummy, 1) != 1) {
        perror("write(dummy)");
        goto cleanup;
    }

    while (g_running) {
        uint8_t value = 0;

        /* Read the current conversion result */
        ssize_t n = read(fd, &value, 1);
        if (n != 1) {
            if (n < 0)
                perror("read");
            else
                fprintf(stderr, "read returned %zd bytes (unexpected EOF)\n", n);
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)value);
        fflush(stdout);

        /* Sleep for the remainder of the 100 ms cycle */
        usleep((useconds_t)(SAMPLE_MS * 1000));
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (close(fd) != 0)
            perror("close");
    }
    return rc;
}

