code:
/*
 * Raspberry Pi 3 Model B+ — Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor (3.3 V supply, analog output)
 *   - ADS1115 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - SS49E analog output -> ADS1115 AIN0 (single-ended)
 *   - Motor control signal on GPIO27 (BCM)
 *
 * Behavior:
 *   - Samples AIN0 at 1 Hz, converts to magnetic field (Gauss)
 *   - Maintains a rolling average in a circular buffer
 *   - Drives GPIO27 HIGH when the average exceeds 500 Gauss
 *   - Logs all events to syslog
 *   - Graceful shutdown on SIGINT/SIGTERM
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS            "/dev/i2c-1"
#define ADS1115_ADDR       0x48

#define ADS1115_REG_CONV   0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS, no comparator */
#define ADS1115_CONFIG_BASE 0x8483

#define BUFFER_SIZE        10
#define SAMPLE_PERIOD_US   1000000  /* 1 Hz */
#define THRESHOLD_GAUSS    500.0f
#define GPIO_PIN           27
#define VOLTAGE_SUPPLY     3.3f
#define ADC_MAX_COUNT      32767.0f /* 16-bit signed, single-ended positive */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ----------------------------- Circular buffer ---------------------------- */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- ADS1115 helpers ---------------------------- */

static int ads1115_write_config(int fd, uint16_t config)
{
    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (uint8_t)((config >> 8) & 0xFF);
    buf[2] = (uint8_t)(config & 0xFF);

    if (write(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "ADS1115 config write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_conversion(int fd, int16_t *out)
{
    uint8_t reg = ADS1115_REG_CONV;
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "ADS1115 register select failed: %s", strerror(errno));
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 conversion read failed: %s", strerror(errno));
        return -1;
    }

    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ----------------------------- Sensor logic ------------------------------- */

static float read_magnetic_field(int fd)
{
    int16_t raw;
    if (ads1115_read_conversion(fd, &raw) != 0)
        return NAN;

    float voltage = (float)raw * VOLTAGE_SUPPLY / ADC_MAX_COUNT;

    if (voltage < 0.0f || voltage > VOLTAGE_SUPPLY) {
        syslog(LOG_WARNING, "Voltage out of range: %.3f V", voltage);
        return NAN;
    }

    /*
     * Honeywell SS49E transfer function (approximate):
     *   V = Vcc * (1 - exp(-B / B_sat))
     * where B_sat ~ 1000 Gauss (typical).
     * For small B / B_sat, V ~ Vcc * (1 - (1 - B / B_sat)) = Vcc * (B / B_sat).
     * So B ~ (V / Vcc) * B_sat.
     */
    const float B_sat = 1000.0f;
    float field = (voltage / VOLTAGE_SUPPLY) * B_sat;
    return field;
}

/* ----------------------------- GPIO helpers ------------------------------- */

static int gpio_init(void)
{
    int ret = gpiochip4_request_output(GPIO_PIN, "hall_monitor", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO%d: %s", GPIO_PIN, strerror(-ret));
        return -1;
    }
    return 0;
}

static void gpio_set(int value)
{
    if (gpiochip4_set_value(GPIO_PIN, value) < 0)
        syslog(LOG_ERR, "Failed to set GPIO%d: %s", GPIO_PIN, strerror(errno));
}

static void gpio_cleanup(void)
{
    gpiochip4_set_value(GPIO_PIN, 0);
    gpiochip4_release(GPIO_PIN);
}

/* ----------------------------- Signal handling ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave 0x%02X: %s",
               ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (ads1115_write_config(g_i2c_fd, ADS1115_CONFIG_BASE) != 0) {
        syslog(LOG_ERR, "ADS1115 config write failed; aborting");
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed; aborting");
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    CircularBuffer mag_buf;
    cb_init(&mag_buf);
    bool motor_shutdown = false;

    syslog(LOG_INFO, "Hall-effect monitor started (threshold %.1f Gauss, GPIO%d)",
           THRESHOLD_GAUSS, GPIO_PIN);

    while (g_running) {
        float field = read_magnetic_field(g_i2c_fd);

        if (isnan(field)) {
            syslog(LOG_WARNING, "Sensor read error — skipping sample");
        } else {
            cb_add(&mag_buf, field);
            float avg = cb_average(&mag_buf);

            if (!motor_shutdown && avg > THRESHOLD_GAUSS) {
                syslog(LOG_INFO, "Threshold exceeded (%.2f Gauss) — shutting down motor", avg);
                gpio_set(1);
                motor_shutdown = true;
            } else if (motor_shutdown && avg <= THRESHOLD_GAUSS) {
                syslog(LOG_INFO, "Threshold cleared (%.2f Gauss) — resuming motor", avg);
                gpio_set(0);
                motor_shutdown = false;
            }

            syslog(LOG_INFO, "Field: %.2f Gauss, Avg: %.2f Gauss", field, avg);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down — releasing GPIO and closing I2C");
    gpio_cleanup();
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

