/*
 * Soil Moisture Monitor & Watering Controller
 * Board:  Raspberry Pi Zero W
 * ADC:    MCP3008 on SPI0 CE0 (CE0 = GPIO8, CE1 = GPIO7, MISO=GPIO9,
 *         MOSI=GPIO10, SCLK=GPIO11, VDD=3V3, VREF=3V3, DGND/AGND=GND)
 * Sensor: Vegetronix VH400 (analog output) -> MCP3008 CH0
 * Pump:   Relay on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (BCM 8)            */
#define SPI_SPEED        1000000    /* 1 MHz                                 */
#define SPI_FLAGS        0          /* SPI mode 0, active-low CE              */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0        */
#define MOISTURE_THRESHOLD 300     /* 10-bit ADC value (0-1023)              */
#define PUMP_GPIO        18         /* BCM pin for relay/pump control        */
#define PUMP_DURATION_S  10         /* Pump on-time in seconds               */
#define POLL_INTERVAL_S  60         /* Sampling interval in seconds          */
#define LOG_FILE         "watering_events.txt"
#define ADC_MAX          1023       /* 10-bit ADC full-scale code            */
#define ADC_MIN          0
#define ADC_STUCK_LIMIT  100        /* consecutive identical readings to flag */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* --------------------------- Forward Declarations ------------------------ */
static int  read_adc(int channel);
static void control_pump(int on);
static void log_event(int moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- ADC Read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit code in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return value;
}

/* ------------------------------- Pump Control ----------------------------- */
static void control_pump(int on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", PUMP_GPIO);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(int moisture_level)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (g_log) {
        fprintf(g_log, "%s - Moisture: %d, Pump: ON\n", ts, moisture_level);
        fflush(g_log);
    }
    printf("%s - Moisture: %d, Pump: ON\n", ts, moisture_level);
}

/* ------------------------------- Signal Handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    control_pump(0);

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(0);  /* start with pump off */

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started.\n");
    printf("ADC: SPI0 CE0 CH%d | Pump: GPIO%d | Threshold: %d | Poll: %ds\n",
           ADC_CHANNEL, PUMP_GPIO, MOISTURE_THRESHOLD, POLL_INTERVAL_S);

    int stuck_count = 0;
    int last_value  = -1;

    while (g_running) {
        int moisture = read_adc(ADC_CHANNEL);

        if (moisture < 0) {
            fprintf(stderr, "ADC read error; skipping cycle\n");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        /* Detect stuck / invalid sensor readings */
        if (moisture == last_value) {
            stuck_count++;
            if (stuck_count >= ADC_STUCK_LIMIT) {
                fprintf(stderr, "Warning: ADC reading stuck at %d for %d samples\n",
                        moisture, stuck_count);
                stuck_count = 0;  /* reset to avoid flooding */
            }
        } else {
            stuck_count = 0;
            last_value = moisture;
        }

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d < %d). Activating pump.\n",
                   moisture, MOISTURE_THRESHOLD);
            control_pump(1);
            log_event(moisture);

            /* Keep pump on for the configured duration, checking for shutdown */
            for (int i = 0; i < PUMP_DURATION_S && g_running; i++) {
                sleep(1);
            }
            control_pump(0);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

