/*
 * Raspberry Pi 4 Model B – Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - ADS1115 16-bit ADC on I2C bus 1, address 0x48 (ADDR pin tied to GND)
 *   - SS49E analog output wired to ADS1115 AIN0
 *   - LED + 330 Ω resistor on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lpigpio -lrt
 *
 * Run:
 *   ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0 single-ended, PGA 4.096 V, 128 SPS, no comparator */
#define ADS1115_CONFIG_BASE  0x8483
#define ADS1115_CONFIG_OS    0x8000  /* Operational status / single-shot start */

#define LED_GPIO             17
#define BLINK_DURATION_MS    1000
#define BLINK_HALF_PERIOD_US 50000   /* 50 ms on, 50 ms off */
#define SAMPLE_PERIOD_US     100000  /* 100 ms between samples */

#define DEFAULT_THRESHOLD    100.0f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers ---------------------------- */
static int ads1115_read_conversion(int handle, int16_t *raw)
{
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion result.\n");
        return -1;
    }

    *raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int ads1115_start_single_shot(int handle)
{
    uint16_t config = ADS1115_CONFIG_OS | ADS1115_CONFIG_BASE;
    char buf[3];

    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor logic ------------------------------ */
static float raw_to_gauss(int16_t raw)
{
    /* PGA 4.096 V => 1 LSB = 125 µV */
    const float vref = 4.096f;
    const float lsb_v  = vref / 32768.0f;
    const float gauss_per_v = 1.0f;  /* SS49E linear output: ~1.0 G/V */

    float voltage = (float)raw * lsb_v;
    return voltage * gauss_per_v;
}

/* ----------------------------- LED blink ---------------------------------- */
static void blink_led(int gpio, int duration_ms)
{
    for (int i = 0; i < duration_ms / BLINK_HALF_PERIOD_US && g_running; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(BLINK_HALF_PERIOD_US);
        gpioWrite(gpio, 0);
        gpioDelay(BLINK_HALF_PERIOD_US);
    }
}

/* ----------------------------- Main --------------------------------------- */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[i + 1]);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring Hall sensor on ADS1115 (0x%02X). Threshold: %.2f Gauss\n",
           ADS1115_ADDR, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (ads1115_start_single_shot(g_i2c_handle) != 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        gpioDelay(10000);

        int16_t raw;
        if (ads1115_read_conversion(g_i2c_handle, &raw) != 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for %d ms.\n", BLINK_DURATION_MS);
            blink_led(LED_GPIO, BLINK_DURATION_MS);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ----------------------------- Cleanup --------------------------------- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

