#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_controller"
#define SPI_READ_INTERVAL 60
#define SPI_READ_ERROR_THRESHOLD 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_moisture(void) {
    int raw = read_mcp3008(0);
    if (raw < 0) return -1;
    if (raw == 0 || raw == 1023) {
        syslog(LOG_WARNING, "Sensor absent or out of range: raw=%d", raw);
        return -1;
    }
    return (int)(((float)raw / 1023.0f) * 100.0f);
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write pump GPIO %d: %s", PUMP_GPIO, strerror(errno));
        return;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
}

static void pump_control_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty pump control message received");
        return;
    }
    char payload[32];
    int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';
    syslog(LOG_INFO, "Pump control command: %s", payload);
    if (strcmp(payload, "pump_on") == 0) {
        control_pump(1);
    } else if (strcmp(payload, "pump_off") == 0) {
        control_pump(0);
    } else {
        syslog(LOG_ERR, "Invalid pump control command: %s", payload);
    }
}

static void publish_soil_moisture(int moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", moisture);
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, (int)strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish soil moisture: %s", mosquitto_strerror(mosquitto_errno(mosq)));
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_controller", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set pump GPIO mode: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create Mosquitto client");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, pump_control_callback);

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to pump control topic: %s", mosquitto_strerror(mosquitto_errno(mosq)));
        cleanup();
        return 1;
    }

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(mosquitto_errno(mosq)));
        cleanup();
        return 1;
    }
    mosquitto_loop_start(mosq);

    syslog(LOG_INFO, "Soil moisture controller started");

    int error_count = 0;
    while (running) {
        int moisture = read_soil_moisture();
        if (moisture < 0) {
            error_count++;
            if (error_count >= SPI_READ_ERROR_THRESHOLD) {
                syslog(LOG_ERR, "Too many SPI read errors, aborting");
                break;
            }
            sleep(SPI_READ_INTERVAL);
            continue;
        }
        error_count = 0;

        if (moisture < MOISTURE_THRESHOLD_LOW && !pump_state) {
            control_pump(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state) {
            control_pump(0);
        }

        publish_soil_moisture(moisture);
        sleep(SPI_READ_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

