        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc0 = read_mcp3008_channel(0);
        int adc1 = read_mcp3008_channel(1);
        int adc2 = read_mcp3008_channel(2);

        if (adc0 < 0 || adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading ADC values; aborting.\n");
            break;
        }

        float v0 = adc_to_voltage(adc0);
        float v1 = adc_to_voltage(adc1);
        float v2 = adc_to_voltage(adc2);

        if (log_data(v0, v1, v2) != 0) {
            fprintf(stderr, "Error logging data; aborting.\n");
            break;
        }

        printf("Ch0: %.3f V | Ch1: %.3f V | Ch2: %.3f V\n", v0, v1, v2);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

