/*
 * Vibration monitor using a MAX9814 electret microphone amplifier
 * sampled via an MCP3008 ADC on SPI0 CE0 (/dev/spidev0.0).
 *
 * Hardware:
 *   Raspberry Pi 3 Model B+
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 13)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MAX9814 OUT  -> MCP3008 CH0
 *   MAX9814 VDD  -> 3.3 V
 *   MAX9814 GND  -> GND
 *   MAX9814 VCM  -> 1.65 V (mid-supply)
 *   MAX9814 GAIN -> 1 (default)
 *
 * Motors:
 *   Motor 1 control -> GPIO17 (BCM)
 *   Motor 2 control -> GPIO27 (BCM)
 *   Each motor driven through a transistor (e.g. NPN BJT or MOSFET).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vib_monitor vib_monitor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000          /* 1 MHz – well within MCP3008 spec */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0                /* SPI mode 0 (CPOL=0, CPHA=0) */

#define MOTOR_PIN_1       17               /* BCM 17 */
#define MOTOR_PIN_2       27               /* BCM 27 */
#define PWM_FREQUENCY_HZ  100              /* 100 Hz hardware PWM */
#define PWM_RANGE         100              /* 0–100 duty-cycle steps */
#define PWM_DUTY_OFF      0
#define PWM_DUTY_FULL     100

#define NOISE_THRESHOLD   500              /* 10-bit ADC: 0–1023 */
#define SAMPLE_PERIOD_US  10000            /* 10 ms */
#define LOG_FILE          "vibration_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  spi_init(void);
static int  mcp3008_read(int channel);
static void motor_set(int pin, int duty);
static void log_event(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI init -------------------------------- */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = spiOpen(0, speed, mode);   /* bus 0 = CE0 */
    if (g_spi_fd < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(g_spi_fd));
        return -1;
    }

    if (spiSetBitsPerWord(g_spi_fd, bits) < 0) {
        fprintf(stderr, "spiSetBitsPerWord failed: %s\n", pigpio_error(g_spi_fd));
        spiClose(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------ MCP3008 read ------------------------------ */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_fd, tx, rx, 3);
    if (ret < 0) {
        fprintf(stderr, "spiXfer failed: %s\n", pigpio_error(ret));
        return -1;
    }
    if (ret != 3) {
        fprintf(stderr, "spiXfer short transfer: %d bytes\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------ Motor control ----------------------------- */
static void motor_set(int pin, int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > 100) duty = 100;

    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM(%d, %d) failed\n", pin, duty);
    }
}

/* ------------------------------ Logging ---------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_fp) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    motor_set(MOTOR_PIN_1, PWM_DUTY_OFF);
    motor_set(MOTOR_PIN_2, PWM_DUTY_OFF);

    if (g_spi_fd >= 0) {
        spiClose(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------ Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(MOTOR_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motors are off at start */
    motor_set(MOTOR_PIN_1, PWM_DUTY_OFF);
    motor_set(MOTOR_PIN_2, PWM_DUTY_OFF);

    /* Initialize SPI */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Vibration monitor started");

    /* Main sampling loop */
    while (g_running) {
        int noise = mcp3008_read(0);
        if (noise < 0) {
            log_event("ADC read error – skipping cycle");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (noise > NOISE_THRESHOLD) {
            motor_set(MOTOR_PIN_1, PWM_DUTY_FULL);
            motor_set(MOTOR_PIN_2, PWM_DUTY_FULL);
            log_event("Significant vibration detected");
        } else {
            motor_set(MOTOR_PIN_1, PWM_DUTY_OFF);
            motor_set(MOTOR_PIN_2, PWM_DUTY_OFF);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

