}

/* ------------------------------ Logging ---------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_fp) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    motor_set(MOTOR_PIN_1, PWM_DUTY_OFF);
    motor_set(MOTOR_PIN_2, PWM_DUTY_OFF);

    if (g_spi_fd >= 0) {
        spiClose(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------ Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(MOTOR_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motors are off at start */
    motor_set(MOTOR_PIN_1, PWM_DUTY_OFF);
    motor_set(MOTOR_PIN_2, PWM_DUTY_OFF);

    /* Initialize SPI */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Vibration monitor started");

    /* Main sampling loop */
    while (g_running) {
        int noise = mcp3008_read(0);
        if (noise < 0) {
            log_event("ADC read error – skipping cycle");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (noise > NOISE_THRESHOLD) {
            motor_set(MOTOR_PIN_1, PWM_DUTY_FULL);
            motor_set(MOTOR_PIN_2, PWM_DUTY_FULL);
            log_event("Significant vibration detected");
        } else {
            motor_set(MOTOR_PIN_1, PWM_DUTY_OFF);
            motor_set(MOTOR_PIN_2, PWM_DUTY_OFF);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

