code:
/*
 * Soil Moisture Monitor — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - Vegetronix VH400 soil moisture sensor (0–3 V output) -> MCP3008 CH0
 *   - MCP3008 ADC on SPI channel 0 (CE0), SPI clock 1 MHz
 *   - Relay module driving a water pump on BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define PUMP_GPIO        17         /* BCM GPIO 17 — active-high relay */

#define MOISTURE_THRESHOLD 30.0f   /* Percent — turn pump on below this */
#define SAMPLE_INTERVAL_S  60       /* Seconds between readings */
#define MAX_RETRIES       3

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static bool g_pigpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  spi_init(void);
static int  spi_close(void);
static int  read_mcp3008(int channel, uint16_t *out);
static float adc_to_moisture(uint16_t adc);
static void control_pump(float moisture);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI helpers ------------------------------- */

static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n",
                g_spi_handle);
        return -1;
    }
    return 0;
}

static int spi_close(void)
{
    if (g_spi_handle >= 0) {
        int rc = spiClose(g_spi_handle);
        if (rc < 0) {
            fprintf(stderr, "Warning: spiClose failed (pigpio error %d).\n", rc);
            return -1;
        }
        g_spi_handle = -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read.
 *
 * 3-byte transfer (Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", bytes);
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | (uint8_t)rx[2]);
    return 0;
}

/* ----------------------------- Moisture conversion ----------------------- */

/*
 * Vegetronix VH400: 0 V -> dry (0 %), 3 V -> wet (100 %).
 * 10-bit ADC: 0..1023.
 */
static float adc_to_moisture(uint16_t adc)
{
    return ((float)adc / 1023.0f) * 100.0f;
}

/* ----------------------------- Pump control ------------------------------ */

static void control_pump(float moisture)
{
    int level = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(PUMP_GPIO, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed.\n", PUMP_GPIO, level);
    }
    printf("Moisture: %.2f%%  Pump: %s\n", moisture, level ? "ON" : "OFF");
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    if (g_pigpio_inited) {
        gpioWrite(PUMP_GPIO, 0);
    }
    spi_close();
    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed.\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* start with pump off */

    /* --- Initialize SPI --- */
    if (spi_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started.\n");
    printf("SPI ch%d @ %d Hz, pump GPIO %d, threshold %.1f%%.\n",
           SPI_CHANNEL, SPI_SPEED, PUMP_GPIO, MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t adc = 0;
        bool ok = false;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (read_mcp3008(0, &adc) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "Warning: MCP3008 read attempt %d/%d failed.\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (!ok) {
            fprintf(stderr, "Error: MCP3008 read failed after %d attempts.\n",
                    MAX_RETRIES);
            /* Keep pump off on sensor failure */
            gpioWrite(PUMP_GPIO, 0);
            continue;
        }

        float moisture = adc_to_moisture(adc);
        printf("ADC: %4u  Moisture: %6.2f%%\n", adc, moisture);

        control_pump(moisture);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; ++s) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

