#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buffer[3] = {0};

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
}

static int calculate_average(int a, int b, int c) {
    return (a + b + c) / 3;
}

static int set_valve_position(int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid valve position: %d\n", position);
        return -1;
    }
    if (gpioPWM(VALVE_GPIO, position) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static int log_data(int a, int b, int c, int avg, int position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, ADC1: %d, ADC2: %d, ADC3: %d, Average: %d, Valve Position: %d\n",
                timestamp, a, b, c, avg, position) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
