/*
 * Soil Moisture Monitor — Raspberry Pi Zero W
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / GPIO8), 1 MHz, SPI mode 0
 *   - YL-69 soil moisture sensor on MCP3008 channel 0 (CH0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* SPI mode 0, active-low CE */

#define MCP3008_CHANNEL  0          /* CH0 */
#define SAMPLE_INTERVAL  5          /* seconds between samples */
#define MAX_RETRIES      5          /* SPI read retries per sample */
#define LOG_FILE         "soil_data.txt"

/*
 * YL-69 analog output: dry air  -> ~0 V  -> 0
 *                       wet soil   -> ~3.3 V -> 1023
 *
 * A linear mapping is applied; adjust bounds for your specific sensor.
 */
#define ADC_MIN          0
#define ADC_MAX          1023
#define MOISTURE_DRY     0.0f
#define MOISTURE_WET     100.0f

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* --------------------------- MCP3008 read -------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* --------------------------- Moisture conversion -------------------------- */

static float adc_to_moisture(int adc_value)
{
    if (adc_value < ADC_MIN) adc_value = ADC_MIN;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    return MOISTURE_DRY +
           ((float)(adc_value - ADC_MIN) / (float)(ADC_MAX - ADC_MIN)) *
           (MOISTURE_WET - MOISTURE_DRY);
}

/* --------------------------- Logging ------------------------------------- */

static void log_data(float moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log_file)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_level);
    fclose(fp);
}

/* --------------------------- Main ---------------------------------------- */

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = -1;
        int retries = 0;
        int delay_ms = 100;

        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(g_spi_handle, MCP3008_CHANNEL);
            if (adc_value >= 0)
                break;

            fprintf(stderr, "SPI read failed (attempt %d/%d). Retrying in %d ms...\n",
                    retries + 1, MAX_RETRIES, delay_ms);
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            retries++;
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI communication failed after %d retries. Skipping sample.\n",
                    MAX_RETRIES);
            log_data(-1.0f);
        } else {
            float moisture = adc_to_moisture(adc_value);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture);
            log_data(moisture);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --------------------------- Cleanup ---------------------------------- */

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nSoil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

