#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CONFIG_FILE "theremin_config.txt"
#define PWM_PERIOD_NS 10000000
#define PWM_RANGE 100
#define MAX_DISTANCE 400
#define MIN_DISTANCE 20
#define MAX_FREQUENCY 1000
#define MIN_FREQUENCY 200
#define MAX_VOLUME 100
#define MIN_VOLUME 0
#define TIMEOUT_US 30000
#define SAMPLE_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int trig_fd = -1;
static int echo_fd = -1;
static int spi_fd = -1;
static int pwm_fd = -1;
static int pwm_export_done = 0;

typedef struct {
    float distance_min;
    float distance_max;
    float frequency_min;
    float frequency_max;
    float volume_min;
    float volume_max;
} calibration_params_t;

static calibration_params_t params = {
    .distance_min = 20.0f,
    .distance_max = 400.0f,
    .frequency_min = 200.0f,
    .frequency_max = 1000.0f,
    .volume_min = 0.0f,
    .volume_max = 100.0f
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_sysfs(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    int len = (int)strlen(value);
    if (write(fd, value, len) != len) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_sysfs(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    int n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) return -1;
    buf[n] = '\0';
    return 0;
}

static int gpio_export(int pin) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write_sysfs("/sys/class/gpio/export", buf) < 0) {
        perror("gpio export");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", pin);
    return write_sysfs("/sys/class/gpio/unexport", buf);
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    return write_sysfs(path, dir);
}

static int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    return write_sysfs(path, value ? "1" : "0");
}

static int gpio_read(int pin) {
    char path[64];
    char buf[4];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
