#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define LOG_FILE        "alcohol_log.txt"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100
#define SENSOR_MIN_ADC  0
#define SENSOR_MAX_ADC  1023
#define ALCOHOL_THRESHOLD_PPM 50.0f
#define STABILITY_THRESHOLD 3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_ppm(int adc_value)
{
    return (float)adc_value * 100.0f / 1023.0f;
}

static const char *classify_alcohol_level(float ppm)
{
    if (ppm > ALCOHOL_THRESHOLD_PPM)
        return "Alcohol detected! Limit exceeded.";
    else if (ppm < 20.0f)
        return "Sobriety confirmed.";
    else
        return "Alcohol level within acceptable range.";
}

static void log_data(float ppm, const char *status)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting UTC time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(g_log_fp, "%s, %.2f ppm, %s\n", timestamp, ppm, status) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;
    int consecutive_max_adc = 0;
    int consecutive_min_adc = 0;

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_adc(ADC_CHANNEL);
            if (adc_value >= 0)
                break;
            retries++;
            if (retries < MAX_RETRIES)
                usleep(RETRY_DELAY_MS * 1000);
        }

        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error reading ADC after %d retries.\n", MAX_RETRIES);
            if (consecutive_errors >= STABILITY_THRESHOLD) {
                fprintf(stderr, "Sensor absent or SPI bus error. Check wiring.\n");
                consecutive_errors = 0;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        consecutive_errors = 0;

        if (adc_value == SENSOR_MAX_ADC) {
            consecutive_max_adc++;
            if (consecutive_max_adc >= STABILITY_THRESHOLD) {
                fprintf(stderr, "Warning: ADC saturated at 1023 for %d samples. Sensor may be disconnected or faulty.\n", STABILITY_THRESHOLD);
                consecutive_max_adc = 0;
            }
        } else if (adc_value == SENSOR_MIN_ADC) {
            consecutive_min_adc++;
            if (consecutive_min_adc >= STABILITY_THRESHOLD) {
                fprintf(stderr, "Warning: ADC at 0 for %d samples. Sensor may be disconnected or faulty.\n", STABILITY_THRESHOLD);
                consecutive_min_adc = 0;
            }
        } else {
            consecutive_max_adc = 0;
            consecutive_min_adc = 0;
        }

        float ppm = adc_to_ppm(adc_value);
        const char *status = classify_alcohol_level(ppm);

        printf("ADC: %d, %.2f ppm, %s\n", adc_value, ppm, status);
        log_data(ppm, status);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

