#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

#define SPEED_MIN 0
#define SPEED_MAX 100
#define SPEED_INCREMENT 5
#define SPEED_HOLD_TIME 2
#define SPEED_DECELERATION_TIME 1
#define PAUSE_TIME 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buf[3] = {0};

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed for channel %d: %d\n", channel, spi_handle);
        return -1;
    }

    int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    spiClose(spi_handle);

    if (result < 0) {
        fprintf(stderr, "Error: spiXfer failed for channel %d: %d\n", channel, result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

int map_value(int x, int in_min, int in_max, int out_min, int out_max) {
    if (in_max == in_min) return out_min;
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

void set_motor_speed(int motor_number, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;

    int enable_pin = MOTOR1_ENABLE;
    int direction_pin = MOTOR1_DIRECTION;
    if (motor_number == 2) {
        enable_pin = MOTOR2_ENABLE;
        direction_pin = MOTOR2_DIRECTION;
    }

    if (speed > 0) {
        gpioWrite(enable_pin, 1);
        if (speed < 50) {
            gpioWrite(direction_pin, 1);
            gpioPWM(enable_pin, speed * 2);
        } else {
            gpioWrite(direction_pin, 0);
            gpioPWM(enable_pin, (speed - 50) * 2);
        }
    } else {
        gpioWrite(enable_pin, 0);
    }
}

void motor_accelerate(int motor_number, int target_speed) {
    int current_speed = 0;
    while (current_speed < target_speed && program_running) {
        set_motor_speed(motor_number, current_speed);
        current_speed += SPEED_INCREMENT;
        usleep(10000);
    }
}

void motor_decelerate(int motor_number, int target_speed) {
    int current_speed = target_speed;
    while (current_speed > 0 && program_running) {
        set_motor_speed(motor_number, current_speed);
        current_speed -= SPEED_INCREMENT;
        usleep(10000);
    }
    set_motor_speed(motor_number, 0);
}

void motor_hold_speed(int motor_number, int speed) {
    set_motor_speed(motor_number, speed);
    sleep(SPEED_HOLD_TIME);
    set_motor_speed(motor_number, 0);
}

void reverse_motors(int motor1_speed, int motor2_speed) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    usleep(100000);

    set_motor_speed(1, motor1_speed);
    set_motor_speed(2, motor2_speed);
    usleep(100000);

    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    usleep(100000);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);

    while (program_running) {
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Retrying...\n");
            sleep(1);
            continue;
        }

        int speed1 = map_value(pot1_value, 0, 1023, SPEED_MIN, SPEED_MAX);
        int speed2 = map_value(pot2_value, 0, 1023, SPEED_MIN, SPEED_MAX);

        motor_accelerate(1, speed1);
        motor_accelerate(2, speed2);

        motor_hold_speed(1, speed1);
        motor_hold_speed(2, speed2);

        motor_decelerate(1, speed1);
        motor_decelerate(2, speed2);

        sleep(PAUSE_TIME);

        reverse_motors(speed1, speed2);
    }

    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);

    gpioTerminate();
    return 0;
}

