#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define DEBOUNCE_US 10000
#define CALIBRATION_DURATION 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calibrate_ambient_noise(int duration_seconds) {
    long sum = 0;
    int count = 0;
    int sample;

    printf("Calibrating ambient noise for %d seconds...\n", duration_seconds);
    for (int i = 0; i < duration_seconds * 10 && running; i++) {
        sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error reading MCP3008 during calibration.\n");
            return -1;
        }
        sum += sample;
        count++;
        gpioDelay(100000);
    }

    if (!running) {
        return -1;
    }

    if (count == 0) {
        fprintf(stderr, "Calibration failed: no samples collected.\n");
        return -1;
    }

    return (int)(sum / count);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int ambient_noise = calibrate_ambient_noise(CALIBRATION_DURATION);
    if (ambient_noise < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Ambient noise level: %d\n", ambient_noise);

    int last_led_state = 0;
    uint32_t last_trigger_time = 0;

    while (running) {
        int sample = read_mcp3008(MCP3008_CHANNEL);
        if (sample < 0) {
            fprintf(stderr, "Error reading MCP3008.\n");
            break;
        }

        uint32_t now = gpioTick();
        int exceed = (sample > ambient_noise);

        if (exceed && !last_led_state) {
            if ((now - last_trigger_time) >= DEBOUNCE_US) {
                gpioWrite(LED_GPIO, 1);
                last_led_state = 1;
                last_trigger_time = now;
            }
        } else if (!exceed && last_led_state) {
            gpioWrite(LED_GPIO, 0);
            last_led_state = 0;
        }

        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

