#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        0
#define SPI_CS_GPIO     8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static int  g_log_fd   = -1;
static int  g_cs_fd    = -1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

static int gpio_init(void)
{
    g_cs_fd = open("/dev/gpiochip0", O_RDWR);
    if (g_cs_fd < 0) {
        perror("open(/dev/gpiochip0)");
        return -1;
    }

    struct gpio_desc *cs_desc = NULL;
    struct gpio_chip_desc *chip_desc = NULL;
    unsigned int offset = SPI_CS_GPIO;

    if (ioctl(g_cs_fd, GPIO_GET_CHIP_AND_LINE, &chip_desc) < 0) {
        perror("ioctl(GPIO_GET_CHIP_AND_LINE)");
        goto fail;
    }

    cs_desc = chip_desc->first_line;
    while (cs_desc != NULL && cs_desc->offset != offset) {
        cs_desc = cs_desc->next;
    }
    if (cs_desc == NULL) {
        fprintf(stderr, "Failed to find GPIO line %u\n", SPI_CS_GPIO);
        goto fail;
    }

    if (ioctl(g_cs_fd, GPIO_GET_LINE_HANDLE, &cs_desc) < 0) {
        perror("ioctl(GPIO_GET_LINE_HANDLE)");
        goto fail;
    }

    struct gpio_line_request_config req_cfg;
    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer      = "mcp3008-cs";
    req_cfg.request_type  = GPIO_LINE_REQUEST_DIRECTION_OUTPUT;
    req_cfg.flags         = 0;

    if (ioctl(g_cs_fd, GPIO_LINE_REQUEST(cs_desc, &req_cfg, 1)) < 0) {
        perror("ioctl(GPIO_LINE_REQUEST)");
        goto fail;
    }

    return 0;

fail:
    close(g_cs_fd);
    g_cs_fd = -1;
    return -1;
}

static int log_file_init(void)
{
    g_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (g_log_fd < 0) {
        perror("open(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    if (ioctl(g_cs_fd, GPIO_LINE_REQUEST_OUTPUT(1, 0)) < 0) {
        perror("GPIO_LINE_REQUEST_OUTPUT(0)");
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        if (ioctl(g_cs_fd, GPIO_LINE_REQUEST_OUTPUT(1, 1)) < 0) {
            perror("GPIO_LINE_REQUEST_OUTPUT(1)");
        }
        return -1;
    }

    if (ioctl(g_cs_fd, GPIO_LINE_REQUEST_OUTPUT(1, 1)) < 0) {
        perror("GPIO_LINE_REQUEST_OUTPUT(1)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void sleep_until_next_sample(void)
{
    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next);
    next.tv_nsec += SAMPLE_PERIOD_NS;
    if (next.tv_nsec >= 1000000000L) {
        next.tv_sec  += 1;
        next.tv_nsec -= 1000000000L;
    }
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC_RAW, &now);
    if (next.tv_sec > now.tv_sec ||
        (next.tv_sec == now.tv_sec && next.tv_nsec > now.tv_nsec)) {
        struct timespec rem;
        rem.tv_sec  = next.tv_sec  - now.tv_sec;
        rem.tv_nsec = next.tv_nsec - now.tv_nsec;
        nanosleep(&rem, NULL);
    }
}

static void cleanup(void)
{
    if (g_log_fd >= 0) {
        fflush(g_log_fd);
        close(g_log_fd);
        g_log_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_fd >= 0) {
        close(g_cs_fd);
        g_cs_fd = -1;
    }
}

int main(void)
{
    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (log_file_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio sampling started. Press Ctrl+C to stop.\n");

    while (g_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            perror("clock_gettime");
            break;
        }

        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        char line[128];
        int len = snprintf(line, sizeof(line), "%ld|%d\n",
                           (long)ts.tv_sec * 1000000000L + ts.tv_nsec,
                           adc_value);
        if (len < 0 || (size_t)len >= sizeof(line)) {
            fprintf(stderr, "snprintf failed\n");
            break;
        }

        if (write(g_log_fd, line, len) != len) {
            perror("write(log)");
            break;
        }
        if (fflush(g_log_fd) != 0) {
            perror("fflush(log)");
            break;
        }

        sleep_until_next_sample();
    }

    cleanup();
    printf("Audio sampling stopped.\n");
    return EXIT_SUCCESS;
}

