#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0
#define MAX_FIELD_MT 100.0
#define MIN_FIELD_MT -100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Read a single GPIO pin; returns 0 or 1, or -1 on error. */
static int read_gpio(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Warning: gpioRead(%d) failed: %s\n", pin, strerror(errno));
        return -1;
    }
    return v;
}

/* Convert a digital state to a magnetic field strength in millitesla. */
static double state_to_field_mt(int state) {
    double voltage = (state == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    return voltage * 100.0;  /* mT per volt */
}

/* Log three field values to the CSV file. */
static int log_data(double f1, double f2, double f3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", f1, f2, f3) < 0) {
        fprintf(stderr, "Error: fprintf to %s failed: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush(%s) failed: %s\n", LOG_FILE, strerror(errno));
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Magnetic field logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        int s1 = read_gpio(SENSOR1_PIN);
        int s2 = read_gpio(SENSOR2_PIN);
        int s3 = read_gpio(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Warning: incomplete GPIO read, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double f1 = state_to_field_mt(s1);
        double f2 = state_to_field_mt(s2);
        double f3 = state_to_field_mt(s3);

        if (f1 > MAX_FIELD_MT || f1 < MIN_FIELD_MT)
            fprintf(stderr, "Warning: sensor1 field %.2f mT out of range\n", f1);
        if (f2 > MAX_FIELD_MT || f2 < MIN_FIELD_MT)
            fprintf(stderr, "Warning: sensor2 field %.2f mT out of range\n", f2);
        if (f3 > MAX_FIELD_MT || f3 < MIN_FIELD_MT)
            fprintf(stderr, "Warning: sensor3 field %.2f mT out of range\n", f3);

        if (log_data(f1, f2, f3) != 0) {
            fprintf(stderr, "Warning: log_data failed for this sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nMagnetic field logging stopped.\n");
    return EXIT_SUCCESS;
}

