#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define CSV_FILE        "sensor_data.csv"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, or -1 on error.
 */
static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2].
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

