#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60
#define MAX_PAYLOAD_LENGTH 256

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static int mqtt_connection_status = 0;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

static int parse_json_payload(const char *payload, bool *led_state) {
    if (payload == NULL || led_state == NULL) {
        return -1;
    }

    char *endptr;
    long led_state_value = strtol(payload, &endptr, 10);

    if (*endptr != '\0' || (led_state_value != 0 && led_state_value != 1)) {
        return -1;
    }

    *led_state = (led_state_value == 1);
    return 0;
}

static void led_control_callback(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context;
    (void)topicLen;

    if (message == NULL || message->payload == NULL) {
        log_message("Error: NULL payload received.");
        return;
    }

    if (message->payloadlen < 0 || message->payloadlen > MAX_PAYLOAD_LENGTH) {
        log_message("Error: Payload length out of bounds.");
        MQTTClient_freeMessage(&message);
        return;
    }

    bool led_state = false;
    if (parse_json_payload(message->payload, &led_state) != 0) {
        log_message("Error: Invalid JSON payload. Expected {\"led_state\": true/false}.");
    } else {
        if (gpioWrite(GPIO_PIN, led_state ? 1 : 0) != 0) {
            log_message("Error: Failed to write to GPIO pin.");
        } else {
            printf("LED state set to: %s\n", led_state ? "ON" : "OFF");
        }
    }

    MQTTClient_freeMessage(&message);
}

static void connection_lost_callback(void *context, char *cause) {
    (void)context;
    if (cause != NULL) {
        log_message("MQTT connection lost: ");
        log_message(cause);
    } else {
        log_message("MQTT connection lost.");
    }
    mqtt_connection_status = 0;
}

static void connection_established_callback(void *context) {
    (void)context;
    log_message("MQTT connection established.");
    mqtt_connection_status = 1;
}

static int connect_to_mqtt(void) {
    int delay = 1;
    int retries = 0;

    while (running && retries < 10) {
        int rc = MQTTClient_connect(client, NULL, 1000);
        if (rc == MQTTCLIENT_SUCCESS) {
            log_message("MQTT connection successful.");
            MQTTClient_setCallbacks(client, NULL, connection_lost_callback, connection_established_callback, NULL);
            return 0;
        } else {
            char error_message[128];
            snprintf(error_message, sizeof(error_message), "MQTT connection failed with code %d. Retrying in %d seconds.", rc, delay);
            log_message(error_message);
            retries++;
            gpioSleep(PI_TIME_RELATIVE, delay, 0);
            delay *= 2;
            if (delay > MAX_RECONNECT_DELAY) {
                delay = MAX_RECONNECT_DELAY;
            }
        }
    }

    log_message("MQTT connection failed after multiple retries.");
    return -1;
}

static void cleanup(void) {
    if (mqtt_connection_status == 1) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_loop_terminate(client);
        MQTTClient_destroy(&client);
        mqtt_connection_status = 0;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed.");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_message("Failed to set GPIO pin mode.");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_message("Failed to initialize GPIO pin state.");
        gpioTerminate();
        return 1;
    }

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, NULL);

    if (connect_to_mqtt() != 0) {
        log_message("Failed to connect to MQTT broker. Exiting.");
        cleanup();
        return 1;
    }

    if (MQTTClient_subscribe(client, MQTT_TOPIC, 0) != MQTTCLIENT_SUCCESS) {
        log_message("Failed to subscribe to MQTT topic. Exiting.");
        cleanup();
        return 1;
    }

    while (running) {
        MQTTClient_loop(client, 100);
    }

    log_message("Shutting down gracefully.");
    cleanup();
    return 0;
}

