#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define LED_PIN 18
#define POLL_DELAY_US 100000  /* 100 ms */
#define LED_ON_TIME_US 1000000 /* 1 s */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure sound sensor pin as input */
    ret = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", SOUND_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n", LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d low (code %d).\n", LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);
        if (sound_level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", SOUND_SENSOR_PIN, sound_level);
            break;
        }

        printf("Sound level: %d\n", sound_level);

        /* KY-038 DO goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");

            ret = gpioWrite(LED_PIN, 1);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn LED on (code %d).\n", ret);
                break;
            }

            /* Wait for 1 second, checking for shutdown signal */
            for (int i = 0; i < 10 && running; i++) {
                gpioDelay(100000); /* 100 ms */
            }

            ret = gpioWrite(LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to turn LED off (code %d).\n", ret);
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up GPIO resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

