#include <sys/file.h>
#include <linux/gpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/wait.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define CONSUMER "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_event(const char *message) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        return -1;
    }

    if (flock(fd, LOCK_EX) == -1) {
        perror("Error acquiring lock on log file");
        close(fd);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char log_entry[512];
    int len = snprintf(log_entry, sizeof(log_entry), "%s: %s\n", timestamp, message);
    if (len < 0 || len >= (int)sizeof(log_entry)) {
        fprintf(stderr, "Error formatting log entry\n");
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }

    ssize_t written = write(fd, log_entry, len);
    if (written == -1) {
        perror("Error writing to log file");
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }

    if (flock(fd, LOCK_UN) == -1) {
        perror("Error releasing lock on log file");
        close(fd);
        return -1;
    }

    if (close(fd) == -1) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error installing SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error installing SIGTERM handler");
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP_NAME, O_RDONLY);
    if (chip_fd == -1) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpio_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER;
    config.request_type = GPIO_LINE_REQUEST_EVENT_FALLING_EDGE;

    if (ioctl(chip_fd, GPIO_GET_LINE_REQUEST_CONFIG, &config) == -1) {
        perror("Error getting line request config");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    config.offset = GPIO_LINE_OFFSET;
    if (ioctl(chip_fd, GPIO_GET_LINE_VALUE, &config) == -1) {
        perror("Error getting line value");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(chip_fd, GPIO_SET_LINE_REQUEST_CONFIG, &config) == -1) {
        perror("Error setting line request config");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct gpio_line_event event;
        memset(&event, 0, sizeof(event));

        if (ioctl(chip_fd, GPIO_WAIT_EVENT_LINE, &event) == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error waiting for event");
            break;
        }

        if (event.event_type == GPIO_LINE_EVENT_FALLING_EDGE) {
            printf("Vibration detected! Shutting down...\n");

            if (log_event("Vibration detected! Shutting down...") == -1) {
                fprintf(stderr, "Failed to log event.\n");
            }

            if (system("sudo shutdown -h now") == -1) {
                perror("Error executing shutdown command");
            }

            break;
        }
    }

    if (ioctl(chip_fd, GPIO_SET_LINE_REQUEST_CONFIG, NULL) == -1) {
        perror("Error clearing line request config");
    }

    if (close(chip_fd) == -1) {
        perror("Error closing GPIO chip");
    }

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

