/*
 * BMP280 altitude logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3)
 *   BMP280 SCL  -> GPIO3 (pin 5)
 *   BMP280 VDD  -> 3.3 V (NOT 5 V — BMP280 is a 3.3 V logic device)
 *   BMP280 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_altitude bmp280_altitude.c -lpigpio -lrt
 * Run:    sudo ./bmp280_altitude
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- BMP280 constants (BMP280 datasheet) ---- */
#define BMP280_I2C_BUS        1
#define BMP280_I2C_ADDR       0x76

#define BMP280_REG_ID         0xD0
#define BMP280_REG_RESET      0xE0
#define BMP280_REG_STATUS     0xF3
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_CONFIG     0xF5
#define BMP280_REG_PRESS_MSB  0xF7
#define BMP280_REG_TEMP_MSB   0xFA

#define BMP280_CHIP_ID        0x58
#define BMP280_RESET_CMD      0xB6

/* Oversampling: x1 for temp, x1 for pressure (0x27) */
#define BMP280_CTRL_MEAS_VAL  0x27
/* Standby 500 us, IIR filter off (0x04) */
#define BMP280_CONFIG_VAL     0x04

/* Calibration coefficients (read from registers 0x88..0xA1) */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a BMP280 register.                           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a BMP280 register.                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at `reg` (up to 3 bytes).             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_block(int handle, uint8_t reg, uint8_t *buf, int len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%d) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and verify the chip ID.                                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_id(int handle, uint8_t *id)
{
    if (bmp280_read_reg(handle, BMP280_REG_ID, id) != 0)
        return -1;
    if (*id != BMP280_CHIP_ID) {
        fprintf(stderr, "[ERROR] Chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                *id, BMP280_CHIP_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Soft-reset the sensor.                                              */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_reset(int handle)
{
    if (bmp280_write_reg(handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms settle after reset */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibration coefficients (0x88..0xA1).                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_calibration(int handle, bmp280_calib_t *cal)
{
    uint8_t buf[24];
    if (bmp280_read_block(handle, 0x88, buf, sizeof(buf)) != 0)
        return -1;

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t) (buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t) (buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t) (buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t) (buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t) (buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t) (buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t) (buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t) (buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t) (buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t) (buf[22] | (buf[23] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw temperature and pressure (3 bytes each).                   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t buf[6];
    if (bmp280_read_block(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0)
        return -1;

    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

/* ------------------------------------------------------------------ */
/* BME2080-style compensation (datasheet §4.2.3).                      */
/* Returns compensated temperature in 0.01 °C units.                   */
/* ------------------------------------------------------------------ */
static int32_t bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal,
                                      int32_t *t_fine)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) *
            ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) *
              ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) *
            ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;   /* 0.01 °C */
}

/* ------------------------------------------------------------------ */
/* BME2080-style compensation (datasheet §4.2.4).                      */
/* Returns compensated pressure in Pa.                                  */
/* ------------------------------------------------------------------ */
static uint32_t bmp280_compensate_press(int32_t raw_p, int32_t t_fine,
                                        const bmp280_calib_t *cal)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) +
           ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;                       /* avoid div-by-zero */
    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)p;
}

/* ------------------------------------------------------------------ */
/* Compute altitude from pressure (Pa) and sea-level pressure (Pa).    */
/* Returns altitude in metres.                                         */
/* ------------------------------------------------------------------ */
static double bmp280_compute_altitude(uint32_t press_pa, double sea_level)
{
    return 44330.0 * (1.0 - pow((double)press_pa / sea_level, 0.1903));
}

/* ------------------------------------------------------------------ */
/* Append one log line: timestamp, altitude.                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_altitude(FILE *fp, double altitude)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }
    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f\n", ts, altitude) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper.                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(BMP280_I2C_BUS, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                BMP280_I2C_BUS, BMP280_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- verify chip ID ---- */
    uint8_t chip_id = 0;
    if (bmp280_read_id(g_i2c_handle, &chip_id) != 0) {
        fprintf(stderr, "[FATAL] BMP280 not detected at 0x%02X\n", BMP280_I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- soft reset ---- */
    if (bmp280_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] BMP280 reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- read calibration ---- */
    bmp280_calib_t cal;
    if (bmp280_read_calibration(g_i2c_handle, &cal) != 0) {
        fprintf(stderr, "[FATAL] BMP280 calibration read failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- configure: oversampling x1, standby 500 us, IIR off ---- */
    if (bmp280_write_reg(g_i2c_handle, BMP280_REG_CTRL_MEAS, BMP280_CTRL_MEAS_VAL) != 0) {
        fprintf(stderr, "[FATAL] Failed to write CTRL_MEAS\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (bmp280_write_reg(g_i2c_handle, BMP280_REG_CONFIG, BMP280_CONFIG_VAL) != 0) {
        fprintf(stderr, "[FATAL] Failed to write CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen("altitude_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open altitude_log.txt for append\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction() failed; continuing without handler\n");
    }

    printf("BMP280 logging started. Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int32_t raw_t = 0, raw_p = 0;
        int32_t t_fine = 0;

        if (bmp280_read_raw(g_i2c_handle, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "[WARN] Sensor read error; retrying in 5 s\n");
            gpioDelay(5000000);
            continue;
        }

        int32_t temp_centi = bmp280_compensate_temp(raw_t, &cal, &t_fine);
        uint32_t press_pa   = bmp280_compensate_press(raw_p, t_fine, &cal);

        double altitude = bmp280_compute_altitude(press_pa, 101325.0);

        if (log_altitude(g_log_file, altitude) != 0) {
            fprintf(stderr, "[WARN] Logging failed; continuing\n");
        }

        gpioDelay(5000000); /* 5 s */
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

