        close(i2c_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int adc_value = 0;

        if (i2c_read_light(i2c_fd, &lux) != 0) {
            fprintf(stderr, "Error reading light sensor\n");
