#define SPI_FLAGS 0
#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int log_data(int sensor_id, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s Sensor %d: %d\n", timestamp, sensor_id, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int sensor_channels[NUM_SENSORS] = { 0, 1, 2 };

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int moisture = read_mcp3008(sensor_channels[i]);
            if (moisture < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i + 1);
            } else if (moisture < 0 || moisture > 1023) {
                fprintf(stderr, "Warning: Invalid moisture reading %d from sensor %d\n", moisture, i + 1);
            } else {
                if (log_data(i + 1, moisture) != 0) {
                    fprintf(stderr, "Error: Failed to log data for sensor %d\n", i + 1);
                }
            }
        }

        if (!terminate) {
            sleep(SLEEP_INTERVAL);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Goodbye.\n");
    return 0;
}

