#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Light sequencer using four Songle SRD-05VDC-SL relay modules.
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   Relay 1 -> BCM 17
 *   Relay 2 -> BCM 22
 *   Relay 3 -> BCM 23
 *   Relay 4 -> BCM 24
 *
 * Assumes active-high relay modules (HIGH = relay ON, LOW = relay OFF).
 *
 * Build:  gcc -Wall -Wextra -O2 -o light_sequencer light_sequencer.c -lpigpio -lrt
 * Run:    sudo ./light_sequencer
 */

#define RELAY_1_PIN 17
#define RELAY_2_PIN 22
#define RELAY_3_PIN 23
#define RELAY_4_PIN 24

#define NUM_RELAYS 4
#define RELAY_DELAY_US 1000000  /* 1 second in microseconds */

static const int relay_pins[NUM_RELAYS] = {
    RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN
};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler: set flag so main loop exits cleanly.               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Activate a relay (HIGH) and verify the write succeeded.            */
/* ------------------------------------------------------------------ */
static int activate_relay(int pin)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, HIGH) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate a relay (LOW) and verify the write succeeded.           */
/* ------------------------------------------------------------------ */
static int deactivate_relay(int pin)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, LOW) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate all relays and terminate pigpio.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        (void)gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure relay pins as outputs and ensure all relays are OFF --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(pin=%d) failed\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (deactivate_relay(relay_pins[i]) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    /* --- Main loop: sequential activation / deactivation --- */
    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (activate_relay(relay_pins[i]) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay %d (BCM %d) ON\n", i + 1, relay_pins[i]);
            gpioDelay(RELAY_DELAY_US);

            if (deactivate_relay(relay_pins[i]) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay %d (BCM %d) OFF\n", i + 1, relay_pins[i]);
            gpioDelay(RELAY_DELAY_US);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

