/*
 * rain.c — Raspberry Pi 3 Model B+
 *
 * Reads an MCP3008 analog rain sensor on SPI channel 0 (1 MHz, mode 0)
 * and drives an L298N-controlled DC motor to close or open a window
 * based on a threshold.  Every second the rain level is appended to
 * rain_log.txt with a timestamp.
 *
 * Build:  gcc -o rain rain.c -lthe_driver -lrt -lpthread
 * Run:    sudo ./rain
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <the_driver.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          SPI_MODE_0

#define RAIN_THRESHOLD    5
#define MOTOR_RUN_TIME_S  3
#define POLL_INTERVAL_S   1

#define LOG_FILE          "rain_log.txt"

/* L298N / DC motor driver pins (BCM numbering) */
#define MOTOR_IN1         17
#define MOTOR_IN2         18
#define MOTOR_ENA         27

#define PWM_RANGE         255
#define PWM_DUTY          150

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_init(void);
static int  mcp3008_read(uint8_t channel, uint16_t *out);
static void log_rain_level(uint16_t level);
static void motor_forward(void);
static void motor_reverse(void);
static void motor_stop(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- SPI --------------------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * 3-byte transfer: [0x01] [SGL/DIFF | D2 | D1 | D0 | 0 0 0 0] [0x00]
 * Result: ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }
    if (out == NULL) return -1;

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_rain_level(uint16_t level)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    if (fprintf(g_log, "%s, Rain Level: %u\n", ts, level) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
    } else {
        fflush(g_log);
    }
}

/* ----------------------------- Motor ------------------------------------- */
static void motor_forward(void)
{
    the_driver_set_pin_mode(MOTOR_IN1, OUTPUT);
    the_driver_set_pin_mode(MOTOR_IN2, OUTPUT);
    the_driver_set_pin_mode(MOTOR_ENA, OUTPUT);

    the_driver_write_pin(MOTOR_IN1, 1);
    the_driver_write_pin(MOTOR_IN2, 0);
    the_driver_set_pwm(MOTOR_ENA, PWM_DUTY);
}

static void motor_reverse(void)
{
    the_driver_set_pin_mode(MOTOR_IN1, OUTPUT);
    the_driver_set_pin_mode(MOTOR_IN2, OUTPUT);
    the_driver_set_pin_mode(MOTOR_ENA, OUTPUT);

    the_driver_write_pin(MOTOR_IN1, 0);
    the_driver_write_pin(MOTOR_IN2, 1);
    the_driver_set_pwm(MOTOR_ENA, PWM_DUTY);
}

static void motor_stop(void)
{
    the_driver_set_pin_mode(MOTOR_IN1, OUTPUT);
    the_driver_set_pin_mode(MOTOR_IN2, OUTPUT);
    the_driver_set_pin_mode(MOTOR_ENA, OUTPUT);

    the_driver_write_pin(MOTOR_IN1, 0);
    the_driver_write_pin(MOTOR_IN2, 0);
    the_driver_set_pwm(MOTOR_ENA, 0);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    the_driver_cleanup();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize the_driver --- */
    if (the_driver_init() != 0) {
        fprintf(stderr, "the_driver_init() failed\n");
        fclose(g_log); g_log = NULL;
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        the_driver_cleanup();
        fclose(g_log); g_log = NULL;
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t rain_level = 0;
        if (mcp3008_read(0, &rain_level) != 0) {
            fprintf(stderr, "SPI read error; continuing.\n");
        } else {
            log_rain_level(rain_level);

            if (rain_level > RAIN_THRESHOLD) {
                printf("Rain level %u > %d — closing window.\n",
                       rain_level, RAIN_THRESHOLD);
                motor_forward();
            } else {
                printf("Rain level %u <= %d — opening window.\n",
                       rain_level, RAIN_THRESHOLD);
                motor_reverse();
            }

            sleep(MOTOR_RUN_TIME_S);
            motor_stop();
        }

        if (g_running) sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

