#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_PIN 26
#define LED_PIN 16
#define DEBOUNCE_DELAY_MS 50
#define LED_ON_DURATION_MS 500
#define SAMPLE_DELAY_US 1000
#define THRESHOLD 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ADC pin %d as input.\n", ADC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize LED pin %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_adc(void) {
    int adc_value = gpioRead(ADC_PIN);
    if (adc_value < 0) {
        fprintf(stderr, "Error: Failed to read ADC pin %d.\n", ADC_PIN);
        return -1;
    }
    return adc_value;
}

static bool detect_clap(int current_value, int previous_value) {
    return (current_value > THRESHOLD && previous_value <= THRESHOLD);
}

static void trigger_led(void) {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to turn on LED.\n");
        return;
    }
    gpioDelay(LED_ON_DURATION_MS * 1000);
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to turn off LED.\n");
    }
}

static void log_clap_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int previous_value = -1;
    bool clap_detected = false;

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int current_value = read_adc();
        if (current_value < 0) {
            gpioDelay(100000);
            continue;
        }

        if (clap_detected) {
            if (current_value <= THRESHOLD) {
                clap_detected = false;
            }
        } else {
            if (detect_clap(current_value, previous_value)) {
                clap_detected = true;
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
                trigger_led();
                log_clap_event();
            }
        }

        previous_value = current_value;
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

