#include <string.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define RETRY_DELAY_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_gpio_value(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void control_feeder(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance monitoring on GPIO %d...\n", GPIO_PIN);

    while (running) {
        int distance = read_gpio_value(GPIO_PIN);

        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying in %d seconds...\n", RETRY_DELAY_SEC);
            gpioDelay(RETRY_DELAY_SEC * 1000000);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance, retrying in %d seconds...\n", RETRY_DELAY_SEC);
            gpioDelay(RETRY_DELAY_SEC * 1000000);
            continue;
        }

        control_feeder(distance);

        gpioDelay(RETRY_DELAY_SEC * 1000000);
    }

    printf("\nCleaning up and exiting...\n");
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);
    gpioTerminate();

    return EXIT_SUCCESS;
}

