#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define READ_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_moisture(const char *filename, int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime failed");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, value) < 0) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    unsigned int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        if (log_moisture(LOG_FILE, moisture) != 0) {
            fprintf(stderr, "Failed to log moisture data\n");
        }

        sleep(READ_INTERVAL);
    }

    printf("\nCleaning up...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

