#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define ADC_MAX 1023.0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "current_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_current(int adc_value) {
    float voltage = ((float)adc_value / ADC_MAX) * VREF;
    if (voltage < 0.0f || voltage > VREF) {
        fprintf(stderr, "Warning: ADC voltage %.3f V out of range [0, %.1f]\n", voltage, VREF);
        return 0.0f;
    }
    return voltage;
}

static int log_current(FILE *fp, float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int spi_handle = -1;
    FILE *log_file = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        goto cleanup_gpio;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        goto cleanup_spi;
    }

    printf("Starting current monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (log_current(log_file, current) != 0) {
            fprintf(stderr, "Error logging current\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

    if (log_file != NULL) {
        fclose(log_file);
    }
cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

