#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <driver/spi_dev.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static volatile sig_atomic_t program_running = 1;
static int spi_handle = -1;

int spi_setup(spi_config_t config) {
    spi_handle = spi_device_open(&config);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx_buf[3] = {0};

    int ret = spi_device_transfer(spi_handle, (const uint8_t *)tx_buf, (uint8_t *)rx_buf, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
    }
}

void cleanup() {
    if (spi_handle >= 0) {
        spi_device_close(spi_handle);
        spi_handle = -1;
    }
    spi_terminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    spi_config_t spi_config = {
        .driver_num = 0,
        .device_id = SPI_CHANNEL,
        .baud_rate = SPI_BAUD,
