/*
 * security_cam.c — PIR-triggered camera snapshotter for Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o security_cam security_cam.c -lpigpio -lrt
 * Run:    sudo ./security_cam
 *
 * Hardware:
 *   HC-SR501 PIR sensor
 *     VCC -> 5 V  (pin 2 or 4)
 *     GND -> GND  (pin 6)
 *     OUT -> GPIO17 (BCM 17, pin 11)
 *
 *   Raspberry Pi 4 Model B (40-pin header)
 *     GPIO17 = BCM 17 = physical pin 11
 *
 * Dependencies: pigpio (http://abyz.me.uk/rpi/pigpio/)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_PIN          17
#define POLL_INTERVAL_US 50000   /* 50 ms  */
#define DEBOUNCE_DELAY_US 200000  /* 200 ms */
#define CAPTURE_DIR      "/home/pi/security_cam"
#define MAX_FILENAME_LEN  256
#define MAX_PATH_LEN      512

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    }

    char buf[256];
    snprintf(buf, sizeof(buf), "[%s] %s", ts, msg);
    syslog(priority, "%s", buf);
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (errno != ENOENT) {
        perror("stat");
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

/*
 * Fork + exec libcamera-still.
 * Returns 0 on success, -1 on failure.
 */
static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }

    if (pid == 0) {
        /* Child */
        char *const argv[] = {
            "libcamera-still",
            "--nopreview",
            "-o", (char *)filename,
            "--width", "1280",
            "--height", "720",
            "--encoding", "jpg",
            "--timeout", "1000",
            NULL
        };

        execvp("libcamera-still", argv);
        /* If execvp returns, it failed */
        perror("execvp(libcamera-still)");
        _exit(127);
    }

    /* Parent */
    int status = 0;
    pid_t w;
    do {
        w = waitpid(pid, &status, 0);
    } while (w < 0 && errno == EINTR);

    if (w < 0) {
        perror("waitpid");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    if (WIFEXITED(status)) {
        fprintf(stderr, "libcamera-still exited with status %d\n",
                WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "libcamera-still killed by signal %d\n",
                WTERMSIG(status));
    }
    return -1;
}

/*
 * Build a filename: <capture_dir>/<YYYY-MM-DDTHH-MM-SS-motion_value>.jpg
 * Returns 0 on success, -1 on failure.
 */
static int build_filename(const char *capture_dir, int motion_value,
                          char *out, size_t out_len)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H-%M-%S", t);

    int n = snprintf(out, out_len, "%s/%s-motion_%d.jpg",
                     capture_dir, ts, motion_value);
    if (n < 0 || (size_t)n >= out_len) {
        fprintf(stderr, "Filename buffer too small\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        log_event(LOG_ERR, "Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return EXIT_FAILURE;
    }
    log_event(LOG_INFO, "pigpio initialised successfully");

    if (ensure_directory(CAPTURE_DIR) != 0) {
        log_event(LOG_ERR, "Cannot access or create capture directory");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_event(LOG_INFO, "Capture directory ready");

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set PIR pin mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        log_event(LOG_ERR, "Failed to set PIR pull-down");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "PIR sensor monitoring started on GPIO17");

    int last_state = gpioRead(PIR_PIN);
    if (last_state < 0) {
        log_event(LOG_ERR, "Initial gpioRead failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int motion = gpioRead(PIR_PIN);
        if (motion < 0) {
            log_event(LOG_ERR, "gpioRead failed on PIR pin");
            ret = EXIT_FAILURE;
            break;
        }

        if (motion != last_state) {
            /* Debounce: wait, then re-read to confirm */
            gpioDelay(DEBOUNCE_DELAY_US);

            int confirm = gpioRead(PIR_PIN);
            if (confirm < 0) {
                log_event(LOG_ERR, "gpioRead failed during debounce");
                ret = EXIT_FAILURE;
                break;
            }

            if (confirm == motion) {
                last_state = motion;

                char filename[MAX_FILENAME_LEN];
                if (build_filename(CAPTURE_DIR, motion,
                                   filename, sizeof(filename)) != 0) {
                    log_event(LOG_ERR, "Failed to build filename");
                    continue;
                }

                log_event(LOG_INFO, "Motion detected (value =", motion, ")");

                if (capture_image(filename) == 0) {
                    log_event(LOG_INFO, "Image captured: ", filename);
                } else {
                    log_event(LOG_ERR, "Image capture failed: ", filename);
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down");
    gpioTerminate();
    log_event(LOG_INFO, "pigpio terminated");

    return ret;
}

