static int capture_frame(int fd, char **frame_buffer, size_t *frame_size) {
    struct timeval timeout = { 1, 0 };
    fd_set fds;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    ret = select(fd + 1, &fds, NULL, NULL, &timeout);
    if (ret < 0) {
        if (errno == EINTR) return -1;
        perror("select() failed");
        return -1;
    }
    if (ret == 0) {
        fprintf(stderr, "select() timed out\n");
        return -1;
    }

    struct {
        unsigned int width;
        unsigned int height;
        unsigned int depth;
        unsigned int bytes_per_line;
        unsigned int size;
        unsigned int fps;
        unsigned int padding;
    } header;

    ssize_t bytes_read = read(fd, &header, sizeof(header));
    if (bytes_read < 0) {
        perror("read() failed");
        return -1;
    }
    if (bytes_read != sizeof(header)) {
        fprintf(stderr, "Incomplete MJPEG header: %zd bytes\n", bytes_read);
        return -1;
    }

    if (header.size > MAX_FRAME_SIZE) {
        fprintf(stderr, "Frame size %u exceeds maximum %zu\n", header.size, MAX_FRAME_SIZE);
        return -1;
    }

    *frame_buffer = mmap(NULL, header.size, PROT_READ, MAP_SHARED, fd, 0);
    if (*frame_buffer == MAP_FAILED) {
        perror("mmap() failed");
        return -1;
    }

    *frame_size = header.size;
