    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime() failed");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec) < 0) {
        perror("fprintf() failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose() failed");
        return -1;
    }

    return 0;
}

