    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            goto cleanup;
        }
        buffer_sizes[i] = buf.length;
        buffers_mapped++;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (stop_flag) {
        fprintf(stderr, "Interrupted before frame capture\n");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "No data available in buffer\n");
        goto cleanup;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("fopen(" IMAGE_FILE ")");
        goto cleanup;
    }

    size_t written = fwrite(buffers[buf.index], 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        perror("fwrite");
        goto cleanup;
    }

    if (fflush(fp) == EOF) {
        perror("fflush");
        goto cleanup;
    }

    printf("MJPEG frame written to %s (%zu bytes)\n", IMAGE_FILE, written);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
    }

    for (int i = 0; i < buffers_mapped; i++) {
        if (buffers[i] != NULL && buffers[i] != MAP_FAILED) {
            if (munmap(buffers[i], buffer_sizes[i]) == -1) {
                perror("munmap");
            }
        }
    }

    if (fp != NULL) {
        if (fclose(fp) == EOF) {
            perror("fclose");
        }
    }

    if (fd != -1) {
        close(fd);
    }

    return ret;
}

