#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

#define PWM_FREQUENCY 50
#define PWM_RANGE 1000
#define MIN_DUTY_CYCLE 50
#define MAX_DUTY_CYCLE 100
#define MID_POSITION 75
#define STEP_SIZE 5
#define MIN_POSITION 25
#define MAX_POSITION 125
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_position(int pin, int position) {
    if (position < MIN_POSITION || position > MAX_POSITION) {
        fprintf(stderr, "Error: Servo position out of range (%d) on pin %d\n", position, pin);
        return -1;
    }
    int duty = MIN_DUTY_CYCLE + (position - MIN_POSITION) * (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE) / (MAX_POSITION - MIN_POSITION);
    if (gpioServo(pin, duty) != 0) {
        fprintf(stderr, "Error: Failed to set servo on pin %d to duty %d\n", pin, duty);
        return -1;
    }
    return 0;
}

static int adjust_servo(int pin, int *position, int step) {
    *position += step;
    if (*position < MIN_POSITION) {
        *position = MIN_POSITION;
    } else if (*position > MAX_POSITION) {
        *position = MAX_POSITION;
    }
    return set_servo_position(pin, *position);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pan servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set tilt servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set tilt up button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set tilt down button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pan left button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pan right button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on tilt up button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on tilt down button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on pan left button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on pan right button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for pan servo\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for tilt servo\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range for pan servo\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range for tilt servo\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_position = MID_POSITION;
    int tilt_position = MID_POSITION;

    if (set_servo_position(PAN_SERVO_PIN, pan_position) != 0) {
        fprintf(stderr, "Error: Failed to initialize pan servo position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_servo_position(TILT_SERVO_PIN, tilt_position) != 0) {
        fprintf(stderr, "Error: Failed to initialize tilt servo position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Mount Control\n");
    printf("Pan: BCM%d | Tilt: BCM%d | Up: BCM%d | Down: BCM%d | Left: BCM%d | Right: BCM%d\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN, TILT_UP_BUTTON_PIN, TILT_DOWN_BUTTON_PIN,
           PAN_LEFT_BUTTON_PIN, PAN_RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(TILT_UP_BUTTON_PIN) == 0) {
            if (adjust_servo(TILT_SERVO_PIN, &tilt_position, STEP_SIZE) != 0) {
                fprintf(stderr, "Error: Failed to adjust tilt position\n");
            }
        }
        if (gpioRead(TILT_DOWN_BUTTON_PIN) == 0) {
            if (adjust_servo(TILT_SERVO_PIN, &tilt_position, -STEP_SIZE) != 0) {
                fprintf(stderr, "Error: Failed to adjust tilt position\n");
            }
        }
        if (gpioRead(PAN_LEFT_BUTTON_PIN) == 0) {
            if (adjust_servo(PAN_SERVO_PIN, &pan_position, -STEP_SIZE) != 0) {
                fprintf(stderr, "Error: Failed to adjust pan position\n");
            }
        }
        if (gpioRead(PAN_RIGHT_BUTTON_PIN) == 0) {
            if (adjust_servo(PAN_SERVO_PIN, &pan_position, STEP_SIZE) != 0) {
                fprintf(stderr, "Error: Failed to adjust pan position\n");
            }
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nCleaning up...\n");
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

