#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define NUM_BUFFERS 4
#define BLUR_RADIUS 3
#define JPEG_QUALITY 75

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int yuyv_to_rgb(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height; i++) {
        int y = yuyv[i * 2];
        int u = yuyv[i * 2 + 1];
        int v = yuyv[i * 2 + 2];
        int cb = u - 128;
        int cr = v - 128;
        int r = (y + (cr * 4546) / 10000 + 16) >> 6;
        int g = (y - (cb * 3596) / 10000 - (cr * 1441) / 10000 + 16) >> 6;
        int b = (y + (cb * 4200) / 10000 + 16) >> 6;
        rgb[i * 3] = (r < 0) ? 0 : (r > 255) ? 255 : r;
        rgb[i * 3 + 1] = (g < 0) ? 0 : (g > 255) ? 255 : g;
        rgb[i * 3 + 2] = (b < 0) ? 0 : (b > 255) ? 255 : b;
    }
    return 0;
}

static int blur(unsigned char *rgb, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        fprintf(stderr, "Error: Failed to allocate memory for blur.\n");
        return -1;
    }
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            int count = 0;
            for (int dy = -BLUR_RADIUS; dy <= BLUR_RADIUS; dy++) {
                for (int dx = -BLUR_RADIUS; dx <= BLUR_RADIUS; dx++) {
                    int ny = y + dy;
                    int nx = x + dx;
                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        int idx = (ny * width + nx) * 3;
                        sum_r += rgb[idx];
                        sum_g += rgb[idx + 1];
                        sum_b += rgb[idx + 2];
                        count++;
                    }
                }
            }
            int idx = (y * width + x) * 3;
            temp[idx] = sum_r / count;
            temp[idx + 1] = sum_g / count;
            temp[idx + 2] = sum_b / count;
        }
    }
    memcpy(rgb, temp, width * height * 3);
    free(temp);
    return 0;
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, const char *filename, int quality) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }
    unsigned char header[6];
    header[0] = 0xFF;
    header[1] = 0xD8;
    header[2] = 0xFF;
    header[3] = 0xE0;
    header[4] = 0x00;
    header[5] = 1.0 * quality / 100.0 * 65535.0;
    if (fwrite(header, 1, 6, fp) != 6) {
        fprintf(stderr, "Error: Failed to write JPEG header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    unsigned char sof0 = 0xFF;
    unsigned char prec = 0xDB;
    unsigned char prec_val = 0x00;
    unsigned char height_lsb = height & 0xFF;
    unsigned char height_msb = (height >> 8) & 0xFF;
    unsigned char width_lsb = width & 0xFF;
    unsigned char width_msb = (width >> 8) & 0xFF;
    unsigned char components = 3;
    unsigned char h_ac = 0x1F;
    unsigned char v_ac = 0x1F;
    unsigned char h_dc = 0x1F;
    unsigned char v_dc = 0x1F;
    unsigned char quant_table_dc = 0x00;
    unsigned char quant_table_ac = 0x00;
    unsigned char start_of_scan = 0xFF;
    unsigned char eos = 0xD9;
    unsigned char scan_header[12] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    scan_header[0] = 0x00;
    scan_header[1] = 0x00;
    scan_header[2] = 0x00;
    scan_header[3] = 0x00;
    scan_header[4] = 0x00;
    scan_header[5] = 0x00;
    scan_header[6] = 0x00;
    scan_header[7] = 0x00;
    scan_header[8] = 0x00;
    scan_header[9] = 0x00;
    scan_header[10] = 0x00;
    scan_header[11] = 0x00;
    if (fwrite(&sof0, 1, 1, fp) != 1 || fwrite(&prec, 1, 1, fp) != 1 || fwrite(&prec_val, 1, 1, fp) != 1 || fwrite(&height_lsb, 1, 1, fp) != 1 || fwrite(&height_msb, 1, 1, fp) != 1 || fwrite(&width_lsb, 1, 1, fp) != 1 || fwrite(&width_msb, 1, 1, fp) != 1 || fwrite(&components, 1, 1, fp) != 1 || fwrite(&h_ac, 1, 1, fp) != 1 || fwrite(&v_ac, 1, 1, fp) != 1 || fwrite(&h_dc, 1, 1, fp) != 1 || fwrite(&v_dc, 1, 1, fp) != 1 || fwrite(&quant_table_dc, 1, 1, fp) != 1 || fwrite(&quant_table_ac, 1, 1, fp) != 1 || fwrite(&start_of_scan, 1, 1, fp) != 1 || fwrite(scan_header, 1, 12, fp) != 12) {
