static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int yuyv_to_rgb(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height; i++) {
        int y = yuyv[i * 2];
        int u = yuyv[i * 2 + 1];
        int v = yuyv[i * 2 + 2];
        int cb = u - 128;
        int cr = v - 128;
        int r = (y + (cr * 4546) / 10000 + 16) >> 6;
        int g = (y - (cb * 3596) / 10000 - (cr * 1441) / 10000 + 16) >> 6;
        int b = (y + (cb * 4200) / 10000 + 16) >> 6;
        rgb[i * 3] = (r < 0) ? 0 : (r > 255) ? 255 : r;
        rgb[i * 3 + 1] = (g < 0) ? 0 : (g > 255) ? 255 : g;
        rgb[i * 3 + 2] = (b < 0) ? 0 : (b > 255) ? 255 : b;
    }
    return 0;
}

static int blur(unsigned char *rgb, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        fprintf(stderr, "Error: Failed to allocate memory for blur.\n");
        return -1;
    }
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            int count = 0;
            for (int dy = -BLUR_RADIUS; dy <= BLUR_RADIUS; dy++) {
                for (int dx = -BLUR_RADIUS; dx <= BLUR_RADIUS; dx++) {
                    int ny = y + dy;
                    int nx = x + dx;
                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        int idx = (ny * width + nx) * 3;
                        sum_r += rgb[idx];
                        sum_g += rgb[idx + 1];
                        sum_b += rgb[idx + 2];
