#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int has_capability(struct v4l2_capability *cap, unsigned int flag)
{
    return (cap->capabilities & flag) != 0;
}

static int has_controls(struct v4l2_capability *cap)
{
    return has_capability(cap, V4L2_CAP_DEVICE_CAPS) &&
           has_capability(cap, V4L2_CAP_DEVICE_CTRL);
}

static int has_autofocus(struct v4l2_capability *cap)
{
    if (!has_controls(cap))
        return 0;

    struct v4l2_queryctrl qctrl;
    memset(&qctrl, 0, sizeof(qctrl));
    qctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(0, VIDIOC_QUERYCTRL, &qctrl) < 0)
        return 0;

    return (qctrl.flags & V4L2_CTRL_FLAG_DISABLED) == 0;
}

static void print_resolution(unsigned int width, unsigned int height)
{
    printf("  %ux%u", width, height);
}

static void print_frame_rate(unsigned int numerator, unsigned int denominator)
{
