#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500
#define PULSE_INCREMENT 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int adjust_pan(int *current_pulse) {
    if (gpioRead(LEFT_BUTTON_PIN) == 0) {
        int new_pulse = *current_pulse - PULSE_INCREMENT;
        if (new_pulse >= MIN_PULSE_WIDTH) {
            *current_pulse = new_pulse;
            printf("Pan LEFT -> %d us\n", *current_pulse);
        }
    }
    if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
        int new_pulse = *current_pulse + PULSE_INCREMENT;
        if (new_pulse <= MAX_PULSE_WIDTH) {
            *current_pulse = new_pulse;
            printf("Pan RIGHT -> %d us\n", *current_pulse);
        }
    }
    return set_servo_pulse(PAN_SERVO_PIN, *current_pulse);
}

static int adjust_tilt(int *current_pulse) {
    if (gpioRead(UP_BUTTON_PIN) == 0) {
        int new_pulse = *current_pulse + PULSE_INCREMENT;
        if (new_pulse <= MAX_PULSE_WIDTH) {
            *current_pulse = new_pulse;
            printf("Tilt UP -> %d us\n", *current_pulse);
        }
    }
    if (gpioRead(DOWN_BUTTON_PIN) == 0) {
        int new_pulse = *current_pulse - PULSE_INCREMENT;
        if (new_pulse >= MIN_PULSE_WIDTH) {
            *current_pulse = new_pulse;
            printf("Tilt DOWN -> %d us\n", *current_pulse);
        }
    }
    return set_servo_pulse(TILT_SERVO_PIN, *current_pulse);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for servo pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_pulse = CENTER_PULSE_WIDTH;
    int tilt_pulse = CENTER_PULSE_WIDTH;

    if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) != 0 ||
        set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Control (50 Hz PWM, 10 us steps, 50 ms loop)\n");
    printf("  Pan servo: GPIO%d | Tilt servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("  UP: GPIO%d | DOWN: GPIO%d | LEFT: GPIO%d | RIGHT: GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("  Center: %d us | Range: [%d, %d] us\n",
           CENTER_PULSE_WIDTH, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (adjust_pan(&pan_pulse) != 0) break;
        if (adjust_tilt(&tilt_pulse) != 0) break;
        usleep(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

