#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_PIN 17
#define DEBOUNCE_DELAY_SEC 2
#define POLL_INTERVAL_US 100000
#define CAPTURE_QUALITY 85
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_DURATION_MS 500
#define CAPTURE_TIMEOUT_MS 2000
#define HTTP_ENDPOINT_SIZE 256
#define JSON_SIZE 512
#define FILENAME_SIZE 256
#define MOTION_CAPTURES_DIR "motion_captures"

static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;
static int g_http_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "raspistill -o %s -w %d -h %d -q %d -t %d -tl %d 2>/dev/null",
        filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY,
        CAPTURE_DURATION_MS, CAPTURE_TIMEOUT_MS);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspistill exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: raspistill killed by signal %d\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

static int generate_json(const char *filename, const char *timestamp, int motion_status,
                         int gpio_pin, char *json_string, size_t json_size) {
    int ret = snprintf(json_string, json_size,
        "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
        filename, timestamp, motion_status, gpio_pin);
    if (ret < 0 || (size_t)ret >= json_size) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        return -1;
    }
    return 0;
}

static int post_data(const char *json_string, const char *filename) {
    char command[1024];
