#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <gpiod.h>

#define PIR_PIN 17
#define DEBOUNCE_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define CAPTURE_CMD "raspistill -o %s -w 640 -h 480 -q 85 --timeout 2000 --nopreview"
#define CAPTURE_TIMEOUT_MS 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int ensure_dir(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir images");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char cmd[512];
    snprintf(cmd, sizeof(cmd), CAPTURE_CMD, filename);

    int fd = popen(cmd, "r");
    if (fd < 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Failed to execute capture command: %s", cmd);
        log_event(msg);
        return -1;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fd) != NULL) {
        /* discard output */
    }

    int status = pclose(fd);
    if (status == -1) {
        char msg[256];
        snprintf(msg, sizeof(msg), "pclose failed for %s", filename);
        log_event(msg);
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Image captured: %s", filename);
        log_event(msg);
        return 0;
    }

    char msg[256];
    snprintf(msg, sizeof(msg), "Capture failed for %s (status=%d)", filename, status);
    log_event(msg);
    return -1;
}

static int generate_filename(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return -1;
    int ms = (int)(t % 1000);
    if (snprintf(buf, len, "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec, ms) >= (int)len) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (ensure_dir(IMAGE_DIR) != 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "pir-monitor") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("PIR monitoring started on GPIO17 (falling edge).");

    while (running) {
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000 }; /* 100 ms */
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) continue; /* timeout, loop and check running */

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        struct timespec debounce_ts = { .tv_sec = 0, .tv_nsec = DEBOUNCE_MS * 1000000L };
        if (gpiod_line_event_wait(line, &debounce_ts) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait (debounce)");
            continue;
        }

        char filename[64];
        if (generate_filename(filename, sizeof(filename)) != 0) {
            log_event("Filename generation failed.");
            continue;
        }

        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", IMAGE_DIR, filename);

        if (capture_image(filepath) != 0) {
            log_event("Image capture failed.");
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_event("PIR monitoring stopped.");
    return EXIT_SUCCESS;
}

