#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FILENAME "cropped.yuv"
#define TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer = NULL;
    int buffer_length = 0;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }
    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Device does not support %dx%d resolution\n", WIDTH, HEIGHT);
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }
    buffer_length = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int rv;

    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = TIMEOUT_SEC;
        tv.tv_usec = 0;
        rv = select(fd + 1, &fds, NULL, NULL, &tv);
    } while (rv == -1 && errno == EINTR && !stop_flag);

    if (rv == -1) {
        if (errno != EINTR) perror("select");
        goto cleanup;
    }
    if (rv == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }
    if (buf.index != 0) {
        fprintf(stderr, "Unexpected buffer index %u\n", buf.index);
        goto cleanup;
    }
    if (buf.bytesused != (WIDTH * HEIGHT * 2)) {
        fprintf(stderr, "Incomplete frame: %u bytes\n", buf.bytesused);
        goto cleanup;
    }

    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        perror("fopen(" FILENAME ")");
        goto cleanup;
    }

    size_t cropped_size = CROP_WIDTH * CROP_HEIGHT * 2;
    unsigned char *cropped = malloc(cropped_size);
    if (cropped == NULL) {
        perror("malloc");
        goto cleanup;
    }

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int src_x = x * 2;
            int src_y = y * 2;
            cropped[y * CROP_WIDTH * 2 + x * 2] = ((unsigned char *)buffer)[src_y + src_x];
            cropped[y * CROP_WIDTH * 2 + x * 2 + 1] = ((unsigned char *)buffer)[src_y + src_x + 1];
        }
    }

    size_t written = fwrite(cropped, 1, cropped_size, fp);
    if (written != cropped_size) {
        perror("fwrite");
        goto cleanup;
    }

    if (fflush(fp) == EOF) {
        perror("fflush");
        goto cleanup;
    }

    printf("Frame captured and cropped to %s (%zu bytes)\n", FILENAME, written);
    ret = EXIT_SUCCESS;

cleanup:
    if (type != V4L2_BUF_TYPE_VIDEO_CAPTURE || fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
    }
    if (buffer != NULL && buffer != MAP_FAILED) {
        if (munmap(buffer, buffer_length) == -1) {
            perror("munmap");
        }
    }
    if (fp != NULL) {
        if (fclose(fp) == EOF) {
            perror("fclose");
        }
    }
    if (fd != -1) {
        close(fd);
    }
    if (ret == EXIT_SUCCESS && cropped != NULL) {
        free(cropped);
    }
    return ret;
}

