#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define SERVO_FREQUENCY 50
#define SERVO_RANGE 180
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_NEUTRAL_ANGLE 90
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int angle_to_pulse_width(int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        fprintf(stderr, "Error: angle %d out of range [0, %d]\n", angle, SERVO_RANGE);
        return -1;
    }
    return SERVO_MIN_PULSE_WIDTH +
           (int)((float)angle / SERVO_RANGE * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
}

static int set_servo_angle(int pin, int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (pulse_width < 0) {
        return -1;
    }
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_servo_angle(PAN_SERVO_PIN, SERVO_NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, SERVO_NEUTRAL_ANGLE);
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    int pan_angle = SERVO_NEUTRAL_ANGLE;
    int tilt_angle = SERVO_NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
        cleanup();
        return 1;
    }

    printf("Servo control started. Press arrow keys to move pan/tilt, 'q' to quit.\n");

    while (running) {
        int c = getchar();
        if (c == 'q' || c == EOF) {
            break;
        }

        switch (c) {
            case 'a':
                pan_angle -= STEP_SIZE;
                if (pan_angle < 0) pan_angle = 0;
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) break;
                printf("Pan left -> %d\n", pan_angle);
                break;
            case 'd':
                pan_angle += STEP_SIZE;
                if (pan_angle > SERVO_RANGE) pan_angle = SERVO_RANGE;
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) break;
                printf("Pan right -> %d\n", pan_angle);
                break;
            case 'w':
                tilt_angle += STEP_SIZE;
                if (tilt_angle > SERVO_RANGE) tilt_angle = SERVO_RANGE;
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) break;
                printf("Tilt up -> %d\n", tilt_angle);
                break;
            case 's':
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < 0) tilt_angle = 0;
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) break;
                printf("Tilt down -> %d\n", tilt_angle);
                break;
            default:
                break;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    cleanup();
    printf("Servo control stopped.\n");
    return 0;
}

