    }

    printf("Servo control started. Press arrow keys to move pan/tilt, 'q' to quit.\n");

    while (running) {
        int c = getchar();
        if (c == 'q' || c == EOF) {
            break;
        }

        switch (c) {
            case 'a':
                pan_angle -= STEP_SIZE;
                if (pan_angle < 0) pan_angle = 0;
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) break;
                printf("Pan left -> %d\n", pan_angle);
                break;
            case 'd':
                pan_angle += STEP_SIZE;
                if (pan_angle > SERVO_RANGE) pan_angle = SERVO_RANGE;
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) break;
                printf("Pan right -> %d\n", pan_angle);
                break;
            case 'w':
                tilt_angle += STEP_SIZE;
                if (tilt_angle > SERVO_RANGE) tilt_angle = SERVO_RANGE;
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) break;
                printf("Tilt up -> %d\n", tilt_angle);
                break;
            case 's':
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < 0) tilt_angle = 0;
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) break;
                printf("Tilt down -> %d\n", tilt_angle);
                break;
            default:
                break;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    cleanup();
    printf("Servo control stopped.\n");
    return 0;
}

