#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define SAMPLE_INTERVAL_MS 500
#define WIND_SPEED_SCALE 0.1f
#define WIND_DIRECTION_RESOLUTION 16
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_init(int fd) {
    if (i2c_write_byte(fd, 0x33) < 0) return -1;
    if (i2c_write_byte(fd, 0x32) < 0) return -1;
    if (i2c_write_byte(fd, 0x06) < 0) return -1;
    if (i2c_write_byte(fd, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, 0x28) < 0) return -1;
    if (i2c_write_byte(fd, 0x01) < 0) return -1;
    return 0;
}

static int lcd_clear(int fd) {
    if (i2c_write_byte(fd, 0x01) < 0) return -1;
    usleep(2000);
    return 0;
}

static int lcd_set_cursor(int fd, int row, int col) {
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    addr |= (col & 0x0F);
    if (i2c_write_byte(fd, addr) < 0) return -1;
    return 0;
}

static int lcd_write_string(int fd, const char *str) {
    while (*str) {
        if (i2c_write_byte(fd, (uint8_t)*str) < 0) return -1;
        str++;
    }
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    if (spi_transfer(fd, tx, rx, 3) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        lcd_clear(i2c_fd);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (lcd_init(i2c_fd) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input\n");
        gpioTerminate();
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (gpioSetPullUpDown(17, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO17\n");
        gpioTerminate();
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    if (gpioSetISRFuncEx(17, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO17\n");
        gpioTerminate();
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        pulse_count = 0;
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = SAMPLE_WINDOW_MS * 1000000L}, NULL);

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ms = (end.tv_sec - start.tv_sec) * 1000L + (end.tv_nsec - start.tv_nsec) / 1000000L;
        if (elapsed_ms < 0) elapsed_ms = 0;

        float wind_speed = (float)pulse_count * WIND_SPEED_SCALE * (float)elapsed_ms / 1000.0f;

        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            adc_value = -1;
        }

        char wind_direction_str[16];
        if (adc_value >= 0) {
            int direction = (adc_value / (ADC_MAX_VALUE / WIND_DIRECTION_RESOLUTION)) % WIND_DIRECTION_RESOLUTION;
            switch (direction) {
                case 0:  strncpy(wind_direction_str, "N", sizeof(wind_direction_str) - 1); break;
                case 1:  strncpy(wind_direction_str, "NNE", sizeof(wind_direction_str) - 1); break;
                case 2:  strncpy(wind_direction_str, "NE", sizeof(wind_direction_str) - 1); break;
                case 3:  strncpy(wind_direction_str, "ENE", sizeof(wind_direction_str) - 1); break;
                case 4:  strncpy(wind_direction_str, "E", sizeof(wind_direction_str) - 1); break;
                case 5:  strncpy(wind_direction_str, "ESE", sizeof(wind_direction_str) - 1); break;
                case 6:  strncpy(wind_direction_str, "SE", sizeof(wind_direction_str) - 1); break;
                case 7:  strncpy(wind_direction_str, "SSE", sizeof(wind_direction_str) - 1); break;
                case 8:  strncpy(wind_direction_str, "S", sizeof(wind_direction_str) - 1); break;
                case 9:  strncpy(wind_direction_str, "SSW", sizeof(wind_direction_str) - 1); break;
                case 10: strncpy(wind_direction_str, "SW", sizeof(wind_direction_str) - 1); break;
                case 11: strncpy(wind_direction_str, "WSW", sizeof(wind_direction_str) - 1); break;
                case 12: strncpy(wind_direction_str, "W", sizeof(wind_direction_str) - 1); break;
                case 13: strncpy(wind_direction_str, "WNW", sizeof(wind_direction_str) - 1); break;
                case 14: strncpy(wind_direction_str, "NW", sizeof(wind_direction_str) - 1); break;
                case 15: strncpy(wind_direction_str, "NNW", sizeof(wind_direction_str) - 1); break;
                default: strncpy(wind_direction_str, "N", sizeof(wind_direction_str) - 1); break;
            }
            wind_direction_str[sizeof(wind_direction_str) - 1] = '\0';
        } else {
            strncpy(wind_direction_str, "N", sizeof(wind_direction_str) - 1);
            wind_direction_str[sizeof(wind_direction_str) - 1] = '\0';
        }

        char lcd_buffer[LCD_WIDTH + 1];
        snprintf(lcd_buffer, sizeof(lcd_buffer), "WS: %.1f MPH | %s", wind_speed, wind_direction_str);

        if (lcd_clear(i2c_fd) < 0) {
            fprintf(stderr, "LCD clear failed\n");
        }
        if (lcd_set_cursor(i2c_fd, 0, 0) < 0) {
            fprintf(stderr, "LCD set cursor failed\n");
        }
        if (lcd_write_string(i2c_fd, lcd_buffer) < 0) {
            fprintf(stderr, "LCD write string failed\n");
        }

        if (adc_value == ADC_MAX_VALUE || adc_value == ADC_MIN_VALUE) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d), sensor may be absent or disconnected\n", adc_value);
        }

        if (running) {
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = SAMPLE_INTERVAL_MS * 1000000L}, NULL);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    gpioTerminate();
    return 0;
}

