/*
 * Water Flow Sensor (YF-S201) Measurement and LCD Display
 * Board:  Raspberry Pi 3 Model B+
 * Sensor:  YF-S201 on GPIO17 (BCM), physical pin 11
 * LCD:    16x2 LCD1602 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *
 * Build:  gcc -O2 -Wall -o flow_meter flow_meter.c -lpigpio -lrt
 * Run:    sudo ./flow_meter
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLOW_SENSOR_GPIO      17          /* BCM pin connected to YF-S201 OUT */
#define I2C_BUS               1           /* /dev/i2c-1 on RPi 3B+            */
#define LCD_ADDR              0x27        /* Common I2C address for 16x2 LCD */
#define LCD_WIDTH             16
#define LCD_CHR               1
#define LCD_CMD               0
#define LCD_BACKLIGHT         0x08
#define LCD_ENABLE            0x04
#define LCD_RS                0x01
#define LCD_EN                0x04
#define LCD_RW                0x02
#define LCD_RS_SHIFT          0
#define LCD_EN_SHIFT          1
#define LCD_RW_SHIFT          2
#define LCD_BACKLIGHT_SHIFT   3
#define LCD_D4_SHIFT          4
#define LCD_D5_SHIFT          5
#define LCD_D6_SHIFT          6
#define LCD_D7_SHIFT          7
#define LCD_ENABLE_PULSE_US   500        /* Enable pulse width (microseconds) */
#define LCD_E_PULSE_DELAY_US  200        /* Enable to-and-from delay (us)    */
