#define LCD_DISPLAY_OFF       0x08
#define LCD_CURSOR_OFF        0x06
#define LCD_ENTRY_MODE_SET    0x02
#define LCD_FUNCTION_SET      0x28
#define LCD_CLEAR_DISPLAY     0x01
#define LCD_SET_CURSOR        0x80
#define FLOW_SCALE            0.001      /* L/min per pulse (YF-S201 5L/min) */
#define SAMPLE_INTERVAL_US    1000000    /* 1 second in microseconds        */
#define NO_FLOW_TIMEOUT_S     10         /* Max seconds with no pulses      */

