static void flow_callback(int gpio, int level, uint32_t tick, void *userdata);
static int  lcd_init(void);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

