    gpioDelay(5000);
    lcd_send_nibble(0x03, false);
    gpioDelay(1000);
    lcd_send_nibble(0x03, false);
    gpioDelay(1000);
    lcd_send_nibble(0x02, false);
    gpioDelay(1000);

