    lcd_command(LCD_FUNCTION_SET);
    /* Display on, cursor off, blink off */
    lcd_command(LCD_DISPLAY_ON | LCD_CURSOR_OFF);
    /* Entry mode: increment, no shift */
    lcd_command(LCD_ENTRY_MODE_SET);
    /* Clear display */
    lcd_clear();

    return 0;
}

