static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        lcd_clear();
        lcd_print("Shutting down...");
        gpioDelay(2000000);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize LCD via I2C */
    g_i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, LCD_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init() != 0) {
        fprintf(stderr, "Error: LCD initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure flow sensor GPIO */
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    /* Register alert callback for rising edge */
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, flow_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO %d.\n",
                FLOW_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water flow measurement started. Press Ctrl+C to exit.\n");
    lcd_print("Flow Rate: 0.00");

    uint32_t last_pulse_tick = gpioTick();
    uint32_t no_flow_start   = last_pulse_tick;

    while (g_running) {
        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_pulse_tick;

        /* Check for sensor-absent / no-flow timeout */
        if (elapsed > (uint32_t)(NO_FLOW_TIMEOUT_S * 1000000)) {
            fprintf(stderr, "Warning: No flow detected for %d seconds.\n",
                    NO_FLOW_TIMEOUT_S);
            lcd_clear();
            lcd_print("Sensor absent or");
            lcd_set_cursor(1, 0);
            lcd_print("no flow detected");
            last_pulse_tick = now;
            no_flow_start   = now;
            continue;
        }

        /* Measure pulses over 1-second interval */
        uint32_t start_tick = gpioTick();
        uint32_t pulse_count = 0;

        while (g_running && (gpioTick() - start_tick) < SAMPLE_INTERVAL_US) {
            gpioDelay(10000);  /* 10 ms sleep to reduce CPU usage */
        }

        if (!g_running)
            break;

        last_pulse_tick = gpioTick();

        float flow_rate = (float)pulse_count * FLOW_SCALE;
        lcd_print_flow_rate(flow_rate);

        printf("Flow Rate: %.2f L/min (pulses: %u)\n", flow_rate, pulse_count);
    }

    cleanup();
    return EXIT_SUCCESS;
}

