#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_US 800

static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d (BCM %d) as output.\n", i, row_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(row_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise row pin %d (BCM %d) LOW.\n", i, row_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set column pin %d (BCM %d) as output.\n", i, col_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise column pin %d (BCM %d) HIGH.\n", i, col_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(col_pins[i], 1);
    }
}

static void draw_led(int row, int col) {
    if (gpioWrite(row_pins[row], 1) != 0) {
        fprintf(stderr, "Error: failed to set row %d HIGH.\n", row);
        return;
    }
    if (gpioWrite(col_pins[col], 0) != 0) {
        fprintf(stderr, "Error: failed to set column %d LOW.\n", col);
        gpioWrite(row_pins[row], 0);
        return;
    }
}

static void clear_row(int row) {
    gpioWrite(row_pins[row], 0);
}

static void clear_col(int col) {
    gpioWrite(col_pins[col], 1);
}

static void display_frame(int frame[NUM_ROWS][NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        clear_row(row);
        for (int col = 0; col < NUM_COLS; col++) {
            if (frame[row][col] == 1) {
                draw_led(row, col);
            }
        }
        gpioDelay(DELAY_US);
    }
}

static void generate_frame_left(int frame[NUM_ROWS][NUM_COLS], int phase) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            int idx = (row + phase) % NUM_ROWS;
            frame[row][col] = (idx == col) ? 1 : 0;
        }
    }
}

static void generate_frame_right(int frame[NUM_ROWS][NUM_COLS], int phase) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            int idx = (row - phase + NUM_ROWS) % NUM_ROWS;
            frame[row][col] = (idx == col) ? 1 : 0;
        }
    }
}

static void cleanup(void) {
    clear_matrix();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    int frame_left[NUM_ROWS][NUM_COLS];
    int frame_right[NUM_ROWS][NUM_COLS];
    int phase_left = 0;
    int phase_right = 0;

    while (running) {
