            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set column pin %d (BCM %d) as output.\n", i, col_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise column pin %d (BCM %d) HIGH.\n", i, col_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(col_pins[i], 1);
    }
}

static void draw_led(int row, int col) {
    if (gpioWrite(row_pins[row], 1) != 0) {
        fprintf(stderr, "Error: failed to set row %d HIGH.\n", row);
        return;
    }
    if (gpioWrite(col_pins[col], 0) != 0) {
        fprintf(stderr, "Error: failed to set column %d LOW.\n", col);
        gpioWrite(row_pins[row], 0);
        return;
    }
}

static void clear_row(int row) {
    gpioWrite(row_pins[row], 0);
}

static void clear_col(int col) {
    gpioWrite(col_pins[col], 1);
}

