/*
 * VL53L3CX Multi-Target Time-of-Flight Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: STMicroelectronics VL53L3CX
 *
 * NOTE: The VL53L3CX requires proprietary firmware downloaded via I2C
 *       to configure the sensor for multi-target operation.  This
 *       program implements the I2C communication layer and error
 *       handling, and stubs the firmware download with a descriptive
 *       comment so that the firmware can be compiled and linked in
 *       a separate build step.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l3cx_reader vl53l3cx_reader.c \
 *               -lpigpio -lrt
 * Run:    sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C address ---- */
#define VL53L3CX_ADDR 0xBA

/* ---- I2C bus ---- */
#define I2C_BUS 1

/* ---- Polling interval (microseconds) ---- */
#define POLL_INTERVAL_US 100000  /* 100 ms */

/* ---- Maximum number of targets ---- */
#define MAX_TARGETS 10

/* ---- VL53L3CX register addresses (16-bit, big-endian on the bus) ---- */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID       0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START             0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS           0x0089
#define VL53L3CX_REG_RESULT_NUM_OF_TARGETS         0x008A
#define VL53L3CX_REG_RESULT_TARGET_DISTANCE        0x008C

/* ---- Expected model ID for VL53L3CX ---- */
#define VL53L3CX_MODEL_ID 0xEA

/* ---- Global state ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Write a 16-bit register address followed by `len` bytes ---- */
static int i2c_write_reg(uint16_t reg, const uint8_t *data, uint8_t len)
{
    uint8_t buf[32];
    uint8_t *p = buf;

    if (len > 30) {
        fprintf(stderr, "Error: write length %u exceeds buffer\n", len);
        return -1;
    }

    *p++ = (uint8_t)(reg >> 8);
    *p++ = (uint8_t)(reg & 0xFF);
    memcpy(p, data, len);

    if (i2cWriteDevice(i2c_handle, (char *)buf, len + 2) != (int)(len + 2)) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* ---- Read `len` bytes from a 16-bit register address ---- */
static int i2c_read_reg(uint16_t reg, uint8_t *data, uint8_t len)
{
    uint8_t addr_buf[2];
    addr_buf[0] = (uint8_t)(reg >> 8);
    addr_buf[1] = (uint8_t)(reg & 0xFF);

    if (i2cWriteDevice(i2c_handle, (char *)addr_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cWriteDevice (addr) failed for reg 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* ---- Read a single 16-bit register (big-endian) ---- */
static int i2c_read_reg16(uint16_t reg, uint16_t *value)
{
    uint8_t data[2];
    if (i2c_read_reg(reg, data, 2) != 0)
        return -1;
    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ---- Read a single 8-bit register ---- */
static int i2c_read_reg8(uint16_t reg, uint8_t *value)
{
    return i2c_read_reg(reg, value, 1);
}

/* ---- Initialize the VL53L3CX sensor ---- */
static int init_sensor(void)
{
    uint8_t model_id = 0;

    /* Verify sensor presence by reading the model ID */
    if (i2c_read_reg8(VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: cannot read model ID (sensor absent or bus error)\n");
        return -1;
    }

    if (model_id != VL53L3CX_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L3CX_MODEL_ID);
        return -1;
    }

    printf("VL53L3CX detected (model ID 0x%02X)\n", model_id);

    /*
     * NOTE: The VL53L3CX requires proprietary firmware downloaded via
     *       I2C to configure the sensor for multi-target operation.
     *       This stub prints a descriptive comment; the firmware must
     *       be compiled and linked in a separate build step.
     */
    printf("--- Firmware download stub ---\n");
    printf("  The VL53L3CX firmware download is a proprietary sequence\n");
    printf("  that must be compiled and linked separately.  This stub\n");
    printf("  provides the I2C communication layer and error handling.\n");
    printf("  Replace the stub with the compiled firmware download code.\n");
    printf("--- End of stub ---\n");

    return 0;
}

/* ---- Read distance measurements for all targets ---- */
static int read_distances(uint16_t distances[MAX_TARGETS])
{
    uint8_t status = 0;
    uint8_t num_targets = 0;
    uint8_t target_data[MAX_TARGETS * 2];

    /* Check if data is ready */
    if (i2c_read_reg8(VL53L3CX_REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* Data not ready yet */
        return 1;
    }

    /* Read number of targets */
    if (i2c_read_reg8(VL53L3CX_REG_RESULT_NUM_OF_TARGETS, &num_targets) != 0)
        return -1;

    if (num_targets > MAX_TARGETS) {
        fprintf(stderr, "Warning: %u targets exceeds buffer, clamping to %d\n",
                num_targets, MAX_TARGETS);
        num_targets = MAX_TARGETS;
    }

    /* Read target distance data (16-bit per target, little-endian on the bus) */
    if (i2c_read_reg(VL53L3CX_REG_RESULT_TARGET_DISTANCE, target_data,
                     num_targets * 2) != 0)
        return -1;

    for (uint8_t i = 0; i < num_targets; i++) {
        distances[i] = ((uint16_t)target_data[i * 2 + 1] << 8) | target_data[i * 2];
    }

    return 0;
}

/* ---- Print timestamped distance values ---- */
static void print_distances(const uint16_t distances[], uint8_t num_targets)
{
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Targets: %u", timestamp, num_targets);
    for (uint8_t i = 0; i < num_targets; i++) {
        printf("  T%u=%u", i, distances[i]);
    }
    printf("\n");
    fflush(stdout);
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Stop the sensor */
        (void)i2c_write_reg(VL53L3CX_REG_SYSTEM_MODE_START, NULL, 0);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    uint16_t distances[MAX_TARGETS];
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting continuous distance readings (Ctrl+C to stop)...\n");

    /* Main polling loop */
    while (!terminate) {
        ret = read_distances(distances);
        if (ret == 0) {
            uint8_t num_targets = 0;
            if (i2c_read_reg8(VL53L3CX_REG_RESULT_NUM_OF_TARGETS, &num_targets) == 0) {
                print_distances(distances, num_targets);
            } else {
                fprintf(stderr, "Warning: failed to read number of targets\n");
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: read_distances failed\n");
        }
        /* ret == 1: data not ready yet, just continue */

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

