#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x04
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int *distance) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d (%s)\n",
                bytes_read, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance = (int)raw;
    return 0;
}

static int log_data(int distance) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Distance\n") < 0) {
            fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("Starting distance sampling. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int distance = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_distance(&distance) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retries, MAX_RETRIES);
                if (init_i2c() != 0) {
                    fprintf(stderr, "I2C reinit failed, exiting.\n");
                    terminate = 1;
                    break;
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
            distance = -1;
        }

        if (log_data(distance) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        if (!terminate) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

