    if (si1145_write_reg(SI1145_REG_PS_RATE, 0x08) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_PS_LED21, 0x77) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_PS_LED3, 0x01) < 0) return -1;

    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t vis_lo, vis_hi, ir_lo, ir_hi, ps_lo, ps_hi;

    if (si1145_read_reg(SI1145_REG_ALS_VIS_DATA0, &vis_lo) < 0) return -1;
    if (si1145_read_reg(SI1145_REG_ALS_VIS_DATA0 + 1, &vis_hi) < 0) return -1;
    if (si1145_read_reg(SI1145_REG_ALS_IR_DATA0, &ir_lo) < 0) return -1;
    if (si1145_read_reg(SI1145_REG_ALS_IR_DATA0 + 1, &ir_hi) < 0) return -1;
    if (si1145_read_reg(SI1145_REG_PS1_DATA0, &ps_lo) < 0) return -1;
    if (si1145_read_reg(SI1145_REG_PS1_DATA0 + 1, &ps_hi) < 0) return -1;

    *ambient_light = (uint16_t)((vis_hi << 8) | vis_lo);
    *proximity = (uint16_t)((ps_hi << 8) | ps_lo);

    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    uint16_t proximity, ambient_light;

    while (!terminate) {
        if (si1145_read_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) {
        i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, 0x00);
        i2cClose(i2c_handle);
    }
    if (log_file) fclose(log_file);
    gpioTerminate();

    return 0;
}

