/*
 * HC-SR04 Ultrasonic Distance Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring (BCM numbering):
 *   GPIO 17 -> TRIGGER (output)
 *   GPIO 27 -> ECHO    (input via 1k/2k divider; 5V sensor, 3.3V Pi)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lm
 * Run:    sudo ./hcsr04_log   (root needed for pigpio)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  30000       /* 30 ms max wait for echo rise   */
#define PULSE_TIMEOUT_US 30000       /* 30 ms max wait for echo fall   */
#define SAMPLE_PERIOD_S  60          /* 60 s between samples          */
#define SPEED_OF_SOUND   34300.0     /* cm/s at ~20 °C                */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define WATERING_THRESHOLD_CM 15.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns elapsed microseconds between two gpioTick() calls.        */
static long elapsed_us(const uint32_t *start, const uint32_t *end)
{
    return (long)(*end - *start);
}

/* ------------------------------------------------------------------ */
/*
 * Measure distance in cm.  Returns >= 0 on success, -1.0 on timeout,
 * -2.0 on sensor-absent (echo never rose).
 */
static double measure_distance(void)
{
    uint32_t t_start, t_rise, t_fall;
    int      echo_state;

    /* --- Issue 10 µs trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* --- Wait for echo rising edge (timeout 30 ms) --- */
    t_start = gpioTick();
    do {
        echo_state = gpioRead(ECHO_PIN);
        if (echo_state < 0) {
            fprintf(stderr, "Error: gpioRead(ECHO) failed\n");
            return -1.0;
        }
        if (elapsed_us(&t_start, &gpioTick()) > ECHO_TIMEOUT_US) {
            return -2.0;   /* sensor absent / no object */
        }
    } while (echo_state == 0);
    t_rise = gpioTick();

    /* --- Wait for echo falling edge (timeout 30 ms) --- */
    do {
        echo_state = gpioRead(ECHO_PIN);
        if (echo_state < 0) {
            fprintf(stderr, "Error: gpioRead(ECHO) failed\n");
            return -1.0;
        }
        if (elapsed_us(&t_rise, &gpioTick()) > PULSE_TIMEOUT_US) {
            return -1.0;   /* echo stuck high — timeout */
        }
    } while (echo_state == 1);
    t_fall = gpioTick();

    long pulse_us = elapsed_us(&t_rise, &t_fall);
    double distance_cm = (pulse_us / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -3.0;   /* out of range */
    }
    return distance_cm;
}

/* ------------------------------------------------------------------ */
static void log_reading(double distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (distance_cm < 0) {
        const char *reason = "TIMEOUT";
        if (distance_cm == -2.0) reason = "SENSOR_ABSENT";
        if (distance_cm == -3.0) reason = "OUT_OF_RANGE";
        fprintf(g_log, "%s, %s\n", ts, reason);
    } else {
        fprintf(g_log, "%s, %.2f cm\n", ts, distance_cm);
        if (distance_cm < WATERING_THRESHOLD_CM) {
            fprintf(g_log, "%s, Time to water the plant!\n", ts);
        }
    }
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen("distance_log.txt", "a");
    if (!g_log) {
        perror("fopen(distance_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 logger started.  TRIGGER=GPIO%d, ECHO=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Logging to distance_log.txt every %d s.  Press Ctrl-C to stop.\n",
           SAMPLE_PERIOD_S);

    /* --- Main sampling loop --- */
    while (g_running) {
        double distance = measure_distance();
        log_reading(distance);
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

