#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR 0x34
#define I2C_BUS 1

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_CONFIG2 0x91
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02
#define ENABLE_PEN 0x04
#define ENABLE_WEN 0x08

#define PROXIMITY_THRESHOLD 200
#define POLL_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = (uint16_t)((data_buf[1] << 8) | data_buf[0]);
    return 0;
}

static int initialize_apds9960(int handle) {
    uint8_t id;
    if (i2c_read_byte(handle, APDS9960_ID, &id) != 0) {
        fprintf(stderr, "Error: Failed to read APDS9960 ID.\n");
        return -1;
    }
    if (id != 0x96) {
        fprintf(stderr, "Error: Invalid APDS9960 ID: 0x%02X (expected 0x96).\n", id);
        return -1;
    }

    if (i2c_write_byte(handle, APDS9960_ENABLE, ENABLE_PON) != 0) return -1;
    gpioDelay(1000);

    if (i2c_write_byte(handle, APDS9960_ATIME, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PTIME, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG1, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x00) != 0) return -1;

    if (i2c_write_byte(handle, APDS9960_ENABLE, ENABLE_PON | ENABLE_AEN | ENABLE_PEN | ENABLE_WEN) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_apds9960_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *proximity) {
    uint8_t status;
    if (i2c_read_byte(handle, APDS9960_STATUS, &status) != 0) return -1;

    if ((status & 0x01) == 0) {
        return 1; // No data ready yet
    }

    if (i2c_read_word(handle, APDS9960_CDATAL, red) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_CDATAH, red) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_RDATAL, green) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_RDATAH, green) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_GDATAL, blue) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_GDATAH, blue) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_BDATAL, blue) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_BDATAH, blue) != 0) return -1;
    if (i2c_read_word(handle, APDS9960_PDATA, proximity) != 0) return -1;

    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, APDS9960_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (initialize_apds9960(i2c_handle) != 0) {
        fprintf(stderr, "Error: APDS9960 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    struct sigaction sa;
