#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define CSV_FILE       "heartrate.csv"
#define SAMPLE_MS      100

/* Si1182 register addresses (from datasheet) */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x08
#define REG_PS_LED21    0x0F
#define REG_PS1_DATA    0x10
#define REG_PS2_DATA    0x11

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X)\n", reg, val);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

static int init_sensor(int fd)
{
    uint8_t part_id;
    if (i2c_read_byte(fd, REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != 0x82) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    /* Write mandatory HW_KEY (0x17 per datasheet) */
    if (i2c_write_byte(fd, REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Set measurement rate to 100 ms (0x0A = 100 ms) */
    if (i2c_write_byte(fd, REG_MEAS_RATE, 0x0A) < 0)
        return -1;

    /* Enable PS1 LED (bit 0) and PS2 LED (bit 1) */
    if (i2c_write_byte(fd, REG_PS_LED21, 0x03) < 0)
        return -1;

    return 0;
}

static int read_proximity(int fd, uint16_t *ps1, uint16_t *ps2)
{
    uint8_t lo, hi;
    if (i2c_read_byte(fd, REG_PS1_DATA, &lo) < 0) return -1;
    if (i2c_read_byte(fd, REG_PS2_DATA, &hi) < 0) return -1;
    *ps1 = (uint16_t)lo;
    *ps2 = (uint16_t)hi;
    return 0;
}

static int calculate_bpm(uint16_t ps1, uint16_t ps2)
{
    /*
     * Placeholder: a real heart-rate monitor would use a
     * proprietary algorithm on the proximity data.  Here we
     * compute a simple difference and scale it to BPM.
     */
    int diff = (int)ps2 - (int)ps1;
    return (int)(diff * 10);
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        perror("fopen " CSV_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint16_t ps1 = 0, ps2 = 0;
        if (read_proximity(g_i2c_fd, &ps1, &ps2) < 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        int bpm = calculate_bpm(ps1, ps2);
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (fprintf(g_csv, "%s,%d\n", ts, bpm) < 0) {
            perror("fprintf");
            break;
        }
        if (fflush(g_csv) != 0) {
            perror("fflush");
            break;
        }

        usleep(SAMPLE_MS * 1000);
    }

    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

