/*
 * Raspberry Pi 3 Model B+ — VL53L0X ToF sensor + GPIO 17 falling-edge trigger
 *
 * Wiring:
 *   VL53L0X SDA -> Pi GPIO 2 (I2C bus 1 SDA)
 *   VL53L0X SCL -> Pi GPIO 3 (I2C bus 1 SCL)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *   VL53L0X XSHUT  -> 3.3 V (sensor enabled)
 *   VL53L0X XIO    -> Pi GPIO 17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l0x_trigger vl53l0x_trigger.c
 *
 * Run:
 *   ./vl53l0x_trigger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x10
#define GPIO_TRIGGER   17          /* BCM pin 17 */
#define LOG_FILE       "distance_log.txt"

/* VL53L0X register addresses (16-bit, big-endian on the bus) */
#define VL53L0X_REG_SOFT_RESET              0x0003
#define VL53L0X_REG_MODEL_ID               0x010F
#define VL53L0X_REG_SYSTEM_MODE_START      0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS    0x0089
#define VL53L0X_REG_RESULT_DISTANCE        0x0096
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086

#define VL53L0X_MODEL_ID_EXPECTED          0xEA
#define VL53L0X_SYS_MODE_START_SINGLE      0x01
#define VL53L0X_SYS_MODE_IDLE              0x00

#define POLL_TIMEOUT_MS                    100
#define MEAS_TIMEOUT_MS                    1000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static FILE *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
