/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg16: write addr 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: read 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L0X                                                             */
/* ------------------------------------------------------------------ */
static int vl53l0x_init(int fd)
{
    uint8_t model_id = 0;

    /* Soft reset */
    if (i2c_write_reg16(fd, VL53L0X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(10000);                       /* 10 ms */

    if (i2c_write_reg16(fd, VL53L0X_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(10000);

    /* Verify model ID */
    if (i2c_read_reg16(fd, VL53L0X_REG_MODEL_ID, &model_id) < 0)
        return -1;

    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "VL53L0X: unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L0X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

