{
    return i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START,
                           VL53L0X_SYS_MODE_START_SINGLE);
}

static int vl53l0x_stop(int fd)
{
    return i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START,
                           VL53L0X_SYS_MODE_IDLE);
}

static int vl53l0x_read_distance(int fd, uint16_t *distance_mm)
{
