    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L0X ready. Waiting for falling-edge trigger on GPIO %d (Ctrl+C to exit)...\n",
