/*
 * Raspberry Pi Zero W – ICU-20201 ultrasonic ToF sensor monitor
 *
 * Hardware:
 *   - ICU-20201 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - LED on GPIO 17 (BCM) with appropriate series resistor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_monitor icu20201_monitor.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ICU20201_ADDR        0x20   /* ICU-20201 default I2C address */
#define LED_GPIO             17
#define DISTANCE_THRESHOLD   20.0f  /* cm */
#define LOG_FILE             "distance_log.txt"
#define SAMPLE_PERIOD_US     100000 /* 100 ms */

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_RESULT_DISTANCE  0x0001
#define REG_CONFIG          0x0002

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_distance(float *distance_out);
static void control_led(int on);
static void log_distance(float distance);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- GPIO init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "[ERROR] Failed to initialise GPIO %d to LOW\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor init -------------------------------- */
static int init_sensor(void)
{
    /*
     * Write a configuration register to enable the measurement engine.
     * The exact register bits depend on the ICU-20201 variant and firmware
     * version; this is a representative starting point.
     */
    uint8_t cfg[3] = {
        REG_CONFIG,
        0x01,          /* enable measurement */
        0x00           /* range / power */
    };

    if (i2cWriteDevice(g_i2c_handle, (char *)cfg, 3) != 0) {
        fprintf(stderr, "[ERROR] Failed to write ICU-20201 config register\n");
        return -1;
    }

    /* Allow the sensor to settle after configuration */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* ----------------------------- Read distance ------------------------------ */
static int read_distance(float *distance_out)
{
    uint8_t reg = REG_RESULT_DISTANCE;
    uint8_t buf[2];

    /* Point to the distance result register */
    if (i2cWriteDevice(g_i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to set ICU-20201 register pointer\n");
        return -1;
    }

    /* Read 2 bytes of distance data */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] Failed to read ICU-20201 distance data\n");
        return -1;
    }

    /*
     * ICU-20201 returns distance as a 16-bit big-endian value.
     * Convert to centimetres (adjust scale factor per datasheet).
     */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *distance_out = (float)raw / 100.0f; /* example scale: 100 counts/cm */
    return 0;
}

/* ----------------------------- LED control -------------------------------- */
static void control_led(int on)
{
    if (gpioWrite(LED_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d) failed\n", LED_GPIO);
    }
}

/* ----------------------------- Log distance -------------------------------- */
static void log_distance(float distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed; logging without timestamp\n");
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "[WARN] fprintf to log file failed\n");
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush of log file failed\n");
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;

        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
            control_led(distance < DISTANCE_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; LED set off\n");
            control_led(0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

