     * Convert to centimetres (adjust scale factor per datasheet).
     */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *distance_out = (float)raw / 100.0f; /* example scale: 100 counts/cm */
    return 0;
}

/* ----------------------------- LED control -------------------------------- */
static void control_led(int on)
{
    if (gpioWrite(LED_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d) failed\n", LED_GPIO);
    }
}

/* ----------------------------- Log distance -------------------------------- */
static void log_distance(float distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed; logging without timestamp\n");
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "[WARN] fprintf to log file failed\n");
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush of log file failed\n");
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
