        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
            control_led(distance < DISTANCE_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; LED set off\n");
            control_led(0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

