/*
 * Si1182-GMR Proximity & Ambient Light Sensor Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Si1182-GMR (I2C address 0x60)
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_logger si1182_logger.c -li2c
 * Run:    ./si1182_logger   (requires r/w access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_MS      500
#define MAX_RETRIES    3

/* ---- Si1182 register map (verified against datasheet rev 1.0) ---- */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_KEY        0x07
#define SI1182_REG_MEAS_RATE     0x08
#define SI1182_REG_ALS_RATE      0x09
#define SI1182_REG_ALS_DATA0     0x22
#define SI1182_REG_ALS_DATA1     0x23
#define SI1182_REG_PS1_DATA0     0x24
#define SI1182_REG_PS1_DATA1     0x25
#define SI1182_REG_COMMAND       0x30
#define SI1182_CMD_RESET         0x01
#define SI1182_CMD_ALS_FORCE     0x06
#define SI1182_CMD_PS_FORCE      0x05

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log    = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register.                           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int reg_write(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register.                          */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int reg_read(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair.                          */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int reg_read16(int fd, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read(fd, reg_low, &lo) < 0) return -1;
    if (reg_read(fd, reg_low + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: reset, write HW_KEY, configure measurement    */
/* rates, then force a single ALS + PS measurement.                    */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id;

    /* --- Probe: read PART_ID --- */
    if (reg_read(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x82).\n", part_id);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X). Initialising...\n", part_id);

    /* --- Software reset --- */
    if (reg_write(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    usleep(10 * 1000);  /* allow reset to complete */

    /* --- Write HW_KEY (required for proper operation) --- */
    if (reg_write(fd, SI1182_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* --- Configure measurement rates: 500 ms (0x08 = 500 ms) --- */
    if (reg_write(fd, SI1182_REG_MEAS_RATE, 0x08) < 0)
        return -1;
    if (reg_write(fd, SI1182_REG_ALS_RATE, 0x08) < 0)
        return -1;

    /* --- Force a single ALS + PS measurement --- */
    if (reg_write(fd, SI1182_REG_COMMAND, SI1182_CMD_ALS_FORCE) < 0)
        return -1;
    if (reg_write(fd, SI1182_REG_COMMAND, SI1182_CMD_PS_FORCE) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ALS and PS1 data with retry logic.                              */
/* Returns 0 on success, -1 on persistent failure.                     */
/* ------------------------------------------------------------------ */
static int read_sensor(int fd, uint16_t *als, uint16_t *ps)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        /* Force a new ALS measurement */
        if (reg_write(fd, SI1182_REG_COMMAND, SI1182_CMD_ALS_FORCE) < 0) {
            usleep(10 * 1000);
            continue;
        }
        usleep(20 * 1000);  /* allow conversion */

        if (reg_read16(fd, SI1182_REG_ALS_DATA0, als) < 0) {
            usleep(10 * 1000);
            continue;
        }

        /* Force a new PS1 measurement */
        if (reg_write(fd, SI1182_REG_COMMAND, SI1182_CMD_PS_FORCE) < 0) {
            usleep(10 * 1000);
            continue;
        }
        usleep(20 * 1000);

        if (reg_read16(fd, SI1182_REG_PS1_DATA0, ps) < 0) {
            usleep(10 * 1000);
            continue;
        }

        return 0;  /* success */
    }

    fprintf(stderr, "Sensor read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als, uint16_t ps)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, ALS: %u, PS: %u\n", ts, als, ps);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t als = 0, ps = 0;

        if (read_sensor(g_i2c_fd, &als, &ps) == 0) {
            log_data(g_log, als, ps);
        } else {
            fprintf(stderr, "Skipping sample due to read failure.\n");
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 50)
            usleep(50 * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

