/*
 * ICU-20201 Ultrasonic ToF Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * LED:    GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    ./tof_monitor [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x04          /* ICU-20201 default I2C address */
#define WHO_AM_I_REG         0x00
#define WHO_AM_I_VAL         0x0D          /* Expected device ID */
#define DISTANCE_REG         0x02
#define LED_GPIO             17
#define LOG_FILE             "tof_log.txt"
#define POLL_INTERVAL_US     50000         /* 50 ms */
#define MAX_RETRIES          3

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Forward Declarations ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance(uint16_t *distance_mm);
static void control_led(int below_threshold);
static void log_data(uint16_t distance_mm);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- I2C Init -------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
