/*
 * Intrusion detection system using Omron B5L-LD50-07050 3D TOF sensor.
 *
 * Wiring (Raspberry Pi Zero W):
 *   B5L SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   B5L SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   B5L VDD  -> 3.3 V
 *   B5L GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion intrusion.c
 * Run:    ./intrusion
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_I2C_ADDR   0x20          /* B5L default I2C address */
#define LOG_FILE       "intrusion_log.txt"
#define THRESHOLD_MM   1000          /* 1 m threshold */
#define SAMPLES        10
#define SAMPLE_DELAY_US 100000       /* 100 ms between samples */
#define MEASURE_DELAY_US 10000       /* 10 ms between request and read */
#define RESPONSE_LEN   15
#define HEADER_VALUE   0x01          /* Expected header byte */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Send a 4-byte command frame to the B5L.                            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int b5l_send_command(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 15-byte response from the B5L.                             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int b5l_read_response(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Request a measurement and parse the 16-bit big-endian distance    */
/* from bytes 11 and 12 of the 15-byte response.                       */
/* Returns distance in mm on success, -1 on error.                    */
/* ------------------------------------------------------------------ */
static int b5l_get_distance(int fd)
{
    uint8_t cmd[4] = {0x01, 0x02, 0x03, 0x04};
    uint8_t resp[RESPONSE_LEN];

    if (b5l_send_command(fd, cmd, sizeof(cmd)) != 0)
        return -1;

    usleep(MEASURE_DELAY_US);

    if (b5l_read_response(fd, resp, sizeof(resp)) != 0)
        return -1;

    if (resp[0] != HEADER_VALUE) {
        fprintf(stderr, "B5L header mismatch: got 0x%02X, expected 0x%02X\n",
                resp[0], HEADER_VALUE);
        return -1;
    }

    int distance = ((resp[11] << 8) | resp[12]) & 0xFFFF;
    return distance;
}

/* ------------------------------------------------------------------ */
static double calculate_average_distance(const int *distances, int n)
{
    double sum = 0.0;
    for (int i = 0; i < n; i++)
        sum += distances[i];
    return sum / (double)n;
}

/* ------------------------------------------------------------------ */
static void log_intrusion(double avg_distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Average Distance: %.2f mm\n", timestamp, avg_distance);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                B5L_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distances[SAMPLES];
        int error = 0;

        for (int i = 0; i < SAMPLES && g_running; i++) {
            int d = b5l_get_distance(g_i2c_fd);
            if (d < 0) {
                fprintf(stderr, "Sensor read error (sample %d)\n", i);
                error = 1;
                break;
            }
            distances[i] = d;
            usleep(SAMPLE_DELAY_US);
        }

        if (error)
            continue;

        double avg = calculate_average_distance(distances, SAMPLES);

        if (avg < THRESHOLD_MM) {
            printf("Intrusion detected! Average distance: %.2f mm\n", avg);
            log_intrusion(avg);
        }

        usleep(1000000); /* 1 s between cycles */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

