/*
 * VL53L0X Time-of-Flight distance reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Wiring: VL53L0X SDA -> GPIO2, SCL -> GPIO3, VDD -> 3V3, GND -> GND
 *
 * Build: gcc -O2 -Wall -o vl53l0x_reader vl53l0x_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l0x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- VL53L0X register definitions (16-bit addresses, 8-bit registers) ---- */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID       0x010F
#define VL53L0X_REG_SYSTEM_MODE_START             0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS       0x0044
#define VL53L0X_REG_RESULT_DISTANCE_MM            0x0096

#define VL53L0X_MODEL_ID_EXPECTED                 0xEA
#define VL53L0X_SYSTEM_MODE_START_SINGLE_SHOT     0x0001

#define I2C_BUS                                  1
#define POLL_TIMEOUT_MS                          100
#define LOOP_DELAY_MS                            500

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then a single byte value.          */
/* ------------------------------------------------------------------ */
static int vl53l0x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%04X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address, then read one byte.                */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_reg8(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(addr=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "i2cReadDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint8_t)data;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address, then read two bytes (little-endian).*/
/* ------------------------------------------------------------------ */
static int vl53l0x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(addr=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "i2cReadDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)((uint8_t)data[1] << 8) | (uint8_t)data[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Wait for the interrupt status to indicate a new sample is ready.    */
/* ------------------------------------------------------------------ */
static int wait_for_data(int handle)
{
    uint8_t status;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (vl53l0x_read_reg8(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS,
                              &status) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        gpioDelay(1000); /* 1 ms */
    }
    fprintf(stderr, "Timeout waiting for VL53L0X data ready\n");
    return -1;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, 0x00, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x00) failed: %s\n",
                I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence via model ID ---- */
    uint8_t model_id;
    if (vl53l0x_read_reg8(g_i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID,
                          &model_id) != 0) {
        fprintf(stderr, "Failed to read VL53L0X model ID (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr,
                "VL53L0X model ID mismatch: got 0x%02X, expected 0x%02X\n",
                model_id, VL53L0X_MODEL_ID_EXPECTED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);

    /* ---- Start a single-shot measurement ---- */
    if (vl53l0x_write_reg8(g_i2c_handle, VL53L0X_REG_SYSTEM_MODE_START,
                           VL53L0X_SYSTEM_MODE_START_SINGLE_SHOT) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        if (wait_for_data(g_i2c_handle) != 0) {
            if (!g_running) break;
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        uint16_t distance;
        if (vl53l0x_read_reg16(g_i2c_handle, VL53L0X_REG_RESULT_DISTANCE_MM,
                               &distance) != 0) {
            if (!g_running) break;
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        /* Clear interrupt so the next measurement can be detected */
        (void)vl53l0x_write_reg8(g_i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, 0x01);

        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];
        time(&rawtime);
        localtime_r(&rawtime, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        printf("%s Distance: %u mm\n", timestamp, distance);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

