code:
/*
 * Si1182 proximity sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 register definitions (per datasheet) ---- */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_KEY        0x07
#define SI1182_REG_MEAS_RATE0    0x08
#define SI1182_REG_MEAS_RATE1    0x09
#define SI1182_REG_PS_LED21      0x0F
#define SI1182_REG_PS1_DATA0     0x10
#define SI1182_REG_PS1_DATA1     0x11

#define SI1182_PART_ID_EXPECTED  0x82
#define SI1182_HW_KEY_VALUE     0x17

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
static int reg_write(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.  */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success.   */
static int reg_read16(int handle, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read(handle, reg_low, &lo) != 0)
        return -1;
    if (reg_read(handle, reg_low + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: verify part ID, write HW_KEY, configure     */
/* measurement rate, and set LED current.                             */
static int si1182_init(int handle)
{
    uint8_t part_id;

    /* --- Verify part ID (sensor-present / bus-open check) --- */
    if (reg_read(handle, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID – sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* --- Write HW_KEY (required for proper operation) --- */
    if (reg_write(handle, SI1182_REG_HW_KEY, SI1182_HW_KEY_VALUE) != 0)
        return -1;

    /* --- Configure measurement rate: 500 ms (0x000A) --- */
    if (reg_write(handle, SI1182_REG_MEAS_RATE0, 0x0A) != 0)
        return -1;
    if (reg_write(handle, SI1182_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    /* --- Set PS_LED21 current (LED1 drive current) --- */
    if (reg_write(handle, SI1182_REG_PS_LED21, 0x0F) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 (GPIO2/GPIO3) --- */
    g_i2c_handle = i2cOpen(1, 0x40, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x40) failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Initialise sensor --- */
    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1182 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Si1182 ready. Reading proximity every 500 ms. Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t prox;
        if (reg_read16(g_i2c_handle, SI1182_REG_PS1_DATA0, &prox) != 0) {
            fprintf(stderr, "[WARN] Failed to read proximity data; continuing.\n");
        } else {
            printf("Proximity: %u\n", prox);
        }
        gpioDelay(500000); /* 500 ms */
    }

    /* --- Clean shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

