/*
 * OPT3101 Time-of-Flight Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3101 SDA -> GPIO2 (I2C bus 1 SDA)
 *   OPT3101 SCL -> GPIO3 (I2C bus 1 SCL)
 *   OPT3101 VDD -> 3.3 V
 *   OPT3101 GND -> GND
 *
 * Build: gcc -O2 -Wall -o opt3101_reader opt3101_reader.c -lpigpio -lrt
 * Run:   sudo ./opt3101_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3101 Register Map (16-bit addresses, big-endian on the bus) ---- */
#define OPT3101_REG_DEVICE_ID       0x0000
#define OPT3101_REG_SYSTEM_CONFIG  0x0001
#define OPT3101_REG_RANGE_CONFIG   0x0002
#define OPT3101_REG_RANGE_STATUS   0x0003
#define OPT3101_REG_DATA_OUT_0     0x0004
#define OPT3101_REG_DATA_OUT_1     0x0005
#define OPT3101_REG_DATA_OUT_2     0x0006
#define OPT3101_REG_DATA_OUT_3     0x0007
#define OPT3101_REG_AMBIENT_0      0x0008
#define OPT3101_REG_AMBIENT_1      0x0009
#define OPT3101_REG_AMBIENT_2      0x000A
#define OPT3101_REG_AMBIENT_3      0x000B
#define OPT3101_REG_ERROR_FLAGS    0x000C

#define OPT3101_DEVICE_ID          0x3101
#define OPT3101_EXPECTED_ID        0x3101

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define POLL_DELAY_US  500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit OPT3101 register.
 * pigpio i2cWriteWordData sends the 16-bit value as [reg][data_hi][data_lo]
 * on the bus, which matches the OPT3101's big-endian register layout. */
static int opt3101_write_reg(int handle, uint16_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteWordData(reg=0x%04X, val=0x%04X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit OPT3101 register. */
static int opt3101_read_reg(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%04X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
static int opt3101_init(int handle)
{
    uint16_t device_id = 0;

    /* Verify device identity */
    if (opt3101_read_reg(handle, OPT3101_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (device_id != OPT3101_EXPECTED_ID) {
        fprintf(stderr,
                "[ERROR] Unexpected DEVICE_ID: 0x%04X (expected 0x%04X).\n",
                device_id, OPT3101_EXPECTED_ID);
        return -1;
    }
    printf("[INFO] OPT3101 detected (DEVICE_ID = 0x%04X).\n", device_id);

    /*
     * Minimal configuration:
     *   SYSTEM_CONFIG: enable the device (bit 0 = 1)
     *   RANGE_CONFIG:  enable channel 0 (bit 0 = 1), range = 1 m (bits 4-7 = 0x00)
     *                -> 0x0001
     */
    if (opt3101_write_reg(handle, OPT3101_REG_SYSTEM_CONFIG, 0x0001) != 0)
        return -1;
    if (opt3101_write_reg(handle, OPT3101_REG_RANGE_CONFIG, 0x0001) != 0)
        return -1;

    /* Allow the sensor to settle after configuration */
    gpioDelay(10000); /* 10 ms */

    printf("[INFO] OPT3101 initialized.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
static int opt3101_read_data(int handle, uint16_t *distance,
                             uint16_t *ambient, uint16_t *error_flags)
{
    uint16_t status = 0;

    /* Check RANGE_STATUS for data-ready and error flags */
    if (opt3101_read_reg(handle, OPT3101_REG_RANGE_STATUS, &status) != 0)
        return -1;

    if (status & 0x0001) {
        /* Data ready — read channel 0 */
        if (opt3101_read_reg(handle, OPT3101_REG_DATA_OUT_0, distance) != 0)
            return -1;

        /* Read ambient light (channel 0) */
        if (opt3101_read_reg(handle, OPT3101_REG_AMBIENT_0, ambient) != 0)
            return -1;

        /* Read error flags */
        if (opt3101_read_reg(handle, OPT3101_REG_ERROR_FLAGS, error_flags) != 0)
            return -1;
    } else {
        /* No data ready yet — return zeros and let caller decide */
        *distance = 0;
        *ambient  = 0;
        *error_flags = 0;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t distance, uint16_t ambient, uint16_t error_flags)
{
    printf("Distance: %5u mm | Ambient: %5u | Error Flags: 0x%04X\n",
           distance, ambient, error_flags);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x40 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (opt3101_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3101 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Logging every %d ms. Press Ctrl+C to stop.\n", POLL_DELAY_US / 1000);

    /* Main polling loop */
    while (g_running) {
        uint16_t distance = 0, ambient = 0, error_flags = 0;

        if (opt3101_read_data(g_i2c_handle, &distance, &ambient, &error_flags) == 0) {
            log_data(distance, ambient, error_flags);
        } else {
            fprintf(stderr, "[ERROR] Failed to read sensor data.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(POLL_DELAY_US / 10);
        }
    }

    /* ---- Graceful cleanup ---- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

