/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM) via 1 kOhm resistor to 3.3 V logic
 *   HC-SR04 VCC -> 5 V (external supply recommended; sensor is 5 V)
 *   HC-SR04 GND -> GND
 *
 * The HC-SR04 ECHO pin is 5 V and the Pi GPIO is only 3.3 V tolerant.
 * A 1 kOhm resistor on the echo line ensures the signal is within
 * safe limits and prevents damage to the Pi.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   200000   /* 200 ms */
#define MAX_DISTANCE_US   38000    /* ~5 m round-trip */
#define READ_INTERVAL_S   1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Issue a 10 us trigger pulse.
 * Returns 0 on success, -1 on failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

/*
 * Measure the echo pulse duration in microseconds.
 * Returns the duration in us, or -1 on timeout / error.
 */
static long measure_echo(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo rising edge timeout\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo falling edge timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Convert pulse duration (us) to distance (cm).
 * Returns -1.0 for invalid readings.
 */
static float calculate_distance(long pulse_duration)
{
    if (pulse_duration <= 0) {
        fprintf(stderr, "Error: invalid pulse duration %ld us\n", pulse_duration);
        return -1.0f;
    }
    if (pulse_duration > MAX_DISTANCE_US) {
        fprintf(stderr, "Error: pulse duration %ld us exceeds max range\n", pulse_duration);
        return -1.0f;
    }

    /* Speed of sound ~343 m/s => 0.0343 cm/us; round trip / 2 */
    return (float)pulse_duration * 0.0343f / 2.0f;
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(500000); /* 500 ms settle */

    while (g_running) {
        if (trigger_sensor() != 0) {
            gpioDelay(READ_INTERVAL_S * 1000000);
            continue;
        }

        long pulse_duration = measure_echo();
        if (pulse_duration < 0) {
            gpioDelay(READ_INTERVAL_S * 1000000);
            continue;
        }

        float distance = calculate_distance(pulse_duration);
        if (distance < 0.0f) {
            gpioDelay(READ_INTERVAL_S * 1000000);
            continue;
        }

        log_distance(distance);
        gpioDelay(READ_INTERVAL_S * 1000000);
    }

    /* Graceful shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

