/*
 * Raspberry Pi 3 Model B+ — IWR1443 mmWave radar intrusion detector
 *
 * Reads 8-byte magic-word headers + 128 bytes of range-profile data
 * over /dev/serial0 (UART4), detects targets within 1.0 m, logs to
 * intrusion_log.csv, and pulses GPIO 17 (BCM) for 2 s on detection.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_intrusion radar_intrusion.c
 * Run:    ./radar_intrusion   (requires r/w access to /dev/serial0)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>

#define UART_DEVICE      "/dev/serial0"
#define GPIO_PIN          17          /* BCM pin for alert LED */
#define DISTANCE_THRESHOLD 1.0f       /* meters */
#define ALERT_DURATION_S  2           /* seconds */
#define LOG_FILE          "intrusion_log.csv"

/* IWR1443 magic word (8 bytes, big-endian on the wire) */
static const uint8_t MAGIC_WORD[8] = {
    0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static int  g_gpio_pin = GPIO_PIN;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag  = 0;
    tty.c_lflag  = 0;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 10;   /* 1 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
static int init_gpio(int pin)
{
    int ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise failed: %d\n", ret);
        return -1;
    }

    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", pin);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", pin);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_intrusion(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, distance);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void activate_alert(int pin, int duration_s)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", pin);
        return;
    }

    /* Sleep in 100 ms slices so we can respond to signals promptly */
    for (int i = 0; i < duration_s * 10 && g_running; i++)
        usleep(100 * 1000);

    if (gpioWrite(pin, 0) != 0)
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", pin);
}

/* ------------------------------------------------------------------ */
/*
 * Read exactly `len` bytes from the UART within `timeout_ms` ms.
 * Returns 0 on success, -1 on timeout / error.
 */
static int read_exact(int fd, uint8_t *buf, size_t len, int timeout_ms)
{
    size_t got = 0;
    while (got < len && g_running) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv = {
            .tv_sec  = timeout_ms / 1000,
            .tv_usec = (timeout_ms % 1000) * 1000
        };

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select: %s\n", strerror(errno));
            return -1;
        }
        if (rv == 0) {
            fprintf(stderr, "UART read timeout (%zu/%zu bytes)\n",
                    got, len);
            return -1;
        }

        ssize_t n = read(fd, buf + got, len - got);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed by peer\n");
            return -1;
        }
        got += (size_t)n;
    }
    return (got == len) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0)
        return EXIT_FAILURE;

    if (init_gpio(GPIO_PIN) != 0) {
        close(g_uart_fd);
        return EXIT_FAILURE;
    }

    printf("Radar intrusion detection started (UART=%s, GPIO%d, threshold=%.1f m)\n",
           UART_DEVICE, GPIO_PIN, DISTANCE_THRESHOLD);

    while (g_running) {
        uint8_t hdr[8];
        if (read_exact(g_uart_fd, hdr, sizeof(hdr), 1000) != 0) {
            if (!g_running) break;
            continue;
        }

        if (memcmp(hdr, MAGIC_WORD, sizeof(hdr)) != 0) {
            fprintf(stderr, "Magic word mismatch — resyncing\n");
            continue;
        }

        /*
         * Frame layout: 8-byte magic + 128 bytes = 160 bytes total.
         * The 128 bytes contain 64 little-endian 16-bit distance bins.
         */
        uint8_t frame[160];
        memcpy(frame, hdr, sizeof(hdr));
        if (read_exact(g_uart_fd, frame + sizeof(hdr),
                       sizeof(frame) - sizeof(hdr), 1000) != 0) {
            if (!g_running) break;
            continue;
        }

        const uint16_t *bins =
            (const uint16_t *)(frame + sizeof(hdr));

        bool intrusion = false;
        for (int i = 0; i < 64; i++) {
            float distance = (float)bins[i] * 0.0436f;  /* m */
            if (distance > 0.0f && distance <= DISTANCE_THRESHOLD) {
                intrusion = true;
                printf("Intrusion detected! Distance: %.2f m\n", distance);
                break;
            }
        }

        if (intrusion) {
            log_intrusion(DISTANCE_THRESHOLD);
            activate_alert(GPIO_PIN, ALERT_DURATION_S);
        }
    }

    /* Cleanup */
    if (g_uart_fd >= 0)
        close(g_uart_fd);
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();

    printf("Radar intrusion detection stopped.\n");
    return EXIT_SUCCESS;
}

