/*
 * obstacle_detection.c — Raspberry Pi 4 Model B
 *
 * Reads an E18-D80NK IR obstacle sensor on GPIO 17 (active-low) and drives
 * a buzzer on GPIO 18 (active-high) while logging state transitions to
 * obstacle_log.txt.  Uses pigpio for GPIO access.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_detection obstacle_detection.c -lpigpio -lrt
 * Run:    sudo ./obstacle_detection
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17          /* E18-D80NK OUT  (active-low)  */
#define BUZZER_PIN 18          /* Buzzer +       (active-high) */
#define LOG_FILE    "obstacle_log.txt"
#define POLL_US     100000      /* 100 ms               */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int obstacle_detected)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(log_file)");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s  Obstacle %s\n", ts,
            obstacle_detected ? "DETECTED" : "clear");
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_PIN) failed\n");
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN) failed\n");
        return -1;
    }

    /* Start with buzzer off. */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN, 0) failed\n");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure buzzer is off before releasing lines. */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int prev_state = -1;   /* Force initial log. */

    while (g_running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(SENSOR_PIN) failed\n");
            break;
        }

        /* E18-D80NK is active-low: 0 => obstacle detected. */
        int obstacle_detected = (level == 0);

        if (gpioWrite(BUZZER_PIN, obstacle_detected ? 1 : 0) != 0) {
            fprintf(stderr, "gpioWrite(BUZZER_PIN) failed\n");
            break;
        }

        if (obstacle_detected != prev_state) {
            log_event(obstacle_detected);
            prev_state = obstacle_detected;
        }

        gpioDelay(POLL_US);   /* 100 ms */
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

