/*
 * Raspberry Pi 4 Model B — TDK Chirp ICU-20201 Ultrasonic ToF Sensor
 *
 * I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Alert output on BCM GPIO 17 (physical pin 11)
 *
 * Reads distance every 100 ms, logs to distance_log.txt, and asserts
 * BCM 17 when distance < 10.0 cm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_alert icu20201_alert.c -lpigpio -lrt
 * Run:    sudo ./icu20201_alert
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define I2C_ADDR             0x40          /* ICU-20201 default I2C address */
#define DISTANCE_THRESHOLD   10.0f         /* cm */
#define ALERT_GPIO           17            /* BCM 17, physical pin 11 */
#define LOG_FILE             "distance_log.txt"
#define POLL_DELAY_US        100000        /* 100 ms */

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE_MSB     0x00
#define REG_DISTANCE_LSB     0x01
#define REG_CONFIG_MSB       0x02
#define REG_CONFIG_LSB       0x03
#define REG_MEASUREMENT_CTRL 0x04

/*
 * Measurement control register bits.
 *   bit 0 = START_MEAS (1 = start a single-shot measurement)
 *   bit 1 = MODE (0 = continuous, 1 = single-shot)
 *   bit 2 = INT_EN (1 = enable measurement-complete interrupt)
 *   bits 3-7 = reserved
 */
#define CTRL_START_MEAS      0x01
#define CTRL_MODE_SINGLE     0x02
#define CTRL_INT_EN          0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_gpio_pin   = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address.                 */
/* ICU-20201 expects [reg_addr_MSB, reg_addr_LSB, data_MSB, data_LSB].*/
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint8_t reg_msb, uint8_t reg_lsb,
                           uint16_t value)
{
    uint8_t buf[4];
    buf[0] = reg_msb;
    buf[1] = reg_lsb;
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (i2cWriteDevice(handle, (char *)buf, 4) != 4) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for reg 0x%02X%02X\n",
                reg_msb, reg_lsb);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register address.                */
/* ICU-20201 expects [reg_addr_MSB, reg_addr_LSB].                    */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint8_t reg_msb, uint8_t reg_lsb,
                          uint16_t *out)
{
    uint8_t buf[2];
    buf[0] = reg_msb;
    buf[1] = reg_lsb;

    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed for 0x%02X%02X\n",
                reg_msb, reg_lsb);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed for reg 0x%02X%02X\n",
                reg_msb, reg_lsb);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Probe: try a benign register read to confirm the sensor is present. */
    uint16_t cfg;
    if (i2c_read_reg16(g_i2c_handle, REG_CONFIG_MSB, REG_CONFIG_LSB, &cfg) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X on bus %d\n",
                I2C_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /*
     * Configure: continuous measurement mode, interrupt enabled.
     *   CTRL_MODE_SINGLE | CTRL_INT_EN = 0x06
     */
    if (i2c_write_reg16(g_i2c_handle,
                        REG_MEASUREMENT_CTRL & 0xFF,
                        (REG_MEASUREMENT_CTRL >> 8) & 0xFF,
                        CTRL_MODE_SINGLE | CTRL_INT_EN) != 0) {
        fprintf(stderr, "[ERROR] Failed to configure measurement control\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance(float *distance_cm)
{
    /* Trigger a single-shot measurement. */
    if (i2c_write_reg16(g_i2c_handle,
                        REG_MEASUREMENT_CTRL & 0xFF,
                        (REG_MEASUREMENT_CTRL >> 8) & 0xFF,
                        CTRL_START_MEAS | CTRL_MODE_SINGLE | CTRL_INT_EN) != 0) {
        return -1;
    }

    /*
     * The ICU-20201 measurement takes ~10 ms (typ).  Poll the interrupt
     * bit until it reads 1 (measurement complete).
     */
    uint16_t ctrl;
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg16(g_i2c_handle,
                           REG_MEASUREMENT_CTRL & 0xFF,
                           (REG_MEASUREMENT_CTRL >> 8) & 0xFF,
                           &ctrl) != 0) {
            return -1;
        }
        if (ctrl & 0x01) {
            break;
        }
        gpioDelay(5000); /* 5 ms */
    }

    if (!(ctrl & 0x01)) {
        fprintf(stderr, "[ERROR] Measurement timeout\n");
        return -1;
    }

    /* Read the 16-bit distance result. */
    uint16_t dist;
    if (i2c_read_reg16(g_i2c_handle,
                       REG_DISTANCE_MSB, REG_DISTANCE_LSB, &dist) != 0) {
        return -1;
    }

    /*
     * ICU-20201 distance is in millimetres.  Convert to cm.
     * NOTE: The exact scaling factor depends on the configured range
     *       and the sensor's internal clock.  Here we assume 1 LSB = 1 mm.
     */
    *distance_cm = (float)dist / 10.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, distance_cm) < 0) {
        perror("[ERROR] fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_gpio_pin >= 0) {
        gpioWrite(g_gpio_pin, 0);
        gpioSetMode(g_gpio_pin, PI_INPUT);
        g_gpio_pin = -1;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, OUTPUT) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);
    g_gpio_pin = ALERT_GPIO;

    printf("ICU-20201 monitoring started.  Threshold = %.1f cm.  Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    while (g_running) {
        float distance;
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);

            if (log_distance(distance) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
            }

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(ALERT_GPIO, 1);
                printf("[ALERT] Distance below threshold — GPIO %d asserted\n",
                       ALERT_GPIO);
            } else {
                gpioWrite(ALERT_GPIO, 0);
            }
        } else {
            fprintf(stderr, "[WARN] Read failed — continuing\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

