/*
 * Parking Assistance System using VL53L1X ToF Sensor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: STMicroelectronics VL53L1X (I2C address 0x29)
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c \
 *              -lpigpio -lrt
 * Run:    sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define LOG_FILE             "distance_log.csv"
#define POLL_INTERVAL_US     100000   /* 100 ms */

/* Distance thresholds (mm) */
#define STOP_DISTANCE        300
#define APPROACH_DISTANCE    600
#define SLOW_DISTANCE        1200

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward Declarations ------------------------ */
static int  init_sensor(void);
static int  read_distance(uint16_t *distance_mm);
static void log_distance(uint16_t distance_mm);
static void check_distance(uint16_t distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the VL53L1X sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode); create header if file is new/empty */
    g_log_file = fopen(LOG_FILE, "a+");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long fsize = ftell(g_log_file);
        if (fsize == 0) {
            fprintf(g_log_file, "timestamp,distance_mm\n");
            fflush(g_log_file);
        }
    } else {
        perror("fseek failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (read_distance(&distance_mm) == 0) {
            log_distance(distance_mm);
            check_distance(distance_mm);
        } else {
            fprintf(stderr, "Warning: failed to read distance.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Sensor Operations --------------------------- */

/*
 * Initialise the VL53L1X sensor.
 * Returns 0 on success, -1 on failure.
 */
static int init_sensor(void)
{
    /*
     * Simplified initialisation sequence (full register map is extensive).
     * The VL53L1X requires a sequence of register writes to configure timing,
     * ranging, and power modes.  Below we perform a minimal set to bring
     * the sensor into a ranging state.
     */

    /*
     * 0x88 (SYSTEM_INTERRUPT_CLEAR) <- 0x01 : clear any pending interrupt
     * 0x80 (SYSTEM_MODE_START)    <- 0x00 : stop ranging (required before config)
     * 0x80 (SYSTEM_MODE_START)    <- 0x01 : start ranging
     */
    uint8_t data[2];

    data[0] = 0x01;
    if (i2cWriteI2CBlockData(g_i2c_handle, 0x88, (char *)data, 1) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt.\n");
        return -1;
    }

    data[0] = 0x00;
    if (i2cWriteI2CBlockData(g_i2c_handle, 0x80, (char *)data, 1) < 0) {
        fprintf(stderr, "Error: failed to stop ranging.\n");
        return -1;
    }

    data[0] = 0x01;
    if (i2cWriteI2CBlockData(g_i2c_handle, 0x80, (char *)data, 1) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    /* Allow sensor to settle after configuration */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/*
 * Read the distance from the VL53L1X sensor.
 * Returns 0 on success, -1 on failure.
 */
static int read_distance(uint16_t *distance_mm)
{
    uint8_t data[2];

    /*
     * Read 2 bytes from 0x96 (RESULT_RANGE_STATUS) / 0x98 (RESULT_DISTANCE).
     * The sensor returns the latest ranging result in little-endian format.
     */
    if (i2cReadI2CBlockData(g_i2c_handle, 0x98, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: failed to read distance data.\n");
        return -1;
    }

    *distance_mm = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

/* --------------------------- Logging & Guidance -------------------------- */

/*
 * Append a timestamped distance reading to the CSV log file.
 */
static void log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(g_log_file);
}

/*
 * Print a parking guidance message based on the measured distance.
 */
static void check_distance(uint16_t distance_mm)
{
    if (distance_mm < STOP_DISTANCE) {
        printf("STOP\n");
    } else if (distance_mm < APPROACH_DISTANCE) {
        printf("APPROACH\n");
    } else if (distance_mm < SLOW_DISTANCE) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

/* --------------------------- Signal & Cleanup --------------------------- */

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Release all resources.
 */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

