     * The sensor returns the latest ranging result in little-endian format.
     */
    if (i2cReadI2CBlockData(g_i2c_handle, 0x98, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: failed to read distance data.\n");
        return -1;
    }

    *distance_mm = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

/* --------------------------- Logging & Guidance -------------------------- */

/*
 * Append a timestamped distance reading to the CSV log file.
 */
static void log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(g_log_file);
}

/*
 * Print a parking guidance message based on the measured distance.
 */
static void check_distance(uint16_t distance_mm)
{
    if (distance_mm < STOP_DISTANCE) {
        printf("STOP\n");
    } else if (distance_mm < APPROACH_DISTANCE) {
        printf("APPROACH\n");
    } else if (distance_mm < SLOW_DISTANCE) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

/* --------------------------- Signal & Cleanup --------------------------- */

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Release all resources.
 */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

