/*
 * CH201 ultrasonic ToF sensor reader with LED blink feedback.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: TDK InvenSense CH201 on I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * LED:    GPIO 18 (BCM), 330 ohm resistor to GND, 3.3 V logic
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define CH201_ADDR         0x25          /* CH201 default I2C address */
#define LED_GPIO           18
#define SAMPLE_PERIOD_US   100000        /* 100 ms between samples */
#define I2C_RETRY_COUNT    3
#define I2C_RETRY_DELAY_US 10000         /* 10 ms between retries */
#define MAX_DISTANCE_MM    400.0f        /* Calibration ceiling */
#define MIN_DISTANCE_MM    100.0f        /* Calibration floor */
#define MIN_BLINK_US       100000        /* 100 ms = slowest blink */
#define MAX_BLINK_US       10000         /* 10 ms  = fastest blink */

/* CH201 register addresses */
#define CH201_REG_RESULT   0x00
#define CH201_REG_CONFIG   0x01
#define CH201_REG_MODE     0x02
#define CH201_REG_INT_CFG  0x03
#define CH201_REG_INT_STS  0x04

/* CH201 config bits */
#define CH201_CFG_RANGE_100MM  0x0000  /* 100 mm range */
#define CH201_CFG_RANGE_400MM  0x0100  /* 400 mm range */
#define CH201_CFG_MODE_TOF     0x0001  /* Time-of-Flight mode */
#define CH201_CFG_INT_EN      0x0002  /* Enable interrupt */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_pigpio(void);
static int  init_i2c(void);
static int  read_ch201(float *distance_mm);
static uint32_t calculate_blink_period(float distance_mm);
static void log_data(float distance_mm, uint32_t blink_period_us);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- pigpio init ------------------------------- */
static int init_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- CH201 read -------------------------------- */
static int read_ch201(float *distance_mm)
{
    char buf[2];
    int  result;
    int  retries;

    /* Trigger a single measurement by writing 0x01 to MODE register */
    result = i2cWriteByteData(g_i2c_handle, CH201_REG_MODE, 0x01);
    if (result < 0) {
        fprintf(stderr, "[WARN] i2cWriteByteData(MODE) failed: %d\n", result);
        return -1;
    }

    /* Small delay for the measurement to complete */
    gpioDelay(2000);  /* 2 ms */

    /* Read 2 bytes from RESULT register */
    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadI2CBlockData(g_i2c_handle, CH201_REG_RESULT, buf, 2);
        if (result == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *distance_mm = (float)raw * 0.01f;  /* mm per raw unit */
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadI2CBlockData returned %d (expected 2), retries left: %d\n",
                result, retries - 1);
        gpioDelay(I2C_RETRY_DELAY_US);
        retries--;
    }

    fprintf(stderr, "[ERROR] Failed to read CH201 after %d retries\n", I2C_RETRY_COUNT);
    return -1;
}

/* ----------------------------- Blink period calc -------------------------- */
static uint32_t calculate_blink_period(float distance_mm)
{
    if (distance_mm < MIN_DISTANCE_MM) distance_mm = MIN_DISTANCE_MM;
    if (distance_mm > MAX_DISTANCE_MM) distance_mm = MAX_DISTANCE_MM;

    float normalized = (MAX_DISTANCE_MM - distance_mm) /
                       (MAX_DISTANCE_MM - MIN_DISTANCE_MM);

    uint32_t period = MIN_BLINK_US +
                      (uint32_t)(normalized * (MIN_BLINK_US - MAX_BLINK_US));

    return period;
}

/* ----------------------------- Data logger -------------------------------- */
static void log_data(float distance_mm, uint32_t blink_period_us)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("%s  Distance: %.2f mm  Blink: %u us\n", ts, distance_mm, blink_period_us);
    fflush(stdout);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Main sampling loop */
    while (g_running) {
        float distance_mm;

        if (read_ch201(&distance_mm) == 0) {
            uint32_t blink_period = calculate_blink_period(distance_mm);
            log_data(distance_mm, blink_period);

            /* One half-cycle per iteration: on -> off -> on -> ... */
            static bool led_on = false;
            gpioWrite(LED_GPIO, led_on ? 0 : 1);
            led_on = !led_on;

            /* Sleep for the blink period (interruptible by signals) */
            gpioDelay(blink_period);
        } else {
            /* Sensor read failed; back off briefly and retry */
            gpioDelay(500000);  /* 500 ms */
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

