    while (running) {
        int sensor_1_level = read_sensor(SENSOR_1_GPIO);
        int sensor_2_level = read_sensor(SENSOR_2_GPIO);

        if (sensor_1_level < 0 || sensor_2_level < 0) {
            fprintf(stderr, "Error reading sensor GPIOs, exiting.\n");
            break;
        }

        if (sensor_1_level != sensor_1_state) {
            sensor_1_debounce_count++;
            if (sensor_1_debounce_count >= DEBOUNCE_MS / (POLL_INTERVAL_US / 1000)) {
                if (sensor_1_level != sensor_1_last_state) {
                    if (log_event(1, sensor_1_level == 0 ? "DETECTED" : "CLEARED") != 0) {
                        fprintf(stderr, "Error logging event for sensor 1\n");
                    }
                    sensor_1_last_state = sensor_1_level;
                }
                sensor_1_debounce_count = 0;
            }
            sensor_1_state = sensor_1_level;
        }

        if (sensor_2_level != sensor_2_state) {
            sensor_2_debounce_count++;
