#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c‑dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define CH101_ADDR       0x44
#define MEAS_STATUS_REG  0x00
#define DISTANCE_REG     0x01
#define LOG_FILE         "distance_log.csv"
#define SAMPLE_PERIOD_MS 500
#define MEAS_TIMEOUT_MS  50

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int elapsed = 0;

    while (elapsed < MEAS_TIMEOUT_MS) {
        if (i2c_read_reg8(fd, MEAS_STATUS_REG, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
        elapsed++;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "CH101 measurement timeout (status=0x%02X)\n", status);
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg8(fd, DISTANCE_REG, &dist_buf[0]) < 0)
        return -1;
    if (i2c_read_reg8(fd, DISTANCE_REG + 1, &dist_buf[1]) < 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[1] << 8) | dist_buf[0];
    return 0;
}

static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("CH-101 distance logger started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        uint16_t distance = 0;
        if (ch101_read_distance(g_i2c_fd, &distance) == 0) {
            log_data(g_log_fp, distance);
            printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

