#define VL53L5CX_REG_SOFT_RESET 0x0000
#define VL53L5CX_REG_SYSTEM_MODE_START 0x0001
#define VL53L5CX_REG_ZONE_CONFIG 0x0002
#define VL53L5CX_REG_ZONE_DISTANCE 0x0004

#define VL53L5CX_SOFT_RESET_VALUE 0x00
#define VL53L5CX_START_MODE_VALUE 0x01
#define VL53L5CX_ZONE_CONFIG_VALUE 0x08

#define NUM_ZONES 64
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, int len) {
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg addr) error (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error (reg 0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd) {
    if (i2c_write_reg16(fd, VL53L5CX_REG_SOFT_RESET, VL53L5CX_SOFT_RESET_VALUE) < 0) {
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg16(fd, VL53L5CX_REG_ZONE_CONFIG, VL53L5CX_ZONE_CONFIG_VALUE) < 0) {
        return -1;
    }
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_MODE_START, VL53L5CX_START_MODE_VALUE) < 0) {
        return -1;
    }
    return 0;
}

static int read_zone_distances(int fd, uint16_t *distances) {
    uint8_t buf[NUM_ZONES];
    if (i2c_read_reg16(fd, VL53L5CX_REG_ZONE_DISTANCE, buf, NUM_ZONES) < 0) {
        return -1;
    }
    for (int i = 0; i < NUM_ZONES; i++) {
        distances[i] = (uint16_t)buf[i];
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (vl53l5cx_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t distances[NUM_ZONES];
    while (running) {
        if (read_zone_distances(i2c_fd, distances) == 0) {
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("Zone %d: %u mm\n", i, distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read zone distances.\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    close(i2c_fd);
    return 0;
}

