/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MLX75030 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MLX75030 VDD -> 3.3 V
 *   MLX75030 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030_reader mlx75030_reader.c -lpigpio -lrt
 * Run:    sudo ./mlx75030_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS        1
#define I2C_ADDR       0x04          /* MLX75030 default I2C address */
#define SAMPLE_PERIOD_US 100000      /* 100 ms between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000         /* 10 ms between retries */

/*
 * MLX75030 register map (representative subset; adjust if your datasheet
 * differs).  The MLX75030 is a 16-bit register device; the low byte
 * of the register address is written first, then the high byte.
 */
#define REG_DISTANCE_MSB  0x00
#define REG_DISTANCE_LSB  0x01
#define REG_STATUS        0x02
#define REG_CONFIG        0x03

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] I2C write to reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(handle, reg_buf, 1);
        if (rc != 0) {
            fprintf(stderr, "[WARN] I2C write (reg select 0x%02X) failed (attempt %d/%d, rc=%d)\n",
                    reg, attempt + 1, MAX_RETRIES, rc);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }

        char data_buf[1];
        rc = i2cReadDevice(handle, data_buf, 1);
        if (rc == 1 && data_buf[0] != 0) {
            *out = (uint8_t)data_buf[0];
            return 0;
        }
        fprintf(stderr, "[WARN] I2C read from reg 0x%02X failed (attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a 16-bit big-endian register pair (MSB at reg, LSB at reg+1).
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t msb = 0, lsb = 0;
    if (i2c_read_reg8(handle, reg, &msb) != 0)
        return -1;
    if (i2c_read_reg8(handle, reg + 1, &lsb) != 0)
        return -1;
    *out = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

/* ----------------------------- Sensor init ------------------------------- */
static int init_mlx75030(int handle)
{
    /*
     * Minimal configuration: clear any stale status, set power mode,
     * then verify the sensor responds.
     */
    if (i2c_write_reg8(handle, REG_STATUS, 0x00) != 0) {
        fprintf(stderr, "[ERROR] Failed to clear status register\n");
        return -1;
    }
    gpioDelay(1000);  /* allow register writes to settle */

    /*
     * Write a known configuration value to the CONFIG register.
     * The exact bits depend on your application; this is a safe
     * representative value.
     */
    if (i2c_write_reg8(handle, REG_CONFIG, 0x0003) != 0) {
        fprintf(stderr, "[ERROR] Failed to write CONFIG register\n");
        return -1;
    }
    gpioDelay(1000);

    /*
     * Read back the CONFIG register to confirm the sensor is present
     * and responding.
     */
    uint8_t cfg_readback = 0;
    if (i2c_read_reg8(handle, REG_CONFIG, &cfg_readback) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding (no ACK on CONFIG readback)\n");
        return -1;
    }
    if (cfg_readback != 0x03) {
        fprintf(stderr, "[WARN] CONFIG readback mismatch: wrote 0x03, got 0x%02X\n", cfg_readback);
        /* Non-fatal: continue anyway */
    }

    return 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d). "
                        "Sensor may be absent or bus not available.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (init_mlx75030(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] MLX75030 initialization failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 distance reader started.  Sampling every %d ms. "
           "Press Ctrl+C to stop.\n", SAMPLE_PERIOD_US / 1000);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance = 0;

        if (i2c_read_reg16(g_i2c_handle, REG_DISTANCE_MSB, &distance) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("[%ld.%03ld] Distance: %u mm\n",
                   (long)ts.tv_sec, ts.tv_nsec / 1000000, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "[ERROR] Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        /* Sleep for the remainder of the sample period (interruptible) */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

