#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L4CX_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L4CX_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint32_t len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l4cx_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to clear interrupt.\n");
        return -1;
    }
    return 0;
}

static int vl53l4cx_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L4CX_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* No new data available */
    }
    uint8_t dist_data[2] = {0};
    if (i2c_read_reg16(handle, VL53L4CX_REG_RESULT_DISTANCE, dist_data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }
    *distance = ((uint16_t)dist_data[0] << 8) | dist_data[1];
    if (i2c_write_reg16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }
    return 0;
}

