    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l4cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

