    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance sensor reading started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int ret = vl53l4cx_read_distance(g_i2c_handle, &distance);
        if (ret == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else if (ret < 0) {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        /* ret == 1 means no new data; skip this cycle silently */
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

