#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 500000

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(int handle, uint16_t reg, uint16_t val) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "Error: Failed to clear soft reset.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    return vl53l1x_write16(handle, VL53L1X_REG_RANGE_START, 0x01);
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint16_t status;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* No new data yet */
    }
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, distance) < 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        vl53l1x_write16(i2c_handle, VL53L1X_REG_RANGE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);

        if (ret == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: Failed to read distance from VL53L1X.\n");
        }
        /* ret == 1 means no new data yet; skip iteration */

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

