#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_ANGLE_DEG    -90.0f
#define MAX_ANGLE_DEG    90.0f

#define ECHO_TIMEOUT_US  50000  /* 50 ms */
#define LOOP_DELAY_US    200000 /* 200 ms */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Map a distance in cm to a servo angle in degrees.
 * 2 cm  -> -90 deg
 * 400 cm ->  90 deg
 * Returns 0 on success, -1 on invalid input.
 */
static int distance_to_angle(float distance_cm, float *out_angle)
{
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -1;
    }
    float angle = MIN_ANGLE_DEG +
                  (distance_cm - MIN_DISTANCE_CM) *
                  (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    *out_angle = angle;
    return 0;
}

/*
 * Read distance from the HC-SR04 sensor.
 * Returns distance in cm on success, or -1.0 on timeout / error.
 */
static float read_distance(void)
{
    uint32_t start_tick, end_tick;
    int level;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER_PIN low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER_PIN high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER_PIN low\n");
        return -1.0f;
    }

    /* Wait for echo to go high (start of pulse) */
    uint32_t wait_start = gpioTick();
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read ECHO_PIN\n");
            return -1.0f;
        }
        if ((int32_t)(gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0f;
        }
    } while (level == 0);
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    do {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read ECHO_PIN\n");
            return -1.0f;
        }
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0f;
        }
    } while (level == 1);
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    /* speed of sound ~343 m/s => 58 µs per cm; round trip, so divide by 2 */
    float distance = (float)pulse_width / 58.0f / 2.0f;
    return distance;
}

static void log_data(float distance_cm, float angle_deg)
{
