#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define MSG_QUEUE_KEY 1234
#define MSG_QUEUE_SIZE 10
#define POLL_TIMEOUT_MS 50

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int msg_queue_id = -1;

typedef struct {
    long mtype;
    int distance;
} distance_msg_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int init_vl53l1x(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t status;
    uint8_t dist_data[2];
    int timeout = 0;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) return -1;
    gpioDelay(1000);

    while (timeout < 100) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) return -1;
        if ((status & 0x01) != 0) break;
        gpioDelay(1000);
        timeout++;
    }

    if (timeout >= 100) return -1;

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_data, 2) != 2) return -1;

    *distance = (dist_data[0] << 8) | dist_data[1];

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) return -1;

    return 0;
}

static int log_distance(int distance) {
    distance_msg_t msg;
    msg.mtype = 1;
    msg.distance = distance;

    if (msgsnd(msg_queue_id, &msg, sizeof(distance_msg_t), IPC_NOWAIT) == -1) {
        perror("msgsnd");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (msg_queue_id >= 0) {
        msgctl(msg_queue_id, IPC_RMID, NULL);
        msg_queue_id = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        cleanup();
        return 1;
    }

    msg_queue_id = msgget(MSG_QUEUE_KEY, IPC_CREAT | 0666);
    if (msg_queue_id == -1) {
        perror("msgget");
        cleanup();
        return 1;
    }

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %d mm\n", distance);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Failed to log distance\n");
            }
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(POLL_TIMEOUT_MS * 1000);
    }

    cleanup();
    return 0;
}

