#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define BUZZER_THRESHOLD_CM      30.0
#define ECHO_TIMEOUT_US          30000   /* 30 ms — covers ~5 m round trip */
#define SAMPLE_INTERVAL_US       100000 /* 100 ms */
#define TRIGGER_PULSE_US         10

static volatile sig_atomic_t running = 1;
static volatile uint32_t    echo_start = 0;
static volatile uint32_t    echo_end   = 0;
static volatile int         echo_seen  = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * Compute the signed difference across the wraparound boundary.
 */
static inline uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start; /* unsigned subtraction handles wraparound */
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        echo_start = tick;
        echo_seen  = 0;
    } else if (level == 0) {
        echo_end = tick;
        echo_seen = 1;
    }
}

static int read_distance(float *distance_out)
{
    echo_start = 0;
    echo_end   = 0;
    echo_seen  = 0;

    trigger_sensor();

    /* Wait for the echo callback to record the end tick */
    for (int i = 0; i < 100 && !echo_seen; i++) {
        gpioDelay(1000); /* 1 ms */
    }

    if (!echo_seen) {
        fprintf(stderr, "Error: Echo timeout — sensor may be absent or not responding.\n");
        return -1;
    }

    uint32_t elapsed = tick_diff(echo_start, echo_end);
    if (elapsed == 0) {
        fprintf(stderr, "Error: Invalid echo duration (0 us).\n");
        return -1;
    }

    float distance = (float)elapsed * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    *distance_out = distance;
    return 0;
}

static void control_buzzer(float distance)
{
    if (distance < BUZZER_THRESHOLD_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

