        fprintf(stderr, "Error: Failed to set BUZZER_PIN (GPIO %d) as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register alert function on ECHO_PIN (GPIO %d).\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance;
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
            gpioWrite(BUZZER_PIN, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

