/*
 * Gate controller for Raspberry Pi Zero W
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 *   - SG90 servo on GPIO18 (BCM) with hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_controller gate_controller.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./gate_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29

#define SERVO_PIN            18
#define SERVO_OPEN_US        1500   /* 150 ms pulse -> gate open  */
#define SERVO_CLOSE_US       500    /* 50 ms  pulse -> gate closed */
#define SERVO_SETTLE_US      500000 /* 500 ms settle time          */

#define DISTANCE_THRESHOLD_MM 200   /* 20 cm in mm                 */
#define LOG_FILE             "gate_log.txt"
#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_US   100000 /* 100 ms                     */

/* VL53L1X register addresses */
#define VL53L1X_SOFT_RESET       0x0000
#define VL53L1X_SOFT_RESET_VAL   0x00
#define VL53L1X_BOOT_STATUS      0x0001
#define VL53L1X_BOOT_STATUS_VAL  0x00
#define VL53L1X_SYSTEM_START     0x0001
#define VL53L1X_SYSTEM_START_VAL 0x01
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE  0x0096

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void log_event(const char *msg);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void servo_set_angle(int angle_us);
static void gate_control(int distance_mm);
static void remote_control(const char *cmd);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_fp);
}

/* ----------------------------- I2C helpers -------------------------------- */

/*
 * Write a single byte to a 16-bit register address.
 * The VL53L1X expects the 16-bit register address as the first byte
 * followed by the data byte.
 */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t val)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, 3);
        if (rc == 0)
            return 0;
        log_event("I2C write failed, retrying...");
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    log_event("I2C write failed after retries.");
    return -1;
}

/*
 * Read `len` bytes from a 16-bit register address.
 * The VL53L1X expects the 16-bit register address as the first byte
 * followed by the data read.
 */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    uint8_t addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, (char *)addr_buf, 2) != 0) {
            log_event("I2C write (addr) failed, retrying...");
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(handle, (char *)buf, len) == (int)len)
            return 0;
        log_event("I2C read failed, retrying...");
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    log_event("I2C read failed after retries.");
    return -1;
}

/* ----------------------------- VL53L1X ----------------------------------- */

static int vl53l1x_init(int handle)
{
    /* Software reset */
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, VL53L1X_SOFT_RESET_VAL) != 0) {
        log_event("VL53L1X software reset failed.");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Wait for boot to complete (BOOT_STATUS == 0x00) */
    uint8_t boot_status = 0xFF;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(handle, VL53L1X_BOOT_STATUS, &boot_status, 1) != 0)
            return -1;
        if (boot_status == VL53L1X_BOOT_STATUS_VAL)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (boot_status != VL53L1X_BOOT_STATUS_VAL) {
        log_event("VL53L1X boot timeout.");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_START, VL53L1X_SYSTEM_START_VAL) != 0) {
        log_event("VL53L1X start ranging failed.");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    log_event("VL53L1X initialized successfully.");
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};

    /* Check if data is ready (bit 0 of RESULT_RANGE_STATUS) */
    if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status, 1) != 0)
        return -1;
    if (!(status & 0x01)) {
        log_event("VL53L1X data not ready.");
        return -1;
    }

    /* Read 16-bit distance */
    if (i2c_read_reg16(handle, VL53L1X_RESULT_DISTANCE, data, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ----------------------------- Servo -------------------------------------- */

static void servo_set_angle(int angle_us)
{
    if (angle_us < 500 || angle_us > 2500) {
        log_event("Invalid servo angle.");
        return;
    }

    if (gpioServo(SERVO_PIN, angle_us) != 0) {
        log_event("gpioServo failed.");
        return;
    }
    log_event("Servo angle set.");
}

/* ----------------------------- Gate control ------------------------------- */

static void gate_control(int distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD_MM) {
        log_event("Object detected within threshold. Opening gate.");
        servo_set_angle(SERVO_OPEN_US);
        log_event("Gate opened.");
    } else {
        log_event("Path clear. Closing gate.");
        servo_set_angle(SERVO_CLOSE_US);
        log_event("Gate closed.");
    }
}

/* ----------------------------- Remote control ----------------------------- */

static void remote_control(const char *cmd)
{
    if (strcmp(cmd, "open") == 0) {
        log_event("Remote command: open");
        servo_set_angle(SERVO_OPEN_US);
        log_event("Gate opened.");
    } else if (strcmp(cmd, "close") == 0) {
        log_event("Remote command: close");
        servo_set_angle(SERVO_CLOSE_US);
        log_event("Gate closed.");
    } else {
        log_event("Invalid remote command.");
    }
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        log_event("I2C bus open failed.");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        log_event("VL53L1X init failed.");
        i2cClose(g_i2c_handle);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate controller started.");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %u mm", distance_mm);
            log_event(msg);
            gate_control(distance_mm);
        } else {
            log_event("Failed to read distance. Retrying...");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    log_event("Shutting down.");
    servo_set_angle(SERVO_CLOSE_US);
    gpioDelay(SERVO_SETTLE_US);
    i2cClose(g_i2c_handle);
    fclose(g_log_fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

