/* ----------------------------- Servo -------------------------------------- */

static void servo_set_angle(int angle_us)
{
    if (angle_us < 500 || angle_us > 2500) {
        log_event("Invalid servo angle.");
        return;
    }

    if (gpioServo(SERVO_PIN, angle_us) != 0) {
        log_event("gpioServo failed.");
        return;
    }
    log_event("Servo angle set.");
}

/* ----------------------------- Gate control ------------------------------- */

static void gate_control(int distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD_MM) {
        log_event("Object detected within threshold. Opening gate.");
        servo_set_angle(SERVO_OPEN_US);
        log_event("Gate opened.");
    } else {
        log_event("Path clear. Closing gate.");
        servo_set_angle(SERVO_CLOSE_US);
        log_event("Gate closed.");
    }
}

/* ----------------------------- Remote control ----------------------------- */

static void remote_control(const char *cmd)
{
    if (strcmp(cmd, "open") == 0) {
        log_event("Remote command: open");
        servo_set_angle(SERVO_OPEN_US);
        log_event("Gate opened.");
    } else if (strcmp(cmd, "close") == 0) {
        log_event("Remote command: close");
        servo_set_angle(SERVO_CLOSE_US);
        log_event("Gate closed.");
    } else {
        log_event("Invalid remote command.");
    }
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        log_event("I2C bus open failed.");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        log_event("VL53L1X init failed.");
        i2cClose(g_i2c_handle);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate controller started.");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %u mm", distance_mm);
            log_event(msg);
            gate_control(distance_mm);
        } else {
            log_event("Failed to read distance. Retrying...");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    log_event("Shutting down.");
    servo_set_angle(SERVO_CLOSE_US);
    gpioDelay(SERVO_SETTLE_US);
    i2cClose(g_i2c_handle);
    fclose(g_log_fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

