/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO23 (BCM 23, physical pin 16)
 *   ECHO -> GPIO24 (BCM 24, physical pin 18)
 *
 * NOTE: The ECHO line is 5 V.  The Raspberry Pi GPIOs are 3.3 V.
 *       A voltage divider (e.g., 1 kΩ / 2 kΩ) or a logic-level
 *       shifter is REQUIRED to protect the Pi and to ensure
 *       the 5 V ECHO signal is interpreted correctly by the
 *       3.3 V-tolerant GPIO input.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23          /* BCM 23 (physical pin 16) */
#define ECHO_PIN         24          /* BCM 24 (physical pin 18) */

#define TRIGGER_PULSE_US  10          /* 10 µs trigger pulse width */
#define SAMPLE_PERIOD_US  200000      /* 200 ms between measurements (5 Hz) */
#define ECHO_TIMEOUT_US   60000       /* 60 ms max echo wait */
#define MIN_PULSE_US      100         /* noise floor — reject shorter pulses */
#define MAX_PULSE_US      30000       /* ~5 m round-trip ceiling */
#define SPEED_OF_SOUND    34300.0     /* cm/s at ~20 °C */

#define LOG_FILE_NAME     "distance_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/*
 * pigpio alert callbacks run in a dedicated thread.
 * pigpio guarantees the callback runs in a single-threaded context,
 * but we use volatile sig_atomic_t for the shared state.
 */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile bool     g_echo_seen = false;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static void  echo_callback(int gpio, int level, uint32_t tick, void *userdata);
static void  trigger_sensor(void);
static double calculate_distance(uint32_t pulse_us);
static void  log_distance(double distance);
static void  cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Echo Callback ------------------------------ */
/*
 * pigpio dispatches this callback on a dedicated thread.
 * We capture the tick and let the main loop compute the pulse width.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rise_tick  = tick;
        g_echo_seen  = true;
    } else if (level == 0 && g_rise_tick != 0) {
        g_fall_tick  = tick;
    }
}

/* ----------------------------- Trigger Pulse ------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIG high\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low\n");
    }
}

/* ----------------------------- Distance Calculation ----------------------- */
static double calculate_distance(uint32_t pulse_us)
{
    /* distance = (pulse_us * speed_of_sound) / 2 */
    return (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_distance(double distance)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("%s  Distance: %.2f cm\n", ts, distance);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s  Distance: %.2f cm\n", ts, distance);
        fflush(g_log_fp);
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    uint32_t rise_tick, fall_tick, pulse_us;
    double   distance;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN (BCM %d) as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN (BCM %d) as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: cannot set pull-down on ECHO_PIN.\n");
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: cannot initialize TRIGGER_PIN LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN (BCM %d).\n",
                ECHO_PIN);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install signal handlers.\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: BCM %d | ECHO: BCM %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Sampling every %d ms.  Press Ctrl+C to exit.\n\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main measurement loop --- */
    while (g_running) {
        g_echo_seen = false;
        g_rise_tick  = 0;
        g_fall_tick  = 0;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);  /* 100 µs poll */
            waited += 100;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout — no object detected or "
                            "sensor absent.\n");
        } else if (g_fall_tick == 0 || g_rise_tick == 0) {
            fprintf(stderr, "Warning: incomplete echo pulse captured.\n");
        } else {
            /* Handle 32-bit tick wraparound */
            pulse_us = g_fall_tick - g_rise_tick;

            if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
                fprintf(stderr, "Warning: pulse width %u µs out of range "
                                "(noise/timeout).\n", pulse_us);
            } else {
                distance = calculate_distance(pulse_us);
                log_distance(distance);
            }
        }

        /* Sleep for the remainder of the sample period */
        if (g_running) {
            gpioDelay(SAMPLE_PERIOD_US);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    gpioWrite(TRIGGER_PIN, 0);
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

