code:
/*
 * Smart Parking Gate Controller — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X ToF sensor on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *     Shutdown line -> GPIO23 (BCM)
 *     Interrupt line  -> GPIO24 (BCM)
 *   - Servo motor on GPIO18 (BCM) driven via hardware PWM
 *
 * Behaviour:
 *   - Opens gate when an object is within 50 cm.
 *   - Closes gate when the object is beyond 60 cm (hysteresis).
 *   - Logs every gate-state change with a timestamp and distance
 *     to parking_log.txt.
 *   - Clean shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define VL53L1X_ADDR        0x10
#define SERVO_PIN           18

#define DISTANCE_OPEN_CM    50
#define DISTANCE_CLOSE_CM   60

#define LOG_FILE            "parking_log.txt"
#define POLL_DELAY_US       100000   /* 100 ms */
#define SERVO_SETTLE_US     500000   /* 500 ms */

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START         0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK    0x0050
#define VL53L1X_REG_RESULT_DISTANCE_MM        0x0066

#define VL53L1X_MODEL_ID_EXPECTED             0xEA

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static int  i2c_write_reg16(int fd, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int fd);
static int  vl53l1x_read_distance_mm(int fd, uint16_t *distance_mm);
static void servo_set_angle(int angle);
static void log_event(int gate_open, uint16_t distance_mm);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, uint32_t len)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    ssize_t total = 0;
    while ((size_t)total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n <= 0) {
            fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                    reg, strerror(errno));
            return -1;
        }
        total += n;
    }
    return 0;
}

/* ----------------------------- VL53L1X ---------------------------------- */
static int vl53l1x_init(int fd)
{
    uint8_t model_id = 0;

    if (i2c_read_reg16(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Cannot read VL53L1X model ID — sensor absent or bus error.\n");
        return -1;
    }

    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr,
                "VL53L1X model ID mismatch: got 0x%02X, expected 0x%02X.\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Software reset */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms */

    /* Clear any pending interrupt */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;
    gpioDelay(2000);

    return 0;
}

static int vl53l1x_read_distance_mm(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2];
    uint32_t timeout = 100; /* 100 * 100 ms = 10 s */

    /* Start a single measurement */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    do {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0)
            return -1;
        gpioDelay(100000); /* 100 ms */
    } while ((status & 0x01) == 0 && --timeout > 0);

    if (timeout == 0) {
        fprintf(stderr, "VL53L1X measurement timeout.\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian) */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE_MM, dist_buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ----------------------------- Servo ------------------------------------- */
static void servo_set_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    /* 0° -> 500 µs, 180° -> 2500 µs pulse width */
    uint32_t pulse = 500 + (uint32_t)((angle * 2000) / 180);
    gpioServo(SERVO_PIN, pulse);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(int gate_open, uint16_t distance_mm)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log, "%s - Gate %s, Distance: %u mm\n",
            ts, gate_open ? "OPEN" : "CLOSED", distance_mm);
    fflush(g_log);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_write_reg16(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);   /* stop PWM */
    gpioTerminate();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    int gate_open = 0;
    uint16_t distance_mm;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open I2C bus --- */
    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", i2c_dev, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- init sensor --- */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- servo pin --- */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    servo_set_angle(90); /* centre */
    gpioDelay(SERVO_SETTLE_US);

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Parking Gate running. Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        if (vl53l1x_read_distance_mm(g_i2c_fd, &distance_mm) == 0) {
            int cm = distance_mm / 10;

            if (!gate_open && cm <= DISTANCE_OPEN_CM) {
                gate_open = 1;
                servo_set_angle(90);
                gpioDelay(SERVO_SETTLE_US);
                log_event(1, distance_mm);
                printf("Gate OPEN (distance: %d cm)\n", cm);
            } else if (gate_open && cm > DISTANCE_CLOSE_CM) {
                gate_open = 0;
                servo_set_angle(0);
                gpioDelay(SERVO_SETTLE_US);
                log_event(0, distance_mm);
                printf("Gate CLOSED (distance: %d cm)\n", cm);
            }
        } else {
            fprintf(stderr, "Sensor read error — closing gate for safety.\n");
            if (gate_open) {
                gate_open = 0;
                servo_set_angle(0);
                gpioDelay(SERVO_SETTLE_US);
                log_event(0, 0);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

