/* ---- ISO-8601 UTC timestamp helper ---- */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

/* ---- Log a gate event ---- */
static void log_gate_event(const char *event)
{
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    fprintf(g_log_file, "%s %s\n", ts, event);
    fflush(g_log_file);
}

/* ---- Write a 16-bit value to a 16-bit VL53L1X register ---- */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* ---- Read a 16-bit value from a 16-bit VL53L1X register ---- */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char wbuf[2];
    char rbuf[2];
    wbuf[0] = (reg >> 8) & 0xFF;
    wbuf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, wbuf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, rbuf, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
    return 0;
}

/* ---- Initialize the VL53L1X sensor ---- */
static int vl53l1x_init(int handle)
{
    uint16_t soft_reset_val = VL53L1X_SOFT_RESET_VALUE;

    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, soft_reset_val) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Read back to confirm */
    uint16_t readback;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_SOFT_RESET, &readback) < 0) {
        fprintf(stderr, "Error: failed to read back soft reset register\n");
        return -1;
    }
    if (readback != soft_reset_val) {
        fprintf(stderr, "Error: soft reset readback mismatch (0x%04X != 0x%04X)\n",
                readback, soft_reset_val);
        return -1;
