/* ---- Write a 16-bit value to a 16-bit VL53L1X register ---- */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* ---- Read a 16-bit value from a 16-bit VL53L1X register ---- */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char wbuf[2];
    char rbuf[2];
    wbuf[0] = (reg >> 8) & 0xFF;
    wbuf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, wbuf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, rbuf, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1];
    return 0;
}

