static int g_motor_state = 0;   /* 0 = stopped, 1 = forward, -1 = backward */

/* --------------------------- Forward declarations ------------------------ */
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- ISR ------------------------------------- */
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    vl53l1x_read_distance(g_i2c_handle, NULL);
}

/* ------------------------------- I2C helpers ----------------------------- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t val)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = val;

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, 3);
        if (rc == 3)
            return 0;
        fprintf(stderr, "I2C write to 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, 3, rc);
        gpioDelay(I2C_RETRY_BASE_MS * (1 << attempt));
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    uint8_t reg_buf[2];
    reg_buf[0] = (uint8_t)(reg >> 8);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)reg_buf, 2);
        if (rc != 2) {
            fprintf(stderr, "I2C write (addr) to 0x%04X failed (attempt %d/%d): rc=%d\n",
                    reg, attempt + 1, 3, rc);
            gpioDelay(I2C_RETRY_BASE_MS * (1 << attempt));
            continue;
        }
        rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "I2C read from 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, 3, rc);
        gpioDelay(I2C_RETRY_BASE_MS * (1 << attempt));
    }
    return -1;
}

/* ------------------------------- VL53L1X --------------------------------- */
static int vl53l1x_init(int handle)
{
    if (i2c_write_reg16(handle, VL53L1X_SOFT_RESET, VL53L1X_SOFT_RESET_VAL) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms */

    if (i2c_write_reg16(handle, VL53L1X_SYSTEM_START, VL53L1X_START_MEAS) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};

    /* Poll data-ready bit (max 1 s) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg16(handle, VL53L1X_RESULT_STATUS, &status, 1) != 0) {
            fprintf(stderr, "VL53L1X status poll failed\n");
            return -1;
        }
        if (status & VL53L1X_STATUS_DATA_READY)
            break;
        gpioDelay(1000);  /* 1 ms */
        if (i == POLL_TIMEOUT_MS - 1) {
            fprintf(stderr, "VL53L1X data-ready timeout\n");
            return -1;
        }
    }

    if (i2c_read_reg16(handle, VL53L1X_RESULT_RANGE, data, 2) != 0) {
        fprintf(stderr, "VL53L1X range read failed\n");
        return -1;
    }

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------- Motor ----------------------------------- */
static void motor_forward(void)
{
    if (g_motor_state != 1) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        g_motor_state = 1;
        printf("Motor: FORWARD\n");
    }
}

static void motor_backward(void)
{
    if (g_motor_state != -1) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        g_motor_state = -1;
        printf("Motor: BACKWARD\n");
    }
}

static void motor_stop(void)
{
    if (g_motor_state != 0) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        g_motor_state = 0;
        printf("Motor: STOP\n");
    }
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed – sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    motor_stop();

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Running. Press Ctrl+C to exit.\n");

    while (g_running)
        gpioDelay(100000);  /* 100 ms */

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

