/*
 * MPR121 Proximity-Driven LED Art Installation
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: MPR121 at 0x5D
 * LEDs:   GPIO17, GPIO18, GPIO27, GPIO22 (BCM)
 *
 * Build:  gcc -O2 -Wall -o mpr121_art mpr121_art.c -lpigpio -lrt
 * Run:    sudo ./mpr121_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5D

#define LED_PIN_0      17
#define LED_PIN_1      18
#define LED_PIN_2      27
#define LED_PIN_3      22

#define POLL_DELAY_US  50000   /* 50 ms */
#define RESET_DELAY_US 200000  /* 200 ms after soft reset */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG       0x5E
#define MPR121_SOFTRESET       0x80

/* --------------------------- Global state ------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------- Function prototypes ------------------------- */
static int  mpr121_write_reg(int fd, uint8_t reg, uint8_t val);
static int  mpr121_read_reg(int fd, uint8_t reg, uint8_t *val);
static int  mpr121_init(int fd);
static int  mpr121_read_touch(int fd, uint16_t *status);
static void led_set(uint8_t pattern);
static void log_event(uint16_t status);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------ I2C helpers ----------------------------- */
static int mpr121_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[I2C] write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- MPR121 initialization ----------------------- */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (mpr121_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(RESET_DELAY_US);

    /* Verify sensor presence by reading back ELECONFIG */
    uint8_t cfg = 0;
    if (mpr121_read_reg(fd, MPR121_ELECONFIG, &cfg) < 0)
        return -1;
    if (cfg == 0x00) {
        fprintf(stderr, "[MPR121] No ACK from sensor at 0x%02X (cfg=0x%02X) - sensor absent?\n",
                MPR121_ADDR, cfg);
        return -1;
    }

    /* Put all 12 electrodes into proximity (ELEPROX) mode */
    if (mpr121_write_reg(fd, MPR121_ELECONFIG, 0x0C) < 0)
        return -1;

    return 0;
}

/* --------------------------- Read touch status -------------------------- */
static int mpr121_read_touch(int fd, uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------ LED control ----------------------------- */
static void led_set(uint8_t pattern)
{
    gpioWrite(LED_PIN_0, (pattern >> 0) & 1);
    gpioWrite(LED_PIN_1, (pattern >> 1) & 1);
    gpioWrite(LED_PIN_2, (pattern >> 2) & 1);
    gpioWrite(LED_PIN_3, (pattern >> 3) & 1);
}

/* ------------------------------ Logging --------------------------------- */
static void log_event(uint16_t status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s - Proximity detected: 0x%04X\n", ts, status);
    fflush(g_log_fp);
}

/* ------------------------------ Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Release all four LED GPIOs */
    gpioWrite(LED_PIN_0, 0);
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioWrite(LED_PIN_3, 0);
    gpioTerminate();
}

/* ------------------------------ Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main --------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIOs as outputs, initially off */
    gpioSetMode(LED_PIN_0, PI_OUTPUT);
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);
    led_set(0x00);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("proximity_events.log", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 proximity art running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t status = 0;
        if (mpr121_read_touch(g_i2c_fd, &status) < 0) {
            fprintf(stderr, "I2C read error - continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (status != 0) {
            uint8_t pattern = (uint8_t)status;
            led_set(pattern);
            log_event(status);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

