/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   GPIO17 -> HC-SR04 TRIG (output)
 *   GPIO18 -> HC-SR04 ECHO (input)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define TRIGGER_SETTLE_US 5          /* 5 µs low settle before trigger  */
#define ECHO_TIMEOUT_US  30000       /* 30 ms max echo wait            */
#define LOOP_DELAY_US    1000000     /* 1 s between samples            */
#define MIN_DISTANCE_CM  2.0f        /* HC-SR04 minimum range           */
#define MAX_DISTANCE_CM  400.0f      /* HC-SR04 maximum range           */
#define SPEED_OF_SOUND_CM_PER_US 0.0343f /* 343 m/s in cm/µs            */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int trigger_set(int level)
{
    if (gpioWrite(TRIGGER_PIN, level) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, %d) failed\n", level);
        return -1;
    }
    return 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on read error.
 */
static long echo_pulse_us(void)
{
    uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;                 /* echo never rose – sensor absent? */
        }
    }

    uint32_t start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;                 /* echo stuck high – timeout       */
        }
    }

    return (long)(gpioTick() - start);
}

/* ------------------------------------------------------------------ */
/* Distance calculation                                                */
/* ------------------------------------------------------------------ */
static float distance_cm(long pulse_us)
{
    if (pulse_us < 0) return -1.0f;
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    if (!g_log) return;
    fprintf(g_log, "%s\n", msg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (trigger_set(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    /* ---- Open log file ---- */
    g_log = fopen("distance_log.txt", "a");
    if (!g_log) {
        perror("fopen(distance_log.txt)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /* Issue trigger pulse */
        if (trigger_set(1) < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (trigger_set(0) < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse = echo_pulse_us();
        float dist = distance_cm(pulse);

        if (dist < 0.0f) {
            log_line("ERROR: echo timeout or read error");
        } else if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "ERROR: distance %.2f cm out of range [%.0f-%.0f]",
                     dist, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            log_line(msg);
        } else {
            char msg[128];
            time_t now = time(NULL);
            struct tm tm_utc;
            gmtime_r(&now, &tm_utc);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
            snprintf(msg, sizeof(msg), "%s, Distance: %.2f cm", ts, dist);
            log_line(msg);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    trigger_set(0);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

