        fprintf(stderr, "gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (trigger_set(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    /* ---- Open log file ---- */
    g_log = fopen("distance_log.txt", "a");
    if (!g_log) {
        perror("fopen(distance_log.txt)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /* Issue trigger pulse */
        if (trigger_set(1) < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (trigger_set(0) < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse = echo_pulse_us();
        float dist = distance_cm(pulse);

        if (dist < 0.0f) {
            log_line("ERROR: echo timeout or read error");
        } else if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "ERROR: distance %.2f cm out of range [%.0f-%.0f]",
                     dist, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            log_line(msg);
        } else {
            char msg[128];
            time_t now = time(NULL);
            struct tm tm_utc;
            gmtime_r(&now, &tm_utc);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
            snprintf(msg, sizeof(msg), "%s, Distance: %.2f cm", ts, dist);
            log_line(msg);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    trigger_set(0);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

