/*
 * HC-SR04 Ultrasonic Distance Measurement (Raspberry Pi Zero W)
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN      17
#define ECHO_PIN      18

#define TRIG_PULSE_US  10          /* 10 us trigger pulse            */
#define SAMPLE_PERIOD_S 1          /* 1 Hz sampling rate            */
#define LOG_FILE       "distance_log.txt"

/* HC-SR04 timing limits (speed of sound ~343 m/s at 20 C) */
#define MIN_PULSE_US   58          /* ~1 cm  */
#define MAX_PULSE_US   25000       /* ~4 m   */

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                           */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_new_reading = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: captures ECHO rising and falling edges                         */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = true;
    } else if (level == 0 && g_echo_seen) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_new_reading = true;
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Compute (end - start) with 32-bit tick wrap-around.
 * pigpio ticks are 32-bit microseconds; subtraction wraps correctly
 * for the HC-SR04 range (max ~25 ms).
 */
static inline uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;
}

/*
 * Convert pulse width (µs) to distance (m).
 * speed_of_sound = 343 m/s = 0.0343 m/µs; round trip / 2.
 */
static inline float pulse_to_distance_m(uint32_t pulse_us)
{
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(FILE *fp, float distance_m)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Distance: %.2f m\n", timestamp, distance_m);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure TRIG pin --- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(5);  /* ensure clean low */

    /* --- Configure ECHO pin --- */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on both edges --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'.\n", LOG_FILE);
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to '%s'.\n",
           TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        /* Issue 10 us trigger pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIG_PULSE_US);
        gpioWrite(TRIG_PIN, 0);

        /* Wait for a complete reading (or until signal) */
        bool got_reading = false;
        for (int i = 0; i < 100 && g_running; i++) {
            gpioDelay(1000);  /* 1 ms */
            if (g_new_reading) {
                got_reading = true;
                break;
            }
        }

        if (!g_running) {
            break;
        }

        if (!got_reading) {
            fprintf(stderr, "Warning: no echo received within timeout.\n");
            continue;
        }

        /* Validate pulse width */
        uint32_t pulse_us = tick_diff(g_start_tick, g_end_tick);
        if (pulse_us == 0 || pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %u us out of range.\n", pulse_us);
            continue;
        }

        float distance_m = pulse_to_distance_m(pulse_us);
        log_distance(fp, distance_m);
        printf("Distance: %.2f m\n", distance_m);

        /* Reset flags for next cycle */
        g_new_reading = false;
        g_echo_seen  = false;
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);  /* disable ISR */
    gpioWrite(TRIG_PIN, 0);
    fclose(fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

