#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

static int vl53l1x_init(int handle) {
    if (i2cWriteByteData(handle, 0x00, 0x01) < 0) {
        log_message(LOG_ERR, "Failed to write to VL53L1X (init)");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle) {
    char data[2];
    if (i2cReadI2CBlockData(handle, 0x14, data, 2) != 2) {
        log_message(LOG_ERR, "Failed to read distance from VL53L1X");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set XSHUT pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(XSHUT_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        log_message(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "VL53L1X sensor initialised successfully");

    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            char message[128];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(LOG_INFO, message);
        }
        usleep(POLL_INTERVAL_US);
    }

    log_message(LOG_INFO, "Shutting down gracefully");
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

