#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 100000
#define MOVING_AVG_SIZE 5
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500

static volatile sig_atomic_t program_running = 1;
static volatile int new_pulse = 0;
static volatile uint32_t pulse_width = 0;
static volatile uint32_t last_echo_tick = 0;
static volatile uint32_t last_trigger_tick = 0;
static volatile uint32_t last_echo_start_tick = 0;
static volatile uint32_t last_echo_end_tick = 0;
static volatile int echo_state = 0;

static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        last_echo_start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        last_echo_end_tick = tick;
        uint32_t diff = tick - last_echo_start_tick;
        pulse_width = diff;
        new_pulse = 1;
        echo_state = 0;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) return -1.0;
    double distance = (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static double moving_average(double new_value, double *window, int window_size, int *index) {
    double sum = 0.0;
    for (int i = 0; i < window_size; i++) {
        sum += window[i];
    }
    double avg = sum / window_size;
    window[*index] = new_value;
    *index = (*index + 1) % window_size;
    return avg;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) return -1;
    int pulse_width = SERVO_MIN_US + (int)((double)angle / 180.0 * (SERVO_MAX_US - SERVO_MIN_US));
    return gpioServo(SERVO_PIN, pulse_width);
}

static void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance(cm),Angle(deg)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    double distance_window[MOVING_AVG_SIZE] = {0.0};
    int window_index = 0;

    while (program_running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        while (!new_pulse && program_running) {
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                new_pulse = 1;
                break;
            }
            gpioDelay(100);
        }

        if (!new_pulse) {
            log_data(-1.0, 90);
            set_servo_angle(90);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        new_pulse = 0;
        pulse_width = 0;

        double distance = calculate_distance(pulse_width);
        if (distance < 0) {
            log_data(-1.0, 90);
            set_servo_angle(90);
        } else {
            distance = moving_average(distance, distance_window, MOVING_AVG_SIZE, &window_index);
            int angle = (int)distance;
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;
            log_data(distance, angle);
            set_servo_angle(angle);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_servo_angle(0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

