#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define DEFAULT_THRESHOLD 1000
#define I2C_ADDR_DEFAULT 0x60

/* Si1102 register addresses (from datasheet) */
#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_HW_KEY  0x07
#define SI1102_REG_MEAS_RATE 0x08
#define SI1102_REG_PS_RATE 0x09
#define SI1102_REG_PS_LED21 0x0A
#define SI1102_REG_PS_LED3  0x0B
#define SI1102_REG_PS_ADC_MISC 0x0C
#define SI1102_REG_PS1_DATA0 0x10
#define SI1102_REG_PS1_DATA1 0x11
#define SI1102_REG_INT_CFG  0x12
#define SI1102_REG_INT_ENABLE 0x13
#define SI1102_REG_INT_STATUS 0x14
#define SI1102_REG_HW_KEY_VAL 0x07

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t int_flag = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int i2c_address = I2C_ADDR_DEFAULT;
static int proximity_threshold = DEFAULT_THRESHOLD;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int si1102_init(int handle) {
    int part_id = i2c_read_byte(handle, SI1102_REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_HW_KEY, SI1102_REG_HW_KEY_VAL) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_MEAS_RATE, 0x0A) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS_RATE, 0x0A) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS_LED21, 0x0F) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS_LED3, 0x0F) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_PS_ADC_MISC, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_INT_CFG, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, SI1102_REG_INT_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static void log_proximity_data(int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    const char *status = (proximity_value <= proximity_threshold) ? "SAFE" : "ALERT";

    if (log_file != NULL) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity_value, status);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void proximity_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int_flag = 1;
}

static void *proximity_thread(void *arg) {
    (void)arg;
    while (running) {
        if (int_flag) {
            int proximity_value = i2c_read_word(i2c_handle, SI1102_REG_PS1_DATA0);
            if (proximity_value >= 0) {
