    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                proximity_threshold = atoi(optarg);
                if (proximity_threshold <= 0) {
                    fprintf(stderr, "Invalid threshold value. Using default: %d\n", DEFAULT_THRESHOLD);
                    proximity_threshold = DEFAULT_THRESHOLD;
                }
                break;
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            default:
