/*
 * HC-SR04 Ultrasonic Theremin — Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM 23)
 *   HC-SR04 ECHO -> GPIO24 (BCM 24)
 *   Speaker     -> GPIO18 (BCM 18) via 8-ohm resistor/capacitor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define SAMPLE_PERIOD_US 50000   /* 50 ms */

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on out-of-range.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo timeout (no response)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo timeout (stuck high)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance_cm = (float)pulse_us / 58.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: Distance %.2f cm out of range [%.1f, %.1f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -2.0f;
    }

    return distance_cm;
}

/*
 * Map distance to frequency on a logarithmic scale.
 */
static float distance_to_frequency(float distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float normalized = (distance_cm - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return MIN_FREQUENCY_HZ +
           (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) *
           powf(10.0f, (float)log10f(normalized));
}

/*
 * Set PWM frequency and 50 % duty cycle.
 * Returns 0 on success, -1 on error.
 */
static int set_speaker_frequency(float frequency)
{
    if (frequency <= 0.0f) {
        if (gpioPWM(PWM_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioPWM(off) failed\n");
            return -1;
        }
        return 0;
    }

    int pwm_range = 2000000 / (int)frequency;
    if (pwm_range < 1) pwm_range = 1;

    int duty = pwm_range / 2;

    if (gpioSetPWMfrequency(PWM_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        return -1;
    }
    if (gpioPWM(PWM_PIN, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM set duty failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(pwm) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    float current_frequency = 0.0f;
    int  pwm_initialized   = 0;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            if (distance == -2.0f) {
                fprintf(stderr, "Warning: Distance out of range, keeping previous frequency\n");
            } else {
                fprintf(stderr, "Warning: Measurement error, keeping previous frequency\n");
            }
        } else {
            float freq = distance_to_frequency(distance);
            if (freq != current_frequency) {
                if (set_speaker_frequency(freq) == 0) {
                    current_frequency = freq;
                    pwm_initialized = 1;
                } else {
                    fprintf(stderr, "Warning: Failed to set speaker frequency\n");
                }
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (pwm_initialized) {
        gpioPWM(PWM_PIN, 0);
    }
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

