/*
 * Theremin-like instrument using HC-SR04 ultrasonic sensor and a piezo buzzer.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   HC-SR04 trigger -> GPIO23 (BCM)
 *   HC-SR04 echo   -> GPIO24 (BCM)  [pull-down recommended]
 *   Piezo buzzer   -> GPIO18 (BCM)  [hardware PWM0]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0   /* cm/s at ~20 °C */
#define MIN_DISTANCE     5.0       /* cm  (HC-SR04 minimum) */
#define MAX_DISTANCE     50.0      /* cm  (HC-SR04 maximum) */
#define MIN_FREQUENCY    200.0     /* Hz  */
#define MAX_FREQUENCY    2000.0    /* Hz  */
#define ECHO_TIMEOUT_US  100000    /* 100 ms */
#define LOOP_DELAY_US    10000     /* 10 ms  */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns 0 on success and stores distance in *out_cm; returns -1 on error.
 */
static int measure_distance(float *out_cm)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or no object)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (stuck high)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1;
    }

    *out_cm = distance;
    return 0;
}

static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    float freq = MIN_FREQUENCY +
                (distance - MIN_DISTANCE) *
                (MAX_FREQUENCY - MIN_FREQUENCY) /
                (MAX_DISTANCE - MIN_DISTANCE);
    return freq;
}

static int set_buzzer_frequency(float frequency)
{
    if (frequency <= 0.0f) {
        if (gpioPWM(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to stop PWM on buzzer\n");
            return -1;
        }
        return 0;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency %.2f Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {  /* 50 % duty cycle */
        fprintf(stderr, "Error: failed to start PWM on buzzer\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    float distance = 0.0f;
    float frequency = 0.0f;
    int last_valid = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (measure_distance(&distance) == 0) {
            last_valid = 1;
            frequency = map_distance_to_frequency(distance);
            if (set_buzzer_frequency(frequency) != 0) {
                fprintf(stderr, "Warning: failed to set buzzer frequency\n");
            }
            printf("Distance: %.2f cm | Frequency: %.2f Hz\n", distance, frequency);
        } else {
            if (last_valid) {
                printf("Sensor read failed; using last valid distance %.2f cm\n", distance);
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

