        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1;  /* timeout */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance_cm(long pulse_us)
{
    return (float)pulse_us / 58.0f;
