/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 *
 * SPI wiring (BCM numbering):
 *   MOSI  -> GPIO10 (SPI0_MOSI)
 *   MISO  -> GPIO9  (SPI0_MISO)
 *   SCLK  -> GPIO11 (SPI0_SCLK)
 *   CE0   -> GPIO8  (SPI0_CE0)
 *   VDD   -> 3.3 V
 *   GND   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_log icu20201_log.c -lpigpio -lrt
 * Run:    sudo ./icu20201_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz – ICU-20201 supports up to 5 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define LOG_FILE       "distance_log.csv"
#define SAMPLE_PERIOD  100000     /* microseconds (100 ms) */

/* ICU-20201 register addresses (16-bit, big-endian on the wire) */
#define ICU20201_REG_DISTANCE_MSB  0x00
#define ICU20201_REG_DISTANCE_LSB  0x01
#define ICU20201_REG_CONFIG        0x02
#define ICU20201_REG_STATUS        0x03

/* Config register bits */
#define ICU20201_CFG_RESET          0x8000
#define ICU20201_CFG_MODE_TOF       0x0001
#define ICU20201_CFG_MODE_CONTINUOUS 0x0002

/* Status register bits */
#define ICU20201_STATUS_READY       0x01
#define ICU20201_STATUS_ERROR       0x02

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ICU-20201 register via SPI.              */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int icu20201_write_reg(uint8_t reg, uint16_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(value >> 8) };
    char rx[2] = { 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "[ERROR] SPI write to register 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ICU-20201 register via SPI.             */
/* Returns 0 on success and stores value in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int icu20201_read_reg(uint8_t reg, uint16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "[ERROR] SPI read from register 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

