#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR        0x60
#define SI1175_REG_ALS_VIS 0x11
#define SI1175_REG_ALS_IR  0x12
#define SI1175_REG_PS1     0x0A
#define SI1175_REG_COMMAND 0x30
#define SI1175_CMD_RESET   0x01
#define SI1175_CMD_ALS_FORCE 0x06
#define SI1175_CMD_PS_FORCE  0x05

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si1175_reset(int fd)
{
    if (i2c_write_byte(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int si1175_force_als(int fd)
{
    if (i2c_write_byte(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int si1175_read_als_vis(int fd, uint16_t *als_vis)
{
    uint8_t lo, hi;
    if (i2c_read_byte(fd, SI1175_REG_ALS_VIS, &lo) < 0)
        return -1;
    if (i2c_read_byte(fd, SI1175_REG_ALS_VIS + 1, &hi) < 0)
        return -1;
    *als_vis = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (si1175_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 reset failed (sensor may be absent): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("proximity_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open proximity_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    while (g_running) {
        if (si1175_force_als(g_i2c_fd) < 0) {
            fprintf(stderr, "ALS force command failed: %s\n", strerror(errno));
            break;
        }

        uint16_t als_vis = 0;
        if (si1175_read_als_vis(g_i2c_fd, &als_vis) < 0) {
            fprintf(stderr, "ALS read failed: %s\n", strerror(errno));
            break;
        }

        char ts[32];
        get_iso8601_timestamp(ts, sizeof(ts));

        if (fprintf(g_log_fp, "%s,%u\n", ts, als_vis) < 0) {
            fprintf(stderr, "Failed to write to log: %s\n", strerror(errno));
            break;
        }
        fflush(g_log_fp);

        for (int i = 0; i < 5 && g_running; i++)
            sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

