#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1120 I2C address (7-bit) */
#define SI1120_ADDR 0x60

/* Si1120 register addresses (from datasheet) */
#define SI1120_REG_PART_ID       0x00
#define SI1120_REG_HW_KEY        0x07
#define SI1120_REG_MEAS_RATE0    0x08
#define SI1120_REG_MEAS_RATE1    0x09
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0     0x24
#define SI1120_REG_PS1_DATA1     0x25
#define SI1120_REG_COMMAND       0x30
#define SI1120_REG_RESPONSE      0x20

/* Si1120 command codes (from datasheet) */
#define SI1120_CMD_RESET         0x01
#define SI1120_CMD_PS_FORCE      0x05
#define SI1120_CMD_ALS_FORCE     0x06
#define SI1120_CMD_PSALS_FORCE   0x07
#define SI1120_CMD_PS_PAUSE      0x0B
#define SI1120_CMD_ALS_PAUSE     0x0C
#define SI1120_CMD_PSALS_PAUSE   0x0D

/* Expected part ID (from datasheet) */
#define SI1120_PART_ID_EXPECTED  0x20

/* Retry parameters */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000  /* 10 ms */

/* Global resources for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                                */
/* ------------------------------------------------------------------ */
static int i2c_read_byte_retry(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read byte failed (reg 0x%02X, attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, pigpio_error(rc));
        if (attempt < I2C_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_write_byte_retry(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write byte failed (reg 0x%02X, val 0x%02X, attempt %d/%d): %s\n",
                reg, value, attempt + 1, I2C_RETRIES, pigpio_error(rc));
        if (attempt < I2C_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Si1120 driver                                                         */
/* ------------------------------------------------------------------ */
static int si1120_init(int handle)
{
    uint8_t part_id = 0;

    /* Read part ID to verify sensor presence */
    if (i2c_read_byte_retry(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Si1120 part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }

    /* Reset the sensor */
    if (i2c_write_byte_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms reset settling time */

    /* Write HW_KEY (required after reset) */
    if (i2c_write_byte_retry(handle, SI1120_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    /* Set measurement rate to 0 (manual mode) */
    if (i2c_write_byte_retry(handle, SI1120_REG_MEAS_RATE0, 0x00) != 0) {
        fprintf(stderr, "Failed to set measurement rate\n");
        return -1;
    }
    if (i2c_write_byte_retry(handle, SI1120_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Failed to set measurement rate\n");
        return -1;
    }

    return 0;
}

static int si1120_read_data(int handle, uint16_t *ambient_light, uint16_t *proximity)
{
    uint8_t als_lo = 0, als_hi = 0, ps_lo = 0, ps_hi = 0;

    /* Force a single ALS measurement */
    if (i2c_write_byte_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "Failed to force ALS measurement\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms conversion time */

    /* Read ALS data (little-endian) */
    if (i2c_read_byte_retry(handle, SI1120_REG_ALS_VIS_DATA0, &als_lo) != 0)
        return -1;
    if (i2c_read_byte_retry(handle, SI1120_REG_ALS_VIS_DATA1, &als_hi) != 0)
        return -1;
    *ambient_light = (uint16_t)((als_hi << 8) | als_lo);

    /* Force a single PS measurement */
    if (i2c_write_byte_retry(handle, SI1120_REG_COMMAND, SI1120_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Failed to force PS measurement\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms conversion time */

    /* Read PS data (little-endian) */
    if (i2c_read_byte_retry(handle, SI1120_REG_PS1_DATA0, &ps_lo) != 0)
        return -1;
    if (i2c_read_byte_retry(handle, SI1120_REG_PS1_DATA1, &ps_hi) != 0)
        return -1;
    *proximity = (uint16_t)((ps_hi << 8) | ps_lo);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n",
                timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1120 address */
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n",
                SI1120_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1120 sensor */
    if (si1120_init(i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t ambient_light = 0, proximity = 0;

        if (si1120_read_data(i2c_handle, &ambient_light, &proximity) == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }

        gpioDelay(500000);  /* 500 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

