#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define SI1182_ADDR     0x60
#define LOG_FILE        "biometric_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* Si1182 register addresses (from datasheet) */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_MEAS_RATE     0x08
#define SI1182_REG_ALS_DATA      0x22
#define SI1182_REG_PS_DATA       0x24

#define SI1182_PART_ID_EXPECTED  0x82
#define SI1182_MEAS_RATE_100MS   0x0A  /* 100 ms measurement rate */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers using Linux ioctl interface                              */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Si1182 part ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 detected (part ID 0x%02X).\n", part_id);

    /* Configure measurement rate to 100 ms */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE, SI1182_MEAS_RATE_100MS) != 0)
        return -1;

    /* Allow first measurement to complete */
    usleep(200000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                   */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, float *lux, uint16_t *proximity)
{
    uint8_t als_data;
    uint16_t ps_data;

    if (i2c_read_reg8(fd, SI1182_REG_ALS_DATA, &als_data) != 0)
        return -1;
    if (i2c_read_reg16(fd, SI1182_REG_PS_DATA, &ps_data) != 0)
        return -1;

    /*
     * lux = als_data  (raw ADC counts, approximate lux)
     * proximity = ps_data (raw ADC counts)
     */
    *lux = (float)als_data;
    *proximity = ps_data;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */
