    (void)sig;
    terminate = 1;
}

static int si1145_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int si1145_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_read_proximity(uint16_t *proximity) {
    uint8_t ps1_data0, ps1_data1;

    if (si1145_read_reg(0x00, &ps1_data0) < 0) return -1;
    if (si1145_read_reg(0x01, &ps1_data1) < 0) return -1;

    *proximity = ((uint16_t)ps1_data1 << 8) | ps1_data0;
    return 0;
}

static void log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u\n", timestamp, proximity);
    fflush(log_file);
}

