#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define MAX_ANGLE 180.0
#define MIN_ANGLE 0.0
#define MAX_PULSE_WIDTH 2500
#define MIN_PULSE_WIDTH 500
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (double)pulse_width * 0.0343 / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

static void set_servo_angle(double angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    double pulse_width = MIN_PULSE_WIDTH + (angle / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor error or out of range\n");
        } else {
            double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

