#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 50000
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MIN_ANGLE 0.0
#define SERVO_MAX_ANGLE 180.0
#define SERVO_MIN_DISTANCE 20.0
#define SERVO_MAX_DISTANCE 200.0
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance with the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low for at least 2 µs before the pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo start\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo end\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range\n", distance);
        return -1.0;
    }

    return distance;
}

/*
 * Map distance to servo angle.
 * Returns angle in degrees, or -1.0 on invalid input.
 */
static float map_distance_to_angle(float distance)
{
    if (distance < 0.0f) {
        return -1.0f;
    }
    if (distance < SERVO_MIN_DISTANCE) {
        return SERVO_MIN_ANGLE;
    }
    if (distance > SERVO_MAX_DISTANCE) {
        return SERVO_MAX_ANGLE;
    }
    return SERVO_MIN_ANGLE +
           (distance - SERVO_MIN_DISTANCE) *
           (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) /
           (SERVO_MAX_DISTANCE - SERVO_MIN_DISTANCE);
}

/*
 * Set servo angle using the pigpio servo API.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle)
{
    if (angle < 0.0f || angle > 180.0f) {
        fprintf(stderr, "Error: angle %.2f out of range [0, 180]\n", angle);
        return -1;
    }

    int pulse_width = (int)(SERVO_MIN_PULSE_US +
                            (angle / 180.0f) *
                            (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement and servo control started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();
        float angle = -1.0f;

        if (distance >= 0.0f) {
            angle = map_distance_to_angle(distance);
            if (angle < 0.0f) {
                fprintf(stderr, "Warning: invalid angle for distance %.2f cm\n", distance);
            }
        }

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: failed to set servo angle\n");
        }

        if (distance >= 0.0f) {
            printf("Distance: %.2f cm, Angle: %.2f deg\n", distance, angle);
        } else {
            printf("Distance: (timeout/error), Angle: (timeout/error)\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown: stop servo, release pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

