#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x48

#define SI7005_REG_CONFIG  0x1F
#define SI7005_REG_MEAS_HIGH 0x20
#define SI7005_REG_MEAS_LOW  0x21

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si7005_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

static int si7005_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) failed (reg=0x%02X)\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int si7005_read_measurement(int handle, float *temperature, float *humidity) {
    uint8_t meas_high, meas_low;

    if (si7005_write_reg(handle, SI7005_REG_CONFIG, 0x03) != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (si7005_write_reg(handle, SI7005_REG_MEAS_HIGH, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write MEAS_HIGH register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (si7005_read_reg(handle, SI7005_REG_MEAS_HIGH, &meas_high) != 0) {
        fprintf(stderr, "Error: Failed to read MEAS_HIGH register\n");
        return -1;
    }
    if (si7005_read_reg(handle, SI7005_REG_MEAS_LOW, &meas_low) != 0) {
        fprintf(stderr, "Error: Failed to read MEAS_LOW register\n");
        return -1;
    }

