#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG     0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_TEMP_OUT_H  0x41
#define MPU6050_GYRO_XOUT_H 0x43

/* Sample period in microseconds (100 ms) */
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single byte from an MPU-6050 register.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/*
 * Write a single byte to an MPU-6050 register.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/*
 * Initialize the MPU-6050: verify device identity, set sample rate,
 * and configure accelerometer and gyroscope ranges.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_init(int handle)
{
    uint8_t who_am_i = 0;

    if (mpu6050_read_reg(handle, MPU6050_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (mpu6050_write_reg(handle, MPU6050_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /*
     * CONFIG register:
     *   DLPF_CFG[3:0] = 3 → 256 Hz internal sample rate, 8 kHz ODR
     *   FIFO_EN = 0
     *   I2C_MST_EN = 0
     *   I2C_IF_DIS = 0
     *   STBY = 0
     */
    if (mpu6050_write_reg(handle, MPU6050_CONFIG, 0x03) != 0)
        return -1;

    /*
     * GYRO_CONFIG:
     *   FS_SEL[1:0] = 00 → ±250 °/s
     *   LIR = 0
     *   AFS_SEL[1:0] = 00 → ±2 g
     */
    if (mpu6050_write_reg(handle, MPU6050_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /*
     * ACCEL_CONFIG:
     *   AFS_SEL[1:0] = 00 → ±2 g
     *   ACCEL_HPF_CTRL[1:0] = 00
     */
    if (mpu6050_write_reg(handle, MPU6050_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/*
 * Read 14 bytes of accelerometer + temperature + gyroscope data.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_data(int handle,
                             int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *temp, int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];
    int rc = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (rc != 14) {
        fprintf(stderr, "Error reading data block: expected 14 bytes, got %d\n", rc);
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    *temp = (int16_t)((buf[6]  << 8) | (uint8_t)buf[7]);
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);
    return 0;
}

int main(void)
{
    int16_t ax, ay, az, temp, gx, gy, gz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 initialized. Logging data every 100 ms (Ctrl+C to stop).\n");
    fflush(stdout);

    while (g_running) {
        if (mpu6050_read_data(g_i2c_handle, &ax, &ay, &az, &temp, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Temp=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, temp, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read error — continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

