#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x1C
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *ambient, float *object) {
    uint8_t buf[6];
    int16_t raw_ambient, raw_object;

    if (read(i2c_fd, buf, 6) != 6) {
        perror("Failed to read temperature data");
        return -1;
    }

    raw_ambient = (int16_t)((buf[0] << 8) | buf[1]);
    raw_object = (int16_t)((buf[3] << 8) | buf[4]);

    *ambient = (float)raw_ambient / 100.0f;
    *object = (float)raw_object / 100.0f;

    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    if (t == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    if (fflush(log_fp) != 0) {
        perror("Failed to flush log file");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (i2c_init() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient, object;

        if (read_temperature(&ambient, &object) == 0) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Logging failed. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed. Continuing.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

