    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* File logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0)
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char ts[32];
