#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x48
#define CMD_TEMP_NO_HOLD 0xE3
#define CMD_HUMID_NO_HOLD 0xE5
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEAS_TIMEOUT_MS 20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_measurement(int handle, uint8_t cmd, uint16_t *raw) {
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByte(handle, cmd);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), attempt %d/%d: %s\n",
                    cmd, attempt + 1, MAX_RETRIES, strerror(errno));
            gpioDelay(10000);
            continue;
        }
        gpioDelay(15000);
        char buf[2];
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (cmd 0x%02X), attempt %d/%d: %s\n",
                cmd, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

static int convert_temperature(uint16_t raw) {
    return (int)((175.72 * (double)raw) / 65536.0 - 46.85);
}

static int convert_humidity(uint16_t raw) {
    return (int)((125.0 * (double)raw) / 65536.0 - 6.0);
}

static void log_data(FILE *fp, int temp_c, int humidity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %d C, Humidity: %d %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c, humidity);
    fflush(fp);
    printf("%04d-%02d-%02d %02d:%02d:%02d, Temperature: %d C, Humidity: %d %%\n",
           tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
           tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c, humidity);
}

