    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        int temp_c = -999, humidity = -999;

        if (read_measurement(g_i2c_handle, CMD_TEMP_NO_HOLD, &raw_temp) == 0) {
            temp_c = convert_temperature(raw_temp);
        } else {
            fprintf(stderr, "Temperature read failed after retries.\n");
        }

        if (read_measurement(g_i2c_handle, CMD_HUMID_NO_HOLD, &raw_hum) == 0) {
            humidity = convert_humidity(raw_hum);
        } else {
            fprintf(stderr, "Humidity read failed after retries.\n");
        }

        if (temp_c != -999 && humidity != -999) {
            log_data(fp, temp_c, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; skipping log entry.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (fp) fclose(fp);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

