#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x48
#define TRIGGER_CMD    0x3680
#define MEAS_DELAY_MS  45
#define LOG_INTERVAL_MS 100
#define LOG_FILE       "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, TRIGGER_CMD) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, 9) < 0) return -1;

    if (crc8(&data[0], 2) != data[2]) return -2;
    if (crc8(&data[3], 2) != data[5]) return -2;
    if (crc8(&data[6], 2) != data[8]) return -2;

    int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);
    int16_t raw_s = (int16_t)((data[6] << 8) | data[7]);

    if (raw_s == 0) return -3;

    *pressure    = (float)raw_p / (float)raw_s;
    *temperature = (float)raw_t / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(g_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int need_header = (fp == NULL);
    if (fp) fclose(fp);

    if (need_header) {
        fp = fopen(LOG_FILE, "w");
        if (fp) { fprintf(fp, "timestamp,pressure_pa,temperature_c\n"); fclose(fp); }
    }

    while (g_running) {
        float p, t;
        int rc = read_sdp800(g_fd, &p, &t);
        if (rc == 0) {
            log_data(p, t);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", p, t);
        } else {
            fprintf(stderr, "Sensor read error (rc=%d)\n", rc);
        }
        usleep(LOG_INTERVAL_MS * 1000);
    }

    if (g_fd >= 0) close(g_fd);
    return 0;
}

