    if (crc8(&data[3], 2) != data[5]) return -2;
    if (crc8(&data[6], 2) != data[8]) return -2;

    int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);
    int16_t raw_s = (int16_t)((data[6] << 8) | data[7]);

    if (raw_s == 0) return -3;

    *pressure    = (float)raw_p / (float)raw_s;
    *temperature = (float)raw_t / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(g_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int need_header = (fp == NULL);
    if (fp) fclose(fp);

    if (need_header) {
        fp = fopen(LOG_FILE, "w");
        if (fp) { fprintf(fp, "timestamp,pressure_pa,temperature_c\n"); fclose(fp); }
    }

    while (g_running) {
        float p, t;
        int rc = read_sdp800(g_fd, &p, &t);
        if (rc == 0) {
            log_data(p, t);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", p, t);
        } else {
            fprintf(stderr, "Sensor read error (rc=%d)\n", rc);
        }
        usleep(LOG_INTERVAL_MS * 1000);
    }

    if (g_fd >= 0) close(g_fd);
    return 0;
