/*
 * enclosure_temp_logger.c
 *
 * Raspberry Pi Zero W – Sensirion STS30-DIS temperature logger
 *
 * Wiring:
 *   STS30-DIS VDD  -> Pi 3V3  (Pin 1)
 *   STS30-DIS GND  -> Pi GND  (Pin 9)
 *   STS30-DIS SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   STS30-DIS SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Default I2C address: 0x5C (7-bit)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o enclosure_temp_logger enclosure_temp_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./enclosure_temp_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define STS30_ADDR           0x5C          /* Default 7-bit I2C address */
#define SAMPLE_INTERVAL_US   500000        /* 500 ms between samples */
#define CONVERSION_DELAY_US  15000         /* 15 ms conversion wait */
#define LOG_FILE             "enclosure_temp_log.txt"
#define ERROR_LOG_FILE       "error_log.txt"

/*
 * STS30 single-shot high-repeatability measurement command
 * (0x360800): bit 15 = 1 (high repeatability), bits 14:12 = 100 (temperature),
 * bits 11:4 = 0, bits 3:0 = 0000 (no clock stretching).
 */
#define MEASURE_CMD_MSB      0x36
#define MEASURE_CMD_LSB      0x08

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;
static FILE *g_err_fp    = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static int  init_i2c(void);
static int  read_temperature(float *temperature);
static void log_temperature(float temperature);
static void log_error(const char *message);
static uint8_t crc8(const uint8_t *data, int len);

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- I2C Init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, STS30_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- CRC-8 ------------------------------------- */
/*
 * Sensirion CRC-8: polynomial 0x31, initial value 0xFF, no final XOR.
 */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ----------------------------- Temperature Read --------------------------- */
static int read_temperature(float *temperature)
{
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    uint8_t buf[3];
    int     result;

    /* Send measurement command */
    result = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("I2C write failed (measurement command)");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 3 bytes: MSB, LSB, CRC */
    result = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (result != 3) {
        log_error("I2C read failed (temperature data)");
        return -1;
    }

    /* Validate CRC */
    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC mismatch on temperature data");
        return -1;
    }

    /* Convert raw value to Celsius */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw / 2048.0f;

    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_temperature(float temperature)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(g_log_fp);
}

static void log_error(const char *message)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_err_fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(g_err_fp);
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    float temperature;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("Error opening error log file");
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

