#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x48
#define MEASURE_CMD    0x2C
#define MEASURE_DELAY_US 9000
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        perror("write(measure cmd)");
        return -1;
    }

    usleep(MEASURE_DELAY_US);

    uint8_t buf[6];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != 6) {
        if (r < 0) perror("read(response)");
        else fprintf(stderr, "read: expected 6 bytes, got %zd\n", r);
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temperature, humidity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) return 1;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        close(g_i2c_fd);
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;
        if (read_sht40(g_i2c_fd, &temperature, &humidity) == 0) {
            log_data(g_log_fp, temperature, humidity);
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

