#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x48
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define MEAS_DELAY_US  1000       /* 1 ms after trigger */

/* SDP800 continuous measurement command: bit 7 = 0 (read), bit 6 = 0 (continuous),
 * bits 5-0 = 0x00 (mass flow, but pressure is the first measured parameter). */
#define MEAS_CMD       0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* ---- CRC-8 (Sensirion polynomial x^8 + x^5 + x^4 + 1, init 0x31) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x31;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x07 : (crc << 1);
    }
    return crc;
}

static void cleanup(void)
{
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c write");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("i2c read");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "i2c read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, MEAS_CMD) < 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

