/*
 * Si7021 humidity/temperature monitor with fan control on Raspberry Pi 4.
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   Si7021 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *   Fan +       -> GPIO18 (BCM) via transistor/MOSFET
 *   Fan -       -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS            1
#define SI7021_ADDR        0x48          /* Si7021 default 7-bit address */
#define FAN_GPIO           18            /* BCM pin for fan control */

#define TEMP_MEASURE_CMD   0xE3          /* Measure temperature (no clock stretching) */
#define MEASURE_DELAY_US   12000         /* 12 ms > 10.8 ms max conversion time */
#define FAN_ON_DELAY_US    10000         /* 10 ms fan-on settle delay */
#define SAMPLE_INTERVAL_S  2             /* Seconds between readings */
#define BUFFER_SIZE        60
#define MAX_RETRIES        3
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 27.0f

/* --------------------------- Global State ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Circular Buffer --------------------------- */

typedef struct {
    time_t timestamp;
    float  temperature;
} Reading;

typedef struct {
    Reading data[BUFFER_SIZE];
    int     head;
    int     count;
} CircularBuffer;

static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, time_t ts, float temp)
{
    cb->data[cb->head].timestamp  = ts;
    cb->data[cb->head].temperature = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* --------------------------- Si7021 Helpers ----------------------------- */

/*
 * Read temperature in degrees Celsius.
 * Returns 0 on success, -1 on failure.
 */
static int read_temperature(int handle, float *out_temp)
{
    uint8_t cmd = TEMP_MEASURE_CMD;
    uint8_t buf[2];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed\n", attempt + 1);
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
            fprintf(stderr, "[attempt %d] i2cReadDevice failed\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *out_temp = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }

    fprintf(stderr, "Temperature read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

/* --------------------------- Fan Control ------------------------------- */

static void fan_set(int on)
{
    if (gpioWrite(FAN_GPIO, on ? 1 : 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", FAN_GPIO);
}

/* --------------------------- Signal Handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_set(0);

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fan_set(0);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer --- */
    CircularBuffer buf;
    buffer_init(&buf);

    printf("Si7021 fan monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        time_t now = time(NULL);

        if (read_temperature(g_i2c_handle, &temp) == 0) {
            printf("[%ld] Temperature: %.2f C\n", (long)now, temp);
            buffer_add(&buf, now, temp);

            if (temp > TEMP_THRESHOLD_ON && !gpioRead(FAN_GPIO)) {
                fan_set(1);
                gpioDelay(FAN_ON_DELAY_US);
            } else if (temp < TEMP_THRESHOLD_OFF && gpioRead(FAN_GPIO)) {
                fan_set(0);
            }
        } else {
            fprintf(stderr, "[%ld] Sensor read failed — continuing.\n", (long)now);
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    fan_set(0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

