        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_set(0);

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fan_set(0);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer --- */
    CircularBuffer buf;
    buffer_init(&buf);

    printf("Si7021 fan monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        time_t now = time(NULL);

        if (read_temperature(g_i2c_handle, &temp) == 0) {
            printf("[%ld] Temperature: %.2f C\n", (long)now, temp);
            buffer_add(&buf, now, temp);

            if (temp > TEMP_THRESHOLD_ON && !gpioRead(FAN_GPIO)) {
                fan_set(1);
                gpioDelay(FAN_ON_DELAY_US);
            } else if (temp < TEMP_THRESHOLD_OFF && gpioRead(FAN_GPIO)) {
                fan_set(0);
            }
        } else {
            fprintf(stderr, "[%ld] Sensor read failed — continuing.\n", (long)now);
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    fan_set(0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

