/*
 * SCD40 CO2 / Temperature / Humidity monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   SCD40 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD -> 3.3 V
 *   SCD40 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SCD40 constants (per Sensirion SCD40 datasheet) ---- */
#define SCD40_ADDR             0x50
#define SCD40_CMD_START_PERIODIC 0x3600
#define SCD40_CMD_STOP_PERIODIC  0x3500
#define SCD40_CMD_READ_MEASUREMENT 0x0000
#define SCD40_DATA_READY_BIT    0x01
#define SCD40_DATA_READY_DELAY  1000000   /* microseconds */
#define SCD40_MEASUREMENT_DELAY 1000000   /* microseconds */
#define SCD40_CRC8_POLY        0x31
#define SCD40_CRC8_INIT        0xFF

#define I2C_BUS              1
#define LOG_FILE             "air_quality.log"
#define POLL_INTERVAL_US     5000000   /* 5 s */
#define MAX_RETRIES          3

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t scd40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SCD40_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ SCD40_CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ---- Low-level I2C helpers ---- */
static int scd40_write_command(int handle, uint16_t command)
{
    uint8_t buf[2] = { (uint8_t)(command >> 8), (uint8_t)(command & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed\n", command);
        return -1;
    }
    return 0;
}

static int scd40_read_block(int handle, uint8_t *buf, size_t len)
{
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice(%zu bytes) failed\n", len);
        return -1;
    }
    return 0;
}

/* ---- Sensor operations ---- */
static int scd40_start_periodic(int handle)
{
    if (scd40_write_command(handle, SCD40_CMD_START_PERIODIC) != 0)
        return -1;
    gpioDelay(SCD40_MEASUREMENT_DELAY);
    return 0;
}

static int scd40_stop_periodic(int handle)
{
    return scd40_write_command(handle, SCD40_CMD_STOP_PERIODIC);
}

static int scd40_data_ready(int handle)
{
    if (scd40_write_command(handle, SCD40_CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(SCD40_DATA_READY_DELAY);

    uint8_t buf[3];
    if (scd40_read_block(handle, buf, 3) != 0)
        return -1;

    if (scd40_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = ((uint16_t)buf[0] << 8) | buf[1];
    return (word & 0x07FF) ? 1 : 0;
}

static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temp, float *hum)
{
    if (scd40_write_command(handle, SCD40_CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(SCD40_DATA_READY_DELAY);

    uint8_t buf[9];
    if (scd40_read_block(handle, buf, 9) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (scd40_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw  = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t hum_raw  = ((uint16_t)buf[6] << 8) | buf[7];

    *co2  = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum  = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, uint16_t co2, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_stop_periodic(g_i2c_handle);
        gpioDelay(100000);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (scd40_start_periodic(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD40 monitoring started. Logging to %s every 5 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int ready = 0;
        int retries = 0;
        while (retries < MAX_RETRIES && g_running) {
            ready = scd40_data_ready(g_i2c_handle);
            if (ready < 0) {
                fprintf(stderr, "[WARN] data-ready check failed (attempt %d/%d)\n",
                        retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100000);
            } else {
                break;
            }
        }

        if (ready < 0) {
            fprintf(stderr, "[ERROR] data-ready check failed after %d attempts; aborting.\n",
                    MAX_RETRIES);
            break;
        }

        if (!ready) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint16_t co2;
        float temp, hum;
        int ok = 0;
        retries = 0;
        while (retries < MAX_RETRIES && g_running) {
            if (scd40_read_measurement(g_i2c_handle, &co2, &temp, &hum) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] read measurement failed (attempt %d/%d)\n",
                    retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(100000);
        }

        if (!ok) {
            fprintf(stderr, "[ERROR] read measurement failed after %d attempts; aborting.\n",
                    MAX_RETRIES);
            break;
        }

        if (log_data(g_log_file, co2, temp, hum) != 0) {
            fprintf(stderr, "[ERROR] logging failed; aborting.\n");
            break;
        }

        printf("CO2: %u ppm | Temp: %.2f C | Hum: %.2f %%\n", co2, temp, hum);
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

