/*
 * SCD40 CO2 monitor for Raspberry Pi 4 Model B
 *
 * I2C bus 1, SCD40 address 0x50 (7-bit), 5 s sample period.
 * GPIO17 (BCM) drives a warning LED.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run:    sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SCD40_ADDR     0x50          /* SCD40 7-bit I2C address */
#define LED_PIN        17            /* BCM GPIO17 */
#define CO2_THRESHOLD  1000          /* ppm */
#define SAMPLE_PERIOD  5             /* seconds */
#define BUFFER_SIZE    20

/* SCD40 command: continuous measurement, no averaging */
#define CMD_CONT_MEAS  0x0000

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion convention) */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_led_pin    = LED_PIN;
static bool     g_gpio_inited = false;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void cb_init(circular_buffer_t *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(circular_buffer_t *cb, const sensor_data_t *d)
{
    cb->data[cb->head] = *d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Stop continuous measurement */
        (void)i2cWriteByteData(g_i2c_handle, 0x00, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_gpio_inited) {
        gpioWrite(g_led_pin, 0);
