#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

