/*
 * TMP05 temperature logger for Raspberry Pi 4 Model B
 *
 * Reads the TMP05 PWM output on GPIO4 (BCM 4, physical pin 7) using
 * microsecond-resolution timestamps from the host-call() API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_logger tmp05_logger.c -lpigpio -lrt
 * Run:    sudo ./tmp05_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TMP05_GPIO          4          /* BCM 4, physical pin 7 */
#define LOG_FILE            "temperature_log.txt"
#define SAMPLE_INTERVAL_S   5          /* seconds between samples */
#define EDGE_TIMEOUT_US     50000      /* 50 ms timeout waiting for an edge */
#define MAX_CONSECUTIVE_ERR 3          /* consecutive errors before malfunction flag */
#define MIN_TEMP_C          (-40.0f)
#define MAX_TEMP_C          (150.0f)

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Read one TMP05 PWM cycle; returns true on success, false on error.  */
/* ------------------------------------------------------------------ */
static bool read_tmp05(float *temperature_c)
{
    uint32_t t_rise, t_fall;
    uint32_t start_tick, deadline;

    /* Wait for the line to go HIGH (start of a high pulse) */
    start_tick = gpioTick();
    deadline   = start_tick + EDGE_TIMEOUT_US;
    while (gpioRead(TMP05_GPIO) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for HIGH edge\n");
            return false;
        }
    }
    t_rise = gpioTick();

    /* Wait for the line to go LOW (end of the high pulse) */
    deadline = t_rise + EDGE_TIMEOUT_US;
    while (gpioRead(TMP05_GPIO) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for LOW edge\n");
            return false;
        }
    }
    t_fall = gpioTick();

    /* Wait for the line to go HIGH again (end of the low pulse) */
    deadline = t_fall + EDGE_TIMEOUT_US;
    while (gpioRead(TMP05_GPIO) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for second HIGH edge\n");
            return false;
        }
    }
    uint32_t t_rise2 = gpioTick();

    uint32_t th = t_fall - t_rise;          /* high pulse width  */
    uint32_t tl = t_rise2 - t_fall;         /* low  pulse width  */
    uint32_t tc = t_rise2 - t_rise;         /* full cycle width  */

    /*
     * TMP05 PWM duty cycle is proportional to temperature:
     *   D = (T - -40) / (150 - -40)  ->  D = (T + 40) / 190
     *   D = th / tc
     *   th / tc = (T + 40) / 190
     *   T = (th / tc) * 190 - 40
     */
    if (tc == 0) {
        fprintf(stderr, "Error: zero cycle width (th=%u, tl=%u)\n", th, tl);
        return false;
    }

    float duty = (float)th / (float)tc;
    *temperature_c = duty * 190.0f - 40.0f;

    if (*temperature_c < MIN_TEMP_C || *temperature_c > MAX_TEMP_C) {
        fprintf(stderr, "Error: temperature %.2f C out of range [%.0f, %.0f]\n",
                *temperature_c, MIN_TEMP_C, MAX_TEMP_C);
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(float temperature_c)
{
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s, %.2f\n", ts, temperature_c);
    fflush(g_log_fp);
}

static void log_malfunction(void)
{
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s, SENSOR MALFUNCTION\n", ts);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ----------------------------------------- */
    if (gpioSetMode(TMP05_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", TMP05_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMP05 logger started. GPIO%d, logging to %s every %d s.\n",
           TMP05_GPIO, LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature_c;

        if (read_tmp05(&temperature_c)) {
            consecutive_errors = 0;
            log_temperature(temperature_c);
            printf("Temperature: %.2f C\n", temperature_c);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                log_malfunction();
                fprintf(stderr, "Sensor malfunction flag set (consecutive errors: %d)\n",
                        consecutive_errors);
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

