    get_iso8601_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s, SENSOR MALFUNCTION\n", ts);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ----------------------------------------- */
    if (gpioSetMode(TMP05_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", TMP05_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMP05 logger started. GPIO%d, logging to %s every %d s.\n",
           TMP05_GPIO, LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature_c;

        if (read_tmp05(&temperature_c)) {
            consecutive_errors = 0;
            log_temperature(temperature_c);
            printf("Temperature: %.2f C\n", temperature_c);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                log_malfunction();
                fprintf(stderr, "Sensor malfunction flag set (consecutive errors: %d)\n",
                        consecutive_errors);
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

