#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "environmental_data.txt"
#define MEASUREMENT_CMD 0x2C00
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000
#define GREENHOUSE_PERIOD 3600
#define GREENHOUSE_AMPLITUDE_TEMP 2.0
#define GREENHOUSE_AMPLITUDE_HUMIDITY 5.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error: I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Error: I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Error: Temperature CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Error: Humidity CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Error: Failed to read SHT35 after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

static void simulate_greenhouse(float temperature, float humidity, float *out_temp, float *out_hum) {
    time_t rawtime;
    struct tm *timeinfo;
    double elapsed;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    elapsed = difftime(timeinfo->tm_yday * 86400 + timeinfo->tm_hour * 3600 + timeinfo->tm_min * 60 + timeinfo->tm_sec, 0);

    *out_temp = temperature + GREENHOUSE_AMPLITUDE_TEMP * sin(2.0 * M_PI * elapsed / GREENHOUSE_PERIOD);
    *out_hum = humidity + GREENHOUSE_AMPLITUDE_HUMIDITY * sin(2.0 * M_PI * elapsed / GREENHOUSE_PERIOD);
}

int main(void) {
    float temperature, humidity, out_temp, out_hum;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle: %d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting environmental data logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            simulate_greenhouse(temperature, humidity, &out_temp, &out_hum);
            log_data(log_file, out_temp, out_hum);
            printf("Logged: %.2f C, %.2f %%RH\n", out_temp, out_hum);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Logging NaN.\n");
            log_data(log_file, NAN, NAN);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    return 0;
}

