/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   SDP810 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C address: 0x50 (7-bit, default for SDP810 family)
 *
 * Continuous measurement command (0x3602):
 *   0x36 0x02  -> start continuous measurement, average until read
 * Conversion time: ~45 ms
 *
 * Read block (9 bytes):
 *   bytes 0-2 : pressure (24-bit, two's complement)
 *   byte 3    : scale factor (8-bit)
 *   bytes 4-6 : temperature (24-bit, two's complement)
 *   byte 7    : CRC-8 (polynomial 0x31, init 0xFF)
 *
 * Pressure (Pa) = (pressure_raw * scale_factor) / 2^16
 * Temperature (°C) = temperature_raw / 2^16
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x50
#define CSV_FILE       "airflow.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_DELAY_MS  45         /* conversion time (ms) */

/* Continuous measurement command */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x02 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp810(int fd, float *pressure, float *temperature)
{
    uint8_t data[9];

    /* Send continuous-measurement command */
    if (i2c_write_cmd(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) < 0)
        return -1;

    /* Wait for conversion to complete */
    struct timespec ts = { 0, CONV_DELAY_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 9-byte block: pressure(3) + scale(1) + temperature(3) + CRC(1) */
    if (i2c_read_block(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC-8 over the 8 data bytes */
    if (crc8(data, 8) != data[8]) {
        fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n",
                crc8(data, 8), data[8]);
        return -1;
    }

    /* Pressure: 24-bit two's complement, scaled by 8-bit factor */
    int32_t pressure_raw = (int32_t)((data[0] << 16) |
                                     (data[1] << 8)  |
                                     data[2]);
    if (pressure_raw & 0x800000)
        pressure_raw |= 0xFF000000;          /* sign-extend */

    uint8_t scale_factor = data[3];
    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor 0 from sensor\n");
        return -1;
    }

    *pressure = (float)pressure_raw * (float)scale_factor / 65536.0f;

    /* Temperature: 24-bit two's complement */
    int32_t temp_raw = (int32_t)((data[4] << 16) |
                                (data[5] << 8)  |
                                data[6]);
    if (temp_raw & 0x800000)
        temp_raw |= 0xFF000000;

    *temperature = (float)temp_raw / 65536.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP810 reader started on %s (addr 0x%02X). Logging to %s\n",
           I2C_BUS, SDP810_ADDR, CSV_FILE);

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_data(CSV_FILE, pressure, temperature) < 0)
                fprintf(stderr, "Logging failed (continuing)\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

