static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp810(int fd, float *pressure, float *temperature)
{
    uint8_t data[9];

    /* Send continuous-measurement command */
    if (i2c_write_cmd(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) < 0)
        return -1;

    /* Wait for conversion to complete */
    struct timespec ts = { 0, CONV_DELAY_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 9-byte block: pressure(3) + scale(1) + temperature(3) + CRC(1) */
    if (i2c_read_block(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC-8 over the 8 data bytes */
    if (crc8(data, 8) != data[8]) {
        fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n",
                crc8(data, 8), data[8]);
        return -1;
    }

    /* Pressure: 24-bit two's complement, scaled by 8-bit factor */
    int32_t pressure_raw = (int32_t)((data[0] << 16) |
                                     (data[1] << 8)  |
                                     data[2]);
    if (pressure_raw & 0x800000)
        pressure_raw |= 0xFF000000;          /* sign-extend */

    uint8_t scale_factor = data[3];
    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor 0 from sensor\n");
        return -1;
    }

    *pressure = (float)pressure_raw * (float)scale_factor / 65536.0f;

    /* Temperature: 24-bit two's complement */
    int32_t temp_raw = (int32_t)((data[4] << 16) |
                                (data[5] << 8)  |
                                data[6]);
    if (temp_raw & 0x800000)
        temp_raw |= 0xFF000000;

    *temperature = (float)temp_raw / 65536.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP810 reader started on %s (addr 0x%02X). Logging to %s\n",
           I2C_BUS, SDP810_ADDR, CSV_FILE);

    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_data(CSV_FILE, pressure, temperature) < 0)
                fprintf(stderr, "Logging failed (continuing)\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

