#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define CSV_FILE       "environment.csv"
#define SAMPLE_PERIOD  5
#define MEAS_DELAY_US  20000   /* 20 ms — exceeds SHT35 high-repeatability 15 ms */

/* SHT35 single-shot, clock-stretching disabled, high repeatability */
#define CMD_MSB        0x24
#define CMD_LSB        0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion polynomial x^8 + x^5 + x^4 + 1, init 0x31) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x31;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int file_exists(const char *path)
{
    FILE *f = fopen(path, "r");
    if (f) { fclose(f); return 1; }
    return 0;
}

static int ensure_csv_header(void)
{
    if (file_exists(CSV_FILE))
        return 0;

    FILE *f = fopen(CSV_FILE, "w");
    if (!f) { perror("fopen(CSV, w)"); return -1; }
    fprintf(f, "timestamp,temperature_c,humidity_pct\n");
    fclose(f);
    return 0;
}

static int read_sht35(int handle, float *temp_c, float *rh)
{
    uint8_t cmd[2] = { CMD_MSB, CMD_LSB };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh    = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void log_data(float temp_c, float rh)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];

