        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);

    FILE *f = fopen(CSV_FILE, "a");
    if (!f) {
        fprintf(stderr, "fopen(CSV, a) failed: %s\n", strerror(errno));
        return;
    }
    fprintf(f, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fclose(f);
}

