{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Ctrl+C to stop.\n",
           CSV_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temp_c, rh;

        if (read_sht35(g_i2c_handle, &temp_c, &rh) == 0) {
            log_data(temp_c, rh);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   "sample", temp_c, rh);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

