}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    for (int elapsed = 0; elapsed < MEASURE_TIMEOUT_MS; elapsed += 5) {
        uint8_t buf[3];
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
            return -1;
        }
        *raw = (uint16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    fprintf(stderr, "Measurement 0x%02X timed out\n", cmd);
    return -1;
}

static int read_sensor(int fd, float *temp, float *hum) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);

    uint16_t raw_t, raw_h;
    if (read_measurement(fd, CMD_READ_TEMP, &raw_t) < 0)
        return -1;
    if (read_measurement(fd, CMD_READ_HUM, &raw_h) < 0)
        return -1;

    *temp = (float)((raw_t * 175.72f) / 65536.0f) - 46.85f;
    *hum  = (float)((raw_h * 125.0f) / 65536.0f) - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static void log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR\n");
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    FILE *hdr = fopen(LOG_FILE, "r");
    int need_header = (hdr == NULL);
    if (hdr) fclose(hdr);

    while (g_running) {
        float temp, hum;
        if (read_sensor(g_i2c_fd, &temp, &hum) == 0) {
            log_data(temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; resetting and retrying...\n");
            log_data(-999.0f, -999.0f);
        }
        for (int i = 0; i < POLL_INTERVAL && g_running; i++)
            sleep(1);
    }

    if (g_i2c_fd >= 0) {
        i2c_write_cmd(g_i2c_fd, CMD_RESET);
        close(g_i2c_fd);
    }
    return 0;
}

