static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflection */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (sensor may be absent).\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: I2C read failed (9 bytes expected).\n");
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on pressure word.\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw_pressure / 100.0f;
    return 0;
}

static void log_pressure(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float pressure;
        if (read_sdp800(i2c_handle, &pressure) == 0) {
            log_pressure(log_file, pressure);
