            fprintf(stderr, "Warning: sensor read failed, continuing.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

