#define PWM_FREQ 25000
#define PWM_RANGE 100
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, float *pressure) {
    char buf[3];
    int bytes_read = i2cReadDevice(handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: expected 3 bytes, got %d\n", bytes_read);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 16) |
                   ((uint32_t)(uint8_t)buf[1] << 8)  |
                   ((uint32_t)(uint8_t)buf[2]);
    *pressure = (float)raw / 1048576.0f;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    return pressure * 100.0f;
}

static void control_fan(float flow_rate) {
    int duty = (int)(flow_rate * 10.0f);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fflush(fp);
}

