#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x28
#define LPS33HW_REG_CTRL_REG1 0x20
#define LPS33HW_REG_PRESS_OUT_XL 0x28
#define LPS33HW_REG_TEMP_OUT_L 0x2B
#define LPS33HW_REG_WHO_AM_I 0x0F
#define LPS33HW_WHO_AM_I_VAL 0x54

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, int32_t *pressure) {
    uint8_t xl, l, h;
    if (read_register(handle, LPS33HW_REG_PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, LPS33HW_REG_PRESS_OUT_XL + 1, &l) < 0) return -1;
    if (read_register(handle, LPS33HW_REG_PRESS_OUT_XL + 2, &h) < 0) return -1;
    *pressure = (int32_t)((uint32_t)h << 16 | (uint32_t)l << 8 | xl);
    return 0;
}

static int read_temperature(int handle, int16_t *temperature) {
    uint8_t l, h;
    if (read_register(handle, LPS33HW_REG_TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(handle, LPS33HW_REG_TEMP_OUT_L + 1, &h) < 0) return -1;
    *temperature = (int16_t)((uint16_t)h << 8 | l);
    return 0;
}

static void log_data(FILE *fp, int32_t pressure, int16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime_r(&rawtime, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, (float)pressure / 100.0f, (float)temperature / 100.0f);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime_r(&rawtime, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    if (fp) {
        fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
        fflush(fp);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (read_register(i2c_handle, LPS33HW_REG_WHO_AM_I, &who_am_i) < 0) {
        log_error(log_file, "Failed to read WHO_AM_I register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != LPS33HW_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                LPS33HW_WHO_AM_I_VAL, who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, LPS33HW_REG_CTRL_REG1, 0x00) < 0) {
        log_error(log_file, "Failed to reset CTRL_REG1");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10000);

    if (write_register(i2c_handle, LPS33HW_REG_CTRL_REG1, 0x01) < 0) {
        log_error(log_file, "Failed to start continuous conversion");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        int32_t pressure;
        int16_t temperature;

        if (read_pressure(i2c_handle, &pressure) < 0) {
            log_error(log_file, "Failed to read pressure");
        } else if (read_temperature(i2c_handle, &temperature) < 0) {
            log_error(log_file, "Failed to read temperature");
        } else {
            log_data(log_file, pressure, temperature);
        }

        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

