#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

/* STLM75 commands */
#define STLM75_READ_TEMP_HOLD  0x06
#define STLM75_READ_TEMP_NOHOLD 0x05

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/*
 * Read temperature from STLM75.
 * Returns 0 on success and stores the temperature in *out_temp.
 * Returns -1 on I2C error.
 */
static int read_temperature(int handle, float *out_temp)
{
    char cmd = STLM75_READ_TEMP_NOHOLD;
    char data[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    /* STLM75 needs a short delay between command and read */
    gpioDelay(1000); /* 1 ms */

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *out_temp = (float)raw / 100.0f;
    return 0;
}

static void control_led(float avg_temp)
{
    gpioWrite(GPIO_LED, (avg_temp > TEMP_THRESHOLD) ? 1 : 0);
}

int main(void)
{
    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", GPIO_LED);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            float avg_temp = cb_average(&temp_buffer);
            control_led(avg_temp);
            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, avg_temp);
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping iteration\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful cleanup */
    gpioWrite(GPIO_LED, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

