/*
 * SCD30 CO2 / Temperature / Humidity monitor with ventilation control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Sensirion SCD30 (I2C address 0x50)
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_monitor scd30_monitor.c -lpigpio -lrt
 * Run:    sudo ./scd30_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SCD30 constants ---- */
#define SCD30_ADDR             0x50
#define SCD30_MEASURE_CMD      0x3604
#define SCD30_MEASURE_DELAY_US 25000   /* 25 ms (datasheet: max 25 ms) */
#define SCD30_DATA_READY_BIT   0x80    /* bit 7 of status word */

/* ---- Ventilation thresholds (ppm) ---- */
#define CO2_LOW    800
#define CO2_HIGH   1200

/* ---- Sampling ---- */
#define SAMPLE_INTERVAL_S 5

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/*  CRC-8 (Sensirion polynomial 0x31, init 0xFF) — used for CRC-4     */
/*  in the SCD30 status / measurement words.  We compute the full     */
/*  8-bit CRC so the 4-bit CRC-4 is the top nibble of the result.      */
/* ------------------------------------------------------------------ */
static uint8_t scd30_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/*  Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Write a 16-bit command to the SCD30                                */
/* ------------------------------------------------------------------ */
static int scd30_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Read a 3-byte measurement frame (CO2, T, RH, CRC)                  */
/* ------------------------------------------------------------------ */
static int scd30_read_measurement(int handle, uint16_t *co2,
                                  float *temp, float *rh)
{
    uint8_t buf[9];

    /*
     * SCD30 measurement frame (datasheet):
     *   buf[0..1] : CO2 (big-endian, 16-bit)
     *   buf[2]   : T (big-endian, 16-bit, bits 15..4 = temp, bits 3..0 = 0)
     *   buf[3]   : RH (big-endian, 16-bit, bits 15..4 = RH, bits 3..0 = 0)
     *   buf[4..5] : CRC for CO2
     *   buf[6]   : CRC for T
     *   buf[7]   : CRC for RH
     *   buf[8]   : status word (CRC-4 in top nibble)
     */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9)
        return -1;

    /* CRC checks */
    if (scd30_crc8(&buf[0], 2) != buf[4]) return -2;
    if (scd30_crc8(&buf[2], 2) != buf[6]) return -2;
    if (scd30_crc8(&buf[3], 2) != buf[7]) return -2;

    /* Status word — bit 7 = data ready */
    uint8_t status = buf[8];
    if (!(status & SCD30_DATA_READY_BIT))
        return -3;

    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw   = ((uint16_t)buf[2] << 8) | buf[3];
    uint16_t rh_raw  = ((uint16_t)buf[3] << 8) | buf[4];

    *co2 = co2_raw;
    *temp = (float)t_raw / 65536.0f * 100.0f;
    *rh  = (float)rh_raw / 65536.0f * 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Log one CSV line                                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t co2, float temp, float rh)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/*  Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static void control_ventilation(uint16_t co2)
{
    if (co2 < CO2_LOW) {
        printf("CO2 low (%u ppm) — ventilation OFF\n", co2);
    } else if (co2 < CO2_HIGH) {
        printf("CO2 moderate (%u ppm) — ventilation LOW\n", co2);
    } else {
        printf("CO2 high (%u ppm) — ventilation HIGH\n", co2);
    }
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus 1 at SCD30 address ---- */
    g_i2c_handle = i2cOpen(1, SCD30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus 1 at 0x%02X (handle=%d).\n",
                SCD30_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen("air_quality.log", "a");
    if (!g_log_file) {
        perror("Error opening air_quality.log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD30 monitor started. Logging to air_quality.log every %d s.\n",
           SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        uint16_t co2 = 0;
        float    temp = 0.0f, rh = 0.0f;
        int      rc;

        /* Trigger measurement */
        if (scd30_write_cmd(g_i2c_handle, SCD30_MEASURE_CMD) != 0) {
            fprintf(stderr, "Warning: failed to send measurement command.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Wait for conversion */
        gpioDelay(SCD30_MEASURE_DELAY_US);

        /* Read result */
        rc = scd30_read_measurement(g_i2c_handle, &co2, &temp, &rh);
        if (rc == 0) {
            log_data(g_log_file, co2, temp, rh);
            control_ventilation(co2);
        } else {
            const char *err = "unknown";
            switch (rc) {
                case -1: err = "I2C read failed"; break;
                case -2: err = "CRC mismatch";      break;
                case -3: err = "data not ready";     break;
            }
            fprintf(stderr, "Warning: SCD30 read failed (%s).\n", err);
        }

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

