 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 * Run:    ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SDP32_I2C_BUS        "/dev/i2c-1"
#define SDP32_I2C_ADDR       0x50          /* SDP32 default 7-bit address */
#define SDP32_READ_INTERVAL  1000          /* default sampling interval in ms */
#define SDP32_READ_LEN       9             /* 3 words × (2 data + 1 CRC) */
#define SDP32_MEAS_DELAY_US  20000         /* 20 ms measurement settle */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sdp32_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read exactly `len` bytes from the sensor.
 * Returns 0 on success, -1 on I/O error, -2 on sensor-absent (0-length read).
 */
static int sdp32_read_measurement(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EIO || errno == EREMOTEIO) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            return -1;
        }
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "Sensor absent or bus error: read %zd of %zu bytes\n",
                n, len);
        return -2;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC validation                                                      */
/* ------------------------------------------------------------------ */
static bool verify_crc(const uint8_t *word, uint8_t expected_crc)
{
    uint8_t calc = sdp32_crc8(word, 2);
    return (calc == expected_crc);
}

/* ------------------------------------------------------------------ */
/* Conversion                                                          */
/* ------------------------------------------------------------------ */
static void convert_sdp32(const uint8_t *raw,
                          float *pressure, float *temperature)
{
    int16_t p_raw    = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t t_raw    = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t scale_raw = (int16_t)((raw[6] << 8) | raw[7]);

    *pressure    = (float)p_raw / (float)scale_raw;
    *temperature = (float)t_raw / 65536.0f;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval = SDP32_READ_INTERVAL;

    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval '%s'. Using default %d ms.\n",
                    argv[1], SDP32_READ_INTERVAL);
            interval = SDP32_READ_INTERVAL;
        }
    }

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(SDP32_I2C_BUS, SDP32_I2C_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    printf("SDP32 reader started. Interval: %d ms. Press Ctrl+C to exit.\n",
           interval);

    while (g_running) {
        uint8_t raw[SDP32_READ_LEN];

        if (sdp32_read_measurement(g_i2c_fd, raw, SDP32_READ_LEN) != 0) {
            fprintf(stderr, "Sensor read failed. Exiting.\n");
            break;
        }

        /* CRC checks */
        if (!verify_crc(&raw[0], raw[2])) {
            fprintf(stderr, "Pressure CRC mismatch. Exiting.\n");
            break;
        }
        if (!verify_crc(&raw[3], raw[5])) {
            fprintf(stderr, "Temperature CRC mismatch. Exiting.\n");
            break;
        }
        if (!verify_crc(&raw[6], raw[8])) {
            fprintf(stderr, "Scale-factor CRC mismatch. Exiting.\n");
            break;
        }

        float pressure, temperature;
        convert_sdp32(raw, &pressure, &temperature);

        char ts[32];
        timestamp_str(ts, sizeof(ts));
        printf("[%s] Pressure: %.2f Pa, Temperature: %.2f °C\n",
               ts, pressure, temperature);
        fflush(stdout);

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < interval / 100 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

