/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (I2C bus 1):
 *   SDA  -> GPIO2  (pin 3)
 *   SCL  -> GPIO3  (pin 5)
 *   VDD  -> 3.3 V
 *   GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -lpigpio -lrt
 * Run:    sudo ./sdp810
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50          /* SDP810 default 7-bit address */
#define READ_INTERVAL  1             /* seconds between readings */
#define CONV_DELAY_US  45000         /* 45 ms conversion wait */

/* SDP810 command: continuous measurement, mass flow / differential pressure */
#define CMD_MSB        0x36
#define CMD_LSB        0x2F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Sensor data structure                                               */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;       /* Pa */
    float temperature;    /* °C */
} sensor_data_t;

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame                                   */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, sensor_data_t *out)
{
    uint8_t cmd[2] = { CMD_MSB, CMD_LSB };
    uint8_t buf[9];

    /* Trigger a continuous measurement */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned short read\n");
        return -1;
    }

    /* CRC validation on each 3-byte word */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&buf[6], 2, buf[8])) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    /* Parse big-endian signed values */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    /*
     * Scale factors are 16-bit big-endian; the SDP810 datasheet provides
     * the conversion formulas.  Here we use the default scale factors
     * for the 125 Pa variant (pressure: 256 counts/Pa, temperature:
     * 256 counts/°C).  Adjust if a different variant is used.
     */
    const int32_t scale_pressure = 256;
    const int32_t scale_temp     = 256;

    out->pressure    = (float)raw_pressure    / (float)scale_pressure;
    out->temperature = (float)raw_temp        / (float)scale_temp;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP810 address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 differential pressure sensor reader\n");
    printf("Bus %d, address 0x%02X, interval %d s\n", I2C_BUS, I2C_ADDR, READ_INTERVAL);
    fflush(stdout);

    while (g_running) {
        sensor_data_t data;

        if (read_sensor_data(g_i2c_handle, &data) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   data.pressure, data.temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

