#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define CONVERSION_DELAY_MS 20
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_hdc1000(int fd, float *temperature, float *humidity) {
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) {
        return -1;
    }
    usleep(CONVERSION_DELAY_MS * 1000);

    uint16_t raw_temp, raw_hum;
    if (i2c_read_reg16(fd, 0x00, &raw_temp) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, 0x03, &raw_hum) < 0) {
        return -1;
    }

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading HDC1000 sensor data.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

