        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading HDC1000 sensor data.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
