 *   bit 1   = ODR (0 = 1 Hz, 1 = 10 Hz)
 *   bit 2   = OS (one-shot)
 *   bit 3   = MEAS (measurement enable)
 *   bits 4-7 = reserved
 */
#define MLX90833_CFG_MODE_CONT  0x0001
#define MLX90833_CFG_ODR_10HZ   0x0002
#define MLX90833_CFG_MEAS_EN   0x0008

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register pointer.                  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int mlx_write_reg(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)(value >> 8);
    buf[3] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X, val=0x%04X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register pointer.                 */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int mlx_read_reg(int handle, uint16_t reg, uint16_t *out)
{
    char ptr[2];
    char data[2];

    ptr[0] = (char)(reg >> 8);
    ptr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, ptr, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg ptr=0x%04X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 24-bit two's-complement pressure value.                    */
/* Returns 0 on success and stores the signed value in *pressure_pa.   */
/* ------------------------------------------------------------------ */
static int mlx_read_pressure(int handle, int32_t *pressure_pa)
{
    uint16_t raw;
    if (mlx_read_reg(handle, MLX90833_REG_PRESSURE, &raw) != 0)
        return -1;

    /*
     * The pressure register is 24 bits: [31:8] = data, [7:0] = 0.
     * Sign-extend from 24 bits to 32 bits.
     */
    int32_t signed_val = (int32_t)raw << 8;
    if (signed_val & 0x00800000)
        signed_val |= 0xFF000000;

    *pressure_pa = signed_val;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put the sensor in standby before closing. */
        (void)mlx_write_reg(g_i2c_handle, MLX90833_REG_CONFIG, 0x0000);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(MLX90833_I2C_BUS, MLX90833_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                MLX90833_I2C_BUS, MLX90833_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with a config-register read ---- */
    uint16_t cfg_readback = 0;
    if (mlx_read_reg(g_i2c_handle, MLX90833_REG_CONFIG, &cfg_readback) != 0) {
        fprintf(stderr, "[FATAL] MLX90833 not responding at 0x%02X on bus %d\n",
                MLX90833_I2C_ADDR, MLX90833_I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure: continuous mode, 10 Hz ODR, measurement enabled ---- */
    uint16_t cfg = MLX90833_CFG_MODE_CONT | MLX90833_CFG_ODR_10HZ |
                   MLX90833_CFG_MEAS_EN;
    if (mlx_write_reg(g_i2c_handle, MLX90833_REG_CONFIG, cfg) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure MLX90833\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90833 reader started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int32_t pressure_pa;
        if (mlx_read_pressure(g_i2c_handle, &pressure_pa) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("%s  Pressure: %d Pa\n", ts, pressure_pa);
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Pressure read failed; continuing.\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

