/*
 * Raspberry Pi Zero W – TDK ICP-10101 barometric pressure sensor reader
 *
 * Wiring:
 *   ICP-10101 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10101 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10101 VDD -> 3.3 V
 *   ICP-10101 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10101 icp10101.c -lpigpio -lrt
 * Run:    sudo ./icp10101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x60          /* ICP-10101 default I2C address */
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MEAS_DELAY_US  7000          /* 7 ms measurement conversion time */

/* ---- ICP-10101 register addresses ---- */
#define REG_TEMP_LOW   0x04
#define REG_TEMP_HIGH  0x05
#define REG_PRESS_LOW  0x06
#define REG_PRESS_HIGH 0x07
#define REG_CMD        0x08

/* ---- Command codes ---- */
#define CMD_MEASURE    0x3600       /* bit[15]=1 -> start measurement */
#define CMD_RESET      0x8000       /* bit[15]=0 -> reset device */

/* ---- Default / error sentinel values ---- */
#define TEMP_ERROR     (-1000.0f)
#define PRESS_ERROR    (-1.0f)

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the ICP-10101 command register.          */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int icp_write_cmd(int handle, uint16_t cmd)
{
    char buf[2] = { (char)(cmd & 0xFF), (char)((cmd >> 8) & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(cmd 0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register pair.                             */
/* Returns 0 on success and stores the value in *out; -1 on failure.   */
/* ------------------------------------------------------------------ */
static int icp_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg 0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement, wait for conversion, then read results.     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int icp_read_measurement(int handle, float *temperature, float *pressure)
{
    uint16_t raw_temp, raw_press;

    /* 1. Trigger a measurement */
    if (icp_write_cmd(handle, CMD_MEASURE) != 0)
        return -1;

    /* 2. Wait for conversion to complete (datasheet: typ ~3.5 ms) */
    gpioDelay(MEAS_DELAY_US);

    /* 3. Read temperature */
    if (icp_read_reg16(handle, REG_TEMP_LOW, &raw_temp) != 0)
        return -1;

    /* 4. Read pressure */
    if (icp_read_reg16(handle, REG_PRESS_LOW, &raw_press) != 0)
        return -1;

    /* 5. Convert raw values to physical units (datasheet formulas) */
    *temperature = (float)raw_temp / 100.0f;
    *pressure    = (float)raw_press / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Detect sensor-absent / bus-error pattern: negative read or all     */
/* default bytes.  Returns true if the sensor is likely absent.        */
/* ------------------------------------------------------------------ */
static bool is_sensor_absent(int handle)
{
    char buf[2];
    int n = i2cReadI2CBlockData(handle, REG_TEMP_LOW, buf, 2);
    if (n < 0)
        return true;                       /* I2C bus error */
    if (n == 0)
        return true;                       /* no device at address */

    /*
     * If the device is present but returns the default (0x0000)
     * repeatedly, it may be absent or not responding.
     */
    uint16_t t = (uint16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    if (icp_read_reg16(handle, REG_PRESS_LOW, &raw_press) == 0) {
        uint16_t p = raw_press;
        return (t == 0x0000 && p == 0x0000);
    }
    return true;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without handler\n");
    }

    printf("ICP-10101 reader started (bus %d, addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, I2C_ADDR);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature = TEMP_ERROR;
        float pressure    = PRESS_ERROR;
        bool ok = false;

        if (is_sensor_absent(g_i2c_handle)) {
            fprintf(stderr, "[ERROR] Sensor absent or bus error – "
                            "check wiring and I2C address.\n");
        } else {
            if (icp_read_measurement(g_i2c_handle, &temperature, &pressure) == 0) {
                ok = true;
            } else {
                fprintf(stderr, "[ERROR] Measurement read failed.\n");
            }
        }

        /* ---- Timestamped output ---- */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

        if (ok) {
            printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                   ts, temperature, pressure);
        } else {
            printf("%s - Sensor read failed\n", ts);
        }
        fflush(stdout);

        /* ---- Sleep for the remainder of the period ---- */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

