/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (I2C bus 1, BCM numbering):
 *   SDA  -> GPIO2  (pin 3)
 *   SCL  -> GPIO3  (pin 5)
 *   VDD  -> 3.3 V
 *   GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c
 * Run:    sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50          /* SDP800 default 7-bit address */
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms measurement wait */
#define MAX_RETRIES    3

/* SDP800 command: start continuous measurement, mass flow / differential */
static const uint8_t CMD_MEAS[2] = { 0x36, 0x80 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 2-byte command to the sensor                                */
/* ------------------------------------------------------------------ */
static int sdp_write_cmd(uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor                            */
/* ------------------------------------------------------------------ */
static int sdp_read_bytes(uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice: expected %zu bytes, got %d (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read 9 bytes (3 words + 3 CRCs)           */
/* ------------------------------------------------------------------ */
static int sdp_read_measurement(float *pressure, float *temperature)
{
    if (sdp_write_cmd(CMD_MEAS[0], CMD_MEAS[1]) != 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);   /* 45 ms */

    uint8_t data[9];
    if (sdp_read_bytes(data, sizeof(data)) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    *pressure    = (float)raw_pressure;
    *temperature = (float)raw_temp / 200.0f;   /* deg C */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to file                                               */
/* ------------------------------------------------------------------ */
static void log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(fp, "unknown,%.2f,%.2f\n", pressure, temperature);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800 HVAC airflow monitor started.  Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp_read_measurement(&pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000);   /* 10 ms back-off */
        }

        if (ok) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa | Temp: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] sensor read failed after %d attempts\n",
                    MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

