#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x50
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_PERIOD  1000000  /* microseconds (1 s) */
#define MEASURE_DELAY  8000     /* microseconds (8 ms) */

/* SDP800 command: continuous measurement, no averaging, no clock stretching */
#define CMD_MEASURE    0x3600

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp800(int fd, float *pressure_pa)
{
    if (i2c_write_cmd(fd, CMD_MEASURE) < 0)
        return -1;

    usleep(MEASURE_DELAY);

    uint8_t data[3];
    if (i2c_read_data(fd, data, 3) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *pressure_pa = (float)raw / 100.0f;   /* Pa */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure_pa)
{
    int need_header = (access(filename, F_OK) != 0);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "Timestamp,Pressure_Pa\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", ts, pressure_pa);
    } else {
        fprintf(fp, "unknown,%.2f\n", pressure_pa);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP800 airflow monitor started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float pressure;
        if (read_sdp800(g_i2c_fd, &pressure) == 0) {
            if (log_data(LOG_FILE, pressure) < 0)
                fprintf(stderr, "Logging failed; continuing\n");
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle\n");
        }
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

