#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define LOG_FILE "pressure_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

/* MLX90821 register addresses (from datasheet) */
#define MLX90821_REG_PRESSURE_MSB 0x00
#define MLX90821_REG_PRESSURE_LSB 0x01
#define MLX90821_REG_CONFIG 0x02

#define MIN_SAFE_PRESSURE 200.0f
#define MAX_SAFE_PRESSURE 250.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int init_i2c(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }

    /* Configure sensor: enable pressure measurement, set sample rate */
    if (i2cWriteByteData(i2c_handle, MLX90821_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_pressure(float *pressure_out)
{
    int msb, lsb;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        msb = i2cReadByteData(i2c_handle, MLX90821_REG_PRESSURE_MSB);
        if (msb < 0) {
            fprintf(stderr, "I2C read error (MSB) attempt %d/%d: %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            if (init_i2c() != 0) {
                return -1;
            }
            gpioDelay(100000); /* 100 ms */
            continue;
        }

        lsb = i2cReadByteData(i2c_handle, MLX90821_REG_PRESSURE_LSB);
        if (lsb < 0) {
            fprintf(stderr, "I2C read error (LSB) attempt %d/%d: %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            if (init_i2c() != 0) {
                return -1;
            }
            gpioDelay(100000);
            continue;
        }

        int16_t raw = (int16_t)((msb << 8) | lsb);
        *pressure_out = (float)raw * 0.1f; /* kPa per LSB */
        return 0;
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void check_pressure_range(float pressure)
{
    if (pressure < MIN_SAFE_PRESSURE || pressure > MAX_SAFE_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa is outside safe range [%.0f, %.0f] kPa\n",
                pressure, MIN_SAFE_PRESSURE, MAX_SAFE_PRESSURE);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(log_file, 0, SEEK_END) == 0) {
        long size = ftell(log_file);
        if (size == 0) {
            if (fprintf(log_file, "timestamp,pressure_kPa\n") < 0 || fflush(log_file) != 0) {
                fprintf(stderr, "Error writing header: %s\n", strerror(errno));
            }
        }
    } else {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float pressure;

        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure, exiting.\n");
            break;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

