#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x28
#define LOG_FILE       "environmental_data.log"
#define LOG_SIZE_LIMIT (1024 * 1024)
#define MEASURE_DELAY_US 40000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_hih6130(int fd, float *temp, float *hum) {
    uint8_t buf[3];

    if (i2c_write_cmd(fd, 0x01) < 0) return -1;
    usleep(MEASURE_DELAY_US);

    if (i2c_read_data(fd, buf, 3) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint8_t status = buf[2];

    if (status & 0x01) {
        fprintf(stderr, "HIH6130 status error: 0x%02X\n", status);
        return -1;
    }

    *hum = ((float)raw / 16383.0f) * 100.0f;
    *temp = ((float)(raw & 0x7FFF) / 16383.0f) * 165.0f - 40.0f;

    return 0;
}

static void log_data(FILE *fp, float temp, float hum) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HIH6130_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HIH6130_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long fsize = ftell(g_log_fp);
    if (fsize > LOG_SIZE_LIMIT) {
        if (fseek(g_log_fp, 0, SEEK_SET) < 0 || ftruncate(fileno(g_log_fp), 0) < 0) {
            fprintf(stderr, "Failed to truncate log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("Starting HIH6130 logging to %s (max %d bytes)...\n", LOG_FILE, LOG_SIZE_LIMIT);

    while (g_running) {
        float temp, hum;

        if (read_hih6130(g_i2c_fd, &temp, &hum) == 0) {
            log_data(g_log_fp, temp, hum);
            printf("T=%.2f C  H=%.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }

        fseek(g_log_fp, 0, SEEK_END);
        fsize = ftell(g_log_fp);
        if (fsize > LOG_SIZE_LIMIT) {
            if (fseek(g_log_fp, 0, SEEK_SET) < 0 || ftruncate(fileno(g_log_fp), 0) < 0) {
                fprintf(stderr, "Log truncation failed: %s\n", strerror(errno));
            }
        }
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

