/*
 * MLX90824 SENT Pressure Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX90824 SENT_OUT -> GPIO4 (BCM 4, physical pin 7)
 *   MLX90824 VDD     -> 3.3 V (physical pin 1)
 *   MLX90824 GND     -> GND  (physical pin 9)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90824_sent mlx90824_sent.c
 *
 * Run:
 *   ./mlx90824_sent
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SENT_GPIO          4          /* BCM 4 (physical pin 7) */
#define LOG_FILE           "pressure_log.txt"
#define SAMPLE_PERIOD_US   100000     /* 100 ms between samples */
#define SYNC_TIMEOUT_US    1000000    /* 1 s timeout waiting for sync pulse */
#define MAX_NIBBLES        8          /* 1 status + 3 data + 1 checksum */
#define MIN_TICK_US        36         /* 12 ticks * 3 us/tick */
#define MAX_TICK_US        813        /* 271 ticks * 3 us/tick */
#define SYNC_TICKS         56         /* 188 us / 3 us/tick */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Timing Helpers ----------------------------- */

/*
 * Wait for the line to reach the requested level, or until timeout.
 * Returns 0 on success, -1 on timeout or error.
 */
static int wait_level(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/*
 * Measure the duration of a pulse of the given level.
 * Returns pulse width in microseconds, or -1 on timeout.
 */
static int measure_pulse(int gpio, int level, uint32_t timeout_us)
{
    if (wait_level(gpio, level, timeout_us) != 0)
        return -1;

    uint32_t start = gpioTick();
    if (wait_level(gpio, !level, timeout_us) != 0)
        return -1;

    return (int)(gpioTick() - start);
}

/* ----------------------------- SENT Parsing -------------------------------- */

/*
 * Read one SENT frame and decode the nibbles.
 * Returns 0 on success, -1 on error.
 */
static int read_sent_frame(int gpio, uint8_t nibbles[MAX_NIBBLES])
{
    uint32_t start = gpioTick();

    /* Wait for the falling edge of the sync pulse (line goes low). */
    if (wait_level(gpio, 0, SYNC_TIMEOUT_US) != 0) {
        fprintf(stderr, "Error: SENT sync pulse timeout (sensor absent or bus error).\n");
        return -1;
    }

    /* Measure the sync pulse width. */
    int sync_ticks = measure_pulse(gpio, 0, SYNC_TIMEOUT_US);
    if (sync_ticks < 0) {
        fprintf(stderr, "Error: SENT sync pulse measurement timeout.\n");
        return -1;
    }
    if (sync_ticks < 48 || sync_ticks > 64) {
        fprintf(stderr, "Error: SENT sync pulse out of range: %d ticks.\n", sync_ticks);
        return -1;
    }

    /* Read up to MAX_NIBBLES nibbles. */
    for (int i = 0; i < MAX_NIBBLES; i++) {
        int pulse_us = measure_pulse(gpio, 0, SYNC_TIMEOUT_US);
        if (pulse_us < 0) {
            fprintf(stderr, "Error: SENT nibble %d timeout.\n", i);
            return -1;
        }

        if (pulse_us < MIN_TICK_US || pulse_us > MAX_TICK_US) {
            fprintf(stderr, "Error: SENT nibble %d out of range: %d us.\n", i, pulse_us);
            return -1;
        }

        int ticks = pulse_us / 3;          /* 3 us per tick */
        nibbles[i] = (uint8_t)(ticks - 12); /* 12 ticks = nibble 0 */
    }

    return 0;
}

/*
 * Convert the four data nibbles into a 16-bit pressure value.
 * Data nibbles are MSB-first: [nibble3, nibble2, nibble1, nibble0].
 */
static uint16_t decode_pressure(const uint8_t nibbles[MAX_NIBBLES])
{
    uint16_t pressure = ((uint16_t)nibbles[3] << 12) |
                        ((uint16_t)nibbles[2] << 8)  |
                        ((uint16_t)nibbles[1] << 4)  |
                        ((uint16_t)nibbles[0]);
    return pressure;
}

/* ----------------------------- Logging ------------------------------------ */

static void log_pressure(uint16_t pressure)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Pressure: %u.%u Pa\n",
            timestamp,
            (pressure >> 8) & 0xFF,
            pressure & 0xFF);
    fflush(g_log_fp);
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode. */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "--- MLX90824 SENT Pressure Logger started ---\n");
    fflush(g_log_fp);

    /* Configure GPIO4 as input. */
    if (gpioSetMode(SENT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", SENT_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow the sensor to settle after power-up. */
    gpioDelay(100000); /* 100 ms */

    uint8_t nibbles[MAX_NIBBLES];

    while (g_running) {
        if (read_sent_frame(SENT_GPIO, nibbles) == 0) {
            uint16_t pressure = decode_pressure(nibbles);
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Warning: SENT frame read failed, skipping sample.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown. */
    fprintf(g_log_fp, "--- MLX90824 SENT Pressure Logger stopped ---\n");
    fflush(g_log_fp);
    fclose(g_log_fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

