/*
 * greenhouse_monitor.c — Raspberry Pi Zero W + Adafruit TMP117
 *
 * Monitors greenhouse temperature via I2C and logs each reading as a
 * 4-byte little-endian float to greenhouse_temps.dat every 60 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_monitor greenhouse_monitor.c
 * Run:    ./greenhouse_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- TMP117 constants ---- */
#define TMP117_I2C_ADDR        0x41   /* 7-bit address */
#define TMP117_REG_CONFIG      0x00   /* Configuration register */
#define TMP117_REG_TEMP_LOW    0x01   /* Temperature MSB */
#define TMP117_REG_TEMP_HIGH   0x02   /* Temperature LSB */
#define TMP117_REG_DEVICE_ID   0x0C   /* Device ID register */
#define TMP117_EXPECTED_ID     0x0B   /* Expected device ID for TMP117 */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_fp       = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register.                           */
/* ------------------------------------------------------------------ */
static int tmp117_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register.                          */
/* ------------------------------------------------------------------ */
static int tmp117_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature in degrees Celsius.                                */
/* ------------------------------------------------------------------ */
static int tmp117_read_temperature(int fd, float *temp_c)
{
    uint8_t lo, hi;

    if (tmp117_read_reg(fd, TMP117_REG_TEMP_LOW, &lo) != 0)
        return -1;
    if (tmp117_read_reg(fd, TMP117_REG_TEMP_HIGH, &hi) != 0)
        return -1;

    /* TMP117 temperature register: 14-bit signed, 2 uA/°C, 0.25 °C LSB */
    int16_t raw = (int16_t)((hi << 6) | (lo >> 2));
    if (raw & 0x2000)
        raw |= 0xC000;          /* sign-extend 14-bit to 16-bit */

    *temp_c = (float)raw / 4.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the device ID matches the expected value.                    */
/* ------------------------------------------------------------------ */
static int tmp117_verify_id(int fd)
{
    uint8_t id;
    if (tmp117_read_reg(fd, TMP117_REG_DEVICE_ID, &id) != 0)
        return -1;
    if (id != TMP117_EXPECTED_ID) {
        fprintf(stderr,
                "Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, TMP117_EXPECTED_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a float as 4 little-endian bytes to the file.                 */
/* ------------------------------------------------------------------ */
static int write_float_le(FILE *fp, float f)
{
    uint8_t buf[4];
    memcpy(buf, &f, sizeof(f));
    if (fwrite(buf, 1, sizeof(buf), fp) != (size_t)sizeof(buf)) {
        fprintf(stderr, "File write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (GPIO2/3 on Pi Zero W) */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                TMP117_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (tmp117_verify_id(g_i2c_fd) != 0) {
        fprintf(stderr, "TMP117 not detected at address 0x%02X\n",
                TMP117_I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open binary log file */
    g_fp = fopen("greenhouse_temps.dat", "wb");
    if (g_fp == NULL) {
        fprintf(stderr, "Cannot open greenhouse_temps.dat: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging every 60 s. Press Ctrl-C to stop.\n");

    while (g_running) {
        float temp_c;
        if (tmp117_read_temperature(g_i2c_fd, &temp_c) == 0) {
            printf("Temperature: %.2f °C\n", temp_c);
            if (write_float_le(g_fp, temp_c) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Temperature read failed; will retry next cycle.\n");
        }

        /* Sleep 60 s, but wake early on signal */
        for (int i = 0; i < 60 && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

