    running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int cb_write_to_file(const CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    size_t written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (written != (size_t)cb->count) {
        fprintf(stderr, "Error writing to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TMP117_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }
    uint16_t temp_raw = (uint16_t)raw;
    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(handle, TMP117_CONFIG_REG, TMP117_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Error writing TMP117 config: %s\n", strerror(errno));
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    while (running) {
        float temperature;
        if (read_temperature(handle, &temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        if (cb_write_to_file(&temp_buffer, LOG_FILE) != 0) {
            fprintf(stderr, "Warning: failed to persist buffer to file.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
    }

    if (cb_write_to_file(&temp_buffer, LOG_FILE) != 0) {
        fprintf(stderr, "Warning: failed to persist buffer to file on exit.\n");
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

