#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000

#define REG_STATUS 0x00
#define REG_SPEED_H 0x01
#define REG_SPEED_L 0x02
#define REG_TEMP_H 0x03
#define REG_TEMP_L 0x04
#define REG_CONFIG 0x05

#define STATUS_READY 0x00
#define STATUS_MEASURING 0x01

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d)\n",
                I2C_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int configure_sensor(void) {
    char config_data[2] = {0x00, 0x00};

    if (i2cWriteI2CBlockData(i2c_handle, REG_CONFIG, config_data, 2) < 0) {
        fprintf(stderr, "Error: Failed to write configuration register (0x%02X)\n", REG_CONFIG);
        return -1;
    }

    return 0;
}

static int read_sensor_data(float *speed, float *temperature) {
    char status;
    char speed_data[2];
    char temp_data[2];
    int16_t raw_speed;
    int16_t raw_temp;

    if (i2cReadI2CBlockData(i2c_handle, REG_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read status register (0x%02X)\n", REG_STATUS);
        return -1;
    }

    if ((status & STATUS_READY) == 0) {
        fprintf(stderr, "Warning: Sensor not ready (status=0x%02X)\n", (uint8_t)status);
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, REG_SPEED_H, speed_data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read speed data (0x%02X)\n", REG_SPEED_H);
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, REG_TEMP_H, temp_data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data (0x%02X)\n", REG_TEMP_H);
        return -1;
    }

    raw_speed = (int16_t)((speed_data[0] << 8) | speed_data[1]);
    raw_temp = (int16_t)((temp_data[0] << 8) | temp_data[1]);

    *speed = (float)raw_speed;
    *temperature = (float)raw_temp;

    return 0;
}

static int log_data(float speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, speed, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float speed, temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Speed,Temperature\n") < 0) {
            fprintf(stderr, "Error: Failed to write CSV header\n");
            cleanup();
            return 1;
        }
        fflush(log_file);
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (program_running) {
        if (read_sensor_data(&speed, &temperature) == 0) {
            if (log_data(speed, temperature) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Logging NaN values.\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Error: Failed to log NaN values\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

