#define TMP117_TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TMP117_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }
    uint16_t temp_raw = (uint16_t)raw;
    *temperature = ((float)((temp_raw >> 12) & 0x0FFF)) / 16.0f;
    return 0;
}

static int log_temperature(float temperature) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time\n");
        return -1;
    }
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }
    char timestamp[20];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, attempting to reinitialize I2C...\n");
            int reinit_attempts = 0;
            while (running && reinit_attempts < MAX_REINIT_ATTEMPTS) {
                if (init_i2c() == 0) {
                    break;
                }
                reinit_attempts++;
                sleep(1);
            }
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Failed to reinitialize I2C after %d attempts, exiting\n", MAX_REINIT_ATTEMPTS);
                break;
            }
        }
        sleep(1);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

