    nanosleep(&ts, NULL);
}

/* ---- DHT11 timing helpers ---- */

static int wait_for_level(int target, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpio_read(DHT11_GPIO) != target) {
        gpio_delay_us(1);
        elapsed++;
        if (elapsed >= timeout_us) {
            return -1;
        }
    }
    return 0;
}

static int read_bit(void) {
    if (wait_for_level(1, 100) < 0) return -1;
    gpio_delay_us(40);
    int level = gpio_read(DHT11_GPIO);
    gpio_delay_us(40);
    return level;
}

/* ---- DHT11 protocol ---- */

static int dht11_read(int *humidity, int *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;

    /* Start signal: pull low for >= 18 ms, then release */
    gpio_set_direction(DHT11_GPIO, 1);
    gpio_write(DHT11_GPIO, 0);
    gpio_delay_us(20000);
    gpio_write(DHT11_GPIO, 1);
    gpio_set_direction(DHT11_GPIO, 0);

    /* Wait for sensor response: ~80 us low, ~80 us high */
    if (wait_for_level(0, 100) < 0) return -1;
    if (wait_for_level(1, 100) < 0) return -1;
    if (wait_for_level(0, 100) < 0) return -1;

    /* Read 40 data bits */
    for (int i = 0; i < 40; i++) {
        if (wait_for_level(0, 100) < 0) return -1;
        int high_us = 0;
        while (gpio_read(DHT11_GPIO) == 1) {
            gpio_delay_us(1);
            high_us++;
            if (high_us > 100) return -1;
        }
        data[bit_idx] <<= 1;
        if (high_us > 50) {
            data[bit_idx] |= 1;
        }
        bit_idx = (bit_idx + 1) % 5;
    }

    *humidity = (data[0] << 8) | data[1];
    *temperature = (data[2] << 8) | data[3];

    /* Checksum */
    int checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        return -2;
    }

    return 0;
}

