/*
 * ADPD105 dual-sensor correlated color temperature logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   ADPD105 #1  SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3.3 V, GND -> GND
 *   ADPD105 #2  SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3.3 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o cct_logger cct_logger.c -lpigpio -lrt
 * Run:    sudo ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADPD105 constants (from datasheet) ---- */
#define ADPD105_I2C_BUS        1
#define ADPD105_I2C_ADDR_BASE  0x50
#define ADPD105_I2C_ADDR_MASK  0x01

#define ADPD105_REG_RESULT     0x00
#define ADPD105_REG_CONFIG     0x01
#define ADPD105_REG_ID         0x0F

#define ADPD105_ID_EXPECTED    0x105

/* Config word: 16-bit value written to CONFIG register.
 * Bits [15:12] = LED current (0x03 = ~1.5 mA)
 * Bits [11:8]  = ADC range (0x03 = 1024 counts)
 * Bits [7:4]   = Photodiode range (0x03 = 1024 counts)
 * Bits [3:0]   = Integration time (0x03 = ~100 us)
 */
#define ADPD105_CONFIG_WORD    0x0303

/* ---- Application constants ---- */
#define LOG_FILE_NAME          "cct_log.csv"
#define SAMPLE_INTERVAL_US     1000000  /* 1 second */
#define MAX_SENSORS            2

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[MAX_SENSORS];
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADPD105 register.                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd105_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ADPD105] write reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADPD105 register.                        */
/* Returns 0 on success and stores value in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int adpd105_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ADPD105] write reg-select 0x%02X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ADPD105] read reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize one ADPD105 sensor.                                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adpd105_init(int handle)
{
    uint16_t id = 0;

    if (adpd105_read_reg(handle, ADPD105_REG_ID, &id) != 0) {
        fprintf(stderr, "[ADPD105] sensor not responding on handle %d\n",
                handle);
        return -1;
    }
    if (id != ADPD105_ID_EXPECTED) {
        fprintf(stderr, "[ADPD105] ID mismatch: got 0x%04X, expected 0x%04X\n",
                id, ADPD105_ID_EXPECTED);
        return -1;
    }

    if (adpd105_write_reg(handle, ADPD105_REG_CONFIG, ADPD105_CONFIG_WORD) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit result register from an ADPD105.                    */
/* Returns 0 on success and stores value in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int adpd105_read_result(int handle, uint16_t *out)
{
    return adpd105_read_reg(handle, ADPD105_REG_RESULT, out);
}

/* ------------------------------------------------------------------ */
/* Compute correlated color temperature from two photodiode counts.   */
/* Uses the simplified method from the ADPD105 datasheet.              */
/* ------------------------------------------------------------------ */
static double calculate_cct(uint16_t p1, uint16_t p2)
{
    if (p1 == 0 || p2 == 0)
        return 0.0;

    double x = (double)p1 / (double)(p1 + p2);
    double y = (double)p2 / (double)(p1 + p2);

    double n = -449.0 * x + 3525.0;
    double c = 3.0 * x - 27.0 * x * x - 3.0 * y + 27.0 * y * y;
    double f = 903.0 * x * x - 1281.0 * x * x * x + 3133.0 * x * y * y -
               2841.0 * x * y * y * y + 6810.0 * y * y * y * y;

    double z = (n * n - 4.0 * c) / (2.0 * f);
    if (z < 0.0 || z > 1.0)
        return 0.0;

    double t = 449.0 * z + 168.0;
    return t;
}

/* ------------------------------------------------------------------ */
/* Log one CCT reading to the CSV file.                                 */
/* ------------------------------------------------------------------ */
static void log_data(double cct)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f\n", timestamp, cct);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int addresses[MAX_SENSORS] = {
        ADPD105_I2C_ADDR_BASE,
        (ADPD105_I2C_ADDR_BASE | ADPD105_I2C_ADDR_MASK)
    };

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles ---- */
    for (int i = 0; i < MAX_SENSORS; i++) {
        g_i2c_handles[i] = i2cOpen(ADPD105_I2C_BUS, addresses[i], 0);
        if (g_i2c_handles[i] < 0) {
            fprintf(stderr, "i2cOpen failed for sensor %d (addr 0x%02X): %d\n",
                    i, addresses[i], g_i2c_handles[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Initialize sensors ---- */
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (adpd105_init(g_i2c_handles[i]) != 0) {
            fprintf(stderr, "ADPD105 sensor %d init failed\n", i);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Open log file (create with header if new) ---- */
    int file_exists = (access(LOG_FILE_NAME, F_OK) == 0);
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        fprintf(g_log_file, "Timestamp,Average_CCT\n");
        fflush(g_log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t p1 = 0, p2 = 0;
        int ok1 = 0, ok2 = 0;

        for (int i = 0; i < MAX_SENSORS; i++) {
            if (adpd105_read_result(g_i2c_handles[i], &p1) == 0)
                ok1 = 1;
            if (adpd105_read_result(g_i2c_handles[1 - i], &p2) == 0)
