    }
    *value = (uint8_t)result;
    return 0;
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    uint8_t msb, lsb;

    if (read_register(handle, REG_PRESSURE_MSB, &msb) < 0) {
        return -1;
    }
    if (read_register(handle, REG_PRESSURE_LSB, &lsb) < 0) {
        return -1;
    }
    uint16_t raw_pressure = ((uint16_t)msb << 8) | lsb;
    *pressure = (float)raw_pressure / 100.0f;

    if (read_register(handle, REG_TEMP_MSB, &msb) < 0) {
        return -1;
    }
    if (read_register(handle, REG_TEMP_LSB, &lsb) < 0) {
        return -1;
    }
    uint16_t raw_temp = ((uint16_t)msb << 8) | lsb;
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

