#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0
#define TEMP_THRESHOLD_ON  28.0
#define TEMP_THRESHOLD_OFF 26.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, float *temperature)
{
    char buf[2];
    int  bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (returned %d).\n", bytes_read);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    raw &= 0x7FFF;
    *temperature = (float)raw * 0.125f;
    return 0;
}

static void update_circular_buffer(float temperature, float *buffer, int *index, int buffer_size)
{
    buffer[*index] = temperature;
    *index = (*index + 1) % buffer_size;
}

static float calculate_average(float *buffer, int buffer_size)
{
    float sum = 0.0f;
    for (int i = 0; i < buffer_size; i++)
        sum += buffer[i];
    return sum / (float)buffer_size;
}

static int control_fan(float average_temperature, int *fan_state)
{
    if (*fan_state == 0 && average_temperature > TEMP_THRESHOLD_ON) {
        if (gpioWrite(FAN_GPIO, 1) != 0) {
            fprintf(stderr, "Error: Failed to turn fan ON.\n");
            return -1;
        }
        *fan_state = 1;
        printf("Fan ON (avg %.2f C)\n", average_temperature);
    } else if (*fan_state == 1 && average_temperature < TEMP_THRESHOLD_OFF) {
        if (gpioWrite(FAN_GPIO, 0) != 0) {
            fprintf(stderr, "Error: Failed to turn fan OFF.\n");
            return -1;
        }
        *fan_state = 0;
        printf("Fan OFF (avg %.2f C)\n", average_temperature);
    }
    return 0;
}

int main(void)
{
    float temperature_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    int   fan_state    = 0;
    int   i2c_handle   = -1;
    int   pigpio_init  = -1;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    pigpio_init = gpioInitialise();
    if (pigpio_init < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (%d).\n", pigpio_init);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", FAN_GPIO);
        goto cleanup_gpio;
