    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    printf("LM75B temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: Temperature read failed, retrying next cycle.\n");
        } else {
            update_circular_buffer(temperature, temperature_buffer, &buffer_index, BUFFER_SIZE);
            float average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average_temperature);
            if (control_fan(average_temperature, &fan_state) != 0) {
                fprintf(stderr, "Warning: Fan control failed, retrying next cycle.\n");
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);

cleanup_gpio:
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
