/*
 * SDP810-500Pa differential-pressure sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> Pi GPIO2  (I2C bus 1, pin 3)
 *   SDP810 SCL  -> Pi GPIO3  (I2C bus 1, pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_log sdp810_log.c -lpigpio -lrt
 * Run:    sudo ./sdp810_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50          /* SDP810 default 7-bit address */
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms measurement wait */
#define PRESSURE_THRESH 5.0f        /* warning threshold (Pa) */

/* SDP810 measurement command: continuous mode, no averaging */
static const uint8_t CMD_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR          */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one measurement from the SDP810                               */
/* Returns 0 on success, -1 on I/O or CRC error.                       */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Issue measurement command */
    if (i2cWriteDevice(handle, (char *)CMD_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion (datasheet: typ 45 ms) */
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned != 9 bytes\n");
        return -1;
    }

    /* Validate CRCs */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] scale CRC mismatch\n");
        return -1;
    }

    /* Parse big-endian signed values */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* Scale factors from datasheet */
    *pressure    = (float)raw_pressure    / 100.0f;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one reading                                                      */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (addr 0x%02X): %d\n",
                I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 logging started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
            if (pressure > PRESSURE_THRESH)
                fprintf(stderr, "[WARN] Pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESH);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        /* Sleep but wake promptly on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            gpioDelay(1000000);  /* 1 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

