#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x48
#define STTS2004_REG_TEMP 0x00
#define LED_GPIO       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define MAX_CONSEC_ERR 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, STTS2004_REG_TEMP, &raw) != 0)
        return -1;

    int16_t signed_raw = (int16_t)raw;
    *temp_c = (float)signed_raw / 100.0f;
    return 0;
}

static int control_led(int gpio_pin, float temperature)
{
    static bool led_on = false;

    if (temperature > TEMP_HIGH && !led_on) {
        if (gpioWrite(gpio_pin, 1) != 0) {
            fprintf(stderr, "gpioWrite(high) failed: %s\n", strerror(errno));
            return -1;
        }
        led_on = true;
        printf("Temperature %.2f C > %.1f C -> LED ON\n", temperature, TEMP_HIGH);
    } else if (temperature < TEMP_LOW && led_on) {
        if (gpioWrite(gpio_pin, 0) != 0) {
            fprintf(stderr, "gpioWrite(low) failed: %s\n", strerror(errno));
            return -1;
        }
        led_on = false;
        printf("Temperature %.2f C < %.1f C -> LED OFF\n", temperature, TEMP_LOW);
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed: %s\n", LED_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed: %s\n", LED_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            consecutive_errors = 0;
            printf("Temperature: %.2f C\n", temperature);
            if (control_led(LED_GPIO, temperature) != 0) {
                fprintf(stderr, "LED control failed\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Temperature read failed (attempt %d/%d)\n",
                    consecutive_errors, MAX_CONSEC_ERR);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Max consecutive errors reached. Exiting.\n");
                break;
            }
        }
        sleep(1);
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

