#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x50
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "flow_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X.\n", SDP800_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float pressure, temperature;
    while (!terminate) {
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }
        gpioDelay(100000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

