#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "environment.log"
#define SAMPLE_INTERVAL_SEC 60
#define MAX_RETRIES 3
#define MEASURE_RH_NO_HOLD 0x2C
#define MEASURE_TEMP_NO_HOLD 0x2E
#define READ_TEMP_PREV_RH 0xE0
#define MEASURE_DELAY_US 20000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (g_log_file) {
        fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %s\n", cmd, strerror(errno));
    }
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len) {
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice failed: %s\n", strerror(errno));
    }
    return rc;
}

static int read_sensor_id(int handle, uint8_t *id) {
    if (i2c_write_cmd(handle, 0xFA) < 0) return -1;
    gpioDelay(1000);
    if (i2c_read_bytes(handle, id, 2) < 0) return -1;
    return 0;
}

static int read_temperature(int handle, float *temp_c) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(handle, MEASURE_TEMP_NO_HOLD) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);

        uint8_t buf[2];
        if (i2c_read_bytes(handle, buf, 2) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }
    return -1;
}

static int read_humidity(int handle, float *hum_pct) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(handle, MEASURE_RH_NO_HOLD) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);

        uint8_t buf[2];
        if (i2c_read_bytes(handle, buf, 2) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *hum_pct = (125.0f * raw / 65536.0f) - 6.0f;
        if (*hum_pct < 0.0f) *hum_pct = 0.0f;
        if (*hum_pct > 100.0f) *hum_pct = 100.0f;
        return 0;
    }
    return -1;
}

static int read_temperature_prev(int handle, float *temp_c) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(handle, READ_TEMP_PREV_RH) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(10000);

        uint8_t buf[2];
        if (i2c_read_bytes(handle, buf, 2) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }
    return -1;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t sensor_id[2];
    if (read_sensor_id(g_i2c_handle, sensor_id) < 0) {
        log_error("Sensor not responding on I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Si7021 detected (ID: 0x%02X%02X)\n", sensor_id[0], sensor_id[1]);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_c, hum_pct;
        int rc = read_humidity(g_i2c_handle, &hum_pct);
        if (rc == 0) {
            rc = read_temperature_prev(g_i2c_handle, &temp_c);
        }

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
            fflush(g_log_file);
            printf("%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        } else {
            log_error("Failed to read sensor data after retries");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

