        if (i2c_write_cmd(handle, READ_TEMP_PREV_RH) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(10000);

        uint8_t buf[2];
        if (i2c_read_bytes(handle, buf, 2) < 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }
    return -1;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t sensor_id[2];
    if (read_sensor_id(g_i2c_handle, sensor_id) < 0) {
        log_error("Sensor not responding on I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Si7021 detected (ID: 0x%02X%02X)\n", sensor_id[0], sensor_id[1]);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_c, hum_pct;
        int rc = read_humidity(g_i2c_handle, &hum_pct);
        if (rc == 0) {
            rc = read_temperature_prev(g_i2c_handle, &temp_c);
        }

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
            fflush(g_log_file);
            printf("%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        } else {
            log_error("Failed to read sensor data after retries");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

