        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            if (log_temperature(g_log_fp, temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature reading\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read temperature\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

