#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define SCD40_ADDR 0x50
#define SCD40_CMD_START_PERIODIC 0x3608
#define SCD40_CMD_STOP_PERIODIC 0x3600
#define SCD40_CMD_READ_MEASUREMENT 0x0000
#define SCD40_CMD_READ_MEASUREMENT_EXPECTED_LEN 6
#define SCD40_CMD_START_PERIODIC_DELAY_US 100000
#define SCD40_CMD_STOP_PERIODIC_DELAY_US 10000
#define SCD40_READ_INTERVAL_US 5000000
#define SCD40_BUFFER_SIZE 100
#define SCD40_LOG_DIR "/var/log/scd40_data"
#define SCD40_ERROR_LOG_FILE "/var/log/scd40_error.log"
#define SCD40_CSV_FILE_PREFIX "scd40_data"

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[SCD40_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static circular_buffer_t buffer;
static pthread_t logging_thread;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", SCD40_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int start_periodic_measurement(void) {
    uint8_t cmd[2] = { (SCD40_CMD_START_PERIODIC >> 8) & 0xFF, SCD40_CMD_START_PERIODIC & 0xFF };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Failed to send start periodic measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(SCD40_CMD_START_PERIODIC_DELAY_US);
    return 0;
}

static int stop_periodic_measurement(void) {
    uint8_t cmd[2] = { (SCD40_CMD_STOP_PERIODIC >> 8) & 0xFF, SCD40_CMD_STOP_PERIODIC & 0xFF };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(SCD40_CMD_STOP_PERIODIC_DELAY_US);
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = { (SCD40_CMD_READ_MEASUREMENT >> 8) & 0xFF, SCD40_CMD_READ_MEASUREMENT & 0xFF };
    uint8_t buf[SCD40_CMD_READ_MEASUREMENT_EXPECTED_LEN];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Failed to send read measurement command: %s\n", strerror(errno));
        return -1;
    }

    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, SCD40_CMD_READ_MEASUREMENT_EXPECTED_LEN);
    if (bytes_read != SCD40_CMD_READ_MEASUREMENT_EXPECTED_LEN) {
        fprintf(stderr, "Failed to read sensor data: expected %d bytes, got %d: %s\n", SCD40_CMD_READ_MEASUREMENT_EXPECTED_LEN, bytes_read, strerror(errno));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC check failed for CO2 value\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC check failed for temperature value\n");
        return -1;
    }

    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];

    return 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(SCD40_ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void create_log_directory(void) {
    DIR *dir = opendir(SCD40_LOG_DIR);
    if (dir == NULL) {
        if (mkdir(SCD40_LOG_DIR, 0755) != 0) {
            fprintf(stderr, "Failed to create log directory: %s\n", strerror(errno));
        }
    } else {
        closedir(dir);
    }
}

static void get_timestamp(char *timestamp_str, size_t size) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    strftime(timestamp_str, size, "%Y-%m-%d %H:%M:%S", &tm);
}

static void log_data_to_csv(const char *filename, const sensor_data_t *data) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", filename, strerror(errno));
        return;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");
    }

    char timestamp_str[30];
    get_timestamp(timestamp_str, sizeof(timestamp_str));
    fprintf(fp, "%s,%u,%u,%u\n", timestamp_str, data->co2, data->temperature, data->humidity);
    fclose(fp);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(60);
        if (!running) break;

        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        int head = buffer.head;
        pthread_mutex_unlock(&buffer.mutex);

        if (count > 0) {
            char filename[256];
            snprintf(filename, sizeof(filename), "%s/%s_%ld.csv", SCD40_LOG_DIR, SCD40_CSV_FILE_PREFIX, time(NULL));

            for (int i = 0; i < count; i++) {
                int index = (head + i) % SCD40_BUFFER_SIZE;
                log_data_to_csv(filename, &buffer.data[index]);
            }
        }
    }
    return NULL;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    pthread_mutex_destroy(&buffer.mutex);
}

int main(void) {
    memset(&buffer, 0, sizeof(buffer));
    pthread_mutex_init(&buffer.mutex, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return 1;
    }

    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    create_log_directory();

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create logging thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            pthread_mutex_lock(&buffer.mutex);
            buffer.data[buffer.head] = data;
            buffer.head = (buffer.head + 1) % SCD40_BUFFER_SIZE;
            if (buffer.count < SCD40_BUFFER_SIZE) {
                buffer.count++;
            }
            pthread_mutex_unlock(&buffer.mutex);
        } else {
            char timestamp_str[30];
            get_timestamp(timestamp_str, sizeof(timestamp_str));
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "%s: Failed to read sensor data", timestamp_str);
            log_error(error_message);
        }
        gpioDelay(SCD40_READ_INTERVAL_US);
    }

    pthread_join(logging_thread, NULL);

    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%s_%ld.csv", SCD40_LOG_DIR, SCD40_CSV_FILE_PREFIX, time(NULL));
    pthread_mutex_lock(&buffer.mutex);
    int count = buffer.count;
    int head = buffer.head;
    pthread_mutex_unlock(&buffer.mutex);

    if (count > 0) {
        for (int i = 0; i < count; i++) {
            int index = (head + i) % SCD40_BUFFER_SIZE;
            log_data_to_csv(filename, &buffer.data[index]);
        }
    }

    cleanup();
    return 0;
}

