            snprintf(filename, sizeof(filename), "%s/%s_%ld.csv", SCD40_LOG_DIR, SCD40_CSV_FILE_PREFIX, time(NULL));

            for (int i = 0; i < count; i++) {
                int index = (head + i) % SCD40_BUFFER_SIZE;
                log_data_to_csv(filename, &buffer.data[index]);
            }
        }
    }
    return NULL;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    pthread_mutex_destroy(&buffer.mutex);
}

int main(void) {
    memset(&buffer, 0, sizeof(buffer));
    pthread_mutex_init(&buffer.mutex, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return 1;
    }

    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    create_log_directory();

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create logging thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        sensor_data_t data;
        if (read_sensor_data(&data) == 0) {
            pthread_mutex_lock(&buffer.mutex);
            buffer.data[buffer.head] = data;
            buffer.head = (buffer.head + 1) % SCD40_BUFFER_SIZE;
            if (buffer.count < SCD40_BUFFER_SIZE) {
                buffer.count++;
            }
            pthread_mutex_unlock(&buffer.mutex);
        } else {
            char timestamp_str[30];
            get_timestamp(timestamp_str, sizeof(timestamp_str));
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "%s: Failed to read sensor data", timestamp_str);
            log_error(error_message);
        }
        gpioDelay(SCD40_READ_INTERVAL_US);
    }

    pthread_join(logging_thread, NULL);

    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%s_%ld.csv", SCD40_LOG_DIR, SCD40_CSV_FILE_PREFIX, time(NULL));
    pthread_mutex_lock(&buffer.mutex);
    int count = buffer.count;
    int head = buffer.head;
    pthread_mutex_unlock(&buffer.mutex);

    if (count > 0) {
        for (int i = 0; i < count; i++) {
            int index = (head + i) % SCD40_BUFFER_SIZE;
            log_data_to_csv(filename, &buffer.data[index]);
        }
    }

    cleanup();
    return 0;
}

