#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define TRIGGER_INTERVAL_SEC 5
#define TRIGGER_DELAY_US 10000
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d)\n",
                I2C_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    char trigger_cmd[2] = {0x01, 0x00};
    char data[6];
    int result;

    result = i2cWriteDevice(i2c_handle, trigger_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write trigger command to I2C device (pigpio error %d)\n", result);
        return -1;
    }

    gpioDelay(TRIGGER_DELAY_US);

    result = i2cReadDevice(i2c_handle, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes from I2C device (pigpio returned %d)\n", result);
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)(uint8_t)data[0] << 16) |
                            ((uint32_t)(uint8_t)data[1] << 8)  |
                            ((uint32_t)(uint8_t)data[2]);
    uint32_t raw_temperature = ((uint32_t)(uint8_t)data[3] << 16) |
                               ((uint32_t)(uint8_t)data[4] << 8)  |
                               ((uint32_t)(uint8_t)data[5]);

    *pressure = (float)raw_pressure / 65535.0f * 100.0f;
    *temperature = (float)raw_temperature / 65535.0f * 200.0f - 50.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f °C\n",
            timestamp, pressure, temperature);
    fflush(log_file);

    printf("%s, Pressure: %.2f kPa, Temperature: %.2f °C\n",
           timestamp, pressure, temperature);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float pressure, temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    while (program_running) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, skipping sample\n");
        }

        for (int i = 0; i < TRIGGER_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

