/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure monitor
 *
 * Hardware:
 *   - I2C bus 1 (BCM pins 2/3), ICP-10125 at address 0x60
 *   - Warning LED on GPIO17 (BCM), 330 Ω series resistor to GND
 *
 * Behaviour:
 *   - Poll the sensor once per second, reading 6 bytes (2 P, 2 T, 2 CRC).
 *   - Verify CRC-8 (polynomial 0x31, init 0xFF) on the pressure word.
 *   - Normal: LED blinks at 1 Hz (500 ms on, 500 ms off).
 *   - Warning (pressure < 95 000 Pa): LED blinks at 5 Hz (100 ms on, 100 ms off).
 *   - SIGINT triggers a clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x60
#define GPIO_LED       17
#define PRESSURE_WARN  95000.0f   /* Pa */
#define POLL_DELAY_US  1000000    /* 1 s between reads */
#define TRIGGER_DELAY_US 20000   /* 20 ms after trigger */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF) – matches ICP-10125 datasheet   */
/* ------------------------------------------------------------------ */
static uint8_t icp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Trigger a measurement and read 6 bytes:
 *   [P_msb, P_lsb, T_msb, T_lsb, CRC_P_msb, CRC_P_lsb]
 * Returns 0 on success, -1 on error.
 */
static int icp_read(int fd, uint8_t *buf)
{
    /*
     * The ICP-10125 does not have a dedicated trigger register;
     * a read of the pressure/temperature block implicitly triggers a
     * fresh conversion.  We issue a zero-length read to wake the sensor.
     */
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr  = ICP10125_ADDR;
    msgs[0].flags = 0;            /* read */
    msgs[0].len   = 0;
    msgs[0].buf   = NULL;

    data.msgs  = msgs;
    data.nmsgs = 1;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C_RDWR trigger: %s\n", strerror(errno));
        return -1;
    }

    usleep(TRIGGER_DELAY_US);

    /* Read 6 bytes: pressure(2) + temperature(2) + CRC(2) */
    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        if (n < 0)
            fprintf(stderr, "I2C read: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read: short read (%zd/6 bytes)\n", n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Pressure conversion                                                 */
/* ------------------------------------------------------------------ */
static float pressure_from_raw(uint16_t raw)
{
    /*
     * Datasheet conversion:
     *   Pa = raw * 0.015256 - 400.0
     * (Note: the exact scaling depends on the configured range;
     * this formula is representative of the default 100-115 kPa range.)
     */
    return (float)raw * 0.015256f - 400.0f;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void led_set(int gpio, int val)
{
    if (gpioWrite(gpio, val) < 0)
        fprintf(stderr, "gpioWrite(%d, %d): %s\n", gpio, val, strerror(errno));
}

static void led_blink(int gpio, int freq_hz)
{
    if (freq_hz <= 0) freq_hz = 1;
    int period_us = 1000000 / freq_hz;
    int half_us   = period_us / 2;

    led_set(gpio, 1);
    usleep(half_us);
    led_set(gpio, 0);
    usleep(half_us);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- I2C ---- */
    g_i2c_fd = i2c_open(I2C_BUS, ICP10125_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* ---- GPIO (pigpio) ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT): %s\n", GPIO_LED, strerror(errno));
        gpioTerminate();
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    led_set(GPIO_LED, 0);

    printf("ICP-10125 monitoring started (I2C 0x%02X, LED GPIO%d).\n",
           ICP10125_ADDR, GPIO_LED);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t buf[6];

        if (icp_read(g_i2c_fd, buf) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        /* CRC check on pressure word */
        uint8_t calc = icp_crc8(&buf[0], 2);
        if (calc != buf[2]) {
            fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n", calc, buf[2]);
            usleep(POLL_DELAY_US);
            continue;
        }

        uint16_t raw_p = ((uint16_t)buf[0] << 8) | buf[1];
        float pressure = pressure_from_raw(raw_p);

        printf("Pressure: %.2f Pa\n", pressure);

        if (pressure < PRESSURE_WARN) {
            printf("WARNING: pressure below threshold (%.2f < %.2f Pa)\n",
                   pressure, PRESSURE_WARN);
            led_blink(GPIO_LED, 5);   /* 5 Hz warning pattern */
        } else {
