#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x48
#define HTTP_PORT 8080
#define MEASUREMENT_CMD 0x2C
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3
#define READ_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = MEASUREMENT_CMD;
    unsigned char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "Error: Failed to write measurement command (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Error: Failed to read 6 bytes from SHT40 (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(100000);
            continue;
        }

        unsigned int temp_ticks = ((unsigned int)buf[0] << 8) | buf[1];
        unsigned int hum_ticks = ((unsigned int)buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)temp_ticks / 65535.0f;
        *humidity = 100.0f * (float)hum_ticks / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fclose(fp);
}

static void serve_http(float temperature, float humidity) {
    char response[512];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    snprintf(response, sizeof(response),
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "Connection: close\r\n"
             "\r\n"
             "<!DOCTYPE html>\n"
             "<html><head><title>SHT40 Sensor Data</title></head>\n"
             "<body>\n"
             "<h1>SHT40 Sensor Data</h1>\n"
             "<p>Temperature: %.2f C</p>\n"
             "<p>Humidity: %.2f %%</p>\n"
             "<p>Last updated: %d-%02d-%02d %02d:%02d:%02d</p>\n"
             "</body></html>\n",
             temperature, humidity,
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec);

