/*
 * HDC2010 temperature & humidity reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   HDC2010 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   HDC2010 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   HDC2010 VDD -> 3.3 V
 *   HDC2010 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -lpigpio -lrt
 * Run:    sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ---- HDC2010 constants (verified against TI HDC2010 datasheet) ---- */
#define HDC2010_ADDR        0x48   /* 7-bit I2C address */
#define REG_TEMP_LSB        0x00
#define REG_TEMP_MSB        0x01
#define REG_HUM_LSB         0x02
#define REG_HUM_MSB         0x03
#define REG_MEAS_CONFIG     0x0F
#define MEAS_CONFIG_TRIGGER 0x01   /* bit 0: start measurement */
#define MEAS_CONFIG_READY   0x00   /* bit 0: measurement complete */
#define MEAS_CONFIG_T_EN    0x02   /* bit 1: enable temperature measurement */
#define MEAS_CONFIG_H_EN    0x04   /* bit 2: enable humidity measurement */
#define MEAS_CONFIG_HEAT_EN 0x08   /* bit 3: enable heater (0 = off) */
#define MEAS_CONFIG_DEFAULT (MEAS_CONFIG_T_EN | MEAS_CONFIG_H_EN | MEAS_CONFIG_HEAT_EN)
#define MEAS_TIMEOUT_US     500000 /* 500 ms max wait for a measurement */
#define SAMPLE_INTERVAL_S   5
#define I2C_BUS             1
#define I2C_RETRY_MAX       3
#define I2C_RETRY_DELAY_US  10000

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Helpers ---- */

/*
 * Write a 16-bit value to a 16-bit register (pigpio i2cWriteWordData
 * sends [reg, high_byte, low_byte] in that order).
 */
static int reg_write_word(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/*
 * Read a 16-bit register (pigpio i2cReadWordData reads [reg, low_byte, high_byte]).
 */
static int reg_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0)
        return -1;
    *out = (uint16_t)rc;
    return 0;
}

/*
 * Read a single byte register.
 */
static int reg_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return -1;
    *out = (uint8_t)rc;
    return 0;
}

/*
 * Trigger a measurement and wait for completion.
 * Returns 0 on success, -1 on error, 1 on timeout.
 */
static int trigger_and_wait(int handle)
{
    uint16_t cfg;
    uint32_t elapsed = 0;

    /* Write MEAS_CONFIG with TRIGGER bit set. */
    if (reg_write_word(handle, REG_MEAS_CONFIG, MEAS_CONFIG_DEFAULT | MEAS_CONFIG_TRIGGER) < 0)
        return -1;

    /* Poll bit 0 until it reads 1 (ready) or timeout. */
    do {
        if (reg_read_word(handle, REG_MEAS_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & MEAS_CONFIG_READY)
            return 0;
        gpioDelay(1000); /* 1 ms */
        elapsed += 1000;
    } while (elapsed < MEAS_TIMEOUT_US);

    return 1; /* timeout */
}

/*
 * Read temperature (°C) and humidity (%RH).
 * Returns 0 on success, -1 on error.
 */
static int read_sensor(int handle, float *temperature, float *humidity)
{
    uint16_t raw_t, raw_h;
    int rc;

    rc = trigger_and_wait(handle);
    if (rc != 0) {
        fprintf(stderr, "Error: sensor measurement timeout (rc=%d)\n", rc);
        return -1;
    }

    rc = reg_read_word(handle, REG_TEMP_LSB, &raw_t);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to read temperature register\n");
        return -1;
    }

    rc = reg_read_word(handle, REG_HUM_LSB, &raw_h);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to read humidity register\n");
        return -1;
    }

    /* TI conversion formulas (datasheet): */
    *temperature = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_h / 65536.0f) * 100.0f;

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    float temperature, humidity;
    int rc;

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HDC2010 address. */
    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) — sensor may be absent or bus unavailable\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    printf("HDC2010 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        rc = read_sensor(g_i2c_handle, &temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error: sensor read failed (rc=%d)\n", rc);
        }

        /* Sleep SAMPLE_INTERVAL_S seconds, checking g_running every second. */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            gpioDelay(1000000);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

