/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   SDP800 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x50 (SDP800 default, verified against datasheet)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -lpigpio -lrt
 * Run:    sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x50
#define MEASURE_CMD    0x3600   /* Start continuous measurement command */
#define MEASURE_DELAY  45000    /* 45 ms measurement conversion time */
#define LOOP_DELAY     500000   /* 500 ms between readings */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t checksum)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == checksum);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_data(int handle, uint8_t *buf, uint32_t len)
{
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    if (bytes != (int)len) {
        fprintf(stderr, "I2C read failed: expected %u bytes, got %d\n",
                len, bytes);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    if (i2c_write_cmd(handle, MEASURE_CMD) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY);   /* 45 ms conversion time */

    uint8_t data[6];
    if (i2c_read_data(handle, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRCs */
    if (!crc8_check(&data[0], 2, data[2])) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&data[3], 2, data[5])) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (int16_t)((data[3] << 8) | data[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus ----------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SDP800_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int16_t pressure, temperature;

        if (read_sdp800(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d (0x%04X)\n",
                   pressure, temperature, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(LOOP_DELAY / 10);
    }

    /* --- cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

