code:
/*
 * PID-controlled reflow oven for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX6675 thermocouple amplifier on SPI0 (CE0 / GPIO8, SCLK=GPIO11,
 *     MOSI=GPIO10, MISO=GPIO9)
 *   - Solid-state relay on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o reflow reflow.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./reflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 (GPIO8)  */
#define SPI_SPEED        4000000    /* 4 MHz         */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define SSR_GPIO         17         /* BCM 17        */
#define SSR_PERIOD_US    1000000    /* 1 s period    */
#define SAMPLE_PERIOD_US 1000000    /* 1 Hz          */

#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"

/* PID gains (tune for your specific oven) */
#define KP  1.0
#define KI  0.1
#define KD  0.01

/* MAX6675: 15 ms conversion time; sample every 10 ms for safety */
#define MAX6675_CONV_US  15000
#define MAX6675_READ_US  10000

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static FILE *g_profile = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  spi_read_max6675(int handle, float *temp_c);
static float pid_update(float setpoint, float actual, float *integral,
                         float *prev_error, float dt);
static int  load_profile(FILE *fp, float *target, float *time_s);
static void log_data(FILE *log, float temp, float target);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MAX6675 SPI read ---------------------------- */

/*
 * MAX6675 3-byte SPI payload (Mode 0, MSB-first):
 *   Byte 0: 0x00 (reserved)
 *   Byte 1: [D2:D0][SCV][FAULT][reserved]
 *   Byte 2: [D16:D13][reserved]
 *
 *   D2: fault bit (1 = fault)
 *   D1: negative temperature (1 = negative)
 *   D0: SCV (single-ended fault)
 *   D16:D13 = 14-bit signed thermocouple value
 */
static int spi_read_max6675(int handle, float *temp_c)
{
    char tx[3] = {0, 0, 0};
    char rx[3] = {0, 0, 0};
    int  bytes;
    int16_t raw;

    bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "[ERROR] SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    /* Fault bit (D2 of byte 1) */
    if (rx[1] & 0x04) {
        fprintf(stderr, "[ERROR] MAX6675 fault detected\n");
        return -2;
    }

    /* 14-bit signed thermocouple value */
    raw = (int16_t)(((rx[1] & 0x03) << 8) | (uint8_t)rx[2]);
    if (raw & 0x2000) {
        raw |= 0xC000;          /* sign-extend */
    }

    *temp_c = (float)raw * 0.25f;
    return 0;
}

/* ----------------------------- PID update -------------------------------- */

static float pid_update(float setpoint, float actual, float *integral,
                         float *prev_error, float dt)
{
    float error = setpoint - actual;
    *integral += error * dt;

    /* Anti-windup clamp */
    if (*integral > 1.0f) *integral = 1.0f;
    if (*integral < 0.0f) *integral = 0.0f;

    float derivative = (error - *prev_error) / dt;
    float output = KP * error + KI * (*integral) + KD * derivative;

    *prev_error = error;
    return output;
}

/* ----------------------------- Profile loader ----------------------------- */

static int load_profile(FILE *fp, float *target, float *time_s)
{
    char line[256];
    int  idx = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0')
            continue;

        if (idx >= 100) {
            fprintf(stderr, "[WARN] Profile exceeds 100 entries, truncating\n");
            break;
        }

        if (sscanf(line, "%f,%f", &time_s[idx], &target[idx]) != 2) {
            fprintf(stderr, "[WARN] Malformed profile entry: '%s'\n", line);
            continue;
        }
        idx++;
    }

    if (idx == 0) {
        fprintf(stderr, "[ERROR] Profile file empty or unreadable\n");
        return -1;
    }
    return idx;
}

/* ----------------------------- Data logger -------------------------------- */

static void log_data(FILE *log, float temp, float target)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "1970-01-01 00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(log, "%s,%.2f,%.2f\n", ts, temp, target);
    fflush(log);
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_profile) {
        fclose(g_profile);
        g_profile = NULL;
    }
    /* Ensure SSR is off before terminating pigpio */
    gpioWrite(SSR_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    int  spi_handle = -1;
    float target[100];
    float time_s[100];
    int  profile_size = 0;
    float integral = 0.0f;
    float prev_error = 0.0f;
    float current_time = 0.0f;
    int  profile_idx = 0;
    int  ssr_state = 0;
    uint32_t on_us = 0;
    uint32_t off_us = 0;
    float temp_c = 0.0f;
    int  consecutive_errors = 0;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SSR GPIO setup --- */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output\n", SSR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SSR_GPIO, 0);

    /* --- SPI open --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open profile file --- */
    g_profile = fopen(PROFILE_FILE, "r");
    if (!g_profile) {
        fprintf(stderr, "[WARN] Cannot open profile file '%s'; using default 0 C\n",
                PROFILE_FILE);
    } else {
        profile_size = load_profile(g_profile, target, time_s);
        if (profile_size <= 0) {
            fprintf(stderr, "[WARN] Profile load failed; using default 0 C\n");
            target[0] = 0.0f;
            time_s[0] = 0.0f;
            profile_size = 1;
        }
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reflow oven started. Press Ctrl+C to exit.\n");

    /* --- Main control loop --- */
    while (g_running) {
        uint32_t start_tick = gpioTick();

        /* --- Read thermocouple --- */
        int rc = spi_read_max6675(spi_handle, &temp_c);
        if (rc == 0) {
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "[FATAL] Too many SPI errors, aborting\n");
                break;
            }
            gpioDelay(MAX6675_READ_US);
            continue;
        }

        /* --- Update PID --- */
        float pid_out = pid_update(target[profile_idx], temp_c,
                                    &integral, &prev_error, 0.1f);

        /* Clamp to [0, 1] */
        if (pid_out < 0.0f)   pid_out = 0.0f;
        if (pid_out > 1.0f)   pid_out = 1.0f;

        on_us   = (uint32_t)(pid_out * SSR_PERIOD_US);
        off_us  = SSR_PERIOD_US - on_us;

        /* --- SSR PWM via gpioPWM (pigpio hardware PWM on GPIO17) --- */
        if (on_us > 0 && off_us > 0) {
            gpioPWM(SSR_GPIO, (int)(on_us / 1000));  /* 0-1000 duty */
        } else {
            gpioPWM(SSR_GPIO, 0);
        }

        /* --- Log --- */
        log_data(g_log, temp_c, target[profile_idx]);

        /* --- Advance profile --- */
        current_time += 0.1f;
        if (current_time >= time_s[profile_idx]) {
            if (profile_idx + 1 < profile_size) {
                profile_idx++;
            } else {
                fprintf(stderr, "[INFO] Profile complete, holding at %.2f C\n",
                        target[profile_idx]);
            }
            current_time = 0.0f;
        }

        /* --- Sleep remainder of 100 ms cycle --- */
        uint32_t elapsed = gpioTick() - start_tick;
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

