#define SPI_SPEED        4000000    /* 4 MHz         */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define SSR_GPIO         17         /* BCM 17        */
#define SSR_PERIOD_US    1000000    /* 1 s period    */
#define SAMPLE_PERIOD_US 1000000    /* 1 Hz          */

#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"

/* PID gains (tune for your specific oven) */
#define KP  1.0
#define KI  0.1
#define KD  0.01

