/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MAX6675 SPI read ---------------------------- */

/*
 * MAX6675 3-byte SPI payload (Mode 0, MSB-first):
 *   Byte 0: 0x00 (reserved)
 *   Byte 1: [D2:D0][SCV][FAULT][reserved]
 *   Byte 2: [D16:D13][reserved]
 *
 *   D2: fault bit (1 = fault)
 *   D1: negative temperature (1 = negative)
 *   D0: SCV (single-ended fault)
 *   D16:D13 = 14-bit signed thermocouple value
 */
static int spi_read_max6675(int handle, float *temp_c)
{
    char tx[3] = {0, 0, 0};
    char rx[3] = {0, 0, 0};
    int  bytes;
    int16_t raw;

    bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "[ERROR] SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    /* Fault bit (D2 of byte 1) */
    if (rx[1] & 0x04) {
        fprintf(stderr, "[ERROR] MAX6675 fault detected\n");
        return -2;
    }

    /* 14-bit signed thermocouple value */
    raw = (int16_t)(((rx[1] & 0x03) << 8) | (uint8_t)rx[2]);
    if (raw & 0x2000) {
        raw |= 0xC000;          /* sign-extend */
    }

    *temp_c = (float)raw * 0.25f;
    return 0;
}

/* ----------------------------- PID update -------------------------------- */

static float pid_update(float setpoint, float actual, float *integral,
                         float *prev_error, float dt)
{
    float error = setpoint - actual;
    *integral += error * dt;

    /* Anti-windup clamp */
    if (*integral > 1.0f) *integral = 1.0f;
    if (*integral < 0.0f) *integral = 0.0f;

    float derivative = (error - *prev_error) / dt;
    float output = KP * error + KI * (*integral) + KD * derivative;

    *prev_error = error;
    return output;
}

/* ----------------------------- Profile loader ----------------------------- */

static int load_profile(FILE *fp, float *target, float *time_s)
{
    char line[256];
    int  idx = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0')
            continue;

        if (idx >= 100) {
            fprintf(stderr, "[WARN] Profile exceeds 100 entries, truncating\n");
            break;
        }

        if (sscanf(line, "%f,%f", &time_s[idx], &target[idx]) != 2) {
            fprintf(stderr, "[WARN] Malformed profile entry: '%s'\n", line);
            continue;
        }
        idx++;
    }

    if (idx == 0) {
        fprintf(stderr, "[ERROR] Profile file empty or unreadable\n");
        return -1;
    }
    return idx;
}

