    return 0;
}

static int init_pwm(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_GPIO);
    if (write_sysfs(path, "10000000") < 0) return -1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_GPIO);
    if (write_sysfs(path, "0") < 0) return -1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_GPIO);
    if (write_sysfs(path, "1") < 0) return -1;
    return 0;
}

static int read_temperature(float *temp) {
    char buf[256];
    if (read_sysfs(DS18B20_DEVICE_PATH, buf, sizeof(buf)) < 0) return -1;
    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for DS18B20\n");
        return -1;
    }
    char *t = strstr(buf, "t=");
    if (t == NULL) {
        fprintf(stderr, "Temperature data not found\n");
        return -1;
    }
    long raw = strtol(t + 2, NULL, 10);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static float pid_control(float setpoint, float current_temp, float kp, float ki, float kd,
                         float *integral, float *prev_error) {
    float error = setpoint - current_temp;
    *integral += error;
    float derivative = error - *prev_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

static int set_relay(int state) {
    return write_sysfs("/sys/class/gpio/gpio17/value", state ? "1" : "0");
}

static int set_pwm_duty(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    long duty_ns = (long)duty_percent * PWM_PERIOD_NS / 100;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_GPIO);
    char val[16];
    snprintf(val, sizeof(val), "%ld", duty_ns);
    return write_sysfs(path, val);
}

static void log_data(float avg_temp, float setpoint, float pid_out, int duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s,%.2f,%.2f,%.2f,%d\n", ts, avg_temp, setpoint, pid_out, duty);
    fflush(log_fp);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }
    float setpoint = atof(argv[1]);
    float kp = atof(argv[2]);
    float ki = atof(argv[3]);
    float kd = 0.0f;
    if (argc > 4) kd = atof(argv[4]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    if (init_pwm() < 0) {
        fprintf(stderr, "PWM initialization failed\n");
        fclose(log_fp);
        return 1;
    }

    float integral = 0.0f, prev_error = 0.0f;
    float temp;
    int duty = 0;

    while (running) {
        if (read_temperature(&temp) == 0) {
            float pid_out = pid_control(setpoint, temp, kp, ki, kd, &integral, &prev_error);
            duty = (int)pid_out;
            if (duty > 100) duty = 100;
            if (duty < 0) duty = 0;
            if (set_relay(duty > 0) < 0) {
                fprintf(stderr, "Relay control failed\n");
            }
            if (set_pwm_duty(duty) < 0) {
                fprintf(stderr, "PWM duty cycle failed\n");
            }
            log_data(temp, setpoint, pid_out, duty);
        } else {
            fprintf(stderr, "Temperature read failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    set_relay(0);
    set_pwm_duty(0);
    if (w1_fd >= 0) close(w1_fd);
    if (pwm_fd >= 0) close(pwm_fd);
    if (log_fp) fclose(log_fp);
    return 0;
}

