#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR      0x36
#define AHT20_CMD_MEAS  0x06
#define AHT20_MEAS_MS   80
#define AHT20_RETRY     3
#define AHT20_RETRY_MS  10
#define POLL_MS         5000
#define DEHUM_GPIO      17
#define HUM_HIGH        60.0f
#define HUM_LOW         55.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_pigpio_inited = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n)
{
    size_t got = 0;
    while (got < n) {
        ssize_t r = read(fd, buf + got, n - got);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        got += (size_t)r;
    }
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t buf[6];
    int attempt;

    for (attempt = 0; attempt < AHT20_RETRY; attempt++) {
        if (i2c_write_cmd(fd, AHT20_CMD_MEAS) != 0) {
            gpioDelay(AHT20_RETRY_MS * 1000);
            continue;
        }

        gpioDelay(AHT20_MEAS_MS * 1000);

        if (i2c_read_n(fd, buf, sizeof(buf)) != 0) {
            gpioDelay(AHT20_RETRY_MS * 1000);
            continue;
        }

        if ((buf[0] & 0x03) != 0) {
            fprintf(stderr, "AHT20 not calibrated (status=0x%02X)\n", buf[0]);
            gpioDelay(AHT20_RETRY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[1] << 8) | buf[2];
        *humidity = ((float)raw / 65535.0f) * 100.0f;
        return 0;
    }

    fprintf(stderr, "AHT20 read failed after %d retries\n", AHT20_RETRY);
    return -1;
}

static void log_humidity(float humidity)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    fflush(stdout);
}

static void control_dehumidifier(float humidity)
{
    static int relay_on = 0;

    if (humidity > HUM_HIGH && !relay_on) {
        if (gpioWrite(DEHUM_GPIO, 1) == 0) {
            relay_on = 1;
            printf("Dehumidifier ON\n");
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to activate dehumidifier relay\n");
        }
    } else if (humidity < HUM_LOW && relay_on) {
        if (gpioWrite(DEHUM_GPIO, 0) == 0) {
            relay_on = 0;
            printf("Dehumidifier OFF\n");
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to deactivate dehumidifier relay\n");
        }
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = 1;

    if (gpioSetMode(DEHUM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", DEHUM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(DEHUM_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float humidity;
        if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        gpioDelay(POLL_MS * 1000);
    }

    gpioWrite(DEHUM_GPIO, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_pigpio_inited) gpioTerminate();
    return EXIT_SUCCESS;
}

