#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define MEASURE_CMD_HIGH 0x3E
#define MEASURE_CMD_LOW 0xBE
#define POLL_INTERVAL 60
#define SERVER_ADDR "api.example.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed for command 0x%02X: %s", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes = read(fd, buf, len);
    if (bytes < 0 || (size_t)bytes != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_htu21d(int fd, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t data[4];

    if (write(fd, cmd, 2) != 2) {
        syslog(LOG_ERR, "Failed to send measurement command: %s", strerror(errno));
        return -1;
    }

    usleep(15000);

    if (i2c_read_data(fd, data, 4) != 0) {
        return -1;
    }

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    uint16_t raw_temp = (data[2] << 8) | data[3];

    float h = -6.0 + 125.0 * (float)raw_humidity / 65536.0;
    if (h < 0.0) h = 0.0;
    if (h > 100.0) h = 100.0;

    *humidity = h;
    return 0;
}

static int send_http_post(const char *json_data) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_ADDR, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid server address: %s", SERVER_ADDR);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection to server failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        SERVER_ADDR, strlen(json_data), json_data);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request buffer too small");
        close(sockfd);
        return -1;
    }

    if (write(sockfd, request, req_len) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire I2C bus access: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D sensor initialized on %s at address 0x%02X", I2C_BUS, HTU21D_ADDR);

    while (running) {
        float humidity = 0.0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_htu21d(i2c_fd, &humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                syslog(LOG_WARNING, "HTU21D read failed, retrying (%d/%d)", retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (success) {
            char json_data[64];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

            if (send_http_post(json_data) != 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            } else {
                syslog(LOG_INFO, "Sent humidity data: %s", json_data);
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    close(i2c_fd);
    closelog();
    return 0;
}

