/*
 * BMP280 Pressure Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP280 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   BMP280 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   BMP280 VDD -> 3.3 V
 *   BMP280 GND -> GND
 *
 * Build: gcc -O2 -Wall -o bmp280_monitor bmp280_monitor.c -lpigpio -lrt
 * Run:   sudo ./bmp280_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP280 constants (verified against datasheet) ---- */
#define BMP280_I2C_ADDR          0x76
#define BMP280_REG_CHIP_ID       0xD0
#define BMP280_REG_RESET         0xE0
#define BMP280_REG_CTRL_MEAS     0xF4
#define BMP280_REG_CONFIG        0xF5
#define BMP280_REG_PRESS_MSB     0xF7
#define BMP280_REG_TEMP_MSB      0xFA
#define BMP280_REG_CALIB_00      0x88
#define BMP280_CHIP_ID           0x58

#define I2C_BUS                  1
#define SAMPLE_INTERVAL_US       2000000  /* 2 seconds */
#define CONVERSION_DELAY_US      10000    /* 10 ms */
#define MAX_RETRIES              3
#define PRESSURE_THRESHOLD_HPA   1020.0f
#define PRESSURE_THRESHOLD_HPA_L 980.0f

/* ---- Calibration coefficients (BMP280 datasheet) ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return (i2cWriteDevice(handle, buf, 2) == 0) ? 0 : -1;
}

/* ---- BMP280 initialization ---- */
static int bmp280_init(int handle, bmp280_calib_t *cal) {
    uint8_t chip_id;

    /* Verify chip ID */
    if (i2c_read_reg(handle, BMP280_REG_CHIP_ID, &chip_id, 1) < 0) {
        fprintf(stderr, "[ERROR] Failed to read chip ID.\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "[ERROR] Chip ID mismatch: got 0x%02X, expected 0x%02X.\n",
                chip_id, BMP280_CHIP_ID);
        return -1;
    }

    /* Read calibration coefficients (24 bytes starting at 0x88) */
    uint8_t cal_buf[24];
    if (i2c_read_reg(handle, BMP280_REG_CALIB_00, cal_buf, sizeof(cal_buf)) < 0) {
        fprintf(stderr, "[ERROR] Failed to read calibration data.\n");
        return -1;
    }

    cal->dig_T1 = (uint16_t)(cal_buf[0]  | (cal_buf[1]  << 8));
    cal->dig_T2 = (int16_t)(cal_buf[2]  | (cal_buf[3]  << 8));
    cal->dig_T3 = (int16_t)(cal_buf[4]  | (cal_buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(cal_buf[6]  | (cal_buf[7]  << 8));
    cal->dig_P2 = (int16_t)(cal_buf[8]  | (cal_buf[9]  << 8));
    cal->dig_P3 = (int16_t)(cal_buf[10] | (cal_buf[11] << 8));
    cal->dig_P4 = (int16_t)(cal_buf[12] | (cal_buf[13] << 8));
    cal->dig_P5 = (int16_t)(cal_buf[14] | (cal_buf[15] << 8));
    cal->dig_P6 = (int16_t)(cal_buf[16] | (cal_buf[17] << 8));
    cal->dig_P7 = (int16_t)(cal_buf[18] | (cal_buf[19] << 8));
    cal->dig_P8 = (int16_t)(cal_buf[20] | (cal_buf[21] << 8));
    cal->dig_P9 = (int16_t)(cal_buf[22] | (cal_buf[23] << 8));

    /* Configure: t_sb=500us, filter=4, spi3w_en=0 (I2C mode) */
    if (i2c_write_reg(handle, BMP280_REG_CONFIG, 0x04) < 0) {
        fprintf(stderr, "[ERROR] Failed to write config register.\n");
        return -1;
    }

    /* Config: osrs_t=x1, osrs_p=x1, mode=normal (0x27) */
    if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "[ERROR] Failed to write ctrl_meas register.\n");
        return -1;
    }

    return 0;
}

/* ---- BMP280 read with retries ---- */
static int bmp280_read(int handle, const bmp280_calib_t *cal,
                        int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Trigger measurement */
        if (i2c_write_reg(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
            fprintf(stderr, "[WARN] Trigger write failed (attempt %d).\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(CONVERSION_DELAY_US);

        /* Read 6 bytes: press(3) + temp(3) */
        if (i2c_read_reg(handle, BMP280_REG_PRESS_MSB, data, 6) < 0) {
            fprintf(stderr, "[WARN] Read failed (attempt %d).\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
        *raw_temp  = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
        return 0;
    }

    fprintf(stderr, "[ERROR] BMP280 read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

/* ---- Bosch compensation (datasheet formulas) ---- */
static int32_t compensate_temp(int32_t raw_temp, const bmp280_calib_t *cal) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)cal->dig_T1)) * ((raw_temp >> 4) - ((int32_t)cal->dig_T1))) >> 12) *
            ((int32_t)cal->dig_T3)) >> 14;
    return (var1 + var2) >> 2;
}

static uint32_t compensate_press(int32_t raw_press, int32_t raw_temp,
                                 const bmp280_calib_t *cal) {
    int32_t var1, var2;
    uint32_t p;

    int32_t t_fine = compensate_temp(raw_temp, cal);
    var1 = ((int32_t)t_fine) - 128000;
    var2 = var1 * var1 * (int32_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int32_t)cal->dig_P5) << 17);
    var2 = var2 + (((int32_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int32_t)cal->dig_P3) >> 8) + ((var1 * (int32_t)cal->dig_P2) << 12);
    var1 = (((((int32_t)1) << 47) + var1)) * ((int32_t)cal->dig_P1) >> 33;

    if (var1 == 0) return 0;

    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int32_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int32_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int32_t)cal->dig_P7) << 4);

    return p;  /* Pa */
}

/* ---- Logging ---- */
static void log_pressure(float pressure_hpa) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("[ERROR] fopen pressure_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure_hpa);
    } else {
        fprintf(fp, "[timestamp error], Pressure: %.2f hPa\n", pressure_hpa);
    }

    fclose(fp);
}

/* ---- Main ---- */
int main(void) {
    bmp280_calib_t cal;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[ERROR] sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp280_init(g_i2c_handle, &cal) < 0) {
        fprintf(stderr, "[ERROR] BMP280 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] BMP280 initialized. Monitoring pressure (threshold ±40 hPa)...\n");

    while (g_running) {
        int32_t raw_temp, raw_press;

        if (bmp280_read(g_i2c_handle, &cal, &raw_temp, &raw_press) == 0) {
            uint32_t press_pa = compensate_press(raw_press, raw_temp, &cal);
            float press_hpa = (float)press_pa / 100.0f;

            if (press_hpa > PRESSURE_THRESHOLD_HPA ||
                press_hpa < PRESSURE_THRESHOLD_HPA_L) {
                printf("[ALERT] Pressure: %.2f hPa\n", press_hpa);
                log_pressure(press_hpa);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; re-initializing I2C.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[ERROR] Re-open failed (handle=%d).\n", g_i2c_handle);
                break;
            }
            if (bmp280_init(g_i2c_handle, &cal) < 0) {
                fprintf(stderr, "[ERROR] Re-init failed.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("[INFO] Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

