                                 const bmp280_calib_t *cal) {
    int32_t var1, var2;
    uint32_t p;

    int32_t t_fine = compensate_temp(raw_temp, cal);
    var1 = ((int32_t)t_fine) - 128000;
    var2 = var1 * var1 * (int32_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int32_t)cal->dig_P5) << 17);
    var2 = var2 + (((int32_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int32_t)cal->dig_P3) >> 8) + ((var1 * (int32_t)cal->dig_P2) << 12);
    var1 = (((((int32_t)1) << 47) + var1)) * ((int32_t)cal->dig_P1) >> 33;

    if (var1 == 0) return 0;

    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int32_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int32_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int32_t)cal->dig_P7) << 4);

    return p;  /* Pa */
}

/* ---- Logging ---- */
static void log_pressure(float pressure_hpa) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("[ERROR] fopen pressure_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure_hpa);
    } else {
        fprintf(fp, "[timestamp error], Pressure: %.2f hPa\n", pressure_hpa);
    }

    fclose(fp);
}

/* ---- Main ---- */
int main(void) {
    bmp280_calib_t cal;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[ERROR] sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp280_init(g_i2c_handle, &cal) < 0) {
        fprintf(stderr, "[ERROR] BMP280 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] BMP280 initialized. Monitoring pressure (threshold ±40 hPa)...\n");

    while (g_running) {
        int32_t raw_temp, raw_press;

        if (bmp280_read(g_i2c_handle, &cal, &raw_temp, &raw_press) == 0) {
            uint32_t press_pa = compensate_press(raw_press, raw_temp, &cal);
            float press_hpa = (float)press_pa / 100.0f;

            if (press_hpa > PRESSURE_THRESHOLD_HPA ||
                press_hpa < PRESSURE_THRESHOLD_HPA_L) {
                printf("[ALERT] Pressure: %.2f hPa\n", press_hpa);
                log_pressure(press_hpa);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; re-initializing I2C.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[ERROR] Re-open failed (handle=%d).\n", g_i2c_handle);
                break;
            }
            if (bmp280_init(g_i2c_handle, &cal) < 0) {
                fprintf(stderr, "[ERROR] Re-init failed.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("[INFO] Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

