/*
 * Raspberry Pi 4B environmental logger
 *
 * TMP117  I2C  address 0x44  (SA0 tied to GND)
 * AHT20   I2C  address 0x44  (SA0 tied to GND)
 * PIR     GPIO17 (gpiochip4 line 17), active-high motion output
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x44
#define AHT20_ADDR     0x44
#define PIR_CHIP       "gpiochip4"
#define PIR_LINE       17
#define SAMPLE_INTERVAL_S 1
#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 10

#define TMP117_REG_TEMP_LOW  0x00
#define TMP117_REG_CONFIG    0x01
#define TMP117_CFG_DEFAULT   0x00

#define AHT20_REG_TEMP_LOW   0x00
#define AHT20_REG_HUM_LOW    0x02
#define AHT20_REG_MEAS_HIGH  0x0F
#define AHT20_REG_MEAS_LOW   0x0E
#define AHT20_REG_CONFIG     0x0B
#define AHT20_CFG_DEFAULT    0x00

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, val, 1) != 1) {
            usleep(I2C_RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_tmp117(int fd, float *temp_c)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, TMP117_REG_TEMP_LOW, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, TMP117_REG_TEMP_HIGH, &hi) < 0)
        return -1;
    int16_t raw = (int16_t)((hi << 8) | lo);
    *temp_c = raw * 0.0078125f;
    return 0;
}

static int read_aht20(int fd, float *temp_c, float *rh)
{
    uint8_t meas_hi, meas_lo;
    uint8_t t_lo, t_hi, h_lo, h_hi;

    if (i2c_write_reg8(fd, AHT20_REG_MEAS_HIGH, 0x01) < 0)
        return -1;
    usleep(5000);
    if (i2c_read_reg8(fd, AHT20_REG_MEAS_HIGH, &meas_hi) < 0)
        return -1;
    if (i2c_read_reg8(fd, AHT20_REG_MEAS_LOW, &meas_lo) < 0)
        return -1;
    if ((meas_hi & 0x01) != 0) {
        fprintf(stderr, "AHT20: measurement not complete (status=0x%02X)\n", meas_hi);
        return -1;
    }
    if (i2c_read_reg8(fd, AHT20_REG_TEMP_LOW, &t_lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, AHT20_REG_TEMP_HIGH, &t_hi) < 0)
        return -1;
    if (i2c_read_reg8(fd, AHT20_REG_HUM_LOW, &h_lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, AHT20_REG_HUM_HIGH, &h_hi) < 0)
        return -1;

    int16_t t_raw = (int16_t)((t_hi << 8) | t_lo);
    int16_t h_raw = (int16_t)((h_hi << 8) | h_lo);
    *temp_c = t_raw * 0.01f;
    *rh = h_raw * 0.01f;
    return 0;
}

static int read_pir(struct gpiod_line *line, int *motion)
{
    int v = gpiod_line_get_value(line);
    if (v < 0) {
        fprintf(stderr, "PIR read error: %s\n", strerror(errno));
        return -1;
    }
    *motion = (v == 1) ? 1 : 0;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d_%H-%M-%S", &tm);
}

static void get_daily_filename(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d.csv", &tm);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int tmp117_fd = -1, aht20_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", PIR_CHIP, strerror(errno));
        goto cleanup;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pir_line, "pir-logger") < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    tmp117_fd = open(I2C_BUS, O_RDWR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(tmp117_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg8(tmp117_fd, TMP117_REG_CONFIG, TMP117_CFG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write TMP117 config: %s\n", strerror(errno));
        goto cleanup;
    }

    aht20_fd = open(I2C_BUS, O_RDWR);
    if (aht20_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(aht20_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg8(aht20_fd, AHT20_REG_CONFIG, AHT20_CFG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write AHT20 config: %s\n", strerror(errno));
        goto cleanup;
    }

    char daily_filename[64];
    get_daily_filename(daily_filename, sizeof(daily_filename));

    FILE *fp = fopen(daily_filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", daily_filename, strerror(errno));
        goto cleanup;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        fflush(fp);
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", daily_filename);

    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        int motion = 0;
        int err = 0;

        if (read_tmp117(tmp117_fd, &temp_c) < 0)
            fprintf(stderr, "TMP117 read failed\n");
        if (read_aht20(aht20_fd, &temp_c, &rh) < 0)
            fprintf(stderr, "AHT20 read failed\n");
        if (read_pir(pir_line, &motion) < 0)
            fprintf(stderr, "PIR read failed\n");

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (fp) {
            fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp_c, rh, motion);
            fflush(fp);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0) close(aht20_fd);
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

