/*
 * Rain-activated window closer for Raspberry Pi 5.
 *
 * Hardware:
 *   - YL-83 rain sensor  DO  -> GPIO17 (active-low)
 *   - L298N motor driver
 *       ENA     -> GPIO22
 *       IN1     -> GPIO23
 *       IN2     -> GPIO24
 *
 * Behaviour:
 *   Polls GPIO17 every 2 s.  When the pin reads LOW (rain detected) the
 *   motor is driven forward for 5 s, then stopped.  Every event (detection,
 *   motor start/stop, error) is logged to stdout with a timestamp.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */

#define RAIN_SENSOR_PIN    17
#define MOTOR_ENA_PIN      22
#define MOTOR_IN1_PIN      23
#define MOTOR_IN2_PIN      24

#define MOTOR_RUN_TIME_SEC 5
#define POLL_INTERVAL_SEC  2

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Helpers ----------------------------------- */

static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(buf, len, "unknown-time");
}

static void log_msg(const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof(ts));
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/* ----------------------------- Motor control ----------------------------- */

static int motor_forward(struct gpiod_line *ena,
                         struct gpiod_line *in1,
                         struct gpiod_line *in2)
{
    if (gpiod_line_set_value(in1, 1) < 0) {
        log_msg("Error: failed to set IN1 high");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_msg("Error: failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(ena, 1) < 0) {
        log_msg("Error: failed to enable ENA");
        return -1;
    }
    log_msg("Motor started (forward)");
    return 0;
}

static int motor_stop(struct gpiod_line *ena,
                      struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    if (gpiod_line_set_value(in1, 0) < 0) {
        log_msg("Error: failed to set IN1 low");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_msg("Error: failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(ena, 0) < 0) {
        log_msg("Error: failed to disable ENA");
        return -1;
    }
    log_msg("Motor stopped");
    return 0;
}

/* ----------------------------- Signal handling ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) < 0)
        perror("sigaction(SIGTERM)");
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    install_signal_handlers();

    /* Open the default GPIO chip (gpiochip4 on Pi 5). */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2712");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        fprintf(stderr, "Failed to acquire one or more GPIO lines: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request rain sensor line as input. */
    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        fprintf(stderr, "Failed to request rain sensor line: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request motor control lines as outputs, initialised low. */
    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        fprintf(stderr, "Failed to request ENA line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        fprintf(stderr, "Failed to request IN1 line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        fprintf(stderr, "Failed to request IN2 line: %s\n", strerror(errno));
        goto cleanup;
    }

    log_msg("Rain sensor monitoring started (YL-83 on GPIO17, L298N on GPIO22/23/24).");

    while (g_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            log_msg("Error: failed to read rain sensor");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {  /* active-low: LOW => rain detected */
            log_msg("Rain detected - closing window");

            if (motor_forward(ena_line, in1_line, in2_line) < 0) {
                log_msg("Motor start failed; continuing to next cycle");
            } else {
                /* Run for MOTOR_RUN_TIME_SEC, checking g_running every second. */
                for (int i = 0; i < MOTOR_RUN_TIME_SEC && g_running; i++)
                    sleep(1);

                if (motor_stop(ena_line, in1_line, in2_line) < 0)
                    log_msg("Motor stop failed");
            }
        }

        if (g_running)
            sleep(POLL_INTERVAL_SEC);
    }

    log_msg("Shutting down - stopping motor");
    motor_stop(ena_line, in1_line, in2_line);
    ret = EXIT_SUCCESS;

cleanup:
    if (rain_line)  gpiod_line_release(rain_line);
    if (ena_line)   gpiod_line_release(ena_line);
    if (in1_line)   gpiod_line_release(in1_line);
    if (in2_line)   gpiod_line_release(in2_line);
    if (chip)       gpiod_chip_close(chip);
    return ret;
