#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27
#define PWM_FREQ   1000
#define PWM_RANGE  255
#define SAMPLE_US  500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int read_cpu_load(float *load_out)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    static unsigned long long prev_idle = 0, prev_non_idle = 0;
    unsigned long long idle = idle + iowait;
    unsigned long long non_idle = user + nice + system + irq + softirq + steal;

    unsigned long long prev_idle_total = prev_idle + prev_non_idle;
    unsigned long long now_total = idle + non_idle;

    unsigned long long prev_idle_diff = prev_idle_total - prev_idle;
    unsigned long long prev_non_idle_diff = now_total - prev_idle_total;

    prev_idle = idle;
    prev_non_idle = non_idle;

    unsigned long long total_diff = prev_idle_diff + prev_non_idle_diff;
    if (total_diff == 0) {
        *load_out = 0.0f;
        return 0;
    }

    unsigned long long idle_diff = prev_idle - prev_idle;
    unsigned long long non_idle_diff = prev_non_idle - prev_idle;

    unsigned long long idle_contrib = idle_diff - prev_idle_diff;
    unsigned long long non_idle_contrib = non_idle_diff - prev_idle_diff;

    unsigned long long total_contrib = idle_contrib + non_idle_contrib;
    if (total_contrib == 0) {
        *load_out = 0.0f;
        return 0;
    }

    float load = (float)(non_idle_contrib * 100) / (float)total_contrib;
    if (load < 0.0f) load = 0.0f;
    if (load > 100.0f) load = 100.0f;

    *load_out = load;
    return 0;
}

static void map_load_to_color(float load, int *r, int *g, int *b)
{
    if (load < 0.0f) load = 0.0f;
    if (load > 100.0f) load = 100.0f;

    float l = load / 100.0f;
    if (l < 0.5f) {
        *r = (int)(255.0f * (1.0f - l));
        *g = (int)(255.0f * l);
        *b = 0;
    } else {
        *r = 255;
        *g = (int)(255.0f * (1.0f - (l - 0.5f)));
        *b = 0;
    }
}

static int set_led_color(int r, int g, int b)
{
    if (gpioPWM(RED_PIN, r) < 0) {
        fprintf(stderr, "Error setting PWM on RED_PIN\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        fprintf(stderr, "Error setting PWM on GREEN_PIN\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        fprintf(stderr, "Error setting PWM on BLUE_PIN\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("CPU load RGB LED monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float cpu_load;
        if (read_cpu_load(&cpu_load) != 0) {
            fprintf(stderr, "Error reading CPU load, retrying...\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int r, g, b;
        map_load_to_color(cpu_load, &r, &g, &b);

        if (set_led_color(r, g, b) != 0) {
            fprintf(stderr, "Error setting LED color\n");
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

