 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3)
 *   BMP280 SCL  -> GPIO3 (pin 5)
 *   BMP280 VDD  -> 3V3
 *   BMP280 GND  -> GND
 *
 * I2C bus: /dev/i2c-1  (BCM numbering)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bmp280_udp bmp280_udp.c -li2c -lm
 *
 * Run:
 *   ./bmp280_udp
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR    0x76

#define BMP280_REG_ID       0xD0
#define BMP280_REG_RESET    0xE0
#define BMP280_REG_CTRL     0xF4
#define BMP280_REG_CONFIG   0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_CALIB    0x88

#define BMP280_CHIP_ID      0x58
#define BMP280_RESET_CMD    0xB6

#define UDP_IP   "192.168.1.100"
#define UDP_PORT 5000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Calibration coefficients (BMP280 datasheet) ---- */

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read (reg 0x%02X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal)
{
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, buf, sizeof(buf)) != 0)
        return -1;

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t) (buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t) (buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t) (buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t) (buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t) (buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t) (buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t) (buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t) (buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t) (buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t) (buf[22] | (buf[23] << 8));
    return 0;
}

/*
 * Bosch BMP280 compensation (datasheet, 32-bit integer math).
 * Returns temperature in 0.01 °C and pressure in Pa.
 */
static int32_t bmp280_compensate_temp(int32_t adc_T, const bmp280_calib_t *cal,
                                      int32_t *t_fine)
{
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)cal->dig_T1 << 1))) *
            ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)cal->dig_T1)) *
              ((adc_T >> 4) - ((int32_t)cal->dig_T1))) >> 12) *
            ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;  /* 0.01 °C */
}

static uint32_t bmp280_compensate_press(int32_t adc_P, int32_t t_fine,
                                        const bmp280_calib_t *cal)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) +
           ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)p;  /* Pa */
}

static int bmp280_init(int fd, bmp280_calib_t *cal)
{
    uint8_t chip_id;

    if (i2c_read_reg(fd, BMP280_REG_ID, &chip_id, 1) != 0)
        return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not detected (ID=0x%02X, expected 0x%02X)\n",
                chip_id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    usleep(2000);  /* wait for reset */

    if (bmp280_read_calibration(fd, cal) != 0)
        return -1;

    /* config: t_sb=500us(000), filter=4(010), spi3w_en=0 -> 0x28 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x28) != 0)
        return -1;

    /* ctrl: osrs_t=x1(001), osrs_p=x1(001), mode=normal(11) -> 0x27 */
    if (i2c_write_reg(fd, BMP280_REG_CTRL, 0x27) != 0)
        return -1;

    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal,
                       float *temperature, float *pressure)
{
    uint8_t data[6];
    int32_t adc_P, adc_T, t_fine;

    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) != 0)
        return -1;

    adc_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) |
            ((int32_t)data[2] >> 4);
    adc_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) |
            ((int32_t)data[5] >> 4);

    int32_t t_centi = bmp280_compensate_temp(adc_T, cal, &t_fine);
    *temperature = t_centi / 100.0f;

    uint32_t p_pa = bmp280_compensate_press(adc_P, t_fine, cal);
    *pressure = p_pa;
    return 0;
}

static int send_udp(int sockfd, const char *data)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid UDP address: %s\n", UDP_IP);
        return -1;
    }
    if (sendto(sockfd, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "UDP send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    int udp_fd = -1;
    bmp280_calib_t cal;
    float temperature, pressure;
    char json_buf[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bmp280_init(i2c_fd, &cal) != 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BMP280 initialized. Sending UDP every %d s. Ctrl+C to stop.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        if (bmp280_read(i2c_fd, &cal, &temperature, &pressure) == 0) {
            snprintf(json_buf, sizeof(json_buf),
                     "{\"temperature\":%.2f,\"pressure\":%.2f}",
                     temperature, pressure);
            if (send_udp(udp_fd, json_buf) != 0)
                fprintf(stderr, "UDP send failed; continuing.\n");
            else
                printf("Sent: %s\n", json_buf);
        } else {
            fprintf(stderr, "BMP280 read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (udp_fd >= 0) close(udp_fd);
    return EXIT_SUCCESS;
}

