        if (bmp280_read(i2c_fd, &cal, &temperature, &pressure) == 0) {
            snprintf(json_buf, sizeof(json_buf),
                     "{\"temperature\":%.2f,\"pressure\":%.2f}",
                     temperature, pressure);
            if (send_udp(udp_fd, json_buf) != 0)
                fprintf(stderr, "UDP send failed; continuing.\n");
            else
                printf("Sent: %s\n", json_buf);
        } else {
            fprintf(stderr, "BMP280 read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (udp_fd >= 0) close(udp_fd);
    return EXIT_SUCCESS;
}

