#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define FAN_GPIO    18
#define PWM_FREQ    1000
#define PWM_RANGE   255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} FanData;

static FanData fan_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_read_thermocouple(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (raw=0x%08X)\n", raw);
        return -2;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < 25.0f) {
        return 0;
    } else if (temperature < 40.0f) {
        return (int)((temperature - 25.0f) * 50.0f / 15.0f);
    } else if (temperature < 60.0f) {
        return (int)((temperature - 40.0f) * 150.0f / 20.0f + 50.0f);
    } else {
        return 255;
    }
}

static void store_data(time_t timestamp, float temperature, int pwm_duty) {
    fan_buffer[buffer_index].timestamp = timestamp;
    fan_buffer[buffer_index].temperature = temperature;
    fan_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Fan Data Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&fan_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Temp: %.2f C, PWM: %d\n", time_str, fan_buffer[idx].temperature, fan_buffer[idx].pwm_duty);
    }
    printf("--- End of Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature;
        int rc = spi_read_thermocouple(&temperature);

        if (rc == 0) {
            int pwm_duty = calculate_pwm_duty(temperature);
            if (gpioPWM(FAN_GPIO, pwm_duty) != 0) {
                fprintf(stderr, "Failed to set PWM duty on GPIO%d\n", FAN_GPIO);
            }
            store_data(time(NULL), temperature, pwm_duty);
            printf("Temp: %.2f C, PWM: %d\n", temperature, pwm_duty);
        } else if (rc == -2) {
            fprintf(stderr, "MAX31855 fault, skipping fan update\n");
        } else {
            fprintf(stderr, "SPI read error, skipping fan update\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioDelay(100000);
    spiClose(spi_handle);
    print_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

