#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SPI_DELAY_US    0
#define LOG_FILE        "rtd_log.csv"
#define READ_INTERVAL   5
#define RTD_A0_FAULT     0x01
#define RTD_A1_FAULT     0x02
#define RTD_A2_FAULT     0x04
#define RTD_A3_FAULT     0x08
#define RTD_RTD_FAULT    0x10
#define RTD_FAULT_MASK   0x1F
#define RTD_FAULT_NONE   0x00

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_max31865(uint8_t *data)
{
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (spi_transfer(tx, rx, 4) < 0)
        return -1;

    uint32_t raw = ((uint32_t)rx[0] << 24) |
                   ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8)  |
                   ((uint32_t)rx[3]);

    uint8_t fault = (uint8_t)(raw & 0x0F);
    if (fault != RTD_FAULT_NONE) {
        fprintf(stderr, "MAX31865 fault: 0x%02X (RTD=0x%02X, A0=0x%02X, A1=0x%02X, A2=0x%02X, A3=0x%02X)\n",
                fault,
                (raw >> 12) & 0x0F,
                (raw >> 8)  & 0x0F,
                (raw >> 4)  & 0x0F,
                (raw >> 0)  & 0x0F);
        return -1;
    }

    uint16_t rtd_code = (uint16_t)((raw >> 12) & 0x0FFF);
    if (rtd_code == 0) {
        fprintf(stderr, "MAX31865: RTD code is zero (sensor absent or not connected)\n");
        return -1;
    }

    int16_t rtd_resistance = (int16_t)rtd_code;
    if (rtd_resistance < 0)
        rtd_resistance = -rtd_resistance;

    double rtd_ohms = (double)rtd_resistance / 100.0;
    double temp_c = -258.96 + (25.0 + (rtd_ohms - 100.0) / 100.0) * (4.306 + (rtd_ohms - 100.0) / 100.0 * (0.001103 + (rtd_ohms - 100.0) / 100.0 * 0.000000063));

    data[0] = (uint8_t)(temp_c * 100.0);
    data[1] = (uint8_t)(temp_c * 100.0 + 0.5);
    data[2] = (uint8_t)(temp_c * 100.0 + 0.5);
    data[3] = '\n';
    return 0;
}

static int log_temperature(const char *ts, const char *temp)
{
    if (fprintf(g_log_fp, "%s,%.2f\n", ts, atof(temp)) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0)
        return 1;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_fp, "timestamp,temperature_c\n");
    fflush(g_log_fp);

    printf("MAX31865 RTD logger started. Logging to %s every %d seconds.\n", LOG_FILE, READ_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t data[4] = {0};
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

        if (read_max31865(data) == 0) {
            char temp_str[16];
            snprintf(temp_str, sizeof(temp_str), "%.2f", (double)data[0] + (double)data[1] / 100.0);
            if (log_temperature(ts, temp_str) < 0)
                fprintf(stderr, "Logging failed at %s\n", ts);
            else
                printf("%s - Temperature: %s C\n", ts, temp_str);
        } else {
            fprintf(stderr, "%s - Sensor read error\n", ts);
        }

        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

