/*
 * BME280 I2C reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   BME280 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   BME280 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   BME280 VDD -> 3.3 V
 *   BME280 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o bme280_log bme280_log.c -li2c -lm
 * Run:    ./bme280_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BME280 constants (verified against datasheet DS42668) ---- */
#define BME280_I2C_ADDR          0x76
#define BME280_REG_ID            0xD0
#define BME280_REG_RESET         0xE0
#define BME280_REG_CTRL_HUM      0xF2
#define BME280_REG_STATUS        0xF3
#define BME280_REG_CTRL_MEAS     0xF4
#define BME280_REG_CONFIG        0xF5
#define BME280_REG_PRESS_MSB     0xF7
#define BME280_REG_TEMP_MSB      0xFA
#define BME280_REG_HUM_MSB       0xFD

#define BME280_CHIP_ID           0x60
#define BME280_RESET_CMD         0xB6

/* Oversampling: temp x1, press x1, humidity x1 */
#define BME280_OSRS_T_1X         0x20
#define BME280_OSRS_P_1X         0x04
#define BME280_OSRS_H_1X         0x01

/* Filter: off */
#define BME280_FILTER_OFF        0x00

/* Standby: 1000 ms */
#define BME280_T_SB              0x05

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
