    int32_t press_pa = raw_to_pressure(raw, cal, t_fine);
    uint32_t hum_pct_u = raw_to_humidity(raw, cal, t_fine);

    *temp_c    = t_centi / 100.0f;
    *hum_pct   = hum_pct_u / 1024.0f;
    *press_hpa = press_pa / 100.0f;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, float temp_c, float hum_pct, float press_hpa)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, temp_c, hum_pct, press_hpa);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    bme280_calib_t cal;
    if (bme280_init(g_i2c_fd, &cal) != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("bme280_log.csv", "a");
    if (!g_log_fp) {
        perror("fopen bme280_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_c, hum_pct, press_hpa;
        if (bme280_read(g_i2c_fd, &cal, &temp_c, &hum_pct, &press_hpa) == 0) {
            log_data(g_log_fp, temp_c, hum_pct, press_hpa);
        } else {
            fprintf(stderr, "Sensor read error; continuing\n");
        }
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

