#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define ALERT_GPIO 24
#define BUFFER_SIZE 720  /* 60 seconds * 12 readings/second */
#define DEVIATION_THRESHOLD 5.0f
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

/* BMP180 Registers */
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

/* BMP180 Commands */
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS1 0x34

/* Calibration data */
typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float pressure;
} pressure_reading_t;

static pressure_reading_t pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static float rolling_average = 0.0f;
static bool i2c_initialized = false;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_word(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(handle, buf, 2);
}

static int read_calibration_data(int handle, bmp180_cal_t *c) {
    if (i2c_read_word(handle, 0xAA, &c->ac1) < 0) return -1;
    if (i2c_read_word(handle, 0xAC, &c->ac2) < 0) return -1;
    if (i2c_read_word(handle, 0xAE, &c->ac3) < 0) return -1;
    if (i2c_read_word(handle, 0xB0, (int16_t*)&c->ac4) < 0) return -1;
    if (i2c_read_word(handle, 0xB2, (int16_t*)&c->ac5) < 0) return -1;
    if (i2c_read_word(handle, 0xB4, (int16_t*)&c->ac6) < 0) return -1;
    if (i2c_read_word(handle, 0xB6, &c->b1) < 0) return -1;
    if (i2c_read_word(handle, 0xB8, &c->b2) < 0) return -1;
    if (i2c_read_word(handle, 0xBA, &c->mb) < 0) return -1;
    if (i2c_read_word(handle, 0xBC, &c->mc) < 0) return -1;
    if (i2c_read_word(handle, 0xBE, &c->md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    if (i2c_read_word(handle, BMP180_REG_MSB, (int16_t*)raw) < 0) return -1;
    *raw >>= 8;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS1) < 0) return -1;
    gpioDelay(5000);
    char buf[3];
    if (i2cWriteByte(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *raw = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 1) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 1);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void update_rolling_average(float new_pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = new_pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i].pressure;
    rolling_average = sum / buffer_count;
}

static void check_pressure_deviation(float current_pressure) {
    if (buffer_count == 0) return;
    float deviation = current_pressure - rolling_average;
    if (deviation > DEVIATION_THRESHOLD) {
        fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa, Deviation: %.2f hPa\n",
                current_pressure, rolling_average, deviation);
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(1000000);
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void cleanup(void) {
    if (i2c_initialized) {
        i2cClose(i2c_handle);
        i2c_initialized = false;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    i2c_initialized = true;

    if (read_calibration_data(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        cleanup();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (!terminate) {
        int32_t ut, up;
        if (read_raw_temperature(i2c_handle, &ut) < 0) {
            fprintf(stderr, "I2C error reading temperature\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_raw_pressure(i2c_handle, &up) < 0) {
            fprintf(stderr, "I2C error reading pressure\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float pressure = calculate_pressure(ut, up, &cal);
        update_rolling_average(pressure);
        check_pressure_deviation(pressure);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

