#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define TIMER_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int16_t val;
    uint16_t uval;

    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1) < 0) return -1;
    ac1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2) < 0) return -1;
    ac2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3) < 0) return -1;
    ac3 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4) < 0) return -1;
    ac4 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5) < 0) return -1;
    ac5 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6) < 0) return -1;
    ac6 = (uint16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1) < 0) return -1;
    b1 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2) < 0) return -1;
    b2 = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB) < 0) return -1;
    mb = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC) < 0) return -1;
    mc = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    if (i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD) < 0) return -1;
    md = (int16_t)i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == 0 || ac1 == 0xFFFF || ac2 == 0 || ac2 == 0xFFFF ||
        ac3 == 0 || ac3 == 0xFFFF || ac4 == 0 || ac4 == 0xFFFF ||
        ac5 == 0 || ac5 == 0xFFFF || ac6 == 0 || ac6 == 0xFFFF ||
        b1 == 0 || b1 == 0xFFFF || b2 == 0 || b2 == 0xFFFF ||
        mb == 0 || mb == 0xFFFF || mc == 0 || mc == 0xFFFF ||
        md == 0 || md == 0xFFFF) {
        fprintf(stderr, "Error: Invalid calibration data (sensor may be absent or bus error)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *raw_temp = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS0) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static int calculate_temperature(int32_t raw_temp, double *temp_c) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
