#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define LOG_FILE "fan_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp_out) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long millideg = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid temperature format\n");
        return -1;
    }

    *temp_out = (float)millideg / 1000.0;
    return 0;
}

static int map_temp_to_duty(float temp) {
    if (temp <= TEMP_MIN) return 0;
    if (temp >= TEMP_MAX) return PWM_RANGE;
    return (int)(((temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * PWM_RANGE);
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    if (fprintf(log_file, "%s, %.2f, %d\n", timestamp, temp, duty) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Failed to read CPU temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int duty = map_temp_to_duty(temp);

        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle\n");
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f°C, Duty: %d/%d\n", temp, duty, PWM_RANGE);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    printf("Fan control stopped.\n");
    return 0;
}

