#define BMP280_REG_CALIB    0x88

/* ctrl_meas: osrs_t=x8 (001), osrs_p=x8 (001), mode=forced (11) -> 0b00100111 = 0x27 */
#define BMP280_FORCED_MODE  0x27

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Calibration coefficients (BMP280 datasheet, 24-bit signed) ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calib(int fd, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, buf, sizeof(buf)) != 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

/* Returns 0 on success, -1 on error */
static int bmp280_read(int fd, const bmp280_calib_t *cal,
                        float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_p, raw_t;
    int32_t var1, var2, t_fine;
    int32_t p_acc;
    uint32_t p_acc_u;

    /* Trigger forced-mode measurement */
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, BMP280_FORCED_MODE) != 0) return -1;

    /* Wait for measurement to complete (max ~5.5 ms for x8/x8) */
    usleep(6000);

    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) return -1;

    raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
