    p_acc = p_acc + ((int32_t)cal->dig_P4 << 35);
    p_acc = p_acc + (raw_p << 1);
    p_acc = p_acc + (raw_p * (int32_t)cal->dig_P3 >> 2);
    p_acc = p_acc + ((raw_p * raw_p * (int32_t)cal->dig_P2 >> 12) >> 12);
