    return 0;
}

static int log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    int addr = BMP280_ADDR_1;
    bmp280_calib_t cal;
    float temperature, pressure;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Try default address first */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return 1;
    }

    /* Verify sensor identity */
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Cannot read BMP280 ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x58). "
                        "Sensor not present or wrong device.\n", id);
        close(fd);
        return 1;
    }

    /* Read calibration coefficients */
    if (bmp280_read_calib(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    /* Set config: t_sb=0.5ms (000), filter=off (000), spi3w_en=0 -> 0x20 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x20) != 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("BMP280 initialized at 0x%02X. Logging to %s every %d s.\n",
           addr, LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        if (bmp280_read(fd, &cal, &temperature, &pressure) == 0) {
            printf("T=%.2f °C  P=%.2f hPa\n", temperature, pressure);
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed: %s\n", strerror(errno));
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down cleanly.\n");
    if (fd >= 0) close(fd);
    return 0;
