#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75_ADDR      0x48
#define LM75_TEMP_REG  0x00
#define GPIO_LED       18
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0
#define TEMP_THRESHOLD 28.0

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static int      g_gpio_pin = GPIO_LED;
static pthread_mutex_t g_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static CircularBuffer g_temp_buffer = {0};

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, LM75_ADDR, strerror(errno));
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioSetMode(g_gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                g_gpio_pin, strerror(errno));
        return -1;
    }
    if (gpioWrite(g_gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing GPIO %d low: %s\n",
                g_gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature)
{
    char reg = LM75_TEMP_REG;
    char data[2] = {0};

    if (i2cWriteDevice(g_i2c_fd, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(g_i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw * 0.1f;
    return 0;
}

static void add_to_buffer(float temperature)
{
    pthread_mutex_lock(&g_buffer_mutex);
    g_temp_buffer.buffer[g_temp_buffer.head] = temperature;
    g_temp_buffer.head = (g_temp_buffer.head + 1) % BUFFER_SIZE;
    if (g_temp_buffer.count < BUFFER_SIZE)
        g_temp_buffer.count++;
    pthread_mutex_unlock(&g_buffer_mutex);
}

static float calculate_average(void)
{
    float sum = 0.0f;
    int count = 0;

    pthread_mutex_lock(&g_buffer_mutex);
    for (int i = 0; i < g_temp_buffer.count; i++) {
        sum += g_temp_buffer.buffer[i];
        count++;
    }
    pthread_mutex_unlock(&g_buffer_mutex);

    return (count > 0) ? (sum / (float)count) : 0.0f;
}

static void *led_thread(void *arg)
{
    (void)arg;
    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            pthread_mutex_lock(&g_buffer_mutex);
            add_to_buffer(temp);
            float avg = calculate_average();
            pthread_mutex_unlock(&g_buffer_mutex);

            int led_state = (temp > TEMP_THRESHOLD) ? 1 : 0;
            if (gpioWrite(g_gpio_pin, led_state) != 0) {
                fprintf(stderr, "Error writing to GPIO %d: %s\n",
                        g_gpio_pin, strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading temperature, attempting reinit...\n");
            if (init_i2c() != 0 || init_gpio() != 0) {
                fprintf(stderr, "Reinit failed, exiting thread.\n");
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }
    return NULL;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_gpio_pin = GPIO_LED;

    if (init_i2c() != 0 || init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_t led_tid;
    if (pthread_create(&led_tid, NULL, led_thread, NULL) != 0) {
        fprintf(stderr, "Error creating LED thread: %s\n", strerror(errno));
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        time_sleep(SAMPLE_PERIOD);
    }

