#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define HEATER_MAX_TEMP 80.0
#define HEATER_REF_RES 430.0
#define PT100_NOMINAL_RES 100.0
#define CONFIG_FILE "config.json"
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int driver_id = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31865(int handle, double *temperature) {
    char data[4] = {0};
    int ret = spiRead(handle, data, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed (returned %d)\n", ret);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)data[0] << 24) |
                   ((uint32_t)(uint8_t)data[1] << 16) |
                   ((uint32_t)(uint8_t)data[2] << 8)  |
                   ((uint32_t)(uint8_t)data[3]);
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31865 fault detected (raw=0x%08X)\n", raw);
        return -2;
    }
    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    *temperature = (temp_raw / 16383.0) * 100.0;
    return 0;
}

static double calculate_resistance(double temperature) {
    return PT100_NOMINAL_RES * (1.0 + 0.00385 * temperature);
}

static double calculate_heater_current(double resistance) {
    return 5.0 / resistance;
}

static double calculate_heater_power(double current) {
    return current * 5.0;
}

static double pid_control(double setpoint, double actual, double kp, double ki, double kd,
                          double *integral, double *previous_error) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *previous_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

static int load_configuration(const char *filename, double *setpoint, double *kp, double *ki, double *kd) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to load config: %s\n", error.text);
        return -1;
    }
    json_t *sp = json_object_get(root, "setpoint");
    json_t *kp_obj = json_object_get(root, "kp");
    json_t *ki_obj = json_object_get(root, "ki");
    json_t *kd_obj = json_object_get(root, "kd");
    if (sp && json_is_real(sp)) *setpoint = json_real_value(sp);
    if (kp_obj && json_is_real(kp_obj)) *kp = json_real_value(kp_obj);
    if (ki_obj && json_is_real(ki_obj)) *ki = json_real_value(ki_obj);
    if (kd_obj && json_is_real(kd_obj)) *kd = json_real_value(kd_obj);
    json_decref(root);
    return 0;
}

static void cleanup(void) {
    if (driver_id >= 0) {
        gpioPWM(PWM_GPIO, 0);
        gpioSetPWMfrequency(PWM_GPIO, 0);
        gpioSetPWMrange(PWM_GPIO, 0);
        gpioSetMode(PWM_GPIO, PI_INPUT);
        gpioSetDriveMode(driver_id, PI_ALT0);
        gpioTerminate();
    }
    if (spi_handle >= 0) spiClose(spi_handle);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    driver_id = gpioSetMode(PWM_GPIO, PI_ALT0);
    if (driver_id < 0) {
        fprintf(stderr, "Failed to set PWM GPIO mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    double setpoint = 25.0, kp = 1.0, ki = 0.1, kd = 0.01;
    if (load_configuration(CONFIG_FILE, &setpoint, &kp, &ki, &kd) != 0) {
        fprintf(stderr, "Using defaults: setpoint=%.1f Kp=%.3f Ki=%.3f Kd=%.3f\n", setpoint, kp, ki, kd);
    }

    double integral = 0.0, previous_error = 0.0;
    int failsafe_active = 0;

    while (running) {
        double temp;
        int rc = read_max31865(spi_handle, &temp);
        if (rc != 0) {
            if (rc == -2) {
                fprintf(stderr, "MAX31865 fault, shutting down\n");
                failsafe_active = 1;
            }
            gpioPWM(PWM_GPIO, 0);
            break;
        }
        if (temp > HEATER_MAX_TEMP) {
            fprintf(stderr, "Temperature %.2f C exceeds %.1f C, shutting down\n", temp, HEATER_MAX_TEMP);
            failsafe_active = 1;
        }
        double resistance = calculate_resistance(temp);
        double current = calculate_heater_current(resistance);
        double power = calculate_heater_power(current);
        double pid_out = pid_control(setpoint, temp, kp, ki, kd, &integral, &previous_error);
        int duty = (int)(pid_out * 100.0 / power);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        gpioPWM(PWM_GPIO, duty);
        printf("T=%.2f C R=%.2f ohm I=%.3f A P=%.2f W duty=%d/%d\n", temp, resistance, current, power, duty, PWM_RANGE);
        usleep(LOOP_DELAY_US);
    }

    if (failsafe_active) {
        fprintf(stderr, "Failsafe triggered, heater off\n");
    }
    cleanup();
    return failsafe_active ? 1 : 0;
}

