        fprintf(stderr, "Failed to read BMP180 calibration data: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 on %s (addr 0x%02X)... Press Ctrl+C to exit.\n", I2C_BUS, BMP180_ADDR);

    while (running) {
        int32_t raw_temp, raw_pressure;
        if (read_raw_temperature(i2c_fd, &raw_temp) != 0) {
            fprintf(stderr, "Temperature read failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }
        if (read_raw_pressure(i2c_fd, &raw_pressure) != 0) {
            fprintf(stderr, "Pressure read failed: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

