static int  bmp180_read_calibration(void);
static int  bmp180_read_raw_temp(int32_t *ut);
static int  bmp180_read_raw_press(int32_t *up);
static float bmp180_compute_temperature(int32_t ut);
static float bmp180_compute_pressure(int32_t up, int32_t ut);
static void  buffer_add(time_t ts, float temp, float press);
static void  timer_callback(void *userdata);
static void  cleanup(void);
static void  signal_handler(int sig);

/* ---- BMP180 calibration read ---- */
static int bmp180_read_calibration(void)
{
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }

    cal.ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    cal.ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    cal.ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    cal.ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    cal.ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    cal.ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal.b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal.b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal.mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal.mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal.md  = (int16_t)((buf[20] << 8) | buf[21]);

    if (cal.ac1 == 0 && cal.ac2 == 0 && cal.ac3 == 0 &&
        cal.ac4 == 0 && cal.ac5 == 0 && cal.ac6 == 0) {
        fprintf(stderr, "Error: calibration data is all zero (sensor absent?)\n");
        return -1;
    }
    return 0;
}

/* ---- Raw temperature read ---- */
static int bmp180_read_raw_temp(int32_t *ut)
{
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    uint8_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

/* ---- Raw pressure read (OSS = 0) ---- */
static int bmp180_read_raw_press(int32_t *up)
{
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS_OSS0) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time for OSS=0 */

    uint8_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    uint8_t xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }
    *up = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb;
    *up >>= 8;  /* OSS=0: shift right 8 to get 16-bit result */
    return 0;
}

/* ---- Temperature (°C) ---- */
static float bmp180_compute_temperature(int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

/* ---- Pressure (Pa) ---- */
static float bmp180_compute_pressure(int32_t up, int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t b3 = (((int32_t)cal.ac1 * 4 + x3 + x4) + 2) >> 2;

    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + x4 + 2)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);  /* OSS=0 */

    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p;
}

/* ---- Circular buffer ---- */
static void buffer_add(time_t ts, float temp, float press)
{
    buffer.data[buffer.head].timestamp = ts;
    buffer.data[buffer.head].temperature = temp;
    buffer.data[buffer.head].pressure    = press;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

/* ---- Timer callback (500 ms) ---- */
static void timer_callback(void *userdata)
{
    (void)userdata;

    int32_t ut, up;

    if (bmp180_read_raw_temp(&ut) != 0) return;
    if (bmp180_read_raw_press(&up) != 0) return;

    float temp = bmp180_compute_temperature(ut);
    float press = bmp180_compute_pressure(up, ut);

    time_t now = time(NULL);
    buffer_add(now, temp, press);

    printf("[%ld] Temp: %.2f C  Pressure: %.2f Pa\n",
           (long)now, temp, press);
    fflush(stdout);

    if (temp > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp180_read_calibration() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    buffer.head = 0;
    buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        gpioDelay(100000);  /* 100 ms sleep */
    }

    gpioSetTimerFuncEx(0, 0, NULL, NULL);  /* disable timer */
    cleanup();
    return EXIT_SUCCESS;
}

