        fprintf(stderr, "[WARN] I2C read (temp) attempt %d failed\n", attempt + 1);
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ---- Read raw uncompensated pressure ---- */
static int bmp180_read_raw_pressure(int handle, int32_t *up)
{
    char cmd[1] = { BMP180_CMD_PRESSURE_00 };
    char data[3];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, cmd, 1) != 0) {
            fprintf(stderr, "[WARN] I2C write (pressure) attempt %d failed\n", attempt + 1);
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }
        gpioDelay(BMP180_PRESSURE_WAIT_US);
        if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, data, 3) == 3) {
            *up = ((int32_t)(data[0] & 0xFF) << 16) |
                  ((int32_t)(data[1] & 0xFF) << 8)  |
                  ((int32_t)(data[2] & 0xFF));
            *up >>= 8;  /* OSS = 0 */
            return 0;
        }
        fprintf(stderr, "[WARN] I2C read (pressure) attempt %d failed\n", attempt + 1);
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ---- Bosch compensation (OSS = 0) ---- */
static int bmp180_compute_pressure(int32_t ut, int32_t up, int32_t *pressure_pa)
{
    int32_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;  /* OSS = 0 */

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)up - b3) * (50000 >> 0);  /* OSS = 0 */

    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *pressure_pa = p;
    return 0;
}

/* ---- Log pressure to file ---- */
static void log_pressure(int32_t pressure_pa)
{
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("[ERROR] fopen pressure_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %d\n", ts, pressure_pa);
    } else {
        fprintf(fp, "(time-error), %d\n", pressure_pa);
    }

    fclose(fp);
}

/* ---- Button ISR (falling edge) ---- */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0) {
        return; /* Only act on falling edge */
    }

    uint32_t now = gpioTick();
    if ((now - g_last_interrupt_tick) < DEBOUNCE_US) {
        return; /* Debounce */
    }
    g_last_interrupt_tick = now;

    g_logging_enabled = !g_logging_enabled;
    printf("[INFO] Logging %s\n", g_logging_enabled ? "enabled" : "disabled");
}

/* ---- Main ---- */
int main(void)
{
    int handle = -1;
    int ret = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Configure button GPIO */
    gpioSetMode(GPIO_BUTTON, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);

    /* Open I2C bus 1 at BMP180 address */
    handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (addr 0x%02X): %d\n", BMP180_ADDR, handle);
        goto cleanup;
    }

    /* Read calibration coefficients */
    if (bmp180_read_calibration(handle) != 0) {
        fprintf(stderr, "[ERROR] Failed to read BMP180 calibration data\n");
        goto cleanup;
    }

    /* Register ISR on falling edge */
    if (gpioSetISRFuncEx(GPIO_BUTTON, FALLING_EDGE, DEBOUNCE_US, button_isr, NULL) != 0) {
        fprintf(stderr, "[ERROR] gpioSetISRFuncEx failed\n");
        goto cleanup;
    }

    printf("[INFO] BMP180 logger started. Press button (GPIO27) to toggle logging.\n");

    while (g_running) {
        if (g_logging_enabled) {
            int32_t ut, up, pressure_pa;

            if (bmp180_read_raw_temperature(handle, &ut) != 0) {
                fprintf(stderr, "[ERROR] Temperature read failed; retrying next cycle\n");
                gpioDelay(LOG_INTERVAL_US);
                continue;
            }
            if (bmp180_read_raw_pressure(handle, &up) != 0) {
                fprintf(stderr, "[ERROR] Pressure read failed; retrying next cycle\n");
                gpioDelay(LOG_INTERVAL_US);
                continue;
            }
            if (bmp180_compute_pressure(ut, up, &pressure_pa) != 0) {
                fprintf(stderr, "[ERROR] Pressure computation failed\n");
                gpioDelay(LOG_INTERVAL_US);
                continue;
            }
            log_pressure(pressure_pa);
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (handle >= 0) {
        i2cClose(handle);
    }
    cleanup();
    return ret;
}

