#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 0.8
#define KP 1.0
#define KI 0.1
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char buffer[4];
    int result = spiRead(handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: short to ground\n");
        } else if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: unknown\n");
        }
        return -2;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;
    }
    *temperature = thermocouple_raw * 0.25;
    return 0;
}

static float calculate_duty_cycle(float temperature, float target) {
    static float integral = 0.0;
    float error = target - temperature;
    float proportional = KP * error;
    integral += KI * error;
    float output = proportional + integral;
    if (output < 0.0) output = 0.0;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    return output;
}

static void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioWrite(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, duty_cycle;
    while (running) {
        if (read_max31855(spi_handle, &temperature) == 0) {
            duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE);
            gpioPWM(HEATER_GPIO, (int)(duty_cycle * 1000000));
            log_data(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Sensor read error, setting duty cycle to 0\n");
            gpioPWM(HEATER_GPIO, 0);
            log_data(-999.0, 0.0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

