#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define POLL_US    500000  /* 0.5 seconds */

/* Common-anode RGB LED: cathode to GPIO, 330 ohm resistors per channel */
#define PWM_RANGE  255
#define PWM_DUTY_OFF 255  /* 255 = 100% duty = channel off (common anode) */

static volatile sig_atomic_t g_running = 1;
static FILE *g_temp_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Set a PWM duty cycle on the given pin.
 * Returns 0 on success, -1 on failure.
 */
static int set_pwm(int pin, int duty)
{
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

/*
 * Read CPU temperature in millidegrees Celsius from the sysfs file.
 * Returns 0 on success and stores the value in *out_temp; returns -1 on error.
 */
static int read_cpu_temp(int *out_temp)
{
    char buffer[32];
    ssize_t bytes_read;

    if (g_temp_fp == NULL) {
        g_temp_fp = fopen(TEMP_FILE, "r");
        if (g_temp_fp == NULL) {
            fprintf(stderr, "Error: cannot open %s: %s\n",
                    TEMP_FILE, strerror(errno));
            return -1;
        }
    }

    bytes_read = fread(buffer, 1, sizeof(buffer) - 1, g_temp_fp);
    if (bytes_read < 0) {
        fprintf(stderr, "Error: fread failed: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        fprintf(stderr, "Error: read 0 bytes from %s\n", TEMP_FILE);
        return -1;
    }

    buffer[bytes_read] = '\0';

    /* Strip trailing newline/CR if present */
    size_t len = strlen(buffer);
    while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r')) {
        buffer[--len] = '\0';
    }

    char *endptr = NULL;
    errno = 0;
    long temp_long = strtol(buffer, &endptr, 10);
    if (errno != 0 || endptr == buffer) {
        fprintf(stderr, "Error: invalid temperature data: '%s'\n", buffer);
        return -1;
    }

    *out_temp = (int)temp_long;
    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    /* Common-anode: 0 duty = full brightness, 255 duty = off */
    set_pwm(RED_PIN,   PWM_DUTY_OFF - red);
    set_pwm(GREEN_PIN, PWM_DUTY_OFF - green);
    set_pwm(BLUE_PIN,  PWM_DUTY_OFF - blue);
}

static void all_led_off(void)
{
    set_pwm(RED_PIN,   PWM_DUTY_OFF);
    set_pwm(GREEN_PIN, PWM_DUTY_OFF);
    set_pwm(BLUE_PIN,  PWM_DUTY_OFF);
}

int main(void)
{
    int temp_milli;
    int red, green, blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM range for 0-255 duty cycle */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup */
    all_led_off();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("CPU Temperature Monitor (common-anode RGB LED)\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_cpu_temp(&temp_milli) != 0) {
            fprintf(stderr, "Error reading temperature, skipping cycle\n");
            gpioDelay(POLL_US);
            continue;
        }

        printf("Temperature: %d m°C  RGB(%d, %d, %d)\n",
               temp_milli, 0, 0, 0);  /* placeholder until color logic */
        fflush(stdout);

        if (temp_milli < 40000) {
            red   = 0;
            green = 0;
            blue  = 255;
        } else if (temp_milli < 60000) {
            red   = 0;
            green = 255;
            blue  = 0;
        } else {
            red   = 255;
            green = 0;
            blue  = 0;
        }

        set_led_color(red, green, blue);

        gpioDelay(POLL_US);
    }

    /* Graceful shutdown */
    all_led_off();

    if (g_temp_fp != NULL) {
        fclose(g_temp_fp);
        g_temp_fp = NULL;
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

