    set_pwm(GREEN_PIN, PWM_DUTY_OFF);
    set_pwm(BLUE_PIN,  PWM_DUTY_OFF);
}

int main(void)
{
    int temp_milli;
    int red, green, blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM range for 0-255 duty cycle */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup */
    all_led_off();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("CPU Temperature Monitor (common-anode RGB LED)\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_cpu_temp(&temp_milli) != 0) {
            fprintf(stderr, "Error reading temperature, skipping cycle\n");
            gpioDelay(POLL_US);
            continue;
        }

        printf("Temperature: %d m°C  RGB(%d, %d, %d)\n",
               temp_milli, 0, 0, 0);  /* placeholder until color logic */
        fflush(stdout);

        if (temp_milli < 40000) {
            red   = 0;
            green = 0;
            blue  = 255;
        } else if (temp_milli < 60000) {
            red   = 0;
            green = 255;
            blue  = 0;
        } else {
            red   = 255;
            green = 0;
            blue  = 0;
        }

        set_led_color(red, green, blue);

        gpioDelay(POLL_US);
    }

    /* Graceful shutdown */
    all_led_off();

    if (g_temp_fp != NULL) {
        fclose(g_temp_fp);
        g_temp_fp = NULL;
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

