#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3
#define MAX_RETRIES_DELAY_MS 1000
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int send_http_request(const char *json_data) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", SERVER_IP);
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST /api/humidity HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s", SERVER_IP, strlen(json_data), json_data);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        fprintf(stderr, "Request buffer too small\n");
        close(sock);
        return -1;
    }

    if (write(sock, request, req_len) < 0) {
        perror("write");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

static int read_dht22(float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int last_state = PI_HIGH;
    int bits_read = 0;
    uint32_t start_tick, elapsed;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(500000);

    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    for (int i = 0; i < 85; i++) {
        int state = gpioRead(DHT22_GPIO);
        if (state < 0) return -1;

        if (state != last_state) {
            last_state = state;
            if (state == PI_LOW) {
                start_tick = gpioTick();
                while (gpioRead(DHT22_GPIO) == PI_LOW) {
                    if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
                }
                elapsed = gpioTick() - start_tick;
                if (elapsed > 50) {
                    data[bits_read / 8] |= (1 << (7 - (bits_read % 8)));
                }
                bits_read++;
            }
        }
    }

    if (bits_read < 40) return -1;

    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) return -1;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

static int send_data_with_retry(float humidity, float temperature) {
    char json_data[256];
    snprintf(json_data, sizeof(json_data),
        "{\"humidity\": %.1f, \"temperature\": %.1f}",
        humidity, temperature);

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (send_http_request(json_data) == 0) {
            return 0;
        }
        fprintf(stderr, "Attempt %d failed. Retrying in %d ms...\n",
            attempt, MAX_RETRIES_DELAY_MS);
        gpioDelay(MAX_RETRIES_DELAY_MS * 1000);
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        float humidity, temperature;
        if (read_dht22(&humidity, &temperature) == 0) {
            printf("Humidity: %.1f%%, Temperature: %.1f°C\n",
                humidity, temperature);
            if (send_data_with_retry(humidity, temperature) != 0) {
                fprintf(stderr, "Failed to send data after %d retries.\n",
                    MAX_RETRIES);
            }
        } else {
            fprintf(stderr, "DHT22 read failed.\n");
        }
        gpioDelay(60000000);
    }

    gpioTerminate();
    return 0;
}

