/*
 * BMP180 pressure logger with a falling-edge GPIO interrupt toggle.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: BMP180 at address 0x77
 * Button: GPIO4, internal pull-up, falling-edge interrupt
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_log bmp180_log.c -lpigpio -lrt
 * Run:    sudo ./bmp180_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants -------------------------------------------------- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE

#define BMP180_OSS              3
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define BMP180_CONV_TIME_US     26000   /* OSS=3: 4.5 ms max; 26 ms worst-case */

/* ---- GPIO / interrupt constants --------------------------------------- */
#define BUTTON_GPIO             4
#define DEBOUNCE_US             200000  /* 200 ms */
#define LOG_INTERVAL_US         2000000 /* 2 s   */
#define LOG_FILE                "pressure_log.txt"

/* ---- Globals ----------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging = 0;
static volatile uint32_t      g_last_tick = 0;
static int                     g_i2c_handle = -1;

/* ---- Calibration coefficients ----------------------------------------- */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t g_cal;
static int g_cal_valid = 0;

/* ---- Prototypes ------------------------------------------------------- */
static int  bmp180_read_calibration(void);
static int  bmp180_read_raw_temp(int32_t *ut);
static int  bmp180_read_raw_pressure(int32_t *up);
static int  bmp180_compute_b5(int32_t ut, int32_t *b5_out);
static int  bmp180_compute_pressure(int32_t up, int32_t b5, int32_t *pressure_pa);
static void log_pressure(int32_t pressure_pa);
static void button_isr(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);

/* ---- BMP180 calibration read ------------------------------------------ */
static int bmp180_read_calibration(void)
{
    uint8_t buf[22];

    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }

    g_cal.ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    g_cal.ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    g_cal.ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    g_cal.ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    g_cal.ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    g_cal.ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    g_cal.b1  = (int16_t)((buf[12] << 8) | buf[13]);
    g_cal.b2  = (int16_t)((buf[14] << 8) | buf[15]);
    g_cal.mb  = (int16_t)((buf[16] << 8) | buf[17]);
    g_cal.mc  = (int16_t)((buf[18] << 8) | buf[19]);
    g_cal.md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity-check: AC1/AC6 must not be 0 or 0xFFFF on a real BMP180 */
    if (g_cal.ac1 == 0 || g_cal.ac1 == (int16_t)0x8000 ||
        g_cal.ac6 == 0 || g_cal.ac6 == 0xFFFF) {
        fprintf(stderr, "Error: invalid calibration data (sensor absent?)\n");
        return -1;
    }

    g_cal_valid = 1;
    return 0;
}

/* ---- Raw temperature read -------------------------------------------- */
static int bmp180_read_raw_temp(int32_t *ut)
{
    uint8_t cmd[2] = { BMP180_REG_CONTROL, BMP180_CMD_TEMP };

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000); /* 4.5 ms max */

    uint8_t buf[2];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }

    *ut = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- Raw pressure read ------------------------------------------------ */
static int bmp180_read_raw_pressure(int32_t *up)
{
    uint8_t cmd[2] = { BMP180_REG_CONTROL, BMP180_CMD_PRESSURE | (BMP180_OSS << 6) };

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(BMP180_CONV_TIME_US);

    uint8_t buf[3];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }

    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

/* ---- Compute B5 ------------------------------------------------------- */
static int bmp180_compute_b5(int32_t ut, int32_t *b5_out)
{
    int32_t x1 = ((ut - (int32_t)g_cal.ac6) * (int32_t)g_cal.ac5) >> 15;
    int32_t x2 = ((int32_t)g_cal.mc << 11) / (x1 + (int32_t)g_cal.md);
    *b5_out = x1 + x2;
    return 0;
}

/* ---- Compute pressure in Pa ------------------------------------------ */
static int bmp180_compute_pressure(int32_t up, int32_t b5, int32_t *pressure_pa)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)g_cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)g_cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)g_cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);

    uint32_t b4 = ((uint32_t)g_cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (uint32_t)(50000 >> BMP180_OSS);

    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure_pa = p + ((x1 + x2 + 3791) >> 4);
    return 0;
}

/* ---- Log pressure to file -------------------------------------------- */
static void log_pressure(int32_t pressure_pa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f hPa\n", ts, pressure_pa / 100.0);
    } else {
        fprintf(fp, "(timestamp error), %.2f hPa\n", pressure_pa / 100.0);
    }

    fclose(fp);
}

/* ---- Button ISR ------------------------------------------------------- */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)userdata;

    uint32_t diff = tick - g_last_tick;
    if (diff < DEBOUNCE_US) {
        return; /* debounce */
    }
    g_last_tick = tick;

    g_logging = !g_logging;
    printf("Logging %s\n", g_logging ? "enabled" : "disabled");
    fflush(stdout);
}

/* ---- Signal handler --------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp180_read_calibration() != 0) {
        fprintf(stderr, "Error: BMP180 calibration read failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetAlertFuncEx(BUTTON_GPIO, button_isr, NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 logger ready. Press button on GPIO4 to toggle logging.\n");
    fflush(stdout);

    while (g_running) {
        if (g_logging) {
            int32_t ut, up, b5;
            if (bmp180_read_raw_temp(&ut) == 0 &&
                bmp180_read_raw_pressure(&up) == 0 &&
                bmp180_compute_b5(ut, &b5) == 0) {
                int32_t pressure_pa;
                if (bmp180_compute_pressure(up, b5, &pressure_pa) == 0) {
                    log_pressure(pressure_pa);
                } else {
                    fprintf(stderr, "Error: pressure computation failed\n");
                }
            } else {
                fprintf(stderr, "Error: sensor read failed\n");
            }
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

