#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <getopt.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define READ_INTERVAL 10
#define MAX_RETRIES_COUNT 3
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-library's-api-call.com/api/humidity";

typedef struct {
    float humidity;
    int valid;
} DHT22Data;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static char *get_iso8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = malloc(25);
    if (!timestamp) return NULL;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S", timeinfo);
    return timestamp;
}

static void log_message(int priority, const char *message) {
    char *ts = get_iso8601_timestamp();
    if (ts) {
        syslog(priority, "%s %s", ts, message);
        free(ts);
    } else {
        syslog(priority, "%s", message);
    }
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents; (void)userp;
    return size * nmemb;
}

static int post_humidity_data(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        log_message(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }
    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
    char *url = strdup(api_url);
    if (!url) {
        log_message(LOG_ERR, "strdup() failed");
        curl_easy_cleanup(curl);
        return -1;
    }
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        log_message(LOG_ERR, "curl_slist_append() failed");
        free(url);
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    int ret = -1;
    if (res == CURLE_OK && http_code >= 200 && http_code < 300) {
        ret = 0;
    } else {
        char msg[256];
        snprintf(msg, sizeof(msg), "HTTP POST failed: %s (code %ld)", curl_easy_strerror(res), http_code);
        log_message(LOG_ERR, msg);
    }
    curl_slist_free_all(headers);
    free(url);
    curl_easy_cleanup(curl);
    return ret;
}

static DHT22Data read_dht22(int gpio_pin) {
    DHT22Data data = {0.0f, 0};
    uint8_t bits[5] = {0};
    int i, j;
    struct timespec start, end;
    long elapsed_us;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(2000);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30);
    gpioSetMode(gpio_pin, PI_INPUT);

    for (i = 0; i < 85; i++) {
        if (gpioRead(gpio_pin) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpioRead(gpio_pin) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
                if (elapsed_us > DHT22_TIMEOUT_US) goto retry;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (elapsed_us > DHT22_TIMEOUT_US) goto retry;
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpioRead(gpio_pin) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
                if (elapsed_us > DHT22_TIMEOUT_US) goto retry;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (elapsed_us > 50) bits[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (bits[0] + bits[1] + bits[2] + bits[3] != bits[4]) {
        log_message(LOG_ERR, "DHT22 checksum failed");
        goto retry;
    }

    data.humidity = (bits[0] * 256 + bits[1]) / 10.0f;
    data.valid = 1;
    return data;

retry:
    log_message(LOG_ERR, "DHT22 read failed, retrying...");
    return data;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = strdup(optarg);
                if (!api_url) {
                    fprintf(stderr, "Error: Failed to allocate memory for URL.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s url]\n", argv[0]);
                return 1;
        }
    }

    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting DHT22 sensor monitoring...");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    curl_global_init(CURL_GLOBAL_DEFAULT);

    while (running) {
        DHT22Data dht_data = {0.0f, 0};
        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            dht_data = read_dht22(DHT22_GPIO);
            if (dht_data.valid) break;
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(2);
            }
        }

        if (dht_data.valid) {
            int post_retries = 0;
            while (post_retries < MAX_RETRIES && running) {
                if (post_humidity_data(dht_data.humidity) == 0) {
                    log_message(LOG_INFO, "Humidity data posted successfully");
                    break;
                }
                post_retries++;
                if (post_retries < MAX_RETRIES) {
                    sleep(2);
                }
            }
        } else {
            log_message(LOG_ERR, "Failed to read DHT22 sensor after multiple retries");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    log_message(LOG_INFO, "Shutting down...");
    curl_global_cleanup();
    closelog();
    return 0;
}

