    data.humidity = (bits[0] * 256 + bits[1]) / 10.0f;
    data.valid = 1;
    return data;

retry:
    log_message(LOG_ERR, "DHT22 read failed, retrying...");
    return data;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = strdup(optarg);
                if (!api_url) {
                    fprintf(stderr, "Error: Failed to allocate memory for URL.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s url]\n", argv[0]);
                return 1;
        }
    }

    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting DHT22 sensor monitoring...");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    curl_global_init(CURL_GLOBAL_DEFAULT);

    while (running) {
        DHT22Data dht_data = {0.0f, 0};
        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            dht_data = read_dht22(DHT22_GPIO);
            if (dht_data.valid) break;
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(2);
            }
        }

        if (dht_data.valid) {
            int post_retries = 0;
            while (post_retries < MAX_RETRIES && running) {
                if (post_humidity_data(dht_data.humidity) == 0) {
                    log_message(LOG_INFO, "Humidity data posted successfully");
                    break;
                }
                post_retries++;
                if (post_retries < MAX_RETRIES) {
                    sleep(2);
                }
            }
        } else {
            log_message(LOG_ERR, "Failed to read DHT22 sensor after multiple retries");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    log_message(LOG_INFO, "Shutting down...");
    curl_global_cleanup();
    closelog();
    return 0;
}

