#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening CPU temp file: %s\n", strerror(errno));
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading CPU temp: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int read_fan_state(void) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file: %s\n", strerror(errno));
        return -1;
    }
    int state;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return state;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening fan state file for writing: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_max_state(void) {
    FILE *fp = fopen(MAX_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening max state file: %s\n", strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max state: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int calculate_fan_speed(int cpu_temp_milli) {
    int temp_celsius = cpu_temp_milli / 1000;
    if (temp_celsius < 45) return 0;
    if (temp_celsius < 55) return 1;
    if (temp_celsius < 65) return 2;
    return 3;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int current_fan_state = -1;
    int max_state = -1;

    while (program_running) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp < 0) {
            log_event("Error reading CPU temperature, retrying...");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int desired_fan_state = calculate_fan_speed(cpu_temp);

        if (current_fan_state != desired_fan_state) {
            if (max_state == -1) {
                max_state = read_max_state();
                if (max_state < 0) {
                    log_event("Error reading max fan state, retrying...");
                    sleep(POLL_INTERVAL_SEC);
                    continue;
                }
            }
            if (desired_fan_state > max_state) {
                desired_fan_state = max_state;
            }
            if (write_fan_state(desired_fan_state) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message),
                         "Fan speed changed to %d (CPU temp: %d mC)",
                         desired_fan_state, cpu_temp);
                log_event(log_message);
                current_fan_state = desired_fan_state;
            } else {
                log_event("Error writing fan state, retrying...");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (current_fan_state != 0) {
        if (write_fan_state(0) == 0) {
            log_event("Fan speed set to 0 on shutdown.");
        } else {
            log_event("Error setting fan to 0 on shutdown.");
        }
    }
    log_event("Program terminated.");
    return 0;
}

