    int bytes = spiRead(g_spi_handle, (char *)rx, 4);
    if (bytes != 4) {
        snprintf(fault_str, fault_len, "SPI read error (got %d bytes)", bytes);
        return -1;
    }

    /* Fault bit is the 16th bit of the 32-bit word (byte 3, bit 7) */
    if (rx[3] & 0x80) {
        if (rx[3] & 0x01)
            snprintf(fault_str, fault_len, "Open circuit");
        else if (rx[3] & 0x02)
            snprintf(fault_str, fault_len, "Short to GND");
        else if (rx[3] & 0x04)
            snprintf(fault_str, fault_len, "Short to VCC");
        else
            snprintf(fault_str, fault_len, "Unknown fault");
        return -2;
    }

    /*
     * 32-bit big-endian data:
     *   D31..D18 : 14-bit signed thermocouple temp (°C)
     *   D15..D4  : 12-bit signed internal (cold-junction) temp
     *   D3       : reserved
     *   D2       : fault bit
     *   D1       : reserved
     *   D0       : reserved
     *
     * Thermocouple data is in bits 31..18 (14-bit signed, 0.25 °C LSB).
     */
    int32_t raw = ((int32_t)rx[0] << 24) |
                  ((int32_t)rx[1] << 16) |
                  ((int32_t)rx[2] <<  8) |
                  ((int32_t)rx[3]);

    int16_t temp_raw = (int16_t)(raw >> 18);  /* sign-extends 14-bit */
    *temperature = (float)temp_raw * 0.25f;

    snprintf(fault_str, fault_len, "OK");
    return 0;
}

/* ----------------------------- PID calculation ---------------------------- */
static float calculate_pid(float current_temp, float target_temp)
{
    static float integral = 0.0f;
    static float prev_error = 0.0f;
    float error = target_temp - current_temp;

    integral += error;
    float derivative = error - prev_error;
    prev_error = error;

    float output = (KP * error) + (KI * integral) + (KD * derivative);
    return output;
}

/* ----------------------------- Heater PWM -------------------------------- */
static int set_heater_pwm(float duty_cycle)
{
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 100.0f) duty_cycle = 100.0f;

    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0f));
    if (gpioPWM(HEATER_GPIO, pwm_value) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO%d\n", HEATER_GPIO);
        return -1;
    }
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float current_temp, float duty_cycle, float pid_output)
{
    FILE *fp = fopen("heater_log.txt", "a");
    if (!fp) {
        perror("fopen heater_log.txt");
        return;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", current_temp, duty_cycle, pid_output);
    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    /* Ensure heater is off before terminating pigpio */
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Heater GPIO as output */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioPWM(HEATER_GPIO, 0);  /* Heater off initially */

    /* Configure hardware PWM on GPIO18 */
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 500 kHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PID heater controller started. Target: %.1f °C | Ctrl+C to exit\n",
           TARGET_TEMPERATURE);

    int consecutive_errors = 0;

    while (g_running) {
        float current_temp = 0.0f;
        char fault_str[64] = "OK";
        int rc = read_max31855(&current_temp, fault_str, sizeof(fault_str));

        if (rc == 0) {
            consecutive_errors = 0;

            if (current_temp < MIN_TEMPERATURE || current_temp > MAX_TEMPERATURE) {
                fprintf(stderr, "Temperature out of range: %.2f °C (fault=%s)\n",
                        current_temp, fault_str);
                gpioPWM(HEATER_GPIO, 0);
                log_data(current_temp, 0.0f, 0.0f);
            } else {
                float pid_output = calculate_pid(current_temp, TARGET_TEMPERATURE);
                float duty_cycle = pid_output;

                if (set_heater_pwm(duty_cycle) == 0) {
                    log_data(current_temp, duty_cycle, pid_output);
                    printf("T=%.2f °C | PID=%.2f | Duty=%.2f%%\n",
                           current_temp, pid_output, duty_cycle);
                }
            }
        } else if (rc == -2) {
            consecutive_errors++;
            fprintf(stderr, "MAX31855 fault: %s\n", fault_str);
            gpioPWM(HEATER_GPIO, 0);
            log_data(0.0f, 0.0f, 0.0f);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive MAX31855 faults. Aborting.\n");
                break;
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "SPI read error (attempt %d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);
            gpioPWM(HEATER_GPIO, 0);
            log_data(0.0f, 0.0f, 0.0f);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors. Aborting.\n");
                break;
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

