/*
 * Raspberry Pi 4 Model B — Noctua NF-A4x10 PWM fan controller
 *
 * Wiring:
 *   Fan PWM  -> GPIO18 (physical pin 12)
 *   Fan V+    -> 5 V (pin 2 or 4)
 *   Fan GND   -> GND (pin 6)
 *
 * The Noctua NF-A4x10 accepts a 5 V PWM signal on its 4-pin header.
 * The PWM frequency is set to 25 kHz (typical for 4-pin PC fans) and
 * the duty cycle is varied linearly between 0 % (fan off) and 100 %
 * (fan at full speed) as the CPU temperature rises from 40 °C to 70 °C.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_control fan_control.c -lpigpio -lrt
 * Run:    sudo ./fan_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define PWM_FREQUENCY_HZ  25000          /* 25 kHz — typical for 4-pin PC fans */
#define TEMP_LOW_C        40.0f
#define TEMP_HIGH_C       70.0f
#define LOG_FILE          "cooling_log.csv"
#define POLL_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CPU temperature (Celsius)                                          */
/* ------------------------------------------------------------------ */
static float read_cpu_temperature(void)
{
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("fopen /sys/class/thermal/thermal_zone0/temp");
        return -1.0f;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "fscanf failed for CPU temperature\n");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);

    return (float)temp_milli / 1000.0f;
}

/* ------------------------------------------------------------------ */
/* Linear mapping: 40 °C -> 0 %, 70 °C -> 100 %                        */
/* ------------------------------------------------------------------ */
static int calculate_pwm_duty_percent(float temperature)
{
    if (temperature <= TEMP_LOW_C)
        return 0;
    if (temperature >= TEMP_HIGH_C)
        return 100;

    float frac = (temperature - TEMP_LOW_C) / (TEMP_HIGH_C - TEMP_LOW_C);
    return (int)(frac * 100.0f + 0.5f);
}

/* ------------------------------------------------------------------ */
/* PWM helpers                                                          */
/* ------------------------------------------------------------------ */
static int set_pwm_frequency(int gpio, int frequency)
{
    if (gpioSetPWMfrequency(gpio, frequency) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d, %d) failed\n", gpio, frequency);
        return -1;
    }
    return 0;
}

static int set_pwm_duty_percent(int gpio, int percent)
{
    if (percent < 0)   percent = 0;
    if (percent > 100) percent = 100;

    int range = 255;          /* pigpio default range for PWM */
    int duty = (percent * range) / 100;

    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "gpioPWM(%d, %d) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, int duty_percent)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%d\n", ts, temperature, duty_percent) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure fan is off before terminating pigpio */
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO18 as PWM output --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Set PWM frequency --- */
    if (set_pwm_frequency(FAN_GPIO, PWM_FREQUENCY_HZ) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Ensure fan starts off --- */
    if (set_pwm_duty_percent(FAN_GPIO, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Write CSV header if file is new/empty --- */
    FILE *hdr = fopen(LOG_FILE, "r");
    if (!hdr) {
        hdr = fopen(LOG_FILE, "w");
        if (hdr) {
            fprintf(hdr, "timestamp,temperature_c,pwm_duty_percent\n");
            fclose(hdr);
        } else {
            perror("fopen (header)");
        }
    } else {
        fclose(hdr);
    }

    printf("Fan control started. GPIO%d @ %d Hz. Ctrl+C to exit.\n",
           FAN_GPIO, PWM_FREQUENCY_HZ);

    /* --- Main polling loop --- */
    while (g_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0.0f) {
            fprintf(stderr, "Temperature read failed; skipping cycle.\n");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int duty = calculate_pwm_duty_percent(temperature);

        if (set_pwm_duty_percent(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty; continuing.\n");
        }

        if (log_data(temperature, duty) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Temp: %.2f °C  |  Fan: %d%%\n", temperature, duty);

        sleep(POLL_INTERVAL_S);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Fan control stopped.\n");
    return EXIT_SUCCESS;
}

