#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8 polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_flow_rate(int handle, int *flow_rate) {
    uint8_t buf[3];
    int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "I2C read error on handle %d: %d\n", handle, bytes_read);
        return -1;
    }
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return -2;
    }
    *flow_rate = (int)((buf[0] << 8) | buf[1]);
    return 0;
}

static int log_flow_data(int flow1, int flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
