#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x48
#define RED_CHANNEL 0x00
#define IR_CHANNEL 0x01
#define LED_GPIO 17
#define IR_THRESHOLD 2000
