#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Interrupt service routine (ISR) */
static void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

/* Function to calculate RPM */
static float calculate_rpm(int pulse_count) {
    return (float)pulse_count * 60.0f;
}

/* Function to log RPM to file */
static void log_rpm(float rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    int ret;

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* Set GPIO18 as input with pull-down resistor */
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not install SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not install SIGTERM handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR for rising edge detection */
    ret = gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set ISR function: %d\n", ret);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    /* Main loop */
    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        if (!running) {
            break;
        }

        int local_pulse_count = 0;
        pthread_mutex_lock(&pulse_mutex);
        local_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        float rpm = calculate_rpm(local_pulse_count);
        log_rpm(rpm);
    }

    /* Graceful shutdown */
    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

