/*
 * ADPD144RI photometric sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO2 (pin 3)
 *   ADPD144RI SCL -> GPIO3 (pin 5)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode   -> GPIO17 (pin 11) through 330 Ω resistor -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -li2c -lpigpio -lrt
 *
 * Run:
 *   sudo ./adpd144ri
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x04          /* ADPD144RI default I2C address */
#define RED_REG        0x00          /* Red photodiode result register */
#define IR_REG         0x01          /* Infrared photodiode result register */
#define LED_GPIO       17
#define THRESHOLD      2000
#define SAMPLE_US      100000        /* 100 ms */
#define LOG_FILE       "adpd144ri_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*
 * Read a 16-bit little-endian register from the ADPD144RI.
 * Returns 0 on success, -1 on error.
 */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: expected 2 bytes, got %d (%s)\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u\n", ts, red, ir) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (read_reg16(g_i2c_handle, RED_REG, &red) != 0 ||
            read_reg16(g_i2c_handle, IR_REG, &ir) != 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            if (log_data(g_log_fp, red, ir) != 0) {
                fprintf(stderr, "Logging failed — continuing.\n");
            }

            if (ir > THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

