        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GAIN_SELECT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO%d LOW (60 dB gain)\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    int prev_level = 0;
    while (running) {
        int level = gpioRead(AUDIO_INPUT_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", AUDIO_INPUT_PIN);
            break;
        }

        if (level == 1 && prev_level == 0) {
            if (log_audio_event(1) != 0) {
                fprintf(stderr, "Failed to log audio event\n");
            }
        }

        prev_level = level;
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("Audio sampling stopped.\n");
    return EXIT_SUCCESS;
}

