/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC Sensor Logger
 *
 * Reads TVOC (ppb) and eCO2 (ppm) from an MICS-VZ-89TE on I2C bus 1,
 * computes an indoor air quality (IAQ) index, and logs timestamped
 * CSV records every 5 seconds to air_quality_log.csv.
 *
 * Wiring:
 *   VDD  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 * Run:    sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x28          /* MICS-VZ-89TE default I2C address */
#define LOG_FILE             "air_quality_log.csv"
#define SAMPLE_INTERVAL_S    5
#define MAX_RETRIES          3
#define RETRY_DELAY_US       100000        /* 100 ms between retries */

/* MICS-VZ-89TE register addresses */
#define REG_TVOC_MSB         0x04
#define REG_TVOC_LSB         0x05
#define REG_ECO2_MSB         0x06
#define REG_ECO2_LSB         0x07
#define REG_STATUS           0x08
#define REG_CONFIG           0x09

/* Status register bits */
#define STATUS_ERROR         0x01
#define STATUS_READY         0x02

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_i2c(void);
static int  read_sensor_data(uint16_t *tvoc, uint16_t *eco2);
static int  compute_iaq(uint16_t tvoc, uint16_t eco2, int *iaq);
static void log_data(uint16_t tvoc, uint16_t eco2, int iaq);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C Init ----------------------------------- */
static int initialize_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    /*
     * Probe the sensor by reading the status register.
     * A negative handle or a zero-length read typically means the
     * device is not present at the given address.
     */
    int status = i2cReadByteData(i2c_handle, REG_STATUS);
    if (status < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X (read failed: %d)\n",
                I2C_ADDR, status);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Clear any latched error bit and configure the sensor */
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to write CONFIG register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- Sensor Read -------------------------------- */
static int read_sensor_data(uint16_t *tvoc, uint16_t *eco2)
{
    int status;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        status = i2cReadByteData(i2c_handle, REG_STATUS);
        if (status >= 0) {
            if (status & STATUS_ERROR) {
                fprintf(stderr, "[WARN] Sensor error flag set (status=0x%02X), retrying...\n",
                        status);
                retries++;
                gpioDelay(RETRY_DELAY_US);
                continue;
            }
            if (!(status & STATUS_READY)) {
                fprintf(stderr, "[WARN] Sensor not ready (status=0x%02X), retrying...\n",
                        status);
                retries++;
                gpioDelay(RETRY_DELAY_US);
                continue;
            }
            break;
        }
        fprintf(stderr, "[WARN] I2C status read failed (attempt %d/%d): %d\n",
                retries + 1, MAX_RETRIES, status);
        retries++;
        gpioDelay(RETRY_DELAY_US);
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "[ERROR] Sensor not ready after %d retries\n", MAX_RETRIES);
        return -1;
    }

    /* Read TVOC (2 bytes, MSB first) */
    int tvoc_msb = i2cReadByteData(i2c_handle, REG_TVOC_MSB);
    int tvoc_lsb = i2cReadByteData(i2c_handle, REG_TVOC_LSB);
    if (tvoc_msb < 0 || tvoc_lsb < 0) {
        fprintf(stderr, "[ERROR] TVOC read failed (msb=%d, lsb=%d)\n", tvoc_msb, tvoc_lsb);
        return -1;
    }
    *tvoc = ((uint16_t)tvoc_msb << 8) | (uint16_t)tvoc_lsb;

    /* Read eCO2 (2 bytes, MSB first) */
    int eco2_msb = i2cReadByteData(i2c_handle, REG_ECO2_MSB);
    int eco2_lsb = i2cReadByteData(i2c_handle, REG_ECO2_LSB);
    if (eco2_msb < 0 || eco2_lsb < 0) {
        fprintf(stderr, "[ERROR] eCO2 read failed (msb=%d, lsb=%d)\n", eco2_msb, eco2_lsb);
        return -1;
