/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC Sensor Logger
 *
 * Reads TVOC (ppb) and eCO2 (ppm) from an MICS-VZ-89TE on I2C bus 1,
 * computes an indoor air quality (IAQ) index, and logs timestamped
 * CSV records every 5 seconds to air_quality_log.csv.
 *
 * Wiring:
 *   VDD  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 * Run:    sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
