#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 17          /* BCM GPIO 17, physical pin 11 */
#define CONSUMER_LABEL     "ttp223_tamper"
#define POLL_INTERVAL_US   100000     /* 100 ms */
#define ALERT_THRESHOLD_S  5          /* 5 seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void cleanup(int pin)
{
    if (pin >= 0) {
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_OFF);
    }
    gpioTerminate();
}

int main(void)
{
    int pin = TOUCH_SENSOR_PIN;
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", pin, strerror(errno));
        cleanup(pin);
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(pin, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Failed to disable pull-up/down on GPIO %d: %s\n", pin, strerror(errno));
        cleanup(pin);
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(pin, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d: %s\n", pin, strerror(errno));
        cleanup(pin);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM). Press Ctrl+C to exit.\n", pin);

    struct timespec touch_start;
    int touch_active = 0;

    while (g_running) {
        int level = gpioRead(pin);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        if (level == 1) {
            if (!touch_active) {
                touch_active = 1;
                if (clock_gettime(CLOCK_MONOTONIC, &touch_start) != 0) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
            }
        } else {
            touch_active = 0;
        }

        if (touch_active) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                ret = EXIT_FAILURE;
                break;
            }

            double elapsed = (now.tv_sec - touch_start.tv_sec)
                           + (now.tv_nsec - touch_start.tv_nsec) / 1e9;

            if (elapsed >= ALERT_THRESHOLD_S) {
                printf("Intrusion detected! Touch held for %.1f seconds.\n", elapsed);
                fflush(stdout);
                touch_active = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup(pin);
    return ret;
}

