/*
 * INMP441 I2S MEMS Microphone Capture for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   INMP441 SCL  -> Pi I2S SCL (GPIO 15 / PCM CLK)
 *   INMP441 SDO  -> Pi I2S SDO (GPIO 14 / PCM FS)
 *   INMP441 DIN  -> Pi I2S DIN (GPIO 13 / PCM DIN)
 *   INMP441 L/R  -> Pi GPIO 17 (BCM)
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define GPIO_CHANNEL    17
#define SAMPLE_RATE     48000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS    2
#define CAPTURE_DURATION 10
#define OUTPUT_FILE     "audio_capture.pcm"

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int set_gpio_channel(int channel)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            perror("Failed to open gpio export");
            return -1;
        }
    } else {
        if (write(fd, "17", 3) < 0) {
            perror("Failed to export GPIO 17");
            close(fd);
            return -1;
        }
        close(fd);
    }

    fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction");
        return -1;
    }
    if (write(fd, "out", 3) < 0) {
        perror("Failed to set GPIO direction");
        close(fd);
        return -1;
    }
    close(fd);

    fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
