    if (write(fd, (channel == 0) ? "0" : "1", 3) < 0) {
        perror("Failed to set GPIO value");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

static int initialize_alsa(int *fd)
{
    int format = AFMT_S16_LE;
    int channels = NUM_CHANNELS;
    int rate = SAMPLE_RATE;
    int period_size = 1024;

    int hw_params = 0;
    int hw_params_size = sizeof(hw_params);

    *fd = open(I2S_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open ALSA device");
        return -1;
