        perror("Failed to get hardware parameters");
        close(*fd);
        return -1;
    }

    hw_params.nr_channels = channels;
    hw_params.format.linear = format;
    hw_params.rate.value = rate;
    hw_params.rate.step = 0;
    hw_params.period_size = period_size;
    hw_params.periods = 1;

    if (ioctl(*fd, SNDRV_PCM_IOCTL_HW_PARAMS_SET, &hw_params) < 0) {
        perror("Failed to set hardware parameters");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SNDRV_PCM_IOCTL_HW_PARAMS_GET, &hw_params) < 0) {
        perror("Failed to get updated hardware parameters");
        close(*fd);
        return -1;
    }

    if (hw_params.rate.value != rate) {
        fprintf(stderr, "Warning: ALSA clock not exactly %d Hz, got %d\n", rate, hw_params.rate.value);
    }

    if (ioctl(*fd, SNDRV_PCM_IOCTL_HW_STREAM_PARAMS_SET, &hw_params) < 0) {
        perror("Failed to set stream parameters");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SNDRV_PCM_IOCTL_HW_STREAM_PARAMS_GET, &hw_params) < 0) {
        perror("Failed to get updated stream parameters");
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_audio(int fd, FILE *fp, int duration_seconds)
{
    int bytes_per_sample = BITS_PER_SAMPLE / 8;
    int samples_per_second = SAMPLE_RATE;
    int total_samples = samples_per_second * duration_seconds;
    int total_bytes = total_samples * NUM_CHANNELS * bytes_per_sample;
    int bytes_written = 0;
    int bytes_to_write = total_bytes;
    int bytes_to_read = 1024;
    unsigned char buffer[1024];
    int left_channel = 0;

    while (!terminate && bytes_written < total_bytes) {
        if (set_gpio_channel(left_channel) < 0) {
            fprintf(stderr, "Failed to set GPIO channel\n");
            return -1;
        }

        ssize_t bytes_read = read(fd, buffer, bytes_to_read);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Failed to read from ALSA device");
            return -1;
        }
