            fprintf(stderr, "ALSA device closed unexpectedly\n");
            return -1;
        }

        size_t bytes_to_write_this_time = (size_t)bytes_read;
        if (bytes_to_write_this_time > bytes_to_write) {
            bytes_to_write_this_time = bytes_to_write;
