        goto cleanup;
    }

    if (capture_audio(fd, fp, CAPTURE_DURATION) < 0) {
        fprintf(stderr, "Audio capture failed\n");
        goto cleanup;
    }

    ret = 0;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

