#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define SENSOR_TIMEOUT_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file);
    }
    printf("%s - %s\n", timestamp, event_type);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set fan PWM pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise PWM to 0\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PWM_PIN, 0);
    gpioWrite(FLAME_SENSOR_PIN, 0);
    gpioTerminate();
}

static int read_flame_sensor(void) {
    int reading = gpioRead(FLAME_SENSOR_PIN);
    if (reading < 0) {
        fprintf(stderr, "Error: Failed to read flame sensor\n");
        return -1;
    }
    return reading;
}

static void control_fan(int flame_detected) {
    if (flame_detected) {
        if (gpioPWM(FAN_PWM_PIN, 128) != 0) {
            fprintf(stderr, "Error: Failed to start PWM\n");
        } else {
            log_event("Flame detected - fan activated");
        }
    } else {
        if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to stop PWM\n");
        } else {
            log_event("Flame cleared - fan stopped");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    int last_flame_state = 0;
    uint32_t last_change_tick = gpioTick();
    uint32_t sensor_timeout_start = gpioTick();

    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected < 0) {
            log_event("Error reading flame sensor");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (flame_detected != last_flame_state) {
            uint32_t now = gpioTick();
            if ((now - last_change_tick) > DEBOUNCE_DELAY_US) {
                last_change_tick = now;
                last_flame_state = flame_detected;
                control_fan(flame_detected);
            }
        }

        uint32_t elapsed = gpioTick() - sensor_timeout_start;
        if (elapsed > SENSOR_TIMEOUT_US) {
            log_event("Sensor timeout - possible sensor absent");
            sensor_timeout_start = gpioTick();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    return EXIT_SUCCESS;
}

