/*
 * AWR1642 mmWave radar SPI reader for Raspberry Pi 4 Model B
 *
 * SPI: /dev/spidev0.0  (CE0 / GPIO8), 1 MHz, mode 0
 * Trigger: GPIO23 (BCM) - hardware frame trigger
 * Data-ready: GPIO24 (BCM) - interrupt-driven data capture
 *
 * Captures 32768-byte range-Doppler heatmap frames at 100 ms intervals
 * and logs them to a binary file with a 4144 magic header.
 *
 * Build: gcc -O2 -Wall -o radar_reader radar_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define TRIGGER_PIN     23
#define DATA_READY_PIN  24

#define FRAME_SIZE      32768
#define LOG_MAGIC       4144
#define LOG_FILE        "radar_data.log"
#define CAPTURE_PERIOD  100000  /* microseconds (100 ms) */

/*
 * AWR1642 range-Doppler configuration (from TI mmWave SDK).
 * Each frame is 32768 bytes; the struct is written to the log file.
 */
typedef struct __attribute__((packed)) {
    uint32_t start_freq_hz;
    uint32_t end_freq_hz;
    uint16_t num_chirps;
    uint16_t num_samples;
} radar_config_t;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN): %s\n", pigpio_error(0));
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(DATA_READY_PIN): %s\n", pigpio_error(0));
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0): %s\n", pigpio_error(0));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE, "wb");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    uint32_t magic = LOG_MAGIC;
    if (fwrite(&magic, sizeof(magic), 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(magic): %s\n", strerror(errno));
        fclose(g_log_fp); g_log_fp = NULL;
        return -1;
    }

    radar_config_t cfg = {
        .start_freq_hz = 77000000000ULL,
        .end_freq_hz   = 79000000000ULL,
        .num_chirps    = 64,
        .num_samples   = 256
    };

    if (fwrite(&cfg, sizeof(cfg), 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(config): %s\n", strerror(errno));
        fclose(g_log_fp); g_log_fp = NULL;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int capture_frame(uint8_t *frame)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 1): %s\n", pigpio_error(0));
        return -1;
    }

    /* Wait for data-ready interrupt (poll with timeout) */
    int ready = 0;
    for (int i = 0; i < 100; i++) {
        ready = gpioRead(DATA_READY_PIN);
        if (ready == 1) break;
        gpioDelay(1000); /* 1 ms */
    }
    if (ready != 1) {
        fprintf(stderr, "Timeout waiting for data-ready\n");
        gpioWrite(TRIGGER_PIN, 0);
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0): %s\n", pigpio_error(0));
        return -1;
    }

    uint8_t *tx = malloc(FRAME_SIZE);
    if (!tx) {
        fprintf(stderr, "malloc(%zu): %s\n", FRAME_SIZE, strerror(errno));
        return -1;
    }

    uint8_t *rx = malloc(FRAME_SIZE);
    if (!rx) {
        fprintf(stderr, "malloc(%zu): %s\n", FRAME_SIZE, strerror(errno));
        free(tx);
        return -1;
    }

    if (spi_transfer(tx, rx, FRAME_SIZE) < 0) {
        free(tx); free(rx);
        return -1;
    }

    memcpy(frame, rx, FRAME_SIZE);
    free(tx); free(rx);
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_frame(uint8_t *frame)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(&ts, sizeof(ts), 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(timestamp): %s\n", strerror(errno));
        return -1;
    }

    uint32_t frame_num = 0;
    if (fwrite(&frame_num, sizeof(frame_num), 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(frame_num): %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(frame, FRAME_SIZE, 1, g_log_fp) != 1) {
        fprintf(stderr, "fwrite(frame): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
