/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state = -1;          /* Unknown initial state */
    int first_read = 1;

    /* --- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --------------------------------------------- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Enable the internal pull-down so the input reads 0 when the
     * sensor output is open or floating.  The KY-026 digital output
     * is active-high (1 = flame detected).
     */
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d.  Logging to '%s'.\n",
           FLAME_SENSOR_GPIO, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", FLAME_SENSOR_GPIO);
            break;
        }

        if (first_read) {
            /* Log the initial state so the log is never empty. */
            char ts[32];
            if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
                printf("Initial state: %s - Flame %s\n",
                       ts, level ? "DETECTED" : "CLEARED");
                if (log_state_change(ts, level) != 0) {
                    fprintf(stderr, "Warning: initial state not logged.\n");
                }
            } else {
                fprintf(stderr, "Failed to generate initial timestamp.\n");
            }
            first_read = 0;
            last_state = level;
            continue;
        }

        if (level != last_state) {
            char ts[32];
            if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
                printf("%s - Flame %s\n", ts, level ? "DETECTED" : "CLEARED");
                if (log_state_change(ts, level) != 0) {
                    fprintf(stderr, "Error logging state change.\n");
                }
            } else {
                fprintf(stderr, "Failed to generate timestamp.\n");
            }
            last_state = level;
        }

        gpioDelay(POLL_INTERVAL_US);   /* 100 ms */
    }

    /* --- Cleanup ---------------------------------------------------- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

