/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD -> 3.3 V
 *   OPT3001 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o opt3001_logger opt3001_logger.c -li2c -lm
 *
 * Run:
 *   ./opt3001_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define OPT3001_ADDR     0x54
#define DATA_FILE        "light_data.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define MAX_RETRIES      3

/* OPT3001 register addresses */
#define REG_RESULT_LO    0x00
#define REG_RESULT_HI    0x01
#define REG_CONFIG       0x02
#define REG_MANUFACTURER 0x7E
#define REG_DEVICE_ID    0x7F

/* Expected manufacturer / device ID for OPT3001 */
#define OPT3001_MANUFACTURER 0x54
#define OPT3001_DEVICE_ID   0x01

/*
 * Configuration register (0x02) bit layout:
 *   [7:6] = Range (00 = 0.00015 lux, 01 = 0.015 lux, 10 = 1.5 lux, 11 = 15 lux)
 *   [5]   = Auto-range (1 = enable)
 *   [4]   = Continuous mode (1 = continuous)
 *   [3:2] = Conversion time (00 = 100 ms, 01 = 200 ms, 10 = 400 ms, 11 = 800 ms)
 *   [1:0] = Reserved
 *
 * 0x40 -> 100 ms conversion time, auto-range enabled, continuous mode.
 */
#define CONFIG_VALUE 0x40

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_data_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int opt3001_init(int fd)
{
    uint8_t manuf = 0, device_id = 0;

    /* Verify sensor presence by reading manufacturer / device ID */
    if (i2c_read_reg8(fd, REG_MANUFACTURER, &manuf) < 0) {
        fprintf(stderr, "Cannot read manufacturer register - sensor absent or bus error.\n");
        return -1;
    }
    if (manuf != OPT3001_MANUFACTURER) {
        fprintf(stderr, "Unexpected manufacturer ID 0x%02X (expected 0x%02X).\n",
                manuf, OPT3001_MANUFACTURER);
        return -1;
    }

    if (i2c_read_reg8(fd, REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Cannot read device ID register.\n");
        return -1;
    }
    if (device_id != OPT3001_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X).\n",
                device_id, OPT3001_DEVICE_ID);
        return -1;
    }

    printf("OPT3001 detected (manufacturer=0x%02X, device_id=0x%02X).\n",
           manuf, device_id);

    /* Configure: 100 ms conversion time, auto-range, continuous mode */
    if (i2c_write_reg8(fd, REG_CONFIG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to configure OPT3001.\n");
        return -1;
    }

    /* Allow first conversion to complete */
    usleep(150000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read lux with retry                                                */
/* ------------------------------------------------------------------ */
static int opt3001_read_lux(int fd, float *lux_out)
{
    uint8_t lo = 0, hi = 0;
    int16_t raw;
    float lux;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg8(fd, REG_RESULT_LO, &lo) < 0) {
            usleep(10000);
            continue;
        }
        if (i2c_read_reg8(fd, REG_RESULT_HI, &hi) < 0) {
            usleep(10000);
            continue;
        }

        raw = (int16_t)((hi << 8) | lo);

        /*
         * OPT3001 result is left-justified in 16 bits.
         * The 16-bit value is scaled by the current range.
         * With auto-range enabled, the default range is 0.00015 lux.
         * The 16-bit value is divided by 16384 (0x4000) to get the
         * scaled lux value.
         */
        lux = (float)raw / 16384.0f * 0.00015f;

        /* Sanity-check: lux should be non-negative */
        if (lux < 0.0f) {
            fprintf(stderr, "Warning: negative lux reading (%.6f) - retrying.\n",
                    lux);
            usleep(10000);
            continue;
        }

        *lux_out = lux;
        return 0;
    }

    fprintf(stderr, "Failed to read lux after %d attempts.\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed.\n");
        return;
    }

    if (fprintf(fp, "%s, %.4f\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to data file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_data_file != NULL) {
        fclose(g_data_file);
        g_data_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* Install signal handlers for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (opt3001_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open data file for appending */
    g_data_file = fopen(DATA_FILE, "a");
    if (g_data_file == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", DATA_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging OPT3001 lux readings to %s every %d ms. Press Ctrl+C to stop.\n",
           DATA_FILE, SAMPLE_PERIOD_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_fd, &lux) == 0) {
            log_data(g_data_file, lux);
        } else {
            fprintf(stderr, "Skipping sample due to read failure.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(SAMPLE_PERIOD_US / 10);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

