#define POLL_INTERVAL_SEC  1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) != NULL) {
        if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0)
            printf("%s", buf);
        else
            printf("unknown-time");
    } else {
        printf("unknown-time");
    }
}

/* ------------------------------------------------------------------ */
