 *
 * Wiring:
 *   VCC  -> 3V3 (Pin 1)
 *   GND  -> GND (Pin 9)
 *   OUT1 -> BCM GPIO2 (Pin 3)
 *   OUT2 -> BCM GPIO3 (Pin 5)
 *   OUT3 -> BCM GPIO4 (Pin 7)
 *   OUT4 -> BCM GPIO5 (Pin 29)
 *   OUT5 -> BCM GPIO6 (Pin 31)
 *   OUT6 -> BCM GPIO7 (Pin 33)
 *   OUT7 -> BCM GPIO8 (Pin 35)
 *   OUT8 -> BCM GPIO9 (Pin 37)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 5, 6, 7, 8, 9
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret;
    int i;

    memset(lines, 0, sizeof(lines));
    memset(values, 0, sizeof(values));

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as an input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-reader");
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Channel | Pin | Value\n");
    printf("--------+-----+-------\n");
    fflush(stdout);

    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = ret;
        }

        print_timestamp();
        for (i = 0; i < NUM_CHANNELS; i++) {
            printf("  CH%d  | BCM%u | %d\n",
                   i + 1, channel_pins[i], values[i]);
        }
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return (program_running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

