#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <ttp226.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int ret;
    int values[NUM_CHANNELS];
    int i;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Initialize TTP226 driver --- */
    ret = ttp226_init();
    if (ret != 0) {
        fprintf(stderr, "Error: TTP226 initialization failed (code %d).\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        ret = ttp226_read(values);
        if (ret != 0) {
            fprintf(stderr, "Error: TTP226 read failed (code %d).\n", ret);
            break;
        }

        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        /* Sleep in small increments so signals are caught promptly */
        for (i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    /* --- Clean shutdown --- */
    ttp226_close();
    gpioTerminate();
    return EXIT_SUCCESS;
}

