/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   CH0 -> GPIO2  (physical pin 3)
 *   CH1 -> GPIO3  (physical pin 5)
 *   CH2 -> GPIO4  (physical pin 7)
 *   CH3 -> GPIO17 (physical pin 11)
 *   CH4 -> GPIO27 (physical pin 13)
 *   CH5 -> GPIO22 (physical pin 15)
 *   CH6 -> GPIO10 (physical pin 19)
 *   CH7 -> GPIO9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lpigpio -lrt
 * Run:    sudo ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000   /* 50 ms */

static const int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

int main(void)
{
    int *channel_states = NULL;
    int *requested_lines = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Allocate state arrays --- */
    channel_states = calloc(NUM_CHANNELS, sizeof(int));
    requested_lines = calloc(NUM_CHANNELS, sizeof(int));
    if (channel_states == NULL || requested_lines == NULL) {
        fprintf(stderr, "Error: failed to allocate state arrays.\n");
        goto cleanup;
    }

    /* --- Configure each channel as input --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        requested_lines[i] = gpioSetMode(channel_pins[i], PI_INPUT);
        if (requested_lines[i] != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM pin %d (ret=%d).\n",
                    channel_pins[i], requested_lines[i]);
            goto cleanup;
        }
    }

    /* --- Disable pull-up/pull-down bias so the sensor drives the line --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for BCM pin %d.\n",
                    channel_pins[i]);
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Timestamp,CH0,CH1,CH2,CH3,CH4,CH5,CH6,CH7\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            channel_states[i] = gpioRead(channel_pins[i]);
            if (channel_states[i] < 0) {
                fprintf(stderr, "Error: gpioRead failed for BCM pin %d (ret=%d).\n",
                        channel_pins[i], channel_states[i]);
                goto cleanup;
            }
        }

        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
               timestamp,
               channel_states[0], channel_states[1], channel_states[2],
               channel_states[3], channel_states[4], channel_states[5],
               channel_states[6], channel_states[7]);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release every line request individually --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (requested_lines[i] != 0) {
            gpioSetMode(channel_pins[i], PI_INPUT);   /* safe to call even if not set */
        }
    }

    if (channel_states != NULL) {
        free(channel_states);
    }
    if (requested_lines != NULL) {
        free(requested_lines);
    }
    gpioTerminate();
    return ret;
}

