/*
 * Raspberry Pi Zero W – Omron D7E-1 tilt sensor monitor
 *
 * Wiring:
 *   D7E-1 VCC  -> 3V3 (pin 1)
 *   D7E-1 GND  -> GND (pin 9)
 *   D7E-1 OUT  -> GPIO4 (BCM pin 7)
 *
 * The D7E-1 output is active-HIGH when the sensor is tilted.
 * The internal pull-up on GPIO4 keeps the line HIGH when the
 * sensor is disconnected or floating.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_PIN 4          /* BCM pin 7 */
#define POLL_DELAY_US 100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so the main loop exits cleanly.          */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;
    int last_state = -1;   /* force initial print */

    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        fprintf(stderr, "       Run as root (sudo) and ensure pigpiod is not running.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure tilt pin as input with internal pull-up ---- */
    if (gpioSetMode(TILT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", TILT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n", TILT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow the pull-up to settle */
    gpioDelay(10000); /* 10 ms */

    /* ---- Print startup banner ---- */
    printf("Raspberry Pi Zero W – Omron D7E-1 Tilt Sensor Monitor\n");
    printf("Pin : BCM %d (GPIO4, physical pin 7)\n", TILT_PIN);
    printf("State: HIGH = tilted, LOW  = not tilted\n");
    printf("Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(TILT_PIN);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed (code %d).\n",
                    TILT_PIN, level);
            break;
        }

        if (level != last_state) {
            printf("%s\n", level == 0 ? "Tilted" : "Not Tilted");
            fflush(stdout);
            last_state = level;
        }

        gpioDelay(POLL_DELAY_US); /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

