#define SI1145_CMD_PS_AUTO_PAUSE_123 0xFF

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY 0x17

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Invalid Part ID: 0x%02X (expected 0x%02X).\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (i2c_write_reg(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }
    if (i2c_write_reg(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0.\n");
        return -1;
    }
    if (i2c_write_reg(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE1.\n");
        return -1;
    }
    if (i2c_write_reg(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_AUTO) < 0) {
        fprintf(stderr, "Error: Failed to start ALS auto measurement.\n");
        return -1;
    }
    return 0;
}

int read_uv_index(int fd, uint16_t *uv_index) {
    uint8_t low, high;
    if (i2c_read_reg(fd, SI1145_REG_UV_INDEX0, &low) < 0) {
        return -1;
    }
    if (i2c_read_reg(fd, SI1145_REG_UV_INDEX1, &high) < 0) {
        return -1;
    }
    *uv_index = ((uint16_t)high << 8) | low;
    return 0;
}

int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t low, high;
    if (i2c_read_reg(fd, SI1145_REG_ALS_VIS_DATA0, &low) < 0) {
        return -1;
    }
    if (i2c_read_reg(fd, SI1145_REG_ALS_VIS_DATA1, &high) < 0) {
        return -1;
    }
    *als_visible = ((uint16_t)high << 8) | low;
    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        cleanup();
        return 1;
    }

    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV_Index,ALS_Visible\n");
    }

    while (running) {
        uint16_t uv_index, als_visible;
        if (read_uv_index(i2c_fd, &uv_index) < 0) {
            fprintf(stderr, "Error: Failed to read UV index.\n");
        } else if (read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error: Failed to read ALS visible.\n");
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - UV Index: %u, ALS Visible: %u\n", timestamp, uv_index, als_visible);
            fprintf(log_file, "%s,%u,%u\n", timestamp, uv_index, als_visible);
            fflush(log_file);
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

