/* Sensirion 8-bit CRC: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int init_sensor(int fd)
{
    if (i2c_write_cmd(fd, START_CMD) < 0)
        return -1;
    usleep(MEASURE_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, float *out)
{
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;
    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t buf[3];
    if (i2c_read_data(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out = (float)raw / 1000.0f;
    return 0;
}

static void log_data(FILE *fp, float f1, float f2, float avg, bool alarm)
{
    time_t t = time(NULL);
