    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Sensor1: %.3f, Sensor2: %.3f, Avg: %.3f, Alarm: %s\n",
