    if (g_i2c_fd2 < 0) {
        perror("open " I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("ioctl I2C_SLAVE 0x51");
        cleanup();
        return EXIT_FAILURE;
    }
    if (init_sensor(g_i2c_fd2) < 0) {
        fprintf(stderr, "Sensor 2 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

