        float f1 = 0.0f, f2 = 0.0f;
        bool ok1 = (read_flow_rate(g_i2c_fd1, &f1) == 0);
        bool ok2 = (read_flow_rate(g_i2c_fd2, &f2) == 0);

        float avg = 0.0f;
