#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 50000

typedef struct {
    time_t timestamp;
    int detected;
} SensorData;

static SensorData buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO%d\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(void) {
    return gpioRead(SENSOR_PIN);
}

static void add_to_buffer(time_t timestamp, int detected) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].detected = detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void dump_buffer(void) {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_buf[32];
        struct tm *tm_info = localtime(&buffer[idx].timestamp);
        if (tm_info != NULL) {
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Obstacle %s\n", time_buf, buffer[idx].detected ? "DETECTED" : "clear");
        } else {
            printf("[unknown] Obstacle %s\n", buffer[idx].detected ? "DETECTED" : "clear");
        }
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (program_running) {
        int sensor_value = read_sensor();
        time_t current_time = time(NULL);

        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
            add_to_buffer(current_time, 1);
        } else {
            add_to_buffer(current_time, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    dump_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

