/*
 * Omron D7S vibration sensor reader for Raspberry Pi 5 (Bookworm, 64-bit).
 *
 * Wiring:
 *   D7S SDA  -> GPIO2  (BCM 2,  I2C bus 1 SDA)
 *   D7S SCL  -> GPIO3  (BCM 3,  I2C bus 1 SCL)
 *   D7S VCC  -> 3.3 V
 *   D7S GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 *
 * Run:
 *   ./fan_health
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILE       "fan_health.csv"
#define POLL_INTERVAL  500000   /* microseconds (500 ms) */
#define ACTIVATION_TIMEOUT_US 1000000  /* 1 second */

/* D7S register addresses (16-bit, big-endian on the bus) */
#define D7S_REG_MODE   0x0000
#define D7S_REG_X_L    0x0001
#define D7S_REG_X_H    0x0002
#define D7S_REG_Y_L    0x0003
#define D7S_REG_Y_H    0x0004
#define D7S_REG_Z_L    0x0005
#define D7S_REG_Z_H    0x0006

/*
 * Mode bits (16-bit word, sent MSB first):
 *   bit 0   = 0  (reserved)
 *   bit 1   = 0  (reserved)
 *   bit 2   = 0  (reserved)
 *   bit 3   = 0  (reserved)
 *   bit 4   = 0  (reserved)
 *   bit 5   = 0  (reserved)
 *   bit 6   = 0  (reserved)
 *   bit 7   = 0  (reserved)
 *   bit 8   = 0  (reserved)
 *   bit 9   = 0  (reserved)
 *   bit 10  = 0  (reserved)
 *   bit 11  = 0  (reserved)
 *   bit 12  = 0  (reserved)
 *   bit 13  = 0  (reserved)
 *   bit 14  = 0  (reserved)
 *   bit 15  = 0  (reserved)
 *
 * The D7S is configured via the MODE register.  A value of 0x0000
 * selects the default operating mode (continuous measurement).
 */
#define D7S_MODE_DEFAULT 0x0000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    uint8_t data[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor activation                                                   */
/* ------------------------------------------------------------------ */
static int sensor_activate(int fd)
{
    if (i2c_write_reg16(fd, D7S_REG_MODE, D7S_MODE_DEFAULT) != 0)
        return -1;

    printf("D7S: switching to default mode (0x%04X)...\n",
           D7S_MODE_DEFAULT);

    /* Allow the sensor to settle into the new mode. */
    usleep(100000);  /* 100 ms */

    /*
     * Poll the X-axis low-byte register (D7S_REG_X_L) for up to 1 s.
     * If the sensor is not ready (e.g. wiring fault or device absent),
     * the read will fail or return 0xFFFF (bus error / NACK).
     */
    uint16_t x_l = 0;
    int ok = 0;

    for (int i = 0; i < 20; ++i) {
        if (i2c_read_reg16(fd, D7S_REG_X_L, &x_l) != 0)
            return -1;
        if (x_l != 0xFFFF) {
            ok = 1;
            break;
        }
        usleep(50000);  /* 50 ms */
    }

    if (!ok) {
        fprintf(stderr, "D7S: did not become active within 1 s (last X_L=0x%04X)\n",
                x_l);
        return -1;
    }

    printf("D7S: active (X_L=0x%04X).\n", x_l);
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int csv_write_header_if_new(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "CSV header write failed: %s\n", strerror(errno));
            return -1;
        }
        fflush(fp);
    }
    return 0;
}

static int csv_write_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "CSV write failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    g_csv = fopen(CSV_FILE, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (csv_write_header_if_new(g_csv) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Activate sensor */
    if (sensor_activate(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor activation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("D7S vibration sensor monitoring started.\n");
    printf("Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           CSV_FILE, POLL_INTERVAL / 1000);

    /* Main polling loop */
    while (g_running) {
        uint16_t x_l, x_h, y_l, y_h, z_l, z_h;

        if (i2c_read_reg16(g_i2c_fd, D7S_REG_X_L, &x_l) != 0 ||
            i2c_read_reg16(g_i2c_fd, D7S_REG_X_H, &x_h) != 0 ||
            i2c_read_reg16(g_i2c_fd, D7S_REG_Y_L, &y_l) != 0 ||
            i2c_read_reg16(g_i2c_fd, D7S_REG_Y_H, &y_h) != 0 ||
            i2c_read_reg16(g_i2c_fd, D7S_REG_Z_L, &z_l) != 0 ||
            i2c_read_reg16(g_i2c_fd, D7S_REG_Z_H, &z_h) != 0) {
            fprintf(stderr, "I2C read error — will retry next cycle.\n");
            usleep(POLL_INTERVAL);
            continue;
        }

        int16_t x = (int16_t)((x_h << 8) | x_l);
        int16_t y = (int16_t)((y_h << 8) | y_l);
        int16_t z = (int16_t)((z_h << 8) | z_l);

        if (csv_write_sample(g_csv, x, y, z) != 0) {
            fprintf(stderr, "CSV write error — will retry next cycle.\n");
        }

        usleep(POLL_INTERVAL);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

