/*
 * Raspberry Pi 4 Model B — Dual KY-032 IR Obstacle Avoidance Sensor
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO23 (BCM)
 *   Sensor 2 OUT -> GPIO24 (BCM)
 *   LED anode    -> GPIO25 (BCM) via 220-330 ohm resistor to GND
 *
 * The KY-032 OUT pin is active-LOW: 0 = obstacle detected, 1 = clear.
 * The LED is driven HIGH when either sensor detects an obstacle.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle obstacle.c -lpigpio -lrt
 * Run:    sudo ./obstacle
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN     25

#define POLL_DELAY_US 100000   /* 100 ms */
#define DEBOUNCE_US   50000    /* 50 ms debounce */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (safe_set_mode(SENSOR1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR2_PIN, PI_INPUT) != 0 ||
        safe_set_mode(LED_PIN,    PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup */
    if (safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle detection started.\n");
    printf("  Sensor 1: GPIO%u (active-LOW)\n", SENSOR1_PIN);
    printf("  Sensor 2: GPIO%u (active-LOW)\n", SENSOR2_PIN);
    printf("  LED:      GPIO%u\n", LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    bool led_on = false;

    while (g_running) {
        int s1 = safe_read(SENSOR1_PIN);
        int s2 = safe_read(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — turn LED off for safety */
            if (led_on) {
                safe_write(LED_PIN, 0);
                led_on = false;
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 OUT is active-LOW: 0 = obstacle detected */
        bool obstacle = (s1 == 0 || s2 == 0);

        if (obstacle && !led_on) {
            if (safe_write(LED_PIN, 1) == 0) {
                led_on = true;
                printf("Obstacle detected — LED ON\n");
            }
        } else if (!obstacle && led_on) {
            if (safe_write(LED_PIN, 0) == 0) {
                led_on = false;
                printf("Clear — LED OFF\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    safe_write(LED_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

