#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return level;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (running) {
        int level = read_sensor();
        if (level < 0) {
            log_event("ERROR: GPIO read failure, scheduling re-initialization");
            sleep(REINIT_DELAY_SEC);
            if (initialize_gpio() != 0) {
                log_event("ERROR: Re-initialization failed, exiting");
                break;
            }
            log_event("GPIO re-initialized");
            continue;
        }

        if (level == 1) {
            printf("ALERT: Water detected!\n");
            fflush(stdout);
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    log_event("System stopped");
    return EXIT_SUCCESS;
}

