#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE    "rpm_log.txt"
#define SAMPLE_PERIOD_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets a flag               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in a pigpio thread                      */
/* ------------------------------------------------------------------ */
static void pulse_alert_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {                 /* rising edge */
        g_pulse_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted in one SAMPLE_PERIOD_US window     */
/* ------------------------------------------------------------------ */
static double calculate_rpm(void)
{
    int pulses = (int)g_pulse_count;
    g_pulse_count = 0;

    /* pulses per second * 60 = RPM */
    return (double)pulses * 60.0;
}

/* ------------------------------------------------------------------ */
/* Append one timestamped RPM line to the log file and stdout          */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_fp != NULL) {
        if (fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
            fprintf(stderr, "fprintf to log failed\n");
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush failed\n");
        }
    }

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* ---- pigpio init ------------------------------------------------ */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* ---- open log file --------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin -------------------------------------- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback ----------------------------------- */
    if (gpioSetAlertFunc(SENSOR_PIN, pulse_alert_cb) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for pin %d\n", SENSOR_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    fflush(stdout);

    /* ---- main sampling loop ---------------------------------------- */
    while (g_running) {
        gpioDelay(SAMPLE_PERIOD_US);   /* 1 second */
        if (!g_running) break;

        double rpm = calculate_rpm();
        log_rpm(rpm);
    }

    /* ---- graceful cleanup ------------------------------------------ */
    gpioSetAlertFunc(SENSOR_PIN, NULL);   /* disable callback */
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_OFF);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

