 *   00 -> 01 -> 11 -> 10 -> 00  (clockwise)
 *   00 -> 10 -> 11 -> 01 -> 00 (counter-clockwise)
 * Direction is inferred by comparing the current state to the previous state.
 */
typedef struct {
    int sensor_a_state;
    int sensor_b_state;
    int direction;  /* +1 = clockwise, -1 = counter-clockwise, 0 = unknown */
} QuadratureState;

static QuadratureState current_state = {0, 0, 0};
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/*
 * ISR callback — invoked by the driver library's edge-triggered alert API.
 * We only update the shared state; the main thread consumes it.
 */
static void quadrature_isr(int sensor_pin, int state)
{
    (void)sensor_pin;

    pthread_mutex_lock(&state_mutex);

    if (sensor_pin == SENSOR_A_PIN) {
        current_state.sensor_a_state = state;
    } else if (sensor_pin == SENSOR_B_PIN) {
        current_state.sensor_b_state = state;
    }

