     * When both sensors change simultaneously (state 00 -> 11 or 11 -> 00),
     * the direction is unknown.
     */
    if (current_state.sensor_a_state != current_state.sensor_b_state) {
        int prev_a = current_state.sensor_a_state;
        int prev_b = current_state.sensor_b_state;

        /*
         * Build a 2-bit state from the current rising/falling edges.
         * 0 = low, 1 = high.
         */
        int current_state_code = (current_state.sensor_a_state << 1) |
                                 current_state.sensor_b_state;
        int prev_state_code = (prev_a << 1) | prev_b;

        /*
         * Clockwise: 00 -> 01 -> 11 -> 10 -> 00
         * Counter-clockwise: 00 -> 10 -> 11 -> 01 -> 00
         */
        if (current_state_code == 01 && prev_state_code == 00) {
            current_state.direction = 1;
        } else if (current_state_code == 11 && prev_state_code == 01) {
            current_state.direction = 1;
        } else if (current_state_code == 10 && prev_state_code == 11) {
            current_state.direction = 1;
        } else if (current_state_code == 00 && prev_state_code == 10) {
            current_state.direction = 1;
        } else if (current_state_code == 10 && prev_state_code == 00) {
            current_state.direction = -1;
        } else if (current_state_code == 01 && prev_state_code == 11) {
            current_state.direction = -1;
        } else if (current_state_code == 00 && prev_state_code == 01) {
            current_state.direction = -1;
        } else if (current_state_code == 11 && prev_state_code == 00) {
            current_state.direction = -1;
        } else {
            current_state.direction = 0;
        }
    }

    pthread_cond_signal(&state_cond);
    pthread_mutex_unlock(&state_mutex);
