#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;
static int gpio_chip_fd = -1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int gpio_request_line(int fd, unsigned int offset,
                             enum gpio_line_direction direction,
                             enum gpio_line_bias bias) {
    struct gpio_request req;
    memset(&req, 0, sizeof(req));
    req.line_offset = offset;
    req.request_type = (direction == GPIO_LINE_DIRECTION_INPUT)
        ? GPIO_REQUEST_DIRECTION_INPUT
        : GPIO_REQUEST_DIRECTION_OUTPUT;
    req.flags = 0;

    if (direction == GPIO_LINE_DIRECTION_OUTPUT) {
        req.flags |= GPIO_REQUEST_FLAG_BIAS_PULL_UP;
    }

    if (ioctl(fd, GPIO_GET_LINE_BIAS, &bias) < 0) {
        syslog(LOG_ERR, "Failed to get line bias: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_SET_LINE_BIAS, &bias) < 0) {
        syslog(LOG_ERR, "Failed to set line bias: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_REQUEST_LINE, &req) < 0) {
        syslog(LOG_ERR, "Failed to request line %u: %s", offset, strerror(errno));
        return -1;
    }

    return 0;
}

static int gpio_set_value(int fd, unsigned int offset, int value) {
    struct gpio_set_value val;
    val.offset = offset;
    val.value = value;

    if (ioctl(fd, GPIO_SET_VALUE, &val) < 0) {
        syslog(LOG_ERR, "Failed to set value %d on line %u: %s", value, offset, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_get_value(int fd, unsigned int offset) {
    struct gpio_get_value val;
    val.offset = offset;

    if (ioctl(fd, GPIO_GET_VALUE, &val) < 0) {
        syslog(LOG_ERR, "Failed to get value on line %u: %s", offset, strerror(errno));
        return -1;
    }
    return val.value;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "[%s] %s", timestamp, message);
}

int main(void) {
    openlog("touch_sensor_led", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    gpio_chip_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_chip_fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_request_line(gpio_chip_fd, TOUCH_SENSOR_PIN,
                          GPIO_LINE_DIRECTION_INPUT,
                          GPIO_LINE_BIAS_PULL_DOWN) < 0) {
        close(gpio_chip_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_request_line(gpio_chip_fd, LED_PIN,
                          GPIO_LINE_DIRECTION_OUTPUT,
                          GPIO_LINE_BIAS_PULL_UP) < 0) {
        close(gpio_chip_fd);
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Touch sensor and LED initialized.");

    while (program_running) {
        int sensor_value = gpio_get_value(gpio_chip_fd, TOUCH_SENSOR_PIN);
        if (sensor_value < 0) {
            log_event("Failed to read touch sensor.");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (sensor_value == 1) {
            if (gpio_set_value(gpio_chip_fd, LED_PIN, 1) < 0) {
                log_event("Failed to turn on LED.");
            } else {
                log_event("Touch detected, LED turned on.");
            }
        } else {
            if (gpio_set_value(gpio_chip_fd, LED_PIN, 0) < 0) {
                log_event("Failed to turn off LED.");
            } else {
                log_event("Touch released, LED turned off.");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Shutting down, turning off LED.");
    gpio_set_value(gpio_chip_fd, LED_PIN, 0);
    close(gpio_chip_fd);
    closelog();
    return EXIT_SUCCESS;
}

