/*
 * TTP223B capacitive touch sensor -> LED toggle on Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TTP223B OUT  -> GPIO17 (physical pin 11)
 *   TTP223B VCC  -> 3.3 V
 *   TTP223B GND  -> GND
 *   LED anode    -> GPIO18 (physical pin 12) through 330 Ω resistor
 *   LED cathode  -> GND
 *
 * Behaviour:
 *   On each rising edge of the touch sensor OUT line the LED toggles.
 *   A 50 ms software debounce is applied after each detected edge.
 *   SIGINT / SIGTERM trigger a clean shutdown of the pigpio line event
 *   interface and the program exits.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o touch_led touch_led.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for the line event interface).
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 17
#define LED_PIN          18
#define DEBOUNCE_US      50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin as output and ensure it starts LOW --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor pin as input --- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register a rising-edge alert on the touch sensor line --- */
    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch sensor : GPIO%d (rising edge)\n", TOUCH_SENSOR_PIN);
    printf("  LED          : GPIO%d\n", LED_PIN);
    printf("  Debounce     : %d ms\n", DEBOUNCE_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop: wait for rising edges and toggle the LED --- */
    while (g_running) {
        /*
         * gpioWaitForEdge returns the level that triggered the edge.
         * A return value of 1 indicates a rising edge.
         */
        int level = gpioWaitForEdge(TOUCH_SENSOR_PIN, -1);
        if (level < 0) {
            fprintf(stderr, "Error: gpioWaitForEdge failed on GPIO%d.\n",
                    TOUCH_SENSOR_PIN);
            break;
        }

        if (level == 1) {
            /* Debounce: wait 50 ms, then re-read to confirm the line is still HIGH */
            gpioDelay(DEBOUNCE_US);

            int confirm = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm == 1) {
                int current = gpioRead(LED_PIN);
                if (current < 0) {
                    fprintf(stderr, "Error: failed to read GPIO%d.\n", LED_PIN);
                    break;
                }

                if (gpioWrite(LED_PIN, !current) != 0) {
                    fprintf(stderr, "Error: failed to toggle GPIO%d.\n", LED_PIN);
                    break;
                }

                printf("Touch detected -> LED %s\n",
                       current ? "OFF" : "ON");
            }
        }
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_PIN, 0);   /* Ensure LED is off */
    gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, NULL, NULL); /* Unregister alert */
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

