code:
/*
 * Raspberry Pi Zero W — Dual TTP223B capacitive touch sensor logger
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4  (active-high digital output)
 *   Sensor 2 OUT -> GPIO17
 *   LED 1       -> GPIO27
 *   LED 2       -> GPIO22
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c -lpigpio -lrt
 * Run:    sudo ./touch_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22

/* ---- Log buffer ---- */
#define LOG_BUFFER_SIZE 100

typedef struct {
    int    sensor_pin;
    time_t timestamp;
    int    state;          /* 0 = released, 1 = touched */
} log_entry_t;

static log_entry_t log_buffer[LOG_BUFFER_SIZE];
static int          log_head = 0;   /* next write slot */
static int          log_tail = 0;   /* oldest entry */
static int          log_count = 0; /* entries currently stored */
static int          overflow_count = 0;

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void cleanup(void);
static void print_log_summary(void);
static void log_event(int sensor_pin, int state);

/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO directions ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_1_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR_2_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_1_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_2_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Ensure LEDs are off at start ---- */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_1_PIN, 0) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_2_PIN, 0) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Sensor 1: GPIO%d  LED: GPIO%d  Sensor 2: GPIO%d  LED: GPIO%d\n",
           SENSOR_1_PIN, LED_1_PIN, SENSOR_2_PIN, LED_2_PIN);
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            gpioDelay(50000); /* 50 ms */
            continue;
        }

        /* ---- Sensor 1 ---- */
        if (s1 == 1) {
            if (gpioWrite(LED_1_PIN, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED_1_PIN, 1) failed.\n");
            }
            log_event(SENSOR_1_PIN, 1);
        } else {
            if (gpioWrite(LED_1_PIN, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED_1_PIN, 0) failed.\n");
            }
            log_event(SENSOR_1_PIN, 0);
        }

        /* ---- Sensor 2 ---- */
        if (s2 == 1) {
            if (gpioWrite(LED_2_PIN, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED_2_PIN, 1) failed.\n");
            }
            log_event(SENSOR_2_PIN, 1);
        } else {
            if (gpioWrite(LED_2_PIN, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED_2_PIN, 0) failed.\n");
            }
            log_event(SENSOR_2_PIN, 0);
        }

        gpioDelay(50000); /* 50 ms debounce / polling interval */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    print_log_summary();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Turn off LEDs */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();
}

static void print_log_summary(void)
{
    printf("\n--- Log Summary ---\n");
    printf("  Entries stored: %d/%d\n", log_count, LOG_BUFFER_SIZE);
    printf("  Overflows:     %d\n", overflow_count);
    printf("  Log buffer:\n");

    int start = (log_count == LOG_BUFFER_SIZE) ? log_tail : log_head;
    for (int i = 0; i < log_count; i++) {
        int idx = (start + i) % LOG_BUFFER_SIZE;
        char ts_str[32];
        struct tm tm_info;
        localtime_r(&log_buffer[idx].timestamp, &tm_info);
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("    [%s] Sensor %d  State: %d\n",
               ts_str, log_buffer[idx].sensor_pin, log_buffer[idx].state);
    }
}

static void log_event(int sensor_pin, int state)
{
    log_buffer[log_head].sensor_pin = sensor_pin;
    log_buffer[log_head].timestamp  = time(NULL);
    log_buffer[log_head].state      = state;

    log_head = (log_head + 1) % LOG_BUFFER_SIZE;
    if (log_count < LOG_BUFFER_SIZE) {
        log_count++;
    } else {
        log_tail = (log_tail + 1) % LOG_BUFFER_SIZE;
        overflow_count++;
    }
}

