#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(int s1, int s2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d\n", timestamp, s1, s2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void calculate_rpm(int s1_prev, int s2_prev, int s1_curr, int s2_curr,
                          struct timespec *last_change) {
    static struct timespec last_state_change = {0, 0};
    struct timespec now;
    double elapsed_sec;
    double rpm;

    clock_gettime(CLOCK_MONOTONIC, &now);

    if (s1_curr != s1_prev || s2_curr != s2_prev) {
        if (last_state_change.tv_sec == 0 && last_state_change.tv_nsec == 0) {
            last_state_change = now;
        } else {
            elapsed_sec = (now.tv_sec - last_state_change.tv_sec) +
                          (now.tv_nsec - last_state_change.tv_nsec) / 1e9;

            if (elapsed_sec > 0.0) {
                rpm = 60.0 / elapsed_sec;
                printf("RPM: %.2f\n", rpm);
            }
            last_state_change = now;
        }
    }

    *last_change = now;
}

int main(void) {
    int s1_prev = -1, s2_prev = -1;
    int s1_curr, s2_curr;
    struct timespec last_change = {0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "# timestamp,sensor1_state,sensor2_state\n") < 0) {
        fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file header: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (running) {
        s1_curr = gpioRead(SENSOR1_PIN);
        s2_curr = gpioRead(SENSOR2_PIN);

        if (s1_curr < 0 || s2_curr < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        if (s1_curr != s1_prev || s2_curr != s2_prev) {
            if (log_data(s1_curr, s2_curr) != 0) {
                fprintf(stderr, "Error logging data\n");
                break;
            }
            calculate_rpm(s1_prev, s2_prev, s1_curr, s2_curr, &last_change);
            s1_prev = s1_curr;
            s2_prev = s2_curr;
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nCleaning up...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

