#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define READ_INTERVAL_SEC 1

/* Si1182 register addresses (from datasheet) */
#define REG_PART_ID 0x00
#define REG_HW_KEY  0x07
#define REG_MEAS_RATE 0x08
#define REG_HR_DATA  0x09
#define REG_SPO2_DATA 0x0A
#define REG_COMMAND  0x18

#define CMD_RESET 0x01
#define CMD_START 0x02

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_sensor(void) {
    uint8_t part_id;
    if (read_reg(REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    if (write_reg(REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(REG_MEAS_RATE, 0x0A) < 0) return -1;
    if (write_reg(REG_COMMAND, CMD_START) < 0) return -1;

    return 0;
}

static int read_sensor_data(int *heart_rate, int *spo2) {
    uint8_t hr_data, spo2_data;

    if (read_reg(REG_HR_DATA, &hr_data) < 0) return -1;
    if (read_reg(REG_SPO2_DATA, &spo2_data) < 0) return -1;

    *heart_rate = (int)hr_data;
    *spo2 = (int)spo2_data;
    return 0;
}

static void log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
