/*
 * bridge_monitor.c — Raspberry Pi Zero W
 *
 * Monitors two Omron D7E-3 tilt sensors on GPIO17 and GPIO18 (BCM)
 * with internal pull-down resistors.  Drives an active-high alarm on
 * GPIO27 when either sensor stays HIGH for more than 2 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bridge_monitor bridge_monitor.c -lpigpio -lrt
 * Run:    sudo ./bridge_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SENSOR_1_PIN 17          /* BCM 17 — first tilt sensor  */
#define SENSOR_2_PIN 18          /* BCM 18 — second tilt sensor */
#define ALARM_PIN    27          /* BCM 27 — alarm output      */

#define TILT_THRESHOLD_SEC  2     /* seconds a sensor must stay HIGH */
#define POLL_INTERVAL_US   100000 /* 100 ms between polls          */
#define LOG_FILE_NAME      "bridge_integrity.log"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static void  cleanup(void);
static int   init_gpio(void);
static int   read_sensor(int pin);
static void  log_event(const char *event_type, int sensor_id);
static void  activate_alarm(void);
static void  deactivate_alarm(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure alarm is off before releasing resources */
    deactivate_alarm();

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- GPIO init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_PIN);
        return -1;
    }

    /* Enable internal pull-down resistors so sensors read LOW when idle */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", SENSOR_1_PIN);
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", SENSOR_2_PIN);
    }

    /* Start with alarm OFF */
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise alarm pin LOW.\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Sensor read ------------------------------- */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d).\n", pin, level);
    }
    return level;
}

/* ----------------------------- Log event ---------------------------------- */
static void log_event(const char *event_type, int sensor_id)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: log file not open; cannot log event.\n");
    }
}

/* ----------------------------- Alarm helpers ------------------------------ */
static void activate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate alarm on GPIO%d.\n", ALARM_PIN);
    }
}

static void deactivate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate alarm on GPIO%d.\n", ALARM_PIN);
    }
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    int sensor1_state = 0;
    int sensor2_state = 0;
    time_t sensor1_high_since = 0;
    time_t sensor2_high_since = 0;
    int    alarm_active = 0;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise GPIO subsystem */
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started.\n");
    printf("  Sensor 1: GPIO%d | Sensor 2: GPIO%d | Alarm: GPIO%d\n",
           SENSOR_1_PIN, SENSOR_2_PIN, ALARM_PIN);
    printf("  Threshold: %d s | Poll: %d ms\n", TILT_THRESHOLD_SEC, POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* Main monitoring loop */
    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — back off briefly and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Sensor 1 */
        if (s1 == 1) {
            if (sensor1_state == 0) {
                sensor1_high_since = time(NULL);
                log_event("tilt-start", 1);
            }
            sensor1_state = 1;
        } else {
            sensor1_state = 0;
        }

        /* Sensor 2 */
        if (s2 == 1) {
            if (sensor2_state == 0) {
                sensor2_high_since = time(NULL);
                log_event("tilt-start", 2);
            }
            sensor2_state = 1;
        } else {
            sensor2_state = 0;
        }

        /* Check alarm conditions */
        if (sensor1_state == 1 &&
            (time(NULL) - sensor1_high_since) >= TILT_THRESHOLD_SEC) {
            if (!alarm_active) {
                activate_alarm();
                alarm_active = 1;
                log_event("threshold-exceeded", 1);
            }
        } else if (sensor2_state == 1 &&
                   (time(NULL) - sensor2_high_since) >= TILT_THRESHOLD_SEC) {
            if (!alarm_active) {
                activate_alarm();
                alarm_active = 1;
                log_event("threshold-exceeded", 2);
            }
        } else if (sensor1_state == 0 && sensor2_state == 0) {
            if (alarm_active) {
                deactivate_alarm();
                alarm_active = 0;
                log_event("tilt-end", 0);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

