/*
 * Raspberry Pi 3 Model B+ — Omron D7S-A0011 seismic sensor monitor
 *
 * Wiring:
 *   SDA  -> GPIO2  (I2C bus 1 SDA)
 *   SCL  -> GPIO3  (I2C bus 1 SCL)
 *   LED  -> GPIO17 (BCM) via ~330 Ω series resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lthe_driver -lm -lrt
 *
 * The D7S-A0011 I2C driver (the_driver) is a placeholder; replace with
 * the actual vendor/product-specific library (e.g. omron_d7s).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <the_driver.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x20          /* D7S-A0011 default I2C address */
#define GPIO_LED            17            /* BCM pin for alert LED */
#define THRESHOLD           500.0f        /* Euclidean vibration magnitude */
#define POLL_INTERVAL_US    100000        /* 100 ms */
#define LED_ON_TIME_US      1000000       /* 1 s   */
#define MAX_RETRIES         3
#define LOG_FILE            "seismic_events.log"

/* D7S-A0011 register addresses (placeholder — replace with real values) */
#define REG_CTRL1           0x00
#define REG_VIB_X           0x04
#define REG_VIB_Y           0x06
#define REG_VIB_Z           0x08

/* CTRL1 bit masks */
#define CTRL1_POWER_DOWN    0x01
#define CTRL1_AUTOCONV      0x02

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log    = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int v = i2c_read_reg16(fd, reg);
        if (v >= 0) {
            *out = (uint16_t)v;
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int r = i2c_write_reg16(fd, reg, val);
        if (r == 0)
            return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

/* --------------------------- Sensor init --------------------------------- */
static int init_sensor(int fd)
{
    /* Verify sensor presence by reading CTRL1 */
    uint16_t ctrl1 = 0;
    if (i2c_read_reg(fd, REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "Sensor not responding on I2C addr 0x%02X\n", I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit, enable auto-conversion */
    ctrl1 &= ~CTRL1_POWER_DOWN;
    ctrl1 |=  CTRL1_AUTOCONV;
    if (i2c_write_reg(fd, REG_CTRL1, ctrl1) != 0) {
        fprintf(stderr, "Failed to configure CTRL1\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Vibration magnitude -------------------------- */
static float calc_magnitude(int16_t x, int16_t y, int16_t z)
{
    float x_f = (float)x;
    float y_f = (float)y;
    float z_f = (float)z;
    return sqrtf(x_f * x_f + y_f * y_f + z_f * z_f);
}

/* --------------------------- Logging -------------------------------------- */
static void log_event(float magnitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log, "%s - Earthquake detected! Magnitude: %.2f\n", ts, magnitude);
    fflush(g_log);
}

/* --------------------------- LED control ---------------------------------- */
static void led_on(void)
{
    if (gpio_write(GPIO_LED, 1) != 0)
        fprintf(stderr, "Warning: failed to turn LED on: %s\n", strerror(errno));
}

static void led_off(void)
{
    if (gpio_write(GPIO_LED, 0) != 0)
        fprintf(stderr, "Warning: failed to turn LED off: %s\n", strerror(errno));
}

