static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpio_write(GPIO_LED, 0);
    gpio_close();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

