    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_open() != 0) {
        fprintf(stderr, "gpio_open() failed: %s\n", strerror(errno));
        fclose(g_log);
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpio_set_mode(%d) failed: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_write(GPIO_LED, 0);

    /* Open I2C bus */
    g_i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2c_open(bus=%d, addr=0x%02X) failed: %s\n",
