/*
 * Raspberry Pi 5 — Four-sensor obstacle detector with LED indicator.
 *
 * Sensors : Keywish KY-032 IR obstacle avoidance modules
 *           OUT -> GPIO4, GPIO17, GPIO27, GPIO22 (BCM)
 *           Active-low: 0 = object detected, 1 = clear
 * LED     : GPIO18 (BCM), active-high
 *
 * Build   : gcc -O2 -Wall -Wextra -o obstacle obstacle.c -lpigpio -lrt
 * Run     : sudo ./obstacle
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define NUM_SENSORS 4
#define POLL_US    50000   /* 50 ms */

static const int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};
static const int led_pin            = 18;

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                    sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Enable internal pull-up so the sensor line reads 1 when idle. */
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n",
                    sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetMode(led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", led_pin);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(led_pin, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n",
                led_pin);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    /* Best-effort: turn LED off and release pigpio. */
    gpioWrite(led_pin, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        bool any_detected = false;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = gpioRead(sensor_pins[i]);
            if (v < 0) {
                fprintf(stderr, "Warning: read failed on GPIO%d.\n",
                        sensor_pins[i]);
                continue;
            }
            /* Active-low: 0 => object detected. */
            if (v == 0) {
                any_detected = true;
                break;
            }
        }

        if (gpioWrite(led_pin, any_detected ? 1 : 0) != 0) {
            fprintf(stderr, "Warning: failed to write LED on GPIO%d.\n",
                    led_pin);
        }

        gpioDelay(POLL_US);   /* 50 ms non-blocking delay */
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

