/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   VCC  -> 3.3 V (Pin 1)
 *   GND  -> GND   (Pin 9)
 *   OUT0 -> GPIO5  (Pin 29)
 *   OUT1 -> GPIO6  (Pin 31)
 *   OUT2 -> GPIO13 (Pin 33)
 *   OUT3 -> GPIO19 (Pin 35)
 *   OUT4 -> GPIO26 (Pin 37)
 *   OUT5 -> GPIO12 (Pin 32)
 *   OUT6 -> GPIO16 (Pin 36)
 *   OUT7 -> GPIO20 (Pin 38)
 *
 * Build: gcc -Wall -Wextra -O2 -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_states, 0, sizeof(prev_states));

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s (errno: %d)\n",
                strerror(errno), errno);
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s (errno: %d)\n",
                strerror(errno), errno);
        return EXIT_FAILURE;
    }

    /* Acquire all eight output lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s (errno: %d)\n",
                    channel_pins[i], strerror(errno), errno);
            goto cleanup;
        }
    }

    /* Request each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s (errno: %d)\n",
                    channel_pins[i], strerror(errno), errno);
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_states[NUM_CHANNELS];
        int read_error = 0;

        /* Read all eight channels in a single loop */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s (errno: %d)\n",
                        channel_pins[i], strerror(errno), errno);
                read_error = 1;
                break;
            }
            current_states[i] = val;
        }

        if (read_error) {
            goto cleanup;
        }

        /* Log only on state change */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (current_states[i] != prev_states[i]) {
                print_timestamp();
                if (current_states[i] == 1) {
                    printf("Channel %d (GPIO %u): TOUCH\n", i, channel_pins[i]);
                } else {
                    printf("Channel %d (GPIO %u): RELEASED\n", i, channel_pins[i]);
                }
                fflush(stdout);
                prev_states[i] = current_states[i];
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

