#define GROW_LIGHT_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int veml7700_write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int veml7700_read_register(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int veml7700_init(int handle) {
    uint8_t config = 0x00;
    if (veml7700_write_register(handle, VEML7700_REG_CONFIG, config) != 0) {
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int veml7700_read_lux(int handle, uint16_t *lux) {
    uint8_t als_data_low, als_data_high;
    if (veml7700_read_register(handle, VEML7700_REG_ALS_DATA, &als_data_low) != 0) {
        return -1;
    }
    if (veml7700_read_register(handle, VEML7700_REG_ALS_DATA + 1, &als_data_high) != 0) {
        return -1;
    }
    *lux = ((uint16_t)als_data_high << 8) | als_data_low;
    return 0;
}

static int map_lux_to_brightness(uint16_t lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

static int set_grow_light_brightness(int brightness) {
    if (gpioPWM(GROW_LIGHT_GPIO, brightness) != 0) {
        return -1;
    }
    return 0;
}

static void log_data(uint16_t lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %u, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, VEML7700_ADDR);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GROW_LIGHT_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(GROW_LIGHT_GPIO, PWM_RANGE);

    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (program_running) {
        uint16_t lux = 0;
        int error_code = 0;

        if (veml7700_read_lux(i2c_handle, &lux) != 0) {
            error_code = -1;
            fprintf(stderr, "Failed to read lux value\n");
        }

        int brightness = map_lux_to_brightness(lux);

        if (set_grow_light_brightness(brightness) != 0) {
            fprintf(stderr, "Failed to set grow light brightness\n");
        }

        log_data(lux, brightness, error_code);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    set_grow_light_brightness(0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

