/*
 * TTP226 8-Channel Capacitive Touch Sensor – Raspberry Pi Zero W
 *
 * Wiring:
 *   TTP226 OUT1..OUT8 -> BCM GPIO2..GPIO9  (inputs, pull-down)
 *   TTP226 VCC       -> 3.3 V
 *   TTP226 GND       -> GND
 *   Alert LED anode  -> BCM GPIO17 (with ~330 Ω series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_alert touch_alert.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN      17
#define POLL_DELAY_US 50000   /* 50 ms */
#define DEBOUNCE_US   200000  /* 200 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_touch_event(int channel)
{
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        perror("fopen(touch_log.txt)");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf()");
    }

    if (fclose(fp) != 0) {
        perror("fclose(touch_log.txt)");
    }
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void control_led(int any_touched)
{
    if (gpioWrite(LED_PIN, any_touched ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(LED_PIN) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure channel pins as inputs with pull-down ------------ */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n",
                    channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                    channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Configure LED pin as output and ensure it is off ----------- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("  Channels : BCM GPIO%d..GPIO%d (inputs, pull-down)\n",
           channel_pins[0], channel_pins[NUM_CHANNELS - 1]);
    printf("  LED      : BCM GPIO%d (output)\n", LED_PIN);
    printf("  Log file : touch_log.txt\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop ------------------------------------------ */
    int last_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        last_state[i] = 0;

    while (g_running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(channel_pins[i]);
            if (level < 0) {
                fprintf(stderr, "gpioRead(%d) failed\n", channel_pins[i]);
                continue;
            }

            if (level == 1) {
                any_touched = 1;

                /* Debounce: ignore rapid re-triggers within DEBOUNCE_US */
                if (last_state[i] == 0) {
                    log_touch_event(i + 1);
                    printf("Channel %d touched.\n", i + 1);
                }
            }
            last_state[i] = level;
        }

        control_led(any_touched);
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

