#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x40
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 1000000
#define POST_CONFIG_DELAY_US 100000

/* OPT3001 register addresses (16-bit, big-endian on the bus) */
#define OPT3001_REG_RESULT_L 0x00
#define OPT3001_REG_CONFIG_L 0x01

/* Configuration word: 16-bit, big-endian */
#define CONFIG_WORD_VALUE 0x0001  /* Example: 1 lux resolution, 100ms conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Swap bytes of a 16-bit value (big-endian -> little-endian, or vice versa) */
static uint16_t swap16(uint16_t val)
{
    return (uint16_t)((val >> 8) | (val << 8));
}

/* Write a 16-bit big-endian value to a 16-bit register address */
static int opt3001_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address */
static int opt3001_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Read ambient light (lux) from the OPT3001 */
static int read_light_level(int handle, float *lux)
{
    uint16_t config_word = swap16(CONFIG_WORD_VALUE);
    uint16_t result_raw;

    /* Write configuration word (big-endian on the bus) */
    if (opt3001_write_reg16(handle, OPT3001_REG_CONFIG_L, config_word) != 0) {
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(POST_CONFIG_DELAY_US);

    /* Read result (big-endian on the bus) */
    if (opt3001_read_reg16(handle, OPT3001_REG_RESULT_L, &result_raw) != 0) {
        return -1;
    }

    /* Convert raw value to lux (example: 1 lux per count) */
    *lux = (float)result_raw;
    return 0;
}

/* Log light level with timestamp to file and stdout */
static void log_light_level(FILE *fp, float lux)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fflush(fp);
    printf("%s, %.2f\n", timestamp, lux);
}

int main(void)
{
    float lux;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("OPT3001 light sensor logging started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (read_light_level(g_i2c_handle, &lux) == 0) {
            log_light_level(g_log_file, lux);
        } else {
            fprintf(stderr, "Error reading light level, skipping sample.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

