    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void)
{
    int last_state = 0;
    int current_state;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                TOUCH_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                TOUCH_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    last_state = gpioRead(TOUCH_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d\n",
                TOUCH_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_GPIO);

    while (running) {
        current_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n",
                    TOUCH_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (log_event(current_state ? "Touch Detected" : "Touch Released") != 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
            last_state = current_state;
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

