#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x48
#define CSV_FILE       "cooling_log.csv"
#define SAMPLE_PERIOD  1
#define MIN_FLOW       0.0f
#define MAX_FLOW       100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read flow from SLF3S-1300F.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];

    if (write(fd, cmd, 2) != 2) {
        perror("I2C write command");
        return -1;
    }

    /* Datasheet: minimum 2 ms between command and read */
    usleep(2000);

    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        if (n < 0) perror("I2C read");
        else fprintf(stderr, "I2C read short: %zd bytes\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch\n");
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float flow_rate, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(fp);
}

static void cleanup(void) {
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = i2c_init();
    if (g_i2c_fd < 0) {
        fprintf(stderr, "I2C init failed\n");
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        perror("fopen CSV");
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_csv);
    }

    while (g_running) {
        float flow_rate;
        int rc = read_flow_rate(g_i2c_fd, &flow_rate);

        if (rc == 0) {
            if (flow_rate < MIN_FLOW || flow_rate > MAX_FLOW) {
                log_data(g_csv, flow_rate, "INVALID");
                fprintf(stderr, "Out-of-range flow: %.2f ml/min\n", flow_rate);
            } else {
                log_data(g_csv, flow_rate, "OK");
            }
        } else {
            log_data(g_csv, 0.0f, "ERROR");
            fprintf(stderr, "Sensor read failed (rc=%d), re-initializing I2C...\n", rc);
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(100000);
            g_i2c_fd = i2c_init();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-init failed\n");
                break;
            }
        }

        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return 0;
}

