        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    unsigned pins[3] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
