#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define TOUCH_PIN 23
#define LED_PIN   24
#define GPIO_CHIP "/dev/gpiochip4"
#define LOG_FILE  "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_event(int led_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (log_fd < 0) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (dprintf(log_fd, "%s - Touch detected, LED state: %d\n", timestamp, led_state) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(log_fd) < 0) {
        fprintf(stderr, "Warning: fsync failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    struct timespec ts;
    int led_state = 0;
    int ret = EXIT_FAILURE;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (log_event(led_state) < 0) {
        fprintf(stderr, "Failed to write initial log entry\n");
        goto cleanup;
    }

    if (gpiochipOpen(GPIO_CHIP) < 0) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    if (gpiochipGetLine(GPIO_CHIP, TOUCH_PIN) < 0) {
        fprintf(stderr, "Failed to get touch line %d: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiochipGetLine(GPIO_CHIP, LED_PIN) < 0) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiochipGetLines(GPIO_CHIP, TOUCH_PIN, 1) < 0) {
        fprintf(stderr, "Failed to request touch line %d: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiochipGetLines(GPIO_CHIP, LED_PIN, 1) < 0) {
        fprintf(stderr, "Failed to request LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpioSetMode(GPIO_CHIP, TOUCH_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set touch line %d as input: %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpioSetMode(GPIO_CHIP, LED_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set LED line %d as output: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpioWrite(GPIO_CHIP, LED_PIN, led_state) < 0) {
        fprintf(stderr, "Failed to initialize LED state: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch lamp started. Touch GPIO23 to toggle LED on GPIO24. Press Ctrl+C to exit.\n");

    while (running) {
        int event_ret = gpioReadEvent(GPIO_CHIP, TOUCH_PIN, &ts);

        if (event_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpioReadEvent failed on touch pin %d: %s\n", TOUCH_PIN, strerror(errno));
            break;
        }

        if (event_ret == 1) {
            if (ts.tv_sec == 0 && ts.tv_nsec == 0) {
                fprintf(stderr, "gpioReadEvent returned with zero timestamp, ignoring\n");
                continue;
            }

            led_state = !led_state;

            if (gpioWrite(GPIO_CHIP, LED_PIN, led_state) < 0) {
                fprintf(stderr, "Failed to write LED state: %s\n", strerror(errno));
                break;
            }

            if (log_event(led_state) < 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (gpioWrite(GPIO_CHIP, LED_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off LED during cleanup: %s\n", strerror(errno));
    }
    gpiochipClose(GPIO_CHIP);

    if (log_fd >= 0) {
        if (close(log_fd) < 0) {
            fprintf(stderr, "Warning: failed to close log file: %s\n", strerror(errno));
        }
        log_fd = -1;
    }

    printf("Exiting.\n");
    return ret;
}

