static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *log_file, const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s - %s\n", ts, message) < 0) {
        perror("fprintf(log_file)");
    }
    if (fflush(log_file) != 0) {
        perror("fflush(log_file)");
    }
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *line, int duration_ms)
{
    if (gpiod_line_set_value(line, 1) != 0) {
        perror("gpiod_line_set_value(buzzer ON)");
        return -1;
    }

    for (int elapsed = 0; elapsed < duration_ms && g_running; elapsed += SLICE_MS) {
        usleep(SLICE_MS * 1000);
    }

    if (gpiod_line_set_value(line, 0) != 0) {
        perror("gpiod_line_set_value(buzzer OFF)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(log_file)");
        goto cleanup;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* ---- Get lines ---- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") != 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    /* ---- Log startup ---- */
    log_event(log_file, "System started");

    /* ---- Main loop: poll flame sensor every POLL_INTERVAL_MS ---- */
    int prev_flame = 1;   /* assume no flame at startup (active-low) */

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* LOW (0) => flame detected */
        if (val == 0 && prev_flame == 1) {
            log_event(log_file, "FLAME DETECTED");
            if (buzzer_on(buzzer_line, BUZZER_DURATION_MS) != 0) {
                break;
            }
        }

        prev_flame = val;

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_MS / SLICE_MS && g_running; i++) {
            usleep(SLICE_MS * 1000);
        }
    }

    /* ---- Log shutdown ---- */
    log_event(log_file, "System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure buzzer is off */
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return ret;
}

