#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN          17
#define DEBOUNCE_MS      200
#define POLL_INTERVAL_US 10000
#define LOG_FILE         "touch_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_touch_event(void)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int last_state = 0;
    int first_read = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        fclose(g_log_fp);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n",
                strerror(errno));
        fclose(g_log_fp);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed on touch sensor pin\n");
            break;
        }

        if (first_read) {
            last_state = current_state;
            first_read = 0;
        } else if (current_state == 1 && last_state == 0) {
            if (log_touch_event() != 0) {
                fprintf(stderr, "Warning: failed to log touch event\n");
            }

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                break;
            }

            gpioDelay(DEBOUNCE_MS * 1000);

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                break;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

