/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensors: 3 × TI TMAG5110A1 (open-drain latch output)
 *   Sensor 1 OUT → GPIO4  (BCM)
 *   Sensor 2 OUT → GPIO17 (BCM)
 *   Sensor 3 OUT → GPIO27 (BCM)
 *
 * Latch behavior (open-drain, active-low):
 *   - Magnet present  (south pole near sensor) → OUT = LOW  (0)
 *   - Magnet removed   → OUT = HIGH (1)
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000   /* 100 ms */

/* ------------------------------------------------------------------ */
/* Global state for signal-handler access                              */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — clean shutdown                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (ISO-8601, local time)                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Log a state change with timestamp                                   */
/* ------------------------------------------------------------------ */
static void log_state_change(int sensor_id, int state)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s - Sensor %d: %s\n",
                ts, sensor_id,
                state ? "Magnet Removed" : "Magnet Present");
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: log file not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error                  */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d).\n",
                pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure sensor pins                         */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d.\n",
                    pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %d.\n",
                    pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Open log file (append mode)                                         */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Close log file and terminate pigpio                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int sensor_pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);
    int prev_state[3] = {0, 0, 0};
    int first_read = 1;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio and configure pins */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring %d TMAG5110A1 sensors (GPIO%d, GPIO%d, GPIO%d)...\n",
           num_sensors, SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        for (int i = 0; i < num_sensors; ++i) {
            int state = read_sensor(sensor_pins[i]);
            if (state < 0) {
                /* Read error — skip this sample, keep running */
                continue;
            }

            if (first_read) {
                /* First reading: record initial state without logging */
                prev_state[i] = state;
                first_read = 0;
            } else if (state != prev_state[i]) {
                /* State change detected */
                log_state_change(i + 1, state);
                prev_state[i] = state;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

