    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int sensor_pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);
    int prev_state[3] = {0, 0, 0};
    int first_read = 1;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio and configure pins */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring %d TMAG5110A1 sensors (GPIO%d, GPIO%d, GPIO%d)...\n",
           num_sensors, SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        for (int i = 0; i < num_sensors; ++i) {
            int state = read_sensor(sensor_pins[i]);
            if (state < 0) {
                /* Read error — skip this sample, keep running */
                continue;
            }

            if (first_read) {
                /* First reading: record initial state without logging */
                prev_state[i] = state;
                first_read = 0;
            } else if (state != prev_state[i]) {
                /* State change detected */
                log_state_change(i + 1, state);
                prev_state[i] = state;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

