    if (i2c_read_reg8(fd, SI1182_REG_HW_REV, &raw) != 0)
        return -1;
    *bpm_out = (int)raw;
    return 0;
}

/* ---- Moving average filter ---- */

static double moving_average(double new_value, double *window, int *index,
                              int window_size)
{
    double sum = 0.0;
    for (int i = 0; i < window_size; i++)
        sum += window[i];
    double avg = sum / window_size;

    window[*index] = new_value;
    *index = (*index + 1) % window_size;

    return avg;
}

