static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ---- Sensor configuration ---- */

static int si1182_init(int fd)
{
    uint8_t part_id, hw_rev, hw_key;

    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    if (i2c_read_reg8(fd, SI1182_REG_HW_REV, &hw_rev) != 0)
        return -1;
    if (hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n",
                hw_rev, SI1182_HW_REV_EXPECTED);
        return -1;
    }

    if (i2c_read_reg8(fd, SI1182_REG_HW_KEY, &hw_key) != 0)
        return -1;
    if (hw_key != SI1182_HW_KEY_EXPECTED) {
        fprintf(stderr, "Unexpected HW_KEY: 0x%02X (expected 0x%02X)\n",
                hw_key, SI1182_HW_KEY_EXPECTED);
        return -1;
    }

    /*
     * Configure LED currents for the 16 on-chip LEDs.
     * Each LED current register (0x0F..0x1E) holds the current in
     * milliamps; a value of 0x00 disables the LED.
     * We enable all 16 LEDs at ~10 mA each.
     */
    for (int i = 0; i < 16; i++) {
        uint8_t reg = 0x0F + (uint8_t)(i * 2);
        if (i2c_write_reg8(fd, reg, 0x0A) != 0)
            return -1;
    }

    /*
     * Set measurement rate to 1 Hz (1000 ms / 1000 = 1).
     * The MEAS_RATE register is 8-bit; a value of 0x00 disables
     * measurements.  0x01 = 1 Hz.
     */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE, 0x01) != 0)
        return -1;

    return 0;
}

/* ---- Heart-rate reading ---- */

static int si1182_read_heart_rate(int fd, int *bpm_out)
{
    uint8_t raw;
    if (i2c_read_reg8(fd, SI1182_REG_HW_REV, &raw) != 0)
        return -1;
    *bpm_out = (int)raw;
    return 0;
}

/* ---- Moving average filter ---- */

static double moving_average(double new_value, double *window, int *index,
                              int window_size)
{
    double sum = 0.0;
    for (int i = 0; i < window_size; i++)
        sum += window[i];
    double avg = sum / window_size;

    window[*index] = new_value;
    *index = (*index + 1) % window_size;

    return avg;
}

/* ---- CSV logging ---- */

static int log_heart_rate(FILE *fp, int bpm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d\n", timestamp, bpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */

