/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads an 8-channel TTP226 capacitive touch sensor module on BCM pins
 * 5, 6, 7, 8, 9, 10, 11, 12 (OUT1..OUT8) and drives an 8-bit binary counter
 * on BCM pins 17 and 24 (bit 0 on 17, bit 7 on 24) using libgpiod.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    sudo ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 10
#define STABILIZE_MS 200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[2] = {17, 24};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_touch_event(FILE *log_file, int channel, int counter)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file) {
        if (fprintf(log_file, "%s, Channel: %d, Counter: %d\n",
                    timestamp, channel, counter) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        }
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[2];
    int counter = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        sensor_lines[i] = NULL;
    for (int i = 0; i < 2; i++)
        counter_lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(sensor %u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "touch_counter") < 0) {
            fprintf(stderr, "gpiod_line_request_input(sensor %u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 2; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(counter %u) failed: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(counter %u) failed: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    FILE *log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: could not open touch_log.txt: %s\n",
                strerror(errno));
    }

    printf("Touch sensor counter started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    usleep(STABILIZE_MS * 1000);

    while (running) {
        int prev_counter = counter;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(sensor %u) failed: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 1) {
                counter = (counter + 1) & 0xFF;
                if (counter != prev_counter) {
                    log_touch_event(log_file, i + 1, counter);
                }
            }
        }

        for (int i = 0; i < 2; i++) {
            int val = (counter >> (1 - i)) & 1;
            if (gpiod_line_set_value(counter_lines[i], val) < 0) {
                fprintf(stderr, "gpiod_line_set_value(counter %u) failed: %s\n",
                        counter_pins[i], strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 2; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
            gpiod_line_release(counter_lines[i]);
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i])
            gpiod_line_release(sensor_lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);

    return ret;
}

