        fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int pins[NUM_SENSORS];
    int i;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_SENSORS; i++) {
        pins[i] = sensor_pins[i];
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "ky033-tracking") < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    if (write_header_if_needed(fp) < 0) {
        goto cleanup;
    }

    printf("Starting KY-033 sensor logging to %s. Press Ctrl+C to stop.\n", CSV_FILENAME);

    while (program_running) {
        int values[NUM_SENSORS];
        int read_error = 0;

        for (i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n", pins[i], strerror(errno));
                read_error = 1;
                break;
            }
            values[i] = val;
        }

        if (read_error) {
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (log_sensor_data(fp, values[0], values[1], values[2], values[3]) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

