        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", SENSOR_1_GPIO, strerror(errno));
        } else {
            sensor1_state = s1;
            uint32_t now = gpioTick();
            if (sensor1_state == 0 && last_sensor1_state == 1 &&
                (now - last_change_time1) >= (DEBOUNCE_MS * 1000)) {
                log_event(1);
                last_change_time1 = now;
            }
            last_sensor1_state = sensor1_state;
        }

        if (s2 < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", SENSOR_2_GPIO, strerror(errno));
        } else {
            sensor2_state = s2;
            uint32_t now = gpioTick();
            if (sensor2_state == 0 && last_sensor2_state == 1 &&
                (now - last_change_time2) >= (DEBOUNCE_MS * 1000)) {
                log_event(2);
                last_change_time2 = now;
            }
            last_sensor2_state = sensor2_state;
        }

        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

