/*
 * ICS-40180 analog MEMS microphone peak detector for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ICS-40180 VDD  -> 3.3 V (pin 1)
 *   ICS-40180 GND  -> GND   (pin 9)
 *   ICS-40180 OUT  -> GPIO4 (BCM 4, physical pin 7) via 10 kΩ resistor
 *   LED anode     -> GPIO17 (BCM 17, physical pin 11) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mic_peak mic_peak.c -lgpiod
 * Run:    sudo ./mic_peak
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MIC_PIN    4          /* BCM 4  – analog microphone output */
#define LED_PIN    17         /* BCM 17 – LED control            */
#define LED_MS     100        /* LED on duration in milliseconds */
#define SAMPLE_US  125        /* 8 kHz sampling period           */
#define POLL_TIMEOUT_MS 1000  /* gpiod_line_get_value timeout    */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld", buf, ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *mic_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open the gpiochip that exposes BCM 4 / BCM 17 ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first available chip */
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    mic_line = gpiod_chip_get_line(chip, MIC_PIN);
    if (!mic_line) {
        perror("gpiod_chip_get_line(mic)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Request microphone line as input */
    if (gpiod_line_request_input(mic_line, "mic_peak") < 0) {
        perror("gpiod_line_request_input(mic)");
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "mic_peak", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    /* Install SIGINT handler */
    if (install_signal_handler() < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("ICS-40180 peak detector running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int val = gpiod_line_get_value(mic_line);
        if (val < 0) {
            perror("gpiod_line_get_value(mic)");
            break;
        }

        if (val == 1) {
            print_timestamp();
            printf(" - Sound peak detected\n");
            fflush(stdout);

            /* Turn LED on */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led, on)");
                break;
            }

            /* Keep LED on for LED_MS milliseconds */
            struct timespec ts_start, ts_now;
            clock_gettime(CLOCK_MONOTONIC, &ts_start);
            long elapsed_ms = 0;
            while (g_running && elapsed_ms < LED_MS) {
                clock_gettime(CLOCK_MONOTONIC, &ts_now);
                elapsed_ms = (ts_now.tv_sec - ts_start.tv_sec) * 1000L
                            + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000L;
                usleep(1000); /* 1 ms */
            }

            /* Turn LED off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led, off)");
                break;
            }
        }

        usleep(SAMPLE_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (mic_line) {
        gpiod_line_release(mic_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

