#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int left_state, center_state, right_state;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with internal pull-up resistors */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-up resistors to settle */
    usleep(10000);

    printf("SunFounder 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%d | Center: GPIO%d | Right: GPIO%d\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (running) {
        left_state = gpioRead(LEFT_SENSOR_PIN);
        center_state = gpioRead(CENTER_SENSOR_PIN);
        right_state = gpioRead(RIGHT_SENSOR_PIN);

        if (left_state < 0 || center_state < 0 || right_state < 0) {
            fprintf(stderr, "Error: GPIO read failure (L=%d, C=%d, R=%d).\n",
                    left_state, center_state, right_state);
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n",
               left_state, center_state, right_state);

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

