/*
 * Si1175 ALS Reader for Raspberry Pi 4 Model B
 *
 * Reads the 16-bit visible ambient light sensor (ALS) data from a Si1175
 * optical heart-rate sensor over I2C bus 1.  The Si1175 exposes the ALS
 * data as two 8-bit registers (0x16 and 0x17) that are combined into a
 * single 16-bit raw value.
 *
 * Wiring:
 *   Si1175 SDA -> GPIO2 (I2C bus 1 SDA)
 *   Si1175 SCL -> GPIO3 (I2C bus 1 SCL)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1175 I2C address ---- */
#define SI1175_ADDR 0x60

/* ---- Si1175 register addresses ---- */
#define SI1175_REG_ALS_VIS_DATA0 0x16  /* ALS visible light data LSB  */
#define SI1175_REG_ALS_VIS_DATA1 0x17  /* ALS visible light data MSB  */

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for Ctrl+C / SIGINT                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an Si1175 register                           */
/* ------------------------------------------------------------------ */
static int si1175_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit ALS visible light value                             */
/* ------------------------------------------------------------------ */
static int si1175_read_als_vis(int handle, uint16_t *als_vis)
{
    uint8_t lo, hi;

    if (si1175_read_byte(handle, SI1175_REG_ALS_VIS_DATA0, &lo) != 0)
        return -1;
    if (si1175_read_byte(handle, SI1175_REG_ALS_VIS_DATA1, &hi) != 0)
        return -1;

    *als_vis = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the Si1175 address ---- */
    g_i2c_handle = i2cOpen(1, SI1175_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1175_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }

    printf("Si1175 ALS Reader started.  Press Ctrl+C to exit.\n");
    printf("Sampling every %d us.\n\n", SAMPLE_INTERVAL_US);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t als_vis = 0;

        if (si1175_read_als_vis(g_i2c_handle, &als_vis) == 0) {
            printf("ALS (visible): %u\n", als_vis);
            fflush(stdout);
        } else {
            fprintf(stderr, "[ERROR] Failed to read ALS data\n");
        }

        /*
         * Sleep in small increments so SIGINT is caught promptly.
         * gpioDelay is a busy-wait-free microsecond delay.
         */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

