/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (BCM numbering):
 *   TP1 -> GPIO5   TP2 -> GPIO6   TP3 -> GPIO13  TP4 -> GPIO19
 *   TP5 -> GPIO26  TP6 -> GPIO12  TP7 -> GPIO16  TP8 -> GPIO20
 *   VCC -> 3.3 V   GND -> GND
 *
 * Compile: gcc -o touch_poll touch_poll.c -lrt
 * Run:     ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

#include <linux/gpio.h>
#include <linux/input.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }
}

static int request_line_input(int fd, unsigned int pin)
{
    struct gpio_desc *desc = NULL;
    struct gpio_chip *chip = NULL;
    int ret;

    ret = gpiochip_open_by_label("gpiochip0");
    if (ret < 0) {
        ret = gpiochip_open_by_number(0);
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    chip = (struct gpio_chip *)ret;

    desc = gpiochip_get_line(chip, pin);
    if (!desc) {
        fprintf(stderr, "Failed to get GPIO line %u: %s\n", pin, strerror(errno));
        gpiochip_close(chip);
        return -1;
    }

    ret = gpiochip_request_line(chip, desc,
                                GPIO_LINE_REQUEST_DIRECTION_INPUT,
                                0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                pin, strerror(errno));
        gpiochip_release_line(chip, desc);
        gpiochip_close(chip);
        return -1;
    }

    return 0;
}

static int read_line(int fd, unsigned int pin)
{
    struct gpio_desc *desc = NULL;
    struct gpio_chip *chip = NULL;
    int ret;

    ret = gpiochip_open_by_label("gpiochip0");
    if (ret < 0) {
        ret = gpiochip_open_by_number(0);
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    chip = (struct gpio_chip *)ret;

    desc = gpiochip_get_line(chip, pin);
    if (!desc) {
        fprintf(stderr, "Failed to get GPIO line %u: %s\n", pin, strerror(errno));
        gpiochip_close(chip);
        return -1;
    }

    ret = gpiochip_get_value(chip, desc);
    if (ret < 0) {
        fprintf(stderr, "Failed to read GPIO line %u: %s\n", pin, strerror(errno));
        gpiochip_release_line(chip, desc);
        gpiochip_close(chip);
        return -1;
    }

    gpiochip_release_line(chip, desc);
    gpiochip_close(chip);
    return ret;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return;
    }
    printf("[%ld.%09ld] ", (long)ts.tv_sec, (long)ts.tv_nsec);
}

int main(void)
{
    int ret;
    int lines_requested = 0;
    int exit_code = EXIT_SUCCESS;

    install_signal_handlers();

    for (int i = 0; i < NUM_CHANNELS; i++) {
        ret = request_line_input(0, channel_pins[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input.\n",
                    channel_pins[i]);
            exit_code = EXIT_FAILURE;
            goto cleanup;
        }
        lines_requested++;
    }

    while (g_running) {
        print_timestamp();
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = read_line(0, channel_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u.\n",
                        channel_pins[i]);
                exit_code = EXIT_FAILURE;
                goto cleanup;
            }
            printf("CH%d=%d ", i + 1, val);
        }
        printf("\n");
        fflush(stdout);

        struct timespec sleep_ts;
        sleep_ts.tv_sec = 0;
        sleep_ts.tv_nsec = POLL_INTERVAL_MS * 1000000L;
        nanosleep(&sleep_ts, NULL);
    }

cleanup:
    for (int i = 0; i < lines_requested; i++) {
        struct gpio_desc *desc = NULL;
        struct gpio_chip *chip = NULL;
        int ret = gpiochip_open_by_label("gpiochip0");
        if (ret < 0) {
            ret = gpiochip_open_by_number(0);
        }
        if (ret < 0) {
            fprintf(stderr, "Failed to open gpiochip0 for cleanup: %s\n",
                    strerror(errno));
            goto cleanup_exit;
        }
        chip = (struct gpio_chip *)ret;

        desc = gpiochip_get_line(chip, channel_pins[i]);
        if (desc) {
            gpiochip_release_line(chip, desc);
        }
        gpiochip_close(chip);
    }

cleanup_exit:
    return exit_code;
}

