/*
 * fade_rgb_led.c — Fade a common-anode RGB LED between random hues on a
 * Raspberry Pi 4 Model B using the Linux GPIO character-device interface
 * (libgpiod).  Each transition is a 50-step linear interpolation over 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fade_rgb_led fade_rgb_led.c -lgpiod
 * Run:    sudo ./fade_rgb_led
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_RANGE  255          /* 8-bit resolution */
#define PWM_FREQ  1000         /* Hz */
#define STEPS     50            /* per transition */
#define STEP_MS   100          /* 5 s total */
#define LOOP_MS   100000       /* 100 s between hue changes */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

static void clamp_u8(int *v)
{
    if (*v < 0)   *v = 0;
    if (*v > 255) *v = 255;
}

static void set_led(struct gpiod_line *r, struct gpiod_line *g,
                    struct gpiod_line *b, int r_val, int g_val, int b_val)
{
    clamp_u8(&r_val);
    clamp_u8(&g_val);
    clamp_u8(&b_val);

    if (gpiod_line_set_value(r, r_val) < 0)
        syslog(LOG_ERR, "set_value(red): %s", strerror(errno));
    if (gpiod_line_set_value(g, g_val) < 0)
        syslog(LOG_ERR, "set_value(green): %s", strerror(errno));
    if (gpiod_line_set_value(b, b_val) < 0)
        syslog(LOG_ERR, "set_value(blue): %s", strerror(errno));
}

static void turn_off(struct gpiod_line *r, struct gpiod_line *g,
                     struct gpiod_line *b)
{
    set_led(r, g, b, 0, 0, 0);
}

/* ------------------------------------------------------------------ */
/* RGB math                                                        */
/* ------------------------------------------------------------------ */

/*
 * Convert a hue (0..360) to RGB for a common-anode LED.
 *   0   -> red
 *   120 -> green
 *   240 -> blue
 *   360 -> red
 *
 * Common-anode: 0 = full brightness, 255 = off.
 */
static void hue_to_rgb(float hue, int *r, int *g, int *b)
{
    hue = fmodf(hue, 360.0f);
    if (hue < 0.0f)   hue += 360.0f;

    float h = hue / 60.0f;
    int   i = (int)h;
    float f = h - (float)i;
    float p = 0.0f;
    float q = 1.0f - f;
    float t = 1.0f - q;

    float r_f, g_f, b_f;

    switch (i % 6) {
    case 0: r_f = 1.0f; g_f = t; b_f = p; break;
    case 1: r_f = q; g_f = 1.0f; b_f = p; break;
    case 2: r_f = p; g_f = 1.0f; b_f = t; break;
    case 3: r_f = p; g_f = q; b_f = 1.0f; break;
    case 4: r_f = t; g_f = p; b_f = 1.0f; break;
    case 5: r_f = 1.0f; g_f = p; b_f = q; break;
    default: r_f = g_f = b_f = 0.0f; break;
    }

    /* Common-anode: invert */
    *r = (int)(255.0f * (1.0f - r_f));
    *g = (int)(255.0f * (1.0f - g_f));
    *b = (int)(255.0f * (1.0f - b_f));
}

/*
 * Linear interpolation between two RGB values over STEPS steps.
 * Returns the final RGB values in *out_r, *out_g, *out_b.
 */
static void interpolate(int r1, int g1, int b1,
                        int r2, int g2, int b2,
                        int *out_r, int *out_g, int *out_b)
{
    float dr = (float)(r2 - r1) / STEPS;
    float dg = (float)(g2 - g1) / STEPS;
    float db = (float)(b2 - b1) / STEPS;

    float r = (float)r1;
    float g = (float)g1;
    float b = (float)b1;

    for (int i = 0; i < STEPS; i++) {
        r += dr;
        g += dg;
        b += db;
        set_led(r_line, g_line, b_line, (int)r, (int)g, (int)b);
        usleep(STEP_MS * 1000);
    }

    *out_r = (int)r;
    *out_g = (int)g;
    *out_b = (int)b;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("fade_rgb_led", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting fade_rgb_led");

    install_signals();

    /* ---- Open the default GPIO chip (gpiochip4 on Pi 4 with 5.10+ kernel) ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *r_line = gpiod_chip_get_line(chip, RED_PIN);
    struct gpiod_line *g_line = gpiod_chip_get_line(chip, GREEN_PIN);
    struct gpiod_line *b_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!r_line || !g_line || !b_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    /* Request each line as an output, initially low (off for common-anode) */
    if (gpiod_line_request_output(r_line, "fade_rgb_led", 0) < 0) {
        syslog(LOG_ERR, "request_output(red): %s", strerror(errno));
        goto fail;
    }
    if (gpiod_line_request_output(g_line, "fade_rgb_led", 0) < 0) {
        syslog(LOG_ERR, "request_output(green): %s", strerror(errno));
        goto fail;
    }
    if (gpiod_line_request_output(b_line, "fade_rgb_led", 0) < 0) {
        syslog(LOG_ERR, "request_output(blue): %s", strerror(errno));
        goto fail;
    }

    /* Seed PRNG from /dev/urandom */
    FILE *urandom = fopen("/dev/urandom", "rb");
    if (!urandom) {
        syslog(LOG_ERR, "fopen(/dev/urandom): %s", strerror(errno));
        goto fail;
    }
    unsigned char seed_buf[4];
    if (fread(seed_buf, 1, sizeof(seed_buf), urandom) != sizeof(seed_buf)) {
        syslog(LOG_ERR, "fread(/dev/urandom): %s", strerror(errno));
        fclose(urandom);
        goto fail;
    }
    fclose(urandom);
    srand((unsigned int)seed_buf[0] | ((unsigned int)seed_buf[1] << 8) |
          ((unsigned int)seed_buf[2] << 16) | ((unsigned int)seed_buf[3] << 24));

    int r1 = 0, g1 = 0, b1 = 0;
    hue_to_rgb((float)rand() / RAND_MAX * 360.0f, &r1, &g1, &b1);
    set_led(r_line, g_line, b_line, r1, g1, b1);

    while (g_running) {
        float hue = (float)rand() / RAND_MAX * 360.0f;
        int r2, g2, b2;
        hue_to_rgb(hue, &r2, &g2, &b2);

        interpolate(r1, g1, b1, r2, g2, b2, &r1, &g1, &b1);

        /* Sleep LOOP_MS, but wake early on signal */
        for (int ms = 0; ms < LOOP_MS && g_running; ms += 100)
            usleep(100 * 1000);
    }

    /* ---- Graceful shutdown ---- */
    turn_off(r_line, g_line, b_line);
    gpiod_line_release(r_line);
    gpiod_line_release(g_line);
    gpiod_line_release(b_line);
    gpiod_chip_close(chip);
    syslog(LOG_INFO, "Fade_rgb_led stopped");
    closelog();
    return EXIT_SUCCESS;

fail:
    turn_off(r_line, g_line, b_line);
    gpiod_line_release(r_line);
    gpiod_line_release(g_line);
    gpiod_line_release(b_line);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_FAILURE;
}

