/*
 * TCS34725 Color Sensor Reader with LED Threshold Indicator
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1 (BCM pins 2 = SDA, 3 = SCL)
 * Sensor: TCS34725 at 0x29
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o tcs34725 tcs34725.c -lpigpio -lrt
 * Run:    sudo ./tcs34725
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- TCS34725 register definitions ---- */
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_ID              0x12
#define TCS34725_CDATAL          0x14
#define TCS34725_RDATAL          0x16
#define TCS34725_GDATAL          0x18
#define TCS34725_BDATAL          0x1A
#define TCS34725_CONTROL         0x0F

#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02

/* ---- Application constants ---- */
#define I2C_BUS                 "/dev/i2c-1"
#define LED_GPIO                 17
#define RED_THRESHOLD            200
#define POLL_INTERVAL_US         200000   /* 200 ms */
#define ATIME_154MS              0x04     /* ~154 ms integration time */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static int      g_led_gpio = -1;
static bool     g_sensor_ok = false;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                            */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int tcs_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register.                             */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int tcs_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "write(reg=0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725 sensor.                                    */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int fd)
{
    uint8_t id = 0;

    /* Verify sensor identity (ID register at 0x12). */
    if (tcs_read_reg(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Cannot read TCS34725 ID register.\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44).\n", id);
        return -1;
    }

    /* Power on (PON). */
    if (tcs_write_reg(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    usleep(3000);  /* allow PON to settle */

    /* Set integration time (~154 ms). */
    if (tcs_write_reg(fd, TCS34725_ATIME, ATIME_154MS) != 0)
        return -1;

    /* Enable RGBC (AEN). */
    if (tcs_write_reg(fd, TCS34725_ENABLE,
                      TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    usleep(3000);  /* allow first integration cycle */
    g_sensor_ok = true;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw RGBC values from the TCS34725.                             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_read_raw(int fd, uint16_t *r, uint16_t *g,
                             uint16_t *b, uint16_t *c)
{
    uint8_t buf[8];

    if (!g_sensor_ok) {
        fprintf(stderr, "Sensor not initialized; cannot read.\n");
        return -1;
    }

    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | TCS34725_CDATAL);
    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "write(CDATAL) failed: %s\n", strerror(errno));
        return -1;
    }
    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read(CDATAL..BDATAL) failed: %s\n", strerror(errno));
        return -1;
    }

    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated RGBC values.                                        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_read_calibrated(int fd, uint16_t *r, uint16_t *g,
                                    uint16_t *b, uint16_t *c)
{
    uint16_t raw_r, raw_g, raw_b, raw_c;

    if (tcs34725_read_raw(fd, &raw_r, &raw_g, &raw_b, &raw_c) != 0)
        return -1;

    /*
     * TCS34725 default calibration (gain = 1, no power-of-two scaling).
     * The datasheet provides a full calibration routine; here we assume
     * the sensor is already calibrated or the defaults are acceptable.
     */
    *r = raw_r;
    *g = raw_g;
    *b = raw_b;
    *c = raw_c;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper.  Releases all resources.                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led_gpio >= 0) {
        gpioWrite(g_led_gpio, 0);
        gpioSetMode(g_led_gpio, PI_INPUT);
        g_led_gpio = -1;
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor before closing. */
        (void)tcs_write_reg(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (tcs34725_init(g_i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO. */
    g_led_gpio = LED_GPIO;
    if (gpioSetMode(g_led_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed.\n", g_led_gpio);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(g_led_gpio, 0);

    printf("TCS34725 ready.  Polling every %d ms.  Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);

    /* Main loop. */
    while (g_running) {
        uint16_t r, g, b, c;

        if (tcs34725_read_calibrated(g_i2c_fd, &r, &g, &b, &c) != 0) {
            fprintf(stderr, "Read failed; re-initializing sensor.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            g_sensor_ok = false;

            usleep(100000);
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "re-open(%s) failed: %s\n", I2C_BUS, strerror(errno));
                continue;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
                close(g_i2c_fd);
                g_i2c_fd = -1;
                continue;
            }
            if (tcs34725_init(g_i2c_fd) != 0) {
                fprintf(stderr, "re-init failed; will retry next cycle.\n");
                continue;
            }
            g_sensor_ok = true;
            continue;
        }

        printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);

        if (r > RED_THRESHOLD) {
            gpioWrite(g_led_gpio, 1);
            printf("  -> RED threshold exceeded -> LED ON\n");
        } else {
            gpioWrite(g_led_gpio, 0);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

