/*
 * Raspberry Pi 4 Model B – BH1750 light sensor → 10-LED WS2812B strip
 *
 * Hardware:
 *   - BH1750 FWH (I2C address 0x29) on /dev/i2c-1 (SDA=GPIO2, SCL=GPIO3)
 *   - 10 × WS2812B LEDs on GPIO18 (PCM_CLK, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bh1750_ws2812 bh1750_ws2812.c
 *
 * Run:
 *   ./bh1750_ws2812
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/pwm.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x29
#define BH1750_ONE_TIME 0x01
#define BH1750_MEAS_MS  180

#define NUM_LEDS       10
#define PWM_CHIP       0
#define PWM_CHANNEL    0
#define PWM_PERIOD_NS  10000000ULL   /* 10 MHz – WS2812B expects ~1.25 µs per bit */
#define PWM_DUTY_OFF   0ULL
#define PWM_DUTY_ON    5000000ULL   /* 50% of period */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_pwm_fd = -1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out)
{
    if (i2c_write_cmd(fd, BH1750_ONE_TIME) < 0)
        return -1;

    usleep(BH1750_MEAS_MS * 1000);

    uint8_t data[2];
    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void map_lux_to_leds(float lux, uint8_t leds[NUM_LEDS])
{
    float log_lux = log10f(lux > 0.0f ? lux : 1.0f);
    float norm = log_lux / 3.0f;   /* ~0..1 for 0..1000 lux */
    for (int i = 0; i < NUM_LEDS; i++) {
        leds[i] = (uint8_t)(norm * 255.0f);
    }
}

static int pwm_init(void)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "PWM open failed: %s\n", strerror(errno));
        return -1;
    }

