/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Wiring:
 *   BH1750 SDA → GPIO2 (pin 3), SCL → GPIO3 (pin 5), VCC → 3V3, GND → GND
 *   APA102 DIN → GPIO10 (pin 19), VCC → 5V, GND → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -li2c -lrt
 *
 * Run:
 *   sudo ./light_led
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_DEVICE     "/dev/spidev0.0"
#define BH1750_ADDR    0x29
#define BH1750_PWR_ON  0x01
#define BH1750_CONT_HRES 0x10   /* 1 lux resolution, ~120 ms */
#define NUM_LEDS       8
#define SPI_SPEED_HZ   1000000
#define SAMPLE_DELAY_US 150000   /* 150 ms between samples */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "i2c_write_byte(0x%02X) failed: %s\n",
                byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes(%zu) failed: %s\n",
                len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "spi_transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BH1750                                                             */
/* ------------------------------------------------------------------ */

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0)
        return -1;
    usleep(10000);  /* power-up settling */
    return 0;
}

static int bh1750_read_lux(int fd, uint16_t *lux_out)
{
    uint8_t cmd = BH1750_CONT_HRES;
    if (i2c_write_byte(fd, cmd) < 0)
        return -1;

    usleep(120000);  /* 120 ms conversion time */

    uint8_t data[2];
    if (i2c_read_bytes(fd, data, 2) < 0)
        return -1;

    *lux_out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* APA102                                                             */
/* ------------------------------------------------------------------ */

static int apa102_set_color(int fd, uint8_t r, uint8_t g, uint8_t b)
{
    uint8_t tx[4 + NUM_LEDS * 4 + 4];
    uint8_t rx[4 + NUM_LEDS * 4 + 4];

    /* 32-bit start frame (all 0) */
    memset(tx, 0x00, 4);
    /* 32-bit end frame (all 0) */
    memset(tx + 4 + NUM_LEDS * 4, 0x00, 4);

    for (int i = 0; i < NUM_LEDS; i++) {
        tx[4 + i * 4]     = 0xE0;  /* global brightness = 255 */
        tx[4 + i * 4 + 1] = b;
        tx[4 + i * 4 + 2] = g;
        tx[4 + i * 4 + 3] = r;
    }

    return spi_transfer(fd, tx, rx, sizeof(tx));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1, spi_fd = -1;
    int rc = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed – sensor may be absent or bus error\n");
        goto cleanup;
    }

    /* ---- Open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t lux = 0;

        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error – continuing\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        /* Scale 0–255 lux to 0–255 brightness */
        uint8_t brightness = (uint8_t)(lux / 2);
        if (brightness > 255) brightness = 255;

        if (apa102_set_color(spi_fd, brightness, brightness, brightness) < 0) {
            fprintf(stderr, "APA102 SPI transfer failed – continuing\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    if (apa102_set_color(spi_fd, 0, 0, 0) < 0)
        fprintf(stderr, "Warning: failed to turn off LEDs on shutdown\n");

    rc = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd  >= 0) close(spi_fd);
    return rc;
}

