/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1, spi_fd = -1;
    int rc = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed – sensor may be absent or bus error\n");
        goto cleanup;
    }

    /* ---- Open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t lux = 0;

        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error – continuing\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        /* Scale 0–255 lux to 0–255 brightness */
        uint8_t brightness = (uint8_t)(lux / 2);
        if (brightness > 255) brightness = 255;

        if (apa102_set_color(spi_fd, brightness, brightness, brightness) < 0) {
            fprintf(stderr, "APA102 SPI transfer failed – continuing\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    if (apa102_set_color(spi_fd, 0, 0, 0) < 0)
        fprintf(stderr, "Warning: failed to turn off LEDs on shutdown\n");

    rc = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd  >= 0) close(spi_fd);
    return rc;
}

