/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient light sensor → APA102 LED strip
 *
 * Hardware:
 *   - I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *   - Up to 3 × BH1750 sensors at addresses 0x5C or 0x5D
 *   - APA102 strip: MOSI = GPIO10 (BCM), SCLK = GPIO11 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_strip light_strip.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define BH1750_ADDR_1        0x5C
#define BH1750_ADDR_2        0x5D
#define NUM_SENSORS          3
#define SPI_CHANNEL          0
#define SPI_SPEED            1000000          /* 1 MHz — well within APA102 spec */
#define SPI_FLAGS            0                /* Mode 0, active-high CS */
#define LED_COUNT            32               /* APA102 pixels on the strip */
#define FADE_STEPS           50               /* 500 ms fade over 50 steps */
#define FADE_DELAY_US        10000            /* 10 ms per step */
#define LOOP_DELAY_US        100000           /* 100 ms between cycles */
#define BH1750_CONV_MS       180              /* 170–180 ms conversion time */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[NUM_SENSORS];
static int g_spi_handle = -1;
static int g_pigpio_ready = 0;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_spi(void);
static int  read_bh1750(int handle, uint16_t *lux);
static int  read_sensors(uint16_t *lux_out);
static void set_led_strip_color(uint8_t r, uint8_t g, uint8_t b);
static void fade_strip(uint8_t r, uint8_t g, uint8_t b, uint32_t duration_us);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */

static int init_i2c(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        int addr = (i == 0) ? BH1750_ADDR_1 : BH1750_ADDR_2;
        int h = i2cOpen(I2C_BUS, addr, 0);
        if (h < 0) {
            fprintf(stderr, "Warning: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                    I2C_BUS, addr, h);
            g_i2c_handles[i] = -1;
        } else {
            printf("BH1750 found at 0x%02X (handle %d)\n", addr, h);
            g_i2c_handles[i] = h;
        }
    }
    return 0;
}

/* ----------------------------- SPI init ---------------------------------- */

static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- BH1750 read -------------------------------- */

/*
 * Trigger a one-time measurement (write 0x01 to the device) and read the
 * 2-byte result after BH1750_CONV_MS.
 * Returns 0 on success, -1 on I2C error, -2 on timeout/no-device.
 */
static int read_bh1750(int handle, uint16_t *lux)
{
    if (handle < 0) return -1;

    /* Trigger one-time measurement */
    if (i2cWriteByte(handle, 0x01) < 0) {
        fprintf(stderr, "i2cWriteByte (trigger) failed: %d\n", handle);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);

    /* Read 2 bytes (MSB first) */
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "i2cReadDevice returned %d (expected 2): %d\n", n, handle);
        return -2;
    }

    *lux = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ----------------------------- Sensor read -------------------------------- */

static int read_sensors(uint16_t *lux_out)
{
    uint32_t sum = 0;
    int valid = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] < 0) continue;

        uint16_t lux;
        int rc = read_bh1750(g_i2c_handles[i], &lux);
        if (rc == 0) {
            sum += lux;
            valid++;
        } else {
            fprintf(stderr, "Sensor %d (handle %d) read failed (rc=%d)\n",
                    i, g_i2c_handles[i], rc);
        }
    }

    if (valid == 0) {
        fprintf(stderr, "No valid BH1750 readings — using default 128\n");
        *lux_out = 128;
        return -1;
    }

    *lux_out = (uint16_t)(sum / valid);
    return 0;
}

/* ----------------------------- APA102 helpers ----------------------------- */

/*
 * APA102 frame: 4 bytes per pixel (start=0x00, GRB, end=0xFF).
 * We set all pixels to the same color.
 */
static void set_led_strip_color(uint8_t r, uint8_t g, uint8_t b)
{
    if (g_spi_handle < 0) return;

    uint8_t frame[LED_COUNT * 4];
    for (int i = 0; i < LED_COUNT; i++) {
        frame[i * 4 + 0] = 0x00;
        frame[i * 4 + 1] = 0x00;
        frame[i * 4 + 2] = b;
        frame[i * 4 + 3] = g;
        frame[i * 4 + 4] = r;
        frame[i * 4 + 5] = 0xFF;
    }

    int n = spiWrite(g_spi_handle, (char *)frame, sizeof(frame));
    if (n != (int)sizeof(frame)) {
        fprintf(stderr, "spiWrite failed: %d\n", n);
    }
}

static void fade_strip(uint8_t r, uint8_t g, uint8_t b, uint32_t duration_us)
{
    uint32_t step_us = duration_us / FADE_STEPS;
    uint8_t r_step = (uint8_t)((int32_t)r * FADE_STEPS / duration_us);
    uint8_t g_step = (uint8_t)((int32_t)g * FADE_STEPS / duration_us);
    uint8_t b_step = (uint8_t)((int32_t)b * FADE_STEPS / duration_us);

    for (int i = 0; i <= FADE_STEPS && g_running; i++) {
        uint8_t cr = (uint8_t)((int32_t)r_step * i / FADE_STEPS);
        uint8_t cg = (uint8_t)((int32_t)g_step * i / FADE_STEPS);
        uint8_t cb = (uint8_t)((int32_t)b_step * i / FADE_STEPS);
        set_led_strip_color(cr, cg, cb);
        gpioDelay(step_us);
    }
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        /* Turn off the strip (all pixels black) */
        set_led_strip_color(0, 0, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }

    if (g_pigpio_ready) {
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed — continuing with available sensors\n");
    }

    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting light-to-brightness control loop...\n");

    while (g_running) {
        uint16_t lux = 0;
        int rc = read_sensors(&lux);

        if (rc == 0) {
            printf("Lux: %u\n", lux);

            /* Map lux to a brightness value (0–255) */
            uint8_t brightness = (uint8_t)(lux / 100);
            if (brightness > 255) brightness = 255;

            /* Set all pixels to the computed brightness (white) */
            fade_strip(brightness, brightness, brightness, 500000);
        } else {
            fprintf(stderr, "Sensor read failed — keeping current brightness\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

