#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x45
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04
#define WS2812B_PIN 18
#define NUM_LEDS 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg8(fd, VEML7700_CONFIG, 0x00) < 0) {
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg8(fd, VEML7700_CONFIG, 0x01) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int veml7700_read_lux(int fd, float *lux) {
    uint16_t raw;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, VEML7700_ALS_DATA, &raw) == 0) {
            *lux = (float)raw * 0.001f;
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static float gamma_correct(float lux) {
    if (lux <= 0.0f) return 0.0f;
    float gamma = 2.2f;
    return powf(lux, 1.0f / gamma);
}

static int ws2812b_set_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t data[NUM_LEDS * 24];
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i * 24] = 0x00;
        data[i * 24 + 1] = 0xFF;
        data[i * 24 + 2] = 0x00;
        data[i * 24 + 3] = (uint8_t)(brightness * 255 / 100);
        data[i * 24 + 4] = 0x00;
