#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define SELF_TEST_SAMPLES 5
#define SELF_TEST_INTERVAL_US 100000  /* 100 ms */
#define POLL_INTERVAL_US 50000        /* 50 ms */
#define ERROR_BLINK_CYCLES 5
#define ERROR_BLINK_INTERVAL_US 100000 /* 100 ms */
#define ERROR_BUZZER_PATTERN_US {200, 200, 600, 200}
#define ERROR_BUZZER_PATTERN_REPEAT 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

static int safe_write(unsigned pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
    }
    return v;
}

static void error_signal(void) {
    log_event("Self-test failed: flame detected on all samples");
    for (int i = 0; i < ERROR_BLINK_CYCLES && g_running; i++) {
        safe_write(LED_PIN, 1);
        gpioDelay(ERROR_BLINK_INTERVAL_US);
        safe_write(LED_PIN, 0);
        gpioDelay(ERROR_BLINK_INTERVAL_US);
    }
    for (int r = 0; r < ERROR_BUZZER_PATTERN_REPEAT && g_running; r++) {
        for (int p = 0; p < 4 && g_running; p++) {
            safe_write(BUZZER_PIN, 1);
            gpioDelay(ERROR_BUZZER_PATTERN_US[p]);
            safe_write(BUZZER_PIN, 0);
        }
    }
    gpioTerminate();
    exit(1);
}

static int self_test(void) {
    log_event("Starting self-test...");
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) return -1;
        if (v == 0) {
            log_event("Self-test: flame detected on sample");
            return 0;
        }
        gpioDelay(SELF_TEST_INTERVAL_US);
    }
    log_event("Self-test: no flame detected on all samples");
    return 1;
}

static void cleanup(void) {
    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(FLAME_SENSOR_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(FLAME_SENSOR_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    if (self_test() != 1) {
        error_signal();
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_event("Warning: could not install SIGINT handler");
    }

    log_event("Entering main loop");
    while (g_running) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (v == 0) {
            log_event("Flame detected");
            safe_write(BUZZER_PIN, 1);
            safe_write(LED_PIN, 1);
            while (g_running) {
                int r = safe_read(FLAME_SENSOR_PIN);
                if (r < 0) {
                    gpioDelay(POLL_INTERVAL_US);
                    continue;
                }
                if (r == 1) {
                    log_event("Flame cleared");
                    safe_write(BUZZER_PIN, 0);
                    safe_write(LED_PIN, 0);
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
            }
        } else {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

