#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x29
#define BH1750_CONT_HRES_MODE 0x10
#define BH1750_RESET    0x07
#define BH1750_CONV_TIME_MS 180

#define LED_GPIO       17
#define BUFFER_SIZE    60
#define MAX_LUX        1000
#define MIN_FREQ_HZ    0.5
#define MAX_FREQ_HZ    5.0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_reset(int fd) {
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    usleep(10000);
    return 0;
}

static int bh1750_set_mode(int fd) {
    if (i2c_write_byte(fd, BH1750_CONT_HRES_MODE) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, int *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

static void add_to_buffer(int *buf, int size, int *idx, int value) {
    buf[*idx] = value;
    *idx = (*idx + 1) % size;
}

static double calculate_average(const int *buf, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) sum += buf[i];
    return sum / size;
}

