/*
 * 74HC595 shift register + common-cathode seven-segment display driver.
 *
 * Wiring (BCM numbering):
 *   GPIO17 <- 74HC595 DS  (serial data input)
 *   GPIO18 <- 74HC595 SHCP (clock)
 *   GPIO27 <- 74HC595 STCP (storage/latch)
 *   74HC595 Q0..Q7 -> segments a,b,c,d,e,f,g,dp (dp unused)
 *
 * Displays digit '5' and blinks it 500 ms on / 500 ms off.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seg7 seg7.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define BCM_DATA   17
#define BCM_CLOCK  18
#define BCM_LATCH  27

#define ON_MS     500
#define OFF_MS    500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Shift out one byte MSB-first.
 *   bit 0 -> Q0 (segment a)
 *   bit 1 -> Q1 (segment b)
 *   ...
 *   bit 7 -> Q7 (segment dp / unused)
 */
static void shift_out(struct gpiod_line *data, struct gpiod_line *clock,
                      struct gpiod_line *latch, unsigned char byte)
{
    for (int i = 7; i >= 0; i--) {
        int bit = (byte >> i) & 1;
        if (gpiod_line_set_value(data, bit) < 0) {
            perror("gpiod_line_set_value (data)");
            return;
        }
        if (gpiod_line_set_value(clock, 1) < 0) {
            perror("gpiod_line_set_value (clock high)");
            return;
        }
        usleep(1);                       /* >0 ns high pulse */
        if (gpiod_line_set_value(clock, 0) < 0) {
            perror("gpiod_line_set_value (clock low)");
            return;
        }
        usleep(1);
    }
    if (gpiod_line_set_value(latch, 1) < 0) {
        perror("gpiod_line_set_value (latch high)");
        return;
    }
    usleep(1);
    if (gpiod_line_set_value(latch, 0) < 0) {
        perror("gpiod_line_set_value (latch low)");
        return;
    }
    usleep(1);
}

/*
 * Common-cathode seven-segment display patterns:
 *   bit 0 = a, bit 1 = b, bit 2 = c, bit 3 = d,
 *   bit 4 = e, bit 5 = f, bit 6 = g, bit 7 = dp (unused)
 */
static const unsigned char digit_5 = 0x3D;   /* a b c d f g */

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *data = NULL, *clock = NULL, *latch = NULL;
    int ret = EXIT_FAILURE;

    /* --- signal handling for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- open default gpiochip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    data  = gpiod_chip_get_line(chip, BCM_DATA);
    clock = gpiod_chip_get_line(chip, BCM_CLOCK);
    latch = gpiod_chip_get_line(chip, BCM_LATCH);
    if (!data || !clock || !latch) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* --- request all three lines as outputs, initial value LOW --- */
    if (gpiod_line_request_output(data, "seg7-data", 0) < 0) {
        perror("gpiod_line_request_output(data)");
        goto cleanup;
    }
    if (gpiod_line_request_output(clock, "seg7-clock", 0) < 0) {
        perror("gpiod_line_request_output(clock)");
        goto cleanup;
    }
    if (gpiod_line_request_output(latch, "seg7-latch", 0) < 0) {
        perror("gpiod_line_request_output(latch)");
        goto cleanup;
    }

    /* --- blink '5' until interrupted --- */
    while (g_running) {
        shift_out(data, clock, latch, digit_5);
        usleep(ON_MS * 1000);
        if (!g_running) break;
        shift_out(data, clock, latch, 0x00);   /* all segments off */
        usleep(OFF_MS * 1000);
    }

    /* --- clean off state --- */
    shift_out(data, clock, latch, 0x00);
    ret = EXIT_SUCCESS;

cleanup:
    /* Lines are released automatically when the chip is closed,
     * but we turn them off explicitly for safety. */
    if (data)  gpiod_line_set_value(data, 0);
    if (clock) gpiod_line_set_value(clock, 0);
    if (latch) gpiod_line_set_value(latch, 0);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

