/*
 * blink_button.c — Blink GPIO17 (LED) with a 2 s period while waiting
 * for a falling-edge press on GPIO18 (button).  On detection the LED
 * is turned off and the program exits cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    sudo ./blink_button   (or ensure user is in the 'gpio' group)
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define PERIOD_MS  1000
#define POLL_MS    100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    struct gpiod_line *btn  = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean Ctrl-C exit --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip 0 (the main GPIO controller on Raspberry Pi) --- */
    chip = gpiod_chip_open_by_number(0);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_number(0)");
        return EXIT_FAILURE;
    }

    /* --- Get LED line (BCM 17) --- */
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (led == NULL) {
        perror("gpiod_chip_get_line(LED_PIN)");
        goto cleanup;
    }

    /* --- Get button line (BCM 18) --- */
    btn = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (btn == NULL) {
        perror("gpiod_chip_get_line(BUTTON_PIN)");
        goto cleanup;
    }

    /* --- Request LED as output, initial value LOW --- */
    if (gpiod_line_request_output(led, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* --- Request button as input with pull-up and falling-edge event detection --- */
    if (gpiod_line_request_falling_edge_events(btn, "blink_button") < 0) {
        perror("gpiod_line_request_falling_edge_events(BUTTON)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d (period %d ms). Press the button on GPIO%d to stop.\n",
           LED_PIN, PERIOD_MS, BUTTON_PIN);
    fflush(stdout);

    /* --- Main blink loop --- */
    while (g_running) {
        if (gpiod_line_set_value(led, 1) < 0) {
            perror("gpiod_line_set_value(LED, 1)");
            goto cleanup;
        }

        if (gpiod_line_set_value(led, 0) < 0) {
            perror("gpiod_line_set_value(LED, 0)");
            goto cleanup;
        }

        /*
         * Sleep for the blink period, but wake every POLL_MS so we can
         * respond promptly to SIGINT or a falling-edge event.
         */
        for (int ms = 0; ms < PERIOD_MS && g_running; ms += POLL_MS) {
            usleep(POLL_MS * 1000);
        }

        /*
         * Check for a falling-edge event.  gpiod_line_event_wait() returns
         * 1 if an event is available within the timeout, 0 if timeout, or < 0 on error.
         */
        int ev = gpiod_line_event_wait(btn, &(struct timespec){0, 0});
        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait(BUTTON)");
            goto cleanup;
        }
        if (ev == 1) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(btn, &event) < 0) {
                perror("gpiod_line_event_read(BUTTON)");
                goto cleanup;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed! Stopping.\n");
                fflush(stdout);
                break;
            }
        }
    }

    /* --- Graceful shutdown: LED off, release lines, close chip --- */
    if (gpiod_line_set_value(led, 0) < 0) {
        perror("gpiod_line_set_value(LED, 0) on exit");
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (led != NULL) {
        gpiod_line_release(led);
    }
    if (btn != NULL) {
        gpiod_line_release(btn);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

