#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH to GPIO%d.\n", LED_PIN);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);

        for (int i = 0; i < DELAY_MS && running; i++) {
            gpioDelay(1000);
        }

        if (!running) {
            break;
        }

        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO%d.\n", LED_PIN);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);

        for (int i = 0; i < DELAY_MS && running; i++) {
            gpioDelay(1000);
        }
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

