#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define BLINK_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED GPIO%d low.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LED control ready. Press the button (GPIO%d) to blink the LED (GPIO%d). Ctrl+C to exit.\n",
           BUTTON_PIN, LED_PIN);
    fflush(stdout);

    while (running) {
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state < 0) {
            fprintf(stderr, "Error: failed to read button GPIO%d (code %d).\n",
                    BUTTON_PIN, button_state);
            break;
        }

        if (button_state == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on (GPIO%d).\n", LED_PIN);
                break;
            }

            for (int i = 0; i < 10 && running; i++) {
                gpioDelay(BLINK_INTERVAL_US);
                if (gpioWrite(LED_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to turn LED off (GPIO%d).\n", LED_PIN);
                    break;
                }
                gpioDelay(BLINK_INTERVAL_US);
                if (gpioWrite(LED_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to turn LED on (GPIO%d).\n", LED_PIN);
                    break;
                }
            }

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off (GPIO%d).\n", LED_PIN);
                break;
            }
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off (GPIO%d).\n", LED_PIN);
                break;
            }
            gpioDelay(10000);  /* 10 ms idle poll to avoid busy-wait */
        }
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

