#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_FREQ_HZ  100
#define PWM_PERIOD_NS (1000000000L / PWM_FREQ_HZ)
#define PWM_HALF_NS   (PWM_PERIOD_NS / 2)

#define COLOR_CHANGE_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_gpio_write(int pin, int val)
{
    if (gpioWrite(pin, val) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, val);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(int pin, int mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %d) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static void sleep_ns(long ns)
{
    struct timespec req = { 0, ns };
    struct timespec rem;
    while (nanosleep(&req, &rem) == -1 && errno == EINTR) {
        req = rem;
    }
}

static void pwm_off(void)
{
    safe_gpio_write(RED_PIN, 0);
    safe_gpio_write(GREEN_PIN, 0);
    safe_gpio_write(BLUE_PIN, 0);
}

static void pwm_set(int r, int g, int b)
{
    if (r < 0) r = 0; if (r > 100) r = 100;
    if (g < 0) g = 0; if (g > 100) g = 100;
    if (b < 0) b = 0; if (b > 100) b = 100;

    long on_r = (long)r * PWM_HALF_NS / 100;
    long on_g = (long)g * PWM_HALF_NS / 100;
    long on_b = (long)b * PWM_HALF_NS / 100;

    safe_gpio_write(RED_PIN, 1);
    safe_gpio_write(GREEN_PIN, 1);
    safe_gpio_write(BLUE_PIN, 1);

    sleep_ns(on_r);
    safe_gpio_write(RED_PIN, 0);

    sleep_ns(on_g);
    safe_gpio_write(GREEN_PIN, 0);

    sleep_ns(on_b);
    safe_gpio_write(BLUE_PIN, 0);

    sleep_ns(PWM_PERIOD_NS - on_r - on_g - on_b);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (safe_gpio_set_mode(RED_PIN,  PI_OUTPUT) != 0 ||
        safe_gpio_set_mode(GREEN_PIN, PI_OUTPUT) != 0 ||
        safe_gpio_set_mode(BLUE_PIN,  PI_OUTPUT) != 0) {
        pwm_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        pwm_set(r, g, b);

        for (int i = 0; i < COLOR_CHANGE_MS && g_running; i++) {
            usleep(1000);
        }
    }

    pwm_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

