/*
 * LSM303DLHC impact monitor for Raspberry Pi Zero W
 *
 * Polls the accelerometer at 10 Hz, computes the total G-force magnitude,
 * and when it exceeds a configurable threshold, pulses GPIO17 HIGH for 50 ms
 * and logs the event to impact_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_monitor impact_monitor.c -lpigpio -lrt
 * Run:    sudo ./impact_monitor [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define LSM303_ADDR          0x19          /* DLHC default address (SA0 tied to GND) */

#define LSM303_WHO_AM_I      0x0F
#define LSM303_WHO_AM_I_VAL  0x49          /* DLHC accelerometer WHO_AM_I value */

#define LSM303_CTRL_REG1_A   0x20
#define LSM303_CTRL_REG4_A   0x23
#define LSM303_OUT_X_L_A     0x28
#define LSM303_OUT_X_H_A     0x29
#define LSM303_OUT_Y_L_A     0x2A
#define LSM303_OUT_Y_H_A     0x2B
#define LSM303_OUT_Z_L_A     0x2C
#define LSM303_OUT_Z_H_A     0x2D

#define ACCEL_SCALE          0.000244f     /* 1 mg/LSB at +/- 2 g full-scale */
#define SAMPLE_PERIOD_US     100000        /* 10 Hz */
#define IMPACT_PULSE_US      50000         /* 50 ms */
#define DEFAULT_THRESHOLD    2.0f
#define LOG_FILE             "impact_log.txt"
#define GPIO_PIN             17            /* BCM 17 */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_checked(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[I2C] write failed reg 0x%02X val 0x%02X\n", reg, val);
        return -1;
    }
    return 0;
}

static int i2c_read_block_checked(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[I2C] read failed reg 0x%02X (got %d, expected %u)\n",
                reg, n, len);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int init_lsm303(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, LSM303_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "[LSM303] WHO_AM_I read failed\n");
        return -1;
    }
    if (who != LSM303_WHO_AM_I_VAL) {
        fprintf(stderr, "[LSM303] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1_A: 0x57 -> 10 Hz, XYZ axes enabled */
    if (i2c_write_checked(handle, LSM303_CTRL_REG1_A, 0x57) < 0)
        return -1;

    /* CTRL_REG4_A: 0x00 -> +/- 2 g full-scale, continuous mode */
    if (i2c_write_checked(handle, LSM303_CTRL_REG4_A, 0x00) < 0)
        return -1;

    return 0;
}

