static int read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block_checked(handle, LSM303_OUT_X_L_A, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* --------------------------- Impact logic -------------------------------- */
static void impact_interrupt(float x, float y, float z, float threshold)
{
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > threshold) {
        printf("[Impact] G-force magnitude %.3f exceeds threshold %.2f\n",
               mag, threshold);

        if (gpioWrite(GPIO_PIN, 1) < 0)
            fprintf(stderr, "[GPIO] failed to set pin HIGH\n");

        gpioDelay(IMPACT_PULSE_US);

        if (gpioWrite(GPIO_PIN, 0) < 0)
            fprintf(stderr, "[GPIO] failed to set pin LOW\n");

        if (g_log_fp) {
