            char ts[64];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(g_log_fp, "%s,%.3f,%.3f,%.3f,%.3f\n",
                    ts, x, y, z, mag);
            fflush(g_log_fp);
        }
    }
}

