    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure GPIO is left in a safe state */
    gpioWrite(GPIO_PIN, 0);
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Invalid threshold '%s'. Using default %.2f\n",
                        argv[i], DEFAULT_THRESHOLD);
