#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[8];
    int bytes_read = i2cReadDevice(i2c_handle, buf, sizeof(buf));
    if (bytes_read != (int)sizeof(buf)) {
        fprintf(stderr, "I2C read error: expected %zu bytes, got %d (%s)\n",
                sizeof(buf), bytes_read, strerror(errno));
        return -1;
    }
    *als   = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static void set_led_brightness(uint16_t als_value) {
    int pwm_value = (int)(als_value / 65535.0 * PWM_RANGE);
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    if (pwm_value < 0) pwm_value = 0;
    gpioPWM(LED_GPIO, pwm_value);
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n",
            timestamp, als, red, green, blue);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    uint16_t als, red, green, blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d ms...\n",
                    RETRY_DELAY_US / 1000);
            gpioDelay(RETRY_DELAY_US);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

