    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d ms...\n",
                    RETRY_DELAY_US / 1000);
            gpioDelay(RETRY_DELAY_US);
