#include <pigpio.h>

/*
 * FXOS8700CQ 6-Axis Accelerometer/Magnetometer — Raspberry Pi Zero W
 * I2C bus 1, address 0x1E (SA0 tied to GND)
 *
 * Build:  gcc -O2 -Wall -o impact_detect impact_detect.c -lpigpio -lm
 * Run:    sudo ./impact_detect
