#define I2C_BUS        1
#define FXOS8700_ADDR  0x1E

/* FXOS8700CQ register addresses */
#define FXOS8700_REG_STATUS       0x00
#define FXOS8700_REG_OUT_X_MSB    0x01
#define FXOS8700_REG_WHO_AM_I     0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1    0x2A
#define FXOS8700_REG_CTRL_REG2    0x2B

#define FXOS8700_WHO_AM_I_VAL     0xC7

/* ±2 g range → 1 mg/LSB = 0.001 g/LSB */
#define ACCEL_SCALE 0.001f

#define IMPACT_THRESHOLD 1.5f   /* g */
#define SAMPLE_PERIOD_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an FXOS8700 register.                            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int fxos_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an FXOS8700 register.                            */
/* Returns the byte value (0–255) on success, -1 on error.            */
/* ------------------------------------------------------------------ */
static int fxos_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a block of N bytes starting at `reg` (auto-increment).         */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int fxos_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the device identity.                                        */
/* ------------------------------------------------------------------ */
static bool verify_device(void)
{
    int who = fxos_read_reg(FXOS8700_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return false;
