        fprintf(stderr,
                "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return false;
    }
    printf("[INFO] FXOS8700CQ detected (WHO_AM_I = 0x%02X).\n", who);
    return true;
}

/* ------------------------------------------------------------------ */
/* Configure the FXOS8700 for 200 Hz ODR, ±2 g range, active mode.     */
/* ------------------------------------------------------------------ */
static bool configure_sensor(void)
{
    /* Standby first so configuration changes take effect. */
    if (fxos_write_reg(FXOS8700_REG_CTRL_REG1, 0x00) < 0)
        return false;

    /* ±2 g range → 0x00 (default) */
    if (fxos_write_reg(FXOS8700_REG_XYZ_DATA_CFG, 0x00) < 0)
        return false;

    /* 200 Hz ODR (0x07) | active mode (bit 3 = 1) → 0x87 */
    if (fxos_write_reg(FXOS8700_REG_CTRL_REG1, 0x87) < 0)
        return false;

    /* CTRL_REG2: auto-increment for multi-byte reads (bit 0 = 1) */
    if (fxos_write_reg(FXOS8700_REG_CTRL_REG2, 0x01) < 0)
        return false;

    return true;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data (X, Y, Z) and convert to g.      */
/* ------------------------------------------------------------------ */
static int read_accel(float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (fxos_read_block(FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute acceleration magnitude.                                      */
/* ------------------------------------------------------------------ */
static float calc_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped impact event to the log file.                  */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float mag)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("[ERROR] fopen(impact_log.txt)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, mag);

    if (fclose(fp) != 0)
        perror("[WARN] fclose(impact_log.txt)");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus 1 at the FXOS8700 address --------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify device identity ------------------------------------ */
    if (!verify_device()) {
        fprintf(stderr, "[FATAL] FXOS8700CQ not detected. Exiting.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure sensor ------------------------------------------- */
    if (!configure_sensor()) {
        fprintf(stderr, "[FATAL] Sensor configuration failed. Exiting.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Monitoring for impacts (threshold %.2f g). Ctrl-C to exit.\n",
           IMPACT_THRESHOLD);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float x, y, z;

        if (read_accel(&x, &y, &z) < 0) {
            /* I2C read error: skip this sample, keep running. */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float mag = calc_magnitude(x, y, z);

        if (mag > IMPACT_THRESHOLD) {
            log_impact(x, y, z, mag);
            printf("[IMPACT] | x=%.3f y=%.3f z=%.3f | mag=%.3f g\n", x, y, z, mag);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- graceful shutdown ----------------------------------------- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

