#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 17

/* Threshold in g */
#define THRESHOLD_G 2.0f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345                                              */
/* ------------------------------------------------------------------ */
static bool adxl345_init(int handle)
{
    /* Verify device ID */
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register (I2C error %d)\n", devid);
        return false;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: unexpected DEVID value 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return false;
    }

    /* Standby mode to allow configuration changes */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set standby mode\n");
        return false;
    }

    /*
     * DATA_FORMAT (0x31):
     *   Bit 3 (FULL_RES) = 1  -> full resolution, 4-wire SPI half-resolution
     *   Bits 2:1 (RANGE)    = 00 -> +/- 2 g
     *   Bit 0 (BW_RATE)     = 0  -> 100 Hz output data rate
     * Value = 0x08
     */
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set data format\n");
        return false;
    }

    /* Enable measurement mode */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to enable measurement mode\n");
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (6 bytes starting at DATAX0)                  */
/* ------------------------------------------------------------------ */
static bool read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];

    /*
     * i2cReadI2CBlockData returns the number of bytes read, or a negative
     * error code on failure.  We need exactly 6 bytes for the 6-byte
     * acceleration block.
     */
    int bytes_read = i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (returned %d)\n", bytes_read);
        return false;
    }

    /*
     * Full-resolution mode, +/- 2 g range.
     * LSB = 1/256 g  =>  sensitivity = 4 mg/LSB = 0.004 g/LSB
     * Two's-complement, 16-bit signed.
     */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)(((uint16_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)(((uint16_t)buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;

    return true;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the file                                        */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Check threshold and drive the LED                                  */
/* ------------------------------------------------------------------ */
static void check_threshold(float x, float y, float z)
{
    bool exceed = (fabsf(x) > THRESHOLD_G) ||
                  (fabsf(y) > THRESHOLD_G) ||
                  (fabsf(z) > THRESHOLD_G);

    gpioWrite(LED_PIN, exceed ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADXL345 address */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the ADXL345 */
    if (!adxl345_init(g_i2c_handle)) {
        fprintf(stderr, "Error: ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file in append mode */
    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open accel_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write a header if the file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z)) {
            log_data(g_log_file, x, y, z);
            check_threshold(x, y, z);
        } else {
            /* On read failure, turn LED off and skip logging */
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

