#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDRESS 0x19
#define MAG_ADDRESS 0x1E

#define ACCEL_CTRL_REG1 0x20
#define ACCEL_CTRL_REG4 0x23
#define ACCEL_OUT_X_L 0x28

#define MAG_CRA 0x00
#define MAG_MR_REG 0x02
#define MAG_OUT_X_H 0x03

#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "compass_log.txt"

static volatile sig_atomic_t running = 1;
static int accel_handle = -1;
static int mag_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_accel(void) {
    accel_handle = i2cOpen(I2C_BUS, ACCEL_ADDRESS, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer (0x%02X): %d\n", ACCEL_ADDRESS, accel_handle);
        return -1;
    }
    if (i2cWriteByteData(accel_handle, ACCEL_CTRL_REG1, 0x27) < 0) {
        fprintf(stderr, "Error writing ACCEL_CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(accel_handle, ACCEL_CTRL_REG4, 0x0C) < 0) {
        fprintf(stderr, "Error writing ACCEL_CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int init_mag(void) {
    mag_handle = i2cOpen(I2C_BUS, MAG_ADDRESS, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer (0x%02X): %d\n", MAG_ADDRESS, mag_handle);
        return -1;
    }
    if (i2cWriteByteData(mag_handle, MAG_CRA, 0x00) < 0) {
        fprintf(stderr, "Error writing MAG_CRA\n");
        return -1;
    }
    if (i2cWriteByteData(mag_handle, MAG_MR_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing MAG_MR_REG\n");
        return -1;
    }
    return 0;
}

static int read_accel(float *ax, float *ay, float *az) {
    char buf[6];
    if (i2cReadI2CBlockData(accel_handle, ACCEL_OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *ax = (float)raw_x / 16384.0f;
    *ay = (float)raw_y / 16384.0f;
    *az = (float)raw_z / 16384.0f;
    return 0;
}

static int read_mag(float *mx, float *my, float *mz) {
    char buf[6];
    if (i2cReadI2CBlockData(mag_handle, MAG_OUT_X_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *mx = (float)raw_x / 1000.0f;
    *my = (float)raw_y / 1000.0f;
    *mz = (float)raw_z / 1000.0f;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float mx_comp = mx * cosf(pitch) + mz * sinf(pitch);
    float my_comp = mx * sinf(roll) * sinf(pitch) + my * cosf(roll) - mz * sinf(roll) * cosf(pitch);
    float heading = atan2f(my_comp, mx_comp) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n", timestamp, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_accel() != 0 || init_mag() != 0) {
        if (accel_handle >= 0) i2cClose(accel_handle);
        if (mag_handle >= 0) i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accel(&ax, &ay, &az) == 0 && read_mag(&mx, &my, &mz) == 0) {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    if (accel_handle >= 0) i2cClose(accel_handle);
    if (mag_handle >= 0) i2cClose(mag_handle);
    gpioTerminate();
    return 0;
}

