/*
 * VL6180X Time-of-Flight distance logger for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL6180X SDA -> GPIO2 (pin 3, I2C bus 1)
 *   VL6180X SCL -> GPIO3 (pin 5, I2C bus 1)
 *   VL6180X VDD -> 3.3 V
 *   VL6180X GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl6180x_log vl6180x_log.c -li2c -lm
 * Run:    sudo ./vl6180x_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL6180X_ADDR   0x29
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_MS      100
#define DOOR_THRESHOLD 100   /* mm */

/* VL6180X register addresses */
#define REG_IDENTIFICATION_MODEL_ID  0x000
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSRANGE_START          0x018
#define REG_RESULT_RANGE_VAL        0x062
#define REG_RESULT_INTERRUPT_STATUS 0x04F
#define REG_SYSTEM_INTERRUPT_CONFIG 0x014
#define REG_SYSTEM_INTERRUPT_CLEAR  0x015
#define REG_SYSTEM_FRESH_OUT_OF_RESET_GO 0x017

#define EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        val
    };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write8(0x%04X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read8(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t reg_buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "i2c_read8: write reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read8: read reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *val)
{
    uint8_t reg_buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    uint8_t data[2];
    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "i2c_read16: write reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read16: read reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL6180X initialization                                              */
/* ------------------------------------------------------------------ */
static int vl6180x_init(int fd)
{
    uint8_t model_id = 0;

    /* 1. Verify sensor identity */
    if (i2c_read8(fd, REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Cannot read model ID — sensor absent or bus error.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* 2. Software reset */
    if (i2c_write8(fd, REG_SYSTEM_FRESH_OUT_OF_RESET_GO, 0x00) != 0)
        return -1;
    if (i2c_write8(fd, 0x012, 0x01) != 0)
        return -1;
    usleep(10000); /* 10 ms */

    /* 3. Clear any pending interrupts */
    if (i2c_write8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x07) != 0)
        return -1;

    /* 4. Configure interrupt: new sample ready */
    if (i2c_write8(fd, REG_SYSTEM_INTERRUPT_CONFIG, 0x04) != 0)
        return -1;

    /* 5. Clear fresh-out-of-reset flag */
    if (i2c_write8(fd, REG_SYSTEM_FRESH_OUT_OF_RESET, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one range measurement                                         */
/* ------------------------------------------------------------------ */
static int vl6180x_read_range(int fd, uint16_t *distance_mm)
{
    uint8_t int_status = 0;
    uint16_t range = 0;

    /* 1. Start a single-shot range measurement */
    if (i2c_write8(fd, REG_SYSRANGE_START, 0x01) != 0)
        return -1;

    /* 2. Poll the interrupt status bit until data is ready */
    for (int i = 0; i < 50; i++) {
        if (i2c_read8(fd, REG_RESULT_INTERRUPT_STATUS, &int_status) != 0)
            return -1;
        if (int_status & 0x04)
            break;
        usleep(2000); /* 2 ms */
    }
    if (!(int_status & 0x04)) {
        fprintf(stderr, "Timeout waiting for range measurement.\n");
        return -1;
    }

    /* 3. Read the range value */
    if (i2c_read16(fd, REG_RESULT_RANGE_VAL, &range) != 0)
        return -1;

    /* 4. Clear the interrupt so the next measurement can trigger */
    if (i2c_write8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x07) != 0)
        return -1;

    *distance_mm = range;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Distance: %u mm\n", ts, distance_mm);
    fflush(fp);
}

static void log_door_status(FILE *fp, uint16_t distance_mm)
{
    if (distance_mm < DOOR_THRESHOLD)
        fprintf(fp, "DOOR_OPEN\n");
    else
        fprintf(fp, "DOOR_CLOSED\n");
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    uint16_t distance = 0;

    /* --- Signal handling --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL6180X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL6180X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (vl6180x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL6180X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL6180X initialized. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        if (vl6180x_read_range(g_i2c_fd, &distance) == 0) {
            log_data(g_log, distance);
            log_door_status(g_log, distance);
        } else {
            fprintf(stderr, "Read failed — attempting re-initialization.\n");
            if (vl6180x_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

