/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU Ultrasonic MEMS Microphone TDOA sampler
 *
 * Wiring:
 *   Sensor 1: I2C bus 1, address 0x48 (SA0 tied to GND)
 *   Sensor 2: I2C bus 1, address 0x49 (SA0 tied to VDD)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o audio_tdoa audio_tdoa.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./audio_tdoa
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x48
#define SENSOR2_ADDR   0x49
#define SAMPLE_INTERVAL_US 10000   /* 10 ms */
#define LOG_FILE       "audio_log.dat"

/* IMP23ABSU register addresses (16-bit big-endian, little-endian on wire) */
#define REG_DATA_L      0x00
#define REG_DATA_H      0x01
#define REG_CONFIG      0x02

/*
 * Configuration register (0x02):
 *   Bit 15    OS       = 1 (start one-shot conversion)
 *   Bit 14    PD       = 1 (power-down = 0 -> active)
 *   Bits 13:12 ODR[1:0] = 11 (1 kHz ODR)
 *   Bits 11:8  reserved
 *   Bits 7:4   reserved
 *   Bits 3:0   reserved
 * Value = 0x8003
 */
#define CONFIG_VALUE    0x8003

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static FILE *g_log_file    = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian sample from the IMP23ABSU.                 */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_sensor_sample(int handle, int16_t *out)
{
    int lo = i2cReadByteData(handle, REG_DATA_L);
    if (lo < 0)
        return -1;

    int hi = i2cReadByteData(handle, REG_DATA_H);
    if (hi < 0)
        return -1;

    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    /*
     * Write the configuration register to arm the sensor and set ODR.
     * i2cWriteWordData sends the 16-bit value as [reg, low_byte, high_byte]
     * on the wire, which matches the IMP23ABSU big-endian register layout.
     */
    if (i2cWriteWordData(handle, REG_CONFIG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error: failed to write config register (handle %d)\n",
                handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C handles ---- */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Error: cannot open I2C for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Error: cannot open I2C for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- sensor init ---- */
    if (init_sensor(g_i2c_handle1) < 0) {
        fprintf(stderr, "Error: sensor 1 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (init_sensor(g_i2c_handle2) < 0) {
        fprintf(stderr, "Error: sensor 2 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- write CSV header if file is empty ---- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(g_log_file);
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Sampling at %d Hz. Press Ctrl+C to stop.\n",
           1000000 / SAMPLE_INTERVAL_US);

    /* ---- main sampling loop ---- */
    while (g_running) {
        int16_t s1 = 0, s2 = 0;
        bool ok1 = (read_sensor_sample(g_i2c_handle1, &s1) == 0);
        bool ok2 = (read_sensor_sample(g_i2c_handle2, &s2) == 0);

        if (!ok1 || !ok2) {
            fprintf(stderr, "Warning: I2C read failure (s1=%d s2=%d) — skipping sample\n",
                    ok1, ok2);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        /* ---- timestamp ---- */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        /* ---- TDOA (simplified: s2 arrives later => positive TDOA) ---- */
        double tdoa = 0.0;
        if (s2 != 0) {
            tdoa = ((double)s1 / (double)s2) * 1e-6;  /* placeholder model */
        }

        /* ---- CSV line ---- */
        fprintf(g_log_file, "%ld,%ld,%d,%d,%.6f\n",
                (long)ts.tv_sec, (long)ts.tv_nsec, s1, s2, tdoa);
        fflush(g_log_file);

        usleep(SAMPLE_INTERVAL_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

