#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (7-bit) */
#define ADIS16488_REG_XGYRO_OUT  0x04
#define ADIS16488_REG_YGYRO_OUT  0x06
#define ADIS16488_REG_ZGYRO_OUT  0x08
#define ADIS16488_REG_XACCEL_OUT 0x0A
#define ADIS16488_REG_YACCEL_OUT 0x0C
#define ADIS16488_REG_ZACCEL_OUT 0x0E

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* Sensitivities (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* Stall time between read request and data transfer (microseconds) */
#define STALL_US 40

/* Sampling interval (milliseconds) */
#define SAMPLE_INTERVAL_MS 100

/* Global resources for cleanup */
static int spi_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer heavy cleanup to main()       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called by atexit()                                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                          */
/* Returns 0 on success, -1 on SPI error, -2 on invalid register.      */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg_addr, int16_t *out)
{
    if (out == NULL) {
        return -1;
    }

    /*
     * ADIS16488A SPI read: send 16-bit command word, then read 16-bit
     * data word.  The command word is 0x0000 | (reg_addr << 1), where
     * the MSB of the 8-bit address field is 0 (read).
     */
    char tx_cmd[2];
    char rx_cmd[2];
    char tx_data[2];
    char rx_data[2];

    tx_cmd[0] = 0x00;
    tx_cmd[1] = (char)(reg_addr << 1);

    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI transfer error during command phase (reg 0x%02X)\n", reg_addr);
        return -1;
    }

    /* Stall time between command and data transfer */
    gpioDelay(STALL_US);

    tx_data[0] = 0x00;
    tx_data[1] = 0x00;

    if (spiXfer(spi_handle, tx_data, rx_data, 2) != 2) {
        fprintf(stderr, "SPI transfer error during data phase (reg 0x%02X)\n", reg_addr);
        return -1;
    }

    /* ADIS16488A returns data MSB-first */
    *out = (int16_t)(((uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six sensor channels and convert to engineering units      */
/* ------------------------------------------------------------------ */
static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                          float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw_x, raw_y, raw_z;

    if (read_register(ADIS16488_REG_XGYRO_OUT, &raw_x) != 0) return -1;
    if (read_register(ADIS16488_REG_YGYRO_OUT, &raw_y) != 0) return -1;
    if (read_register(ADIS16488_REG_ZGYRO_OUT, &raw_z) != 0) return -1;
    if (read_register(ADIS16488_REG_XACCEL_OUT, &raw_x) != 0) return -1;
    if (read_register(ADIS16488_REG_YACCEL_OUT, &raw_y) != 0) return -1;
    if (read_register(ADIS16488_REG_ZACCEL_OUT, &raw_z) != 0) return -1;

    *gyro_x = (float)raw_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_z * ACCEL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample row to the CSV file                                   */
/* ------------------------------------------------------------------ */
static int log_data(float gyro_x, float gyro_y, float gyro_z,
                    float accel_x, float accel_y, float accel_z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(csv_file, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, ts.tv_nsec / 1000000L,
                gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(csv_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Non-blocking delay that checks the running flag every 1 ms          */
/* ------------------------------------------------------------------ */
static void delay_ms(int ms)
{
    int remaining = ms;
    while (remaining > 0 && running) {
        int chunk = (remaining > 100) ? 100 : remaining;
        gpioDelay(chunk * 1000); /* microseconds */
        remaining -= chunk;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    csv_file = fopen("imu_data.csv", "a");
    if (csv_file == NULL) {
        perror("fopen imu_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(csv_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register cleanup for normal exit paths */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit registration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "IMU read failed; skipping sample\n");
        } else {
            if (log_data(gyro_x, gyro_y, gyro_z,
                         accel_x, accel_y, accel_z) != 0) {
                fprintf(stderr, "CSV write failed; aborting\n");
                break;
            }
        }

        delay_ms(SAMPLE_INTERVAL_MS);
    }

    printf("\nShutting down gracefully...\n");
    return EXIT_SUCCESS;
}

