#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ADIS16448 Register Addresses */
#define ADIS16448_REG_GLOB_CMD      0x02
#define ADIS16448_REG_SMPL_PRD      0x36
#define ADIS16448_REG_SENS_AVG      0x3A
#define ADIS16448_REG_GYRO_XOUT_H   0x1F
#define ADIS16448_REG_GYRO_XOUT_L   0x20
#define ADIS16448_REG_GYRO_YOUT_H   0x22
#define ADIS16448_REG_GYRO_YOUT_L   0x23
#define ADIS16448_REG_GYRO_ZOUT_H   0x24
#define ADIS16448_REG_GYRO_ZOUT_L   0x25
#define ADIS16448_REG_ACCL_XOUT_H   0x28
#define ADIS16448_REG_ACCL_XOUT_L   0x29
#define ADIS16448_REG_ACCL_YOUT_H   0x2A
#define ADIS16448_REG_ACCL_YOUT_L   0x2B
#define ADIS16448_REG_ACCL_ZOUT_H   0x2C
#define ADIS16448_REG_ACCL_ZOUT_L   0x2D

/* SPI Configuration */
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE   SPI_MODE_3
#define SPI_BITS   8
#define SPI_SPEED  1000000  /* 1 MHz */

/* ADIS16448 Scale Factors */
#define GYRO_SCALE 0.02f   /* dps/LSB */
#define ACCEL_SCALE 0.00025f /* g/LSB */

/* Global variables for cleanup */
static int spi_fd = -1;
static int spi_driver_fd = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Function to initialize the SPI interface */
static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    /* Set SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    /* Set bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    /* Set max speed */
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

/* Function to read a single register from the ADIS16448 */
static int read_register(uint8_t reg_addr, uint8_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    /* ADIS16448 single register read: send 8-bit address with bit 7 set, then dummy byte */
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

/* Function to write a single register to the ADIS16448 */
static int write_register(uint8_t reg_addr, uint8_t data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    /* ADIS16448 single register write: send 8-bit address without bit 7 set, then data byte */
    tx_buf[0] = reg_addr & 0x7F;
    tx_buf[1] = data;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }

    return 0;
}

/* Function to read a 16-bit register pair (e.g., gyroscope or accelerometer) */
static int read_register_16(uint8_t reg_addr_h, uint16_t *data) {
    uint8_t high, low;

    if (read_register(reg_addr_h, &high) < 0) return -1;
    if (read_register(reg_addr_h + 1, &low) < 0) return -1;

    *data = ((uint16_t)high << 8) | low;
    return 0;
}

/* Function to read gyroscope data */
static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    if (read_register_16(ADIS16448_REG_GYRO_XOUT_H, &raw_gyro_x) < 0) return -1;
    if (read_register_16(ADIS16448_REG_GYRO_YOUT_H, &raw_gyro_y) < 0) return -1;
    if (read_register_16(ADIS16448_REG_GYRO_ZOUT_H, &raw_gyro_z) < 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;

    return 0;
}

/* Function to read accelerometer data */
static int read_accel_data(float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register_16(ADIS16448_REG_ACCL_XOUT_H, &raw_accel_x) < 0) return -1;
    if (read_register_16(ADIS16448_REG_ACCL_YOUT_H, &raw_accel_y) < 0) return -1;
    if (read_register_16(ADIS16448_REG_ACCL_ZOUT_H, &raw_accel_z) < 0) return -1;

    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
