static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    /* Set SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    /* Set bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    /* Set max speed */
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

/* Function to read a single register from the ADIS16448 */
static int read_register(uint8_t reg_addr, uint8_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    /* ADIS16448 single register read: send 8-bit address with bit 7 set, then dummy byte */
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

/* Function to write a single register to the ADIS16448 */
static int write_register(uint8_t reg_addr, uint8_t data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    /* ADIS16448 single register write: send 8-bit address without bit 7 set, then data byte */
    tx_buf[0] = reg_addr & 0x7F;
    tx_buf[1] = data;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
