/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16448 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 * Run:    sudo ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 constants (per datasheet) ---- */
#define ADIS16448_REG_XGYRO_OUT   0x04
#define ADIS16448_REG_YGYRO_OUT   0x06
#define ADIS16448_REG_ZGYRO_OUT   0x08
#define ADIS16448_REG_XACCL_OUT  0x0A
#define ADIS16448_REG_YACCL_OUT  0x0C
#define ADIS16448_REG_ZACCL_OUT  0x0E

#define ADIS16448_GYRO_LSB       0.05f   /* deg/sec per LSB  */
#define ADIS16448_ACCL_LSB       0.00025f /* g per LSB        */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz */
#define SPI_FLAGS   0                /* Mode 0, active-low CE */

#define SAMPLE_PERIOD_US 100000      /* 100 ms */
#define STALL_US         40           /* >= 40 us per datasheet */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read one 16-bit register from the ADIS16448.
 *
 * The ADIS16448 SPI interface requires a two-transfer cycle:
 *   Transfer 1: send [cmd | 0x8000] (bit 15 = 1 for read)
 *   Transfer 2: send dummy 0xFFFF to clock out the 16-bit data word.
 *
 * Returns 0 on success and stores the raw 16-bit value in *out.
 * Returns -1 on SPI transfer failure.
 */
static int adis16448_read_reg(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  ret;

    /* ---- Transfer 1: send read command ---- */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer 1 failed (reg 0x%02X, ret=%d)\n", reg, ret);
        return -1;
    }

    /* ---- Stall time (>= 40 us) ---- */
    gpioDelay(STALL_US);

    /* ---- Transfer 2: dummy to clock out data ---- */
    tx[0] = 0x00;
    tx[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer 2 failed (reg 0x%02X, ret=%d)\n", reg, ret);
        return -1;
    }

    /* rx[0] is the high byte, rx[1] is the low byte (MSB first) */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_xyz(float *gx, float *gy, float *gz)
{
    int16_t raw;

    if (adis16448_read_reg(ADIS16448_REG_XGYRO_OUT, &raw) != 0) return -1;
    *gx = (float)raw * ADIS16448_GYRO_LSB;

    if (adis16448_read_reg(ADIS16448_REG_YGYRO_OUT, &raw) != 0) return -1;
    *gy = (float)raw * ADIS16448_GYRO_LSB;

    if (adis16448_read_reg(ADIS16448_REG_ZGYRO_OUT, &raw) != 0) return -1;
    *gz = (float)raw * ADIS16448_GYRO_LSB;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel_xyz(float *ax, float *ay, float *az)
{
    int16_t raw;

    if (adis16448_read_reg(ADIS16448_REG_XACCL_OUT, &raw) != 0) return -1;
    *ax = (float)raw * ADIS16448_ACCL_LSB;

    if (adis16448_read_reg(ADIS16448_REG_YACCL_OUT, &raw) != 0) return -1;
    *ay = (float)raw * ADIS16448_ACCL_LSB;

    if (adis16448_read_reg(ADIS16448_REG_ZACCL_OUT, &raw) != 0) return -1;
    *az = (float)raw * ADIS16448_ACCL_LSB;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float gx, gy, gz, ax, ay, az;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI0 CE0 at 1 MHz, Mode 0 ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (read_gyro_xyz(&gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
        } else if (read_accel_xyz(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accel read error; continuing\n");
        } else {
            printf("Gyro: X=%.3f Y=%.3f Z=%.3f deg/s  |  Accel: X=%.3f Y=%.3f Z=%.3f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        /* Sleep 100 ms (interruptible by signals) */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

