        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float gx, gy, gz, ax, ay, az;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI0 CE0 at 1 MHz, Mode 0 ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (read_gyro_xyz(&gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
        } else if (read_accel_xyz(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accel read error; continuing\n");
        } else {
            printf("Gyro: X=%.3f Y=%.3f Z=%.3f deg/s  |  Accel: X=%.3f Y=%.3f Z=%.3f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        /* Sleep 100 ms (interruptible by signals) */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

