/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Wiring: VCC -> 3.3V, GND -> GND, SCL -> GPIO3, SDA -> GPIO2
 *
 * Build: gcc -O2 -Wall -o mpu6886 mpu6886.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6886 register definitions ---- */
#define MPU6886_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define ACCEL_XOUT_H        0x3B
#define GYRO_XOUT_H         0x43

#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_PERIOD_US    50000   /* 50 ms */
#define MAX_RETRIES         3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): write returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_burst(0x%02X): write returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst(0x%02X): read returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor data structure ---- */
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x,  gyro_y,  gyro_z;
} sensor_data_t;

/* ---- Read with retry ---- */
static int read_sensor_data(int fd, sensor_data_t *out)
{
    uint8_t raw[14];

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (i2c_read_burst(fd, ACCEL_XOUT_H, raw, sizeof(raw)) == 0) {
            out->accel_x = (int16_t)((raw[0]  << 8) | raw[1]);
            out->accel_y = (int16_t)((raw[2]  << 8) | raw[3]);
            out->accel_z = (int16_t)((raw[4]  << 8) | raw[5]);
            /* raw[6..7] = temperature (skipped) */
            out->gyro_x  = (int16_t)((raw[8]  << 8) | raw[9]);
            out->gyro_y  = (int16_t)((raw[10] << 8) | raw[11]);
            out->gyro_z  = (int16_t)((raw[12] << 8) | raw[13]);
            return 0;
        }
        if (attempt < MAX_RETRIES)
            usleep(1000);
    }
    return -1;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6886_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    /* Wake up the MPU-6886 (clear SLEEP bit) */
    if (i2c_write_reg8(g_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6886 (sensor absent or bus error)\n");
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }
    usleep(100000); /* allow oscillator to stabilise */

    printf("MPU-6886 ready on %s (addr 0x%02X). Press Ctrl-C to stop.\n",
           I2C_BUS, MPU6886_ADDR);

    while (g_running) {
        sensor_data_t data;
        if (read_sensor_data(g_fd, &data) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   data.accel_x, data.accel_y, data.accel_z,
                   data.gyro_x,  data.gyro_y,  data.gyro_z);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; continuing.\n",
                    MAX_RETRIES);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return EXIT_SUCCESS;
}

