        fprintf(stderr, "I2C read failed: %s (reg=0x%02X, expected %zu bytes)\n", desc, reg, len);
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: %s (reg=0x%02X, got %d, expected %zu)\n", desc, reg, n, len);
        return -1;
    }
    return 0;
}

/* ---- ADXL345 initialization ---- */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_checked(handle, ADXL345_REG_DEVID, &devid, 1, "DEVID") < 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not detected: DEVID=0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby -> enter configuration */
    if (i2c_write_checked(handle, ADXL345_REG_POWER_CTL, 0x00, "POWER_CTL standby") < 0)
        return -1;

    /* Full resolution, ±2 g, right-justified, all axes enabled */
    if (i2c_write_checked(handle, ADXL345_REG_DATA_FORMAT, 0x0B, "DATA_FORMAT") < 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_checked(handle, ADXL345_REG_POWER_CTL, 0x08, "POWER_CTL measure") < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration (g) ---- */
static int adxl345_read_g(int handle, float *xg, float *yg, float *zg)
{
    uint8_t raw[6];
    int16_t x, y, z;

    if (i2c_read_checked(handle, ADXL345_REG_DATAX0, raw, 6, "accel data") < 0)
        return -1;

    x = (int16_t)((raw[1] << 8) | raw[0]);
    y = (int16_t)((raw[3] << 8) | raw[2]);
    z = (int16_t)((raw[5] << 8) | raw[4]);

    *xg = (float)x / SCALE_FACTOR_2G;
    *yg = (float)y / SCALE_FACTOR_2G;
    *zg = (float)z / SCALE_FACTOR_2G;
    return 0;
}

/* ---- Impact detection ---- */
static bool detect_impact(float xg, float yg, float zg, float threshold)
{
    float mag = sqrtf(xg * xg + yg * yg + zg * zg);
    return (mag > threshold);
}

/* ---- Log impact event ---- */
static void log_impact(float xg, float yg, float zg, float mag)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s, X=%.3f g, Y=%.3f g, Z=%.3f g, Mag=%.3f g\n",
            ts, xg, yg, zg, mag);
    fflush(g_log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cWriteByteData(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x00); /* standby */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    float xg, yg, zg;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 impact detector running. Threshold: %.1f g\n", IMPACT_THRESHOLD_G);
    printf("Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        if (adxl345_read_g(g_i2c_handle, &xg, &yg, &zg) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (detect_impact(xg, yg, zg, IMPACT_THRESHOLD_G)) {
            float mag = sqrtf(xg * xg + yg * yg + zg * zg);
            log_impact(xg, yg, zg, mag);
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DURATION_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

