#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ICM-20602 register addresses */
#define ICM20602_REG_PWR_MGMT_1   0x6B
#define ICM20602_REG_ACCEL_XOUT_H 0x3B
#define ICM20602_REG_GYRO_XOUT_H  0x43

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1
#define I2C_ADDR 0x69

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to initialize the ICM-20602 */
static int init_icm20602(int handle) {
    /* Wake up the device: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, ICM20602_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Function to read accelerometer data */
static int read_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ICM20602_REG_ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to read gyroscope data */
static int read_gyro(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ICM20602_REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to log data to a CSV file */
static int log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                    int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec,
                ax, ay, az, gx, gy, gz) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ICM-20602 */
    if (init_icm20602(i2c_handle) < 0) {
        fprintf(stderr, "ICM-20602 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging IMU data to imu_log.csv. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (program_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_accel(i2c_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        } else if (read_gyro(i2c_handle, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
        } else {
            if (log_data(log_file, ax, ay, az, gx, gy, gz) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz) */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

