#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* MMA8451Q Register Addresses */
#define MMA8451_ADDR          0x1D
#define MMA8451_REG_STATUS    0x00
#define MMA8451_REG_OUT_X_MSB 0x01
#define MMA8451_REG_OUT_X_LSB 0x02
#define MMA8451_REG_OUT_Y_MSB 0x03
#define MMA8451_REG_OUT_Y_LSB 0x04
#define MMA8451_REG_OUT_Z_MSB 0x05
#define MMA8451_REG_OUT_Z_LSB 0x06
#define MMA8451_REG_CTRL_REG1 0x2A
#define MMA8451_REG_CTRL_REG2 0x2B
#define MMA8451_REG_ID        0x0D

/* Expected Device ID */
#define MMA8451_ID            0x0A

/* Configuration */
#define I2C_BUS               1
#define LED_GPIO              17
#define ACCEL_THRESHOLD       2.0f   /* g */
#define POLL_DELAY_US         100000 /* 100 ms */
#define LED_ON_DELAY_US       500000 /* 500 ms */
#define G_PER_COUNT           1024.0f /* ±2 g range */

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a single byte register                                             */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte register                                             */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    return i2cWriteByteData(handle, reg, value);
}

/* ------------------------------------------------------------------ */
/* Initialize the MMA8451Q                                               */
/* ------------------------------------------------------------------ */
static int init_mma8451(int handle)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (read_register(handle, MMA8451_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: failed to read ID register\n");
        return -1;
    }
    if (id != MMA8451_ID) {
        fprintf(stderr, "Error: unexpected device ID 0x%02X (expected 0x%02X)\n",
                id, MMA8451_ID);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (write_register(handle, MMA8451_REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set standby mode\n");
        return -1;
    }

    /* ±2 g range, 800 Hz ODR (0x08) */
    if (write_register(handle, MMA8451_REG_CTRL_REG1, 0x08) < 0) {
        fprintf(stderr, "Error: failed to set ODR/range\n");
        return -1;
    }

    /* Enable all axes (XYZ) */
    if (write_register(handle, MMA8451_REG_CTRL_REG2, 0x07) < 0) {
        fprintf(stderr, "Error: failed to enable axes\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (6 bytes)                                      */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2cReadI2CBlockData(handle, MMA8451_REG_OUT_X_MSB, (char *)buf, 6) != 6) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / G_PER_COUNT;
    *y = (float)raw_y / G_PER_COUNT;
    *z = (float)raw_z / G_PER_COUNT;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Check if any axis exceeds the threshold                               */
/* ------------------------------------------------------------------ */
static bool check_threshold(float x, float y, float z, float threshold)
{
    return (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold);
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MMA8451_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, MMA8451_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mma8451(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MMA8451 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
