static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *value)
{
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, reg, &msb) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &lsb) < 0)
        return -1;
    *value = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int init_tmag5273(int fd)
{
    /* Device Configuration register: default 0x00 (continuous conversion, 100 Hz ODR) */
    if (i2c_write_reg8(fd, REG_DEVICE_CONFIG, 0x00) < 0)
        return -1;
    return 0;
}

static int read_tmag5273(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_X_MSB, x) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_MSB, y) < 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_MSB, z) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", TMAG5273_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_tmag5273(g_i2c_fd) < 0) {
        fprintf(stderr, "TMAG5273 initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending; create header if new */
    g_csv = fopen(CSV_FILE, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    fseek(g_csv, 0, SEEK_END);
    long fsize = ftell(g_csv);
    if (fsize == 0) {
        if (fprintf(g_csv, "Timestamp,X,Y,Z\n") < 0 || fflush(g_csv) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(g_csv);
            g_csv = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
    }

