        if (read_tmag5273(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_csv, x, y, z);
        } else {
            fprintf(stderr, "Failed to read magnetic field data\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_DELAY_S * 10 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
