/*
 * ADXL345 Free-Fall Detector with Timestamped Logging
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1  (ADXL345 SA0 tied to GND -> 0x53)
 * INT1:   GPIO17 (BCM 17, physical pin 11)
 *
 * Build:  gcc -O2 -Wall -Wextra -o freefall_detect freefall_detect.c -li2c -lpigpio -lrt
 * Run:    sudo ./freefall_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDRESS 0x53
#define ADXL345_DEV_ID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_INT_SOURCE 0x30

#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_BW_RATE_100HZ 0x0A
#define ADXL345_INT_FREEFALL 0x04
#define ADXL345_INT_MAP_INT1_FF 0x04

/* ---- GPIO / I2C ---- */
#define I2C_BUS "/dev/i2c-1"
#define GPIO_INT1 17
#define LOG_FILE "freefall_log.csv"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_fd = -1;
static FILE *g_log = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 init ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEV_ID, &devid) != 0)
        return -1;
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby mode before configuration */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: +/-2g, full resolution, right-justified */
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Bandwidth rate 100 Hz */
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, ADXL345_BW_RATE_100HZ) != 0)
        return -1;

    /* Free-fall interrupt on INT1 */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, ADXL345_INT_FREEFALL) != 0)
        return -1;

    /* Map free-fall interrupt to INT1 */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, ADXL345_INT_MAP_INT1_FF) != 0)
        return -1;

    /* Clear any latched interrupts */
    uint8_t int_src = 0;
    if (i2c_read_reg8(fd, ADXL345_INT_SOURCE, &int_src) != 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ---- Read 6 bytes of acceleration ---- */
static int adxl345_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_DATAX0, buf, 6) != 0)
        return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

/* ---- Log one sample ---- */
static void log_sample(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable interrupts and set standby */
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_INT_ENABLE, 0x00);
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_gpio_fd >= 0) {
        gpioSetAlertFuncEx(GPIO_INT1, NULL, NULL);
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "w");
    if (!g_log) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log, "Timestamp,X,Y,Z\n");
    fflush(g_log);

    /* Configure GPIO17 as input with pull-up (INT1 is open-drain) */
    gpioSetMode(GPIO_INT1, PI_INPUT);
    gpioSetPullUpDown(GPIO_INT1, PI_PUD_UP);

    /* Register alert callback (edge-triggered) */
    g_gpio_fd = gpioSetAlertFuncEx(GPIO_INT1, NULL, NULL);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Failed to set GPIO alert on pin %d: %s\n",
                GPIO_INT1, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* Main poll loop */
    while (g_running) {
        fd_set rfds;
        struct timeval tv;
        FD_ZERO(&rfds);
        FD_SET(g_gpio_fd, &rfds);
        tv.tv_sec = 1;
        tv.tv_usec = 0;

        int ret = select(g_gpio_fd + 1, &rfds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0)
            continue;  /* timeout, loop back */

        /* Handle alert */
        int level = gpioRead(GPIO_INT1);
        if (level == 0) {  /* falling edge = free-fall detected */
            int16_t x, y, z;
            if (adxl345_read_accel(g_i2c_fd, &x, &y, &z) == 0) {
                char ts[32];
                get_timestamp(ts, sizeof(ts));
                log_sample(g_log, ts, x, y, z);
                printf("Free-fall detected: %s, X=%d, Y=%d, Z=%d\n",
                       ts, x, y, z);
            } else {
                fprintf(stderr, "Failed to read acceleration data\n");
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

