/*
 * LSM6DSR IMU Fall Detection Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA  -> GPIO2 (I2C bus 1 SDA)
 *   LSM6DSR SCL  -> GPIO3 (I2C bus 1 SCL)
 *   LSM6DSR VDD  -> 3.3 V
 *   LSM6DSR GND  -> GND
 *
 * Build: gcc -O2 -Wall -o lsm6dsr_fall lsm6dsr_fall.c -lm
 * Run:   sudo ./lsm6dsr_fall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- LSM6DSR I2C / register definitions ---- */
#define I2C_BUS        1
#define LSM6DSR_ADDR   0x6A

#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0x67

#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_H_G       0x23
#define OUTY_L_G       0x24
#define OUTY_H_G       0x25
#define OUTZ_L_G       0x26
#define OUTZ_H_G       0x27
#define OUTX_L_XL      0x28
#define OUTX_H_XL      0x29
#define OUTY_L_XL      0x2A
#define OUTY_H_XL      0x2B
#define OUTZ_L_XL      0x2C
#define OUTZ_H_XL      0x2D

#define ACCEL_SENSITIVITY 0.061e-3f   /* +/- 2 g range -> 61 mg/LSB */
#define GYRO_SENSITIVITY  8.75e-6f    /* +/- 250 dps range -> 8.75 mdps/LSB */

#define SAMPLE_PERIOD_US 9615        /* ~104 Hz */
#define FALL_WINDOW_S   1.0f
#define FREEFALL_THRESH  0.2f        /* g */
#define IMPACT_THRESH    2.5f        /* g */

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} FallState;

static FallState fall_state = IDLE;
static time_t freefall_start = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(void)
{
    uint8_t who_am_i = 0;
    if (i2c_read_burst(WHO_AM_I_REG, &who_am_i, 1) != 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* ODR = 104 Hz, FS_XL = +/- 2 g */
    if (i2c_write_reg(CTRL1_XL, 0x40) != 0)
        return -1;
    /* ODR = 104 Hz, FS_G = +/- 250 dps */
    if (i2c_write_reg(CTRL2_G, 0x40) != 0)
        return -1;

    return 0;
}

/* ---- Data read ---- */
static int read_sensor_data(float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz)
{
    uint8_t buf[12];
    if (i2c_read_burst(OUTX_L_G, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;
    return 0;
}

/* ---- Logging ---- */
static void log_data(float ax, float ay, float az,
                     float gx, float gy, float gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%03ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, ts.tv_nsec / 1000000L,
            ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

/* ---- Fall detection ---- */
static void detect_fall(float ax, float ay, float az)
{
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    switch (fall_state) {
    case IDLE:
        if (mag < FREEFALL_THRESH) {
            freefall_start = time(NULL);
            fall_state = FREEFALL;
        }
        break;
    case FREEFALL:
        if (mag > IMPACT_THRESH) {
            fall_state = IMPACT;
            printf("[FALL DETECTED] Impact detected after %.1f s of freefall.\n",
                   (double)(time(NULL) - freefall_start));
        } else if ((time(NULL) - freefall_start) * 1.0 >= FALL_WINDOW_S) {
            fall_state = IDLE;
            printf("[FALL DETECTED] Freefall timeout (%.1f s).\n",
                   (double)FALL_WINDOW_S);
        }
        break;
    case IMPACT:
        fall_state = IDLE;
        break;
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, LSM6DSR_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
