        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "# LSM6DSR Fall Detection Log - started\n");
    fprintf(log_file, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps\n");
    fflush(log_file);

    printf("LSM6DSR initialised. Logging to motion_log.txt (Ctrl+C to stop).\n");

