#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND on GY-50 breakout) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28
#define OUT_X_H    0x29
#define OUT_Y_L    0x2A
#define OUT_Y_H    0x2B
#define OUT_Z_L    0x2C
#define OUT_Z_H    0x2D

/* Expected device ID */
#define WHO_AM_I_EXPECTED 0xD3

/* Sensitivity scale factor: 8.75 mdps/LSB => 1/114.285 */
#define GYRO_SCALE (1.0 / 114.285)

#define I2C_BUS 1
#define SAMPLE_US 10000  /* 10 ms */
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register; returns 0 on success, -1 on failure. */
static int gyro_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write to register 0x%02X failed.\n", reg);
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register; returns 0 on success, -1 on failure. */
static int gyro_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select) for register 0x%02X failed.\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error: I2C read from register 0x%02X failed.\n", reg);
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

/* Initialize the L3G4200D: verify device ID, set sample rate, enable axes. */
static int gyro_init(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (gyro_read_reg(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, WHO_AM_I_EXPECTED);
        return -1;
    }

    /*
     * CTRL_REG1: 0x20 = 0x0F  -> 100 Hz ODR, normal mode, all axes enabled
     * CTRL_REG4: 0x23 = 0x08  -> +/- 245 dps full-scale, little-endian
     */
    if (gyro_write_reg(handle, CTRL_REG1, 0x0F) != 0) return -1;
    if (gyro_write_reg(handle, CTRL_REG4, 0x08) != 0) return -1;

    return 0;
}

/* Read all six raw gyroscope bytes; returns 0 on success, -1 on failure. */
static int gyro_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char reg_buf[1] = { (char)OUT_X_L };
    char data[6];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select) for OUT_X_L failed.\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 6) != 6) {
        fprintf(stderr, "Error: I2C read of 6-byte gyro block failed.\n");
        return -1;
    }

    *x = (int16_t)(((uint8_t)data[1] << 8) | (uint8_t)data[0]);
    *y = (int16_t)(((uint8_t)data[3] << 8) | (uint8_t)data[2]);
    *z = (int16_t)(((uint8_t)data[5] << 8) | (uint8_t)data[4]);
    return 0;
}

/* Append a timestamped record to the CSV log. */
static int log_data(FILE *fp, double x, double y, double z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%09ld,%.6f,%.6f,%.6f\n",
                timestamp, ts.tv_nsec, x, y, z) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the GY-50 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope with retry */
    int init_ok = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (gyro_init(g_i2c_handle) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Warning: gyro_init attempt %d/%d failed.\n",
                attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    if (!init_ok) {
        fprintf(stderr, "Error: Gyroscope initialization failed after %d attempts.\n",
                MAX_RETRIES);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the CSV log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening gyro_log.csv");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if the file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (gyro_read_raw(g_i2c_handle, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Warning: gyro_read_raw failed, retrying in 10 ms.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double x = (double)raw_x * GYRO_SCALE;
        double y = (double)raw_y * GYRO_SCALE;
        double z = (double)raw_z * GYRO_SCALE;

        if (log_data(g_log_file, x, y, z) != 0) {
            fprintf(stderr, "Warning: log_data failed, continuing.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Gyroscope logging stopped.\n");
    return EXIT_SUCCESS;
}

