#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17          /* BCM 17, physical pin 11 */
#define LOG_FILE_NAME      "flame_events.log"
#define POLL_INTERVAL_US   500000      /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly.              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file and flush immediately.    */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (g_log_fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s – %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor.  Returns 1 (flame), 0 (no flame), or -1 on   */
/* error.  The KY-026 DO is active-LOW: LOW = flame detected.           */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level == PI_BAD_GPIO) {
        fprintf(stderr, "gpioRead() failed on GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so the line is defined when the sensor   */
    /* module is disconnected or its output is open-collector.          */
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d.  Press Ctrl-C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int flame = read_flame_sensor();

        if (flame == 1) {
            printf("FLAME DETECTED!\n");
            if (log_event("Flame detected: YES") != 0) {
                fprintf(stderr, "Failed to log flame event\n");
            }
        } else if (flame == 0) {
            if (log_event("Flame detected: NO") != 0) {
                fprintf(stderr, "Failed to log no-flame event\n");
            }
        } else {
            /* read_flame_sensor() returned -1 – treat as error */
            if (log_event("ERROR: sensor read failed") != 0) {
                fprintf(stderr, "Failed to log sensor error\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

