static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read 6 bytes of acceleration data from the D7S-0001.
 * Returns 0 on success, -1 on I2C error, -2 on sensor-absent /
 * unexpected data pattern.
 */
static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[SENSOR_BYTES];

    ssize_t n = read(fd, buf, SENSOR_BYTES);
    if (n != SENSOR_BYTES) {
        if (n < 0)
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C short read: got %zd of %d bytes\n", n, SENSOR_BYTES);
        return -1;
    }

    /*
     * D7S-0001 acceleration data is little-endian 16-bit per axis.
     * Byte 0-1 = X, Byte 2-3 = Y, Byte 4-5 = Z.
     */
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    /*
     * Sensor-absent / bus-error pattern: all bytes = 0xFF.
     * (Omron D7S-0001 returns 0xFF when the sensor is disconnected
     * or the bus is not responding.)
     */
    if (buf[0] == ERROR_VALUE && buf[1] == ERROR_VALUE &&
        buf[2] == ERROR_VALUE && buf[3] == ERROR_VALUE &&
        buf[4] == ERROR_VALUE && buf[5] == ERROR_VALUE) {
        fprintf(stderr, "Sensor absent or bus error (0xFF pattern)\n");
        return -2;
    }

    return 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire exclusive access to the sensor device */
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open CSV file for appending */
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

    printf("Logging vibration data to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        int ret = read_sensor_data(fd, &x, &y, &z);
        if (ret == 0) {
            get_iso8601_timestamp(ts, sizeof(ts));
            if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
                fprintf(stderr, "Failed to write CSV row: %s\n", strerror(errno));
                goto cleanup;
            }
            if (fflush(fp) != 0)
                fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        } else if (ret == -1) {
            /* I2C bus error — skip this sample */
        }
        /* ret == -2: sensor absent — skip this sample */

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            fprintf(stderr, "Warning: close(fd) failed: %s\n", strerror(errno));
    }
    return rc;
}

