/*
 * Conveyor belt monitoring system using two TI DRV5032 digital Hall-Effect sensors.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensors: TI DRV5032 (digital output)
 * Wiring:
 *   Hall sensor 1 OUT -> GPIO17 (BCM)
 *   Hall sensor 2 OUT -> GPIO27 (BCM)
 *   Both sensor VCC -> 3.3 V, GND -> GND
 *   Internal pull-ups enabled on both GPIO lines.
 *
 * Behavior:
 *   - Polls both sensors every 50 ms.
 *   - Appends a timestamped state record to conveyor_log.txt.
 *   - Prints "Conveyor halted!" when both sensors read logic 1.
 *   - Graceful shutdown on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o conveyor_monitor conveyor_monitor.c -lpigpio -lrt
 * Run:    sudo ./conveyor_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LOG_FILE     "conveyor_log.txt"
#define POLL_DELAY_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);

    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_sensor_data(int sensor_id, int value)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[%s] Error opening %s: %s\n", ts, LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s Sensor %d: %d\n", ts, sensor_id, value);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read with error handling                                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Release both lines so they can be reused */
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_OFF);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs with pull-ups --- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");
    printf("Sensor 1: GPIO%d | Sensor 2: GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);

    /* --- Main polling loop --- */
    while (g_running) {
        int v1 = read_sensor(SENSOR_1_PIN);
        int v2 = read_sensor(SENSOR_2_PIN);

        if (v1 < 0 || v2 < 0) {
            /* Sensor read error — log and continue */
            log_sensor_data(1, v1);
            log_sensor_data(2, v2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_sensor_data(1, v1);
        log_sensor_data(2, v2);

        if (v1 == 1 && v2 == 1) {
            printf("Conveyor halted!\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

