#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MMA8452Q I2C address (SA0 tied to GND on GY-45 breakout) */
#define MMA8452Q_ADDR 0x1D

/* MMA8452Q register addresses */
#define MMA8452Q_REG_STATUS     0x00
#define MMA8452Q_REG_OUT_X_MSB  0x01
#define MMA8452Q_REG_OUT_X_LSB  0x02
#define MMA8452Q_REG_OUT_Y_MSB  0x03
#define MMA8452Q_REG_OUT_Y_LSB  0x04
#define MMA8452Q_REG_OUT_Z_MSB  0x05
#define MMA8452Q_REG_OUT_Z_LSB  0x06
#define MMA8452Q_REG_CTRL_REG1  0x2A
#define MMA8452Q_REG_WHO_AM_I   0x0D

/* Expected device ID */
#define MMA8452Q_WHO_AM_I_VAL  0x1A

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* Log file path */
#define LOG_FILE "fall_log.txt"

/* I2C bus device path */
#define I2C_BUS "/dev/i2c-1"

/* Global file descriptors for cleanup */
static int i2c_fd = -1;
static FILE *log_file = NULL;

/* Signal flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a block of bytes starting at an 8-bit register */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MMA8452Q initialization                                             */
/* ------------------------------------------------------------------ */
static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, MMA8452Q_REG_WHO_AM_I, &who_am_i) < 0)
        return -1;

    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Read current CTRL_REG1 to preserve configuration bits */
    uint8_t ctrl1 = 0;
    if (i2c_read_reg8(fd, MMA8452Q_REG_CTRL_REG1, &ctrl1) < 0)
        return -1;

    /* Standby mode (ODR = 0) */
    if (i2c_write_reg8(fd, MMA8452Q_REG_CTRL_REG1, 0x00) < 0)
        return -1;

    /* Set ODR = 100 Hz (0x05) and enable active mode (bit 3) */
    if (i2c_write_reg8(fd, MMA8452Q_REG_CTRL_REG1, 0x05 | 0x08) < 0)
        return -1;

    /* Restore any previously configured bits */
    if (i2c_write_reg8(fd, MMA8452Q_REG_CTRL_REG1, ctrl1) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data                                               */
/* ------------------------------------------------------------------ */
static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    /* Read all six data registers in one block */
    if (i2c_read_block(fd, MMA8452Q_REG_OUT_X_MSB, buf, 6) < 0)
        return -1;

    /* Combine MSB and LSB, then right-shift by 4 to get signed 12-bit */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute tilt angle (degrees) from X and Y acceleration              */
/* ------------------------------------------------------------------ */
static double compute_tilt(int16_t x, int16_t y)
{
    double angle = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (angle < 0.0)
        angle += 360.0;
    return angle;
}

/* ------------------------------------------------------------------ */
/* Log a fall event with timestamp                                     */
/* ------------------------------------------------------------------ */
static void log_fall(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;
    double tilt;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mma8452q(i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MMA8452Q initialized. Monitoring for falls (threshold %.1f deg)...\n",
           TILT_THRESHOLD);

    /* Main polling loop */
    while (program_running) {
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            /* I2C error: skip this iteration, keep running */
            usleep(10000);
            continue;
        }

        tilt = compute_tilt(x, y);

        if (tilt > TILT_THRESHOLD) {
            printf("Tilt %.2f deg exceeds threshold %.1f deg — logging fall\n",
                   tilt, TILT_THRESHOLD);
            log_fall(log_file, x, y, z);
        }

        usleep(10000); /* 10 ms ≈ 100 Hz */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
