/*
 * LIS3MDL Triple-Axis Magnetometer Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LIS3MDL VCC  -> Pi 3.3 V (Pin 1)
 *   LIS3MDL GND  -> Pi GND  (Pin 9)
 *   LIS3MDL SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   LIS3MDL SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_log mag_log.c -lm
 * Run:    sudo ./mag_log   (root needed for /dev/i2c-1 on older kernels)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants ---- */
#define LIS3MDL_ADDR          0x1D   /* SA0 tied high on Adafruit breakout */
#define LIS3MDL_WHO_AM_I      0x0F
#define LIS3MDL_WHO_AM_I_VAL  0x3D
#define LIS3MDL_CTRL_REG1     0x20
#define LIS3MDL_CTRL_REG2     0x21
#define LIS3MDL_CTRL_REG3     0x22
#define LIS3MDL_CTRL_REG4     0x23
#define LIS3MDL_CTRL_REG5     0x24
#define LIS3MDL_CTRL_REG6     0x25
#define LIS3MDL_CTRL_REG7     0x26
#define LIS3MDL_OUT_X_L       0x28
#define LIS3MDL_OUT_X_H       0x29
#define LIS3MDL_OUT_Y_L       0x2A
#define LIS3MDL_OUT_Y_H       0x2B
#define LIS3MDL_OUT_Z_L       0x2C
#define LIS3MDL_OUT_Z_H       0x2D

/* ---- Calibration (replace with your own values) ---- */
static const float X_OFFSET = 0.0f;
static const float Y_OFFSET = 0.0f;
static const float Z_OFFSET = 0.0f;
static const float X_SCALE  = 1.0f;
static const float Y_SCALE  = 1.0f;
static const float Z_SCALE  = 1.0f;

/* ---- Metal-detection threshold (mG) ---- */
#define METAL_THRESHOLD_MG 800.0f

/* ---- Sampling ---- */
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lis3mdl(int fd)
{
    uint8_t who;

    /* Verify device identity */
    if (i2c_read_reg(fd, LIS3MDL_WHO_AM_I, &who) != 0)
        return -1;
    if (who != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: temp enable | 10 Hz ODR | continuous-conversion mode */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG1, 0x57) != 0)
        return -1;

    /* CTRL_REG2: ±4 gauss full-scale */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG2, 0x00) != 0)
        return -1;

    /* CTRL_REG3: little-endian offset */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG3, 0x00) != 0)
        return -1;

    /* CTRL_REG4: 800 Hz data-rate, little-endian offset */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG4, 0x80) != 0)
        return -1;

    /* CTRL_REG5: high-resolution disabled (default) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG5, 0x00) != 0)
        return -1;

    /* CTRL_REG6: no auto-reset, no block data-ready */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG6, 0x00) != 0)
        return -1;

    /* CTRL_REG7: no high-pass filter */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG7, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *x_mg, float *y_mg, float *z_mg)
{
    uint8_t raw[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2c_read_block(fd, LIS3MDL_OUT_X_L, raw, 6) != 0)
        return -1;

    x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    /*
     * ±4 gauss sensitivity: 0.146 mG/LSB.
     * Apply calibration offset and scale.
     */
    *x_mg = ((float)x_raw - X_OFFSET) * X_SCALE * 0.146f;
    *y_mg = ((float)y_raw - Y_OFFSET) * Y_SCALE * 0.146f;
    *z_mg = ((float)z_raw - Z_OFFSET) * Z_SCALE * 0.146f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x_mg, float y_mg, float z_mg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x_mg, y_mg, z_mg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void check_metal(float x_mg, float y_mg, float z_mg)
{
    float mag = sqrtf(x_mg * x_mg + y_mg * y_mg + z_mg * z_mg);
    if (mag > METAL_THRESHOLD_MG) {
        fprintf(stderr,
                "ALERT: Metal detected! Magnitude: %.2f mG\n", mag);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    int retries = 3;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (BCM GPIO2/3 on Pi 3B+) */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LIS3MDL_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Retry sensor init up to `retries` times */
    while (retries > 0) {
        if (init_lis3mdl(g_i2c_fd) == 0)
            break;
        retries--;
        if (retries > 0) {
            fprintf(stderr, "Retrying LIS3MDL init (%d left)...\n", retries);
            usleep(100000);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "LIS3MDL initialization failed after 3 attempts.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open magnetic_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "LIS3MDL logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x_mg, y_mg, z_mg;

        if (read_magnetometer(g_i2c_fd, &x_mg, &y_mg, &z_mg) != 0) {
            fprintf(stderr, "Read error; attempting sensor reinit...\n");
            if (init_lis3mdl(g_i2c_fd) != 0) {
                fprintf(stderr, "Reinit failed; continuing to retry.\n");
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_fp, x_mg, y_mg, z_mg);
        check_metal(x_mg, y_mg, z_mg);

        usleep(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

