/*
 * ADXL354B Vibration Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADXL354B SDO -> GPIO9  (BCM 9, SPI0 MISO)
 *   ADXL354B SDA -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADXL354B SCL -> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADXL354B VDD -> 3.3 V
 *   ADXL354B GND -> GND
 *
 * Build: gcc -O2 -Wall -o vibration_logger vibration_logger.c -lpigpio -lrt
 * Run:   sudo ./vibration_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL354B Register Map ---- */
#define ADXL354B_REG_DEVID_AD     0x00
#define ADXL354B_REG_RESET        0x1F
#define ADXL354B_REG_POWER_CTL    0x2D
#define ADXL354B_REG_STATUS       0x2E
#define ADXL354B_REG_XDATA_L      0x0E

#define ADXL354B_DEVID_AD_VAL     0xAD
#define ADXL354B_RESET_VAL        0x00
#define ADXL354B_POWER_CTL_RUN    0x01
#define ADXL354B_STATUS_STABLE    0x01

/* ---- SPI Configuration ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CS handled by pigpio */

#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL354B register via SPI.
 * Returns 0 on success, -1 on failure. */
static int adxl_write_reg(uint8_t reg, uint8_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "[ERROR] SPI write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL354B register via SPI.
 * Returns 0 on success, -1 on failure. */
static int adxl_read_reg(uint8_t reg, uint8_t *value)
{
    char tx[2] = { (char)(reg | 0x80 | 0x40), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "[ERROR] SPI read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 20-bit signed axis value (3 consecutive bytes, little-endian).
 * Returns 0 on success, -1 on failure. */
static int adxl_read_axis(uint8_t reg, int32_t *out)
{
    char tx[4] = { (char)(reg | 0x80 | 0x40), 0, 0, 0 };
    char rx[4] = { 0, 0, 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "[ERROR] SPI multi-byte read from reg 0x%02X failed\n", reg);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[1] << 12) |
                   ((uint32_t)(uint8_t)rx[2] << 4)  |
                   ((uint32_t)(uint8_t)rx[3] >> 4);

    /* Sign-extend 20-bit value to 32-bit */
    if (raw & 0x80000)
        raw |= 0xFFF00000;

    *out = (int32_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl_init(void)
{
    uint8_t devid = 0;

    /* 1. Software reset */
    if (adxl_write_reg(ADXL354B_REG_RESET, ADXL354B_RESET_VAL) != 0)
        return -1;
    gpioDelay(1000);  /* 1 ms */

    /* 2. Standby: clear RUN bit */
    if (adxl_write_reg(ADXL354B_REG_POWER_CTL, 0x00) != 0)
        return -1;
    gpioDelay(1000);

    /* 3. Wait for STABLE bit in STATUS register */
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (adxl_read_reg(ADXL354B_REG_STATUS, &status) != 0)
            return -1;
        if (status & ADXL354B_STATUS_STABLE)
            break;
        gpioDelay(1000);
    }
    if (!(status & ADXL354B_STATUS_STABLE)) {
        fprintf(stderr, "[ERROR] ADXL354B not ready (STATUS=0x%02X)\n", status);
        return -1;
    }

    /* 4. Enable RUN mode */
    if (adxl_write_reg(ADXL354B_REG_POWER_CTL, ADXL354B_POWER_CTL_RUN) != 0)
        return -1;
    gpioDelay(1000);

    /* 5. Verify PARTID */
    if (adxl_read_reg(ADXL354B_REG_DEVID_AD, &devid) != 0)
        return -1;
    if (devid != ADXL354B_DEVID_AD_VAL) {
        fprintf(stderr, "[ERROR] Unexpected PARTID: 0x%02X (expected 0x%02X)\n",
                devid, ADXL354B_DEVID_AD_VAL);
        return -1;
    }

    printf("[INFO] ADXL354B detected (PARTID=0x%02X)\n", devid);
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_data(int32_t x, int32_t y, int32_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, X: %d, Y: %d, Z: %d\n",
                timestamp, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] Failed to write to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl_init() != 0) {
        fprintf(stderr, "[FATAL] ADXL354B initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int32_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (adxl_read_axis(ADXL354B_REG_XDATA_L, &x) == 0 &&
                adxl_read_axis(ADXL354B_REG_XDATA_L + 2, &y) == 0 &&
                adxl_read_axis(ADXL354B_REG_XDATA_L + 4, &z) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(1000);
        }

        if (ok) {
            if (log_data(x, y, z) != 0)
                fprintf(stderr, "[WARN] Logging failed\n");
        } else {
            fprintf(stderr, "[WARN] SPI read failed after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

