#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses (from datasheet) */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0x3      /* Mode 3: active-high, sampled on trailing edge */

/* Scaling factors (from datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* Sampling interval */
#define SAMPLE_DELAY_US 10000  /* 10 ms -> ~100 Hz */

/* Global resources for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl-C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362.                         */
/* Returns 0 on success, -1 on SPI transfer failure.                  */
/* ------------------------------------------------------------------ */
static int read_register16(uint8_t reg_addr, int16_t *out)
{
    char tx[2];
    char rx[2];

    /*
     * ADIS16362 SPI read protocol:
     *   1. Send the register address with the MSB set (0x80 | reg).
     *   2. Send a dummy byte (0x00).
     *   3. The device returns the data on the next 16-bit transfer.
     *
     * Because pigpio's spiXfer sends the data in the tx buffer, we
     * must stage the two bytes and read them back.
     */
    tx[0] = (char)(0x80 | (reg_addr & 0x7F));
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register with a 16-bit read protocol (two transfers).  */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_register16_protocol(uint8_t reg_addr, int16_t *out)
{
    char tx[2];
    char rx[2];

    /* First transfer: send address + dummy */
    tx[0] = (char)(0x80 | (reg_addr & 0x7F));
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (stage 1)\n", reg_addr);
        return -1;
    }

    /* Small delay between transfers (datasheet: >100 ns) */
    gpioDelay(100);

    /* Second transfer: dummy address + dummy */
    tx[0] = 0x00;
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (stage 2)\n", reg_addr);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all sensor data and convert to physical units.                 */
/* ------------------------------------------------------------------ */
static int read_sensor_data(float *x_gyro, float *y_gyro, float *z_gyro,
                            float *x_accel, float *y_accel, float *z_accel)
{
    int16_t raw_x_gyro, raw_y_gyro, raw_z_gyro;
    int16_t raw_x_accel, raw_y_accel, raw_z_accel;

    if (read_register16_protocol(ADIS16362_REG_XGYRO_OUT, &raw_x_gyro) != 0) return -1;
    if (read_register16_protocol(ADIS16362_REG_YGYRO_OUT, &raw_y_gyro) != 0) return -1;
    if (read_register16_protocol(ADIS16362_REG_ZGYRO_OUT, &raw_z_gyro) != 0) return -1;
    if (read_register16_protocol(ADIS16362_REG_XACCEL_OUT, &raw_x_accel) != 0) return -1;
    if (read_register16_protocol(ADIS16362_REG_YACCEL_OUT, &raw_y_accel) != 0) return -1;
    if (read_register16_protocol(ADIS16362_REG_ZACCEL_OUT, &raw_z_accel) != 0) return -1;

    *x_gyro   = (float)raw_x_gyro * GYRO_SCALE;
    *y_gyro   = (float)raw_y_gyro * GYRO_SCALE;
    *z_gyro   = (float)raw_z_gyro * GYRO_SCALE;
    *x_accel = (float)raw_x_accel * ACCEL_SCALE;
    *y_accel = (float)raw_y_accel * ACCEL_SCALE;
    *z_accel = (float)raw_z_accel * ACCEL_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped measurement to the CSV file.                       */
/* ------------------------------------------------------------------ */
static int log_data(float x_gyro, float y_gyro, float z_gyro,
                    float x_accel, float y_accel, float z_accel)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro,
                x_accel, y_accel, z_accel) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Install signal handler for SIGINT */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        float x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

        if (read_sensor_data(&x_gyro, &y_gyro, &z_gyro,
                             &x_accel, &y_accel, &z_accel) == 0) {
            if (log_data(x_gyro, y_gyro, z_gyro,
                         x_accel, y_accel, z_accel) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

