/*
 * KY-032 IR obstacle-avoidance sensor monitor (Raspberry Pi 3 Model B+)
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (physical pin 1)
 *   GND         -> GND   (physical pin 9)
 *
 * The KY-032 module output is active-low: 0 = obstacle detected, 1 = path clear.
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_monitor ky032_monitor.c -lpigpio -lrt
 * Run:    sudo ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        printf("[unknown time] ");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        printf("[unknown time] ");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        printf("[unknown time] ");
        return;
    }

    printf("[%s] ", buf);
}

/*
 * Read both sensor lines simultaneously using gpioReadMany().
 * Returns 0 on success, -1 on failure.
 */
static int read_sensors(int *out1, int *out2)
{
    int pins[2] = { SENSOR_1_PIN, SENSOR_2_PIN };
    int values[2];

    int rc = gpioReadMany(pins, values);
    if (rc != 2) {
        fprintf(stderr, "gpioReadMany failed (rc=%d)\n", rc);
        return -1;
    }

    *out1 = values[0];
    *out2 = values[1];
    return 0;
}

