 * Interpret the active-low KY-032 output:
 *   0 -> obstacle detected
 *   1 -> path clear
 */
static const char *interpret_value(int value)
{
    return (value == 0) ? "Obstacle detected" : "Path clear";
}

/* ------------------------------------------------------------------ */
