    while (g_running) {
        int v1 = -1, v2 = -1;

        if (read_sensors(&v1, &v2) != 0) {
            print_timestamp();
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
