/*
 * ADIS16266 Gyroscope SPI Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, BCM 8)
 *   ADIS16266 SCLK -> GPIO11 (SPI0 SCLK, BCM 11)
 *   ADIS16266 DOUT -> GPIO9  (SPI0 MISO, BCM 9)
 *   ADIS16266 DIN  -> GPIO10 (SPI0 MOSI, BCM 10)
 *   ADIS16266 VDD  -> 3.3 V
 *   ADIS16266 GND  -> GND
 *
 * SPI0 CE0 is active-low; the ADIS16266 asserts its own CS when selected.
 *
 * Build:  gcc -O2 -Wall -Wextra -o adis16266 adis16266.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define ADIS16266_XGYRO_REG  0x04
#define ADIS16266_YGYRO_REG  0x06
#define ADIS16266_ZGYRO_REG  0x08

#define ADIS16266_SCALE_FACTOR 0.02f  /* deg/sec per LSB */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * ADIS16266 two-transfer read protocol:
 *   Transfer 1: send address byte with MSB set (0x80 | reg), then
 *               read back 2 dummy bytes (clocks out the previous data).
 *   Transfer 2: send 0x00, then read back the 2 data bytes.
 */
static int adis16266_read_reg16(uint8_t reg, int16_t *out)
{
    if (g_spi_fd < 0)
        return -1;

    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};

    /* Phase 1: address strobe */
    tx[0] = 0x80 | reg;
    tx[1] = 0x00;
    tx[2] = 0x00;
    tx[3] = 0x00;

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 4;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (phase 1): %s\n", strerror(errno));
        return -1;
    }

    /* Phase 2: data read */
    tx[0] = 0x00;
    tx[1] = 0x00;
    tx[2] = 0x00;
    tx[3] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 4;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (phase 2): %s\n", strerror(errno));
        return -1;
    }

    /* Data is in rx[2] and rx[3] (MSB first) */
    *out = (int16_t)((rx[2] << 8) | rx[3]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_data(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg16(ADIS16266_XGYRO_REG, &raw_x) < 0)
        return -1;
    if (adis16266_read_reg16(ADIS16266_YGYRO_REG, &raw_y) < 0)
        return -1;
    if (adis16266_read_reg16(ADIS16266_ZGYRO_REG, &raw_z) < 0)
        return -1;

    *x = (float)raw_x * ADIS16266_SCALE_FACTOR;
    *y = (float)raw_y * ADIS16266_SCALE_FACTOR;
    *z = (float)raw_z * ADIS16266_SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        printf("%ld.%09ld, X: %.2f, Y: %.2f, Z: %.2f\n",
               (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    } else {
        printf("[timestamp-error], X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0)
        return EXIT_FAILURE;

    printf("ADIS16266 Gyroscope Reader\n");
    printf("SPI device: %s | Mode: %d | Bits: %d | Speed: %u Hz\n",
           SPI_DEVICE, SPI_MODE, SPI_BITS, SPI_SPEED_HZ);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "SPI read error — continuing.\n");
        } else {
            log_data(x, y, z);
        }

        /* 100 ms delay (microseconds) */
        struct timespec req = { .tv_sec = 0, .tv_nsec = 100000000L };
        while (nanosleep(&req, &req) < 0 && errno == EINTR && g_running)
            ;
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

