static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d (expected %u)\n",
                reg, len, rc, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    if (read_reg(handle, LSM6DSR_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

