/*
 * Raspberry Pi 4 Model B – FXOS8700 (Adafruit breakout) I2C reader
 *
 * Wiring:
 *   FXOS8700 SDA  -> Pi GPIO2  (I2C bus 1 SDA)
 *   FXOS8700 SCL  -> Pi GPIO3  (I2C bus 1 SCL)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lpigpio -lrt
 * Run:
 *   sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 register definitions ---- */
#define FXOS8700_ADDRESS        0x0C   /* AD0 tied to GND */

#define FXOS8700_REG_STATUS     0x00
#define FXOS8700_REG_OUT_X_MSB  0x01
#define FXOS8700_REG_ID         0x0D

/*
 * Control registers.
 * The FXOS8700 is reset by writing 0x00 to CTRL_REG1.
 */
#define FXOS8700_REG_CTRL_REG1  0x2A
#define FXOS8700_REG_CTRL_REG2  0x2B

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int fxos_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns the byte value (0–255) on success, -1 on error.
 */
static int fxos_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    return rc;
}

/*
 * Read a block of `len` bytes starting at `reg`.
 * Returns 0 on success, -1 on error.
 */
static int fxos_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, want=%u, got=%d): %s\n",
                reg, len, rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */

/*
 * Verify the device identity register matches the expected value
 * (0x0B for the FXOS8700).
 */
static bool fxos_verify_id(int handle)
{
    int id = fxos_read_reg(handle, FXOS8700_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read ID register – sensor may be absent.\n");
        return false;
    }
    if (id != 0x0B) {
        fprintf(stderr, "Unexpected ID register value: 0x%02X (expected 0x0B).\n", id);
        return false;
    }
    printf("FXOS8700 detected (ID=0x%02X).\n", id);
    return true;
}

/*
 * Initialize the FXOS8700:
 *   1. Software reset via CTRL_REG1.
 *   2. Standby mode (clear ACTIVE bit).
 *   3. Configure CTRL_REG2 for 100 Hz ODR, normal mode.
 */
static bool fxos_init(int handle)
{
    /* Software reset */
    if (fxos_write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x00) < 0)
        return false;
    gpioDelay(2000); /* 2 ms settle after reset */

    /* Standby mode (clear ACTIVE bit) */
    if (fxos_write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x00) < 0)
        return false;

    /*
     * CTRL_REG2:
     *   ODR[3:0] = 0110  -> 100 Hz
     *   ACTIVE   = 1     -> active mode
     *   -> 0x26
     */
    if (fxos_write_reg(handle, FXOS8700_REG_CTRL_REG2, 0x26) < 0)
        return false;

    return true;
}

/* ---- Data extraction ---- */

/*
 * Read a 12-byte combined block (6 accel + 6 mag).
 * Layout: [X_MSB, X_LSB, X_LSB_tail, Y, Z, X, Y, Z, X, Y, Z, X]
 *   Accel: 14-bit left-aligned in 24 bits (MSB first).
 *   Mag:   16-bit big-endian in 12 bits.
 */
static int fxos_read_data(int handle,
                          int16_t *ax, int16_t *ay, int16_t *az,
                          int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];

    if (fxos_read_block(handle, FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    /* Accelerometer: 14-bit left-aligned, sign-extended to 16 bits */
    int16_t raw_ax = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]) >> 2;
    int16_t raw_ay = (int16_t)(((uint16_t)buf[3] << 8) | buf[4]) >> 2;
    int16_t raw_az = (int16_t)(((uint16_t)buf[6] << 8) | buf[7]) >> 2;

    /* Magnetometer: 16-bit big-endian, already 16 bits */
    int16_t raw_mx = (int16_t)((uint16_t)buf[8] << 8 | buf[9]);
    int16_t raw_my = (int16_t)((uint16_t)buf[10] << 8 | buf[11]);

    *ax = raw_ax; *ay = raw_ay; *az = raw_az;
    *mx = raw_mx; *my = raw_my; *mz = raw_az; /* Z is the same as accel Z */
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Verify sensor identity */
    if (!fxos_verify_id(g_i2c_handle)) {
        fprintf(stderr, "FXOS8700 not detected. Check wiring and address.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (!fxos_init(g_i2c_handle)) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition (Ctrl+C to stop)...\n");

    /* Main loop */
    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos_read_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d   Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed – retrying next cycle.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

