#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAY0 0x34
#define DATAZ0 0x36
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int read_acceleration_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int result = i2cReadI2CBlockData(handle, DATAX0, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_norm = (double)x;
    double y_norm = (double)y;
    double z_norm = (double)z;
    double magnitude = sqrt(x_norm * x_norm + y_norm * y_norm + z_norm * z_norm);
    if (magnitude == 0.0) {
        return 0.0;
    }
    return atan2(y_norm, sqrt(x_norm * x_norm + z_norm * z_norm)) * 180.0 / M_PI;
}

static int log_tilt_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Tilt Angle: %.2f degrees\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, tilt_angle);
    fclose(fp);
    return 0;
}

static int initialize_adxl345(int handle) {
    uint8_t devid;
    if (read_register(handle, 0x00, &devid) < 0) {
        fprintf(stderr, "ADXL345 not detected on bus.\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0xE5).\n", devid);
        return -1;
    }
    if (write_register(handle, POWER_CTL, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (write_register(handle, DATA_FORMAT, 0x08) < 0) return -1;
    if (write_register(handle, POWER_CTL, 0x08) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (initialize_adxl345(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int16_t x, y, z;
    double tilt_angle;
    while (program_running) {
        if (read_acceleration_data(i2c_handle, &x, &y, &z) == 0) {
            tilt_angle = calculate_tilt_angle(x, y, z);
            if (tilt_angle > TILT_THRESHOLD) {
                if (log_tilt_event(tilt_angle) == 0) {
                    printf("Tilt event logged: %.2f degrees\n", tilt_angle);
                } else {
                    fprintf(stderr, "Failed to log tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

