/*
 * door_access.c — Dual 12 V relay door-lock controller for Raspberry Pi 4 B
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 *
 * Hardware:
 *   Door A  relay IN  -> GPIO17 (BCM 17)
 *   Door B  relay IN  -> GPIO27 (BCM 27)
 *   Relay module (e.g. TIP120 + ULN2003) driven by 5 V relay driver
 *   Lock energized (closed) = relay coil energized = GPIO LOW
 *   Lock unlocked (open)   = relay coil de-energized = GPIO HIGH
 *
 * Behaviour:
 *   1. Generate a random 6-digit code (100000..999999) and print it.
 *   2. Read a numeric entry from stdin.  Non-numeric input is cleared
 *      and the user is re-prompted.
 *   3. If the entry matches the code, append "YYYY-MM-DD HH:MM:SS,NNNNNN"
 *      to access_log.txt and print "Access granted".
 *   4. If the entry does not match, print "Access denied".
 *   5. Hold the unlock state for 5 s, then re-energize the locks.
 *   6. Repeat from step 1.
 *
 * Cleanup:
 *   SIGINT/SIGTERM sets running = 0; the main loop exits, sets both
 *   outputs LOW, releases the gpiod chip, and closes the log file.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_DURATION_SEC  5
#define CODE_LENGTH  6
#define CODE_MIN  100000
#define CODE_MAX  999999
#define LOG_FILE "access_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int generate_code(void)
{
    return (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
}

static int read_code(void)
{
    char buffer[32];
    int code = 0;
    int ch;

    printf("Enter code: ");
    fflush(stdout);

    if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
        if (feof(stdin)) {
            fprintf(stderr, "End of input received.\n");
            return -1;
        }
        fprintf(stderr, "Error reading input: %s\n", strerror(errno));
        return -1;
    }

    if (buffer[0] == '\n' || buffer[0] == '\r') {
        fprintf(stderr, "Empty input. Please enter a code.\n");
        return -1;
    }

    for (size_t i = 0; buffer[i] != '\0' && buffer[i] != '\n' && buffer[i] != '\r'; i++) {
        if (buffer[i] < '0' || buffer[i] > '9') {
            fprintf(stderr, "Invalid input. Please enter a numeric code.\n");
            return -1;
        }
        code = code * 10 + (buffer[i] - '0');
    }

    return code;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%06d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Door A: GPIO%d | Door B: GPIO%d\n", DOOR_A_PIN, DOOR_B_PIN);
    printf("Locks are initially energized (closed). Press Ctrl+C to exit.\n\n");

    while (running) {
        int code = generate_code();
        printf("Generated code: %d\n", code);

        int entered_code = read_code();
        if (entered_code < 0) {
            if (!running) {
                break;
            }
            continue;
        }

        if (entered_code == code) {
            printf("Access granted.\n");
            if (log_access(code) < 0) {
                fprintf(stderr, "Warning: failed to log access.\n");
            }
        } else {
            printf("Access denied.\n");
        }

        printf("Unlocking doors for %d second(s)...\n", UNLOCK_DURATION_SEC);

        if (gpiod_line_set_value(line_a, 1) < 0) {
            fprintf(stderr, "Error unlocking Door A: %s\n", strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line_b, 1) < 0) {
            fprintf(stderr, "Error unlocking Door B: %s\n", strerror(errno));
            goto cleanup;
        }

        for (int i = 0; i < UNLOCK_DURATION_SEC && running; i++) {
            sleep(1);
        }

        if (gpiod_line_set_value(line_a, 0) < 0) {
            fprintf(stderr, "Error locking Door A: %s\n", strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line_b, 0) < 0) {
            fprintf(stderr, "Error locking Door B: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Doors re-energized. Waiting for next access attempt...\n\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line_a != NULL) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b != NULL) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully. Doors locked.\n");
    return ret;
}

