#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x50
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, BH1750_CONT_HIGH_RES_MODE);
    if (rc < 0) {
        fprintf(stderr, "Error writing to BH1750 (rc=%d)\n", rc);
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading from BH1750 (rc=%d)\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "Timestamp: %s, Lux: %.2f\n", ts, lux);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

