#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <mpr121.h>

#define PORT 12345
#define BUFFER_SIZE 1024
#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 20000
#define PLAYBACK_DURATION_S 5
#define LOG_FILE "frequency_log.txt"
#define SECRET_KEY "MySecretKey"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpr121(void) {
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        return -1;
    }
    return 0;
}

static int read_touch_data(int *touch_values) {
    char buf[MPR121_TOUCH_DATA_LEN];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCH_DATA_REG, buf, MPR121_TOUCH_DATA_LEN);
    if (bytes_read != MPR121_TOUCH_DATA_LEN) {
        fprintf(stderr, "Error: Failed to read touch data (read %d bytes, expected %d)\n", bytes_read, MPR121_TOUCH_DATA_LEN);
        return -1;
    }
    for (int i = 0; i < 12; i++) {
        touch_values[i] = (buf[i] & 0x0F) != 0;
    }
    return 0;
}

static int calculate_frequency(const int *touch_values) {
    int sum = 0;
    for (int i = 0; i < 12; i++) {
        sum += touch_values[i];
    }
    return sum * 100;
}

static int play_tone(int frequency) {
    if (frequency <= 0) {
        fprintf(stderr, "Error: Invalid frequency %d\n", frequency);
        return -1;
    }
    if (gpioHardwarePWM(PWM_PIN, frequency, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to start hardware PWM on GPIO%d\n", PWM_PIN);
        return -1;
    }
    return 0;
}

static int stop_tone(void) {
    if (gpioHardwarePWM(PWM_PIN, 0, 0) != 0) {
        fprintf(stderr, "Error: Failed to stop hardware PWM on GPIO%d\n", PWM_PIN);
        return -1;
    }
    return 0;
}

static int log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
    return 0;
}

static int authenticate_message(const char *message, const char *secret_key) {
    char expected_prefix[BUFFER_SIZE];
    snprintf(expected_prefix, sizeof(expected_prefix), "MOTION_DETECTED:%s", secret_key);
    if (strncmp(message, expected_prefix, strlen(expected_prefix)) != 0) {
        return 0;
    }
    return 1;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (i2c_handle >= 0) {
        mpr121_close(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_mpr121() != 0) {
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error: setsockopt(SO_REUSEADDR) failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: Bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (running && errno != EINTR) {
                fprintf(stderr, "Error: Accept failed: %s\n", strerror(errno));
            }
            continue;
        }

        char buffer[BUFFER_SIZE];
        ssize_t bytes_read = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_read < 0) {
            fprintf(stderr, "Error: recv failed: %s\n", strerror(errno));
            close(client_fd);
            continue;
        }
        if (bytes_read == 0) {
            printf("Client disconnected\n");
            close(client_fd);
            continue;
        }
        buffer[bytes_read] = '\0';

        printf("Received: %s\n", buffer);

        if (authenticate_message(buffer, SECRET_KEY)) {
            int touch_values[12];
            int frequency;
            int consecutive_errors = 0;

            while (running && consecutive_errors < 10) {
                if (read_touch_data(touch_values) == 0) {
                    consecutive_errors = 0;
                    frequency = calculate_frequency(touch_values);
                    if (play_tone(frequency) == 0) {
                        if (log_frequency(frequency) != 0) {
                            fprintf(stderr, "Warning: Failed to log frequency\n");
                        }
                        for (int i = 0; i < PLAYBACK_DURATION_S * 50 && running; i++) {
                            gpioDelay(SAMPLE_INTERVAL_US);
                        }
                        if (stop_tone() != 0) {
                            fprintf(stderr, "Warning: Failed to stop tone\n");
                        }
                    } else {
                        fprintf(stderr, "Warning: Failed to play tone\n");
                    }
                } else {
                    consecutive_errors++;
                    fprintf(stderr, "Warning: Failed to read touch data (consecutive errors: %d)\n", consecutive_errors);
                }
            }

            if (!running) {
                break;
            }
            fprintf(stderr, "Error: Too many consecutive read failures, aborting tone playback\n");
        } else {
            printf("Invalid message format\n");
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

