/*
 * LSM303DLHC magnetometer — Z-axis magnitude → LED brightness (PWM)
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (SDA1 = GPIO2, SCL1 = GPIO3)
 * Sensor: LSM303DLHC magnetometer (address 0x19)
 * LED:    GPIO17 (BCM), hardware PWM via pigpio
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_led mag_led.c -lpigpio -lrt
 * Run:    sudo ./mag_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define LSM303_ADDR         0x19          /* DLHC magnetometer address (SA0 tied to GND) */
#define LSM303_REG_X_LSB    0x08          /* X-axis MSB (auto-increment from 0x08) */
#define LSM303_REG_TEMP_OUT 0x05          /* Temperature register (unused here) */
#define LSM303_REG_CTRL_REG1 0x20         /* Temp sensor enable / X-axis enable */
#define LSM303_REG_CTRL_REG2 0x21         /* Z-axis enable / gain */
#define LSM303_REG_CTRL_REG3 0x22         /* Y-axis enable / gain */
#define LSM303_REG_CTRL_REG4 0x23         /* Z-axis enable / gain */
#define LSM303_REG_CTRL_REG5 0x24         /* Output data rate / auto-increment */
#define LSM303_REG_CTRL_REG6 0x25         /* Continuous conversion mode */
#define LSM303_REG_CTRL_REG7 0x26         /* Z-axis gain */

#define LED_GPIO            17            /* BCM pin for LED PWM */
#define PWM_FREQUENCY       1000          /* Hz */
#define PWM_RANGE           255           /* 8-bit resolution */
#define SAMPLE_PERIOD_US    100000        /* 100 ms */
#define MAX_FIELD_US        1000000       /* 1 ms = 1000 LSB (approx) */
#define MAX_BRIGHTNESS      255

#define LOG_FILE            "mag_led.log"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int init_lsm303(int fd)
{
    /*
     * Configure the magnetometer for continuous-conversion mode,
     * 100 Hz ODR, 11-bit XYZ resolution, and continuous-conversion.
     */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG1, 0x70) != 0) return -1; /* Temp on, X axis enabled */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG2, 0x00) != 0) return -1; /* Z axis enabled, gain 1 */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG3, 0x00) != 0) return -1; /* Y axis enabled, gain 1 */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG4, 0x00) != 0) return -1; /* Z axis enabled, gain 1 */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG5, 0x1C) != 0) return -1; /* 100 Hz ODR, 11-bit XYZ */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG6, 0x00) != 0) return -1; /* Continuous-conversion mode */
    if (i2c_write_reg8(fd, LSM303_REG_CTRL_REG7, 0x00) != 0) return -1; /* Z-axis gain 1 */

    return 0;
}

/* --------------------------- Data read ----------------------------------- */
/*
 * Read 6 bytes starting at 0x08 (X MSB, X LSB, Z MSB, Z LSB, Y MSB, Y LSB).
 * The DLHC auto-increments the register pointer after each byte read.
 */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, LSM303_REG_X_LSB, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* --------------------------- Brightness mapping --------------------------- */
static int map_field_to_brightness(int16_t z_axis)
{
    double abs_z = fabs((double)z_axis);
    double brightness = (abs_z / (double)MAX_FIELD_US) * (double)MAX_BRIGHTNESS;
    if (brightness > (double)MAX_BRIGHTNESS) brightness = (double)MAX_BRIGHTNESS;
    if (brightness < 0.0)             brightness = 0.0;
    return (int)(brightness + 0.5);
}

/* --------------------------- Logging ------------------------------------- */
static void log_data(int16_t x, int16_t y, int16_t z, int brightness)
{
    if (!g_log_fp) return;
    fprintf(g_log_fp, "X=%6d Y=%6d Z=%6d Brightness=%3d\n",
            x, y, z, brightness);
    fflush(g_log_fp);
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Stop PWM and release pigpio */
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioPWM(LED_GPIO, 0);

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    char dev_path[32];
    snprintf(dev_path, sizeof(dev_path), "/dev/i2c-%d", I2C_BUS);
    g_i2c_fd = open(dev_path, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev_path, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_lsm303(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303DLHC initialisation failed (sensor may be absent)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM303DLHC magnetometer running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int brightness = map_field_to_brightness(z);
        gpioPWM(LED_GPIO, brightness);

        log_data(x, y, z, brightness);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

