/*
 * HMC5883L Hard-Iron Offset Compensation — Raspberry Pi Zero W
 *
 * Wiring:
 *   HMC5883L VCC  -> Pi 3V3  (Pin 1)
 *   HMC5883L GND  -> Pi GND  (Pin 6)
 *   HMC5883L SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   HMC5883L SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -o hmc5883l_offset hmc5883l_offset.c -lpigpio -lrt
 * Run:    sudo ./hmc5883l_offset
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HMC5883L register definitions ---- */
#define HMC5883L_ADDR_DEFAULT 0x1E

#define HMC5883L_REGISTER_CONFIG_A 0x00
#define HMC5883L_REGISTER_CONFIG_B 0x01
#define HMC5883L_REGISTER_MODE     0x02
#define HMC5883L_REGISTER_DATA_X_MSB 0x03
#define HMC5883L_REGISTER_DATA_X_LSB 0x04
#define HMC5883L_REGISTER_DATA_Z_MSB 0x05
#define HMC5883L_REGISTER_DATA_Z_LSB 0x06
#define HMC5883L_REGISTER_DATA_Y_MSB 0x07
#define HMC5883L_REGISTER_DATA_Y_LSB 0x08

/* Config A: 8-average, 15 Hz, normal measurement */
#define HMC5883L_CONFIG_A_VAL 0x70
/* Config B: Gain = 1.3 Ga (0x20) */
#define HMC5883L_CONFIG_B_VAL 0x20
/* Mode: continuous measurement */
#define HMC5883L_MODE_CONTINUOUS 0x00

/* ---- Application constants ---- */
#define I2C_BUS 1
#define SAMPLE_PERIOD_US 500000   /* 500 ms */
#define NUM_SAMPLES 100
#define MAX_RETRIES 3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

/* Write a single byte to a register; returns 0 on success, -1 on failure. */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

/* Read N bytes starting at `reg`; returns 0 on success, -1 on failure. */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read (reg 0x%02X, len %u) failed\n", reg, len);
        return -1;
    }
    return 0;
}

/* ---- HMC5883L initialization ---- */
static int hmc5883l_init(int handle)
{
    if (i2c_write_reg(handle, HMC5883L_REGISTER_CONFIG_A, HMC5883L_CONFIG_A_VAL) != 0)
        return -1;
    if (i2c_write_reg(handle, HMC5883L_REGISTER_CONFIG_B, HMC5883L_CONFIG_B_VAL) != 0)
        return -1;
    if (i2c_write_reg(handle, HMC5883L_REGISTER_MODE, HMC5883L_MODE_CONTINUOUS) != 0)
        return -1;
    return 0;
}

/* ---- Read raw 16-bit magnetic field data ---- */
static int hmc5883l_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t data[6];
    if (i2c_read_block(handle, HMC5883L_REGISTER_DATA_X_MSB, data, 6) != 0)
        return -1;

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

/* ---- Moving-average hard-iron offset computation ---- */
static void update_offset(int16_t x, int16_t y, int16_t z,
                          int16_t *ox, int16_t *oy, int16_t *oz,
                          int16_t *buf_x, int16_t *buf_y, int16_t *buf_z,
                          int *idx, int n)
{
    buf_x[*idx] = x;
    buf_y[*idx] = y;
    buf_z[*idx] = z;
    *idx = (*idx + 1) % n;

    int32_t sx = 0, sy = 0, sz = 0;
    for (int i = 0; i < n; i++) {
        sx += buf_x[i];
        sy += buf_y[i];
        sz += buf_z[i];
    }
    *ox = (int16_t)(sx / n);
    *oy = (int16_t)(sy / n);
    *oz = (int16_t)(sz / n);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR_DEFAULT, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, HMC5883L_ADDR_DEFAULT, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hmc5883l_init(g_i2c_handle) != 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t ox = 0, oy = 0, oz = 0;
    int16_t buf_x[NUM_SAMPLES], buf_y[NUM_SAMPLES], buf_z[NUM_SAMPLES];
    int idx = 0;

    printf("HMC5883L offset compensation started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (hmc5883l_read_raw(g_i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (!ok) {
            fprintf(stderr, "Persistent I2C read failure; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        update_offset(raw_x, raw_y, raw_z, &ox, &oy, &oz,
                      buf_x, buf_y, buf_z, &idx, NUM_SAMPLES);

        int16_t corr_x = raw_x - ox;
        int16_t corr_y = raw_y - oy;
        int16_t corr_z = raw_z - oz;

        printf("X: %6d  Y: %6d  Z: %6d  (raw: %6d %6d %6d  off: %6d %6d %6d)\n",
               corr_x, corr_y, corr_z,
               raw_x, raw_y, raw_z,
               ox, oy, oz);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO2 (physical pin 3)
 *   LSM303D SCL  -> GPIO3 (physical pin 5)
 *   LSM303D INT1 -> BCM GPIO23 (physical pin 16)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Run:
 *   ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register map (accelerometer) ---- */
#define LSM303D_ADDR          0x1D
#define LSM303D_ID_REG        0x0F
#define LSM303D_ID_VALUE      0x49
#define LSM303D_CTRL_REG1     0x20
#define LSM303D_CTRL_REG2     0x21
#define LSM303D_CTRL_REG3     0x22
#define LSM303D_CTRL_REG4     0x23
#define LSM303D_CTRL_REG5     0x24
#define LSM303D_CTRL_REG6     0x25
#define LSM303D_CTRL_REG7     0x26
#define LSM303D_OUT_X_L       0x28
#define LSM303D_OUT_X_H       0x29
#define LSM303D_OUT_Y_L       0x2A
#define LSM303D_OUT_Y_H       0x2B
#define LSM303D_OUT_Z_L       0x2C
#define LSM303D_OUT_Z_H       0x2D
#define LSM303D_INT_CTRL_REG  0x30
#define LSM303D_INT_STATUS_REG 0x31

/* ---- Configuration ---- */
#define I2C_BUS               "/dev/i2c-1"
#define GPIO_CHIP             "gpiochip4"   /* BCM GPIO23 on Pi Zero W */
#define GPIO_LINE             23
#define BUFFER_SIZE           64
#define SAMPLE_PERIOD_US      10000        /* 10 ms */
#define INT_THRESHOLD_MG      2000.0f      /* 2 g */
#define SENSITIVITY_MG_LSB    0.061f       /* 0.061 mg/LSB */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ---- Types ---- */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Prototypes ---- */
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int  i2c_read_reg16(int fd, uint8_t reg, int16_t *out);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *out);
static int  init_lsm303d(int fd);
static int  read_accel(int fd, accel_sample_t *sample);
static void buffer_add(circular_buffer_t *buf, accel_sample_t s);
static void dump_last_n(const circular_buffer_t *buf, int n);
static void cleanup(void);
static void sigint_handler(int sig);

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_reg(fd, reg, buf, 2) < 0)
        return -1;
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    return i2c_read_reg(fd, reg, out, 1);
}

/* ---- Initialization ---- */
static int init_lsm303d(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, LSM303D_ID_REG, &id) < 0)
        return -1;
    if (id != LSM303D_ID_VALUE) {
        fprintf(stderr, "LSM303D identity mismatch: got 0x%02X, expected 0x%02X\n",
                id, LSM303D_ID_VALUE);
        return -1;
    }

    /* CTRL_REG1: enable accelerometer, ODR = 100 Hz (0x40) */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG1, 0x40) < 0)
        return -1;

    /* CTRL_REG2: full-scale = 2 g (0x00), high-resolution off */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG2, 0x00) < 0)
        return -1;

    /* CTRL_REG3: anti-aliasing = 50 Hz (0x00), no high-pass */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG3, 0x00) < 0)
        return -1;

    /* CTRL_REG4: enable all axes (0x07) */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG4, 0x07) < 0)
        return -1;

    /* CTRL_REG5: enable all interrupts (0x07) */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG5, 0x07) < 0)
        return -1;

    /* CTRL_REG6: enable all interrupt sources (0x3F) */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG6, 0x3F) < 0)
        return -1;

    /* CTRL_REG7: enable all axes in interrupt (0x07) */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG7, 0x07) < 0)
        return -1;

    /* INT_CTRL_REG: threshold = 2000 mg (0x0F), duration = 0 (0x00) */
    if (i2c_write_reg(fd, LSM303D_INT_CTRL_REG, 0x0F) < 0)
        return -1;

    return 0;
}

/* ---- Accelerometer read ---- */
static int read_accel(int fd, accel_sample_t *sample)
{
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_Y_L, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_Z_L, &raw_z) < 0) return -1;

    sample->x = (float)raw_x * SENSITIVITY_MG_LSB / 1000.0f;
    sample->y = (float)raw_y * SENSITIVITY_MG_LSB / 1000.0f;
    sample->z = (float)raw_z * SENSITIVITY_MG_LSB / 1000.0f;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(circular_buffer_t *buf, accel_sample_t s)
{
    buf->data[buf->head] = s;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void dump_last_n(const circular_buffer_t *buf, int n)
{
    if (n > buf->count) n = buf->count;
    if (n <= 0) return;

    int start = (buf->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        time_t now = time(NULL);
        struct tm tmv;
        localtime_r(&now, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("%s  X: %7.2f mg  Y: %7.2f mg  Z: %7.2f mg\n",
               ts, buf->data[idx].x, buf->data[idx].y, buf->data[idx].z);
    }
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        if (g_i2c_fd >= 0)
            i2c_write_reg(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lsm303d(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line as input */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(g_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as input: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    circular_buffer_t buf = {0};

    printf("LSM303D monitoring started. INT1 on BCM GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (g_running) {
        accel_sample_t sample;
        if (read_accel(g_i2c_fd, &sample) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
        } else {
            buffer_add(&buf, sample);

            /* Poll INT1 (active-high) */
            int val = gpiod_line_get_value(g_line);
            if (val < 0) {
                fprintf(stderr, "Warning: GPIO read failed: %s\n", strerror(errno));
            } else if (val == 1) {
                printf("INT1 triggered!\n");
                dump_last_n(&buf, 10);
                /* Clear interrupt by reading INT_STATUS_REG */
                uint8_t status;
                if (i2c_read_reg8(g_i2c_fd, LSM303D_INT_STATUS_REG, &status) < 0)
                    fprintf(stderr, "Warning: could not clear INT1 status\n");
            }
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

