#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_both_low(void) {
    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW\n", SOLENOID_1_PIN);
        return -1;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW\n", SOLENOID_2_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_both_low() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int other_pin = SOLENOID_2_PIN;

    while (g_running) {
        if (gpioWrite(active_pin, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d HIGH\n", active_pin);
            break;
        }
        if (gpioWrite(other_pin, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d LOW\n", other_pin);
            break;
        }

        struct timespec ts = {
            .tv_sec = DELAY_MS / 1000,
            .tv_nsec = (DELAY_MS % 1000) * 1000000L
        };
        if (nanosleep(&ts, NULL) != 0) {
            perror("nanosleep");
            break;
        }

        if (!g_running) {
            break;
        }

        if (gpioWrite(active_pin, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d LOW\n", active_pin);
            break;
        }
        if (gpioWrite(other_pin, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d HIGH\n", other_pin);
            break;
        }

        active_pin = other_pin;
        other_pin = SOLENOID_1_PIN;
    }

    set_both_low();
    gpioTerminate();
    return EXIT_SUCCESS;
}

