#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define EXPECTED_CODE "123456"
#define EXPECTED_CODE_LEN 6
#define READ_TIMEOUT_SEC 5
#define LOCK_OPEN_DURATION_SEC 2
#define MAX_READ_LEN 256

static volatile sig_atomic_t g_running = 1;
static int g_uart0_handle = -1;
static int g_uart1_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(int handle, const char *device) {
    int fd = serOpen(handle, device, 9600, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

static int read_code(int uart_handle, char *code, size_t max_len) {
    char buf[MAX_READ_LEN];
    memset(buf, 0, sizeof(buf));
    memset(code, 0, max_len);

    time_t start = time(NULL);
    int total = 0;

    while (g_running) {
        int n = serRead(uart_handle, buf, sizeof(buf) - 1);
        if (n < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            if (difftime(time(NULL), start) >= READ_TIMEOUT_SEC) {
                fprintf(stderr, "Timeout reading code from UART\n");
                return -1;
            }
            gpioDelay(100000);
            continue;
        }
        start = time(NULL);

        for (int i = 0; i < n && total < (int)max_len - 1; i++) {
            char c = buf[i];
            if (c >= '0' && c <= '9') {
                code[total++] = c;
            } else {
                total = 0;
                break;
            }
        }
        code[total] = '\0';
    }
    return (int)strlen(code);
}

static int compare_codes(const char *a, const char *b, size_t len) {
    int result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= (unsigned char)(a[i] ^ b[i]);
    }
    return (result == 0);
}

static int unlock_door(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio_pin);
        return -1;
    }
    gpioDelay(LOCK_OPEN_DURATION_SEC * 1000000);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0 || gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LOCK1_GPIO, 0) != 0 || gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise lock relays LOW\n");
        gpioTerminate();
        return 1;
    }

    g_uart0_handle = 0;
    g_uart1_handle = 1;

    g_uart0_handle = init_uart(g_uart0_handle, "/dev/serial0");
    if (g_uart0_handle < 0) {
        gpioTerminate();
        return 1;
    }

    g_uart1_handle = init_uart(g_uart1_handle, "/dev/serial1");
    if (g_uart1_handle < 0) {
        serClose(g_uart0_handle);
        gpioTerminate();
        return 1;
    }

    char code1[EXPECTED_CODE_LEN + 1];
    char code2[EXPECTED_CODE_LEN + 1];

    while (g_running) {
        int len1 = read_code(g_uart0_handle, code1, sizeof(code1));
        int len2 = read_code(g_uart1_handle, code2, sizeof(code2));

        if (len1 > 0 && len2 > 0) {
            if (compare_codes(code1, code2, EXPECTED_CODE_LEN) &&
                compare_codes(code1, EXPECTED_CODE, EXPECTED_CODE_LEN)) {
                printf("Codes match! Unlocking doors...\n");
                if (unlock_door(LOCK1_GPIO) != 0 || unlock_door(LOCK2_GPIO) != 0) {
                    fprintf(stderr, "Error unlocking doors\n");
                }
            } else {
                fprintf(stderr, "Codes do not match: %s %s\n", code1, code2);
            }
        } else if (len1 > 0 || len2 > 0) {
            fprintf(stderr, "Incomplete code received: %s %s\n",
                    len1 > 0 ? code1 : "N/A",
                    len2 > 0 ? code2 : "N/A");
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    serClose(g_uart0_handle);
    serClose(g_uart1_handle);
    gpioTerminate();
    return 0;
}

