        result |= (unsigned char)(a[i] ^ b[i]);
    }
    return (result == 0);
}

static int unlock_door(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio_pin);
        return -1;
    }
    gpioDelay(LOCK_OPEN_DURATION_SEC * 1000000);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0 || gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LOCK1_GPIO, 0) != 0 || gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise lock relays LOW\n");
        gpioTerminate();
        return 1;
    }

    g_uart0_handle = 0;
    g_uart1_handle = 1;

    g_uart0_handle = init_uart(g_uart0_handle, "/dev/serial0");
    if (g_uart0_handle < 0) {
        gpioTerminate();
        return 1;
    }

    g_uart1_handle = init_uart(g_uart1_handle, "/dev/serial1");
    if (g_uart1_handle < 0) {
        serClose(g_uart0_handle);
        gpioTerminate();
        return 1;
    }

    char code1[EXPECTED_CODE_LEN + 1];
    char code2[EXPECTED_CODE_LEN + 1];

    while (g_running) {
        int len1 = read_code(g_uart0_handle, code1, sizeof(code1));
        int len2 = read_code(g_uart1_handle, code2, sizeof(code2));

        if (len1 > 0 && len2 > 0) {
            if (compare_codes(code1, code2, EXPECTED_CODE_LEN) &&
                compare_codes(code1, EXPECTED_CODE, EXPECTED_CODE_LEN)) {
                printf("Codes match! Unlocking doors...\n");
                if (unlock_door(LOCK1_GPIO) != 0 || unlock_door(LOCK2_GPIO) != 0) {
                    fprintf(stderr, "Error unlocking doors\n");
                }
            } else {
                fprintf(stderr, "Codes do not match: %s %s\n", code1, code2);
            }
        } else if (len1 > 0 || len2 > 0) {
            fprintf(stderr, "Incomplete code received: %s %s\n",
                    len1 > 0 ? code1 : "N/A",
                    len2 > 0 ? code2 : "N/A");
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    serClose(g_uart0_handle);
    serClose(g_uart1_handle);
    gpioTerminate();
    return 0;
}

