/*
 * Raspberry Pi 4 Model B — PIR motion detector with door-strike relay.
 *
 * Hardware:
 *   HC-SR501 PIR sensor  -> physical GPIO4  (BCM 4)
 *   Door-strike relay   -> physical GPIO17 (BCM 17)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_door pir_door.c -lgpiod
 *
 * Run:
 *   sudo ./pir_door
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN          4
#define RELAY_PIN        17
#define POLL_INTERVAL_US 50000   /* 50 ms  */
#define RELAY_PULSE_US   1000000 /* 1 s    */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *message)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    syslog(priority, "%s - %s", ts, message);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        goto out;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        goto out;
    }

    /* ---- open syslog ---- */
    openlog("pir_door", LOG_PID | LOG_CONS, LOG_USER);
    log_event(LOG_INFO, "Starting PIR door strike monitor");

    /* ---- open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        goto out;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", PIR_PIN, strerror(errno));
        goto out;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", RELAY_PIN, strerror(errno));
        goto out;
    }

    /* ---- request PIR line as input ---- */
    if (gpiod_line_request_input(pir_line, "pir_door") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto out;
    }

    /* ---- request relay line as output, initial value LOW ---- */
    if (gpiod_line_request_output(relay_line, "pir_door", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto out;
    }

    log_event(LOG_INFO, "GPIO initialized: PIR=BCM4, Relay=BCM17");

    time_t motion_start = 0;
    int relay_armed = 0;

    /* ---- main polling loop ---- */
    while (g_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            syslog(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
            break;
        }

        if (pir_val == 1) {
            if (!relay_armed) {
                log_event(LOG_INFO, "Motion detected — activating relay");

                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to activate relay: %s", strerror(errno));
                    break;
                }
                relay_armed = 1;
                motion_start = time(NULL);
            } else {
                /* Keep relay energized until failsafe or de-energize. */
            }
        } else {
            if (relay_armed) {
                log_event(LOG_INFO, "Motion ended — deactivating relay");
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to deactivate relay: %s", strerror(errno));
                    break;
                }
                relay_armed = 0;
            }
            motion_start = 0;
        }

        /* ---- failsafe check ---- */
        if (relay_armed && (time(NULL) - motion_start) > FAILSAFE_TIMEOUT) {
            log_event(LOG_WARNING,
                      "Failsafe triggered: relay energized for > 10 s — de-energizing");
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                syslog(LOG_ERR, "Failsafe de-energize failed: %s", strerror(errno));
                break;
            }
            relay_armed = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- clean shutdown ---- */
    log_event(LOG_INFO, "Shutting down — ensuring relay is off");
    if (relay_armed) {
        gpiod_line_set_value(relay_line, 0);
    }
    ret = EXIT_SUCCESS;

out:
    if (pir_line)
        gpiod_line_release(pir_line);
    if (relay_line)
        gpiod_line_release(relay_line);
    if (chip)
        gpiod_chip_close(chip);
    log_event(LOG_INFO, "Exiting");
    closelog();
    return ret;
}

