#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON_TIME 300  /* 5 minutes in seconds */
#define RELAY_OFF_TIME 60  /* 1 minute pause in seconds */
#define TIMER_INTERVAL 60 /* 1 minute */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int activate_relay(int pin, int duration_seconds) {
    if (gpioWrite(pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", pin);
        return -1;
    }
    syslog(LOG_INFO, "Relay on GPIO %d activated for %d seconds", pin, duration_seconds);
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(pin, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", pin);
        return -1;
    }
    syslog(LOG_INFO, "Relay on GPIO %d deactivated", pin);
    return 0;
}

static void timer_callback(int timer_id, void *user_data) {
    (void)timer_id;
    (void)user_data;

    static int current_relay = 1;
    static int last_relay = -1;
    static int state = 0;

    switch (state) {
        case 0:
            if (current_relay != last_relay) {
                syslog(LOG_INFO, "Starting irrigation cycle for relay %d", current_relay);
                last_relay = current_relay;
            }
            if (activate_relay(current_relay, RELAY_ON_TIME) != 0) {
                program_running = 0;
                return;
            }
            state = 1;
            break;
        case 1:
            if (activate_relay(current_relay, RELAY_OFF_TIME) != 0) {
                program_running = 0;
                return;
            }
            state = 2;
            break;
        case 2:
            current_relay++;
            if (current_relay > 4) {
                current_relay = 1;
            }
            state = 0;
            break;
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d to HIGH (OFF)", pins[i]);
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started");

    while (program_running) {
        gpioDelay(100000); /* 100 ms */
    }

    syslog(LOG_INFO, "Irrigation system stopping");

    for (int i = 0; i < 4; i++) {
        gpioWrite(pins[i], 1);
    }

    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

