#define SAMPLE_PERIOD_NS 10000000L  /* 100 Hz */

typedef struct {
    int16_t x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
