#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <stdbool.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "relay_toggle"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int toggle_relay(struct gpiod_line *line, int pin, int interval)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO%u: %s\n", pin, strerror(errno));
        return -1;
    }

    if (gpiod_line_set_value(line, !val) < 0) {
        fprintf(stderr, "Error writing GPIO%u: %s\n", pin, strerror(errno));
        return -1;
    }

    return interval;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    struct timespec next_time[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO%u line: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO%u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &next_time[0]);
    for (int i = 1; i < NUM_RELAYS; i++)
        next_time[i] = next_time[i - 1];
    next_time[0].tv_sec += prime_intervals[0];

    while (program_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (next_time[i].tv_sec < 0 || next_time[i].tv_nsec < 0) {
                next_time[i].tv_sec = 0;
                next_time[i].tv_nsec = 0;
            }
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (now.tv_sec >= next_time[i].tv_sec &&
                (now.tv_sec > next_time[i].tv_sec || now.tv_nsec >= next_time[i].tv_nsec)) {
                int interval = toggle_relay(lines[i], relay_pins[i], prime_intervals[i]);
                if (interval > 0) {
                    next_time[i].tv_sec += interval;
                    next_time[i].tv_nsec = 0;
                }
            }
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

