#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_CONFIG 0x1B

#define GYRO_SCALE_250DPS 131.0
#define GYRO_SCALE_500DPS 65.0
#define GYRO_SCALE_1000DPS 32.0
#define GYRO_SCALE_2000DPS 16.0

#define THRESHOLD 50.0
#define BUFFER_SIZE 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void cb_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(circular_buffer_t *cb, gyro_data_t d) {
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void threshold_check(gyro_data_t d) {
    float mag = sqrtf(d.x * d.x + d.y * d.y + d.z * d.z);
    if (mag > THRESHOLD) {
        printf("Threshold exceeded! Angular velocity: %.2f deg/s\n", mag);
        fflush(stdout);
    }
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg(fd, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *out) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, MPU6050_REG_GYRO_XOUT_H, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);
    out->x = (float)rx / GYRO_SCALE_250DPS;
    out->y = (float)ry / GYRO_SCALE_250DPS;
    out->z = (float)rz / GYRO_SCALE_250DPS;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(fd);
        return 1;
    }

    circular_buffer_t cb;
    cb_init(&cb);

    printf("MPU6050 gyroscope monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        gyro_data_t g;
        if (read_gyro_data(fd, &g) < 0) {
            fprintf(stderr, "Gyro read error, continuing...\n");
            usleep(10000);
            continue;
        }
        cb_add(&cb, g);
        threshold_check(g);
        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

