#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define RESPONSE_TIMEOUT_SEC 1
#define RESPONSE_TIMEOUT_MS (RESPONSE_TIMEOUT_SEC * 1000)
#define RESPONSE_TIMEOUT_NS (RESPONSE_TIMEOUT_SEC * 1000000000L)
#define READ_TIMEOUT_MS 1000
#define MAX_RETRIES 10
#define READ_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, (speed_t)baud_rate);
    cfsetispeed(&tty, (speed_t)baud_rate);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv = { .tv_sec = 0, .tv_usec = 1000 };
        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            perror("select");
            return -1;
        }
        if (rv == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed by peer\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int send_command(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        perror("write command");
        return -1;
    }
    return 0;
}

static int read_response(int fd, uint8_t *buf, size_t len) {
    uint8_t partial[9];
    size_t plen = 0;
    struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC, &deadline);
    deadline.tv_sec += RESPONSE_TIMEOUT_SEC;

    while (plen < len) {
        if (!g_running) return -1;

        if (clock_gettime(CLOCK_MONOTONIC, &deadline) < 0) {
            perror("clock_gettime");
            return -1;
        }
        long remaining_ns = (deadline.tv_sec - clock_gettime(CLOCK_MONOTONIC, NULL).tv_sec) * 1000000000L
                          + (deadline.tv_nsec - clock_gettime(CLOCK_MONOTONIC, NULL).tv_nsec);
        if (remaining_ns <= 0) {
            fprintf(stderr, "Response timeout\n");
            return -1;
        }

        ssize_t n = read(fd, partial + plen, len - plen);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read response");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed during read\n");
            return -1;
        }
        plen += (size_t)n;
    }
    memcpy(buf, partial, len);
    return 0;
}

static int parse_response(const uint8_t *buf, int *co2_ppm, int *error_flag) {
    if (buf[0] != 0x02 || buf[1] != 0x01) {
        fprintf(stderr, "Unexpected response header: 0x%02X 0x%02X\n", buf[0], buf[1]);
        return -1;
    }

    uint8_t checksum = 0;
    for (int i = 0; i < 8; i++) {
        checksum += buf[i];
    }
    if (checksum != buf[8]) {
        fprintf(stderr, "Checksum mismatch: calc=0x%02X recv=0x%02X\n", checksum, buf[8]);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[3] << 8) | buf[2];
    *co2_ppm = (int)raw;
    *error_flag = 0;
    return 0;
}

static void log_data(FILE *fp, int co2_ppm, int error_flag) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;

    fprintf(fp, "{\"timestamp\":\"%s.%03ld\",\"co2_ppm\":%d,\"error_flag\":%d}\n",
            timestamp, ms, co2_ppm, error_flag);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;

    fprintf(fp, "%s.%03ld - %s\n", timestamp, ms, msg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        close(g_uart_fd);
        gpioTerminate();
        return 1;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen error log");
        fclose(g_log_fp);
        close(g_uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t cmd[9] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t resp[9];
    int co2_ppm = 0, error_flag = 0;

    while (g_running) {
        if (send_command(g_uart_fd, cmd, sizeof(cmd)) != 0) {
            log_error(g_err_fp, "Failed to send command");
            break;
        }

        gpioDelay(READ_DELAY_US);

        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && g_running) {
            if (read_response(g_uart_fd, resp, sizeof(resp)) == 0) {
                if (parse_response(resp, &co2_ppm, &error_flag) == 0) {
                    success = 1;
                    break;
                }
                log_error(g_err_fp, "Parse error");
            } else {
                log_error(g_err_fp, "Read error");
            }
            retries++;
            gpioDelay(100000);
        }

        if (success) {
            log_data(g_log_fp, co2_ppm, error_flag);
            printf("{\"timestamp\":\"%ld.%03ld\",\"co2_ppm\":%d,\"error_flag\":%d}\n",
                   (long)time(NULL), co2_ppm, error_flag, (long)(co2_ppm * 1000));
        } else {
            fprintf(stderr, "Failed to read CO2 after %d retries\n", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    if (g_uart_fd >= 0) close(g_uart_fd);
    if (g_log_fp) fclose(g_log_fp);
    if (g_err_fp) fclose(g_err_fp);
    gpioTerminate();
