#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define GPIO_LED 17
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define HARD_IRON_X_OFFSET 100.0f
#define HARD_IRON_Y_OFFSET -50.0f
#define TARGET_HEADING 90.0f
#define HEADING_THRESHOLD 10.0f

#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_STATUS 0x09
#define HMC5883L_ID_REG 0x0A
#define HMC5883L_ID_VAL 0x48

typedef struct {
    float heading;
    time_t timestamp;
} HeadingData;

static HeadingData heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_magnetometer(void) {
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    int id = i2cReadByteData(i2c_handle, HMC5883L_ID_REG);
    if (id != HMC5883L_ID_VAL) {
        fprintf(stderr, "Error: HMC5883L not detected (ID: 0x%02X, expected: 0x%02X)\n", id, HMC5883L_ID_VAL);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int result = i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float x_comp = (float)x - HARD_IRON_X_OFFSET;
    float y_comp = (float)y - HARD_IRON_Y_OFFSET;
    float heading = atan2f(y_comp, x_comp) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

static void add_heading_to_buffer(float heading) {
    heading_buffer[buffer_index].heading = heading;
    heading_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void control_led(float heading) {
    float deviation = fabsf(heading - TARGET_HEADING);
    if (deviation > HEADING_THRESHOLD) {
        gpioWrite(GPIO_LED, 1);
    } else {
        gpioWrite(GPIO_LED, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    if (initialize_magnetometer() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading;

    while (!terminate) {
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            heading = calculate_heading(x, y);
            add_heading_to_buffer(heading);
            control_led(heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_LED, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

