/*
 * Raspberry Pi 5 — BH1750 ambient light sensor + RGB lamp control
 *
 * Hardware:
 *   - BH1750 on I2C bus 1, address 0x29 (ADDR pin tied to GND)
 *   - RED relay  on GPIO 17 (BCM)
 *   - GREEN relay on GPIO 27 (BCM)
 *   - BLUE  relay on GPIO 22 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lighting lighting.c -li2c -lpigpio -lrt
 * Run:
 *   sudo ./lighting
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define BH1750_ADDR         0x29
#define BH1750_CONT_HIGH_RES_MODE 0x10   /* one-shot, high-res, ~120 ms */
#define BH1750_CONV_TIME_MS 120

#define RED_PIN             17
#define GREEN_PIN           27
#define BLUE_PIN            22

#define LUX_THRESHOLD_LOW   50
#define LUX_THRESHOLD_MED   150
#define LUX_THRESHOLD_HIGH  300

#define LOG_FILE            "lighting_log.txt"
#define SAMPLE_INTERVAL_S   1

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_bh1750(int fd, float *lux_out);
static void control_rgb(float lux);
static void log_data(FILE *fp, float lux, int red, int green, int blue);
static void cleanup(void);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    char dev[32];
    snprintf(dev, sizeof(dev), "/dev/i2c-%d", I2C_BUS);

    g_i2c_fd = open(dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", dev, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Probe: write a dummy byte to confirm the device is present */
    uint8_t probe = 0x00;
    if (write(g_i2c_fd, &probe, 1) != 1) {
        fprintf(stderr, "BH1750 not responding at 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- GPIO init ------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return -1;
    }

    unsigned pins[3] = { RED_PIN, GREEN_PIN, BLUE_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode(%u) failed\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 0) < 0) {
            fprintf(stderr, "gpioWrite(%u, 0) failed\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

/* ------------------------------ BH1750 read ------------------------------ */
static int read_bh1750(int fd, float *lux_out)
{
    uint8_t cmd = BH1750_CONT_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write command: %s\n", strerror(errno));
        return -1;
    }

    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "BH1750 read: %s\n", strerror(errno));
        else
            fprintf(stderr, "BH1750 short read: %zd bytes\n", n);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------ RGB control ------------------------------ */
static void control_rgb(float lux)
{
    int red   = (lux < LUX_THRESHOLD_LOW)   ? 1 : 0;
    int green = (lux >= LUX_THRESHOLD_LOW && lux < LUX_THRESHOLD_MED) ? 1 : 0;
    int blue  = (lux >= LUX_THRESHOLD_MED && lux < LUX_THRESHOLD_HIGH) ? 1 : 0;

    gpioWrite(RED_PIN,   red);
    gpioWrite(GREEN_PIN, green);
    gpioWrite(BLUE_PIN,  blue);
}

/* ------------------------------ Logging ---------------------------------- */
static void log_data(FILE *fp, float lux, int red, int green, int blue)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, R:%d G:%d B:%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, red, green, blue);
    fflush(fp);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Lighting control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (read_bh1750(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            control_rgb(lux);
            log_data(g_log_fp, lux,
                     gpioRead(RED_PIN),
                     gpioRead(GREEN_PIN),
                     gpioRead(BLUE_PIN));
            printf("Lux: %.2f  R:%d G:%d B:%d\n",
                   lux,
                   gpioRead(RED_PIN),
                   gpioRead(GREEN_PIN),
                   gpioRead(BLUE_PIN));
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

