/*
 * Dual-motor proportional speed control using an L298N driver.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring (BCM numbering):
 *   Motor A  IN1 -> GPIO17
 *   Motor A  IN2 -> GPIO18  (PWM0)
 *   Motor B  IN3 -> GPIO22
 *   Motor B  IN4 -> GPIO23  (PWM1)
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control 45 60
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18   /* PWM0 */
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23   /* PWM1 */

/* ---- PWM parameters ---- */
#define PWM_FREQUENCY 1000   /* Hz */
#define PWM_RANGE     255     /* duty 0..255 */

/* ---- Control parameters ---- */
#define SPEED_THRESHOLD 50.0f   /* cm */
#define LOOP_DELAY_US   100000   /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Drive a single motor:
 *   forward  when distance < SPEED_THRESHOLD  -> IN1 high, IN2 PWM duty
 *   backward when distance >= SPEED_THRESHOLD -> IN1 low,  IN2 PWM duty
 *   stop     when distance == 0.0 or duty == 0
 *
 * Returns 0 on success, -1 on pigpio error.
 */
static int motor_drive(int in1, int in2, float distance, int *duty)
{
    if (distance < 0.0f) distance = 0.0f;
    if (distance > 100.0f) distance = 100.0f;

    int speed;
    if (distance < SPEED_THRESHOLD) {
        speed = (int)((100.0f - distance) * 255.0f / 100.0f);
        if (speed < 0) speed = 0;
        if (speed > 255) speed = 255;
    } else {
        speed = (int)((distance - SPEED_THRESHOLD) * 255.0f / 100.0f);
        if (speed < 0) speed = 0;
        if (speed > 255) speed = 255;
        if (speed > 0) speed = 255 - speed;  /* reverse direction */
    }

    if (speed == 0) {
        if (gpioWrite(in1, 0) < 0) return -1;
        if (gpioPWM(in2, 0) < 0) return -1;
        *duty = 0;
        return 0;
    }

    if (gpioWrite(in1, speed > 0 ? 1 : 0) < 0) return -1;
    if (gpioPWM(in2, speed) < 0) return -1;
    *duty = speed;
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance_cm> <motor_b_distance_cm>\n", argv[0]);
        fprintf(stderr, "  Values: 10..100 cm\n");
        return EXIT_FAILURE;
    }

    float dist_a = atof(argv[1]);
    float dist_b = atof(argv[2]);

    if (dist_a < 10.0f || dist_a > 100.0f || dist_b < 10.0f || dist_b > 100.0f) {
        fprintf(stderr, "Error: distance must be 10..100 cm (A=%.1f B=%.1f)\n", dist_a, dist_b);
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    int pins[] = {MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- PWM setup ---- */
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor control started.  A=%.1f cm  B=%.1f cm.  Ctrl+C to exit.\n", dist_a, dist_b);

    /* ---- Main control loop ---- */
    while (g_running) {
        int duty_a = 0, duty_b = 0;

        if (motor_drive(MOTOR_A_IN1, MOTOR_A_IN2, dist_a, &duty_a) < 0) {
            fprintf(stderr, "Error: motor_drive(A) failed\n");
            break;
        }
        if (motor_drive(MOTOR_B_IN3, MOTOR_B_IN4, dist_b, &duty_b) < 0) {
            fprintf(stderr, "Error: motor_drive(B) failed\n");
            break;
        }

        printf("A=%3d  B=%3d\n", duty_a, duty_b);
        usleep(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down: stopping motors and cleaning up...\n");
    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

