    if (gpioPWM(in2, speed) < 0) return -1;
    *duty = speed;
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance_cm> <motor_b_distance_cm>\n", argv[0]);
        fprintf(stderr, "  Values: 10..100 cm\n");
        return EXIT_FAILURE;
    }

    float dist_a = atof(argv[1]);
    float dist_b = atof(argv[2]);

    if (dist_a < 10.0f || dist_a > 100.0f || dist_b < 10.0f || dist_b > 100.0f) {
        fprintf(stderr, "Error: distance must be 10..100 cm (A=%.1f B=%.1f)\n", dist_a, dist_b);
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    int pins[] = {MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- PWM setup ---- */
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor control started.  A=%.1f cm  B=%.1f cm.  Ctrl+C to exit.\n", dist_a, dist_b);

    /* ---- Main control loop ---- */
    while (g_running) {
        int duty_a = 0, duty_b = 0;

        if (motor_drive(MOTOR_A_IN1, MOTOR_A_IN2, dist_a, &duty_a) < 0) {
            fprintf(stderr, "Error: motor_drive(A) failed\n");
            break;
        }
        if (motor_drive(MOTOR_B_IN3, MOTOR_B_IN4, dist_b, &duty_b) < 0) {
            fprintf(stderr, "Error: motor_drive(B) failed\n");
            break;
        }

        printf("A=%3d  B=%3d\n", duty_a, duty_b);
        usleep(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down: stopping motors and cleaning up...\n");
    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

