/*
 * Door lock/unlock controller for Raspberry Pi.
 *
 * Hardware:
 *   - 28BYJ-48 unipolar stepper motor via L293D H-bridge
 *   - L293D IN1 -> GPIO17 (BCM)
 *   - L293D IN2 -> GPIO18 (BCM)
 *   - L293D IN3 -> GPIO27 (BCM)
 *   - L293D IN4 -> GPIO22 (BCM)
 *   - LOCK button  -> GPIO24 (BCM), internal pull-up, active-LOW
 *   - UNLOCK button -> GPIO23 (BCM), internal pull-up, active-LOW
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

/* ---- Motor parameters ---- */
#define STEPS_PER_TURN 512          /* 28BYJ-48: ~512 steps per revolution */
#define STEP_DELAY_US 2000         /* 2 ms between steps */
#define LOCK_STEPS  STEPS_PER_TURN /* Clockwise (LOCK) */
#define UNLOCK_STEPS STEPS_PER_TURN /* Counter-clockwise (UNLOCK) */

/* ---- Full-step two-phase sequence (28BYJ-48) ---- */
static const int step_seq[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

/* ---- Program state ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Drive the stepper motor one step in the given direction.
 * direction: +1 = clockwise, -1 = counter-clockwise.
 */
static void stepper_step(int direction)
{
    static int step_idx = 0;
    static int last_direction = 0;

    if (direction == last_direction) {
        step_idx = (step_idx + 1) % 4;
    } else {
        step_idx = (direction > 0) ? 0 : 3;
        last_direction = direction;
    }

    int s = step_seq[step_idx];

    if (gpioWrite(IN1, s[0]) < 0) fprintf(stderr, "gpioWrite(IN1) failed\n");
    if (gpioWrite(IN2, s[1]) < 0) fprintf(stderr, "gpioWrite(IN2) failed\n");
    if (gpioWrite(IN3, s[2]) < 0) fprintf(stderr, "gpioWrite(IN3) failed\n");
    if (gpioWrite(IN4, s[3]) < 0) fprintf(stderr, "gpioWrite(IN4) failed\n");

    gpioDelay(STEP_DELAY_US);
}

/*
 * Rotate the motor the given number of steps in the given direction.
 * Returns true if the full rotation was completed without interruption.
 */
static bool stepper_rotate(int direction, int steps)
{
    for (int i = 0; i < steps && g_running; i++) {
        stepper_step(direction);
    }
    return !g_running;
}

/*
 * De-energize all four coil lines (safe state).
 */
static void motor_off(void)
{
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/*
 * Configure a GPIO as output and drive it low.
 * Returns 0 on success, -1 on failure.
 */
static int setup_output(int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", pin);
        return -1;
    }
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

/*
 * Configure a GPIO as input with internal pull-up.
 * Returns 0 on success, -1 on failure.
 */
static int setup_input_pullup(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, INPUT) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, UP) failed\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor output pins ---- */
    if (setup_output(IN1) < 0 || setup_output(IN2) < 0 ||
        setup_output(IN3) < 0 || setup_output(IN4) < 0) {
        motor_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure button input pins ---- */
    if (setup_input_pullup(LOCK_BUTTON) < 0 || setup_input_pullup(UNLOCK_BUTTON) < 0) {
        motor_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock/unlock controller ready.\n");
    printf("  LOCK button : GPIO%d (active-LOW, pull-up)\n", LOCK_BUTTON);
    printf("  UNLOCK button: GPIO%d (active-LOW, pull-up)\n", UNLOCK_BUTTON);
    printf("  Press Ctrl+C to exit.\n");

    bool lock_locked = false;

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("LOCK button pressed — locking door...\n");
            if (stepper_rotate(+1, LOCK_STEPS)) {
                lock_locked = true;
                printf("Door locked.\n");
            } else {
                printf("Locking interrupted by signal.\n");
            }
            break;
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("UNLOCK button pressed — unlocking door...\n");
            if (stepper_rotate(-1, UNLOCK_STEPS)) {
                lock_locked = false;
                printf("Door unlocked.\n");
            } else {
                printf("Unlocking interrupted by signal.\n");
            }
            break;
        }

        gpioDelay(50000); /* 50 ms poll interval */
    }

    /* ---- Clean shutdown ---- */
    motor_off();
    gpioTerminate();

    if (lock_locked) {
        printf("Program exiting — door locked.\n");
    } else {
        printf("Program exiting — door unlocked.\n");
    }

    return EXIT_SUCCESS;
}

