    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000);
    return 0;
}

int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int raw_x = i2c_read_word(fd, ACCEL_XOUT_H);
    int raw_y = i2c_read_word(fd, ACCEL_YOUT_H);
    int raw_z = i2c_read_word(fd, ACCEL_ZOUT_H);
    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        return -1;
    }
    *x = (int16_t)raw_x;
    *y = (int16_t)raw_y;
    *z = (int16_t)raw_z;
    return 0;
}

void calculate_pitch_roll(int16_t x, int16_t y, int16_t z, float *pitch, float *roll) {
    float x_f = (float)x;
    float y_f = (float)y;
    float z_f = (float)z;
    *pitch = atan2(x_f, sqrt(y_f * y_f + z_f * z_f)) * 180.0 / M_PI;
    *roll = atan2(-y_f, sqrt(x_f * x_f + z_f * z_f)) * 180.0 / M_PI;
}

int set_servo_angle(int gpio) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "1000000");
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) return -1;
    fprintf(fp, "%d", gpio * 1000);
    fclose(fp);
    return 0;
}

int log_data(float pitch, float roll, int servo_pos) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_pos);
    fflush(log_file);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int16_t x, y, z;
        float pitch, roll;
        int retries = 0;
        bool read_ok = false;

        while (retries < MAX_RETRIES && running) {
            if (read_accel_data(i2c_fd, &x, &y, &z) == 0) {
                read_ok = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read accelerometer data after %d retries\n", MAX_RETRIES);
            continue;
        }

        calculate_pitch_roll(x, y, z, &pitch, &roll);

        int servo_pos = (int)(pitch * 10);
        if (servo_pos < 0) servo_pos = 0;
        if (servo_pos > 180) servo_pos = 180;

        if (set_servo_angle(servo_pos) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        log_data(pitch, roll, servo_pos);
        usleep(100000);
    }

    set_servo_angle(0);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

