#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define FADE_DURATION_SEC 1800
#define FADE_STEPS 100
#define PWM_FREQUENCY 100
#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t program_running = 1;

typedef struct {
    int relay_number;
    time_t time_value;
    int state;
} schedule_entry_t;

static schedule_entry_t schedule[24 * 60 + 1];
static int schedule_size = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int load_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    schedule_size = 0;

    while (fgets(line, sizeof(line), fp)) {
        if (schedule_size >= (24 * 60 + 1)) {
            fprintf(stderr, "Warning: schedule file exceeds maximum entries.\n");
            break;
        }

        char *saveptr = NULL;
        char *token = strtok_r(line, ",", &saveptr);
        if (!token) {
            fprintf(stderr, "Warning: empty line in schedule file.\n");
            continue;
        }

        char *time_str = token;
        token = strtok_r(NULL, ",", &saveptr);
        if (!token) {
            fprintf(stderr, "Warning: missing relay number.\n");
            continue;
        }
        int relay_number = atoi(token);

        token = strtok_r(NULL, ",", &saveptr);
        if (!token) {
            fprintf(stderr, "Warning: missing state.\n");
            continue;
        }
        char *state_str = token;

        int hour = (int)strtol(time_str, NULL, 10);
        int minute = (int)strtol(strchr(time_str, ':') + 1, NULL, 10);
        int second = (int)strtol(strchr(time_str, ':') + 3, NULL, 10);

        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) {
            fprintf(stderr, "Warning: invalid time format '%s'.\n", time_str);
            continue;
        }

        time_t time_value = timegm(NULL);
        time_value = (time_value / (60 * 60)) * (60 * 60) + hour * 3600 + minute * 60 + second;

        if (relay_number < 1 || relay_number > NUM_RELAYS) {
            fprintf(stderr, "Warning: invalid relay number %d.\n", relay_number);
            continue;
        }

        if (strcmp(state_str, "on") == 0) {
            schedule[schedule_size].state = 1;
        } else if (strcmp(state_str, "off") == 0) {
            schedule[schedule_size].state = 0;
        } else {
            fprintf(stderr, "Warning: invalid state '%s'.\n", state_str);
            continue;
        }

        schedule[schedule_size].relay_number = relay_number;
        schedule[schedule_size].time_value = time_value;
        schedule_size++;
    }

    fclose(fp);
    return 0;
}

static void set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, strerror(errno));
    }
}

static void fade_relay(int pin, int target_state) {
    int current_state = gpioRead(pin);
    if (current_state == target_state) return;

    int duty_cycle = 0;
    int step_delay = FADE_DURATION_SEC / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; i++) {
        if (!program_running) break;

        duty_cycle = (i * 100) / FADE_STEPS;
        if (gpioPWM(pin, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", pin, strerror(errno));
            break;
        }
        usleep(step_delay * 1000000);
    }

    if (program_running) {
        set_relay(pin, target_state);
    }
}

static void update_lighting(void) {
    time_t current_time = time(NULL);
    int current_minute = (int)(current_time / 60) % (24 * 60);

    for (int i = 0; i < schedule_size; i++) {
        if (schedule[i].time_value > current_time) {
            continue;
        }

        int pin = -1;
        for (int j = 0; j < NUM_RELAYS; j++) {
            if (relay_pins[j] == schedule[i].relay_number) {
                pin = relay_pins[j];
                break;
            }
        }

        if (pin == -1) continue;

        if (schedule[i].state == 1) {
            fade_relay(pin, 1);
        } else {
            fade_relay(pin, 0);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output: %s\n", relay_pins[i], strerror(errno));
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", relay_pins[i], strerror(errno));
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error initializing PWM on GPIO %d: %s\n", relay_pins[i], strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    if (load_schedule(SCHEDULE_FILE) != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Smart home lighting system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        update_lighting();
        sleep(1);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

