/*
 * Theremin-like distance-to-frequency mapping on Raspberry Pi Zero W.
 *
 * Hardware (BCM numbering):
 *   GPIO23 - HC-SR04 trigger (output)
 *   GPIO24 - HC-SR04 echo   (input, 5 V tolerant via divider)
 *   GPIO18 - PWM buzzer    (hardware PWM0)
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define TRIGGER_PULSE_US 10          /* HC-SR04 requires >=10 us pulse      */
#define ECHO_TIMEOUT_US  30000       /* 30 ms max echo wait (~5 m round trip) */
#define LOOP_DELAY_US    20000       /* 20 ms between measurements          */
#define MIN_DISTANCE_MM  20          /* HC-SR04 minimum reliable range       */
#define MAX_DISTANCE_MM  400         /* HC-SR04 maximum reliable range       */
#define MIN_FREQ_HZ      200         /* Buzzer minimum frequency             */
#define MAX_FREQ_HZ      4000        /* Buzzer maximum frequency             */
#define LOOP_HZ          50          /* Main-loop iteration rate             */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Issue a 10 us trigger pulse via pigpio's hardware-safe output.     */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);                       /* ensure clean low              */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Measure echo pulse width in microseconds.                           */
/* Returns >= 0 on success, -1 on timeout, -2 on read error.           */
/* ------------------------------------------------------------------ */
static long read_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* timeout */
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* timeout */
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/* ------------------------------------------------------------------ */
/* Convert distance (mm) to buzzer frequency (Hz).                    */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(int distance_mm)
{
    if (distance_mm < MIN_DISTANCE_MM)
        distance_mm = MIN_DISTANCE_MM;
    if (distance_mm > MAX_DISTANCE_MM)
        distance_mm = MAX_DISTANCE_MM;

    double freq = MIN_FREQ_HZ +
                  (double)(distance_mm - MIN_DISTANCE_MM) *
                  (MAX_FREQ_HZ - MIN_FREQ_HZ) /
                  (MAX_DISTANCE_MM - MIN_DISTANCE_MM);

    if (freq < MIN_FREQ_HZ)   freq = MIN_FREQ_HZ;
    if (freq > MAX_FREQ_HZ)   freq = MAX_FREQ_HZ;

    return (int)(freq + 0.5);
}

/* ------------------------------------------------------------------ */
/* Set buzzer frequency via pigpio hardware PWM.                      */
/* ------------------------------------------------------------------ */
static void set_buzzer_frequency(int frequency)
{
    if (frequency <= 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }
    gpioSetPWMfrequency(BUZZER_PIN, frequency);
    gpioPWM(BUZZER_PIN, 128);          /* 50 % duty cycle */
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* ---- Main loop ---- */
    while (g_running) {
        trigger_sensor();

        long echo_us = read_echo_us();
        if (echo_us < 0) {
            if (echo_us == -1)
                fprintf(stderr, "Warning: echo timeout (sensor absent or out of range).\n");
            else
                fprintf(stderr, "Warning: GPIO read error on echo pin.\n");
            set_buzzer_frequency(0);
        } else {
            int distance_mm = (int)((echo_us / 2.0) * 1000.0 / 34300.0);
            if (distance_mm < MIN_DISTANCE_MM)
                distance_mm = MIN_DISTANCE_MM;

            int frequency = distance_to_frequency(distance_mm);
            set_buzzer_frequency(frequency);

            printf("Distance: %d mm  Frequency: %d Hz\n", distance_mm, frequency);
        }

        /* Enforce 60 ms cycle (1000000 / 50 = 20000 us per iteration) */
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Cleanup ---- */
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

