/*
 * RGB LED color transition on Raspberry Pi 3 Model B+
 * Common-anode RGB LED:
 *   Red   -> GPIO17 (BCM 17)
 *   Green -> GPIO22 (BCM 22)
 *   Blue  -> GPIO27 (BCM 27)
 *
 * Hardware PWM at 1 kHz using pigpio.
 * Simulated proximity value (0.0 to 1.0) is a sine wave over time.
 *
 * Build: gcc -Wall -Wextra -O2 -o rgb_led rgb_led.c -lpigpio -lrt
 * Run:   sudo ./rgb_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_FREQ   1000          /* Hz */
#define PWM_RANGE  1000          /* 0..1000 */
#define LOOP_DELAY_US 10000      /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Common-anode RGB LED: brightness is inverted.
 *   0.0 -> full brightness (pin low)
 *   1.0 -> off (pin high)
 */
static void set_led_color(float red, float green, float blue)
{
    unsigned int r_val = (unsigned int)((1.0f - red) * (float)PWM_RANGE);
    unsigned int g_val = (unsigned int)((1.0f - green) * (float)PWM_RANGE);
    unsigned int b_val = (unsigned int)((1.0f - blue) * (float)PWM_RANGE);

    if (gpioPWM(RED_PIN,   r_val) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on RED_PIN\n");
    if (gpioPWM(GREEN_PIN, g_val) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on GREEN_PIN\n");
    if (gpioPWM(BLUE_PIN,  b_val) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on BLUE_PIN\n");
}

static void turn_off_led(void)
{
    /* Common-anode: drive all pins high to turn off the LED. */
    gpioWrite(RED_PIN,   1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN,  1);
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. "
                        "Run as root (sudo) and ensure pigpiod is not running.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on each pin --- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for RED_PIN (BCM %d)\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GREEN_PIN (BCM %d)\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for BLUE_PIN (BCM %d)\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range for all three pins. */
    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for RED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GREEN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for BLUE_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for RED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GREEN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for BLUE_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off (common-anode: all pins high). */
    turn_off_led();

    printf("RGB LED color transition started. Press Ctrl+C to exit.\n");

    float phase = 0.0f;

    while (g_running) {
        float proximity = sinf(phase);
        if (proximity < 0.0f) proximity = 0.0f;
        if (proximity > 1.0f) proximity = 1.0f;

        /*
         * Simulated proximity:
         *   Red   -> 1.0 (fully on) when proximity is 0.0
         *   Green -> 1.0 when proximity is 0.5
         *   Blue  -> 1.0 when proximity is 1.0
         */
        float red   = 1.0f - proximity;
        float green = 1.0f - fabsf(proximity - 0.5f);
        float blue  = 1.0f - fabsf(proximity - 1.0f);

        set_led_color(red, green, blue);

        phase += 0.01f;
        if (phase > 2.0f * M_PI) phase -= 2.0f * M_PI;

        usleep(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    turn_off_led();
    gpioTerminate();
    printf("Done.\n");

    return EXIT_SUCCESS;
}

