#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define VIBRATION_GPIO 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

static int log_event(int value) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(log_file, "%s GPIO%d=%d\n", ts, VIBRATION_GPIO, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int check_earthquake_alert(int *window, int size) {
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1) high_count++;
    }
    return (high_count >= 3) ? 1 : 0;
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default %d ms.\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VIBRATION_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", VIBRATION_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int window[WINDOW_SIZE] = {0};
    int window_index = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (timeout %d ms)...\n", VIBRATION_GPIO, timeout_ms);

    while (program_running) {
        int level = gpioRead(VIBRATION_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", VIBRATION_GPIO);
            break;
        }

        if (log_event(level) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        window[window_index] = level;
        window_index = (window_index + 1) % WINDOW_SIZE;

        if (check_earthquake_alert(window, WINDOW_SIZE)) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("EARTHQUAKE ALERT at %s\n", ts);
            fflush(stdout);
        }

        if (gpioSetAlertFunc(VIBRATION_GPIO, NULL) != 0) {
            fprintf(stderr, "Warning: failed to reset alert callback\n");
        }

        if (gpioSetAlertFunc(VIBRATION_GPIO, NULL) != 0) {
            fprintf(stderr, "Warning: failed to reset alert callback\n");
        }

        if (gpioSetAlertFunc(VIBRATION_GPIO, NULL) != 0) {
            fprintf(stderr, "Warning: failed to reset alert callback\n");
        }

        gpioDelay(timeout_ms * 1000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

