#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION_SEC 5
#define GAP_BETWEEN_RELAYS_SEC 1
#define POLL_INTERVAL_SEC 10
#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {  /* inactive high */
            fprintf(stderr, "Error: failed to initialise GPIO %d high.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static int read_simulated_moisture(void) {
    return rand() % 101;
}

static void log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

