        fprintf(stderr, "Error: invalid relay number %d.\n", relay_number);
        return;
    }

    int pin = relay_pins[relay_number - 1];
    if (gpioWrite(pin, 0) != 0) {  /* active low */
        fprintf(stderr, "Error: failed to activate relay %d on GPIO %d.\n", relay_number, pin);
        return;
    }

    log_irrigation_event(relay_number, read_simulated_moisture());

    sleep(IRRIGATION_DURATION_SEC);

    if (gpioWrite(pin, 1) != 0) {  /* return to inactive high */
        fprintf(stderr, "Error: failed to deactivate relay %d on GPIO %d.\n", relay_number, pin);
    }
}

