/*
 * Automated Plant Watering System (Raspberry Pi Zero W)
 *
 * Hardware:
 *   - SG90 servo (valve control) on GPIO17 (BCM 17, physical pin 11)
 *   - SG90 servo (nozzle control) on GPIO18 (BCM 18, physical pin 12)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lthe_driver_library -lrt
 *
 * The library's API call is invoked directly; no wiringPi is used.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

/* ---- SG90 pulse-width constants (microseconds) ---- */
#define SERVO_MIN_PULSE 500   /* 0 degrees   */
#define SERVO_MAX_PULSE 2500  /* 180 degrees */
#define SERVO_OPEN_PULSE 1500 /* 90 degrees  (valve open) */
#define SERVO_CLOSED_PULSE 500 /* 0 degrees  (valve closed) */

/* ---- Watering parameters ---- */
#define MOISTURE_THRESHOLD 50
#define WATERING_DURATION_SEC 5
#define CYCLE_DELAY_SEC 5
#define NOZZLE_STEPS 5
#define NOZZLE_STEP_DELAY_SEC 2
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

/* ---- Moisture sequence (0-100) ---- */
static const int moisture_sequence[] = {20, 40, 60, 80, 100};
static const int sequence_length =
    sizeof(moisture_sequence) / sizeof(moisture_sequence[0]);

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  set_servo_angle(int gpio, int angle);
static int  open_valve(void);
static int  close_valve(void);
static int  spray_nozzle(int gpio, int angle);
static int  water_plant(void);
static int  read_moisture(void);
static void signal_handler(int sig);
static void cleanup_servos(void);

/* ------------------------------------------------------------------ */
/*  set_servo_angle
 *
 *  Maps an angle (0-180) to a pulse width (500-2500 us) and drives
 *  the servo on `gpio` using the library's API call.
 *
 *  Returns 0 on success, -1 on failure after MAX_RETRIES.
 */
static int set_servo_angle(int gpio, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: angle %d out of range [0, 180]\n", angle);
        return -1;
    }

    int pulse_width = SERVO_MIN_PULSE +
        (int)((long)angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = the_driver_library_set_servo_pulse_width(gpio, pulse_width);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: servo set failed on GPIO %d (attempt %d/%d): %s\n",
                gpio, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Error: servo set failed on GPIO %d after %d attempts\n",
            gpio, MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
static int open_valve(void)
{
    return set_servo_angle(VALVE_GPIO, 90);
}

/* ------------------------------------------------------------------ */
static int close_valve(void)
{
    return set_servo_angle(VALVE_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/*  spray_nozzle
 *
 *  Sweeps the nozzle through the five pre-defined angles, retrying
 *  each step up to MAX_RETRIES.  Returns 0 on success, -1 on failure.
 */
static int spray_nozzle(int gpio, int angle)
{
    static const int angles[] = {0, 45, 90, 135, 180};

    for (int i = 0; i < NOZZLE_STEPS; i++) {
        if (!g_running) {
            return -1;
        }

        if (spray_nozzle(gpio, angles[i]) != 0) {
            fprintf(stderr, "Warning: nozzle spray failed at angle %d\n",
                    angles[i]);
        }

        if (g_running && angle > 0) {
            sleep(NOZZLE_STEP_DELAY_SEC);
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int water_plant(void)
{
    if (open_valve() != 0) {
        fprintf(stderr, "Error: failed to open valve\n");
        return -1;
    }

    if (spray_nozzle(NOZZLE_GPIO, 1) != 0) {
        fprintf(stderr, "Error: nozzle spray sequence failed\n");
        close_valve();
        return -1;
    }

    if (close_valve() != 0) {
        fprintf(stderr, "Warning: failed to close valve (continuing)\n");
    }

    sleep(WATERING_DURATION_SEC);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_moisture(void)
{
    static int index = 0;
    static time_t last_change = 0;
    time_t now = time(NULL);

    if (now - last_change >= 1) {
        index = (index + 1) % sequence_length;
        last_change = now;
    }

    return moisture_sequence[index];
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup_servos(void)
{
    /* Stop both servos by passing 0 to the library's API call */
    the_driver_library_set_servo_pulse_width(VALVE_GPIO, 0);
    the_driver_library_set_servo_pulse_width(NOZZLE_GPIO, 0);

    /* Invoke the library's cleanup function */
    the_driver_library_cleanup();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the driver library */
    if (the_driver_library_init() != 0) {
        fprintf(stderr, "Error: driver library initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (g_running) {
        int moisture = read_moisture();
        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Watering plant...\n");
            if (water_plant() != 0) {
                fprintf(stderr, "Error: watering cycle failed\n");
            }
        } else {
            printf("Moisture sufficient, skipping watering.\n");
        }

        if (g_running) {
            sleep(CYCLE_DELAY_SEC);
        }
    }

    /* Clean shutdown */
    cleanup_servos();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

