/*
 * VL53L1X distance monitor with relay control on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Relay IN  -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* default address (A0 tied to GND) */
#define RELAY_GPIO           18            /* BCM pin connected to relay IN */
#define DISTANCE_THRESHOLD   50            /* cm */
#define POLL_DELAY_US        100000        /* 100 ms */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char cmd[2];
    char data[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, cmd, 2) != 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(int handle)
{
    /*
     * Minimal initialization sequence (full calibration / ranging setup
     * requires many registers; this sets a safe default mode).
     * The sensor is left in standby so the first ranging call will
     * trigger a fresh measurement cycle.
     */
    if (i2c_write_reg8(handle, 0x88, 0x00) != 0) { /* VHV_CONFIG */
        fprintf(stderr, "VL53L1X: failed to write VHV_CONFIG\n");
        return -1;
    }
    if (i2c_write_reg8(handle, 0x80, 0x01) != 0) { /* SYSTEM_MODE_START */
        fprintf(stderr, "VL53L1X: failed to write SYSTEM_MODE_START\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t raw;

    /*
     * Set the sensor to ranging mode (bit 0 of SYSTEM_MODE_START).
     * A fresh measurement cycle is initiated.
     */
    if (i2c_write_reg8(handle, 0x80, 0x01) != 0) {
        fprintf(stderr, "VL53L1X: failed to start ranging\n");
        return -1;
    }

    /*
     * Poll the data-ready bit (bit 0 of RESULT_INTERRUPT_STATUS)
     * for up to ~50 ms.  The sensor needs time to complete a
     * measurement before the data register is valid.
     */
    for (int i = 0; i < 50; i++) {
        uint16_t status;
        if (i2c_read_reg16(handle, 0x0B, &status) != 0) {
            fprintf(stderr, "VL53L1X: failed to read RESULT_INTERRUPT_STATUS\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    /* Read the 16-bit distance result (mm). */
    if (i2c_read_reg16(handle, 0x96, &raw) != 0) {
        fprintf(stderr, "VL53L1X: failed to read RESULT_RANGE_STATUS\n");
        return -1;
    }

    *distance_mm = raw;
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially LOW. */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    /* Open I2C bus to VL53L1X. */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor may be absent)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
            int distance_cm = (int)(distance_mm / 10);
            printf("Distance: %d cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("  -> Relay ON\n");
            } else {
                gpioWrite(RELAY_GPIO, 0);
                printf("  -> Relay OFF\n");
            }
        } else {
            fprintf(stderr, "Error reading distance from VL53L1X.\n");
            gpioWrite(RELAY_GPIO, 0); /* fail-safe: turn relay off on error */
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

