/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MPU-6050 VCC -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND -> Pi GND  (Pin 9)
 *   MPU-6050 SDA -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   MPU-6050 SCL -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o mpu6050_reader mpu6050_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 Registers */
#define MPU6050_ADDR          0x68
#define PWR_MGMT_1            0x6B
#define GYRO_XOUT_H           0x43
#define GYRO_YOUT_H           0x45
#define GYRO_ZOUT_H           0x47

/* Scaling factor for gyroscope data (default ±250°/s) */
#define GYRO_SCALE 131.0

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to an I2C register */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an I2C register */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive registers */
static int i2c_read_reg16(int fd, uint8_t reg_h, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_reg(fd, reg_h, &high) < 0) return -1;
    if (i2c_read_reg(fd, reg_h + 1, &low) < 0) return -1;
    *value = ((uint16_t)high << 8) | low;
    return 0;
}

