static int init_mpu6050(int fd) {
    uint8_t whoami;
    if (i2c_read_reg(fd, 0x75, &whoami) < 0) return -1;
    if (whoami != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x68). Sensor not present?\n", whoami);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000); /* 100 ms stabilization delay */
    return 0;
}

/* Read gyroscope data */
static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, GYRO_XOUT_H, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_YOUT_H, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_ZOUT_H, &raw_z) < 0) return -1;

    /* Convert raw data to degrees per second */
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

