/*
 * Plant watering system for Raspberry Pi 4 Model B
 *
 * Four 5 V relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22.
 * Active-low: HIGH = relay OFF, LOW = relay ON.
 *
 * Sequence: every 24 hours, each relay is activated for 5 s in turn.
 *
 * Build:  gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_ON_TIME   5          /* seconds */
#define POLL_INTERVAL   60         /* seconds */
#define CYCLE_DURATION  86400      /* 24 hours in seconds */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_timestamp(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(log)");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", ts) < 0) {
        perror("fprintf(log)");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(log)");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_acquired = 0;
    int rc = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to default chip lookup */
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* --- Acquire relay lines --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- Request lines as outputs, initial value HIGH (relay OFF) --- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_acquired++;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* --- Main watering cycle --- */
    while (g_running) {
        time_t start_time = time(NULL);
        if (start_time == (time_t)-1) {
            perror("time");
            break;
        }

        if (log_timestamp(LOG_FILE) != 0) {
            fprintf(stderr, "Warning: failed to log start time.\n");
        }

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            printf("Activating relay on GPIO%u for %d seconds...\n",
                   relay_pins[i], RELAY_ON_TIME);

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }

            /* Sleep in 1-second increments so we can respond to signals */
            for (int s = 0; s < RELAY_ON_TIME && g_running; s++)
                sleep(1);

            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, 1) failed: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        /* Sleep for the remainder of the 24-hour cycle */
        for (int s = 0; s < CYCLE_DURATION && g_running; s++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure all lines are left in the safe HIGH state */
    for (int i = 0; i < lines_acquired; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("Plant watering system stopped.\n");
    return rc;
}

