#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_ZOUT_H 0x47

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Threshold for angular velocity (degrees per second) */
#define VELOCITY_THRESHOLD 250.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Structure to hold gyroscope data */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
static void check_threshold(gyro_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initializes the MPU-6050 */
static int init_mpu6050(void) {
    int status;

    /* Wake up the MPU-6050 (clear sleep bit) */
    status = i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register: %d\n", status);
        return -1;
    }

    /* Allow time for the device to stabilize after waking up */
    gpioDelay(100000); /* 100 ms */

    return 0;
}

/* Reads gyroscope data from the MPU-6050 */
static int read_gyro_data(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int status;

    /* Read raw gyroscope data */
    status = i2cReadWordData(i2c_handle, MPU6050_REG_GYRO_XOUT_H);
    if (status < 0) {
        fprintf(stderr, "Error reading GYRO_XOUT_H: %d\n", status);
        return -1;
    }
    raw_x = (int16_t)status;

    status = i2cReadWordData(i2c_handle, MPU6050_REG_GYRO_YOUT_H);
    if (status < 0) {
        fprintf(stderr, "Error reading GYRO_YOUT_H: %d\n", status);
        return -1;
    }
    raw_y = (int16_t)status;

    status = i2cReadWordData(i2c_handle, MPU6050_REG_GYRO_ZOUT_H);
    if (status < 0) {
        fprintf(stderr, "Error reading GYRO_ZOUT_H: %d\n", status);
        return -1;
    }
    raw_z = (int16_t)status;

    /* Convert raw data to degrees per second (default sensitivity +/- 250 deg/s) */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* Adds data to the circular buffer */
static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

/* Checks if the angular velocity exceeds the threshold */
static void check_threshold(gyro_data_t data) {
    if (fabsf(data.x) > VELOCITY_THRESHOLD ||
        fabsf(data.y) > VELOCITY_THRESHOLD ||
        fabsf(data.z) > VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    circular_buffer_t gyro_buffer = {0};
    gyro_data_t gyro_data;
    int retry_count = 0;
    int init_attempts = 3;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (program_running) {
        float x, y, z;

        /* Read gyroscope data */
        if (read_gyro_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Error reading gyroscope data. Attempting re-initialization...\n");
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            retry_count++;
            if (retry_count <= init_attempts) {
                gpioDelay(1000000); /* 1 second delay before retry */
                i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error re-opening I2C connection: %d\n", i2c_handle);
                } else {
                    if (init_mpu6050() != 0) {
                        fprintf(stderr, "MPU-6050 re-initialization failed\n");
                        i2cClose(i2c_handle);
                        i2c_handle = -1;
                    }
                }
            } else {
                fprintf(stderr, "Failed to re-initialize MPU-6050 after %d attempts. Exiting.\n", init_attempts);
                break;
            }
            continue;
        }

        /* Get timestamp */
        clock_gettime(CLOCK_MONOTONIC, &gyro_data.timestamp);
        gyro_data.x = x;
        gyro_data.y = y;
        gyro_data.z = z;

        /* Add data to buffer */
        add_to_buffer(&gyro_buffer, gyro_data);

        /* Check threshold */
        check_threshold(gyro_data);

        /* Print data to console */
        printf("Timestamp: %ld.%09ld, X: %.2f, Y: %.2f, Z: %.2f\n",
               gyro_data.timestamp.tv_sec, gyro_data.timestamp.tv_nsec,
               gyro_data.x, gyro_data.y, gyro_data.z);

        /* Delay for 50 milliseconds (20 Hz sampling rate) */
        gpioDelay(50000);
    }

    /* Clean up and exit */
    cleanup();
    return EXIT_SUCCESS;
}

