#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define SPI_DELAY_US    0

#define MPU9250_REG_PWR_MGMT_1   0x6B
#define MPU9250_REG_GYRO_XOUT_H  0x43
#define MPU9250_REG_GYRO_YOUT_H  0x45
#define MPU9250_REG_GYRO_ZOUT_H  0x47

#define GYRO_SCALE 131.0f
#define MAX_RETRIES 3
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_cs   = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (uintptr_t)tx;
    tr.rx_buf        = (uintptr_t)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu9250_read_reg(int fd, uint8_t cs, uint8_t reg, uint8_t *val)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (gpiod_line_set_value(g_cs, 0) < 0) {
