#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define LED_PIN 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0f
#define SAMPLE_DELAY_US 10000

#define MPU6050_ADDR 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_CONFIG 0x1B

typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_read_register(uint8_t reg, uint8_t *data, int len) {
    char tx[1 + len];
    char rx[1 + len];
    tx[0] = reg | 0x80;
    for (int i = 1; i <= len; i++) tx[i] = 0;
    if (spiXfer(spi_handle, tx, rx, 1 + len) != 1 + len) return -1;
    for (int i = 0; i < len; i++) data[i] = (uint8_t)rx[i + 1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    return (spiWrite(spi_handle, tx, 2) == 2) ? 0 : -1;
}

static int init_mpu6050(void) {
    if (spi_write_register(MPU6050_REG_PWR_MGMT_1, 0x00) != 0) return -1;
    gpioDelay(100000);
    if (spi_write_register(MPU6050_REG_GYRO_CONFIG, 0x00) != 0) return -1;
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t data[6];
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H, data, 6) != 0) return -1;
    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_z = (int16_t)((data[4] << 8) | data[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               (long)gyro_buffer[idx].timestamp.tv_sec,
               gyro_buffer[idx].timestamp.tv_nsec,
               gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500000);
        gpioWrite(LED_PIN, 0);
        gpioDelay(500000);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "SPI read error\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

