#include <unistd.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define LED_PIN 21
#define TILT_THRESHOLD 45.0
#define SAMPLE_INTERVAL_US 100000

#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_CONFIG 0x1C

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int mpu6050_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int mpu6050_read_reg(uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpu6050_read_block(uint8_t reg, uint8_t *buf, uint8_t len) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        return -1;
    }
    return 0;
}

static int mpu6050_init(void) {
    if (mpu6050_write_reg(MPU6050_REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050.\n");
        return -1;
    }
    gpioDelay(100000);
    if (mpu6050_write_reg(MPU6050_REG_ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not set accelerometer range.\n");
        return -1;
    }
    return 0;
}

static int mpu6050_read_accel(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (mpu6050_read_block(MPU6050_REG_ACCEL_XOUT_H, buf, 6) != 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_tilt(int16_t ax, int16_t ay, int16_t az,
                           float *roll, float *pitch) {
    float x = (float)ax;
    float y = (float)ay;
    float z = (float)az;
    *roll = atan2f(y, sqrtf(x * x + z * z)) * 180.0f / M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / M_PI;
}

static void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening tilt_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    fclose(fp);
}

static void control_led(float roll, float pitch) {
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_handle = open(filename, O_RDWR);
    if (i2c_handle < 0) {
        perror("Error opening I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpu6050_init() != 0) {
        fprintf(stderr, "Error: MPU6050 initialisation failed.\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Tilt sensor data logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int16_t ax, ay, az;
        if (mpu6050_read_accel(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Error reading accelerometer data.\n");
        } else {
            float roll, pitch;
            calculate_tilt(ax, ay, az, &roll, &pitch);
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
            log_data(roll, pitch);
            control_led(roll, pitch);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

