static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: cannot read PART_ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: cannot write HW_KEY\n");
        return -1;
    }
    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_ALS_IR_ADCMUX, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_PS1_ADCMUX, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_PS2_ADCMUX, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_PS3_ADCMUX, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_PS_ENCODING, 0x00) < 0) return -1;
    return 0;
}

static int read_sensor(int fd, uint16_t *ambient, uint16_t *proximity) {
    if (i2c_read_reg16(fd, REG_ALS_VIS_DATA0, ambient) < 0) return -1;
    if (i2c_read_reg16(fd, REG_PS1_DATA0, proximity) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient, proximity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    if (gpioExport(LED_PIN) < 0) {
        fprintf(stderr, "Warning: gpioExport failed for pin %d\n", LED_PIN);
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Warning: gpioSetMode failed for pin %d\n", LED_PIN);
    }
    gpioWrite(LED_PIN, 0);

    while (running) {
        uint16_t ambient = 0, proximity = 0;
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_sensor(i2c_fd, &ambient, &proximity) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "All read attempts failed; skipping sample\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        log_data(log_fp, ambient, proximity);

        if (proximity > PROX_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    gpioWrite(LED_PIN, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

