#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses (from datasheet) */
#define ADXRS290_XGYRO_OUT 0x04
#define ADXRS290_YGYRO_OUT 0x06

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sampling */
#define SAMPLE_DELAY_US 10000  /* 10 ms -> ~100 Hz */

/* Retry configuration */
#define MAX_RETRIES 3

/* Global state for cleanup */
static int spi_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register from the ADXRS290 via SPI.            */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg_addr, int16_t *out)
{
    char tx[3];
    char rx[3];
    int  attempt;

    tx[0] = (char)(reg_addr | 0x80);  /* MSB = 1 for read */
    tx[1] = 0x00;                     /* dummy byte */
    tx[2] = 0x00;                     /* dummy byte */

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            *out = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
            return 0;
        }
        fprintf(stderr, "SPI read attempt %d/%d failed (ret=%d)\n",
                attempt + 1, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(1000);  /* 1 ms backoff before retry */
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialise the SPI interface.                                       */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the CSV data file.                                              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int open_data_file(void)
{
    data_file = fopen("gyro_data.csv", "w");
    if (data_file == NULL) {
        perror("fopen gyro_data.csv");
        return -1;
    }
    if (fprintf(data_file, "timestamp,x_rate,y_rate\n") < 0) {
        perror("fprintf header");
        fclose(data_file);
        data_file = NULL;
        return -1;
    }
    fflush(data_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample line to the CSV file.                                */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_data(int16_t x_rate, int16_t y_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    if (fprintf(data_file, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                x_rate, y_rate) < 0) {
        perror("fprintf data");
        return -1;
    }
    if (fflush(data_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (data_file != NULL) {
        fflush(data_file);
        fclose(data_file);
        data_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (open_data_file() != 0) {
        cleanup();
        return 1;
    }

    printf("ADXRS290 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;

        if (read_register(ADXRS290_XGYRO_OUT, &x_rate) != 0) {
            fprintf(stderr, "Failed to read X gyro after %d retries.\n",
                    MAX_RETRIES);
            break;
        }
        if (read_register(ADXRS290_YGYRO_OUT, &y_rate) != 0) {
            fprintf(stderr, "Failed to read Y gyro after %d retries.\n",
                    MAX_RETRIES);
            break;
        }

        if (log_data(x_rate, y_rate) != 0) {
            fprintf(stderr, "Failed to log data.\n");
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

