#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17

#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static uint32_t last_tick = 0;
    static uint32_t last_tick_level = 0;
    static uint32_t seismic_start_tick = 0;
    static int seismic_active = 0;

    if (gpio == SENSOR_1_PIN || gpio == SENSOR_2_PIN) {
        uint32_t diff = gpioTick() - last_tick;
        if (diff > 0) {
            last_tick = gpioTick();
            last_tick_level = level;
        }
    }

    if (gpio == ALERT_PIN) return;

    if (gpio == SENSOR_1_PIN || gpio == SENSOR_2_PIN) {
        if (level == 1) {
            if (!seismic_active) {
                seismic_active = 1;
                seismic_start_tick = gpioTick();
            }
        } else {
            if (seismic_active) {
                uint32_t elapsed = gpioTick() - seismic_start_tick;
                if (elapsed >= SEISMIC_THRESHOLD_MS * 1000) {
                    log_event("Seismic event detected!");
                    if (gpioWrite(ALERT_PIN, 1) == 0) {
                        gpioDelay(ALERT_DURATION_MS * 1000);
                        gpioWrite(ALERT_PIN, 0);
                    }
                }
                seismic_active = 0;
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(ALERT_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ALERT_PIN, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

