#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* mode 0, active-low CE */

#define GYRO_X_RATE_REG 0x00
#define GYRO_Y_RATE_REG 0x02
#define GYRO_TEMP_REG   0x04

#define LED_PIN        17
#define THRESHOLD      20.0f
#define BUFFER_SIZE    100

typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int handle, uint8_t *tx, uint8_t *rx, int len) {
    int ret = spiXfer(handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: expected %d bytes, got %d\n", len, ret);
        return -1;
    }
    return 0;
}

static int read_gyro_axis(int handle, uint8_t reg, float *rate) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(handle, tx, rx, 3) != 0) {
        return -1;
    }

    int16_t raw = (int16_t)((rx[1] << 8) | rx[2]);
    *rate = (float)raw * 0.005f;  /* 12.5 LSB/deg/s => 1/2500 */
    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

static void buffer_add(circular_buffer_t *cb, gyro_data_t data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

static void check_threshold(circular_buffer_t *cb, float rate) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    gyro_data_t entry = { .timestamp = now, .rate = rate };
    buffer_add(cb, entry);

    if (cb->count == BUFFER_SIZE) {
        gpioWrite(LED_PIN, (rate > THRESHOLD) ? 1 : 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    circular_buffer_t gyro_buffer;
    buffer_init(&gyro_buffer);

    while (running) {
        float rate;
        if (read_gyro_axis(spi_handle, GYRO_X_RATE_REG, &rate) != 0) {
            fprintf(stderr, "Failed to read gyro X-axis\n");
            break;
        }

        check_threshold(&gyro_buffer, rate);
        gpioDelay(10000);  /* 10 ms */
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

