/*
 * smart_sunset.c — Raspberry Pi Zero W
 *
 * Fades three relay-controlled dimmable lamps (GPIO17, GPIO18, GPIO27)
 * sequentially from full brightness to off over a user-defined duration
 * using hardware PWM (pigpio).
 *
 * Build:  gcc -O2 -Wall -Wextra -o smart_sunset smart_sunset.c -lpigpio -lrt
 * Run:    sudo ./smart_sunset <duration_seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_LAMPS 3
#define PWM_FREQUENCY 100          /* Hz — safe for standard 50/60 Hz AC relays */
#define PWM_RANGE     255          /* 8-bit resolution */
#define PWM_DUTY_FULL 255
#define PWM_DUTY_OFF  0

static const int lamp_pins[NUM_LAMPS] = {17, 18, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Lamp control helpers                                                */
/* ------------------------------------------------------------------ */
static int set_lamp_duty(int pin, int duty)
{
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Error: duty %d out of range [0, %d] on pin %d\n",
                duty, PWM_RANGE, pin);
        return -1;
    }
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int duration_ms)
{
    if (duration_ms <= 0) {
        fprintf(stderr, "Error: fade duration %d ms is invalid\n", duration_ms);
        return -1;
    }

    printf("Fading lamp on GPIO%d over %d ms...\n", pin, duration_ms);
    fflush(stdout);

    int steps = duration_ms / 10;          /* ~10 ms per step */
    if (steps <= 0) steps = 1;

    for (int i = 0; i <= steps && g_running; i++) {
        int duty = (PWM_DUTY_FULL * i) / steps;
        if (set_lamp_duty(pin, duty) < 0)
            return -1;
        gpioDelay(10000);                 /* 10 ms */
    }

    if (set_lamp_duty(pin, PWM_DUTY_OFF) < 0)
        return -1;

    printf("Lamp on GPIO%d faded to off.\n", pin);
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "  Duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure PWM pins ---- */
    for (int i = 0; i < NUM_LAMPS; i++) {
        int pin = lamp_pins[i];
        if (gpioSetMode(pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pin, PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed.\n", pin, PWM_FREQUENCY);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pin, PWM_RANGE) < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed.\n", pin, PWM_RANGE);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- ensure lamps start at full brightness ---- */
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (set_lamp_duty(lamp_pins[i], PWM_DUTY_FULL) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Smart sunset simulator started. Duration: %ld s\n", duration);
    printf("Lamps on GPIO%d, GPIO%d, GPIO%d\n",
           lamp_pins[0], lamp_pins[1], lamp_pins[2]);
    printf("Press Ctrl+C to interrupt early.\n");
    fflush(stdout);

    /* ---- fade each lamp sequentially ---- */
    for (int i = 0; i < NUM_LAMPS && g_running; i++) {
        int pin = lamp_pins[i];
        int fade_ms = (int)((duration * 1000L) / NUM_LAMPS);
        if (fade_ms < 100) fade_ms = 100;          /* enforce minimum fade time */

        if (fade_lamp(pin, fade_ms) < 0) {
            fprintf(stderr, "Error: fade failed on GPIO%d.\n", pin);
            goto cleanup;
        }
    }

    printf("Smart sunset sequence complete.\n");
    fflush(stdout);

cleanup:
    /* ---- turn off all lamps ---- */
    for (int i = 0; i < NUM_LAMPS; i++)
        set_lamp_duty(lamp_pins[i], PWM_DUTY_OFF);

    gpioTerminate();
    return g_running ? EXIT_SUCCESS : EXIT_FAILURE;
}

