#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_ON      0   /* active-low: LOW energizes relay */
#define RED_OFF     1
#define YELLOW_ON   0
#define YELLOW_OFF  1
#define GREEN_ON    0
#define GREEN_OFF   1
#define BLUE_ON     0
#define BLUE_OFF    1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_output(unsigned pin, unsigned level)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, PI_OUTPUT) failed\n", pin);
        return -1;
    }
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_input(unsigned pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, PI_INPUT) failed\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup_all(void)
{
    /* Turn all relays off (HIGH = de-energized) before releasing lines */
    gpioWrite(RED_PIN, 1);
    gpioWrite(YELLOW_PIN, 1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN, 1);

    gpioSetMode(RED_PIN, PI_INPUT);
    gpioSetMode(YELLOW_PIN, PI_INPUT);
    gpioSetMode(GREEN_PIN, PI_INPUT);
    gpioSetMode(BLUE_PIN, PI_INPUT);

    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
