#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5D
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define LOOP_DELAY_US 10000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_FILTER_CONFIG 0x5D
#define MPR121_AUTO_CONFIG 0x7B
#define MPR121_SOFT_RESET 0x80

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_error(buf);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFT_RESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_FILTER_CONFIG, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG, 0x0B) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: rc=%d", rc);
        log_error(msg);
        return -1;
    }
    *status = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    bool relay_state = false;
    uint32_t last_touch_ms = 0;

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            uint32_t now_ms = gpioTick() / 1000;
            if (touch_status & 0x0001) {
                if (now_ms - last_touch_ms > DEBOUNCE_DELAY_MS) {
                    relay_state = !relay_state;
                    gpioWrite(RELAY_GPIO, relay_state ? 1 : 0);
                    last_touch_ms = now_ms;
                }
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    log_error("Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

