        fprintf(stderr, "Error: failed to read flame sensor on pin %d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return level;
}

static int log_flame_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_outputs(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate buzzer on pin %d.\n", BUZZER_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate LED on pin %d.\n", LED_PIN);
        return -1;
    }
    return 0;
}

static int deactivate_outputs(void) {
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate buzzer on pin %d.\n", BUZZER_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate LED on pin %d.\n", LED_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    deactivate_outputs();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int flame_count = 0;
    int flame_active = 0;

    while (running) {
        int level = read_flame_sensor();
        if (level < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (level == 0) {
            flame_count++;
            if (flame_count >= DEBOUNCE_COUNT) {
                if (!flame_active) {
                    if (log_flame_detection() != 0) {
                        fprintf(stderr, "Error logging flame detection, exiting.\n");
                        break;
                    }
                    if (activate_outputs() != 0) {
                        fprintf(stderr, "Error activating outputs, exiting.\n");
                        break;
                    }
                    flame_active = 1;
                }
            }
        } else {
            flame_count = 0;
            if (flame_active) {
                if (deactivate_outputs() != 0) {
                    fprintf(stderr, "Error deactivating outputs, exiting.\n");
                    break;
                }
                flame_active = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Flame detection system stopped.\n");
    return EXIT_SUCCESS;
}

