#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

/* Motor A */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

/* Motor B */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

/* PID Gains */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle Avoidance Threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* Motor Speed Limits */
#define MAX_SPEED 255
#define MIN_SPEED -255

/* Log File Name */
#define LOG_FILE "balance_log.txt"

/* Global Variables */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Function Prototypes */
static void signal_handler(int signal);
static void motor_stop(void);
static void motor_forward(int motor, int speed);
static void motor_backward(int motor, int speed);
static void motor_set_speed(int motor, int speed);
static float simulate_tilt_sensor(void);
static float simulate_ultrasonic_sensor(void);
static float pid_control(float setpoint, float measured_value);
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

/* Signal Handler */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Stop Motors */
static void motor_stop(void) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
}

/* Motor Forward */
static void motor_forward(int motor, int speed) {
    if (motor == 1) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, speed);
    } else if (motor == 2) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, speed);
    }
}

/* Motor Backward */
static void motor_backward(int motor, int speed) {
    if (motor == 1) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(MOTOR_A_ENABLE, speed);
    } else if (motor == 2) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(MOTOR_B_ENABLE, speed);
    }
}

/* Motor Set Speed */
static void motor_set_speed(int motor, int speed) {
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < MIN_SPEED) speed = MIN_SPEED;

    if (speed > 0) {
        motor_forward(motor, speed);
    } else if (speed < 0) {
        motor_backward(motor, -speed);
    } else {
        motor_stop();
    }
}

/* Simulate Tilt Sensor */
static float simulate_tilt_sensor(void) {
    return ((float)rand() / RAND_MAX) * 20.0f - 10.0f;
}

/* Simulate Ultrasonic Sensor */
static float simulate_ultrasonic_sensor(void) {
    return ((float)rand() / RAND_MAX) * 398.0f + 2.0f;
}

/* PID Control */
static float pid_control(float setpoint, float measured_value) {
    static float integral = 0.0f;
    static float previous_error = 0.0f;
    float error = setpoint - measured_value;
    integral += error;
    float derivative = error - previous_error;
    float output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

/* Log Data */
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    float setpoint = 0.0f;
    float tilt_error;
    float distance;
    int motor_a_speed;
    int motor_b_speed;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO modes */
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    /* Enable PWM on enable pins */
    gpioSetPWMrange(MOTOR_A_ENABLE, 1000);
    gpioSetPWMrange(MOTOR_B_ENABLE, 1000);
    gpioPWM(MOTOR_A_ENABLE, 0);
    gpioPWM(MOTOR_B_ENABLE, 0);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (running) {
        /* Simulate sensor readings */
        tilt_error = simulate_tilt_sensor();
        distance = simulate_ultrasonic_sensor();

        /* PID Control */
        motor_a_speed = (int)pid_control(setpoint, tilt_error);
        motor_b_speed = motor_a_speed;

        /* Obstacle Avoidance */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -50;
            motor_b_speed = -50;
        }

        /* Set Motor Speeds */
        motor_set_speed(1, motor_a_speed);
        motor_set_speed(2, motor_b_speed);

        /* Log Data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Delay */
        gpioDelay(50000); /* 50ms */
    }

    /* Clean up */
    motor_stop();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

