/*
 * TTP223 Capacitive Touch Sensor -> Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP223 (digital OUT -> GPIO4, physical pin 7, BCM 18)
 * Relay:  5 V relay module (IN -> GPIO17, physical pin 11, BCM 17)
 *
 * The TTP223 output is active-HIGH when touched.  The relay is
 * active-HIGH: energized when GPIO17 is HIGH.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4   /* BCM 18, physical pin 7  */
#define RELAY_PIN        17  /* BCM 17, physical pin 11 */
#define DEBOUNCE_US      50000  /* 50 ms debounce */
#define POLL_DELAY_US    10000  /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        return -1;
    }

    /*
     * The TTP223 has an open-collector output that idles LOW.
     * Enable the internal pull-down so the pin reads LOW when
     * the sensor is disconnected or its output is open.
     */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        return -1;
    }

    /* Start with the relay de-energized (active-HIGH relay). */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", RELAY_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* De-energize the relay before releasing pigpio. */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to de-energize relay during cleanup.\n");
    }
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223 touch sensor on GPIO%d.  Relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    bool relay_state = false;

    while (g_running) {
        int level = gpioRead(TOUCH_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (level == 1) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state ? 1 : 0) != 0) {
                fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN);
                break;
            }
            printf("Touch detected -> relay %s\n", relay_state ? "ON" : "OFF");
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

