/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio via ALSA at 8000 Hz, 16-bit signed little-endian, mono,
 * computes the RMS amplitude of each 1024-frame period, and every 10 ms
 * maps that amplitude to an RGB color driven by a common-cathode LED
 * on GPIO17 (red), GPIO18 (green), GPIO27 (blue) using software PWM
 * via the driver library API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lm
 * Run:    ./mood_light [sensitivity]
 *
 * Compile with -DALSA_AVAILABLE to enable ALSA capture; otherwise
 * audio is simulated with a sine wave so the mood light still cycles.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <getopt.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#include <driver/gpio.h>
#include <driver/pwm.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

/* ---- PWM parameters ---- */
#define PWM_DUTY_CYCLE_RES 1000000  /* 1 million steps (1 µs resolution) */
#define PWM_PERIOD_NS      10000000 /* 10 ms period => 100 Hz */

/* ---- Audio parameters ---- */
#define SAMPLE_RATE        8000
#define PERIOD_FRAMES      1024
#define PERIOD_US          (PERIOD_FRAMES * 1000000UL / SAMPLE_RATE)
#define SAMPLE_SIZE_BYTES  2
#define NUM_CHANNELS       1

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static snd_pcm_t *g_pcm = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Software PWM helpers ---- */
static void pwm_set_duty(int pin, int duty_percent)
{
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int duty_cycles = (duty_percent * PWM_DUTY_CYCLE_RES) / 100;
    int off_cycles  = PWM_DUTY_CYCLE_RES - duty_cycles;

    gpio_set_mode(pin, GPIO_MODE_OUTPUT);

    for (int i = 0; i < 10 && g_running; i++) {
        gpio_set_level(pin, 1);
        gpio_delay_us(duty_cycles * 1000);
        gpio_set_level(pin, 0);
        gpio_delay_us(off_cycles * 1000);
    }
}

static void pwm_off(int pin)
{
    gpio_set_level(pin, 0);
    gpio_set_mode(pin, GPIO_INPUT);
}

/* ---- Audio capture (ALSA) ---- */
#ifdef ALSA_AVAILABLE
static int capture_init(void)
{
    int err;

    err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);

    err = snd_pcm_hw_params_any(g_pcm, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_access(g_pcm, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_format(g_pcm, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(g_pcm, hw_params, NUM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(g_pcm, hw_params, &SAMPLE_RATE, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        return -1;
    }

    unsigned int period_size;
    err = snd_pcm_hw_params_get_period_size_max(hw_params, &period_size, NULL);
    if (err < 0) {
        fprintf(stderr, "Error getting period size: %s\n", snd_strerror(err));
        return -1;
    }

    if (period_size < PERIOD_FRAMES) {
        fprintf(stderr, "Warning: requested period size %d exceeds hardware max %u; using %u\n",
                PERIOD_FRAMES, period_size, period_size);
        PERIOD_FRAMES = period_size;
    }

    err = snd_pcm_hw_params_set_period_size_near(g_pcm, hw_params, &PERIOD_FRAMES, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params(g_pcm, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error applying hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_prepare(g_pcm);
    if (err < 0) {
        fprintf(stderr, "Error preparing PCM: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

static int capture_read(int16_t *buffer, int num_frames)
{
    int err = snd_pcm_readi(g_pcm, buffer, num_frames);
    if (err < 0) {
        if (err == -EPIPE) {
            fprintf(stderr, "Error: EPIPE (buffer overrun), attempting recovery...\n");
            snd_pcm_prepare(g_pcm);
            return -1;
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Error: ESTRPIPE (suspended), attempting recovery...\n");
            snd_pcm_resume(g_pcm);
            return -1;
        } else {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
            return -1;
        }
    }
    return err;
}

static void capture_close(void)
{
    if (g_pcm) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
}
#else
static int capture_init(void)
{
    return 0;
}

static int capture_read(int16_t *buffer, int num_frames)
{
    static double phase = 0.0;
    static double freq = 440.0;
    static double amp = 1.0;

    for (int i = 0; i < num_frames; i++) {
        double sample = amp * sin(phase);
        phase += freq / (double)SAMPLE_RATE;
        if (phase >= 2.0 * M_PI) phase -= 2.0 * M_PI;
        buffer[i] = (int16_t)(sample * 32767.0);
    }
    return num_frames;
}

static void capture_close(void)
{
    /* Nothing to do */
}
#endif

/* ---- RMS amplitude ---- */
static double calculate_rms(const int16_t *buffer, int num_frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / (double)num_frames);
}

/* ---- Color mapping ---- */
static void map_to_color(double amplitude, double sensitivity,
                         int *red, int *green, int *blue)
{
    double norm = amplitude * sensitivity;
    if (norm > 1.0) norm = 1.0;
    if (norm < 0.0) norm = 0.0;

    /* Non-linear mapping: red = norm^2, green = norm, blue = 1 - norm */
    *red   = (int)(norm * norm * 255.0);
    *green = (int)(norm * 255.0);
    *blue  = (int)((1.0 - norm) * 255.0);

    if (*red > 255) *red = 255;
    if (*red < 0)   *red = 0;
    if (*green > 255) *green = 255;
    if (*green < 0)   *green = 0;
    if (*blue > 255)  *blue = 255;
    if (*blue < 0)    *blue = 0;
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    double sensitivity = 1.0;
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0) {
                    fprintf(stderr, "Error: sensitivity must be positive.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [sensitivity]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "Error: PWM initialization failed.\n");
        gpio_deinit();
        return EXIT_FAILURE;
    }

    if (capture_init() < 0) {
        fprintf(stderr, "Error: Audio capture initialization failed.\n");
        pwm_deinit();
        gpio_deinit();
        return EXIT_FAILURE;
    }

    int16_t *audio_buffer = (int16_t *)malloc(PERIOD_FRAMES * NUM_CHANNELS * SAMPLE_SIZE_BYTES);
    if (!audio_buffer) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        capture_close();
        pwm_deinit();
        gpio_deinit();
        return EXIT_FAILURE;
    }

    printf("Mood light started. Sample rate: %d Hz, period: %d frames, sensitivity: %.2f\n",
           SAMPLE_RATE, PERIOD_FRAMES, sensitivity);

    while (g_running) {
        int frames_read = capture_read(audio_buffer, PERIOD_FRAMES);
        if (frames_read < 0) {
            fprintf(stderr, "Warning: capture_read failed, retrying...\n");
            gpio_delay_us(10000);
            continue;
        }

        double amplitude = calculate_rms(audio_buffer, frames_read);
        int red, green, blue;
        map_to_color(amplitude, sensitivity, &red, &green, &blue);

        pwm_set_duty(RED_PIN,   red);
        pwm_set_duty(GREEN_PIN, green);
        pwm_set_duty(BLUE_PIN,  blue);

        gpio_delay_us(PERIOD_US);
    }

    /* ---- Cleanup ---- */
    pwm_off(RED_PIN);
    pwm_off(GREEN_PIN);
    pwm_off(BLUE_PIN);

    free(audio_buffer);
    capture_close();
    pwm_deinit();
    gpio_deinit();

    printf("\nMood light stopped.\n");
    return EXIT_SUCCESS;
}

