#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define TCS34725_ADDRESS 0x29

#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ENABLE_PON 0x01

#define TCS34725_ATIME_154MS 0xFF
#define TCS34725_CONTROL_12BIT 0x00

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int tcs34725_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int tcs34725_init(void) {
    if (tcs34725_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    gpioDelay(3000);
    if (tcs34725_write_reg(TCS34725_ATIME, TCS34725_ATIME_154MS) < 0) return -1;
    if (tcs34725_write_reg(TCS34725_CONTROL, TCS34725_CONTROL_12BIT) < 0) return -1;
    if (tcs34725_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    gpioDelay(154000);
    return 0;
}

static int tcs34725_read_word(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    tcs34725_write_reg(TCS34725_ENABLE, 0x00);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, TCS34725_ADDRESS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        cleanup();
        return 1;
    }

    fp = fopen("color_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Error opening color_data.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(fp, "timestamp,C,R,G,B\n");

    while (running) {
        uint16_t c, r, g, b;
        int err = 0;

        if (tcs34725_read_word(TCS34725_CDATA, &c) < 0) err = 1;
        if (tcs34725_read_word(TCS34725_RDATA, &r) < 0) err = 1;
        if (tcs34725_read_word(TCS34725_GDATA, &g) < 0) err = 1;
        if (tcs34725_read_word(TCS34725_BDATA, &b) < 0) err = 1;

        if (err) {
            c = r = g = b = 0;
        }

        time_t now = time(NULL);
        fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
        fflush(fp);

        gpioDelay(500000);
    }

    cleanup();
    return 0;
}

