#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHT_DURATION 51840

#define PWM_RANGE 100
#define PWM_FREQ 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully...\n", signal);
}

int set_relay_state(int pin, int state) {
    if (gpioPWM(pin, state * PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int all_relays_off(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (set_relay_state(pins[i], 0) != 0) {
            return -1;
        }
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set pin %d as output\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency on pin %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM range on pin %d\n", pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    while (program_running) {
        // Sunrise: 1 hour, duty cycle from 0 to 100
        for (int i = 0; i <= 100 && program_running; i++) {
            if (set_relay_state(RELAY1_PIN, i) != 0 ||
                set_relay_state(RELAY2_PIN, i) != 0 ||
                set_relay_state(RELAY3_PIN, i) != 0 ||
                set_relay_state(RELAY4_PIN, i) != 0) {
                fprintf(stderr, "Error: Failed to set relay state during sunrise\n");
                all_relays_off();
                gpioTerminate();
                return 1;
            }
            gpioDelay(SUNRISE_DURATION / 100);
        }

        // Daytime: 6 hours, all relays on (duty cycle 100)
        for (int i = 0; i < DAYTIME_DURATION / 100 && program_running; i++) {
            if (set_relay_state(RELAY1_PIN, 100) != 0 ||
                set_relay_state(RELAY2_PIN, 100) != 0 ||
                set_relay_state(RELAY3_PIN, 100) != 0 ||
                set_relay_state(RELAY4_PIN, 100) != 0) {
                fprintf(stderr, "Error: Failed to set relay state during daytime\n");
                all_relays_off();
                gpioTerminate();
                return 1;
            }
            gpioDelay(100);
        }

        // Sunset: 1 hour, duty cycle from 100 to 0
        for (int i = 100; i >= 0 && program_running; i--) {
            if (set_relay_state(RELAY1_PIN, i) != 0 ||
                set_relay_state(RELAY2_PIN, i) != 0 ||
                set_relay_state(RELAY3_PIN, i) != 0 ||
                set_relay_state(RELAY4_PIN, i) != 0) {
                fprintf(stderr, "Error: Failed to set relay state during sunset\n");
                all_relays_off();
                gpioTerminate();
                return 1;
            }
            gpioDelay(SUNSET_DURATION / 100);
        }

        // Night: 14.4 hours, all relays off
        for (int i = 0; i < NIGHT_DURATION / 100 && program_running; i++) {
            if (set_relay_state(RELAY1_PIN, 0) != 0 ||
                set_relay_state(RELAY2_PIN, 0) != 0 ||
                set_relay_state(RELAY3_PIN, 0) != 0 ||
                set_relay_state(RELAY4_PIN, 0) != 0) {
                fprintf(stderr, "Error: Failed to set relay state during night\n");
                all_relays_off();
                gpioTerminate();
                return 1;
            }
            gpioDelay(100);
        }
    }

    all_relays_off();
    gpioTerminate();
    return 0;
}

