        for (int i = 0; i < NIGHT_DURATION / 100 && program_running; i++) {
            if (set_relay_state(RELAY1_PIN, 0) != 0 ||
                set_relay_state(RELAY2_PIN, 0) != 0 ||
                set_relay_state(RELAY3_PIN, 0) != 0 ||
                set_relay_state(RELAY4_PIN, 0) != 0) {
                fprintf(stderr, "Error: Failed to set relay state during night\n");
                all_relays_off();
                gpioTerminate();
                return 1;
            }
            gpioDelay(100);
        }
    }

    all_relays_off();
    gpioTerminate();
    return 0;
}

