#define TIMESTAMP_STR_LEN 16

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_video(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspivid -o %s -t %ds --nopreview -w 1280 -h 720 -fps 30",
             filename, VIDEO_DURATION_S);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n", WEXITSTATUS(result));
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

