        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_directory(VIDEO_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ensure_directory(LOG_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

