        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", SENSOR_PIN);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;
            if (elapsed >= DEBOUNCE_MS * 1000) {
                last_trigger_tick = now;

                char timestamp[TIMESTAMP_STR_LEN];
                if (generate_filename(timestamp, sizeof(timestamp)) != 0) {
                    break;
                }

                char video_path[256];
                snprintf(video_path, sizeof(video_path), "%s%s.h264", VIDEO_DIR, timestamp);

                if (capture_video(video_path) == 0) {
                    printf("Video captured: %s\n", video_path);
                } else {
                    fprintf(stderr, "Error capturing video\n");
                }

                if (log_motion_event(timestamp) != 0) {
                    fprintf(stderr, "Error logging motion event\n");
                }
            }
        }

        gpioDelay(10000);
    }

    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

