#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x68

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_init(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    gpioDelay(100000);
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x01) < 0) {
        fprintf(stderr, "Error: Could not set sleep mode\n");
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyro data\n");
        return -1;
    }
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, long long timestamp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    fprintf(fp, "%lld,%d,%d,%d\n", timestamp, gyro_x, gyro_y, gyro_z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (i2cReadByteData(i2c_handle, WHO_AM_I) != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: MPU6050 not found\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpu6050_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    int init_attempts = 0;
    while (running) {
        int16_t gyro_x, gyro_y, gyro_z;
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long long timestamp = (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
            log_data(log_file, timestamp, gyro_x, gyro_y, gyro_z);
            init_attempts = 0;
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Re-initializing...\n");
            if (mpu6050_init() < 0) {
                init_attempts++;
                if (init_attempts >= 3) {
                    fprintf(stderr, "Error: Failed to re-initialize MPU6050 after 3 attempts. Exiting.\n");
                    running = 0;
                }
            } else {
                init_attempts = 0;
            }
        }
        gpioDelay(10000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

