#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {  /* Deactivate all relays initially */
            fprintf(stderr, "Error: failed to write GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 100;
}

static int control_relay(int pin, int moisture_level) {
    int level = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", pin);
        return -1;
    }
    return level;
}

static int log_data(int moisture_level, int relay1_state, int relay2_state,
                    int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, "
                "Relay3: %s, Relay4: %s\n",
                timestamp, moisture_level,
                relay1_state ? "ON" : "OFF",
                relay2_state ? "ON" : "OFF",
                relay3_state ? "ON" : "OFF",
                relay4_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    /* Deactivate all relays (drive HIGH) */
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int moisture_level = read_moisture_sensor();
        int relay1_state = control_relay(RELAY1_PIN, moisture_level);
        int relay2_state = control_relay(RELAY2_PIN, moisture_level);
        int relay3_state = control_relay(RELAY3_PIN, moisture_level);
        int relay4_state = control_relay(RELAY4_PIN, moisture_level);

        if (log_data(moisture_level, relay1_state, relay2_state,
                     relay3_state, relay4_state) != 0) {
            fprintf(stderr, "Warning: logging failed, continuing.\n");
        }

        gpioDelay(5000000);  /* 5 seconds in microseconds */
    }

    cleanup();
    return EXIT_SUCCESS;
}

