/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C1 SDA)
 *   ADXL345 SCL -> GPIO3 (I2C1 SCL)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *   Alarm LED/buzzer -> GPIO27 (BCM)
 *
 * Build: gcc -O2 -Wall -o freefall freefall.c -lpigpio -lrt
 * Run:   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDRESS         0x53   /* 0101 0011 */
#define REG_DEVID               0x00
#define DEVID_EXPECTED          0xE5
#define REG_POWER_CTL           0x2D
#define POWER_CTL_MEASURE       0x08
#define REG_DATA_FORMAT         0x31
#define DATA_FORMAT_FULL_RES    0x0B   /* 4-wire SPI, but we use I2C; bits [3:2] = 10 */
#define REG_DATAX0              0x32
#define REG_BW_RATE             0x2C
#define BW_RATE_100HZ           0x0A

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define ALARM_GPIO              27
#define FREEFALL_THRESHOLD      0.2f   /* g */
#define FREEFALL_DURATION_SEC   0.5
#define ALARM_HOLD_SEC          5
#define POLL_INTERVAL_US        100000 /* 100 ms */
#define LOG_FILE                "freefall.log"

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ---- Prototypes ---- */
static int  adxl345_init(void);
static int  adxl345_read_xyz(float *x, float *y, float *z);
static bool freefall_detected(float x, float y, float z);
static void trigger_alarm(void);
static void log_event(float x, float y, float z);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, ADXL345_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float x, y, z;

        if (adxl345_read_xyz(&x, &y, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error — continuing.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (freefall_detected(x, y, z)) {
            printf("Free-fall detected! (x=%.3f y=%.3f z=%.3f g)\n", x, y, z);
            trigger_alarm();
            log_event(x, y, z);

            /* Wait for the free-fall period to elapse before re-arming */
            time_sleep(FREEFALL_DURATION_SEC);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static int adxl345_init(void)
{
    int rc;

    rc = i2cWriteByteData(i2c_handle, REG_POWER_CTL, POWER_CTL_MEASURE);
    if (rc < 0) {
        fprintf(stderr, "Error: POWER_CTL write failed: %d\n", rc);
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    rc = i2cWriteByteData(i2c_handle, REG_DATA_FORMAT, DATA_FORMAT_FULL_RES);
    if (rc < 0) {
        fprintf(stderr, "Error: DATA_FORMAT write failed: %d\n", rc);
        return -1;
    }

    rc = i2cWriteByteData(i2c_handle, REG_BW_RATE, BW_RATE_100HZ);
    if (rc < 0) {
        fprintf(stderr, "Error: BW_RATE write failed: %d\n", rc);
        return -1;
    }

    /* Verify device identity */
    int devid = i2cReadByteData(i2c_handle, REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: DEVID read failed: %d\n", devid);
        return -1;
    }
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X).\n",
                devid, DEVID_EXPECTED);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_read_xyz(float *x, float *y, float *z)
{
    char raw[6];
    int rc = i2cReadI2CBlockData(i2c_handle, REG_DATAX0, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 6).\n", rc);
        return -1;
    }

    /* ADXL345 is little-endian: DATAX0 = LSB, DATAX1 = MSB */
    int16_t x_raw = (int16_t)(((uint16_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint16_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint16_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* Full-resolution mode: 4 mg/LSB => divide by 256 */
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
static bool freefall_detected(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* ------------------------------------------------------------------ */
static void trigger_alarm(void)
{
    gpioWrite(ALARM_GPIO, 1);
    printf("Alarm triggered for %d seconds.\n", ALARM_HOLD_SEC);
}

/* ------------------------------------------------------------------ */
static void log_event(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

