#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN 4
#define ECHO_PIN 18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 100000
#define MAX_DISTANCE_US 23200
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define LOG_FILE "distance_log.txt"

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile bool g_echo_received = false;
static volatile bool g_new_measurement = false;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&g_mutex);
        g_start_tick = tick;
        g_echo_received = false;
        pthread_mutex_unlock(&g_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&g_mutex);
        g_end_tick = tick;
        g_echo_received = true;
        g_new_measurement = true;
        pthread_mutex_unlock(&g_mutex);
    }
}

static uint32_t tick_diff(uint32_t start, uint32_t end) {
    return end - start;
}

static void log_distance(uint32_t pulse_width_us) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
