        g_echo_received = false;

        uint32_t elapsed = 0;
        while (!g_new_measurement && elapsed < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);
            elapsed += 100;
        }

        if (g_new_measurement) {
