            uint32_t pulse_width = tick_diff(g_start_tick, g_end_tick);
            pthread_mutex_unlock(&g_mutex);

            if (pulse_width > 0 && pulse_width <= MAX_DISTANCE_US) {
                log_distance(pulse_width);
            } else {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            }
        } else {
            fprintf(stderr, "Echo timeout\n");
        }

        if (g_running) {
            gpioDelay(200000);
        }
    }

    printf("\nCleaning up...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
