#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_PIN 17
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define FREE_FALL_TIMEOUT_SEC 5
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2cWriteByteData(handle, reg, value) == 0) return 0;
        gpioDelay(1000);
    }
    return -1;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int r = i2cReadByteData(handle, reg);
        if (r >= 0) {
            *value = (uint8_t)r;
            return 0;
        }
        gpioDelay(1000);
    }
    return -1;
}

static int init_lis3dh(int handle) {
    if (i2c_write_reg(handle, CTRL_REG1, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg(handle, CTRL_REG4, 0x08) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg(handle, CTRL_REG1, 0x27) != 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int read_accel(int handle, float *x, float *y, float *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg(handle, OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg(handle, OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg(handle, OUT_Z_H, &zh) != 0) return -1;
    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;
    return 0;
}

static float calc_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float free_fall_threshold = FREE_FALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;
    if (argc > 1) free_fall_threshold = atof(argv[1]);
    if (argc > 2) impact_threshold = atof(argv[2]);
    if (free_fall_threshold <= 0.0f || impact_threshold <= 0.0f || impact_threshold <= free_fall_threshold) {
        fprintf(stderr, "Invalid thresholds. Using defaults: free_fall=%.2f, impact=%.2f\n", FREE_FALL_THRESHOLD, IMPACT_THRESHOLD);
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", LIS3DH_ADDR);
        gpioTerminate();
        return 1;
    }
    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "Failed to initialize LIS3DH\n");
        cleanup();
        return 1;
    }
    bool free_fall_active = false;
    uint32_t free_fall_start_tick = 0;
    while (running) {
        float x, y, z;
        if (read_accel(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error\n");
            gpioDelay(100000);
            continue;
        }
        float mag = calc_magnitude(x, y, z);
        if (mag < free_fall_threshold) {
            if (!free_fall_active) {
                free_fall_active = true;
                free_fall_start_tick = gpioTick();
            } else if (gpioTick() - free_fall_start_tick > FREE_FALL_TIMEOUT_SEC * 1000000) {
                free_fall_active = false;
            }
        } else {
            free_fall_active = false;
        }
        if (free_fall_active && mag > impact_threshold) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(1000000);
            gpioWrite(BUZZER_PIN, 0);
            free_fall_active = false;
        }
        gpioDelay(SAMPLE_DELAY_US);
    }
    cleanup();
    return 0;
}

