#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LIS3DH_ADDR_DEFAULT 0x19
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lis3dh_init(int handle) {
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL1, 0x77) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL1 register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL4, 0x08) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL4 register\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static void log_data(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        fprintf(stderr, "Error: Failed to execute shutdown command\n");
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x18 || i2c_address > 0x1B) {
                    fprintf(stderr, "Error: Invalid I2C address 0x%X (must be 0x18-0x1B)\n", i2c_address);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address_hex] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%X\n", i2c_address);
        gpioTerminate();
        return 0;
    }

    if (i2cReadByteData(i2c_handle, LIS3DH_REG_WHO_AM_I) != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: LIS3DH not detected (WHO_AM_I mismatch)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (lis3dh_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    while (running) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_data(x, y, z);
                shutdown_system();
                break;
            }
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data, using zeros\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

