/*
 * Autonomous line-following robot for Raspberry Pi 5.
 *
 * Hardware:
 *   SunFounder 3-Way Tracking Sensor (IR reflectance, digital GPIO):
 *     Left  -> GPIO4  (BCM)
 *     Center-> GPIO17 (BCM)
 *     Right -> GPIO27 (BCM)
 *   Alert LED/buzzer (active-high):
 *     Alert -> GPIO22 (BCM)
 *
 * Behaviour:
 *   - Polls sensors every 10 ms.
 *   - Logs readings into a circular buffer (size 5).
 *   - Drives alert HIGH for 2 s when the center sensor reads "no line"
 *     for five consecutive readings.
 *   - Forward  when center detects a line.
 *   - Left     when left  sensor detects a line.
 *   - Right    when right sensor detects a line.
 *   - Stop     when all sensors read "no line".
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o line_follow line_follow.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_SENSOR_PIN   4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

/* ---- Circular buffer ---- */
#define BUFFER_SIZE 5

/* ---- Timing ---- */
#define POLL_DELAY_US  10000   /* 10 ms */
#define ALERT_DURATION_S 2

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_ready = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 (line detected) or 1 (no line / object detected) on success,
 * or -1 on read error.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d (rc=%d)\n", pin, v);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                      */
/* ------------------------------------------------------------------ */
typedef struct {
    int left[BUFFER_SIZE];
    int center[BUFFER_SIZE];
    int right[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, int l, int c, int r)
{
    cb->left[cb->head]  = l;
    cb->center[cb->head] = c;
    cb->right[cb->head] = r;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ------------------------------------------------------------------ */
/* Alert / buzzer                                                       */
/* ------------------------------------------------------------------ */
static void trigger_alert(int duration_s)
{
    if (gpioWrite(ALERT_PIN, 1) < 0)
        fprintf(stderr, "gpioWrite(ALERT, HIGH) failed\n");

    /*
     * Sleep in 100 ms slices so we can respond to signals promptly.
     */
    for (int i = 0; i < duration_s * 10 && g_running; i++)
        gpioDelay(100000);

    if (gpioWrite(ALERT_PIN, 0) < 0)
        fprintf(stderr, "gpioWrite(ALERT, LOW) failed\n");
}

/* ------------------------------------------------------------------ */
/* Motor control placeholders (implement per robot hardware)           */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    printf("Motor: forward\n");
}

static void motor_left(void)
{
    printf("Motor: left\n");
}

static void motor_right(void)
{
    printf("Motor: right\n");
}

static void motor_stop(void)
{
    printf("Motor: stop\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_ready) {
        gpioWrite(ALERT_PIN, 0);
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for sensor pins\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure alert pin as output, initial LOW ---- */
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0 ||
        gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "gpioSetMode/gpioWrite failed for ALERT pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize circular buffer ---- */
    CircularBuffer cb;
    cb_init(&cb);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int l = read_sensor(LEFT_SENSOR_PIN);
        int c = read_sensor(CENTER_SENSOR_PIN);
        int r = read_sensor(RIGHT_SENSOR_PIN);

        if (l < 0 || c < 0 || r < 0) {
            fprintf(stderr, "Sensor read error — stopping for safety\n");
            motor_stop();
            break;
        }

        cb_add(&cb, l, c, r);

        /*
         * No-line alert: centre sensor reads 1 (no line) for all
         * entries in the buffer.
         */
        bool no_line_persistent = true;
        for (int i = 0; i < cb.count; i++) {
            if (cb.center[i] == 0) {
                no_line_persistent = false;
                break;
            }
        }
        if (no_line_persistent && cb.count == BUFFER_SIZE) {
            trigger_alert(ALERT_DURATION_S);
        }

        /*
         * Line-following decisions (centre sensor = line, 0;
         * left/right sensors = line, 0).
         */
        if (c == 0) {
            motor_forward();
        } else if (l == 0) {
            motor_left();
        } else if (r == 0) {
            motor_right();
        } else {
            motor_stop();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful cleanup ---- */
    motor_stop();
    cleanup();
    printf("Exited cleanly.\n");
    return EXIT_SUCCESS;
}

