#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x48
#define RELAY_GPIO 17
#define THRESHOLD 5.0
#define LOG_FILE "magnetic_events.txt"
#define POLL_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    } else {
        fprintf(fp, "(unknown time): %s\n", msg);
    }
    fclose(fp);
}

static int read_si7210(int handle, float *field_mt) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, 0x00);
    if (rc < 0) {
        log_event("I2C write (reg select) failed");
        return -1;
    }
    gpioDelay(1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        log_event("I2C read failed");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *field_mt = (float)raw * 0.1;
    return 0;
}

static void set_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    set_relay(0);

    log_event("Program started");

    while (running) {
        float field;
        if (read_si7210(i2c_handle, &field) != 0) {
            set_relay(0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Field: %.2f mT", field);
        log_event(msg);

        if (field > THRESHOLD) {
            set_relay(1);
        } else {
            set_relay(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_relay(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

