#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int set_relay(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            perror("recv failed");
            close(client_fd);
            continue;
        }
        if (bytes_received == 0) {
            printf("Client disconnected\n");
            close(client_fd);
            continue;
        }
        buffer[bytes_received] = '\0';

        char command[BUFFER_SIZE];
        strncpy(command, buffer, sizeof(command) - 1);
        command[sizeof(command) - 1] = '\0';

        char *cmd = strtok(command, " \r\n");
        if (!cmd) {
            log_event("Invalid command: empty");
            const char *msg = "Invalid command\n";
            send(client_fd, msg, strlen(msg), 0);
            continue;
        }

        if (strcasecmp(cmd, "ON") == 0) {
            if (set_relay(1) == 0) {
                log_event("Relay activated");
                const char *msg = "Relay activated\n";
                send(client_fd, msg, strlen(msg), 0);
            } else {
                log_event("Failed to activate relay");
                const char *msg = "Failed to activate relay\n";
                send(client_fd, msg, strlen(msg), 0);
            }
        } else if (strcasecmp(cmd, "OFF") == 0) {
            if (set_relay(0) == 0) {
                log_event("Relay deactivated");
                const char *msg = "Relay deactivated\n";
                send(client_fd, msg, strlen(msg), 0);
            } else {
                log_event("Failed to deactivate relay");
                const char *msg = "Failed to deactivate relay\n";
                send(client_fd, msg, strlen(msg), 0);
            }
        } else {
            log_event("Invalid command");
            const char *msg = "Invalid command\n";
            send(client_fd, msg, strlen(msg), 0);
        }

        close(client_fd);
        client_fd = -1;
    }

    printf("Shutting down...\n");
    log_event("Server stopped");
    cleanup();
    return EXIT_SUCCESS;
}

