#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x50
#define SENSOR2_ADDR   0x51
#define RELAY_GPIO     18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US  100000

/* Sensirion SLF3S-1300F: 3-byte read, bytes 0-1 = flow, byte 2 = CRC-8 */
#define FLOW_BYTES     3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_h1 = -1;
static int g_i2c_h2 = -1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF, no final XOR) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ---- Read flow rate from one sensor ----
 * Returns 0 on success (flow_rate set), -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[FLOW_BYTES];
    int n = i2cReadDevice(handle, (char *)buf, FLOW_BYTES);
    if (n != FLOW_BYTES) {
        fprintf(stderr, "I2C read failed (handle %d): got %d bytes, expected %d\n",
                handle, n, FLOW_BYTES);
        return -1;
    }
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return -2;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_rate = (float)raw / 1000.0f;   /* ml/min */
    return 0;
}

/* ---- Log flow data with millisecond timestamp ---- */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen("flow_log.txt", "a");
    if (!fp) {
        perror("fopen(flow_log.txt)");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ---- Control relay based on flow thresholds ---- */
static void control_relay(float f1, float f2)
{
    int energize = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, energize) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", RELAY_GPIO, energize);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_h2);
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Start continuous measurement on both sensors (2-byte command) */
    uint8_t start_cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(g_i2c_h1, (char *)start_cmd, 2) != 0) {
        fprintf(stderr, "Start measurement failed for sensor 1\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteDevice(g_i2c_h2, (char *)start_cmd, 2) != 0) {
        fprintf(stderr, "Start measurement failed for sensor 2\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-1300F sensors (0x%02X, 0x%02X) on I2C bus %d. "
           "Relay on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR1_ADDR, SENSOR2_ADDR, I2C_BUS, RELAY_GPIO);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow_rate(g_i2c_h1, &f1);
        int r2 = read_flow_rate(g_i2c_h2, &f2);

        if (r1 == 0 && r2 == 0) {
            log_flow_data(f1, f2);
            control_relay(f1, f2);
        } else {
            if (r1 != 0)
                fprintf(stderr, "Sensor 1 read error (code %d)\n", r1);
            if (r2 != 0)
                fprintf(stderr, "Sensor 2 read error (code %d)\n", r2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

