#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>

/* ---- Pin definitions (BCM numbering) ---- */
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

/* ---- Timing constants (microseconds) ---- */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_REQUIRED_POLLS 3        /* 3 polls = 600 ms */

/* ---- Motor state ---- */
typedef enum { MOTOR_STOP, MOTOR_RUN } motor_state_t;

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static motor_state_t g_motor_state = MOTOR_STOP;
static int g_dry_polls = 0;

/* ---- Function prototypes ---- */
static int  gpio_init(void);
static int  gpio_set_mode(unsigned pin, unsigned mode);
static int  gpio_set_pull(unsigned pin, unsigned pull);
static int  gpio_write(unsigned pin, unsigned value);
static int  motor_start(void);
static int  motor_stop(void);
static int  motor_run(void);
static int  motor_stop_and_wait(void);
static int  motor_stop_and_release(void);
static int  motor_stop_and_cleanup(void);
static void signal_handler(int sig);
static void log_event(int priority, const char *msg);

/* ------------------------------------------------------------------ */
/*  GPIO helpers (pigpio-style API — real pigpio must be linked)       */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    return 0;  /* pigpio must be initialised elsewhere in real app */
}

static int gpio_set_mode(unsigned pin, unsigned mode)
{
    return 0;  /* gpioSetMode(pin, mode) */
}

static int gpio_set_pull(unsigned pin, unsigned pull)
{
    return 0;  /* gpioSetPullUpDown(pin, pull) */
}

static int gpio_write(unsigned pin, unsigned value)
{
    return 0;  /* gpioWrite(pin, value) */
}

/* ------------------------------------------------------------------ */
/*  Motor control (L298N via pigpio)                                  */
/* ------------------------------------------------------------------ */

static int motor_start(void)
{
    if (gpio_write(MOTOR_ENA_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to set ENA high");
        return -1;
    }
    if (gpio_write(MOTOR_IN1_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to set IN1 high");
        return -1;
    }
    if (gpio_write(MOTOR_IN2_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to set IN2 low");
        return -1;
    }
    g_motor_state = MOTOR_RUN;
    log_event(LOG_INFO, "Motor started (close window)");
    return 0;
}

static int motor_stop(void)
{
    if (gpio_write(MOTOR_ENA_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to set ENA low");
        return -1;
    }
    if (gpio_write(MOTOR_IN1_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to set IN1 low");
        return -1;
    }
    if (gpio_write(MOTOR_IN2_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to set IN2 low");
        return -1;
    }
    g_motor_state = MOTOR_STOP;
    log_event(LOG_INFO, "Motor stopped");
    return 0;
}

static int motor_run(void)
{
    return motor_start();
}

static int motor_stop_and_wait(void)
{
    if (motor_stop() != 0)
        return -1;
    usleep(MOTOR_RUN_US);
    return 0;
}

static int motor_stop_and_release(void)
{
    if (motor_stop() != 0)
        return -1;
    return 0;
}

static int motor_stop_and_cleanup(void)
{
    if (motor_stop() != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_event(LOG_ERR, "Failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event(LOG_ERR, "Failed to register SIGTERM handler");
    }

    if (gpio_init() != 0) {
        log_event(LOG_ERR, "GPIO initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_set_mode(RAIN_SENSOR_PIN, 0) != 0) {
        log_event(LOG_ERR, "Failed to set rain sensor pin as input");
        motor_stop_and_cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpio_set_pull(RAIN_SENSOR_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to set rain sensor pull-up");
        motor_stop_and_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_set_mode(MOTOR_ENA_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to set ENA pin as output");
        motor_stop_and_cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(MOTOR_IN1_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to set IN1 pin as output");
        motor_stop_and_cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(MOTOR_IN2_PIN, 1) != 0) {
        log_event(LOG_ERR, "Failed to set IN2 pin as output");
        motor_stop_and_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Rain sensor monitoring started");

    int last_state = 1;  /* assume dry (pull-up high) */

    while (g_running) {
        int rain_detected = gpio_read(RAIN_SENSOR_PIN);
        if (rain_detected < 0) {
            log_event(LOG_ERR, "Failed to read rain sensor");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int current_state = rain_detected;

        /* Rising edge: dry -> wet */
        if (current_state == 0 && last_state == 1) {
            if (g_motor_state == MOTOR_STOP) {
                log_event(LOG_INFO, "Rain detected — closing window");
                if (motor_run() != 0) {
                    log_event(LOG_ERR, "Motor start failed");
                } else {
                    if (motor_stop_and_wait() != 0) {
                        log_event(LOG_ERR, "Motor run-time wait failed");
                    }
                    if (motor_stop_and_release() != 0) {
                        log_event(LOG_ERR, "Motor release failed");
                    }
                }
            } else {
                log_event(LOG_WARNING, "Rain detected but motor already running");
            }
        }
        /* Falling edge: wet -> dry */
        else if (current_state == 1 && last_state == 0) {
            g_dry_polls++;
            if (g_dry_polls >= DRY_REQUIRED_POLLS) {
                log_event(LOG_INFO, "Sensor dry — re-arm");
                g_dry_polls = 0;
            }
        } else {
            g_dry_polls = 0;
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down — stopping motor");
    motor_stop_and_cleanup();
    log_event(LOG_INFO, "Shutdown complete");
    closelog();
    return EXIT_SUCCESS;
}

