#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PW        2000   /* microseconds */
#define UNLOCK_PW       1000
#define DEBOUNCE_US    50000  /* 50 ms debounce / release wait */
#define POLL_US        10000  /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned pin, unsigned pud)
{
    if (gpioSetPullUpDown(pin, pud) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%u, %u) failed\n", pin, pud);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_servo(unsigned pin, unsigned pw)
{
    if (gpioServo(pin, pw) != 0) {
        fprintf(stderr, "gpioServo(%u, %u) failed\n", pin, pw);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses before terminating pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SERVO_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(LOCK_BUTTON, PI_INPUT)  != 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo door lock control started.\n");
    printf("  Servo pin : BCM %d\n", SERVO_PIN);
    printf("  Lock btn  : BCM %d\n", LOCK_BUTTON);
    printf("  Unlock btn: BCM %d\n", UNLOCK_BUTTON);
    printf("  Lock pulse: %d us\n", LOCK_PW);
    printf("  Unlock pulse: %d us\n", UNLOCK_PW);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        if (lock_pressed) {
            printf("Lock button pressed -> locking...\n");
            if (safe_servo(SERVO_PIN, LOCK_PW) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            /* Wait for release + debounce */
            while (g_running && gpioRead(LOCK_BUTTON) == 0)
                gpioDelay(DEBOUNCE_US);
        } else if (unlock_pressed) {
            printf("Unlock button pressed -> unlocking...\n");
            if (safe_servo(SERVO_PIN, UNLOCK_PW) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0)
                gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Servo door lock control stopped.\n");
    return EXIT_SUCCESS;
}

