#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN      4
#define LED_PIN      17
#define LOG_FILE     "security_log.txt"
#define POLL_US      100000   /* 100 ms */
#define LED_ON_US    60000000 /* 60 s  */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, int duration_sec)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s %s", ts, event_type,
                duration_sec >= 0 ? "duration=" : "") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (duration_sec >= 0) {
        if (fprintf(fp, "%d", duration_sec) < 0) {
            perror("fprintf()");
            fclose(fp);
            return -1;
        }
    }

    if (fprintf(fp, "\n") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is OFF at startup */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. PIR=GPIO%d, LED=GPIO%d. Ctrl+C to exit.\n",
           PIR_PIN, LED_PIN);

    int last_pir = 0;
    int led_on   = 0;

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        /* Rising edge: motion detected */
        if (pir == 1 && last_pir == 0) {
            printf("Motion detected!\n");

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN, 1) failed\n");
                break;
            }
            led_on = 1;

            if (log_event("ACTIVATION", -1) != 0) {
                fprintf(stderr, "Failed to log activation event\n");
                break;
            }

            /* Keep floodlight on for 60 s, checking for shutdown */
            for (int i = 0; i < 60 && g_running; i++) {
                gpioDelay(1000000); /* 1 s */
            }

            if (!g_running) {
                break;
            }

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
                break;
            }
            led_on = 0;

            if (log_event("DEACTIVATION", 60) != 0) {
                fprintf(stderr, "Failed to log deactivation event\n");
                break;
            }
        }

        last_pir = pir;
        gpioDelay(POLL_US);
    }

    /* --- Clean shutdown --- */
    if (led_on) {
        gpioWrite(LED_PIN, 0);
    }
    gpioTerminate();

    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

