/*
 * MPR121 Capacitive Touch Sensor -> Relay Toggle on Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1)
 *   MPR121 SCL -> GPIO3 (I2C bus 1)
 *   MPR121 ADDR -> GND (I2C address 0x5E)
 *   Relay IN  -> GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 *   (pigpio must be installed and the library must be accessible)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define MPR121_ADDR          0x5E
#define RELAY_GPIO           17

#define DEBOUNCE_MS          200
#define POLL_DELAY_US        10000   /* 10 ms */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELE0_TOUCH    0x41
#define MPR121_ELE0_RELEASE  0x42
#define MPR121_MHD_R         0x2B
#define MPR121_NHD_R         0x2C
#define MPR121_NCL_R         0x2D
#define MPR121_FDL_R         0x2E
#define MPR121_MHD_F         0x2F
#define MPR121_NHD_F         0x30
#define MPR121_NCL_F         0x31
#define MPR121_FDL_F         0x32
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E
#define MPR121_SOFTRESET     0x80

/* --------------------------- Global State ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static bool g_relay_state = false;

/* ------------------------- Signal Handler ------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------- I2C Helpers --------------------------------- */

/*
 * Write a single byte to an MPR121 register.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an MPR121 register.
 * Returns the byte value (0-255) on success, -1 on failure.
 */
static int mpr121_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    return rc;
}

/*
 * Initialize the MPR121 sensor with documented default values.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Baseline filtering (rising / falling) */
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write_reg(MPR121_E0TTH, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT = 0.5 µs, SFI = 4 samples */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

/*
 * Read the 16-bit touch status register.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_read_touch_status(uint16_t *status)
{
    int lo = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (lo < 0)
        return -1;

    int hi = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (hi < 0)
        return -1;

    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------- Relay Control ------------------------------- */

static int relay_set(bool on)
{
    int rc = gpioWrite(RELAY_GPIO, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d: %s\n",
                RELAY_GPIO, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPR121 address */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, MPR121_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPR121 sensor */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output and ensure it is OFF */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (relay_set(false) < 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_relay_state = false;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay toggle ready. Touch electrode 0 to toggle relay.\n");
    printf("Press Ctrl+C to exit.\n");

    uint32_t last_touch_ms = 0;

    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status; retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Check for a fresh rising edge on electrode 0 */
        if (touch_status & 0x0001) {
            uint32_t now_ms = gpioTick() / 1000;
            if (now_ms - last_touch_ms >= DEBOUNCE_MS) {
                g_relay_state = !g_relay_state;
                if (relay_set(g_relay_state) < 0) {
                    fprintf(stderr, "Failed to set relay state\n");
                } else {
                    printf("Relay toggled to %s\n", g_relay_state ? "ON" : "OFF");
                }
                last_touch_ms = now_ms;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --------------------------- Cleanup ------------------------------- */

    printf("\nShutting down...\n");
    relay_set(false);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

