#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <stdarg.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(stderr, "%s ", ts);
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");
    if (log_file) {
        fprintf(log_file, "%s ", ts);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
    va_end(args);
    vsyslog(LOG_INFO, format, args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        log_event("ERROR: gpioInitialise failed");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        log_event("ERROR: gpioSetMode(SERVO_PIN) failed");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_event("ERROR: gpioSetMode(PIR_PIN) failed");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    int pulse_us = SERVO_MIN_PULSE_US + (int)((long)(angle - SERVO_MIN_ANGLE) *
            (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) /
            (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        log_event("ERROR: gpioServo(%d) failed", pulse_us);
    } else {
        log_event("Servo set to angle %d (pulse %d us)", angle, pulse_us);
    }
}

static int read_pir(void) {
    int val = gpioRead(PIR_PIN);
    if (val < 0) {
        log_event("ERROR: gpioRead(PIR_PIN) failed");
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;
    while ((bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';
        log_event("Received: %s", buffer);
        if (strcmp(buffer, "PIR") == 0) {
            int pir = read_pir();
            if (pir >= 0) {
                char response[32];
                snprintf(response, sizeof(response), "PIR:%d", pir);
                send(client_fd, response, strlen(response), 0);
                log_event("Sent: %s", response);
            } else {
                log_event("ERROR: Failed to read PIR sensor");
            }
        } else if (strncmp(buffer, "the library's API call", 23) == 0) {
            int angle = atoi(buffer + 23);
            if (angle >= SERVO_MIN_ANGLE && angle <= SERVO_MAX_ANGLE) {
                set_servo_angle(angle);
            } else {
                log_event("ERROR: Invalid angle %d (must be %d-%d)",
                          angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
            }
        } else {
            log_event("ERROR: Unknown command: %s", buffer);
        }
    }
    if (bytes_received < 0) {
        log_event("ERROR: recv failed: %s", strerror(errno));
    }
    close(client_fd);
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        closelog();
        return EXIT_FAILURE;
    }
    log_event("INFO: Starting security server");
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_event("ERROR: sigaction failed: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }
    if (init_gpio() != 0) {
        log_event("ERROR: GPIO initialization failed");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("ERROR: socket failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("ERROR: setsockopt(SO_REUSEADDR) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("ERROR: bind failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (listen(server_fd, 3) < 0) {
        log_event("ERROR: listen failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("INFO: Listening on port %d", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_event("ERROR: accept failed: %s", strerror(errno));
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_event("INFO: Connection from %s:%d", client_ip, ntohs(client_addr.sin_port));
        handle_client(client_fd);
    }
    log_event("INFO: Shutting down");
    cleanup();
    return EXIT_SUCCESS;
