/*
 * Grow-light controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - BH1750 ambient-light sensor on I2C1 (GPIO2 = SDA, GPIO3 = SCL)
 *     Address: 0x29 (ADDR pin tied to GND)
 *   - Grow-light relay on GPIO23 (BCM)
 *
 * Behaviour:
 *   - Samples ambient light every 2 s.
 *   - Drives the relay ON when lux < 150, OFF when lux >= 150.
 *   - Logs timestamped lux readings to grow_log.txt.
 *   - On I2C or file error, logs the event and retries on the next cycle.
 *   - Clean shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS              1
#define BH1750_ADDR          0x29
#define BH1750_POWER_ON      0x01
#define BH1750_RESET         0x07
#define BH1750_CONT_HIGHRES  0x10
#define BH1750_MEAS_DELAY_US 120000   /* 120 ms (max conversion time) */
#define SAMPLE_INTERVAL_US   2000000  /* 2 s */
#define LUX_THRESHOLD        150
#define GPIO_RELAY           23
#define LOG_FILE             "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* BH1750 helpers                                                      */
/* ------------------------------------------------------------------ */
static int bh1750_power_on(void)
{
    if (i2cWriteByte(g_i2c_handle, BH1750_POWER_ON) < 0) {
        log_message("BH1750 power-on write failed");
        return -1;
    }
    return 0;
}

static int bh1750_reset(void)
{
    if (i2cWriteByte(g_i2c_handle, BH1750_RESET) < 0) {
        log_message("BH1750 reset write failed");
        return -1;
    }
    return 0;
}

static int bh1750_start_highres(void)
{
    if (i2cWriteByte(g_i2c_handle, BH1750_CONT_HIGHRES) < 0) {
        log_message("BH1750 start-highres write failed");
        return -1;
    }
    return 0;
}

/*
 * Read 2 bytes of lux data.
 * Returns 0 on success and stores lux in *out_lux.
 * Returns -1 on I2C error.
 */
static int bh1750_read_lux(uint16_t *out_lux)
{
    char buf[2];
    int n = i2cReadDevice(g_i2c_handle, buf, 2);
    if (n != 2) {
        log_message("BH1750 I2C read failed (short read)");
        return -1;
    }
    *out_lux = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static void control_relay(int state)
{
    if (gpioWrite(GPIO_RELAY, state) < 0)
        log_message("Failed to write relay GPIO");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Relay GPIO setup ------------------------------------------ */
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RELAY);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);   /* relay OFF at startup */

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init ------------------------------------------------ */
    if (bh1750_power_on() < 0 || bh1750_reset() < 0 || bh1750_start_highres() < 0) {
        fprintf(stderr, "BH1750 initialisation failed; sensor may be absent.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Grow-light controller started");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t lux = 0;

        if (bh1750_read_lux(&lux) == 0) {
            char line[128];
            snprintf(line, sizeof(line), "Lux: %u", lux);
            log_message(line);

            if (lux < LUX_THRESHOLD) {
                control_relay(1);
                log_message("Lux below threshold — relay ON");
            } else {
                control_relay(0);
                log_message("Lux above threshold — relay OFF");
            }
        } else {
            /* Sensor error: ensure relay is OFF for safety, then retry */
            control_relay(0);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 20 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

