/*
 * load_cell_lock.c — Raspberry Pi 3 Model B+
 *
 * TAL220B load cell + HX711 (bit-banged) -> solenoid lock.
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o load_cell_lock load_cell_lock.c -lgpiod
 *
 * Usage:
 *   ./load_cell_lock --threshold 1000 --scale 1.0 --duration 200
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#define HX711_DOUT_LINE  23
#define HX711_SCK_LINE   24
#define SOLENOID_LINE    25

#define DEFAULT_THRESHOLD  1000.0
#define DEFAULT_SCALE      1.0
#define DEFAULT_DURATION   200
#define DEFAULT_READINGS   5
#define DEFAULT_TARE_READINGS 10
#define HX711_TIMEOUT_US  1000000  /* 1 s */
#define POLL_INTERVAL_US  500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
