static int hx711_wait_low(struct gpiod_line *dout)
{
    for (int i = 0; i < 100; ++i) {
        if (gpiod_line_get_value(dout) == 0)
            return 0;
        usleep(1000);
    }
    return -1;
}

/*
 * Read one 24-bit two's-complement sample from the HX711.
 * Returns 0 on success, -1 on timeout or line error.
 */
static int hx711_read_sample(struct gpiod_line *dout, struct gpiod_line *sck,
                              int32_t *out)
{
    if (hx711_wait_low(dout) < 0)
        return -1;

    uint32_t value = 0;
    for (int i = 0; i < 24; ++i) {
        if (gpiod_line_set_value(sck, 1) < 0)
            return -1;
