        value <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0)
            return -1;
        if (bit)
            value |= 1u;
        if (gpiod_line_set_value(sck, 0) < 0)
            return -1;
        usleep(1);
    }

    /* 25th clock pulse: select Channel A, gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0)
        return -1;
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0)
        return -1;
    usleep(1);

    /* Sign-extend 24-bit two's complement to 32-bit */
    if (value & 0x800000u)
        value |= 0xFF000000u;

    *out = (int32_t)value;
    return 0;
}

/*
 * Average `n` samples. Returns 0 on success, -1 on error.
 */
static int hx711_read_average(struct gpiod_line *dout, struct gpiod_line *sck,
                               int n, int32_t *out)
{
    int64_t sum = 0;
    for (int i = 0; i < n; ++i) {
        int32_t v;
        if (hx711_read_sample(dout, sck, &v) < 0)
            return -1;
        sum += v;
        usleep(1000);
    }
    *out = (int32_t)(sum / n);
    return 0;
}

