    }
    return 0;
}

static int solenoid_activate(struct gpiod_line *line, int duration_ms)
{
    if (solenoid_set(line, 1) < 0)
        return -1;
    usleep(duration_ms * 1000);
    return solenoid_set(line, 0);
}

/* ------------------------------------------------------------------ */
/* Tare                                                               */
/* ------------------------------------------------------------------ */

static int tare_load_cell(struct gpiod_line *dout, struct gpiod_line *sck,
                           int n, int32_t *offset)
{
    int64_t sum = 0;
    for (int i = 0; i < n; ++i) {
        int32_t v;
        if (hx711_read_sample(dout, sck, &v) < 0) {
            syslog(LOG_ERR, "Tare read %d/%d failed", i + 1, n);
            return -1;
        }
        sum += v;
        usleep(1000);
    }
    *offset = (int32_t)(sum / n);
    syslog(LOG_INFO, "Tare complete, offset = %d", *offset);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int threshold = (int)DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
