    struct gpiod_line *sck  = gpiod_chip_get_line(chip, HX711_SCK_LINE);
    struct gpiod_line *sol  = gpiod_chip_get_line(chip, SOLENOID_LINE);
    if (!dout || !sck || !sol) {
