static void log_message(int priority, const char *message)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }

    /* Ensure relay starts in the OFF state */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to initialise GPIO17 LOW");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: drive relay OFF and release the driver */
    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT connected to broker");

        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to topic");
        } else {
            log_message(LOG_INFO, "Subscribed to topic");
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "MQTT connection error: %s",
                 mosquitto_strerror(result));
        log_message(LOG_ERR, buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "MQTT unexpected disconnect: %s",
                 mosquitto_strerror(rc));
        log_message(LOG_ERR, buf);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_message(LOG_ERR, "Empty MQTT payload received");
        return;
    }

    char payload[MAX_PAYLOAD_LENGTH];
    size_t len = message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    /* Strip trailing newline / carriage return if present */
    payload[strcspn(payload, "\r\n")] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) == 0) {
            log_message(LOG_INFO, "Relay ON");
        } else {
            log_message(LOG_ERR, "Failed to set GPIO17 HIGH");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) == 0) {
            log_message(LOG_INFO, "Relay OFF");
        } else {
            log_message(LOG_ERR, "Failed to set GPIO17 LOW");
        }
    } else {
        char buf[MAX_PAYLOAD_LENGTH + 64];
        snprintf(buf, sizeof(buf), "Invalid payload: %s", payload);
        log_message(LOG_ERR, buf);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                               MQTT_BROKER_PORT, KEEPALIVE_S);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to connect to broker: %s",
                 mosquitto_strerror(rc));
        log_message(LOG_ERR, buf);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to start MQTT loop: %s",
                 mosquitto_strerror(rc));
        log_message(LOG_ERR, buf);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (g_running) {
        sleep(1);
    }

    /* Graceful shutdown */
    log_message(LOG_INFO, "Shutting down...");
    mosquitto_loop_stop(g_mosq, false);
    mosquitto_disconnect(g_mosq);
    mosquitto_destroy(g_mosq);
    g_mosq = NULL;
    mosquitto_lib_cleanup();
    cleanup_gpio();

    log_message(LOG_INFO, "Shutdown complete");
    return EXIT_SUCCESS;
}

