#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_PERIOD_US 20000

static const int servo_pins[5] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
static const int servo_pulse_widths[5] = {1000, 1500, 2000, 500, 2500};

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

static void set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }
    gpioServo(pin, pulse_width);
}

static void move_servos(void) {
    for (int i = 0; i < 5; i++) {
        set_servo_pulse_width(servo_pins[i], servo_pulse_widths[i]);
    }
}

static void hold_position(void) {
    sleep(3);
}

static void stop_servos(void) {
    for (int i = 0; i < 5; i++) {
        gpioServo(servo_pins[i], 0);
    }
}

static void cleanup_gpio(void) {
    stop_servos();
    gpioTerminate();
}

int main(void) {
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    move_servos();
    hold_position();
    stop_servos();
    cleanup_gpio();

    return EXIT_SUCCESS;
}

