#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN  17   /* DRV8833 IN1  */
#define MOTOR_A_DIR_PIN  18   /* DRV8833 IN2  */
#define MOTOR_B_PWM_PIN  22   /* DRV8833 IN3  */
#define MOTOR_B_DIR_PIN  23   /* DRV8833 IN4  */

#define ENC_A_PHASE_A_PIN 4
#define ENC_A_PHASE_B_PIN 5
#define ENC_B_PHASE_A_PIN 6
#define ENC_B_PHASE_B_PIN 12

/* ---- Control parameters ---- */
#define TARGET_RPM        50.0
#define PWM_FREQUENCY     10000   /* Hz */
#define PWM_RANGE         255
#define LOOP_DELAY_US     100000  /* 100 ms */
#define STALL_TIMEOUT_S   2
#define ENCODER_TICKS_PER_REV 64
#define ENCODER_RATIO 1.0

/* ---- PI controller ---- */
#define KP 0.1
#define KI 0.01

/* ---- Globals ---- */
static volatile int32_t enc_a_ticks = 0;
static volatile int32_t enc_b_ticks = 0;
static volatile bool motor_a_running = false;
static volatile bool motor_b_running = false;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static void motor_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void motor_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_a(int pwm_duty, int direction);
static void set_motor_b(int pwm_duty, int direction);
static void stop_motor(int pwm_pin, int dir_pin);
static double calculate_rpm(int32_t *ticks, double elapsed_s);
static int pi_control(double error, double *integral, double *prev_error);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- ISR: increment tick counter on rising edge ---- */
static void motor_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    enc_a_ticks++;
}

static void motor_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    enc_b_ticks++;
}

/* ---- Drive Motor A: forward = PWM high on IN1, IN2 low ---- */
static void set_motor_a(int pwm_duty, int direction)
{
    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Invalid direction for Motor A: %d\n", direction);
        return;
    }
    if (pwm_duty < 0) pwm_duty = 0;
    if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

    if (direction == 0) {
        gpioWrite(MOTOR_A_DIR_PIN, 0);
        gpioPWM(MOTOR_A_PWM_PIN, pwm_duty);
    } else {
        gpioWrite(MOTOR_A_DIR_PIN, 1);
        gpioPWM(MOTOR_A_PWM_PIN, pwm_duty);
    }
    motor_a_running = true;
}

/* ---- Drive Motor B: forward = PWM high on IN3, IN4 low ---- */
static void set_motor_b(int pwm_duty, int direction)
{
    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Invalid direction for Motor B: %d\n", direction);
        return;
    }
    if (pwm_duty < 0) pwm_duty = 0;
    if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

    if (direction == 0) {
        gpioWrite(MOTOR_B_DIR_PIN, 0);
        gpioPWM(MOTOR_B_PWM_PIN, pwm_duty);
    } else {
        gpioWrite(MOTOR_B_DIR_PIN, 1);
        gpioPWM(MOTOR_B_PWM_PIN, pwm_duty);
    }
    motor_b_running = true;
}

/* ---- Stop both motors ---- */
static void stop_motor(int pwm_pin, int dir_pin)
{
    gpioWrite(dir_pin, 0);
    gpioPWM(pwm_pin, 0);
}

/* ---- RPM from tick count over elapsed seconds ---- */
static double calculate_rpm(int32_t *ticks, double elapsed_s)
{
    if (elapsed_s <= 0.0) return 0.0;
    double revs = (double)(*ticks) / (ENCODER_TICKS_PER_REV * ENCODER_RATIO);
    return revs / elapsed_s * 60.0;
}

/* ---- PI controller with anti-windup clamping ---- */
static int pi_control(double error, double *integral, double *prev_error)
{
    double output = KP * error + KI * (*integral);

    /* Anti-windup: clamp integral when output saturated */
    if (output > PWM_RANGE) {
        output = PWM_RANGE;
        *integral += error;
    } else if (output < 0) {
        output = 0;
        *integral += error;
    } else {
        *integral += error;
    }

    *prev_error = error;
    return (int)output;
}

/* ---- Release all resources ---- */
static void cleanup(void)
{
    stop_motor(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN);
    stop_motor(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN);
    gpioSetISRFuncEx(ENC_A_PHASE_A_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENC_A_PHASE_B_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENC_B_PHASE_A_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENC_B_PHASE_B_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENC_A_PHASE_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENC_A_PHASE_B_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENC_B_PHASE_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENC_B_PHASE_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set encoder pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISRs on rising edge */
    if (gpioSetISRFuncEx(ENC_A_PHASE_A_PIN, RISING_EDGE, 0, motor_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENC_A_PHASE_B_PIN, RISING_EDGE, 0, motor_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENC_B_PHASE_A_PIN, RISING_EDGE, 0, motor_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENC_B_PHASE_B_PIN, RISING_EDGE, 0, motor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register encoder ISRs\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize controller state */
    double integral_a = 0.0, prev_error_a = 0.0;
    double integral_b = 0.0, prev_error_b = 0.0;
    struct timespec last_time = {0, 0};
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    /* Signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_time.tv_sec) +
                         (now.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = now;

        /* Stall detection */
        if (motor_a_running && elapsed > STALL_TIMEOUT_S && enc_a_ticks == 0) {
            fprintf(stderr, "Warning: Motor A stalled (no ticks for %.0f s)\n",
                    STALL_TIMEOUT_S);
        }
        if (motor_b_running && elapsed > STALL_TIMEOUT_S && enc_b_ticks == 0) {
            fprintf(stderr, "Warning: Motor B stalled (no ticks for %.0f s)\n",
                    STALL_TIMEOUT_S);
        }

        /* Reset ticks for this interval */
        int32_t a_ticks = enc_a_ticks;
        int32_t b_ticks = enc_b_ticks;
        enc_a_ticks = 0;
        enc_b_ticks = 0;

        double rpm_a = calculate_rpm(&a_ticks, elapsed);
        double rpm_b = calculate_rpm(&b_ticks, elapsed);

        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        int pwm_a = pi_control(error_a, &integral_a, &prev_error_a);
        int pwm_b = pi_control(error_b, &integral_b, &prev_error_b);

        set_motor_a(pwm_a, 0);
        set_motor_b(pwm_b, 0);

        printf("Motor A: RPM=%.2f, PWM=%d, Motor B: RPM=%.2f, PWM=%d\n",
               rpm_a, pwm_a, rpm_b, pwm_b);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

