#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x29
#define RELAY_GPIO 17
#define LUX_DUSK 50
#define LUX_DAWN 200
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL_SEC 5
#define BH1750_MEAS_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static int read_lux(void) {
    if (i2cWriteByte(i2c_handle, 0x10) != 0) {
        fprintf(stderr, "Error sending measurement command to BH1750\n");
        return -1;
    }
    gpioDelay(BH1750_MEAS_MS * 1000);

    int raw = i2cReadWordData(i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "Error reading lux value from BH1750: %d\n", raw);
        return -1;
    }
    return (raw >> 8) & 0xFF;
}

static void control_relay(int lux) {
    if (lux < LUX_DUSK && relay_state == 0) {
        if (gpioWrite(RELAY_GPIO, 1) == 0) {
            relay_state = 1;
            printf("Relay ON\n");
        } else {
            fprintf(stderr, "Error activating relay\n");
        }
    } else if (lux > LUX_DAWN && relay_state == 1) {
        if (gpioWrite(RELAY_GPIO, 0) == 0) {
            relay_state = 0;
            printf("Relay OFF\n");
        } else {
            fprintf(stderr, "Error deactivating relay\n");
        }
    }
}

static void log_data(int lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Lux = %d, Relay = %s\n",
                timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting chicken coop light control...\n");

    while (running) {
        int lux = read_lux();
        if (lux >= 0) {
            control_relay(lux);
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Sensor read failed; relay deactivated for safety\n");
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_data(-1, 0);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("Shutting down...\n");
    cleanup();
    return 0;
}

