#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LOG_FILE "water_flow.log"
#define PULSES_PER_LITER 450.0
#define DEBOUNCE_US 1000000  /* 1 second debounce */
#define SAMPLE_INTERVAL_US 1000000  /* 1 second sample */
#define FLOW_THRESHOLD_OPEN 5.0
#define FLOW_THRESHOLD_CLOSE 4.5

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static pthread_mutex_t g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    if (!g_log_fp)
        return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "[%s] %s\n", ts, msg);
    fflush(g_log_fp);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&g_pulse_mutex);
    g_pulse_count++;
    pthread_mutex_unlock(&g_pulse_mutex);
}

static double calculate_lpm(int pulses, double elapsed_s)
{
    if (elapsed_s <= 0.0)
        return 0.0;
    double liters = (double)pulses / PULSES_PER_LITER;
