#define CONFIG_FILE "config.ini"
#define DISPENSING_LOG_FILE "dispensing_log.json"
#define PORT 12345
#define MAX_BUFFER_SIZE 1024
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_DELAY_US 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_PULSE_PERIOD_US 20000
#define SERVO_SETTLE_DELAY_US 1000000
#define DISPENSING_STABILIZE_DELAY_US 1000000
#define API_CALL_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int api_call_handle = -1;

typedef struct {
    float calibration_factor;
    float known_weight;
} calibration_data_t;

static calibration_data_t calibration_data = {1.0f, 100.0f};

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_config(const char *filename, calibration_data_t *data) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            data->calibration_factor = strtof(value, NULL);
        } else if (strcmp(key, "known_weight") == 0) {
            data->known_weight = strtof(value, NULL);
        }
    }
    fclose(fp);
    return 0;
}

static int hx711_read(int data_pin, int sck_pin, long *raw_value) {
    int timeout = 0;
    while (gpioRead(data_pin) == 1) {
        gpioDelay(HX711_TIMEOUT_DELAY_US);
        timeout++;
        if (timeout >= HX711_TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "Error: HX711 timeout (DATA stuck HIGH).\n");
            return -1;
        }
    }
    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1);
        value = (value << 1) | gpioRead(data_pin);
        gpioWrite(sck_pin, 0);
        gpioDelay(1);
    }
    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);
    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    *raw_value = value;
    return 0;
}

static float calibrate_weight(long raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

static int set_servo_pulse_width(int pin, int pulse_width_us) {
    if (pulse_width_us < SERVO_MIN_PULSE_WIDTH || pulse_width_us > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid servo pulse width %d.\n", pulse_width_us);
        return -1;
    }
    if (gpioServo(pin, pulse_width_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d.\n", pin);
        return -1;
    }
    return 0;
}

static int dispense_ingredient(float target_weight, float calibration_factor) {
    long raw_value;
    if (hx711_read(HX711_DATA_PIN, HX711_SCK_PIN, &raw_value) != 0) {
        fprintf(stderr, "Error: Failed to read HX711 sensor.\n");
        return -1;
    }
    float actual_weight = calibrate_weight(raw_value, calibration_factor);
    int pulse_width = (int)((target_weight / 100.0f) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    if (set_servo_pulse_width(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        return -1;
    }
    gpioDelay(SERVO_SETTLE_DELAY_US);
    gpioServo(SERVO_PIN, 0);
    gpioDelay(DISPENSING_STABILIZE_DELAY_US);
    if (hx711_read(HX711_DATA_PIN, HX711_SCK_PIN, &raw_value) != 0) {
        fprintf(stderr, "Error: Failed to read HX711 sensor after dispensing.\n");
        return -1;
    }
    actual_weight = calibrate_weight(raw_value, calibration_factor);
    return 0;
}

static int log_dispensing_event(float target_weight, float actual_weight, const char *error_message) {
    FILE *fp = fopen(DISPENSING_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", DISPENSING_LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n", timestamp, target_weight, actual_weight, error_message ? error_message : "none");
    fclose(fp);
    return 0;
}

