#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INITIAL_ANGLE 90
#define STEP_SIZE 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width = (int)(((float)angle / (float)MAX_ANGLE) *
                            (float)(MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) +
                            (float)MIN_PULSE_WIDTH);

    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }

    int ret = gpioServo(SERVO_PIN, pulse_width);
    if (ret != 0) {
        fprintf(stderr, "Error: gpioServo failed with code %d\n", ret);
        return -1;
    }
    return 0;
}

static int adjust_servo_angle(int *angle, char key) {
    if (key == '+') {
        *angle += STEP_SIZE;
        if (*angle > MAX_ANGLE) *angle = MAX_ANGLE;
    } else if (key == '-') {
        *angle -= STEP_SIZE;
        if (*angle < MIN_ANGLE) *angle = MIN_ANGLE;
    } else {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioServo(0) failed to stop PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(INITIAL_ANGLE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    struct termios oldt, newt;
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &newt) != 0) {
        perror("tcsetattr");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int angle = INITIAL_ANGLE;
    int exit_code = EXIT_SUCCESS;

    while (running) {
        int c = getchar();
        if (c == 'q') {
            break;
        } else if (c == '+' || c == '-') {
            if (adjust_servo_angle(&angle, (char)c) == 0) {
                if (set_servo_angle(angle) != 0) {
                    exit_code = EXIT_FAILURE;
                    break;
                }
                printf("Angle: %d degrees\n", angle);
                fflush(stdout);
            }
        }
    }

    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Warning: gpioServo(0) failed to stop PWM on exit\n");
    }

    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);
    gpioTerminate();

    if (exit_code == EXIT_SUCCESS) {
        printf("\nServo control stopped.\n");
    }
    return exit_code;
}

