        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(HALL_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", HALL_SENSOR_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(HALL_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", HALL_SENSOR_GPIO);
        goto cleanup;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- state variables ---- */
    int      pulse_count = 0;
    uint32_t last_tick   = 0;
    int      last_level  = 1;   /* assume idle high */
    int      first_edge  = 1;

    printf("Monitoring Hall sensor on GPIO %d (rising edge, 2 ms debounce).\n",
           HALL_SENSOR_GPIO);
    printf("Logging to %s every %d s. Press Ctrl-C to stop.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL);

    /* ---- main loop ---- */
    while (g_running) {
        uint32_t now_tick = gpioTick();

        /* pigpio ticks are 32-bit microseconds; handle wrap-around */
        uint32_t elapsed = now_tick - last_tick;
        if (elapsed < DEBOUNCE_US) {
            /* within debounce window — ignore */
            int level = gpioRead(HALL_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "gpioRead failed on GPIO %d\n", HALL_SENSOR_GPIO);
                goto cleanup;
            }
            if (level != last_level) {
                last_level = level;
            }
            continue;
        }

        /* ---- detect rising edge ---- */
        int level = gpioRead(HALL_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", HALL_SENSOR_GPIO);
            goto cleanup;
        }

        if (first_edge && level == 1) {
            first_edge = 0;
        }

        if (level == 1 && last_level == 0) {
            pulse_count++;
            last_tick = now_tick;
        }
        last_level = level;

        /* ---- sample interval elapsed? ---- */
        if (elapsed >= (uint32_t)(SAMPLE_INTERVAL * 1000000)) {
            double rpm = (double)pulse_count / (double)SAMPLE_INTERVAL * 60.0;

            if (log_rpm(rpm) != 0) {
                fprintf(stderr, "Logging failed — continuing.\n");
            }
            printf("RPM: %.2f\n", rpm);

            pulse_count = 0;
            last_tick   = now_tick;
        }
    }

    printf("\nShutting down cleanly.\n");

cleanup:
    gpioSetAlertFuncEx(HALL_SENSOR_GPIO, NULL, NULL);
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return EXIT_SUCCESS;
}

