#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_US 50000
#define RELAY_HOLD_TIME_US 10000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_touch_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int control_relay(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, pigpio_error(result));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on touch sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool relay_state = false;
    uint32_t hold_start = 0;
    bool hold_active = false;

    while (running) {
        int touch_value = read_touch_sensor(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (touch_value == 1) {
            if (!relay_state) {
                if (control_relay(RELAY_PIN, 1) < 0) {
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
                relay_state = true;
            }
            if (!hold_active) {
                hold_start = gpioTick();
                hold_active = true;
            } else {
                uint32_t elapsed = gpioTick() - hold_start;
                if (elapsed > RELAY_HOLD_TIME_US) {
                    if (control_relay(RELAY_PIN, 0) < 0) {
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                    relay_state = false;
                    hold_active = false;
                }
            }
        } else {
            if (relay_state) {
                if (control_relay(RELAY_PIN, 0) < 0) {
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
                relay_state = false;
            }
            hold_active = false;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

