#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

#define PWM_RANGE 255
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_US 100000
#define MAX_FLOW_RATE 10.0
#define MIN_FLOW_RATE 0.0

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static double kp = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static double calculate_flow_rate(int pulses) {
    return (double)pulses / 1000.0;
}

static int calculate_valve_position(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    double output = kp * error;
    int position = (int)output;
    if (position < 0) position = 0;
    if (position > PWM_RANGE) position = PWM_RANGE;
    return position;
}

static void set_valve_position(int position) {
    if (gpioPWM(VALVE_PWM_PIN, position) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", VALVE_PWM_PIN);
    }
}

static void log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file);
}

static void cleanup(void) {
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate < MIN_FLOW_RATE || target_flow_rate > MAX_FLOW_RATE) {
                    fprintf(stderr, "Error: target flow rate must be between %.1f and %.1f L/min\n", MIN_FLOW_RATE, MAX_FLOW_RATE);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for valve PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for valve enable pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for valve enable pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open flow_log.csv for writing\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp_ms,flow_rate_L_min,valve_position\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return 1;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);

    while (running) {
        int pulses = pulse_count;
        pulse_count = 0;
        double flow_rate = calculate_flow_rate(pulses);
        int valve_position = calculate_valve_position(flow_rate, target_flow_rate);
        set_valve_position(valve_position);
        log_data(flow_rate, valve_position);
        printf("Flow: %.2f L/min, Valve: %d/%d\n", flow_rate, valve_position, PWM_RANGE);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

