#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 100000
#define DEBOUNCE_MS 50
#define LOCK_OPEN_MS 5000
#define LOG_FILE "/var/log/door_access.log"
#define TAG_LEN 10
#define MAX_RETRIES 4

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static const unsigned char valid_tag[TAG_LEN] = {
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A
};

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s %s\n", ts, msg);
    fflush(log_fp);
}

