#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor 1 */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

/* Motor 2 */
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

/* Encoder 1 */
#define ENCODER1_A 5
#define ENCODER1_B 6

/* Encoder 2 */
#define ENCODER2_A 26
#define ENCODER2_B 19

#define TARGET_RPM 60.0
#define SAMPLE_TIME_US 100000  /* 100 ms */
#define PWM_FREQ 1000          /* 1 kHz software PWM */
#define PWM_RANGE 1000         /* 1000 steps => 1 ms period */

/* PID gains */
#define KP 1.0
#define KI 0.1
#define KD 0.01

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile int encoder1_count = 0;
static volatile int encoder2_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_ENA, 0);
    gpioPWM(MOTOR2_ENB, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&encoder_mutex);
}

static void encoder1_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&encoder_mutex);
    encoder1_count++;
    pthread_mutex_unlock(&encoder_mutex);
}

static void encoder2_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&encoder_mutex);
    encoder2_count++;
    pthread_mutex_unlock(&encoder_mutex);
}

static int read_encoder(int *count) {
    pthread_mutex_lock(&encoder_mutex);
    *count = encoder1_count;
    pthread_mutex_unlock(&encoder_mutex);
    return 0;
}

static double calculate_rpm(int encoder_count, uint32_t elapsed_us) {
    if (elapsed_us == 0) return 0.0;
    double revolutions = (double)encoder_count / 4.0;
    double time_min = (double)elapsed_us / 60000000.0;
    return (revolutions / time_min) * 60.0;
}

static double pid_control(double setpoint, double actual, double *integral, double *previous_error, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

static void set_motor_speed(int motor_number, double pid_output) {
    int in1, in2, ena;
    if (motor_number == 1) {
        in1 = MOTOR1_IN1; in2 = MOTOR1_IN2; ena = MOTOR1_ENA;
    } else if (motor_number == 2) {
        in1 = MOTOR2_IN3; in2 = MOTOR2_IN4; ena = MOTOR2_ENB;
    } else {
        return;
    }

    int duty = (int)pid_output;
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;

    int on_time = (duty * PWM_RANGE) / 100;
    int off_time = PWM_RANGE - on_time;

    if (on_time > 0) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
        gpioPWM(ena, on_time);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
        gpioPWM(ena, 0);
    }
}

static void *encoder_thread(void *arg) {
    (void)arg;
    while (running) {
        gpioDelay(10000); /* 10 ms */
        int e1, e2;
        read_encoder(&e1);
        read_encoder(&e2);
        double rpm1 = calculate_rpm(e1, 10000);
        double rpm2 = calculate_rpm(e2, 10000);

        double error1 = TARGET_RPM - rpm1;
        double error2 = TARGET_RPM - rpm2;

        static double integral1 = 0.0, integral2 = 0.0;
        static double prev_err1 = 0.0, prev_err2 = 0.0;

        double pid_out1 = pid_control(TARGET_RPM, rpm1, &integral1, &prev_err1, 0.01);
        double pid_out2 = pid_control(TARGET_RPM, rpm2, &integral2, &prev_err2, 0.01);

        set_motor_speed(1, pid_out1);
        set_motor_speed(2, pid_out2);

        if (log_file) {
            fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                    rpm1, rpm2, error1, error2, pid_out1, pid_out2);
            fflush(log_file);
        }
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Motor1_RPM,Motor2_RPM,Error1,Error2,PID_Out1,PID_Out2\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0 ||
        gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder2_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder ISRs\n");
        cleanup();
        return 1;
    }

    pthread_t encoder_thread1;
    if (pthread_create(&encoder_thread1, NULL, encoder_thread, NULL) != 0) {
        perror("Failed to create encoder thread");
        cleanup();
        return 1;
    }

    while (running) {
        gpioDelay(SAMPLE_TIME_US);
    }

    pthread_join(encoder_thread1, NULL);
    cleanup();
    return 0;
}

