        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder2_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set encoder ISRs\n");
        cleanup();
        return 1;
    }

    pthread_t encoder_thread1;
    if (pthread_create(&encoder_thread1, NULL, encoder_thread, NULL) != 0) {
        perror("Failed to create encoder thread");
        cleanup();
        return 1;
    }

    while (running) {
        gpioDelay(SAMPLE_TIME_US);
    }

    pthread_join(encoder_thread1, NULL);
    cleanup();
    return 0;
}

