/*
 * MPR121 Capacitive Touch Sensor -> Relay Control with Logging
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: MPR121 at address 0x5D (ADDR pin tied to GND)
 * Relay:  GPIO17 (BCM)
 *
 * Behaviour:
 *   - Polls the 12-bit touch status register every 50 ms.
 *   - Drives the relay HIGH when any electrode is touched, LOW otherwise.
 *   - Logs every relay-state change to relay_log.txt with a timestamp.
 *   - Handles SIGINT (Ctrl-C) to shut down the relay and close I2C handles.
 *   - Robust error handling for I2C operations and sensor initialization.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NAME      "/dev/i2c-1"
#define MPR121_ADDR       0x5D
#define RELAY_GPIO        17
#define LOG_FILE          "relay_log.txt"
#define POLL_DELAY_US     50000   /* 50 ms */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_relay_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 initialization                                               */
/* ------------------------------------------------------------------ */
static int mpr121_init(int fd)
{
    uint8_t val;

    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle after reset */

    /* Verify the device is present by reading the ECR register */
    if (i2c_read_reg8(fd, MPR121_ECR, &val) < 0)
        return -1;
    if (val != 0x00) {
        fprintf(stderr, "MPR121 not detected (ECR=0x%02X). "
                        "Check wiring and address.\n", val);
        return -1;
    }

    /* Filtering parameters (rising / falling / baseline) */
    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg8(fd, MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs (CONFIG1) */
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* ESI=4 samples, SFI=4 µs, ESI=4 µs (CONFIG2) */
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes in run mode (ECR = 0x0C) */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x0C) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 12-bit touch status                                            */
/* ------------------------------------------------------------------ */
static int mpr121_read_touch_status(int fd, uint16_t *status)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Relay: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                state ? "HIGH" : "LOW");
    } else {
        fprintf(fp, "<timestamp-error>, Relay: %s\n",
                state ? "HIGH" : "LOW");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_relay_fd >= 0) {
        if (g_relay_fd >= 0)
            close(g_relay_fd);
        g_relay_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open relay GPIO (BCM 17) */
    g_relay_fd = open("/sys/class/gpio/gpiochip0/gpio17/value", O_WRONLY);
    if (g_relay_fd < 0) {
        fprintf(stderr, "Failed to open relay GPIO 17: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int first_poll = 1;

    while (g_running) {
        uint16_t touch_status;
        if (mpr121_read_touch_status(g_i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status; retrying...\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        int touched = (touch_status != 0);

        if (touched != relay_state || first_poll) {
            if (write(g_relay_fd, touched ? "1" : "0", 1) != 1) {
                fprintf(stderr, "Failed to write relay GPIO: %s\n",
                        strerror(errno));
            } else {
                relay_state = touched;
                log_relay_state(relay_state);
            }
            first_poll = 0;
        }

        usleep(POLL_DELAY_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

