    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
