        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", VALVE1_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", VALVE2_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE1_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW: %s\n", VALVE1_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW: %s\n", VALVE2_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

