        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (activate_valve(VALVE1_GPIO, VALVE1_DURATION_MS) != 0) {
            fprintf(stderr, "Error activating Valve 1\n");
            break;
        }
        log_event(1, VALVE1_DURATION_MS, VALVE1_PAUSE_SEC);

        if (!program_running) break;

        if (activate_valve(VALVE2_GPIO, VALVE2_DURATION_MS) != 0) {
            fprintf(stderr, "Error activating Valve 2\n");
            break;
        }
        log_event(2, VALVE2_DURATION_MS, VALVE2_PAUSE_SEC);
    }

    cleanup();
    printf("Water distribution system stopped.\n");
    return EXIT_SUCCESS;
}

