/*
 * MPR121 Capacitive Touch Sensor - Relay Toggle
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Relay:  GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MPR121_ADDR          0x5D          /* Default ADDR pin tied to GND */
#define RELAY_GPIO           17            /* BCM pin for the relay */
#define POLL_DELAY_US        100000        /* 100 ms between polls */
#define STABILIZE_DELAY_US   100000        /* 100 ms after mode change */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35
#define MPR121_E0TTH         0x41          /* Touch threshold for electrode 0 */
#define MPR121_E0RTH         0x42          /* Release threshold for electrode 0 */
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  mpr121_write_reg(uint8_t reg, uint8_t value);
static int  mpr121_read_reg(uint8_t reg, uint8_t *value);
static int  mpr121_init(void);
static int  mpr121_read_touch_status(uint16_t *touch_status);
static void relay_toggle(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed: %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ----------------------------- MPR121 init -------------------------------- */
static int mpr121_init(void)
{
    /*
     * Put the MPR121 into stop mode so configuration changes take effect.
     * ECR bit 0 = 0 -> stop mode.
     */
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0)
        return -1;
    gpioDelay(STABILIZE_DELAY_US);

    /*
     * Filter configuration (rising / falling / touch / release).
     * MHDR = 0x01, NHDR = 0x01, NCLR = 0x0E, FDLR = 0x00
     * MHDF = 0x01, NHDF = 0x01, NCLF = 0x00, FDLF = 0x00
     * NHDT = 0x00, NCLT = 0x00, FDLT = 0x00
     */
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    /*
     * Debounce: 3 samples for both touch and release.
     */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /*
     * Config1: FFI=00 (6 samples), CDC=16 µA, CDT=0.5 µs.
     */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /*
     * Config2: FFI=00 (6 samples), ESI=10 (10 electrodes), CDC=16 µA.
     */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /*
     * Touch / release thresholds for all 12 electrodes.
     * Touch threshold = 0x0F, Release threshold = 0x0A.
     */
    for (int i = 0; i < 12; i++) {
        uint8_t touch_reg = MPR121_E0TTH + (uint8_t)(i * 2);
        uint8_t release_reg = MPR121_E0RTH + (uint8_t)(i * 2);
        if (mpr121_write_reg(touch_reg, 0x0F) < 0) return -1;
        if (mpr121_write_reg(release_reg, 0x0A) < 0) return -1;
    }

    /*
     * Enter run mode: ECR bit 0 = 1.
     */
    if (mpr121_write_reg(MPR121_ECR, 0x01) < 0)
        return -1;

    gpioDelay(STABILIZE_DELAY_US);
    return 0;
}

/* ----------------------------- Read touch status -------------------------- */
static int mpr121_read_touch_status(uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Relay toggle ------------------------------ */
static void relay_toggle(void)
{
    int level = gpioRead(RELAY_GPIO);
    if (level < 0) {
        fprintf(stderr, "[GPIO] read relay pin %d failed: %s\n",
                RELAY_GPIO, pigpio_error(level));
        return;
    }
    level = !level;
    if (gpioWrite(RELAY_GPIO, level) < 0) {
        fprintf(stderr, "[GPIO] write relay pin %d failed: %s\n",
                RELAY_GPIO, pigpio_error(level));
        return;
    }
    printf("Relay toggled to %s\n", level ? "ON" : "OFF");
    fflush(stdout);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put MPR121 back into stop mode before closing. */
        (void)i2cWriteByteData(g_i2c_handle, MPR121_ECR, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPR121 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output, initially OFF */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite failed for pin %d\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay toggle running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status > 0) {
            relay_toggle();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

