     * Config2: FFI=00 (6 samples), ESI=10 (10 electrodes), CDC=16 µA.
     */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /*
     * Touch / release thresholds for all 12 electrodes.
     * Touch threshold = 0x0F, Release threshold = 0x0A.
     */
    for (int i = 0; i < 12; i++) {
        uint8_t touch_reg = MPR121_E0TTH + (uint8_t)(i * 2);
        uint8_t release_reg = MPR121_E0RTH + (uint8_t)(i * 2);
        if (mpr121_write_reg(touch_reg, 0x0F) < 0) return -1;
        if (mpr121_write_reg(release_reg, 0x0A) < 0) return -1;
    }

    /*
     * Enter run mode: ECR bit 0 = 1.
     */
    if (mpr121_write_reg(MPR121_ECR, 0x01) < 0)
        return -1;

    gpioDelay(STABILIZE_DELAY_US);
    return 0;
}

/* ----------------------------- Read touch status -------------------------- */
static int mpr121_read_touch_status(uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Relay toggle ------------------------------ */
static void relay_toggle(void)
{
    int level = gpioRead(RELAY_GPIO);
    if (level < 0) {
        fprintf(stderr, "[GPIO] read relay pin %d failed: %s\n",
                RELAY_GPIO, pigpio_error(level));
        return;
    }
    level = !level;
    if (gpioWrite(RELAY_GPIO, level) < 0) {
        fprintf(stderr, "[GPIO] write relay pin %d failed: %s\n",
                RELAY_GPIO, pigpio_error(level));
        return;
    }
    printf("Relay toggled to %s\n", level ? "ON" : "OFF");
    fflush(stdout);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put MPR121 back into stop mode before closing. */
        (void)i2cWriteByteData(g_i2c_handle, MPR121_ECR, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPR121 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output, initially OFF */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite failed for pin %d\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay toggle running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status > 0) {
            relay_toggle();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

