#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int set_motor_pwm(int pin, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE || duty_cycle > MAX_DUTY_CYCLE) {
        fprintf(stderr, "Error: Duty cycle %d out of range [%d, %d]\n",
                duty_cycle, MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        return -1;
    }
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int generate_pattern(int *motor1_duty, int *motor2_duty, int *duration_ms) {
    int steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
    *motor1_duty = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
    *motor2_duty = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
    *duration_ms = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    return steps;
}

static void play_pattern(int motor1_duty, int motor2_duty, int duration_ms) {
    if (set_motor_pwm(MOTOR1_PIN, motor1_duty) != 0) {
        return;
    }
    if (set_motor_pwm(MOTOR2_PIN, motor2_duty) != 0) {
        set_motor_pwm(MOTOR1_PIN, 0);
        return;
    }
    gpioDelay(duration_ms * 1000);
    set_motor_pwm(MOTOR1_PIN, 0);
    set_motor_pwm(MOTOR2_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, 1000) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR2_PIN, 1000) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, 255) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR2_PIN, 255) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    while (!shutdown_flag) {
        int motor1_duty = 0, motor2_duty = 0, duration_ms = 0;
        int steps = generate_pattern(&motor1_duty, &motor2_duty, &duration_ms);

        for (int i = 0; i < steps && !shutdown_flag; i++) {
            play_pattern(motor1_duty, motor2_duty, duration_ms);
        }
    }

    printf("\nShutting down...\n");
    set_motor_pwm(MOTOR1_PIN, 0);
    set_motor_pwm(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("Haptic feedback generator stopped.\n");
    return EXIT_SUCCESS;
}

