#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"

#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_SAMPLES 100
#define READ_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;

static float scale_factor = 1.0;
static float offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *raw_value) {
    int i;
    int32_t value = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open calibration file. Using defaults.\n");
        return -1;
    }

    if (fscanf(fp, "%f %f", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Could not read calibration values. Using defaults.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration loaded: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int save_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1;
    }

    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration saved: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int calibrate_sensor(void) {
    int32_t raw_sum = 0;
    int valid_readings = 0;
    int32_t raw_value;

