#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define RAIN_THRESHOLD 3
#define MOTOR_RUN_TIME_SEC 5
#define MOTOR_PWM_FREQ 1000
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150
#define CHECK_INTERVAL_SEC 60
#define POST_CLOSE_WAIT_SEC 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "Error reading rain sensor on GPIO%d", RAIN_SENSOR_PIN);
            return -1;
        }
        if (val == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

static int control_motor(int direction, int duration_sec) {
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", MOTOR_IN1_PIN);
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", MOTOR_IN2_PIN);
        return -1;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", MOTOR_PWM_PIN);
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize PWM on GPIO%d", MOTOR_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GPIO%d", MOTOR_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_PWM_PIN, MOTOR_PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on GPIO%d", MOTOR_PWM_PIN);
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle on GPIO%d", MOTOR_PWM_PIN);
        return -1;
    }

    if (direction == 1) {
        if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d high", MOTOR_IN1_PIN);
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d low", MOTOR_IN2_PIN);
            return -1;
        }
    } else {
        if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d low", MOTOR_IN1_PIN);
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 1) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO%d high", MOTOR_IN2_PIN);
            return -1;
        }
    }

    syslog(LOG_INFO, "Motor started (direction=%d, duration=%d s)", direction, duration_sec);

    for (int i = 0; i < duration_sec * 10 && program_running; i++) {
        gpioDelay(100000);
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM on GPIO%d", MOTOR_PWM_PIN);
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d low", MOTOR_IN1_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d low", MOTOR_IN2_PIN);
        return -1;
    }

    syslog(LOG_INFO, "Motor stopped");
    return 0;
}

static void log_event(const char *event_type, int rain_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (event_type == NULL) {
        syslog(LOG_ERR, "Error: event_type is NULL");
        return;
    }

    if (rain_detected == 0 || rain_detected == 1) {
        syslog(LOG_INFO, "%s - %s - Rain detected: %s", timestamp, event_type, rain_detected ? "YES" : "NO");
    } else {
        syslog(LOG_ERR, "%s - %s - Invalid rain detection value: %d", timestamp, event_type, rain_detected);
    }
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control program started");

    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected < 0) {
            syslog(LOG_ERR, "Error reading rain sensor, skipping cycle");
            for (int i = 0; i < CHECK_INTERVAL_SEC && program_running; i++) {
                sleep(1);
            }
            continue;
        }

        log_event("Rain sensor check", rain_detected);

        if (rain_detected) {
            syslog(LOG_INFO, "Rain detected, closing window");
            if (control_motor(1, MOTOR_RUN_TIME_SEC) < 0) {
                syslog(LOG_ERR, "Failed to control motor");
            }
            log_event("Window closing", rain_detected);

            for (int i = 0; i < POST_CLOSE_WAIT_SEC && program_running; i++) {
                sleep(1);
            }
        } else {
            for (int i = 0; i < CHECK_INTERVAL_SEC && program_running; i++) {
                sleep(1);
            }
        }
    }

    syslog(LOG_INFO, "Shutting down, stopping motor");
    control_motor(0, 0);

    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

