#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_HOLD_TIME 5
#define HX711_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static FILE *calibration_fp = NULL;
static FILE *security_fp = NULL;
static double calibration_factor = 1.0;
static bool solenoid_locked = false;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (solenoid_locked) {
        gpioWrite(SOLENOID_PIN, 0);
        solenoid_locked = false;
    }
    if (calibration_fp) {
        fclose(calibration_fp);
        calibration_fp = NULL;
    }
    if (security_fp) {
        fclose(security_fp);
        security_fp = NULL;
    }
    gpioTerminate();
}

static int read_hx711_raw(int32_t *out) {
    if (out == NULL) return -1;

    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start_tick > HX711_TIMEOUT_US) {
            return -1;
        }
        gpioDelay(10);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    *out = value;
    return 0;
}

static double read_hx711_weight(void) {
    int32_t raw;
    if (read_hx711_raw(&raw) != 0) {
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int save_calibration(double factor) {
    calibration_fp = fopen(CALIBRATION_FILE, "w");
    if (!calibration_fp) {
        fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(calibration_fp, "%.6f\n", factor) < 0) {
        fprintf(stderr, "Error writing calibration: %s\n", strerror(errno));
        fclose(calibration_fp);
        calibration_fp = NULL;
        return -1;
    }
    if (fclose(calibration_fp) != 0) {
        fprintf(stderr, "Error closing calibration file: %s\n", strerror(errno));
        calibration_fp = NULL;
        return -1;
    }
    calibration_fp = NULL;
    return 0;
}

static int load_calibration(void) {
    calibration_fp = fopen(CALIBRATION_FILE, "r");
    if (!calibration_fp) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(stderr, "Calibration file not found. Starting calibration.\n");
        return -1;
    }
    if (fscanf(calibration_fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor\n");
        fclose(calibration_fp);
        calibration_fp = NULL;
        return -1;
    }
    if (fclose(calibration_fp) != 0) {
        fprintf(stderr, "Error closing calibration file: %s\n", strerror(errno));
        calibration_fp = NULL;
        return -1;
    }
    calibration_fp = NULL;
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0;
}

static int calibrate_sensor(void) {
    printf("Place a known weight on the load cell and enter its value in kg:\n");
    double known_weight;
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return -1;
    }
    int32_t raw;
    if (read_hx711_raw(&raw) != 0) {
        fprintf(stderr, "HX711 communication timeout during calibration.\n");
        return -1;
    }
    calibration_factor = (double)raw / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);
    if (save_calibration(calibration_factor) != 0) {
        fprintf(stderr, "Failed to save calibration factor.\n");
        return -1;
    }
    return 0;
}

static int log_security_event(double weight) {
    security_fp = fopen(SECURITY_LOG_FILE, "a");
    if (!security_fp) {
        fprintf(stderr, "Error opening security log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(security_fp, "%d-%02d-%02d %02d:%02d:%02d - Weight: %.2f kg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, weight) < 0) {
        fprintf(stderr, "Error writing to security log: %s\n", strerror(errno));
        fclose(security_fp);
        security_fp = NULL;
        return -1;
    }
    if (fclose(security_fp) != 0) {
        fprintf(stderr, "Error closing security log file: %s\n", strerror(errno));
        security_fp = NULL;
        return -1;
    }
    security_fp = NULL;
    return 0;
}

static int control_solenoid(void) {
    if (solenoid_locked) {
        printf("Solenoid already locked. Unlocking...\n");
        gpioWrite(SOLENOID_PIN, 0);
        solenoid_locked = false;
        return 0;
    }
    printf("Engaging solenoid lock...\n");
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to engage solenoid\n");
        return -1;
    }
    solenoid_locked = true;
    sleep(SOLENOID_HOLD_TIME);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Failed to disengage solenoid\n");
        return -1;
    }
    solenoid_locked = false;
    printf("Solenoid lock released.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set HX711 data pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set HX711 clock pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (load_calibration() != 0) {
        if (calibrate_sensor() != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return 1;
        }
    }

    printf("Starting weight monitoring...\n");
    while (running) {
        double weight = read_hx711_weight();
        if (weight < 0) {
            fprintf(stderr, "HX711 communication timeout. Retrying...\n");
            gpioDelay(100000);
            continue;
        }
        printf("Weight: %.2f kg\n", weight);
        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Engaging solenoid lock.\n");
            if (control_solenoid() != 0) {
                fprintf(stderr, "Solenoid control failed.\n");
            }
            if (log_security_event(weight) != 0) {
                fprintf(stderr, "Failed to log security event.\n");
            }
        }
        gpioDelay(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

