        fprintf(stderr, "Error setting sensor pin %d as input: %s\n", SENSOR_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay pin %d as output: %s\n", RELAY_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int relay_state = 0;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error initializing relay pin %d to LOW: %s\n", RELAY_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring KY-022 on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN, RELAY_PIN);

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin %d: %s\n", SENSOR_PIN, strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            relay_state = toggle_relay(relay_state);
            if (relay_state < 0) {
                gpioDelay(POLL_DELAY_US);
                continue;
            }
            char log_message[64];
            snprintf(log_message, sizeof(log_message), "Relay toggled to %s", relay_state ? "ON" : "OFF");
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nCleaning up and exiting...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return 0;
}

