    char *val = eq + 1;
    while (*val == ' ' || *val == '\t') val++;
    if (*val == '\0') {
        fprintf(stderr, "Error reading file %s: empty value after '='\n", filename);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long val_long = strtol(val, &endptr, 10);
    if (errno != 0 || endptr == val || *endptr != '\0') {
        fprintf(stderr, "Error reading file %s: invalid integer value\n", filename);
        return -1;
    }

    if (val_long < MIN_DURATION || val_long > MAX_DURATION) {
        fprintf(stderr, "Error reading file %s: duration %ld out of range [%d-%d]\n",
                filename, val_long, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val_long;
    return 0;
}

static int set_valve(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_valve(GPIO_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duration;
    if (read_duration(CONFIG_FILE, &duration) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    if (set_valve(GPIO_PIN, 1) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Valve ON\n");

    while (program_running && (duration > 0)) {
        int remaining = (int)sleep(1);
        if (remaining < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
            break;
        }
        duration -= remaining;
    }

    if (set_valve(GPIO_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Valve OFF\n");

    gpioTerminate();
    return EXIT_SUCCESS;
}

