#define LEFT_MOTOR_PIN_1 22
#define LEFT_MOTOR_PIN_2 23
#define RIGHT_MOTOR_PIN_1 24
#define RIGHT_MOTOR_PIN_2 25

/* PWM frequency (Hz) */
#define PWM_FREQUENCY 1000

/* PWM range (0-255) */
#define PWM_RANGE 255

/* Base motor speed (0-255) */
#define BASE_SPEED 150

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Log file name */
#define LOG_FILE "trace_log.txt"

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Function prototypes */
static int initialize_gpio(void);
static void cleanup_gpio(void);
static int read_sensor(int pin);
static void set_motor_speed(int pin, int speed);
static void stop_motors(void);
static void log_data(int left, int middle, int right, int left_speed, int right_speed);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initializes the pigpio library and configures all GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set sensor pin modes\n");
        gpioTerminate();
        return -1;
    }

    /* Configure motor driver pins as outputs */
    if (gpioSetMode(LEFT_MOTOR_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(LEFT_MOTOR_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(RIGHT_MOTOR_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(RIGHT_MOTOR_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set motor pin modes\n");
        gpioTerminate();
        return -1;
    }

    /* Set PWM frequency and range for motor driver pins */
    if (gpioSetPWMfrequency(LEFT_MOTOR_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(LEFT_MOTOR_PIN_2, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR_PIN_1, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR_PIN_2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(LEFT_MOTOR_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LEFT_MOTOR_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RIGHT_MOTOR_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RIGHT_MOTOR_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Cleans up the pigpio library and releases all resources */
static void cleanup_gpio(void) {
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Reads the digital value from a sensor pin (active low: 0 = object detected) */
static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO pin %d\n", pin);
        return -1;
    }
    return value;
}

/* Sets the PWM duty cycle for a motor pin (0-255) */
static void set_motor_speed(int pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioPWM(pin, speed);
}

