static void stop_motors(void) {
    set_motor_speed(LEFT_MOTOR_PIN_1, 0);
    set_motor_speed(LEFT_MOTOR_PIN_2, 0);
    set_motor_speed(RIGHT_MOTOR_PIN_1, 0);
    set_motor_speed(RIGHT_MOTOR_PIN_2, 0);
}

/* Logs sensor data and motor speeds to a file with an ISO 8601 timestamp */
static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
