        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: Sensor read failure, stopping motors\n");
            stop_motors();
            break;
        }

        /* Control logic (active low: 0 = object detected) */
        int left_speed, right_speed;
        if (middle == 0) {
            /* Object detected by middle sensor: drive straight */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0) {
            /* Object detected by left sensor: turn right */
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right == 0) {
            /* Object detected by right sensor: turn left */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            /* No object detected: stop */
            left_speed = 0;
            right_speed = 0;
        }

        /* Set motor speeds */
        set_motor_speed(LEFT_MOTOR_PIN_1, left_speed);
        set_motor_speed(LEFT_MOTOR_PIN_2, 0);
        set_motor_speed(RIGHT_MOTOR_PIN_1, right_speed);
        set_motor_speed(RIGHT_MOTOR_PIN_2, 0);

        /* Log data */
        log_data(left, middle, right, left_speed, right_speed);

        /* Wait for next sample */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    cleanup_gpio();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

