        log_event("Error: Failed to read BH1750 data.");
        return -1;
    }
    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("Error: Failed to write to relay GPIO.");
        return;
    }
    relay_state = state;
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay turned %s.", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        log_event("Error: Failed to open I2C device.");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_event("Grow lamp controller started.");
    while (running) {
        int lux = 0;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %d", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
            }
        }
        gpioDelay(100000);
    }
    log_event("Shutting down gracefully.");
    control_relay(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

