#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_LOCK_PULSE_WIDTH 1000
#define SERVO_UNLOCK_PULSE_WIDTH 2000

#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(gpio, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int read_button(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", gpio);
        return -1;
    }
    return val;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistors on button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_val = read_button(LOCK_BUTTON_PIN);
        int unlock_val = read_button(UNLOCK_BUTTON_PIN);

        if (lock_val < 0 || unlock_val < 0) {
            fprintf(stderr, "Error: Button read failure, exiting\n");
            break;
        }

        if (lock_val == 0) {
            printf("Lock button pressed, moving servo to lock position\n");
            if (set_servo_pulse_width(SERVO_PIN, SERVO_LOCK_PULSE_WIDTH) == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        } else if (unlock_val == 0) {
            printf("Unlock button pressed, moving servo to unlock position\n");
            if (set_servo_pulse_width(SERVO_PIN, SERVO_UNLOCK_PULSE_WIDTH) == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        }

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

