/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 *
 * Two Precision Microdrives 310-101 vibration motors are pulsed
 * sequentially via external driver circuits (e.g., NPN transistors
 * with flyback diodes) on GPIO17 and GPIO27 (BCM numbering).
 *
 * Motor 1: 200 ms pulse on GPIO17
 * Motor 2: 300 ms pulse on GPIO27
 *
 * The motors require 3 V @ 60 mA typical; they MUST NOT be driven
 * directly from the GPIO pins.  An external driver circuit is
 * required to supply the necessary current and to protect the
 * Raspberry Pi from back-EMF.
 *
 * Build:  gcc -O2 -Wall -Wextra -o haptic haptic.c -lpigpio -lrt
 * Run:    sudo ./haptic
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_PULSE_MS  200
#define MOTOR2_PULSE_MS  300

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */

/*
 * Pulse a motor for `duration_ms` by toggling the GPIO line.
 * Returns 0 on success, -1 on error.
 */
static int pulse_motor(int pin, int duration_ms)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);          /* microseconds */

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", pin);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup_gpio(void)
{
    /* Ensure both motor lines are left in a safe (off) state. */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs and ensure they start OFF. */
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR1_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR2_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR1_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) initial state failed\n", MOTOR1_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR2_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) initial state failed\n", MOTOR2_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started.  Press Ctrl+C to exit.\n");
    printf("Motor 1 (GPIO%d): %d ms pulse\n", MOTOR1_PIN, MOTOR1_PULSE_MS);
    printf("Motor 2 (GPIO%d): %d ms pulse\n", MOTOR2_PIN, MOTOR2_PULSE_MS);
    printf("-----------------------------------------------\n");

    while (g_running) {
        if (pulse_motor(MOTOR1_PIN, MOTOR1_PULSE_MS) != 0) {
            fprintf(stderr, "Error: motor 1 pulse failed, exiting\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (!g_running) {
            break;
        }

        if (pulse_motor(MOTOR2_PIN, MOTOR2_PULSE_MS) != 0) {
            fprintf(stderr, "Error: motor 2 pulse failed, exiting\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    printf("Haptic feedback system stopped.\n");
    return EXIT_SUCCESS;
}

