#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <zmq.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_PORT 5555
#define SOUND_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static void log_msg(const char *msg) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s.%06ld] %s\n", ts, tv.tv_usec, msg);
}

static void log_err(const char *msg) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(stderr, "[%s.%06ld] ERROR: %s (errno: %d - %s)\n",
            ts, tv.tv_usec, msg, errno, strerror(errno));
}

static int zmq_send_alert(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        log_err("zmq_ctx_new failed");
        return -1;
    }

    void *sender = zmq_socket(context, ZMQ_PUSH);
    if (!sender) {
        log_err("zmq_socket(PUSH) failed");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_bind(sender, "tcp://*:5555");
    if (rc != 0) {
        log_err("zmq_bind failed");
        zmq_close(sender);
        zmq_ctx_destroy(context);
        return -1;
    }

    char buffer[256];
    snprintf(buffer, sizeof(buffer), "Sound detected on GPIO%d", SOUND_SENSOR_PIN);

    rc = zmq_send(sender, buffer, strlen(buffer), 0);
    if (rc == -1) {
        log_err("zmq_send failed");
        zmq_close(sender);
        zmq_ctx_destroy(context);
        return -1;
    }

    zmq_close(sender);
    zmq_ctx_destroy(context);
    return 0;
}

static int zmq_receive_alert(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        log_err("zmq_ctx_new failed");
        return -1;
    }

    void *receiver = zmq_socket(context, ZMQ_SUB);
    if (!receiver) {
        log_err("zmq_socket(SUB) failed");
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_connect(receiver, "tcp://localhost:5555");
    if (rc != 0) {
        log_err("zmq_connect failed");
        zmq_close(receiver);
        zmq_ctx_destroy(context);
        return -1;
    }

    rc = zmq_setsockopt(receiver, ZMQ_SUBSCRIBE, "", 0);
    if (rc != 0) {
        log_err("zmq_setsockopt(SUB) failed");
        zmq_close(receiver);
        zmq_ctx_destroy(context);
        return -1;
    }

    char buffer[256];
    while (running) {
        rc = zmq_recv(receiver, buffer, sizeof(buffer) - 1, 0);
        if (rc == -1) {
            if (errno == EINTR) continue;
            log_err("zmq_recv failed");
            zmq_close(receiver);
            zmq_ctx_destroy(context);
            return -1;
        }
        buffer[rc] = '\0';
        printf("Received: %s\n", buffer);
        zmq_close(receiver);
        zmq_ctx_destroy(context);
        return 0;
    }

    zmq_close(receiver);
    zmq_ctx_destroy(context);
    return -1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") != 0 &&
        strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        fprintf(stderr, "  Valid modes: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_err("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_err("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
