/*
 * NEC IR Decoder for Raspberry Pi 3 Model B+
 * IR receiver: TSOP38238 on GPIO17 (BCM)
 * MQTT broker: localhost:1883, topic: ir/decoded
 *
 * Build: gcc -O2 -Wall -Wextra -o ir_decoder ir_decoder.c -lpigpio -lmosquitto -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 256
#define MAX_FRAME_SIZE 64

/* NEC timing constants (microseconds) */
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOL 200

typedef struct {
    uint32_t address;
    uint32_t command;
    bool extended;
} ir_command_t;

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_times[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_alert_cb(int gpio, int level, uint32_t tick) {
    (void)gpio;
    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulse_times[pulse_count++] = diff;
        } else {
            syslog(LOG_WARNING, "IR pulse buffer overflow, resetting");
            pulse_count = 0;
            return;
        }
    }

    if (pulse_count >= 64) {
        ir_command_t cmd;
        cmd.address = 0;
        cmd.command = 0;
        cmd.extended = false;

        if (pulse_times[0] > (NEC_HDR_MARK - NEC_TOL) &&
            pulse_times[1] < (NEC_HDR_MARK + NEC_TOL) &&
            pulse_times[2] > (NEC_HDR_SPACE - NEC_TOL) &&
            pulse_times[2] < (NEC_HDR_SPACE + NEC_TOL)) {

            uint32_t addr = 0, cmd_raw = 0;
            int idx = 3;

            for (int i = 0; i < 32; i++) {
                if (idx + 2 >= pulse_count) break;
                uint32_t mark = pulse_times[idx++];
                uint32_t space = pulse_times[idx++];

                if (mark > (NEC_BIT_MARK - NEC_TOL) && mark < (NEC_BIT_MARK + NEC_TOL)) {
                    if (space > (NEC_ONE_SPACE - NEC_TOL) && space < (NEC_ONE_SPACE + NEC_TOL)) {
                        addr |= (1UL << (31 - i));
                    } else if (space > (NEC_ZERO_SPACE - NEC_TOL) && space < (NEC_ZERO_SPACE + NEC_TOL)) {
                        cmd_raw |= (1UL << (31 - i));
                    } else {
                        syslog(LOG_WARNING, "Invalid NEC bit timing at bit %d", i);
                        break;
                    }
                } else {
                    syslog(LOG_WARNING, "Invalid NEC bit mark at bit %d", i);
                    break;
                }
            }

            if (idx >= 65) {
                uint32_t inv_addr = 0, inv_cmd = 0;
                for (int i = 0; i < 32; i++) {
                    if (idx + 2 >= pulse_count) break;
                    uint32_t mark = pulse_times[idx++];
                    uint32_t space = pulse_times[idx++];
                    if (mark > (NEC_BIT_MARK - NEC_TOL) && mark < (NEC_BIT_MARK + NEC_TOL)) {
                        if (space > (NEC_ONE_SPACE - NEC_TOL) && space < (NEC_ONE_SPACE + NEC_TOL)) {
                            inv_addr |= (1UL << (31 - i));
                        } else if (space > (NEC_ZERO_SPACE - NEC_TOL) && space < (NEC_ZERO_SPACE + NEC_TOL)) {
                            inv_cmd |= (1UL << (31 - i));
                        } else {
                            syslog(LOG_WARNING, "Invalid NEC inverted bit timing at bit %d", i);
                            break;
                        }
                    } else {
                        syslog(LOG_WARNING, "Invalid NEC inverted bit mark at bit %d", i);
                        break;
                    }
                }

                if (idx >= 65) {
                    if ((addr ^ inv_addr) == 0x00000000 &&
                        (cmd_raw ^ inv_cmd) == 0x00000000) {
                        cmd.address = addr;
                        cmd.command = cmd_raw;
                        cmd.extended = false;
                        syslog(LOG_INFO, "Decoded NEC command: address=0x%08X, command=0x%08X",
                               cmd.address, cmd.command);

                        char json_string[256];
                        snprintf(json_string, sizeof(json_string),
                                 "{\"address\": %u, \"command\": %u, \"extended\": %s}",
                                 cmd.address, cmd.command, cmd.extended ? "true" : "false");

                        if (mosq) {
                            int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC,
                                                      (int)strlen(json_string),
                                                      json_string, 0, false);
                            if (rc != MOSQ_ERR_SUCCESS) {
                                syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                            }
                        }
                    } else {
                        syslog(LOG_WARNING, "NEC checksum mismatch: addr=0x%08X, inv=0x%08X, cmd=0x%08X, inv=0x%08X",
                               addr, inv_addr, cmd_raw, inv_cmd);
                    }
                } else {
                    syslog(LOG_WARNING, "Incomplete NEC inverted frame");
                }
            } else {
                syslog(LOG_WARNING, "Incomplete NEC frame");
            }
        }
        pulse_count = 0;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return -1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", IR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO%d", IR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFunc(IR_GPIO, ir_alert_cb) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO%d", IR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int initialize_mqtt(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        mosquitto_lib_cleanup();
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_mqtt() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO%d", IR_GPIO);

    while (running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

