#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR     0x29
#define BH1750_CONT_HIGH_RES  0x10
#define NUM_SENSORS     4
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define CONV_DELAY_MS  180
#define LOOP_DELAY_MS  1000

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int i2c_open(uint8_t addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static float read_bh1750(int fd)
{
    uint8_t cmd = BH1750_CONT_HIGH_RES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(start) failed: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(CONV_DELAY_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "read(data) failed: %s\n", strerror(errno));
        return -1.0f;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    return (float)raw / 1.2f;
}

static int send_udp_multicast(const char *data)
{
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "socket() failed: %s\n", strerror(errno));
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sock, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    close(sock);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fds[NUM_SENSORS];
    uint8_t addrs[NUM_SENSORS] = {0x29, 0x29, 0x29, 0x29};

    for (int i = 0; i < NUM_SENSORS; i++) {
        fds[i] = i2c_open(addrs[i]);
        if (fds[i] < 0) {
            fprintf(stderr, "Sensor %d init failed\n", i + 1);
            for (int j = 0; j < i; j++) close(fds[j]);
            return EXIT_FAILURE;
        }
    }

    while (!g_terminate) {
        char data[256];
        int written = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = read_bh1750(fds[i]);
            if (lux < 0.0f) {
                lux = -1.0f;
            }
            int n = snprintf(data + written,
                             sizeof(data) - written,
                             "%d,%.2f;", i + 1, lux);
            if (n > 0) {
                written += n;
            }
        }

        if (written > 0) {
            data[written - 1] = '\0';
            if (send_udp_multicast(data) < 0) {
                fprintf(stderr, "Multicast send failed\n");
            }
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fds[i] >= 0) close(fds[i]);
    }
    return EXIT_SUCCESS;
}

