#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x48
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_init(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int i2c_read_flow(int fd, float *flow_out)
{
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        /* Issue a zero-length write to generate a start condition. */
        if (write(fd, buf, 0) < 0) {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor not responding (ENXIO): %s\n",
                        strerror(errno));
                return -1;
            }
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            retries++;
            if (retries < MAX_RETRIES)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /* Read two bytes of flow data. */
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == (ssize_t)sizeof(buf)) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            /* Mask to 14-bit flow value (bits 13..0). */
            uint16_t flow_raw = raw & 0x3FFF;
            *flow_out = (float)flow_raw / 1024.0f;
            return 0;
        }

        if (n < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error (EIO): %s\n", strerror(errno));
            } else {
                fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "I2C read short: got %zd of 2 bytes\n", n);
        }

        retries++;
        if (retries < MAX_RETRIES)
            usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

static void log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow_rate) < 0)
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    else
        fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_init();
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;

        if (i2c_read_flow(g_i2c_fd, &flow_rate) == 0) {
            log_flow_rate(g_log_fp, flow_rate);
            printf("Flow rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow rate after %d retries.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

