#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x08
#define DEFAULT_SAMPLE_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;

typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_sensor_data(int fd, sensor_data_t *data) {
    int16_t raw_x, raw_y, raw_z;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16_le(fd, 0x00, &raw_x) == 0 &&
            i2c_read_reg16_le(fd, 0x02, &raw_y) == 0 &&
            i2c_read_reg16_le(fd, 0x04, &raw_z) == 0) {
            data->x = (float)raw_x / 1000.0f;
            data->y = (float)raw_y / 1000.0f;
            data->z = (float)raw_z / 1000.0f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (csv_file) {
        fprintf(csv_file, "%s,%s\n", timestamp, message);
        fflush(csv_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data->x, data->y, data->z);
    fflush(csv_file);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int sample_interval = DEFAULT_SAMPLE_INTERVAL;
    char *output_file = DEFAULT_OUTPUT_FILE;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval = atoi(optarg);
                break;
            case 'f':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sample_interval] [-f output_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-1");
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", i2c_address, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen(output_file, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
    fflush(csv_file);

    sensor_data_t sensor_data;

    while (running) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            log_error("Failed to read sensor data after retries");
        }
        sleep(sample_interval);
    }

    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

