#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x29
#define BH1750_CONT_HIGH_RES  0x10
#define BH1750_CONV_TIME_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_light_level(int fd, float *lux_out) {
    unsigned char buf[2];

    if (i2c_write_cmd(fd, BH1750_CONT_HIGH_RES) < 0)
        return -1;

    usleep(BH1750_CONV_TIME_MS * 1000);

    if (i2c_read_data(fd, buf, 2) < 0)
        return -1;

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_udp_multicast(int sockfd, float lux) {
    struct sockaddr_in addr;
    char buffer[32];

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    if (sendto(sockfd, buffer, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    int sockfd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char ttl = MULTICAST_TTL;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Failed to set multicast TTL: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        float lux = 0.0f;
        if (read_light_level(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in 1 s...\n");
            sleep(1);
            continue;
        }

        if (send_udp_multicast(sockfd, lux) < 0) {
            fprintf(stderr, "UDP send failed; retrying in 1 s...\n");
            sleep(1);
            continue;
        }

        printf("Lux: %.2f\n", lux);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    return ret;
}

