            if (errno == EINTR) continue;
            fprintf(stderr, "select error: %s\n", strerror(errno));
            return -1;
        }
        if (sel == 0) {
            fprintf(stderr, "UART read timeout (sensor absent or bus error)\n");
            return -1;
        }

        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read returned 0 (device closed?)\n");
            return -1;
        }

        if (ch == '\n') {
            line[line_len] = '\0';
            return (int)line_len;
        }
        line[line_len++] = ch;
    }

    if (line_len >= line_size - 1) {
        fprintf(stderr, "Line buffer overflow\n");
        return -1;
    }
    line[line_len] = '\0';
    return (int)line_len;
