#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("fcntl F_SETFL");
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }
    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return val;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

static void send_emergency_stop(void) {
    const char *msg = "EMERGENCY STOP!\n";
    size_t len = strlen(msg);
    ssize_t written = write(uart_fd, msg, len);
    if (written < 0) {
        perror("write UART");
    } else if ((size_t)written != len) {
        fprintf(stderr, "Partial UART write: %zd of %zu bytes\n", written, len);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            usleep(100000);
            continue;
        }

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        usleep(100000);
    }

    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioTerminate();
    return 0;
}

